const std = @import("std");
const lexer = @import("lexer.zig");
const functions = @import("functions.zig");
const runtime_functions = @import("runtime_functions.zig");
const catalogue = @import("aggregate_types.zig");
const native = @import("native.zig");
const native_std = @import("native_std.zig");
const stdlib = @import("stdlib.zig");
const stdlib_natives = @import("stdlib_natives.zig");
const scratch = @import("scratch.zig");
const modules = @import("modules.zig");
const macros = @import("macros.zig");
const name_index = @import("name_index.zig");
const qualify = @import("qualify.zig");
const persistable = @import("persistable.zig");
const no_member = std.math.maxInt(u32);
/// Debug builds answer every indexed lookup a second time by the scan it replaced, so the
/// whole test suite checks that the two agree; the scans cost nothing in a release build.
const paired_scans = @import("builtin").mode == .debug;
// Staged member links are u32 so aggregate quotas can grow without a width wall;
// pressure is a checked diagnostic, not an invariant failure.
const Member = struct { node: u32, field: u32, next: u32 = no_member };
pub const types = @import("types.zig");
const Token = lexer.Token;
const Span = types.Span;
const Diagnostic = types.Diagnostic;
const ParseError = error{InvalidSource};
const Name = struct {
    token: Token,
    span: Span,
    scope: Span,
    qualified: bool = false,
    /// A qualified name written inside the module it names, or inside a module nested in it:
    /// what that module declares is in reach whether or not it is `<public>` (RFC-0074).
    inside: bool = false,

    /// Whether only the `<public>` declarations of `scope` may be meant.
    fn sealed(self: Name) bool {
        return self.qualified and !self.inside;
    }
};
const Local = struct {
    name: Span,
    node: u32,
    mutable: bool = false,
    /// RFC-0085, I2: a shared local `var` (S1). Its node is the `ref_new` of its cell, which
    /// never changes: reads are `ref_get` and writes `ref_set` on it, so it has no versions
    /// (`mutable` is false) and no loop carries it.
    shared: bool = false,
    /// The `var` a loop's function declares for a local it carries from visit to visit (a `var`
    /// of the library's): the local itself is declared further out.
    carried: bool = false,
};
/// RFC-0091 (B3): one pattern or name of a destructured parameter. A whole parameter's pattern
/// has no parent and reads parameter `parameter`; every other entry is element `index` of its
/// parent's tuple. A name is a local of the body; a pattern's `name` is empty.
const Pattern = struct {
    parent: u32,
    parameter: u32,
    index: u32,
    name: Span,
    value_type: types.Type,
    /// The node that holds the value, once the body binds it.
    node: u32 = no_member,
};
const LocalCheckpoint = struct { nodes: [types.limits.local_bindings]u32, count: u32, mutable_count: u32 };
/// `ref` (RFC-0085, I2): a shared local, by the node that holds its cell. `noted`: an
/// assignment that shares its local (`wantShare`), in a compile that is discarded; it writes
/// nothing, and its value is the value assigned, of type `noted`.
const Assignment = union(enum) { cell: u32, local: u32, ref: u32, noted: types.Type };
// Explicit continuations share checked operator/operand/local pools. Published
// runtime bodies own copies before temporary template tails are reused.
/// A name the body of a template declares, as its tokens show it (`Parser.bodyDeclaration`),
/// while the bracket that holds it is open (`Parser.ShadowScan`).
const ShadowName = struct {
    span: Span,
    /// The depth of the bracket it is declared in. A parameter of an `Fn` waits for the brace
    /// of its body (`awaiting`) and then belongs to it; one of a method of a parametric type
    /// belongs to the method (`member`) until the member ends.
    depth: usize,
    parameter: bool,
    awaiting: bool = false,
    member: bool = false,
    /// Its own initialiser is still being read: a declaration of the name inside it is
    /// refused without naming it, as `Parser.pendingName` does, but not inside an `Fn` in it,
    /// whose body is a function of its own (`level`).
    pending: bool = false,
    /// How many bodies of `Fn`s are open around it.
    level: u32 = 0,
};

const GenericTemplate = struct {
    name: Span,
    parameters: [types.limits.parameters]Span = undefined,
    parameter_count: u32 = 0,
    /// Bit i is set when parameter i is an effect rather than a type.
    effect_mask: u32 = 0,
    /// Bit i is set when parameter i accepts only comparable types (`T:comparable`).
    comparable_mask: u32 = 0,
    is_public: bool,
    header: u32,
    end: u32,
    source: Span,
    module: u32,
    /// The nested module that declares the template, as `Workspace.current_nested`.
    nested: u32 = types.no_parent,
    /// What the template makes (RFC-0073). For a type, `header` is the token after `class`,
    /// `interface` or `struct` and `end` the token after the closing brace of its body.
    /// A parametric alias (RFC-0083), `Name[T:type] := type`, is `alias`: `header` is the first
    /// token of the type and `end` the token after it. It makes no type of its own.
    kind: enum(u8) { function, class, interface, record, method, alias } = .function,
    /// Bit i is set when parameter i accepts only subtypes of `bounds[i]` (`T:subtype(Base)`).
    subtype_mask: u32 = 0,
    bounds: [types.limits.parameters]types.Type = undefined,
    /// A generic method (RFC-0081): the class or interface that declares it, or, when that is a
    /// parametric type, `outer` is its template and the method is one for every instantiation.
    receiver: types.Type = .i64,
    outer: u32 = no_member,
    access: Access = .internal,
    /// Bit i is set when parameter i accepts only `<castable>` classes, or only `<concrete>` ones,
    /// below `bounds[i]` (`T:castable_subtype(Base)`, `T:concrete_subtype(Base)`, RFC-0081).
    castable_mask: u32 = 0,
    concrete_mask: u32 = 0,
};
comptime {
    // The masks of a template hold one bit for each parameter.
    std.debug.assert(types.limits.parameters <= 32);
}
/// One instantiation of a parametric type: the type made from `template` for the arguments that
/// the tuple type `arguments` lists. It is found by them in `Workspace.instance_table`.
const Instance = struct {
    template: u32,
    arguments: types.Type,
    value: types.Type,
    /// A class or interface is reserved when it is first named and completed (fields, method
    /// signatures, bodies) when nothing stands in the way; a struct is made in one step.
    state: enum(u8) { reserved, completing, complete } = .reserved,
    /// How many instantiations lead to this one, each first named while the one before it was
    /// being completed. It bounds a template that names itself with ever larger arguments.
    generation: u16 = 0,
    /// The supertypes its header names, which must be complete before it is.
    parents: [1 + types.Class.max_interfaces]types.Type = undefined,
    parent_count: u8 = 0,
};
/// A declaration the pre-pass does not declare: a parametric type, a class whose supertypes
/// name an instantiation or another such class, and an alias of any of them. A supertype is
/// an earlier definition and an instantiation is made only when it is named, so such a class
/// is declared when its supertypes are known: where it stands, or earlier if it is named first.
const Late = struct {
    name: Span,
    module: u32,
    /// The module declared inside that file which holds the declaration (RFC-0074), as
    /// `Workspace.current_nested`, and the scope that declares the name, as `currentScope`.
    nested: u32 = types.no_parent,
    scope: u32,
    /// The token of the name, from which the declaration is read again.
    token: u32,
    is_public: bool,
    kind: enum(u8) { template, class, alias },
    /// A class: its type, once it has been reserved.
    declared: ?types.Type = null,
    reserving: bool = false,
};
const GenericContext = struct {
    template: u32,
    arguments: [types.limits.parameters]types.Type = undefined,
    specialization: ?types.Type = null,
    /// For a generic method of a parametric type (RFC-0081): the instantiation it is compiled
    /// for, whose arguments the type's own parameters stand for in the method.
    instance: u32 = no_member,
};
/// The metatypes of RFC-0081: `subtype(T)`, `castable_subtype(T)`, `concrete_subtype(T)`, and
/// B8's `castable_concrete_subtype(T)`, which is the last two in one.
const MetaKind = enum(u8) {
    subtype,
    castable,
    concrete,
    castable_concrete,

    fn named(text: []const u8) ?MetaKind {
        if (std.mem.eql(u8, text, "subtype")) return .subtype;
        if (std.mem.eql(u8, text, "castable_subtype")) return .castable;
        if (std.mem.eql(u8, text, "concrete_subtype")) return .concrete;
        if (std.mem.eql(u8, text, "castable_concrete_subtype")) return .castable_concrete;
        return null;
    }
    /// The bit `stdDeclared` remembers the name under: above every standard form and the bit
    /// operations (`stdlib.bit_base`), below the constant (`stdlib.pi_bit`).
    fn bit(self: MetaKind) u32 {
        return first_bit + @as(u32, @backingInt(self));
    }
    const first_bit: u32 = stdlib.bit_base + 4;
    /// Whether a type value of this kind casts (`K[V]`), and whether it builds (`K{}`).
    fn casts(self: MetaKind) bool {
        return self == .castable or self == .castable_concrete;
    }
    fn builds(self: MetaKind) bool {
        return self == .concrete or self == .castable_concrete;
    }
    /// The field that holds the construction: after the test when the metatype has both.
    fn makerField(self: MetaKind) u32 {
        return if (self == .castable_concrete) 1 else 0;
    }
};
/// A metatype is a struct the compiler makes, one for each kind and bound in a compile. Its one
/// field, named like the metatype, holds the function that is what the value can do: the test of
/// its class (`subtype` of a class, `castable_subtype`) or the construction of an instance
/// (`concrete_subtype`). `subtype` of a type that is not a class has no field: that type is its
/// only subtype, so its one value needs nothing to tell it from another.
const Metatype = struct { kind: MetaKind, bound: types.Type, value: types.Type };
/// The function a type value of `class` holds for a metatype of `bound`: `test` answers whether
/// a value of the bound is of the class (`(V:Bound)<computes><decides>:Bound`), `make` builds an
/// instance (`(V:option(Bound))<effects>:Bound`, the option only telling it from `test`).
const WitnessRole = enum(u8) { test_class, make };
const Witness = struct { role: WitnessRole, bound: types.Type, class: types.Type, function: u32 };
comptime {
    std.debug.assert(@as(u32, @backingInt(MetaKind.castable_concrete)) + MetaKind.first_bit < stdlib.pi_bit);
}
/// What a class is to the metatypes (RFC-0081), one bit each in `Workspace.class_kinds`.
const class_castable: u8 = 1;
const class_concrete: u8 = 2;
/// B4 (RFC-0092): a `GetCastableFinalSuperClass` asked for the family of this class, so no
/// `<final_super>` class may join it any more.
const class_queried: u8 = 4;

/// What `parseGenericDeclaration` needs to know of a generic method (RFC-0081).
const GenericMethod = struct { class: types.Type, access: Access };
/// The generic method a member access names: its template, the class or instantiation that
/// declares it (its receiver), and that instantiation's index, or `no_member` for a plain class.
const MethodFound = struct { id: u32, receiver: types.Type, instance: u32 };
const Effect = struct {
    transacts: bool = false,
    decides: bool = false,
    /// The heap effects a `transacts` signature gives up, `suspends` and `converges` (RFC-0078).
    detail: types.EffectDetail = .{},

    fn of(function: functions.Definition) Effect {
        return .{ .transacts = function.transacts, .decides = function.decides, .detail = function.detail };
    }
    fn set(self: Effect) types.EffectSet {
        return types.effectSet(self.transacts, self.decides, self.detail);
    }
    /// The heap effects alone: what code inside a function may do to state because the
    /// function may. Whether it fails, suspends or converges is its own to say.
    fn heapOnly(self: Effect) Effect {
        var detail = self.detail;
        detail.suspends = false;
        detail.converges = false;
        return .{ .transacts = self.transacts, .detail = detail };
    }
};
/// The effect specifiers, each the bit of its ordinal in the set a signature has written so far.
const EffectWord = enum(u4) {
    computes,
    transacts,
    reads,
    writes,
    allocates,
    decides,
    suspends,
    converges,
    /// RFC-0085, I12: gives up `dictates`; it is no heap effect, so it stands beside one.
    predicts,

    fn bit(self: EffectWord) u16 {
        return @as(u16, 1) << @backingInt(self);
    }
};
/// The effect a set of specifiers states, or null when none of them is a heap effect: a
/// signature says what it does to state (RFC-0067 D10), `<computes>` when nothing.
fn effectOfWords(seen: u16) ?Effect {
    var effect: Effect = .{ .decides = seen & EffectWord.decides.bit() != 0 };
    const reads = seen & EffectWord.reads.bit() != 0;
    const writes = seen & EffectWord.writes.bit() != 0;
    const allocates = seen & EffectWord.allocates.bit() != 0;
    if (seen & EffectWord.transacts.bit() != 0) {
        effect.transacts = true;
    } else if (reads or writes or allocates) {
        // All three together are `<transacts>` under its one encoding.
        effect.transacts = true;
        effect.detail = types.heapDetail(reads, writes, allocates);
    } else if (seen & EffectWord.computes.bit() == 0) return null;
    effect.detail.suspends = seen & EffectWord.suspends.bit() != 0;
    effect.detail.converges = seen & EffectWord.converges.bit() != 0;
    effect.detail.predicts = seen & EffectWord.predicts.bit() != 0;
    std.debug.assert(types.effectsCanonical(effect.transacts, effect.decides, effect.detail));
    return effect;
}
/// What a construct asks of the function it is written in (RFC-0078).
const StateUse = enum { variable_read, field_read, set, construction, local_var, local_read };
/// The effect a class or interface declares for building its instances (RFC-0078), beyond the
/// allocation itself. Unstated, it is what its block clauses and supertypes need.
const ClassEffect = struct { stated: bool = false, effect: Effect = .{} };
/// `Name := type` introduces a transparent alias; types stay structural.
const TypeAlias = struct { name: Span, value: types.Type, is_public: bool = false };
/// A host function bound by `Name := native{"id"}`; the signature comes from the host table.
const NativeBinding = struct { name: Span, entry: u16, params: [native.max_parameters]types.Type, param_count: u8, result: types.Type };
/// Numeric conversion builtins: failable `Floor`/`Ceil`/`Round`/`Int` and total `ToFloat`.
const Conversion = enum(u32) {
    floor,
    ceil,
    round,
    truncate,
    float,
    string,
    interpolation,
    // Integer division forms (RFC-0070): `Quotient[A,B]`, `Mod[A,B]`, `Rational[A,B]` and the
    // total `MakeRationalFromInt(N)`.
    quotient,
    modulo,
    rational,
    to_rational,
    cast,
    // The Book's bitwise intrinsics (RFC-0072): total functions of `i64`, not conversions, but
    // they open and close like one.
    bit_and,
    bit_or,
    bit_xor,
    bit_not,
    /// `string[Units]`: the string of a `[]char`, failing unless the units are valid UTF-8.
    units,
    // The compiler-only forms of a `Case` pattern (RFC-0066), spelled only by the library block.
    case_is,
    case_as,
    case_all,
    case_some,
    case_none,
    case_value,
    case_tuple,
    /// B4 (RFC-0092): `GetCastableFinalSuperClass[Base, Instance]`; not a pattern form, which
    /// `emitConvert` asks about after this one.
    final_super_class,

    fn pattern(self: Conversion) bool {
        return @backingInt(self) >= @backingInt(Conversion.case_is);
    }

    /// The operator of a bitwise intrinsic. `BitNot(X)` is `X` exclusive-or all ones.
    fn bitwise(self: Conversion) ?types.BinaryOp {
        return switch (self) {
            .bit_and => .bit_and,
            .bit_or => .bit_or,
            .bit_xor, .bit_not => .bit_xor,
            else => null,
        };
    }
};

/// The bitwise intrinsic a name spells. They are not reserved: a program's own function of the
/// same name is found first, so programs written before RFC-0072 keep their meaning.
fn bitwiseNamed(name: []const u8) ?Conversion {
    if (!std.mem.startsWith(u8, name, "Bit")) return null;
    if (std.mem.eql(u8, name, "BitAnd")) return .bit_and;
    if (std.mem.eql(u8, name, "BitOr")) return .bit_or;
    if (std.mem.eql(u8, name, "BitXor")) return .bit_xor;
    if (std.mem.eql(u8, name, "BitNot")) return .bit_not;
    return null;
}

/// RFC-0086, P2.3: whether `name` is a standard function that can fail, and so is opened with a
/// bracket where its name stands bare: `OpenReader[N]`, `OpenWriter[N]`.
fn stdFails(name: []const u8) bool {
    const form = stdlib.function(name) orelse return false;
    return form.decides();
}

/// The pattern form a library word names.
fn patternFormNamed(name: []const u8) ?Conversion {
    if (!std.mem.startsWith(u8, name, "__case_")) return null;
    const form = std.meta.stringToEnum(Conversion, name[2..]) orelse return null;
    return if (form.pattern()) form else null;
}
/// Words that already mean something inside an effect specifier or a parameter kind.
fn effectKeyword(name: []const u8) bool {
    for ([_][]const u8{ "computes", "transacts", "decides", "effect", "type", "comparable" }) |word| if (std.mem.eql(u8, name, word)) return true;
    return false;
}
fn projectionName(name: []const u8) bool {
    return std.mem.eql(u8, name, "__elem") or std.mem.eql(u8, name, "__key") or std.mem.eql(u8, name, "__result") or std.mem.eql(u8, name, "__type") or std.mem.eql(u8, name, "__var") or std.mem.eql(u8, name, "__ret");
}
fn conversionNamed(name: []const u8) ?Conversion {
    if (std.mem.eql(u8, name, "Floor")) return .floor;
    if (std.mem.eql(u8, name, "Ceil")) return .ceil;
    if (std.mem.eql(u8, name, "Round")) return .round;
    if (std.mem.eql(u8, name, "Int")) return .truncate;
    if (std.mem.eql(u8, name, "ToFloat")) return .float;
    if (std.mem.eql(u8, name, "ToString")) return .string;
    return null;
}
/// The division builtins of RFC-0070. Unlike the conversions above they are not reserved: a
/// program that already declares one of these names keeps its own meaning for it.
fn divisionNamed(name: []const u8) ?Conversion {
    if (std.mem.eql(u8, name, "Quotient")) return .quotient;
    if (std.mem.eql(u8, name, "Mod")) return .modulo;
    if (std.mem.eql(u8, name, "Rational")) return .rational;
    if (std.mem.eql(u8, name, "MakeRationalFromInt")) return .to_rational;
    return null;
}
/// The methods of the text types (RFC-0069), written after a value: `S.Slice[A, B]`,
/// `C.ToCodeUnit()`. They are found by the type of the value, like `Length`, so none of the
/// names is reserved and a program's own `Slice` or `ToChar` function is unaffected.
const TextMethod = enum(u32) {
    slice,
    scalar_at,
    to_code_unit,
    to_ascii_char32,
    to_code_point,
    to_ascii_string,
    to_char,
    to_char32,

    fn named(receiver: types.Type, name: []const u8) ?TextMethod {
        const Entry = struct { name: []const u8, method: TextMethod };
        const table: []const Entry = if (receiver == .string)
            &.{ .{ .name = "Slice", .method = .slice }, .{ .name = "ScalarAt", .method = .scalar_at } }
        else if (receiver == types.Type.char)
            &.{ .{ .name = "ToCodeUnit", .method = .to_code_unit }, .{ .name = "ToAsciiChar32", .method = .to_ascii_char32 } }
        else if (receiver == types.Type.char32)
            &.{ .{ .name = "ToCodePoint", .method = .to_code_point }, .{ .name = "ToAsciiString", .method = .to_ascii_string } }
        else if (receiver == .i64)
            &.{ .{ .name = "ToChar", .method = .to_char }, .{ .name = "ToChar32", .method = .to_char32 } }
        else
            &.{};
        for (table) |entry| if (std.mem.eql(u8, entry.name, name)) return entry.method;
        return null;
    }
    /// Failable methods are called with brackets and need a failure context.
    fn decides(self: TextMethod) bool {
        return switch (self) {
            .slice, .scalar_at, .to_ascii_char32, .to_char, .to_char32 => true,
            .to_code_unit, .to_code_point, .to_ascii_string => false,
        };
    }
    /// The most arguments the method takes after its receiver.
    fn arguments(self: TextMethod) u32 {
        return switch (self) {
            .slice => 2,
            .scalar_at => 1,
            .to_code_unit, .to_ascii_char32, .to_code_point, .to_ascii_string, .to_char, .to_char32 => 0,
        };
    }
};
/// An arm of a `Case[...]` that takes every value if its type tests hold, and what the parser
/// found of those tests: how many, and whether one of them was not decided by the types.
/// `next` links the arms of one `Case[...]` (`no_failing_arm` ends the list).
/// `typed` is set on an arm whose pattern is `Name:Type` (RFC-0083); `tested` is the type its
/// one test asks for, once the compiler has read it in this compilation.
/// `stamp` orders the type tests of a pass (RFC-0090): the value of `failing_test_stamp` when
/// the arm's test was seen last.
const FailingArm = struct { start: u32, end: u32, next: u32, tests: u32 = 0, undecided: bool = false, keyword: u32 = 0, typed: bool = false, tested: types.Type = .i64, stamp: u32 = 0 };
/// A qualifier of the text (RFC-0083): `(local:)` before the name at `position`, or `(Module:)`
/// whose module name is at `position`.
const Qualifier = struct { position: u32, local: bool };
/// How deep parametric aliases are read inside one another (RFC-0083): each level is a read
/// of a type on the native stack, as a type argument is.
const max_alias_depth: u32 = 8;
/// A parametric alias read for a list of arguments (the tuple type `arguments`): the type it
/// names for them.
const AliasExpansion = struct { template: u32, arguments: types.Type, value: types.Type };
/// A bound of a refinement type being read (RFC-0083): the bits of an `i64` or an `f64`.
const RefinementBound = struct { bits: u64, open: bool = false };
/// A `Case[...]` of a compilation pass with patterns, by the start of its keyword, and the first
/// and last of its arms above (`no_failing_arm` while it has none).
const FailingCase = struct { keyword: u32, first: u32, last: u32 };
const no_failing_arm = std.math.maxInt(u32);
/// Each such arm (`X:T => V,`) and each `Case[V, ...]` spends at least six tokens of the text,
/// so neither table can fill; the check stays as the error a broken bound would be.
const max_failing_arms = types.limits.tokens / 6 + 1;

const AnonymousFrame = struct {
    kind: enum { anonymous, generic } = .anonymous,
    /// The established `For` (an index into `Workspace.for_calls`) whose template generated
    /// this function: its body or its filter.
    for_call: u32 = no_member,
    return_cursor: u32 = 0,
    reference_span: Span = .{ .start = 0, .end = 0 },
    parent_module: u32,
    parent_nested: u32 = types.no_parent,
    parent_generic: ?GenericContext,
    definition: functions.Definition,
    parent_function: ?functions.Definition,
    expected_type: ?types.Type,
    default_expression: bool,
    control_depth: usize,
    operator_base: u32,
    operand_base: u32,
    local_base: u32,
    parentheses: u32,
    operators: u32,
    operands: u32,
    locals: u32,
    checkpoints: u32,
    template_nodes: u32,
    template_members: u32,
    template_arguments: u32,
    staging: u32,
    phase: enum { captures, body } = .captures,
    capture_values: [types.limits.parameters]u32 = undefined,
    capture_count: u32 = 0,
    /// `Fn[...]` listed its captures; otherwise the body captures the names it uses.
    explicit_captures: bool = false,
    /// No `:Type` was written; the result type is the type of the body.
    infer: bool = false,
    /// The result was written `void` (RFC-0080): the body's value is dropped.
    discards: bool = false,
    /// `Workspace.failable_uses` when the body began: what can fail inside a function body
    /// fails that function, not the expression the function value stands in.
    failable_uses: u32 = 0,
    /// A specialization of a generic method (RFC-0081): what the method context was before it,
    /// and that the access which named it is read again once it is published (`return_cursor`
    /// is at the dot), so that it finds the specialization and opens the call.
    method: bool = false,
    parent_method_class: ?types.Type = null,
    parent_member_expression: bool = false,
    /// RFC-0091 (B3): the specialization of an inferred call, whose arguments, this many, wait on
    /// the operand stack under the frame and are passed to it when it is published.
    inferred: u32 = 0,
    /// A function a macro wrote for a loop at the root: it declares the heap effects its body
    /// uses, gathered in `used` (`Parser.useEffect`, RFC-0079).
    infers: bool = false,
    used: types.EffectSet = .{ .diverges = false },
    /// The parser's `inferring` around this function, given back when it is finished.
    parent_inferring: ?u32 = null,
    /// The body of a `Spawn{...}` (RFC-0082): it takes no parameters but its captures, cannot be
    /// left by `Return` or `Break`, and cannot assign what it captured.
    task_body: bool = false,
    /// RFC-0082, P3.3. An arm of `Sync` or `Race`: an expression, ended by the comma or the
    /// parenthesis after it, with the rules of a task's body, and `sites` counts the sites
    /// compiled directly in it. Or the function a cancellation runs for a `Defer` (`landing`):
    /// a copy of its body, a block for effect, which cannot assign what it captured.
    arm: bool = false,
    landing: bool = false,
    sites: u32 = 0,
    /// RFC-0082, P3.4. The body of a `Branch{...}`, a task's body whose value is dropped; and
    /// a function the macro pass wrote as the visit of a `Loop{}` or a `While` (a library `Fn`
    /// that is the first argument of a `Loop(`), where no `Rush` or `Branch` may stand.
    branch_body: bool = false,
    visit: bool = false,
    /// The guard of a live variable (RFC-0084): no parameters but its captures, the effect
    /// `<reads>`, and no local `var` among what it captures.
    guard_body: bool = false,
    /// RFC-0082, P3.6: for an arm that an exit leaves, the type of its pending exits.
    exits: ?types.Type = null,
    /// RFC-0082, P3.8: the function an RFC-0056 `For` template binds to `__for_keep`, its
    /// filter, which it calls in the condition of an `If`: it never suspends. `for_body`: the
    /// one a `For` template binds to `__for_f`, its body or a level of it.
    filter: bool = false,
    for_body: bool = false,
    /// The `Token.site` of the `Fn` a macro wrote, which says the call it was written for;
    /// zero for one the program writes (`Workspace.suspendClause`).
    macro_site: u32 = 0,
    /// RFC-0084, P4.4: the guard of an `Upon` or a `When` (an arm that is also a guard, compiled
    /// inside a region of its own), or its body (an arm that cannot suspend or be left).
    reaction: enum { none, guard, body } = .none,
    /// RFC-0084, P4.5: the body of a `Batch{...}`, with the span of its keyword, where its node
    /// stands: a task's body, as far as exits and assignments go, that cannot suspend.
    batch: ?Span = null,
    /// RFC-0085, I3: a nested function `Name(P)<effects>:R = Body`, a statement of a block. Its
    /// body ends with the statement; `nested_entry` is its entry in `Workspace.nested_functions`.
    nested: bool = false,
    nested_entry: u32 = no_member,
};

/// RFC-0085, I3: a nested function in scope, from its declaration to the end of its block.
/// `runtime` is its code entry, `no_member` while its body is compiled. Its captures are the
/// names `captures` of `Workspace.nested_capture_names` holds, resolved where it is used: each is
/// an immutable value or a variable cell, the same at every use as where it was declared.
/// `block` is the operator of the block that declares it and `depth` the frames open then.
const NestedFunction = struct {
    name: Span,
    runtime: u32 = no_member,
    captures: Span = .{ .start = 0, .end = 0 },
    block: u32,
    depth: u32,
    /// Its bucket of `Workspace.nested_buckets`, and the entry below it there, plus one (zero
    /// for none).
    bucket: u32 = 0,
    next: u32 = 0,
    /// RFC-0085, I4: the end of the names of its declared parameters, which follow its captures
    /// in `Workspace.nested_capture_names`; their defaults are at the same places of
    /// `Workspace.nested_defaults`.
    parameters_end: u32 = 0,
    /// RFC-0076 D16: for the first overload of its name in the block, the number its overloads
    /// are kept under in `Workspace.late_overloads` (zero until one is kept).
    late_block: u32 = 0,
};
/// RFC-0076 D16: an overload that some namesake was not yet known to be distinct from, because
/// a parameter names a class declared further down. `group` is where the first overload of its
/// name is declared, in the same module or block; `parameters` are its declared parameter types.
/// `block` is zero for the functions of a module, and for the nested functions of a block a
/// number given to that compilation of the block: two specializations of one generic body are
/// compiled from the same source and are not overloads of each other.
const LateOverload = struct {
    group: u32,
    block: u32,
    name: Span,
    count: u32,
    parameters: [types.limits.parameters]types.Type,
};
/// Whether some value fits two parameter types (RFC-0076 D16): none does, one does, or it is not
/// known yet because one of them names a class still to be declared.
const Overlap = enum { apart, overlap, pending };
fn parameterTypes(function: *const functions.Definition) [types.limits.parameters]types.Type {
    var result: [types.limits.parameters]types.Type = undefined;
    for (function.parameters[0..function.parameter_count], result[0..function.parameter_count]) |parameter, *slot| slot.* = parameter.value_type;
    return result;
}
/// The nested functions in scope are found by name through this many buckets, each the chain
/// of its entries from the latest down: a lookup reads the chain of one name's bucket.
const nested_bucket_count = @min(std.math.ceilPowerOfTwo(usize, 2 * types.limits.functions) catch unreachable, 4096);
pub const Result = union(enum) { ok: types.Program, failed: Diagnostic };
pub const BundleResult = union(enum) { ok: types.Program, failed: modules.LocatedDiagnostic };

/// Allocate once; compilation never allocates. Programs borrow this workspace
/// and source until the next compile. Evaluation storage is owned separately by
/// its caller. One workspace must not be shared by writers.
pub const Workspace = struct {
    tokens: [types.limits.tokens]Token = undefined,
    /// Output side of the streaming token rewrites; see `Rewrite`.
    spare_tokens: [types.limits.tokens]Token = undefined,
    nodes: [types.limits.nodes]types.Node = undefined,
    /// Which nodes are a numeric literal written where it is used, and not yet read through a
    /// name (RFC-0083): only such a constant becomes a refinement without a cast. Each bit is
    /// written when its node is emitted, so nothing is cleared ahead.
    literal_nodes: std.StaticBitSet(types.limits.nodes) = undefined,
    literal_templates: std.StaticBitSet(types.limits.template_nodes) = undefined,
    bindings: [types.limits.bindings]types.Binding = undefined,
    strings: [types.limits.string_bytes]u8 = undefined,
    source_cells: [types.limits.source_cells]types.SourceCell = undefined,
    /// RFC-0084, P4.3: the variables whose type is a function, in the order declared. A
    /// module cell `Out` is written through its raw cell; a field likewise, by its index in
    /// the class that declares it. `fixed` is a raw value the program never assigns (the
    /// immutable forms), `hidden` one it cannot name.
    live_types: [types.limits.source_cells]LiveType = undefined,
    live_type_count: u32 = 0,
    binding_cells: [types.limits.bindings]u16 = undefined,
    /// The scope that declared each binding, as `currentScope` gave it. A temporary of a macro
    /// is named by library text, which lies outside every nested module, so where a binding's
    /// name is written does not say which module of a file declared it (RFC-0074).
    binding_scope: [types.limits.bindings]u32 = undefined,
    source_cell_count: u32 = 0,
    source_ops: u32 = 0,
    slots: [types.limits.methods]types.Slot = undefined,
    slot_count: u32 = 0,
    /// Who may use each slot and each catalogue field; checked by the compiler only.
    slot_access: [types.limits.methods]Access = undefined,
    field_access: [types.limits.fields]Access = undefined,
    /// Fields declared `<final>`, beside `field_access`: no archetype names one and no class
    /// restates one, so every instance holds the default its declaration gave.
    field_final: [types.limits.fields]bool = undefined,
    /// Live fields (RFC-0084, P4.2), beside `field_access`: their guards give them their
    /// values, so no archetype, constructor or restatement gives one a value.
    field_live: [types.limits.fields]bool = undefined,
    /// Who may assign each `var` field: `var<private> Name<public>:t` is read anywhere and
    /// assigned by its class only. Without a specifier on `var` it is the field's access.
    field_write: [types.limits.fields]Access = undefined,
    methods: [types.limits.methods]MethodInfo = undefined,
    method_count: u32 = 0,
    /// What each slot stands for. An interface field is a getter slot, followed by a setter slot
    /// when it is `var`: an instance seen as the interface is asked for its field like a method.
    slot_kind: [types.limits.methods]SlotKind = undefined,
    /// The type, mutability and default of the interface field behind each getter slot.
    slot_field: [types.limits.methods]InterfaceField = undefined,
    /// The declarations of each slot in the order they were made: `MethodInfo.next` links them.
    slot_first: [types.limits.methods]u32 = undefined,
    slot_last: [types.limits.methods]u32 = undefined,
    /// Name and default of the parameters after `Self` of method declaration `m`, at
    /// `m * limits.parameters`: what a call with named or omitted arguments reads.
    method_parameters: [types.limits.methods * types.limits.parameters]MethodParameter = undefined,
    /// Slots of interfaces that a superclass method stands in for; none in most programs.
    bridge_count: u32 = 0,
    /// B4 (RFC-0092): method declarations whose access an override narrowed; none in most programs.
    narrowed_count: u32 = 0,
    /// B4 (RFC-0092): the narrowed declarations of each slot, beside `slot_declared`.
    slot_narrowings: [types.limits.methods]u32 = undefined,
    dispatch: [types.limits.dispatch]types.Dispatch = undefined,
    dispatch_count: u32 = 0,
    /// Class fields assigned so far; a path assignment that updates no instance is not an assignment.
    class_updates: u32 = 0,
    operators: [types.limits.expression_depth]Operator = undefined,
    anonymous_frames: [types.limits.functions]AnonymousFrame = undefined,
    anonymous_count: u32 = 0,
    generic_templates: [types.limits.functions]GenericTemplate = undefined,
    generic_count: u32 = 0,
    /// Host table consulted by `native{...}` declarations; defaults to the standard
    /// pure kernels and may be replaced before compiling.
    natives: []const native.Entry = &native_std.table,
    native_bindings: [types.limits.natives]NativeBinding = undefined,
    native_binding_count: u32 = 0,
    type_aliases: [types.limits.user_types]TypeAlias = undefined,
    type_alias_count: u32 = 0,
    operands: [types.limits.expression_depth]u32 = undefined,
    symbols: [types.limits.bindings * 2]u32 = undefined,
    functions: functions.Storage = .{},
    runtime_functions: runtime_functions.Storage = .{},
    call_arguments: [types.limits.call_arguments]u32 = undefined,
    call_argument_count: u32 = 0,
    call_ops: u32 = 0,
    catalogue: catalogue.Storage = .{},
    module_storage: modules.Storage = .{},
    current_module: u32 = 0,
    /// The module declared inside the current file that is being compiled (RFC-0074), as an
    /// index of the nested table, or `no_parent` at the top level of the file.
    current_nested: u32 = types.no_parent,
    root_binding_start: u32 = 0,
    members: [types.limits.aggregate_elements]u32 = undefined,
    member_count: u32 = 0,
    staging: [types.limits.aggregate_elements]Member = undefined,
    staging_count: u32 = 0,
    record_fields: [types.limits.record_fields]types.Field = undefined,
    // Initialized exactly alongside the published catalogue field prefix.
    // Resetting the catalogue invalidates old descriptors without clearing it.
    field_defaults: [types.limits.fields]functions.Body = undefined,
    /// RFC-0087, P5.2: the field defaults of `<persistable>` types as values.
    persisted: ConstantStorage = .{},
    source: []const u8 = "",
    token_count: u32 = 0,
    node_count: u32 = 0,
    binding_count: u32 = 0,
    locals: [types.limits.local_bindings]Local = undefined,
    local_count: u32 = 0,
    /// RFC-0091 (B3): the patterns of destructured parameters, each function's a range
    /// (`functions.Definition.patterns`) in pre-order: a pattern before its elements.
    patterns: [types.limits.tokens / 4]Pattern = undefined,
    pattern_count: u32 = 0,
    local_checkpoints: [types.limits.local_checkpoints]LocalCheckpoint = undefined,
    local_checkpoint_count: u32 = 0,
    string_count: u32 = 0,
    expansion_work: u32 = 0,
    string_comparisons: u32 = 0,
    control_ops: u32 = 0,
    diagnostic: Diagnostic = .{ .span = .{ .start = 0, .end = 0 }, .code = .expected_expression },
    /// A module that calls a macro carries the macro library as comment lines after its own
    /// text (see `macros.zig`). `library_base[m]` is where module `m`'s block starts, 0 when it
    /// has none; single-file compiles use module 0. Pooled `Fn` words are handed out per block.
    library_base: [types.limits.modules]u32 = @splat(0),
    library_used: [types.limits.modules]u32 = @splat(0),
    /// Where the template lines of each block start (after its pool of `Fn` words).
    library_templates: [types.limits.modules]u32 = @splat(0),
    library_names: [types.limits.modules]u32 = @splat(0),
    /// `Spawn` words of each module's block taken so far (RFC-0082): one per copy of a `Defer`
    /// body that holds a `Spawn`.
    library_spawns: [types.limits.modules]u32 = @splat(0),
    /// The same for `Branch` words (P3.4).
    library_branches: [types.limits.modules]u32 = @splat(0),
    /// The raw names of each module's block taken so far (RFC-0084, P4.3).
    library_raws: [types.limits.modules]u32 = @splat(0),
    /// Whether the program declares something named `Spawn` (RFC-0082, C17): then the macro
    /// layer, which runs before names are resolved, takes no `Spawn{` for the form.
    spawn_named: bool = false,
    /// The same for `Sync` and `Race` (RFC-0082, P3.3): where the program declares nothing by
    /// the name, the macro pass reads each argument of `Sync(` or `Race(` as a function of its
    /// own, an arm, which no exit may leave and whose `Defer`s are counted from its first.
    sync_named: bool = false,
    race_named: bool = false,
    /// The same for `Rush` (P3.4), read as `Sync` and `Race` are, and for `Branch`, whose body
    /// is framed as a `Spawn`'s is.
    rush_named: bool = false,
    branch_named: bool = false,
    /// The same for `Upon` and `When` (RFC-0084, P4.4), whose guard and body are read as arms
    /// are, each a function of its own that no exit may leave.
    upon_named: bool = false,
    when_named: bool = false,
    /// The same for `Batch` (RFC-0084, P4.5), whose body is framed as a `Spawn`'s is.
    batch_named: bool = false,
    /// RFC-0084, P4.6: the same for `Await`, whose guard is read as `Upon`'s is.
    await_named: bool = false,
    /// `library_names` as it was when the current round of `desugarMacros` began.
    library_names_before: [types.limits.modules]u32 = @splat(0),
    /// The generated lines each block carries, and what a call that found them short asked for:
    /// the compile is then redone with the block extended (`requestExtension`).
    library_extension: [types.limits.modules]macros.Extension = @splat(.{}),
    library_wanted: macros.Extension = .{},
    /// Whether `SortBy(...)` is the standard function in the compile in progress (RFC-0081).
    sort_by_standard: bool = false,
    /// How many generic methods the compile has declared (RFC-0081): none, and no member
    /// access asks for one.
    method_templates: u32 = 0,
    /// The generic methods by the type that declares them (a class, or `parametric_owner` plus
    /// the template of a parametric type) and their name, so that a member access asks only the
    /// supertypes of its receiver, whatever the number of methods of one name.
    method_table: name_index.Table = .{},
    method_slots: [name_index.slotCount(types.limits.functions).?]u32 = undefined,
    /// The metatypes made so far (RFC-0081), found by kind and bound in `metatype_table`, and
    /// by their struct through `metatype_by_type`, whose entries count only when they point
    /// back (as `instance_by_type` does): nothing is cleared by capacity.
    metatypes: [types.limits.user_types]Metatype = undefined,
    metatype_count: u32 = 0,
    metatype_table: name_index.Table = .{},
    metatype_slots: [name_index.slotCount(types.limits.user_types).?]u32 = undefined,
    metatype_by_type: [types.limits.user_types]u32 = undefined,
    /// The functions type values hold, one for each role, bound and class in a compile.
    witnesses: [types.limits.functions]Witness = undefined,
    witness_count: u32 = 0,
    witness_table: name_index.Table = .{},
    witness_slots: [name_index.slotCount(types.limits.functions).?]u32 = undefined,
    /// RFC-0085, I8: the fields with accessors declared so far, found by name in
    /// `accessor_table`, by the type that declares them in `accessor_owners`, and by the slots
    /// of their getters and setters in `accessor_methods` once these are known. Such a field
    /// has no cell: a read calls its getter, a `set` its setter, so each has methods of its own
    /// and there are no more of them than methods. `accessor_type` is the standard type
    /// `accessor`, an empty struct made where a program first writes the name, which no source
    /// expression can build.
    accessor_fields: [types.limits.methods]AccessorField = undefined,
    accessor_count: u32 = 0,
    /// RFC-0085, I9: how many of them have no default; while none has, no archetype looks.
    /// An archetype keeps the values it gives such fields in a chain of `staging` of its own
    /// (`Operator.accessor_head`). Where they are used they are entered in `accessor_given`, by
    /// the field's index, under a number taken from `accessor_archetypes` for that use, so each
    /// lookup is one probe and an entry under another number is stale; an archetype also marks
    /// there, under its own number (`Operator.accessors`), what it has given so far, which finds
    /// a field given twice at its name unless an archetype inside its values overwrote the mark
    /// (then the entering finds it). `accessor_order` lists the fields of one class.
    accessor_required: u32 = 0,
    accessor_given: [types.limits.methods]AccessorGiven = undefined,
    accessor_archetypes: u32 = 0,
    accessor_order: [types.limits.methods]u32 = undefined,
    accessor_table: name_index.Table = .{},
    accessor_slots: [name_index.slotCount(types.limits.methods).?]u32 = undefined,
    accessor_owners: name_index.Table = .{},
    accessor_owner_slots: [name_index.slotCount(types.limits.methods).?]u32 = undefined,
    accessor_methods: name_index.Table = .{},
    accessor_method_slots: [name_index.slotCount(2 * types.limits.methods).?]u32 = undefined,
    accessor_type: ?types.Type = null,
    /// Where `accessor_type` was made: a trial reading (a generic signature, an alias template)
    /// discards the types it made, and another type may then take the number.
    accessor_name: Span = .{ .start = 0, .end = 0 },
    /// `class_castable` and `class_concrete` of every class, written when it is declared.
    class_kinds: [types.limits.user_types]u8 = undefined,
    /// B4 (RFC-0092): the `<final_super>` classes directly below each class, newest first, as
    /// catalogue indices: `final_super_first` per class, `final_super_next` per member. Written
    /// when each class is declared, so only entries of declared classes are read.
    final_super_first: [types.limits.user_types]u32 = undefined,
    final_super_next: [types.limits.user_types]u32 = undefined,
    /// B4 (RFC-0092): the family function of each class a query has asked about, the class's
    /// `class_queried` bit says which entries are written.
    families: [types.limits.user_types]u32 = undefined,
    /// The unguarded arms of the `Case[...]` forms of this pass that take every value if their
    /// type tests hold (RFC-0080). The parser counts the tests of each and whether every one
    /// held by the static types alone; such an arm is `case_cannot_fail`. The arms of
    /// `Case(...)` are recorded too, for `subsumed_arm` (RFC-0090).
    /// Arms are recorded in the order of the text and do not overlap, as are the cases, so a
    /// test finds its arm and a `Case[...]` its arms by binary search.
    failing_arms: [max_failing_arms]FailingArm = undefined,
    failing_arm_count: u32 = 0,
    failing_cases: [max_failing_arms]FailingCase = undefined,
    failing_case_count: u32 = 0,
    /// How many type tests of `Case` patterns this pass has seen (`FailingArm.stamp`).
    failing_test_stamp: u32 = 0,
    /// Parametric aliases being read inside one another (RFC-0083, `expandAlias`).
    alias_depth: u32 = 0,
    /// The instantiations of parametric aliases read so far, found by alias and arguments.
    aliases: [types.limits.user_types]AliasExpansion = undefined,
    alias_count: u32 = 0,
    alias_table: name_index.Table = .{},
    alias_slots: [name_index.slotCount(types.limits.user_types).?]u32 = undefined,
    /// The qualifiers of the text (RFC-0083), in source order: for `(local:)Name` the position
    /// of `Name`, for `(Module:)Name` that of `Module`. Each spends five tokens.
    qualifiers: [types.limits.tokens / 5 + 1]Qualifier = undefined,
    qualifier_count: u32 = 0,
    /// RFC-0085, I10: the tokens that name an enum where it is declared (`enumDeclaredAt`), by
    /// name, filled by the first qualifier of a reserved word in a compile (`declaresEnum`).
    /// `enum_name_count` is `no_member` until then; a program with more such tokens than
    /// types is refused at its first type too many anyway, and is answered by reading the
    /// tokens.
    enum_name_table: name_index.Table = .{},
    enum_name_slots: [name_index.slotCount(types.limits.user_types).?]u32 = undefined,
    enum_name_count: u32 = no_member,
    /// The established `For` calls of the current compile, and the calls that earlier compiles
    /// of the same source found to need the general lowering (`forceFor`).
    for_calls: [max_for_calls]ForCall = undefined,
    for_call_count: u32 = 0,
    for_forced: [max_for_calls]ForKey = undefined,
    for_forced_count: u32 = 0,
    /// The calls the pass in progress has found to need the general lowering (`wantFor`): they
    /// follow the `for_forced_count` known ones. The first `for_forced_sorted` known ones are
    /// in key order, so that asking about a call does not scan them all.
    for_pending: u32 = 0,
    for_forced_sorted: u32 = 0,
    /// Whether `for_calls` is in source order so far, which lets `wantFor` search it.
    for_calls_ordered: bool = true,
    /// For tests: find one such call per compile, as before `wantFor`, to compare against.
    for_one_at_a_time: bool = false,
    /// RFC-0082, P3.8: the general `For` calls that earlier compiles of the same source found
    /// with a site in an iteration (`noteSuspendingFor`), in key order; then the ones the pass in
    /// progress noted. Such a call is lowered without a region per iteration.
    for_suspended: [max_for_calls]ForKey = undefined,
    for_suspended_count: u32 = 0,
    for_suspended_pending: u32 = 0,
    /// The clauses (and bodies) of the calls this pass lowers without regions, as user spans:
    /// what can fail in one is reported there (`suspending_for_fails`), and only a body may
    /// hold a site.
    suspend_clauses: [types.limits.tokens / 2]SuspendClause = undefined,
    suspend_clause_count: u32 = 0,
    /// For tests: keep the region of every iteration, and let a site stand in it, so that a
    /// test can hand both machines the IR the compiler refuses to write (forged IR).
    for_regions_kept: bool = false,
    /// The `option{...}` constructors the parse in progress is inside of that stand outside
    /// every failure context, innermost last; and those that earlier compiles of the same
    /// source found to hold something that can fail, which catch the failure (`wantOption`):
    /// `option_caught_count` of them in order, then the `option_pending` this pass has noted.
    option_open: [types.limits.expression_depth]OptionCall = undefined,
    option_open_count: u32 = 0,
    option_caught: [max_caught_options]ForKey = undefined,
    option_caught_count: u32 = 0,
    option_pending: u32 = 0,
    /// How often the last `compile` or `compileBundle` went through the source.
    passes: u32 = 0,
    /// Which standard names (RFC-0077) the scope `std_memo_scope` was found to declare, or not
    /// to, in pass `std_memo_pass`: row 0 for functions and constants, then one per kind of
    /// receiver. A name is looked for once per scope, however often it is used.
    std_memo_pass: u32 = 0,
    std_memo_scope: u32 = std.math.maxInt(u32),
    std_memo_known: [1 + std.enums.values(stdlib.Receiver).len]u128 = @splat(0),
    std_memo_declared: [1 + std.enums.values(stdlib.Receiver).len]u128 = @splat(0),
    /// RFC-0091 (B3): the headers of the module functions of scope `forward_scope`, as found in
    /// pass `forward_pass`: the token of each name, by the hash of its text. A call of a name
    /// nothing earlier declares asks it for a declaration further down.
    forward_pass: u32 = 0,
    forward_scope: u32 = std.math.maxInt(u32),
    forward_headers: [types.limits.functions]u32 = undefined,
    forward_header_count: u32 = 0,
    forward_table: name_index.Table = .{},
    forward_slots: [name_index.slotCount(types.limits.functions).?]u32 = undefined,
    /// Failable constructs parsed so far: `logic{...}` requires at least one inside it.
    failable_uses: u32 = 0,
    /// `using{M}` declarations: names public in module `target` are visible unqualified in `module`.
    using_edges: [types.limits.imports]struct { module: u32, target: u32 } = undefined,
    using_count: u32 = 0,
    /// Where diagnostics and nodes that would point into a library block point instead.
    library_blame: [types.limits.modules]Span = @splat(.{ .start = 0, .end = 0 }),
    library_tokens: [macros.max_tokens]Token = undefined,
    library_ranges: [macros.template_count][2]u32 = undefined,
    combined_source: [types.limits.source_bytes]u8 = undefined,
    has_library: bool = false,
    /// Whether `library_tokens` holds the templates for the compile in progress.
    library_lexed: bool = false,
    /// Per module, whether `char` (bit 0) or `char32` (bit 1) has been read as the builtin
    /// character type there. A module means one thing by each name: once the builtin has been
    /// used, a declaration of a type or alias of that name in the module is `duplicate_name`,
    /// and a declaration that comes first is what the name means from then on (RFC-0069).
    /// Only `character_use_high` entries are in use and cleared.
    character_uses: [types.limits.modules]u8 = undefined,
    character_use_high: u32 = 0,
    /// Early exit (RFC-0068), while the macro pass runs: the frames an exit has to leave and
    /// the bodies of the `Defer`s whose scope is open, innermost last.
    exit_frames: [max_exit_frames]ExitFrame = undefined,
    exit_frame_count: u32 = 0,
    exit_defers: [max_exit_defers]ExitDefer = undefined,
    /// The words of `macros.exit_words`, lexed with the templates; spans relative to that text.
    exit_tokens: [std.enums.values(macros.ExitWord).len + 1]Token = undefined,
    exit_defer_count: u32 = 0,
    /// The last question about a failure context was answered `no` by a `Defer` body.
    defer_barrier: bool = false,
    /// Class `Block{...}` clauses (RFC-0075). `block_calls[class_blocks[c]]` are the functions
    /// every new instance of class `c` is handed to, in order: its superclass's, then its own.
    /// A class writes its entry when it is declared, before anything can build it, so only
    /// the entries of declared classes are ever read; a class that adds no clause shares
    /// its superclass's run.
    class_blocks: [types.limits.user_types]Span = undefined,
    /// What each class states for building its instances (RFC-0078), written where its header
    /// is parsed, which is before anything can build one.
    class_effects: [types.limits.user_types]ClassEffect = undefined,
    block_calls: [types.limits.dispatch]u32 = undefined,
    block_call_count: u32 = 0,
    /// The class whose `Block{...}` clauses are being compiled: it cannot be built there.
    blocks_pending: ?types.Type = null,
    /// The `object_new` of the class archetype compiled last inside a function, and the
    /// template node after the calls of its block clauses: a constructor function's body
    /// is exactly one such archetype.
    archetype_new: u32 = no_member,
    archetype_end: u32 = no_member,
    /// The template node from which that archetype expanded the defaults of the fields it was
    /// not given: operands of its `object_new` before this node are values it was given.
    archetype_given: u32 = 0,
    /// The `If` conditions that earlier compiles of the same source found to hold something
    /// that can fail, with no bracket to say so, outside every failure context
    /// (`wantCondition`): each is keyed by where its text starts and is a failable condition
    /// from then on (RFC-0049). `condition_forced_count` of them in order, then the
    /// `condition_pending` this pass has noted.
    condition_forced: [max_forced_conditions]ForKey = undefined,
    condition_forced_count: u32 = 0,
    condition_pending: u32 = 0,
    /// The path assignments (`set Xs[I]=V`, `set P.X=V`) that earlier compiles of the same
    /// source found to update nothing: inside a `For` their target is a local the loop has to
    /// carry (`forVariables`). Keyed by where the target is written; `carry_site_count` of them
    /// in order, then the `carry_pending` this pass has noted.
    carry_sites: [max_carry_sites]ForKey = undefined,
    carry_site_count: u32 = 0,
    carry_pending: u32 = 0,
    /// RFC-0082, P3.3: the `Defer`s that earlier compiles of the same source found open at a
    /// suspension site (`wantLanding`), keyed by where the word `Defer` stands. The macro pass
    /// writes a copy of the body of each after its mark, which the parser compiles as the
    /// function a cancellation there runs. `landing_key_count` of them in order, then the
    /// `landing_pending` this pass has noted.
    landing_keys: [max_landing_keys]ForKey = undefined,
    landing_key_count: u32 = 0,
    landing_pending: u32 = 0,
    /// RFC-0085, I2: the local `var` declarations that earlier compiles of the same source found
    /// shared (S1, `wantShare`), keyed by where the declared name stands. Each is a variable cell
    /// from then on. `share_key_count` of them in order, then the `share_pending` this pass has
    /// noted.
    share_keys: [max_share_keys]ForKey = undefined,
    share_key_count: u32 = 0,
    share_pending: u32 = 0,
    /// RFC-0085, I13 (S1e, Q1): a local `var` that any closure form names is shared. False
    /// compiles with the rules of I2 to I14 alone (a closure shares only what it assigns or
    /// what a nested function or a guard names): the tests set it to show, for each closure
    /// form, what a program meant before Q1, and the migration list is the declarations that
    /// only this rule shares (`share_keys` of a compile with it, less those of a compile without).
    share_names: bool = true,
    /// The `For` being rewritten assigns a shared local (`forVariables`).
    for_shared: bool = false,
    /// Where the library `Fn` words stand that the macro pass gave a program's own `Fn`s in the
    /// later copies of a `Defer` body (`streamFunction`): such a function is the program's, not
    /// a loop's (RFC-0085, I2, `userFunction`). Every copy is a code entry, so there are no more
    /// than entries; one past them is simply not recorded.
    renamed_fns: [types.limits.functions]u32 = undefined,
    renamed_fn_count: u32 = 0,
    /// RFC-0085, I3: the nested functions in scope, innermost last, and the names of their
    /// captures. Each is a code entry, so there are no more than entries, and each entry has no
    /// more captures than parameters.
    nested_functions: [types.limits.functions]NestedFunction = undefined,
    nested_count: u32 = 0,
    nested_capture_names: [types.limits.functions * types.limits.parameters]Span = undefined,
    nested_capture_count: u32 = 0,
    /// RFC-0076 D16: the overloads whose distinctness waits for a class, checked again each time
    /// a class is declared (`recheckLateOverloads`). Each is a declared function, so there are no
    /// more than entries.
    late_overloads: [types.limits.functions]LateOverload = undefined,
    late_overload_count: u32 = 0,
    late_block_count: u32 = 0,
    /// The latest entry of each bucket, plus one (`NestedFunction.next`). Cleared once, when a
    /// workspace first declares a nested function; each entry is taken out as it goes.
    nested_buckets: [nested_bucket_count]u32 = undefined,
    nested_buckets_ready: bool = false,
    /// RFC-0085, I4: the default of each parameter whose name `nested_capture_names` holds at the
    /// same place, an empty body for none (and for every capture). Written only for a nested
    /// function's parameters, so it costs nothing until one is declared.
    nested_defaults: [types.limits.functions * types.limits.parameters]functions.Body = undefined,
    /// The landing of each `Defer` mark open in the parser, by the mark's index.
    landings: [max_defer_marks]Landing = undefined,
    /// Whether the pass in progress compiled a `Sync` or a `Race`: in P3.3 only an arm can be
    /// cancelled, so only such a program takes a landing, and only its `Defer`s get one.
    structured_compiled: bool = false,
    /// The names declared `var` at the top level of a module, indexed for the macro pass in
    /// progress (`isSourceCell`): built when first asked for, dropped when the pass ends.
    cell_names: ?name_index.Index = null,
    cell_spans: []Span = &.{},
    cell_names_tried: bool = false,
    /// Brackets open at token `depth_index` of the round of `desugarMacros` in progress (`depthAt`).
    depth_index: usize = 0,
    depth_value: usize = 0,
    /// The cursor of the parse in progress: the tokens around it say which macro call a
    /// diagnostic about generated code belongs to (`siteBlame`). Null outside a parse.
    parse_cursor: ?*const u32 = null,
    /// Tables of the class machinery and of generic functions (`name_index.Table`): what was
    /// found by reading every slot, method, template or function is found by its hash. Each
    /// is filled when it is asked, up to the count beside it, so the code that adds a slot or
    /// a template needs to know nothing of them.
    /// The slots by owner and name (`findMethod`).
    slot_table: name_index.Table = .{},
    slot_table_slots: [name_index.slotCount(types.limits.methods).?]u32 = undefined,
    slots_indexed: u32 = 0,
    /// The slots of each owner (`VisibleSlots`): the table has one entry for each owner, its
    /// first slot; `slot_owner_next` links an owner's slots in order and `slot_owner_last`,
    /// at that first slot, is the newest of them. It is `no_member` at every other slot.
    owner_table: name_index.Table = .{},
    owner_table_slots: [name_index.slotCount(types.limits.methods).?]u32 = undefined,
    slot_owner_next: [types.limits.methods]u32 = undefined,
    slot_owner_last: [types.limits.methods]u32 = undefined,
    /// One method declaration of each name (`methodNamed`).
    method_name_table: name_index.Table = .{},
    /// The declarations indexed by class and slot (`linkMethod`), and for each slot how many
    /// it has and how many of them are `<final>`: a slot with many declarations is asked
    /// through the supertypes of a class instead of through all of its declarations.
    class_method_table: name_index.Table = .{},
    class_method_slots: [name_index.slotCount(types.limits.methods).?]u32 = undefined,
    slot_declared: [types.limits.methods]u32 = undefined,
    slot_finals: [types.limits.methods]u32 = undefined,
    method_name_slots: [name_index.slotCount(types.limits.methods).?]u32 = undefined,
    methods_indexed: u32 = 0,
    /// The generic templates by name (`Parser.findGeneric`).
    generic_table: name_index.Table = .{},
    generic_slots: [name_index.slotCount(types.limits.functions).?]u32 = undefined,
    generics_indexed: u32 = 0,
    /// The published specializations by template and arguments (`findSpecialization`).
    specialization_table: name_index.Table = .{},
    specialization_slots: [name_index.slotCount(types.limits.functions).?]u32 = undefined,
    specializations_indexed: u32 = 0,
    /// Instantiations of parametric types (RFC-0073), and a table of them by template and
    /// arguments (`name_index.Table`, like every other lookup of the compiler): an instance is
    /// entered when it is added, and a compile begins by forgetting them all.
    instances: [types.limits.user_types]Instance = undefined,
    instance_count: u32 = 0,
    instance_table: name_index.Table = .{},
    instance_slots: [name_index.slotCount(types.limits.user_types).?]u32 = undefined,
    /// The inverse of `instances`, by type ID, trusted the same way.
    instance_by_type: [types.limits.user_types]u16 = undefined,
    /// The instantiations whose headers are being read, outermost first: one that is named
    /// again there is among its own supertypes.
    instantiating: [types.limits.instantiation_depth]struct { template: u32, arguments: types.Type } = undefined,
    reserving_depth: u32 = 0,
    /// The instantiations being completed at once, each inside a body of the one before, and
    /// the generation of each.
    completing: [types.limits.instantiation_depth]u16 = undefined,
    instantiation_depth: u32 = 0,
    /// The classes whose declarations are being compiled, outermost first: the class a
    /// top-level declaration declares, and the instantiations being completed.
    open_classes: [types.limits.instantiation_depth + 1]types.Type = undefined,
    open_count: u32 = 0,
    /// Classes and structs that are still collecting their fields and method signatures. While
    /// there is one, a class instantiation that is named is only reserved.
    declaring: u32 = 0,
    /// Every instantiation before this one is complete.
    settled: u32 = 0,
    /// The fields the class or struct being parsed has staged in `record_fields`, and how many
    /// inherited defaults precede theirs at the end of `field_defaults`. An instantiation made
    /// while they wait moves them out of its way.
    staged_fields: u32 = 0,
    staged_inherited: u32 = 0,
    /// An instantiation finished after a class with a larger type ID: the dispatch table is
    /// sorted once before it is published.
    dispatch_unsorted: bool = false,
    /// The declarations the pre-pass left for later (`Late`), in source order. Only programs
    /// with parametric types have any.
    late: [@max(types.limits.user_types, types.limits.functions)]Late = undefined,
    late_count: u32 = 0,
    /// While `reserveClasses` reads a bundle without modules declared in files: whether the
    /// file holding each import edge has said `using` of it by the token being read, so that
    /// an unqualified name reaches the public declarations of that file (`lateSeen`).
    late_using: [types.limits.imports]bool = undefined,
    /// The names a template body declares while its tokens are read (`ShadowScan`).
    shadow_names: [types.limits.local_bindings]ShadowName = undefined,
    /// While `markHidden` runs: the classes that are public or above a public one.
    hidden_owners: [types.limits.user_types]bool = undefined,
    /// RFC-0085, I11: whether the host asks for the resolution table (`forbic qualify`). Off, a
    /// compile writes nothing of it, so the program and every output are the same either way.
    qualify: bool = false,
    /// The table (`qualify.Resolution`): for each identifier the author wrote, the definition the
    /// compiler resolved it to, in the order resolved, one entry per position. There are no more
    /// such identifiers than tokens. `resolution_at[p]` is the entry at position `p` when that
    /// entry points back, so nothing is cleared by capacity; each pass starts the table again.
    resolutions: [types.limits.tokens]qualify.Resolution = undefined,
    resolution_count: u32 = 0,
    resolution_at: [types.limits.source_bytes]u32 = undefined,
    /// Positions noted again with another meaning: none in a consistent compile. The first is
    /// kept for the tests that require none.
    resolution_conflicts: u32 = 0,
    resolution_conflict: u32 = qualify.none,
    /// Whether the file declares a `ToString` function: 0 not asked yet, 1 no, 2 yes. A use of
    /// the built-in `ToString` is noted only where it does not share its name (RFC-0053, B5).
    text_declared: u8 = 0,

    pub fn compile(self: *Workspace, source: []const u8) Result {
        var with_library = macros.callCount(source) != 0;
        var extension: macros.Extension = .{};
        self.for_forced_count = 0;
        self.for_pending = 0;
        self.for_forced_sorted = 0;
        self.option_caught_count = 0;
        self.option_pending = 0;
        self.condition_forced_count = 0;
        self.condition_pending = 0;
        self.carry_site_count = 0;
        self.carry_pending = 0;
        self.landing_key_count = 0;
        self.landing_pending = 0;
        self.share_key_count = 0;
        self.share_pending = 0;
        self.for_suspended_count = 0;
        self.for_suspended_pending = 0;
        self.passes = 0;
        // The block, its numerals, its temporaries, its First templates and its exit words are
        // each asked for at most once and its words a bounded number of times
        // (`max_library_requests`), each `For` is sent to the general lowering at most once,
        // and each `option{...}` is made to catch at most once.
        // A compile that shares locals is compiled again (RFC-0085, I2); each such compile notes
        // at least one declaration that no earlier one did.
        // Each compile that finds a site in an iteration of a general `For` notes at least one
        // call that no earlier one did (RFC-0082, P3.8).
        for (0..max_library_requests + 1 + max_for_calls + max_caught_options + max_forced_conditions + max_carry_sites + max_landing_keys + max_share_keys + max_for_calls) |_| {
            self.module_storage.reset();
            self.has_library = false;
            self.library_wanted = .{};
            self.passes += 1;
            self.structured_compiled = false;
            const result = if (with_library) self.compileWithLibrary(source, extension) else self.compilePrepared(source, false);
            // A pass that noted constructors went on as if they caught: whatever it produced is
            // not the program. So for the conditions it noted (`wantCondition`).
            const noted = self.adoptConditions();
            const carried = self.adoptCarries();
            // A program that compiled with `Defer`s open at sites gets their landings (P3.3).
            const landed = self.adoptLandings(result == .ok and self.structured_compiled);
            // A pass that shared locals compiled their uses as copies (RFC-0085, I2).
            const shared = self.adoptShares();
            // So for the loops it noted (`wantFor`): their block gets the general templates.
            const forced = self.adoptFors();
            if (forced) extension.loops = true;
            // So for the loops whose iterations hold a site: their regions go (RFC-0082, P3.8).
            const suspended = self.adoptSuspendingFors();
            if (self.adoptOptions() or noted or carried or forced or landed or shared or suspended) {
                // A pass that noted a path assignment went on and may have ended at the next
                // `For` that needs the general lowering (`set Out[I]=X` indexes, so every such
                // loop is one). That failure does not depend on what was noted: answering it
                // with the same retry keeps a loop that fills an array at one compile instead
                // of two.
                if (carried and result == .failed and result.failed.code == .failure_context_required and self.forceFor()) extension.loops = true;
                continue;
            }
            if (result == .failed and result.failed.code == .macro_unavailable) {
                // A macro other than `For` is only found after lexing: retry with the library block.
                if (!with_library) {
                    with_library = true;
                    // What the call that found no block needs of one, it gets with it.
                    extension = extension.merged(self.library_wanted);
                    continue;
                }
                if (self.library_wanted.exceeds(extension)) {
                    extension = extension.merged(self.library_wanted);
                    continue;
                }
            }
            if (result == .failed and result.failed.code == .failure_context_required and self.forceFor()) {
                // The call is lowered by the general templates from now on: its block gets them.
                extension.loops = true;
                continue;
            }
            return result;
        }
        unreachable;
    }

    /// How often one module can send its compile back for more library text: once for the
    /// block and at most once for each kind of generated line (a request names at least one
    /// kind the block lacks, or more words), and then for each doubling of the words that copies
    /// of `Defer` bodies take (`fnWord`): the words start at one or more and stop doubling
    /// beyond half the token capacity. The `Spawn` words of such copies (RFC-0082), and from
    /// P3.4 their `Branch` words, double the same way, and so do the names of hidden raw
    /// cells and fields (RFC-0084, P4.3).
    const max_library_requests = 1 + extension_kinds + 4 * word_doublings;
    const extension_kinds = @typeInfo(macros.Extension).@"struct".field_names.len;
    const word_doublings = std.math.log2_int_ceil(usize, types.limits.tokens) + 1;
    comptime {
        // Every field of `Extension` is one kind of line; a new one is counted by being added.
        std.debug.assert(extension_kinds == 13);
        std.debug.assert(@hasField(macros.Extension, "carries") and @hasField(macros.Extension, "loops") and @hasField(macros.Extension, "cases"));
    }

    fn compileWithLibrary(self: *Workspace, source: []const u8, extension: macros.Extension) Result {
        const calls = macros.callCount(source);
        const total = source.len + macros.libraryLength(calls, extension);
        if (total > self.combined_source.len) return .{ .failed = .{ .span = .{ .start = 0, .end = 0 }, .code = .source_limit } };
        @memcpy(self.combined_source[0..source.len], source);
        macros.writeLibrary(self.combined_source[source.len..total], calls, extension);
        self.has_library = true;
        self.library_base[0] = @intCast(source.len);
        self.library_templates[0] = @intCast(source.len + macros.templatesOffset(calls));
        self.library_extension[0] = extension;
        self.library_used[0] = 0;
        self.library_names[0] = 0;
        self.library_spawns[0] = 0;
        self.library_branches[0] = 0;
        self.library_raws[0] = 0;
        self.library_blame[0] = .{ .start = @intCast(source.len), .end = @intCast(source.len) };
        return self.compilePrepared(self.combined_source[0..total], false);
    }

    pub fn compileBundle(self: *Workspace, bundle: modules.Bundle) BundleResult {
        // RFC-0093: a bundle whose root is a module path is a folder tree. Each folder becomes
        // one module made of its files, compiled as any module is; a diagnostic points into
        // the file that holds it.
        if (bundle.parts.len == 0 and bundle.root.len != 0 and bundle.root[0] == '/') {
            const joined = switch (self.module_storage.folders.join(bundle)) {
                .failed => |problem| return .{ .failed = problem },
                .ok => |joined| joined,
            };
            std.debug.assert(joined.parts.len != 0 or joined.modules.len == 0);
            if (joined.parts.len == 0) return .{ .failed = .{ .path = bundle.root, .source = "", .diagnostic = .{ .span = .{ .start = 0, .end = 0 }, .code = .missing_module } } };
            return switch (self.compileBundle(joined)) {
                .ok => |program| .{ .ok = program },
                .failed => |problem| .{ .failed = modules.locateFile(joined, problem) },
            };
        }
        var needs: [types.limits.modules]bool = @splat(false);
        if (bundle.modules.len <= needs.len) for (bundle.modules, 0..) |input, index| {
            needs[index] = macros.callCount(input.source) != 0;
        };
        var extensions: [types.limits.modules]macros.Extension = @splat(.{});
        self.for_forced_count = 0;
        self.for_pending = 0;
        self.for_forced_sorted = 0;
        self.option_caught_count = 0;
        self.option_pending = 0;
        self.condition_forced_count = 0;
        self.condition_pending = 0;
        self.carry_site_count = 0;
        self.carry_pending = 0;
        self.landing_key_count = 0;
        self.landing_pending = 0;
        self.share_key_count = 0;
        self.share_pending = 0;
        self.for_suspended_count = 0;
        self.for_suspended_pending = 0;
        self.passes = 0;
        for (0..types.limits.modules * max_library_requests + 1 + max_for_calls + max_caught_options + max_forced_conditions + max_carry_sites + max_landing_keys + max_share_keys + max_for_calls) |_| {
            self.passes += 1;
            self.structured_compiled = false;
            const result = self.compileBundleWith(bundle, &needs, &extensions);
            const noted = self.adoptConditions();
            const carried = self.adoptCarries();
            // As in `compile`: the modules of the loops this pass noted get the general templates.
            var noted_module: u32 = std.math.maxInt(u32);
            for (self.for_forced[self.for_forced_count..][0..self.for_pending]) |key| {
                // Loops are noted in the order they are parsed, so a module's come together.
                if (key.module == noted_module) continue;
                noted_module = key.module;
                const path = self.module_storage.modules[key.module].path.text(self.module_storage.paths[0..self.module_storage.path_count]);
                if (bundle.modules.len <= needs.len) for (bundle.modules, 0..) |input, index| {
                    if (std.mem.eql(u8, input.path, path)) extensions[index].loops = true;
                };
            }
            const forced_loops = self.adoptFors();
            const landed = self.adoptLandings(result == .ok and self.structured_compiled);
            const shared = self.adoptShares();
            // As in `compile`: a call noted for a site in an iteration is in a module that has
            // the general templates already.
            const suspended = self.adoptSuspendingFors();
            if (self.adoptOptions() or noted or carried or forced_loops or landed or shared or suspended) {
                // As in `compile`: the `For` that ended this pass is sent to the general
                // lowering with the same retry.
                if (carried and result == .failed and result.failed.diagnostic.code == .failure_context_required and self.forceFor()) {
                    const forced = self.for_forced[self.for_forced_count - 1].module;
                    const path = self.module_storage.modules[forced].path.text(self.module_storage.paths[0..self.module_storage.path_count]);
                    if (bundle.modules.len <= needs.len) for (bundle.modules, 0..) |input, index| {
                        if (std.mem.eql(u8, input.path, path)) extensions[index].loops = true;
                    };
                }
                continue;
            }
            if (result == .failed and result.failed.diagnostic.code == .macro_unavailable and bundle.modules.len <= needs.len) {
                // The module that used a macro without a library block gets one, and everything is redone.
                const blamed = for (bundle.modules, 0..) |input, index| {
                    if (std.mem.eql(u8, input.path, result.failed.path)) break index;
                } else return result;
                if (!needs[blamed]) {
                    needs[blamed] = true;
                    extensions[blamed] = extensions[blamed].merged(self.library_wanted);
                    continue;
                }
                // So is one whose block lacks generated text.
                if (self.library_wanted.exceeds(extensions[blamed])) {
                    extensions[blamed] = extensions[blamed].merged(self.library_wanted);
                    continue;
                }
            }
            if (result == .failed and result.failed.diagnostic.code == .failure_context_required and self.forceFor()) {
                // As in `compile`: the module of the call gets the general templates with the retry.
                const forced = self.for_forced[self.for_forced_count - 1].module;
                const path = self.module_storage.modules[forced].path.text(self.module_storage.paths[0..self.module_storage.path_count]);
                if (bundle.modules.len <= needs.len) for (bundle.modules, 0..) |input, index| {
                    if (std.mem.eql(u8, input.path, path)) extensions[index].loops = true;
                };
                continue;
            }
            return result;
        }
        unreachable;
    }

    fn compileBundleWith(self: *Workspace, bundle: modules.Bundle, needs: []const bool, extensions: []const macros.Extension) BundleResult {
        self.resetCompiler("");
        self.has_library = false;
        self.library_wanted = .{};
        // A module that uses a macro gets its library block appended before provenance is built.
        var augmented: [types.limits.modules]modules.Input = undefined;
        var offsets: [types.limits.modules]u32 = @splat(0);
        var used: usize = 0;
        const chosen: modules.Bundle = if (bundle.modules.len > augmented.len) bundle else blk: {
            for (bundle.modules, 0..) |input, index| {
                augmented[index] = input;
                if (!needs[index]) continue;
                const calls = macros.callCount(input.source);
                const total = input.source.len + macros.libraryLength(calls, extensions[index]);
                if (total > self.combined_source.len - used) return .{ .failed = .{ .path = input.path, .source = input.source, .diagnostic = .{ .span = .{ .start = 0, .end = 0 }, .code = .source_limit } } };
                const segment = self.combined_source[used..][0..total];
                @memcpy(segment[0..input.source.len], input.source);
                macros.writeLibrary(segment[input.source.len..], calls, extensions[index]);
                augmented[index].source = segment;
                offsets[index] = @intCast(input.source.len);
                used += total;
                self.has_library = true;
            }
            break :blk .{ .root = bundle.root, .modules = augmented[0..bundle.modules.len], .parts = bundle.parts };
        };
        const prepared = switch (self.module_storage.prepare(chosen, &self.tokens)) {
            .failed => |problem| return .{ .failed = problem },
            .ok => |prepared| prepared,
        };
        if (self.has_library) {
            @memset(&self.library_base, 0);
            @memset(&self.library_used, 0);
            @memset(&self.library_names, 0);
            @memset(&self.library_spawns, 0);
            @memset(&self.library_branches, 0);
            @memset(&self.library_raws, 0);
            for (prepared.modules, 0..) |module, index| {
                const path = module.path.text(prepared.paths);
                for (bundle.modules, 0..) |input, which| {
                    if (offsets[which] == 0 or !std.mem.eql(u8, input.path, path)) continue;
                    self.library_base[index] = module.source.start + offsets[which];
                    self.library_templates[index] = self.library_base[index] + @as(u32, @intCast(macros.templatesOffset(macros.callCount(input.source))));
                    self.library_extension[index] = extensions[which];
                    self.library_blame[index] = .{ .start = self.library_base[index], .end = self.library_base[index] };
                }
            }
        }
        return switch (self.compilePrepared(prepared.source, true)) {
            .ok => |program| .{ .ok = program },
            .failed => |diagnostic| .{ .failed = modules.locate(prepared.source, prepared.paths, prepared.modules, diagnostic, bundle.root) },
        };
    }

    const max_path_segments = 16;
    const max_pending = 64;

    /// A streaming token rewrite: tokens flow from `tokens` into `spare_tokens`, so a pass costs
    /// one copy however many statements it rewrites. A rewritten statement owes closing tokens at
    /// a later source position; those wait on a stack. Statements nest, so the top entry is
    /// always the nearest position.
    const Rewrite = struct {
        const Pending = struct { at: usize, count: u8, tokens: [max_path_segments + 3]Token };
        out: usize = 0,
        pending: [max_pending]Pending = undefined,
        pending_count: usize = 0,
    };

    fn emitTo(self: *Workspace, rw: *Rewrite, token: Token) ParseError!void {
        if (rw.out >= self.spare_tokens.len) return self.fail(token.span, .token_limit);
        self.spare_tokens[rw.out] = token;
        rw.out += 1;
    }

    /// Emits `tokens` just before source token `at` is copied.
    fn owe(self: *Workspace, rw: *Rewrite, at: usize, tokens: []const Token) ParseError!void {
        if (rw.pending_count == max_pending) return self.fail(self.tokens[at].span, .expression_limit);
        std.debug.assert(rw.pending_count == 0 or rw.pending[rw.pending_count - 1].at >= at);
        rw.pending[rw.pending_count] = .{ .at = at, .count = @intCast(tokens.len), .tokens = undefined };
        @memcpy(rw.pending[rw.pending_count].tokens[0..tokens.len], tokens);
        rw.pending_count += 1;
    }

    fn settle(self: *Workspace, rw: *Rewrite, position: usize) ParseError!void {
        while (rw.pending_count != 0 and rw.pending[rw.pending_count - 1].at == position) {
            rw.pending_count -= 1;
            const entry = rw.pending[rw.pending_count];
            for (entry.tokens[0..entry.count]) |token| try self.emitTo(rw, token);
        }
    }

    /// Starts a rewrite at the first token a pass changes: the prefix is copied untouched.
    fn beginRewrite(self: *Workspace, rw: *Rewrite, first: usize) void {
        @memcpy(self.spare_tokens[0..first], self.tokens[0..first]);
        rw.out = first;
    }

    fn finishRewrite(self: *Workspace, rw: *Rewrite) void {
        std.debug.assert(rw.pending_count == 0);
        @memcpy(self.tokens[0..rw.out], self.spare_tokens[0..rw.out]);
        self.token_count = @intCast(rw.out);
    }

    /// RFC-0085, I8: the standard `accessor`, if this compile has made it and still has it.
    fn standardAccessor(self: *const Workspace) ?types.Type {
        const made = self.accessor_type orelse return null;
        const item = catalogue.definition(made, self.catalogue.definitions[0..self.catalogue.count]) orelse return null;
        if (item != .record or !std.meta.eql(item.record.name, self.accessor_name)) return null;
        return made;
    }

    fn zeroWidth(position: u32) Span {
        return .{ .start = position, .end = position };
    }

    fn isName(self: *const Workspace, index: usize, name: []const u8) bool {
        const token = self.tokens[index];
        if (token.kind != .identifier or !std.mem.eql(u8, token.span.text(self.source), name)) return false;
        // A field spelled like a keyword (`P.set`) is not one.
        return index == 0 or self.tokens[index - 1].kind != .dot;
    }

    /// The terminator of the statement or argument that starts at `from`: a newline, separator,
    /// unmatched closer or the end of input.
    fn statementEnd(self: *Workspace, from: usize) ParseError!usize {
        var depth: usize = 0;
        var at = from;
        while (at < self.token_count) : (at += 1) {
            const kind = self.tokens[at].kind;
            if (kind == .eof) return at;
            if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) {
                depth += 1;
                if (depth > types.limits.expression_depth) return self.fail(self.tokens[at].span, .expression_limit);
            }
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) {
                if (depth == 0) return at;
                depth -= 1;
            }
            if (depth == 0 and (kind == .newline or kind == .separator)) return at;
        }
        return self.token_count - 1;
    }

    /// The token after the one path segment (`.field` or `[index]`) starting at `from`,
    /// or `from` itself when none starts there.
    fn segmentEnd(self: *Workspace, from: usize) usize {
        if (from + 1 >= self.token_count) return from;
        if (self.tokens[from].kind == .dot and self.tokens[from + 1].kind == .identifier) return from + 2;
        if (self.tokens[from].kind != .left_bracket) return from;
        var depth: usize = 0;
        var close = from;
        while (close < self.token_count) : (close += 1) {
            const kind = self.tokens[close].kind;
            if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) depth += 1;
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) {
                depth -= 1;
                if (depth == 0) break;
            }
            if (kind == .eof or kind == .newline or kind == .separator) return from;
        }
        if (close >= self.token_count or self.tokens[close].kind != .right_bracket) return from;
        return close + 1;
    }

    /// The token after a path suffix: any run of `.field` and `[index]` segments starting at `from`.
    fn pathEnd(self: *Workspace, from: usize) usize {
        var end = from;
        while (true) {
            const next = self.segmentEnd(end);
            if (next == end) return end;
            end = next;
        }
    }

    /// Whether every `[index]` in the path tokens is a pure expression of names, numbers
    /// and arithmetic, so a rewrite that repeats the path evaluates it exactly once in effect.
    fn indexesArePure(self: *Workspace, start: usize, end: usize) bool {
        var inside = false;
        for (self.tokens[start..end]) |token| switch (token.kind) {
            .left_bracket => {
                if (inside) return false;
                inside = true;
            },
            .right_bracket => inside = false,
            .identifier, .integer, .floating, .string, .escaped_string, .character, .dot, .plus, .minus, .star, .slash => {},
            else => if (inside) return false,
        };
        return true;
    }

    /// Whether `name` is an import alias of the module that contains source offset `position`,
    /// or a module declared before it by a scope around it (RFC-0074): either starts a path
    /// to a cell, not to a field.
    fn isImportAlias(self: *const Workspace, name: []const u8, position: u32) bool {
        const storage = &self.module_storage;
        if (storage.nested_count != 0) {
            const here: Span = .{ .start = position, .end = position };
            if (modules.home(here, storage.modules[0..storage.module_count], self.nestedModules())) |home| {
                var at = home;
                while (true) {
                    if (self.childModule(at, name, position) != null) return !self.localNamed(name, position);
                    at = self.outerScope(at) orelse break;
                }
            }
        }
        for (storage.modules[0..storage.module_count]) |module| {
            if (position < module.source.start or position >= module.source.end) continue;
            for (storage.imports[module.imports.start..module.imports.end]) |edge| {
                if (std.mem.eql(u8, name, edge.alias.text(self.source))) return true;
            }
            return false;
        }
        return false;
    }

    /// RFC-0084: the `=` of a live declaration or attachment that starts at `at`: `var live X`,
    /// `set live X` (a path too, which the parser refuses) or `live X` at the start of a
    /// statement. `var live:T`, `set live = e` and `live:T` name something called `live`.
    fn liveAt(self: *const Workspace, at: usize) ?usize {
        if (at + 3 >= self.token_count) return null;
        // P4.2: `var<private> live F` in a class body, whose `var` says who may assign the field.
        const restricted = at + 5 < self.token_count and self.isName(at, "var") and self.tokens[at + 1].kind == .less and self.tokens[at + 2].kind == .identifier and self.tokens[at + 3].kind == .greater and self.isName(at + 4, "live");
        const word: usize = if ((self.isName(at, "var") or self.isName(at, "set")) and self.isName(at + 1, "live")) at + 1 else if (restricted) at + 4 else if (self.isName(at, "live") and (at == 0 or self.tokens[at - 1].kind == .newline or self.tokens[at - 1].kind == .separator or self.tokens[at - 1].kind == .left_brace)) at else return null;
        if (self.tokens[word + 1].kind != .identifier) return null;
        var depth: usize = 0;
        var index = word + 2;
        while (index < self.token_count) : (index += 1) {
            const kind = self.tokens[index].kind;
            switch (kind) {
                .left_paren, .left_bracket, .left_brace => depth += 1,
                .right_paren, .right_bracket, .right_brace => {
                    if (depth == 0) return null;
                    depth -= 1;
                },
                .equal => if (depth == 0) return index,
                .newline, .separator, .eof => if (depth == 0) return null,
                else => {},
            }
        }
        return null;
    }

    /// RFC-0084, P4.2: whether the `set live` at `at`, whose `=` is `equal`, names a field of an
    /// instance, `set live E.F`: its target ends `.F` after some expression `E`. `set live M.X`
    /// on a module `M` that the program imports names the cell `X` of `M`.
    fn liveFieldAt(self: *const Workspace, at: usize, equal: usize) bool {
        if (!self.isName(at, "set") or equal < at + 5) return false;
        if (self.tokens[equal - 1].kind != .identifier or self.tokens[equal - 2].kind != .dot) return false;
        const first = self.tokens[at + 2];
        // A path of modules, `M.X` or `Outer.Inner.X`, names a cell of a module (C29): it starts
        // at a module the program imports or declares, and each name before the last is a
        // module's. Any other path names a field.
        if (first.kind != .identifier or !self.isImportAlias(first.span.text(self.source), first.span.start)) return true;
        var segment = at + 3;
        while (segment + 1 < equal) : (segment += 2) {
            if (self.tokens[segment].kind != .dot or self.tokens[segment + 1].kind != .identifier) return true;
            if (segment + 1 == equal - 1) return false;
            const text = self.tokens[segment + 1].span.text(self.source);
            const module = for (self.nestedModules()) |nested| {
                if (std.mem.eql(u8, nested.name.text(self.source), text)) break true;
            } else false;
            if (!module) return true;
        }
        return false;
    }

    /// RFC-0084: the guard `G` of `var live X:T = G`, `set live X = G` and `live Y:T = G` is
    /// given braces and a mark, `<guard>{ G }`, which the parser compiles as the body of an
    /// anonymous function of no parameters, named by the word `live`. What `G` is reaches to
    /// the end of its statement.
    fn desugarLive(self: *Workspace) ParseError!void {
        const start = for (0..self.token_count) |index| {
            if (self.liveAt(index) != null) break index;
        } else return;
        var rw: Rewrite = .{};
        self.beginRewrite(&rw, start);
        var at = start;
        while (at < self.token_count) {
            try self.settle(&rw, at);
            if (self.liveAt(at)) |equal| {
                const word = if (self.isName(at, "live")) at else if (self.isName(at + 1, "live")) at + 1 else at + 4;
                const stop = try self.statementEnd(equal + 1);
                if (stop == equal + 1) return self.fail(self.tokens[equal].span, .expected_expression);
                if (self.liveFieldAt(at, equal)) {
                    // P4.2: `set live E.F = G` is `set live <field>(E, F, <guard>{ G })`, so that
                    // `E` is evaluated once, as any operand, before the guard is built.
                    for (self.tokens[at .. at + 2]) |token| try self.emitTo(&rw, token);
                    try self.emitTo(&rw, .{ .kind = .synthetic_live_field, .span = self.tokens[word].span });
                    try self.emitTo(&rw, .{ .kind = .left_paren, .span = zeroWidth(self.tokens[at + 2].span.start) });
                    for (self.tokens[at + 2 .. equal - 2]) |token| try self.emitTo(&rw, token);
                    try self.emitTo(&rw, .{ .kind = .comma, .span = self.tokens[equal - 2].span });
                    try self.emitTo(&rw, self.tokens[equal - 1]);
                    try self.emitTo(&rw, .{ .kind = .comma, .span = self.tokens[equal].span });
                    try self.emitTo(&rw, .{ .kind = .synthetic_guard, .span = self.tokens[word].span });
                    try self.emitTo(&rw, .{ .kind = .left_brace, .span = zeroWidth(self.tokens[equal + 1].span.start) });
                    try self.owe(&rw, stop, &.{ .{ .kind = .right_brace, .span = zeroWidth(self.tokens[stop - 1].span.end) }, .{ .kind = .right_paren, .span = zeroWidth(self.tokens[stop - 1].span.end) } });
                    at = equal + 1;
                    continue;
                }
                for (self.tokens[at .. equal + 1]) |token| try self.emitTo(&rw, token);
                try self.emitTo(&rw, .{ .kind = .synthetic_guard, .span = self.tokens[word].span });
                try self.emitTo(&rw, .{ .kind = .left_brace, .span = zeroWidth(self.tokens[equal + 1].span.start) });
                try self.owe(&rw, stop, &.{.{ .kind = .right_brace, .span = zeroWidth(self.tokens[stop - 1].span.end) }});
                at = equal + 1;
                continue;
            }
            try self.emitTo(&rw, self.tokens[at]);
            at += 1;
        }
        self.finishRewrite(&rw);
    }

    /// RFC-0084, P4.3: a declaration whose type may be a function, `X:F = E`, `X:Bounds.Apply = E`
    /// or `In->Out:F = E` (each with `var` or `live` before it), gets the guard such a type makes,
    /// written after its colon: `X:<live type>{ F(<raw>) }<end> F = E`. Whether `F` names a
    /// function, a method path or a type is a question of names, which the parser answers: it
    /// compiles the guard in the first case and steps over it otherwise (`parseTypeValue`). So
    /// this pass marks only what may be one: a declaration with `->`, one whose type is a path that
    /// does not start at a module, and one whose type is a name the program declares at the start
    /// of a statement with a parenthesis after it, as a function is. Every other declaration keeps
    /// its tokens, and a program with none keeps all of them.
    noinline fn desugarLiveTypes(self: *Workspace) ParseError!void {
        var room: []Span = &.{};
        var named: usize = 0;
        defer if (room.len != 0) scratch.free(room);
        var marked = false;
        {
            var starts: StatementStarts = .{};
            for (0..self.token_count) |at| {
                if (!starts.next(self, at)) continue;
                if (self.liveTypeShape(at) != null) marked = true;
                if (self.functionDeclaredAt(at)) {
                    if (room.len == 0) room = scratch.alloc(Span, self.token_count) orelse return self.fail(self.tokens[at].span, .token_limit);
                    room[named] = self.tokens[at].span;
                    named += 1;
                }
            }
        }
        if (!marked) return;
        const names = room[0..named];
        std.sort.pdq(Span, names, self.source, spanTextBefore);
        var rw: Rewrite = .{};
        var started = false;
        var starts: StatementStarts = .{};
        var insert: ?LiveTypeShape = null;
        for (0..self.token_count) |at| {
            if (starts.next(self, at)) if (self.liveTypeShape(at)) |shape| if (self.liveTypeMarked(shape, names)) {
                insert = shape;
                if (!started) {
                    self.beginRewrite(&rw, at);
                    started = true;
                }
            };
            if (started) try self.emitTo(&rw, self.tokens[at]);
            const shape = insert orelse continue;
            if (at != shape.colon) continue;
            insert = null;
            const first = zeroWidth(self.tokens[shape.path_start].span.start);
            const last = zeroWidth(self.tokens[shape.path_end - 1].span.end);
            try self.emitTo(&rw, .{ .kind = .synthetic_live_type, .span = first });
            try self.emitTo(&rw, .{ .kind = .left_brace, .span = first });
            for (self.tokens[shape.path_start..shape.path_end]) |token| try self.emitTo(&rw, token);
            try self.emitTo(&rw, .{ .kind = .left_paren, .span = last });
            try self.emitTo(&rw, .{ .kind = .synthetic_live_raw, .span = last });
            try self.emitTo(&rw, .{ .kind = .right_paren, .span = last });
            try self.emitTo(&rw, .{ .kind = .right_brace, .span = last });
            try self.emitTo(&rw, .{ .kind = .synthetic_live_end, .span = last });
        }
        if (started) self.finishRewrite(&rw);
    }

    fn spanTextBefore(source: []const u8, a: Span, b: Span) bool {
        return std.mem.order(u8, a.text(source), b.text(source)) == .lt;
    }

    /// Where statements start (RFC-0084, P4.3): at the first token, after a newline, a separator
    /// or an opening brace, and never inside a parenthesis or a bracket. Fed every token in order.
    const StatementStarts = struct {
        /// Whether each open delimiter is a brace; deeper than this, nothing starts.
        open: [64]bool = undefined,
        depth: usize = 0,
        fn next(self: *StatementStarts, w: *const Workspace, at: usize) bool {
            const inside_brace = self.depth == 0 or (self.depth <= self.open.len and self.open[self.depth - 1]);
            const after = at == 0 or switch (w.tokens[at - 1].kind) {
                .newline, .separator, .left_brace => true,
                else => false,
            };
            switch (w.tokens[at].kind) {
                .left_brace, .left_paren, .left_bracket => |kind| {
                    if (self.depth < self.open.len) self.open[self.depth] = kind == .left_brace;
                    self.depth += 1;
                },
                .right_brace, .right_paren, .right_bracket => self.depth -|= 1,
                else => {},
            }
            return inside_brace and after and w.tokens[at].kind == .identifier;
        }
    };

    /// `[var[<a>]] [live] Name[<a>]... [->Name[<a>]...] : Path` at `at` (RFC-0084, P4.3), in the
    /// program's own text: where its colon is and where its type's path lies.
    const LiveTypeShape = struct { colon: usize, path_start: usize, path_end: usize, arrow: bool };
    fn liveTypeShape(self: *const Workspace, at: usize) ?LiveTypeShape {
        const kinds = struct {
            fn of(w: *const Workspace, index: usize) Token.Kind {
                return if (index < w.token_count) w.tokens[index].kind else .eof;
            }
            fn access(w: *const Workspace, index: usize) bool {
                return of(w, index) == .less and of(w, index + 1) == .identifier and of(w, index + 2) == .greater;
            }
        };
        var index = at;
        if (self.isName(index, "var")) {
            index += 1;
            if (kinds.access(self, index)) index += 3;
        }
        if (kinds.of(self, index) == .identifier and self.isName(index, "live") and kinds.of(self, index + 1) == .identifier) index += 1;
        if (kinds.of(self, index) != .identifier or self.libraryModule(self.tokens[index].span) != null) return null;
        index += 1;
        while (kinds.access(self, index)) index += 3;
        var arrow = false;
        if (kinds.of(self, index) == .minus and kinds.of(self, index + 1) == .greater and self.tokens[index].span.end == self.tokens[index + 1].span.start) {
            arrow = true;
            index += 2;
            if (kinds.of(self, index) != .identifier) return null;
            index += 1;
            while (kinds.access(self, index)) index += 3;
        }
        if (kinds.of(self, index) != .colon or kinds.of(self, index + 1) != .identifier) return null;
        const colon = index;
        var end = index + 2;
        while (kinds.of(self, end) == .dot and kinds.of(self, end + 1) == .identifier) end += 2;
        return .{ .colon = colon, .path_start = colon + 1, .path_end = end, .arrow = arrow };
    }

    /// Whether the program declares a function named by the identifier at statement start `at`:
    /// `Name(...)` or `Name<access>(...)`, then its effects and the colon of its result. A call
    /// at the start of a statement has no colon there. A generic one, `Name[`, is not counted:
    /// neither is a parametric type, whose uses would all be marked, and a generic function is no
    /// type anyway.
    fn functionDeclaredAt(self: *const Workspace, at: usize) bool {
        if (self.libraryModule(self.tokens[at].span) != null or reserved(self.tokens[at].span.text(self.source))) return false;
        return self.functionShapeAt(at, false);
    }

    /// The shape of a function declaration at statement start `at`, whatever the name; with
    /// `transparent` the one whose result is its body's type (`Name(...)<effects> := Body`).
    fn functionShapeAt(self: *const Workspace, at: usize, comptime transparent: bool) bool {
        var index = at + 1;
        while (index + 2 < self.token_count and self.tokens[index].kind == .less and self.tokens[index + 1].kind == .identifier and self.tokens[index + 2].kind == .greater) index += 3;
        if (index >= self.token_count or self.tokens[index].kind != .left_paren) return false;
        index = self.segmentClose(index) + 1;
        while (index + 2 < self.token_count and self.tokens[index].kind == .less and self.tokens[index + 1].kind == .identifier and self.tokens[index + 2].kind == .greater) index += 3;
        return index + 1 < self.token_count and self.tokens[index].kind == .colon and (self.tokens[index + 1].kind == .equal) == transparent;
    }

    /// Whether the declaration `shape` may have a function for its type (`desugarLiveTypes`).
    fn liveTypeMarked(self: *const Workspace, shape: LiveTypeShape, names: []const Span) bool {
        if (shape.arrow) return true;
        const first = self.tokens[shape.path_start];
        if (self.libraryModule(first.span) != null) return false;
        const single = shape.path_end - shape.path_start == 1;
        // A path that starts at a module names what that module declares.
        if (!single and !self.isImportAlias(first.span.text(self.source), first.span.start)) return true;
        const last = self.tokens[shape.path_end - 1].span.text(self.source);
        var low: usize = 0;
        var high: usize = names.len;
        while (low < high) {
            const middle = low + (high - low) / 2;
            switch (std.mem.order(u8, names[middle].text(self.source), last)) {
                .lt => low = middle + 1,
                .gt => high = middle,
                .eq => return true,
            }
        }
        return false;
    }

    /// The end of the path of a compound assignment `set P.A[I] op= e` that starts at `at`.
    fn compoundAt(self: *Workspace, at: usize) ?usize {
        if (at + 4 >= self.token_count or !self.isName(at, "set") or self.tokens[at + 1].kind != .identifier) return null;
        const end = self.pathEnd(at + 2);
        if (end + 1 >= self.token_count) return null;
        const op = self.tokens[end];
        const equal = self.tokens[end + 1];
        if (equal.kind != .equal or op.span.end != equal.span.start) return null;
        if (op.kind != .plus and op.kind != .minus and op.kind != .star and op.kind != .slash) return null;
        return end;
    }

    /// Whether token `index` starts a qualifier, `(Word:)Name` (RFC-0083).
    fn qualifierAt(self: *const Workspace, index: usize) bool {
        if (index + 4 >= self.token_count) return false;
        const t = self.tokens[index .. index + 5];
        return t[0].kind == .left_paren and t[1].kind == .identifier and t[2].kind == .colon and t[3].kind == .right_paren and t[4].kind == .identifier and t[2].span.start == t[1].span.end and t[3].span.start == t[2].span.end;
    }

    /// RFC-0083: the Book's qualifiers. `(local:)Name` is `Name`, recorded as written so: a
    /// local or parameter declared so may share its name with a declaration outside the
    /// function, and a use so written must be a local or a parameter. `(Module:)Name` is
    /// `Module.Name`, recorded so that `Module` must name a module. A qualifier is never
    /// written after a dot. Nothing in a program could spell these tokens before.
    fn desugarQualifiers(self: *Workspace) ParseError!void {
        self.qualifier_count = 0;
        self.enum_name_count = no_member;
        const start = for (0..self.token_count) |index| {
            if (self.qualifierAt(index)) break index;
        } else return;
        var rw: Rewrite = .{};
        self.beginRewrite(&rw, start);
        var at = start;
        while (at < self.token_count) {
            if (!self.qualifierAt(at)) {
                try self.emitTo(&rw, self.tokens[at]);
                at += 1;
                continue;
            }
            const word = self.tokens[at + 1];
            const name = self.tokens[at + 4];
            if (at > 0 and self.tokens[at - 1].kind == .dot) return self.fail(self.tokens[at].span, .invalid_qualifier);
            if (self.qualifier_count == self.qualifiers.len) return self.fail(word.span, .expression_limit);
            const local = std.mem.eql(u8, word.span.text(self.source), "local");
            // A word the language gives a meaning (a builtin or compound type, `Block`, `For`,
            // `Case`, a literal) is no local and no module, and a macro would take the
            // qualifier away with it.
            // RFC-0085, I10: an enumerator qualified by its enum may be any word (09:547); it
            // stays a name after the dot, which no macro reads.
            if (local and reserved(name.span.text(self.source))) return self.fail(name.span, .invalid_qualifier);
            if (!local and (reserved(word.span.text(self.source)) or (reserved(name.span.text(self.source)) and !self.declaresEnum(word.span.text(self.source))))) return self.fail(word.span, .invalid_qualifier);
            self.qualifiers[self.qualifier_count] = .{ .position = if (local) name.span.start else word.span.start, .local = local };
            self.qualifier_count += 1;
            if (!local) {
                try self.emitTo(&rw, word);
                try self.emitTo(&rw, .{ .kind = .dot, .span = self.tokens[at + 2].span });
            }
            at += 4;
        }
        self.finishRewrite(&rw);
    }

    /// Whether the program declares an enum named `name`, `name := enum...` with any specifiers
    /// between (RFC-0085, I10). Read from the tokens, before anything is parsed: the parser
    /// checks again that the qualifier names an enum in reach.
    fn declaresEnum(self: *Workspace, name: []const u8) bool {
        if (self.enum_name_count == no_member) {
            self.enum_name_table.clear();
            self.enum_name_count = 0;
            for (0..self.token_count) |index| {
                if (!self.enumDeclaredAt(index)) continue;
                if (self.enum_name_count == types.limits.user_types) {
                    self.enum_name_count = types.limits.user_types + 1;
                    break;
                }
                if (self.enum_name_table.crowded()) {
                    self.enum_name_table.grow(&self.enum_name_slots);
                    for (0..index) |earlier| if (self.enumDeclaredAt(earlier)) self.enum_name_table.enter(&self.enum_name_slots, name_index.hashName(0, self.tokens[earlier].span.text(self.source)), @intCast(earlier));
                }
                self.enum_name_table.enter(&self.enum_name_slots, name_index.hashName(0, self.tokens[index].span.text(self.source)), @intCast(index));
                self.enum_name_count += 1;
            }
        }
        if (self.enum_name_count > types.limits.user_types) {
            for (0..self.token_count) |index| if (self.enumDeclaredAt(index) and std.mem.eql(u8, self.tokens[index].span.text(self.source), name)) return true;
            return false;
        }
        var same = self.enum_name_table.walk(&self.enum_name_slots, name_index.hashName(0, name));
        while (same.next()) |index| if (std.mem.eql(u8, self.tokens[index].span.text(self.source), name)) return true;
        return false;
    }
    /// Whether token `index` names an enum where it is declared: `e`, any `<word>`s, `:=`, `enum`.
    fn enumDeclaredAt(self: *const Workspace, index: usize) bool {
        if (self.tokens[index].kind != .identifier) return false;
        if (index > 0 and self.tokens[index - 1].kind == .dot) return false;
        var at = index + 1;
        while (at + 2 < self.token_count and self.tokens[at].kind == .less and self.tokens[at + 1].kind == .identifier and self.tokens[at + 2].kind == .greater) at += 3;
        return at + 2 < self.token_count and self.tokens[at].kind == .colon and self.tokens[at + 1].kind == .equal and self.tokens[at + 2].kind == .identifier and std.mem.eql(u8, self.tokens[at + 2].span.text(self.source), "enum");
    }

    /// The qualifier written for the name token at `position`, if one was (`desugarQualifiers`).
    fn qualifierFor(self: *const Workspace, position: u32) ?Qualifier {
        if (self.qualifier_count == 0) return null;
        const marks = self.qualifiers[0..self.qualifier_count];
        const index = std.sort.lowerBound(Qualifier, marks, position, struct {
            fn order(key: u32, item: Qualifier) std.math.Order {
                return std.math.order(key, item.position);
            }
        }.order);
        if (index == marks.len or marks[index].position != position) return null;
        return marks[index];
    }

    /// Whether the name token at `position` was written `(local:)Name`.
    fn localQualified(self: *const Workspace, position: u32) bool {
        const found = self.qualifierFor(position) orelse return false;
        return found.local;
    }

    /// Rewrites `set P op= e` into `set P = P op (e)` before parsing, so compound assignment
    /// works for cells, locals, fields and elements with every arithmetic operator. `P` is
    /// read before `e` runs, exactly as the long form reads it, and the inserted tokens
    /// borrow the original spans for diagnostics. Repeated indices must be pure.
    fn desugarCompoundSets(self: *Workspace) ParseError!void {
        var rw: Rewrite = .{};
        var started = false;
        var at: usize = 0;
        while (at < self.token_count) {
            if (started) try self.settle(&rw, at);
            if (self.compoundAt(at)) |end| {
                if (!started) {
                    self.beginRewrite(&rw, at);
                    started = true;
                }
                if (!self.indexesArePure(at + 2, end)) return self.fail(self.tokens[at + 2].span, .path_index_effects);
                const op = self.tokens[end];
                const equal = self.tokens[end + 1];
                const stop = try self.statementEnd(end + 2);
                try self.emitTo(&rw, self.tokens[at]);
                for (self.tokens[at + 1 .. end]) |token| try self.emitTo(&rw, token);
                try self.emitTo(&rw, equal);
                for (self.tokens[at + 1 .. end]) |token| try self.emitTo(&rw, token);
                try self.emitTo(&rw, op);
                try self.emitTo(&rw, .{ .kind = .left_paren, .span = zeroWidth(equal.span.end) });
                try self.owe(&rw, stop, &.{.{ .kind = .right_paren, .span = zeroWidth(self.tokens[stop].span.start) }});
                at = end + 2;
                continue;
            }
            if (started) try self.emitTo(&rw, self.tokens[at]);
            at += 1;
        }
        if (started) self.finishRewrite(&rw);
    }

    /// `set P.A[I].B = e` becomes `set P = WithField(P, A, WithIndex[P.A, I, WithField(P.A[I], B, e)])`,
    /// so updating a nested field or element is a whole-value assignment of a rebuilt
    /// value. The target stays a plain name for the existing assignment rules, and an
    /// element update fails (in the enclosing failure context) when an index is out of range.
    fn desugarPathSets(self: *Workspace) ParseError!void {
        var rw: Rewrite = .{};
        var started = false;
        var at: usize = 0;
        while (at < self.token_count) {
            if (started) try self.settle(&rw, at);
            if (try self.pathSetAt(at)) |end| {
                if (!started) {
                    self.beginRewrite(&rw, at);
                    started = true;
                }
                try self.rewritePathSet(&rw, at, end);
                at = end + 1;
                continue;
            }
            if (started) try self.emitTo(&rw, self.tokens[at]);
            at += 1;
        }
        if (started) self.finishRewrite(&rw);
    }

    /// The `=` that ends the path of `set P.A[I] = e` at `at`, unless this is not a path assignment.
    fn pathSetAt(self: *Workspace, at: usize) ParseError!?usize {
        if (at + 4 >= self.token_count or !self.isName(at, "set") or self.tokens[at + 1].kind != .identifier) return null;
        if (self.tokens[at + 2].kind != .dot and self.tokens[at + 2].kind != .left_bracket) return null;
        // `set Module.Cell = e` writes an imported cell; the parser owns that form.
        if (self.isImportAlias(self.tokens[at + 1].span.text(self.source), self.tokens[at].span.start)) return null;
        const end = self.pathEnd(at + 2);
        if (end == at + 2 or end >= self.token_count or self.tokens[end].kind != .equal) return null;
        return end;
    }

    fn rewritePathSet(self: *Workspace, rw: *Rewrite, at: usize, end: usize) ParseError!void {
        const Segment = struct { start: usize, end: usize };
        var segments: [max_path_segments]Segment = undefined;
        var count: usize = 0;
        var cursor = at + 2;
        while (cursor < end) {
            if (count == max_path_segments) return self.fail(self.tokens[at].span, .token_limit);
            const last = self.segmentEnd(cursor);
            segments[count] = .{ .start = cursor, .end = last };
            count += 1;
            cursor = last;
        }
        // Every index except the last is repeated by the nested rewrite.
        if (!self.indexesArePure(at + 2, segments[count - 1].start)) return self.fail(self.tokens[at + 2].span, .path_index_effects);
        const stop = try self.statementEnd(end + 1);
        const name = self.tokens[at + 1];
        const here = self.tokens[at + 2].span;
        try self.emitTo(rw, self.tokens[at]);
        try self.emitTo(rw, name);
        try self.emitTo(rw, .{ .kind = .equal, .span = self.tokens[end].span });
        for (segments[0..count]) |segment| {
            const is_field = self.tokens[segment.start].kind == .dot;
            try self.emitTo(rw, .{ .kind = if (is_field) .synthetic_with_field else .synthetic_with_index, .span = here });
            try self.emitTo(rw, .{ .kind = if (is_field) .left_paren else .left_bracket, .span = here });
            // The value being updated at this level: the name and the earlier segments.
            try self.emitTo(rw, name);
            for (self.tokens[at + 2 .. segment.start]) |token| try self.emitTo(rw, token);
            try self.emitTo(rw, .{ .kind = .comma, .span = here });
            if (is_field) {
                try self.emitTo(rw, self.tokens[segment.start + 1]);
            } else {
                for (self.tokens[segment.start + 1 .. segment.end - 1]) |token| try self.emitTo(rw, token);
            }
            try self.emitTo(rw, .{ .kind = .comma, .span = here });
        }
        try self.emitTo(rw, .{ .kind = .left_paren, .span = here });
        var closers: [max_path_segments + 1]Token = undefined;
        closers[0] = .{ .kind = .right_paren, .span = zeroWidth(self.tokens[stop].span.start) };
        var level = count;
        while (level > 0) {
            level -= 1;
            const is_field = self.tokens[segments[level].start].kind == .dot;
            closers[count - level] = .{ .kind = if (is_field) .right_paren else .right_bracket, .span = zeroWidth(self.tokens[stop].span.start) };
        }
        try self.owe(rw, stop, closers[0 .. count + 1]);
    }

    /// `Case(S, P1=>V1, ..., _=>D)` becomes `(If(S==(P1), V1, If(S==(P2), V2, ... D)))`.
    /// The scrutinee is a name or field path and every pattern a name, literal or arithmetic
    /// over them, so repeating the scrutinee is pure, free and sees one value. The default arm
    /// is required, which makes every Case total. Arms stay lazy because they are ordinary
    /// `If` branches, and the arm values are rewritten recursively, so Cases nest anywhere.
    /// A Case with any other scrutinee, a binding pattern or a guard takes `rewritePatternCase`.
    fn desugarCases(self: *Workspace) ParseError!void {
        var first: ?usize = null;
        for (0..self.token_count - 1) |index| {
            if (self.isName(index, "Case") and (self.tokens[index + 1].kind == .left_paren or self.tokens[index + 1].kind == .left_bracket)) {
                first = index;
                break;
            }
        }
        const start = first orelse return;
        var rw: Rewrite = .{};
        self.beginRewrite(&rw, start);
        try self.streamCases(&rw, start, self.token_count, 0);
        self.finishRewrite(&rw);
    }

    fn streamCases(self: *Workspace, rw: *Rewrite, from: usize, to: usize, depth: usize) ParseError!void {
        var at = from;
        while (at < to) {
            if (at + 1 < to and self.isName(at, "Case") and (self.tokens[at + 1].kind == .left_paren or self.tokens[at + 1].kind == .left_bracket)) {
                at = try self.rewriteCase(rw, at, depth);
                continue;
            }
            try self.emitTo(rw, self.tokens[at]);
            at += 1;
        }
    }

    /// The index range of `[from, to)` without the newlines at either end.
    fn trimmed(self: *const Workspace, from: usize, to: usize) [2]usize {
        var low = from;
        var high = to;
        while (low < high and self.tokens[low].kind == .newline) low += 1;
        while (high > low and self.tokens[high - 1].kind == .newline) high -= 1;
        return .{ low, high };
    }

    /// The `=>` of the arm in `range`, outside any brackets.
    fn caseArrow(self: *Workspace, range: [2]usize) ParseError!usize {
        var arrow: ?usize = null;
        var inner: usize = 0;
        for (range[0]..range[1]) |index| {
            const kind = self.tokens[index].kind;
            if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) inner += 1;
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) inner -|= 1;
            if (inner == 0 and kind == .arrow) {
                if (arrow != null) return self.fail(self.tokens[index].span, .case_arms);
                arrow = index;
            }
        }
        return arrow orelse self.fail(self.tokens[range[0]].span, .case_arms);
    }

    /// Whether two token ranges spell the same pattern: the same tokens with the same text.
    fn samePattern(self: *const Workspace, a: [2]usize, b: [2]usize) bool {
        if (a[1] - a[0] != b[1] - b[0]) return false;
        for (self.tokens[a[0]..a[1]], self.tokens[b[0]..b[1]]) |x, y| {
            if (x.kind != y.kind or !std.mem.eql(u8, x.span.text(self.source), y.span.text(self.source))) return false;
        }
        return true;
    }

    /// RFC-0080: in a `Case[...]` an arm that no value can select is an error, as in the Book
    /// (09:421). The rule is one a reader can check: an unguarded arm before it is written
    /// exactly like it, as a constant, as a type test of the same type, or as `option{}`.
    /// Whatever the first takes the second would have taken, and what the first refuses the
    /// second refuses. RFC-0090 applies it to `Case(...)` as well, where RFC-0050 had let the
    /// first of two such arms win: the Book's duplicate case is an error in every `case`.
    fn checkReachable(self: *Workspace, bounds: []const usize, item: usize, pattern: [2]usize) ParseError!void {
        const kind = self.patternKind(pattern, false) catch return;
        if (kind != .constant and kind != .typed and kind != .none) return;
        for (1..item) |earlier| {
            const arm = self.caseArm(bounds[earlier], bounds[earlier + 1] - 1) catch return;
            if (arm.guard != null) continue;
            const other = self.patternKind(arm.pattern, false) catch return;
            if (other != kind) continue;
            const same = switch (kind) {
                .constant => self.samePattern(arm.pattern, pattern),
                // The names the two arms bind may differ; the type after the colon decides.
                .typed => self.samePattern(.{ arm.pattern[0] + 1, arm.pattern[1] }, .{ pattern[0] + 1, pattern[1] }),
                else => true,
            };
            if (same) return self.fail(self.tokens[pattern[0]].span, .unreachable_arm);
        }
    }

    /// Records a `Case[...]` with patterns, before its scrutinee and arms are rewritten: cases are
    /// recorded in the order of their keywords.
    fn noteFailingCase(self: *Workspace, keyword: Span) ParseError!void {
        if (self.failing_case_count == max_failing_arms) return self.fail(keyword, .expression_limit);
        std.debug.assert(self.failing_case_count == 0 or self.failing_cases[self.failing_case_count - 1].keyword < keyword.start);
        self.failing_cases[self.failing_case_count] = .{ .keyword = keyword.start, .first = no_failing_arm, .last = no_failing_arm };
        self.failing_case_count += 1;
    }

    /// The recorded `Case[...]` whose keyword starts at `start`.
    fn failingCase(self: *Workspace, start: u32) ?*FailingCase {
        const cases = self.failing_cases[0..self.failing_case_count];
        const index = std.sort.lowerBound(FailingCase, cases, start, struct {
            fn order(key: u32, item: FailingCase) std.math.Order {
                return std.math.order(key, item.keyword);
            }
        }.order);
        if (index == cases.len or cases[index].keyword != start) return null;
        return &cases[index];
    }

    /// Records an arm of a `Case[...]` whose pattern takes every value if its type tests hold.
    fn noteFailingArm(self: *Workspace, keyword: u32, pattern: [2]usize) ParseError!void {
        const span: Span = .{ .start = self.tokens[pattern[0]].span.start, .end = self.tokens[pattern[1] - 1].span.end };
        if (self.failing_arm_count == max_failing_arms) return self.fail(span, .expression_limit);
        std.debug.assert(self.failing_arm_count == 0 or self.failing_arms[self.failing_arm_count - 1].end <= span.start);
        const case = self.failingCase(keyword).?;
        const index = self.failing_arm_count;
        // The rewrite has already read this pattern's kind, so this cannot fail.
        const typed = try self.patternKind(pattern, false) == .typed;
        self.failing_arms[index] = .{ .start = span.start, .end = span.end, .next = no_failing_arm, .keyword = keyword, .typed = typed };
        self.failing_arm_count += 1;
        if (case.last == no_failing_arm) case.first = index else self.failing_arms[case.last].next = index;
        case.last = index;
    }

    /// A type test of a `Case` pattern at `span` for `target`, which the static types alone
    /// decide when `known`. RFC-0083: an arm `Name:Type` whose type is one an earlier arm
    /// `Other:Wider` of the same `Case[...]` already takes (the same type, or a class below
    /// it) can take no value, which is `subsumed_arm`: the textual rule of RFC-0080 with the
    /// types the compiler knows here. RFC-0090 applies it to `Case(...)` too.
    fn noteFailingTest(self: *Workspace, span: Span, known: bool, target: types.Type) ParseError!void {
        const arms = self.failing_arms[0..self.failing_arm_count];
        // The last arm that starts at or before the test is the only one that can hold it.
        const after = std.sort.upperBound(FailingArm, arms, span.start, struct {
            fn order(key: u32, item: FailingArm) std.math.Order {
                return std.math.order(key, item.start);
            }
        }.order);
        if (after == 0) return;
        const arm = &arms[after - 1];
        if (span.end > arm.end) return;
        arm.tests += 1;
        arm.undecided = arm.undecided or !known;
        // A typed arm has its one test in every compilation of its text. Only a `Case[...]`
        // starts its counts again at its end (`checkFailingArms`); a `Case(...)` has no end the
        // parser sees, so its counts go on, and an earlier arm's `tested` is this compilation's
        // only if it was seen after this arm's last test: a compilation of the same text nested
        // in an earlier arm's value (a generic function that specializes itself there) has
        // seen both since, and then the check is left to that compilation.
        if (!arm.typed) return;
        const last = arm.stamp;
        self.failing_test_stamp += 1;
        arm.stamp = self.failing_test_stamp;
        arm.tested = target;
        const case = self.failingCase(arm.keyword) orelse return;
        var index = case.first;
        while (index != no_failing_arm and index != after - 1) : (index = self.failing_arms[index].next) {
            const earlier = self.failing_arms[index];
            if (!earlier.typed or earlier.tests == 0 or earlier.stamp <= last) continue;
            if (catalogue.subtype(target, earlier.tested, self.catalogue.definitions[0..self.catalogue.count])) return self.fail(.{ .start = arm.start, .end = arm.end }, .subsumed_arm);
        }
    }

    /// At the end of the `Case[...]` whose keyword is at `keyword`: an arm all of whose type tests
    /// held by the static types takes every value, so the form could not fail. The counts start
    /// again, for the next compilation of the same text (a generic function's next arguments).
    fn checkFailingArms(self: *Workspace, keyword: Span) ParseError!void {
        const case = self.failingCase(keyword.start) orelse return;
        var index = case.first;
        while (index != no_failing_arm) {
            const arm = &self.failing_arms[index];
            index = arm.next;
            const takes_all = arm.tests != 0 and !arm.undecided;
            arm.tests = 0;
            arm.undecided = false;
            if (takes_all) return self.fail(.{ .start = arm.start, .end = arm.end }, .case_cannot_fail);
        }
    }

    /// TASK-0109, B8: `_` is the wildcard of a `Case` pattern, in the arm `_ => V`, as `_:Type`
    /// and inside a shape (`option{_}`, `tuple{A, _}`), and it names nothing else: the Book
    /// reserves it. A declaration, parameter, field or loop variable of that name is refused
    /// where the token stands, before any rewrite, so no later pass sees a name `_`. Run on the
    /// source tokens, where the arms of a `Case` are still written as the program wrote them.
    fn checkUnderscore(self: *Workspace) ParseError!void {
        _ = try self.scanUnderscore(0, self.token_count, 0);
    }

    /// Reads `[from, to)` for a `_` that is no wildcard. False when a `Case` is not well formed,
    /// which stops the check: `rewriteCase` refuses that `Case` with its own diagnostic, and the
    /// arms of one that cannot be taken apart have no pattern to tell from a value.
    fn scanUnderscore(self: *Workspace, from: usize, to: usize, depth: usize) ParseError!bool {
        var at = from;
        while (at < to) {
            if (at + 1 < to and self.isName(at, "Case") and (self.tokens[at + 1].kind == .left_paren or self.tokens[at + 1].kind == .left_bracket)) {
                if (depth >= rewrite_depth) return self.fail(self.tokens[at].span, .expression_limit);
                at = (try self.scanUnderscoreCase(at, depth)) orelse return false;
            } else if (self.isName(at, "_")) {
                return self.fail(self.tokens[at].span, .underscore_name);
            } else at += 1;
        }
        return true;
    }

    /// The `=>` of the arm in `range` outside any brackets, where `caseArrow` would find it.
    fn armArrow(self: *const Workspace, range: [2]usize) ?usize {
        var inner: usize = 0;
        for (range[0]..range[1]) |index| {
            const kind = self.tokens[index].kind;
            if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) inner += 1;
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) inner -|= 1;
            if (inner == 0 and kind == .arrow) return index;
        }
        return null;
    }

    /// The Case at `at`: the arms are checked to have their `=>` before anything is read, so a
    /// Case that is not well formed costs one pass over its tokens. What is not a pattern is
    /// scanned (the scrutinee, the guards, the values) and the patterns are skipped. Null when
    /// the Case is not one `rewriteCase` would take apart; otherwise the index after its close.
    fn scanUnderscoreCase(self: *Workspace, at: usize, depth: usize) ParseError!?usize {
        var bounds: [types.limits.record_fields + 3]usize = undefined;
        var items: usize = 1;
        var level: usize = 0;
        var close = at + 2;
        bounds[0] = at + 2;
        while (close < self.token_count) : (close += 1) {
            const kind = self.tokens[close].kind;
            if (kind == .eof) return null;
            if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) level += 1;
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) {
                if (level == 0) break;
                level -= 1;
            }
            if (level == 0 and kind == .comma) {
                if (items + 1 == bounds.len) return null;
                bounds[items] = close + 1;
                items += 1;
            }
        }
        if (close >= self.token_count or items < 2) return null;
        bounds[items] = close + 1;
        for (1..items) |item| {
            if (self.armArrow(self.trimmed(bounds[item], bounds[item + 1] - 1)) == null) return null;
        }
        const scrutinee = self.trimmed(bounds[0], bounds[1] - 1);
        if (!try self.scanUnderscore(scrutinee[0], scrutinee[1], depth + 1)) return null;
        for (1..items) |item| {
            const range = self.trimmed(bounds[item], bounds[item + 1] - 1);
            const arrow = self.armArrow(range).?;
            // `where` after a pattern starts the guard, which is an expression like the value.
            const pattern = self.trimmed(range[0], arrow);
            var inner: usize = 0;
            for (pattern[0]..pattern[1]) |index| {
                const kind = self.tokens[index].kind;
                if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) inner += 1;
                if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) inner -|= 1;
                if (inner != 0 or index == pattern[0] or !self.isName(index, "where")) continue;
                if (!try self.scanUnderscore(index + 1, pattern[1], depth + 1)) return null;
                break;
            }
            if (!try self.scanUnderscore(arrow + 1, range[1], depth + 1)) return null;
        }
        return close + 1;
    }

    fn rewriteCase(self: *Workspace, rw: *Rewrite, at: usize, depth: usize) ParseError!usize {
        const keyword = self.tokens[at];
        if (depth >= rewrite_depth) return self.fail(keyword.span, .expression_limit);
        // RFC-0080: `Case[...]` is the Book's `case` without a default in a failure context.
        // It fails when no arm takes the scrutinee, so it has no `_` arm and need not cover
        // an enum; `Case(...)` stays total.
        const failing = self.tokens[at + 1].kind == .left_bracket;
        // Find the closing parenthesis and the depth-zero commas.
        var bounds: [types.limits.record_fields + 3]usize = undefined;
        var items: usize = 1;
        var level: usize = 0;
        var close = at + 2;
        bounds[0] = at + 2;
        while (close < self.token_count) : (close += 1) {
            const kind = self.tokens[close].kind;
            if (kind == .eof) return self.fail(keyword.span, .case_arms);
            if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) level += 1;
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) {
                if (level == 0) break;
                level -= 1;
            }
            if (level == 0 and kind == .comma) {
                if (items + 1 == bounds.len) return self.fail(keyword.span, .case_arms);
                bounds[items] = close + 1;
                items += 1;
            }
        }
        if (close >= self.token_count or self.tokens[close].kind != @as(Token.Kind, if (failing) .right_bracket else .right_paren)) return self.fail(keyword.span, .case_arms);
        bounds[items] = close + 1;
        if (items < 2) return self.fail(keyword.span, .case_arms);
        if (!self.classicCase(bounds[0 .. items + 1])) return self.rewritePatternCase(rw, at, depth, bounds[0 .. items + 1], failing);
        // The scrutinee: identifiers separated by dots.
        const scrutinee_range = self.trimmed(bounds[0], bounds[1] - 1);
        const scrutinee = self.tokens[scrutinee_range[0]..scrutinee_range[1]];
        if (scrutinee.len == 0 or scrutinee.len % 2 == 0) return self.fail(keyword.span, .case_scrutinee);
        for (scrutinee, 0..) |token, index| {
            if (token.kind != (if (index % 2 == 0) Token.Kind.identifier else Token.Kind.dot)) return self.fail(token.span, .case_scrutinee);
        }
        const arms = items - 1;
        const wrapper = Token{ .kind = .left_paren, .span = keyword.span };
        try self.emitTo(rw, wrapper);
        var default_value: [2]usize = .{ 0, 0 };
        for (1..items) |item| {
            const range = self.trimmed(bounds[item], bounds[item + 1] - 1);
            const split = try self.caseArrow(range);
            const pattern = self.trimmed(range[0], split);
            const value = self.trimmed(split + 1, range[1]);
            if (pattern[0] == pattern[1]) return self.fail(self.tokens[split].span, .case_arms);
            if (value[0] == value[1]) return self.fail(self.tokens[split].span, .case_arms);
            const is_default = pattern[1] == pattern[0] + 1 and self.isName(pattern[0], "_");
            if (is_default and item + 1 != items) return self.fail(self.tokens[pattern[0]].span, .case_arms);
            if (is_default) {
                if (failing) return self.fail(self.tokens[pattern[0]].span, .case_cannot_fail);
                default_value = value;
                continue;
            }
            for (self.tokens[pattern[0]..pattern[1]]) |token| switch (token.kind) {
                .identifier, .integer, .floating, .string, .escaped_string, .character, .dot, .plus, .minus, .star, .slash => {},
                else => return self.fail(token.span, .case_pattern),
            };
            try self.checkReachable(bounds[0 .. items + 1], item, pattern);
            if (item + 1 == items and !failing) {
                // No default: the last arm needs no test once the compiler has seen that the
                // patterns are all the cases of the scrutinee's enum.
                try self.emitTo(rw, .{ .kind = .synthetic_exhaustive, .span = keyword.span });
                try self.emitTo(rw, .{ .kind = .left_paren, .span = keyword.span });
                for (scrutinee) |token| try self.emitTo(rw, token);
                for (1..items) |listed| {
                    const other = self.trimmed(bounds[listed], bounds[listed + 1] - 1);
                    const arrow = try self.caseArrow(other);
                    const tokens = self.trimmed(other[0], arrow);
                    try self.emitTo(rw, .{ .kind = .comma, .span = self.tokens[arrow].span });
                    try self.emitTo(rw, .{ .kind = .left_paren, .span = self.tokens[tokens[0]].span });
                    for (self.tokens[tokens[0]..tokens[1]]) |token| try self.emitTo(rw, token);
                    try self.emitTo(rw, .{ .kind = .right_paren, .span = self.tokens[arrow].span });
                }
                try self.emitTo(rw, .{ .kind = .comma, .span = self.tokens[split].span });
                try self.streamCases(rw, value[0], value[1], depth + 1);
                try self.emitTo(rw, .{ .kind = .right_paren, .span = keyword.span });
                break;
            }
            try self.emitTo(rw, .{ .kind = .synthetic_if, .span = keyword.span });
            try self.emitTo(rw, .{ .kind = .left_paren, .span = keyword.span });
            for (scrutinee) |token| try self.emitTo(rw, token);
            try self.emitTo(rw, .{ .kind = .synthetic_case_equal, .span = self.tokens[split].span });
            try self.emitTo(rw, .{ .kind = .left_paren, .span = self.tokens[pattern[0]].span });
            for (self.tokens[pattern[0]..pattern[1]]) |token| try self.emitTo(rw, token);
            try self.emitTo(rw, .{ .kind = .right_paren, .span = self.tokens[split].span });
            try self.emitTo(rw, .{ .kind = .comma, .span = self.tokens[split].span });
            try self.streamCases(rw, value[0], value[1], depth + 1);
            try self.emitTo(rw, .{ .kind = .comma, .span = self.tokens[value[1] - 1].span });
        }
        if (default_value[0] != default_value[1]) try self.streamCases(rw, default_value[0], default_value[1], depth + 1);
        if (failing) {
            // No arm took the scrutinee: `Fail[]`, and one more `If` to close than a total
            // `Case` has, whose last arm is its else.
            try self.emitTo(rw, .{ .kind = .synthetic_fail, .span = keyword.span });
            try self.emitTo(rw, .{ .kind = .right_paren, .span = keyword.span });
        }
        for (0..arms - 1) |_| try self.emitTo(rw, .{ .kind = .right_paren, .span = keyword.span });
        try self.emitTo(rw, .{ .kind = .right_paren, .span = keyword.span });
        return close + 1;
    }

    /// Whether the `Case` whose scrutinee and arms lie between `bounds` is the constant-pattern
    /// form of RFC-0050: a name path compared with effect-free constants. Its lowering repeats
    /// the scrutinee and must not change; every other `Case` binds the scrutinee once (RFC-0066).
    fn classicCase(self: *const Workspace, bounds: []const usize) bool {
        const scrutinee = self.trimmed(bounds[0], bounds[1] - 1);
        // An empty scrutinee is the old diagnostic.
        for (self.tokens[scrutinee[0]..scrutinee[1]], 0..) |token, index| {
            if (token.kind != (if (index % 2 == 0) Token.Kind.identifier else Token.Kind.dot)) return false;
        }
        if ((scrutinee[1] - scrutinee[0]) % 2 == 0 and scrutinee[1] != scrutinee[0]) return false;
        for (1..bounds.len - 1) |item| {
            const first = self.trimmed(bounds[item], bounds[item + 1] - 1)[0];
            for (bounds[item]..bounds[item + 1] - 1) |index| {
                const kind = self.tokens[index].kind;
                // Up to the arrow; a bracket is not a classic token, so none is open there.
                if (kind == .arrow) break;
                switch (kind) {
                    // After a pattern `where` starts a guard; first in the arm it is a value of that name.
                    .identifier => if (index != first and self.isName(index, "where")) return false,
                    .integer, .floating, .string, .escaped_string, .character, .dot, .plus, .minus, .star, .slash, .newline => {},
                    else => return false,
                }
            }
        }
        return true;
    }

    /// How deep the shapes of one pattern nest (`option{tuple{X,_}}` is two).
    const max_pattern_depth = 8;

    /// One step from the scrutinee to the part a sub-pattern matches.
    const PatternStep = union(enum) {
        /// The value of an option known to hold one.
        payload,
        element: struct { index: u32, last: u32 },
        /// Field `name` of the value narrowed to the type in token range `class`.
        field: struct { class: [2]usize, name: Token },
    };
    const PatternPath = struct { steps: [max_pattern_depth]PatternStep = undefined, count: usize = 0 };
    const PatternKind = enum { wildcard, binder, typed, none, some, tuple, record, constant };

    /// One pass over a pattern. `count` sizes it, `tests` emits its conditions in order and
    /// `binds` the statements that bind its names. In a `total` arm nothing is tested: the
    /// compiler checks instead that every narrowing is one the static types already grant.
    const PatternWalk = struct {
        rw: *Rewrite,
        site: Site,
        mode: enum { count, tests, binds, pack, unpack },
        total: bool = false,
        tests: usize = 0,
        binds: usize = 0,
        /// Statements of `binds` that bind a name; `pack` and `unpack` emit one item for each.
        names: usize = 0,
        /// In `unpack` mode: how many names the carrier holds (two or more travel as a tuple).
        carried: usize = 0,
        /// In `tests` mode: how many leading tests open an `If(test,` that the caller closes.
        chained: usize = 0,
        /// The pattern being walked: where the nodes of its forms point.
        span: Span = .{ .start = 0, .end = 0 },
    };

    /// The parts of one arm: `Pattern => Value` or `Pattern where Guard => Value`.
    const CaseArm = struct { pattern: [2]usize, guard: ?[2]usize, value: [2]usize, arrow: usize };

    fn caseArm(self: *Workspace, from: usize, to: usize) ParseError!CaseArm {
        const range = self.trimmed(from, to);
        if (range[0] == range[1]) return self.fail(self.tokens[from].span, .case_arms);
        const arrow = try self.caseArrow(range);
        var pattern = self.trimmed(range[0], arrow);
        const value = self.trimmed(arrow + 1, range[1]);
        var guard: ?[2]usize = null;
        var inner: usize = 0;
        for (pattern[0]..pattern[1]) |index| {
            const kind = self.tokens[index].kind;
            if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) inner += 1;
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) inner -|= 1;
            // `where` after a pattern starts the guard; first, it is a value of that name.
            if (inner != 0 or index == pattern[0] or !self.isName(index, "where")) continue;
            guard = self.trimmed(index + 1, pattern[1]);
            pattern = self.trimmed(pattern[0], index);
            if (guard.?[0] == guard.?[1]) return self.fail(self.tokens[index].span, .case_arms);
            break;
        }
        if (pattern[0] == pattern[1] or value[0] == value[1]) return self.fail(self.tokens[arrow].span, .case_arms);
        return .{ .pattern = pattern, .guard = guard, .value = value, .arrow = arrow };
    }

    /// The `{` of a pattern that ends in `}`: the one that brace closes, after a type name.
    fn patternBrace(self: *Workspace, range: [2]usize) ParseError!usize {
        var open = range[0];
        while (open < range[1] and self.tokens[open].kind != .left_brace) open += 1;
        if (open == range[0] or open == range[1] or self.segmentClose(open) != range[1] - 1) return self.fail(self.tokens[range[0]].span, .case_pattern);
        for (self.tokens[range[0]..open], 0..) |token, index| {
            if (token.kind != (if (index % 2 == 0) Token.Kind.identifier else Token.Kind.dot)) return self.fail(token.span, .case_pattern);
        }
        if ((open - range[0]) % 2 == 0) return self.fail(self.tokens[open].span, .case_pattern);
        return open;
    }

    /// What the pattern in `range` is. A lone name binds inside a shape; at the top of an arm it
    /// is the constant of RFC-0050, as are literals, dotted names and arithmetic anywhere.
    fn patternKind(self: *Workspace, range: [2]usize, nested: bool) ParseError!PatternKind {
        std.debug.assert(range[0] < range[1]);
        const first = self.tokens[range[0]];
        if (range[1] == range[0] + 1 and first.kind == .identifier) {
            if (self.isName(range[0], "_")) return .wildcard;
            if (nested and !reserved(first.span.text(self.source))) return .binder;
        }
        if (range[1] >= range[0] + 3 and first.kind == .identifier and self.tokens[range[0] + 1].kind == .colon) {
            for (self.tokens[range[0] + 2 .. range[1]]) |token| switch (token.kind) {
                .identifier, .dot, .left_paren, .right_paren, .left_bracket, .right_bracket, .comma, .less, .greater => {},
                else => return self.fail(token.span, .case_pattern),
            };
            return .typed;
        }
        if (self.tokens[range[1] - 1].kind == .right_brace) {
            const open = try self.patternBrace(range);
            if (open != range[0] + 1) return .record;
            const empty = self.trimmed(open + 1, range[1] - 1);
            if (self.isName(range[0], "option")) return if (empty[0] == empty[1]) .none else .some;
            if (self.isName(range[0], "tuple")) return .tuple;
            if (reserved(first.span.text(self.source))) return self.fail(first.span, .case_pattern);
            return .record;
        }
        for (self.tokens[range[0]..range[1]]) |token| switch (token.kind) {
            .identifier, .integer, .floating, .string, .escaped_string, .character, .dot, .plus, .minus, .star, .slash => {},
            else => return self.fail(token.span, .case_pattern),
        };
        return .constant;
    }

    /// The end of the part that starts at `from` in a brace list ending at `end`: the next
    /// comma outside brackets, or `end`.
    fn patternPartEnd(self: *const Workspace, from: usize, end: usize) usize {
        var inner: usize = 0;
        for (from..end) |index| {
            const kind = self.tokens[index].kind;
            if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) inner += 1;
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) inner -|= 1;
            if (inner == 0 and kind == .comma) return index;
        }
        return end;
    }

    /// The sub-pattern of record part `range`, which reads `Field := pattern`.
    fn fieldPattern(self: *Workspace, range: [2]usize) ParseError![2]usize {
        if (range[1] < range[0] + 4) return self.fail(self.tokens[range[0]].span, .case_pattern);
        const colon = self.tokens[range[0] + 1];
        if (self.tokens[range[0]].kind != .identifier or colon.kind != .colon or self.tokens[range[0] + 2].kind != .equal or colon.span.end != self.tokens[range[0] + 2].span.start) return self.fail(self.tokens[range[0]].span, .case_pattern);
        return self.trimmed(range[0] + 3, range[1]);
    }

    /// Whether the pattern matches every value of its type, as far as tokens show. Narrowing
    /// patterns (`X:T`, `T{...}`) count only with `typed`: the arm is then lowered `total`, and
    /// the compiler proves each narrowing from the static types.
    fn irrefutable(self: *Workspace, range: [2]usize, nested: bool, typed: bool, depth: usize) ParseError!bool {
        switch (try self.patternKind(range, nested)) {
            .wildcard, .binder => return true,
            .typed => return typed,
            .none, .some, .constant => return false,
            .tuple, .record => |kind| {
                // The same bound as `walkPattern`: a shape may sit inside `max_pattern_depth - 1` others.
                if (depth == max_pattern_depth) return self.fail(self.tokens[range[0]].span, .expression_limit);
                if (kind == .record and !typed) return false;
                const open = try self.patternBrace(range);
                var from = open + 1;
                if (kind == .tuple and self.trimmed(from, range[1] - 1)[0] == range[1] - 1) return self.fail(self.tokens[open].span, .case_pattern);
                while (from < range[1] - 1) {
                    const end = self.patternPartEnd(from, range[1] - 1);
                    var part = self.trimmed(from, end);
                    from = end + 1;
                    if (part[0] == part[1]) return self.fail(self.tokens[open].span, .case_pattern);
                    if (kind == .record) part = try self.fieldPattern(part);
                    if (!try self.irrefutable(part, true, typed, depth + 1)) return false;
                }
                return true;
            },
        }
    }

    fn caseWord(self: *Workspace, site: Site, word: macros.CaseWord) Token {
        return self.libraryToken(site, .case_words, @backingInt(word));
    }

    fn emitKind(self: *Workspace, rw: *Rewrite, kind: Token.Kind, span: Span) ParseError!void {
        try self.emitTo(rw, .{ .kind = kind, .span = span });
    }

    /// Emits the expression that reads the part of the scrutinee at `path`. Every form in it is
    /// compiler-only and adds no check at run time; see `Parser.emitPatternForm`.
    fn emitPatternAccess(self: *Workspace, walk: *PatternWalk, path: *const PatternPath) ParseError!void {
        const here = walk.site.keyword.span;
        var index = path.count;
        while (index != 0) {
            index -= 1;
            switch (path.steps[index]) {
                .payload => try self.emitTo(walk.rw, self.caseWord(walk.site, .value)),
                .element => |element| {
                    try self.emitTo(walk.rw, self.caseWord(walk.site, .tuple));
                    try self.emitKind(walk.rw, .left_paren, here);
                    try self.emitTo(walk.rw, self.numeralToken(walk.site, element.last));
                    try self.emitKind(walk.rw, .comma, here);
                    continue;
                },
                .field => |field| {
                    try self.emitTo(walk.rw, self.caseWord(walk.site, if (walk.total) .all else .as));
                    try self.emitKind(walk.rw, .left_paren, here);
                    for (self.tokens[field.class[0]..field.class[1]]) |token| try self.emitTo(walk.rw, token);
                    try self.emitKind(walk.rw, .comma, here);
                    continue;
                },
            }
            try self.emitKind(walk.rw, .left_paren, here);
        }
        try self.emitTo(walk.rw, self.caseWord(walk.site, .scrutinee));
        for (path.steps[0..path.count]) |step| {
            try self.emitKind(walk.rw, .right_paren, here);
            switch (step) {
                .payload => {},
                .element => |element| {
                    try self.emitKind(walk.rw, .left_paren, here);
                    try self.emitTo(walk.rw, self.numeralToken(walk.site, element.index));
                    try self.emitKind(walk.rw, .right_paren, here);
                },
                .field => |field| {
                    try self.emitKind(walk.rw, .dot, field.name.span);
                    try self.emitTo(walk.rw, field.name);
                },
            }
        }
    }

    /// `Form(Type, part)` or `Form(part)`.
    fn emitPatternForm(self: *Workspace, walk: *PatternWalk, word: macros.CaseWord, class: ?[2]usize, path: *const PatternPath) ParseError!void {
        const here = walk.site.keyword.span;
        try self.emitTo(walk.rw, self.caseWord(walk.site, word));
        // The parser takes the span of a form from its parenthesis: the word is library text.
        try self.emitKind(walk.rw, .left_paren, walk.span);
        if (class) |range| {
            for (self.tokens[range[0]..range[1]]) |token| try self.emitTo(walk.rw, token);
            try self.emitKind(walk.rw, .comma, here);
        }
        try self.emitPatternAccess(walk, path);
        try self.emitKind(walk.rw, .right_paren, here);
    }

    /// One condition of a pattern: a form, or `part == (constant)`.
    fn patternTest(self: *Workspace, walk: *PatternWalk, word: ?macros.CaseWord, tokens: ?[2]usize, path: *const PatternPath) ParseError!void {
        std.debug.assert(!walk.total);
        defer walk.tests += 1;
        if (walk.mode != .tests) return;
        const here = walk.site.keyword.span;
        const chained = walk.tests < walk.chained;
        if (chained) {
            try self.emitKind(walk.rw, .synthetic_if, here);
            try self.emitKind(walk.rw, .left_paren, here);
        }
        if (word) |form| try self.emitPatternForm(walk, form, tokens, path) else {
            const constant = tokens.?;
            try self.emitPatternAccess(walk, path);
            // A constant arm is the Book's `case`, whose scrutinee has one of its types (RFC-0090);
            // a constant inside a shape is the extension's, and compares as `==` does.
            try self.emitKind(walk.rw, if (path.count == 0) .synthetic_case_equal else .equal_equal, self.tokens[constant[0]].span);
            try self.emitKind(walk.rw, .left_paren, self.tokens[constant[0]].span);
            for (self.tokens[constant[0]..constant[1]]) |token| try self.emitTo(walk.rw, token);
            try self.emitKind(walk.rw, .right_paren, self.tokens[constant[1] - 1].span);
        }
        if (chained) try self.emitKind(walk.rw, .comma, here);
    }

    /// One statement of an arm's block: `Name := part;`, narrowed with `word` when given, or
    /// the bare form, which only makes the compiler check it.
    fn patternBind(self: *Workspace, walk: *PatternWalk, name: ?Token, word: ?macros.CaseWord, class: ?[2]usize, path: *const PatternPath) ParseError!void {
        defer walk.binds += 1;
        defer walk.names += @intFromBool(name != null);
        if (walk.mode == .pack or walk.mode == .unpack) return self.patternCarry(walk, name orelse return);
        if (walk.mode != .binds) return;
        if (name) |token| {
            // `:=` is a colon and an equal sign that touch.
            const here = zeroWidth(token.span.end);
            try self.emitTo(walk.rw, token);
            try self.emitKind(walk.rw, .colon, here);
            try self.emitKind(walk.rw, .equal, here);
        }
        if (word) |form| try self.emitPatternForm(walk, form, class, path) else try self.emitPatternAccess(walk, path);
        try self.emitKind(walk.rw, .separator, walk.site.keyword.span);
    }

    /// A bound name on its way through the carrier of an effectful guard: `Name` as an element
    /// of what the guard's attempt yields, or `Name := element;` in the value's block.
    fn patternCarry(self: *Workspace, walk: *PatternWalk, name: Token) ParseError!void {
        const here = zeroWidth(name.span.end);
        if (walk.mode == .pack) {
            if (walk.names != 0) try self.emitKind(walk.rw, .comma, here);
            return self.emitTo(walk.rw, name);
        }
        try self.emitTo(walk.rw, name);
        try self.emitKind(walk.rw, .colon, here);
        try self.emitKind(walk.rw, .equal, here);
        try self.emitTo(walk.rw, self.caseWord(walk.site, .value));
        try self.emitKind(walk.rw, .left_paren, name.span);
        try self.emitTo(walk.rw, self.caseWord(walk.site, .carrier));
        try self.emitKind(walk.rw, .right_paren, here);
        if (walk.carried > 1) {
            try self.emitKind(walk.rw, .left_paren, here);
            try self.emitTo(walk.rw, self.numeralToken(walk.site, walk.names));
            try self.emitKind(walk.rw, .right_paren, here);
        }
        try self.emitKind(walk.rw, .separator, walk.site.keyword.span);
    }

    fn walkPattern(self: *Workspace, walk: *PatternWalk, range: [2]usize, path: *PatternPath, nested: bool) ParseError!void {
        const kind = try self.patternKind(range, nested);
        const narrow: macros.CaseWord = if (walk.total) .all else .as;
        const span: Span = .{ .start = self.tokens[range[0]].span.start, .end = self.tokens[range[1] - 1].span.end };
        walk.span = span;
        switch (kind) {
            .wildcard => {},
            .binder => try self.patternBind(walk, self.tokens[range[0]], null, null, path),
            .typed => {
                const class: [2]usize = .{ range[0] + 2, range[1] };
                if (!walk.total) try self.patternTest(walk, .is, class, path);
                const named = !self.isName(range[0], "_");
                // A total arm checks even a narrowing it does not bind.
                if (named or walk.total) try self.patternBind(walk, if (named) self.tokens[range[0]] else null, narrow, class, path);
            },
            .none => if (!walk.total) try self.patternTest(walk, .none, null, path),
            .constant => try self.patternTest(walk, null, range, path),
            .some, .tuple, .record => {
                const open = try self.patternBrace(range);
                const class: [2]usize = .{ range[0], open };
                if (kind == .some and !walk.total) try self.patternTest(walk, .some, null, path);
                if (kind == .record and !walk.total) try self.patternTest(walk, .is, class, path);
                if (kind == .record and walk.total) try self.patternBind(walk, null, .all, class, path);
                if (path.count == max_pattern_depth) return self.fail(self.tokens[range[0]].span, .expression_limit);
                // Count the parts first: a tuple's accessor names its last position.
                var parts: u32 = 0;
                var from = open + 1;
                while (from < range[1] - 1) : (parts += 1) from = self.patternPartEnd(from, range[1] - 1) + 1;
                if (kind == .some and parts != 1) return self.fail(self.tokens[open].span, .case_pattern);
                if (kind == .tuple) {
                    if (parts == 0) return self.fail(self.tokens[open].span, .case_pattern);
                    if (parts > types.limits.tuple_arity) return self.fail(self.tokens[open].span, .tuple_limit);
                    try self.requireNumerals(walk.site, parts);
                }
                const binds_before = walk.binds;
                var part_index: u32 = 0;
                from = open + 1;
                while (from < range[1] - 1) : (part_index += 1) {
                    const end = self.patternPartEnd(from, range[1] - 1);
                    var part = self.trimmed(from, end);
                    if (part[0] == part[1]) return self.fail(self.tokens[open].span, .case_pattern);
                    path.steps[path.count] = switch (kind) {
                        .some => .payload,
                        .tuple => .{ .element = .{ .index = part_index, .last = parts - 1 } },
                        else => .{ .field = .{ .class = class, .name = self.tokens[part[0]] } },
                    };
                    if (kind == .record) part = try self.fieldPattern(part);
                    path.count += 1;
                    try self.walkPattern(walk, part, path, true);
                    path.count -= 1;
                    from = end + 1;
                }
                // The arity of a tuple is checked where an element is read; a pattern whose
                // block reads none states it alone.
                walk.span = span;
                if (kind == .tuple and walk.binds == binds_before) {
                    path.steps[path.count] = .{ .element = .{ .index = 0, .last = parts - 1 } };
                    path.count += 1;
                    try self.patternBind(walk, null, null, null, path);
                    path.count -= 1;
                }
            },
        }
    }

    /// The value of an arm, inside a block that binds the pattern's names when it has any:
    /// from the scrutinee, or from the carrier when an effectful guard bound them already.
    fn emitArmValue(self: *Workspace, walk: *PatternWalk, arm: CaseArm, binds: usize, carried: usize, depth: usize) ParseError!void {
        const here = walk.site.keyword.span;
        if (binds != 0) {
            try self.emitTo(walk.rw, self.caseWord(walk.site, .block));
            try self.emitKind(walk.rw, .left_brace, here);
            var path: PatternPath = .{};
            walk.mode = if (carried != 0) .unpack else .binds;
            walk.carried = carried;
            walk.binds = 0;
            walk.names = 0;
            try self.walkPattern(walk, arm.pattern, &path, false);
            std.debug.assert(walk.binds == binds);
        }
        try self.streamCases(walk.rw, arm.value[0], arm.value[1], depth + 1);
        if (binds != 0) try self.emitKind(walk.rw, .right_brace, here);
    }

    /// Whether a guard is free of brackets, calls and `?`: it then cannot write state or fail
    /// (it can still stop the run, as a division by zero does anywhere).
    fn plainGuard(self: *const Workspace, guard: [2]usize) bool {
        for (self.tokens[guard[0]..guard[1]]) |token| switch (token.kind) {
            .left_paren, .left_bracket, .left_brace, .question, .synthetic_interpolate => return false,
            else => {},
        };
        return true;
    }

    /// `option{}`: what a carrier holds when its arm was not selected.
    fn emitEmptyCarrier(self: *Workspace, walk: *PatternWalk) ParseError!void {
        const here = walk.site.keyword.span;
        // An aggregate spans from its word to its closing brace, so the brace sits at the word.
        const word = self.caseWord(walk.site, .option_word);
        try self.emitTo(walk.rw, word);
        try self.emitKind(walk.rw, .left_brace, here);
        try self.emitKind(walk.rw, .right_brace, word.span);
    }

    /// The guard of an arm as the innermost condition, with the pattern's names bound around it.
    ///
    /// A plain guard cannot write, so the value block may read the same parts again. Any other
    /// guard runs in its own attempt: one that does not hold leaves nothing behind, and one that
    /// holds keeps its writes. Those writes may reach what the pattern read (a `var` field of an
    /// instance), so when the arm binds names (`carried` of them) the attempt yields their values
    /// as `option{tuple{...}}` and the value block takes them from there: each part is read once,
    /// before the guard runs.
    fn emitArmGuard(self: *Workspace, walk: *PatternWalk, arm: CaseArm, binds: usize, carried: usize, depth: usize) ParseError!void {
        const here = walk.site.keyword.span;
        const guard = arm.guard.?;
        const plain = self.plainGuard(guard);
        std.debug.assert(!plain or carried == 0);
        if (plain and binds == 0) return self.streamCases(walk.rw, guard[0], guard[1], depth + 1);
        if (!plain) {
            try self.emitKind(walk.rw, .synthetic_attempt, here);
            try self.emitKind(walk.rw, .left_paren, here);
        }
        try self.emitTo(walk.rw, self.caseWord(walk.site, .block));
        try self.emitKind(walk.rw, .left_brace, here);
        var path: PatternPath = .{};
        walk.mode = .binds;
        walk.binds = 0;
        walk.names = 0;
        try self.walkPattern(walk, arm.pattern, &path, false);
        std.debug.assert(walk.binds == binds);
        if (plain) {
            try self.streamCases(walk.rw, guard[0], guard[1], depth + 1);
            return self.emitKind(walk.rw, .right_brace, here);
        }
        // A failure of the requirement is reported at the guard. Without a carrier it is the
        // block's value: `true` when the guard holds.
        try self.emitKind(walk.rw, .synthetic_require, .{ .start = self.tokens[guard[0]].span.start, .end = self.tokens[guard[1] - 1].span.end });
        try self.emitKind(walk.rw, .left_bracket, here);
        try self.emitKind(walk.rw, .left_paren, here);
        try self.streamCases(walk.rw, guard[0], guard[1], depth + 1);
        try self.emitKind(walk.rw, .right_paren, here);
        try self.emitKind(walk.rw, .right_bracket, here);
        if (carried != 0) {
            try self.emitKind(walk.rw, .separator, here);
            const option_word = self.caseWord(walk.site, .option_word);
            const tuple_word = self.caseWord(walk.site, .tuple_word);
            try self.emitTo(walk.rw, option_word);
            try self.emitKind(walk.rw, .left_brace, here);
            if (carried > 1) {
                try self.emitTo(walk.rw, tuple_word);
                try self.emitKind(walk.rw, .left_brace, here);
            }
            walk.mode = .pack;
            walk.binds = 0;
            walk.names = 0;
            try self.walkPattern(walk, arm.pattern, &path, false);
            std.debug.assert(walk.names == carried);
            // As in `emitEmptyCarrier`: each closing brace sits at its aggregate's word.
            if (carried > 1) try self.emitKind(walk.rw, .right_brace, tuple_word.span);
            try self.emitKind(walk.rw, .right_brace, option_word.span);
        }
        try self.emitKind(walk.rw, .right_brace, here);
        try self.emitKind(walk.rw, .comma, here);
        if (carried != 0) try self.emitEmptyCarrier(walk) else try self.emitKind(walk.rw, .synthetic_false, here);
        try self.emitKind(walk.rw, .right_paren, here);
    }

    /// Whether the last arm completes a `Case` without a default by the option rule: it is
    /// `option{}` after an unguarded `option{part}` that takes any value, or the reverse.
    fn optionComplete(self: *Workspace, bounds: []const usize, last: CaseArm) ParseError!bool {
        const kind = try self.patternKind(last.pattern, false);
        if (kind != .none and kind != .some) return false;
        if (kind == .some) {
            const inner = self.trimmed(last.pattern[0] + 2, last.pattern[1] - 1);
            if (!try self.irrefutable(inner, true, true, 1)) return false;
        }
        for (1..bounds.len - 2) |item| {
            const arm = try self.caseArm(bounds[item], bounds[item + 1] - 1);
            if (arm.guard != null) continue;
            const other = try self.patternKind(arm.pattern, false);
            if (kind == .some and other == .none) return true;
            if (kind != .none or other != .some) continue;
            const inner = self.trimmed(arm.pattern[0] + 2, arm.pattern[1] - 1);
            if (try self.irrefutable(inner, true, false, 1)) return true;
        }
        return false;
    }

    /// A `Case` with a pattern that binds, a guard, or a scrutinee that is not a name path
    /// (RFC-0066). The scrutinee is evaluated once into a temporary of the module's library
    /// block, and each arm becomes one `If` in the else position of the one before:
    ///
    ///     (Block{__case_s:=(Scrutinee); If(If(Test1, Test2, false), Block{X:=Part; Value}, ...)})
    ///
    /// Tests and parts are compiler-only forms over the temporary. The temporary never changes,
    /// but a part may be read through an instance it refers to, so a part is read again only
    /// where nothing can have run since its test: tests and plain guards write nothing. An arm
    /// whose guard may write binds its names once, inside the guard's attempt, and carries them:
    ///
    ///     Block{__case_r:=If(Test, Attempt(Block{X:=Part; Require[(Guard)]; option{X}}, option{}), option{});
    ///           If(__case_some(__case_r), Block{X:=__case_value(__case_r); Value}, ...)}
    fn rewritePatternCase(self: *Workspace, rw: *Rewrite, at: usize, depth: usize, bounds: []const usize, failing: bool) ParseError!usize {
        const keyword = self.tokens[at];
        const here = keyword.span;
        const close = bounds[bounds.len - 1] - 1;
        const scrutinee = self.trimmed(bounds[0], bounds[1] - 1);
        if (scrutinee[0] == scrutinee[1]) return self.fail(here, .case_scrutinee);
        // Only a module with a pattern `Case` carries its words; one without a block yet asks
        // for both at once.
        const words: macros.Extension = .{ .cases = true };
        if (!self.has_library) {
            self.library_wanted = words;
            return self.fail(here, .macro_unavailable);
        }
        try self.lexLibrary();
        const site = self.siteFor(keyword) catch |failure| {
            self.library_wanted = words;
            return failure;
        };
        if (!site.extension.cases) return self.requestExtension(site, words);
        try self.noteFailingCase(here);
        var walk: PatternWalk = .{ .rw = rw, .site = site, .mode = .count };
        try self.emitKind(rw, .left_paren, here);
        try self.emitTo(rw, self.caseWord(site, .block));
        try self.emitKind(rw, .left_brace, here);
        try self.emitTo(rw, self.caseWord(site, .scrutinee));
        try self.emitKind(rw, .colon, zeroWidth(here.start));
        try self.emitKind(rw, .equal, zeroWidth(here.start));
        try self.emitKind(rw, .left_paren, here);
        try self.streamCases(rw, scrutinee[0], scrutinee[1], depth + 1);
        try self.emitKind(rw, .right_paren, here);
        try self.emitKind(rw, .separator, here);
        const arms = bounds.len - 2;
        // Which arms opened a carrier block around their `If`, to close them innermost first.
        var carriers: std.StaticBitSet(types.limits.record_fields + 3) = .empty;
        var opened: usize = 0;
        for (1..arms + 1) |item| {
            const arm = try self.caseArm(bounds[item], bounds[item + 1] - 1);
            const is_last = item == arms;
            var path: PatternPath = .{};
            walk.mode = .count;
            walk.total = false;
            walk.tests = 0;
            walk.binds = 0;
            walk.names = 0;
            try self.checkReachable(bounds, item, arm.pattern);
            if (arm.guard == null and try self.irrefutable(arm.pattern, false, false, 0)) {
                // A default, with or without names: nothing after it could be selected.
                if (!is_last) return self.fail(self.tokens[arm.pattern[0]].span, .case_arms);
                // And with it the `Case[...]` could not fail.
                if (failing) return self.fail(self.tokens[arm.pattern[0]].span, .case_cannot_fail);
                walk.total = true;
            } else if (is_last and !failing) {
                // No default. The last arm is not tested, so it must be shown to match.
                if (arm.guard != null) return self.fail(here, .case_not_exhaustive);
                if (try self.patternKind(arm.pattern, false) == .constant) {
                    try self.emitEnumCheck(rw, site, bounds, arm, depth);
                    break;
                }
                if (!try self.optionComplete(bounds, arm) and !try self.irrefutable(arm.pattern, false, true, 0)) return self.fail(here, .case_not_exhaustive);
                walk.total = true;
            }
            // An arm that takes every value its type tests let through is known only to the parser.
            // RFC-0090: `Case(...)` records them too, for the arms they leave unreachable
            // (`subsumed_arm`); only `Case[...]` asks whether one takes every value.
            if (arm.guard == null and try self.irrefutable(arm.pattern, false, true, 0)) try self.noteFailingArm(here.start, arm.pattern);
            try self.walkPattern(&walk, arm.pattern, &path, false);
            std.debug.assert(path.count == 0);
            const tests = walk.tests;
            const binds = walk.binds;
            if (walk.total) {
                std.debug.assert(tests == 0 and is_last);
                try self.emitArmValue(&walk, arm, binds, 0, depth);
                break;
            }
            std.debug.assert(tests != 0 or arm.guard != null);
            // The names travel as one tuple when a guard that may write binds them.
            const carried = if (arm.guard != null and !self.plainGuard(arm.guard.?)) walk.names else 0;
            if (carried > types.limits.tuple_arity) return self.fail(self.tokens[arm.pattern[0]].span, .tuple_limit);
            if (carried > 1) try self.requireNumerals(site, carried);
            if (carried != 0) {
                carriers.set(opened);
                try self.emitTo(rw, self.caseWord(site, .block));
                try self.emitKind(rw, .left_brace, here);
                try self.emitTo(rw, self.caseWord(site, .carrier));
                try self.emitKind(rw, .colon, zeroWidth(here.start));
                try self.emitKind(rw, .equal, zeroWidth(here.start));
            } else {
                try self.emitKind(rw, .synthetic_if, here);
                try self.emitKind(rw, .left_paren, here);
            }
            walk.mode = .tests;
            walk.tests = 0;
            walk.chained = if (arm.guard != null) tests else tests - 1;
            try self.walkPattern(&walk, arm.pattern, &path, false);
            std.debug.assert(walk.tests == tests);
            if (arm.guard != null) try self.emitArmGuard(&walk, arm, binds, carried, depth);
            for (0..walk.chained) |_| {
                try self.emitKind(rw, .comma, here);
                if (carried != 0) try self.emitEmptyCarrier(&walk) else try self.emitKind(rw, .synthetic_false, here);
                try self.emitKind(rw, .right_paren, here);
            }
            if (carried != 0) {
                try self.emitKind(rw, .separator, here);
                try self.emitKind(rw, .synthetic_if, here);
                try self.emitKind(rw, .left_paren, here);
                try self.emitTo(rw, self.caseWord(site, .some));
                try self.emitKind(rw, .left_paren, here);
                try self.emitTo(rw, self.caseWord(site, .carrier));
                try self.emitKind(rw, .right_paren, here);
            }
            opened += 1;
            try self.emitKind(rw, .comma, self.tokens[arm.arrow].span);
            try self.emitArmValue(&walk, arm, binds, carried, depth);
            try self.emitKind(rw, .comma, self.tokens[arm.value[1] - 1].span);
        }
        if (failing) {
            // The else of the last arm (RFC-0080): no arm took the scrutinee.
            try self.emitKind(rw, .synthetic_fail, here);
        }
        while (opened != 0) {
            opened -= 1;
            try self.emitKind(rw, .right_paren, here);
            if (carriers.isSet(opened)) try self.emitKind(rw, .right_brace, here);
        }
        try self.emitKind(rw, .right_brace, here);
        try self.emitKind(rw, .right_paren, here);
        return close + 1;
    }

    /// The last arm of a `Case` without a default when it is a constant: the enum rule of
    /// RFC-0050 over the constants of the unguarded arms, any of which selects its own arm.
    fn emitEnumCheck(self: *Workspace, rw: *Rewrite, site: Site, bounds: []const usize, last: CaseArm, depth: usize) ParseError!void {
        const here = site.keyword.span;
        try self.emitKind(rw, .synthetic_exhaustive, here);
        try self.emitKind(rw, .left_paren, here);
        try self.emitTo(rw, self.caseWord(site, .scrutinee));
        for (1..bounds.len - 1) |item| {
            const arm = try self.caseArm(bounds[item], bounds[item + 1] - 1);
            if (arm.guard != null or try self.patternKind(arm.pattern, false) != .constant) continue;
            try self.emitKind(rw, .comma, self.tokens[arm.arrow].span);
            try self.emitKind(rw, .left_paren, self.tokens[arm.pattern[0]].span);
            for (self.tokens[arm.pattern[0]..arm.pattern[1]]) |token| try self.emitTo(rw, token);
            try self.emitKind(rw, .right_paren, self.tokens[arm.arrow].span);
        }
        try self.emitKind(rw, .comma, self.tokens[last.arrow].span);
        try self.streamCases(rw, last.value[0], last.value[1], depth + 1);
        try self.emitKind(rw, .right_paren, here);
    }

    /// Whether the condition starting at `first` needs `Attempt(..., false)` around it, and
    /// the comma that ends it. Only a condition with a bracket (every failable call, index or
    /// conversion uses one) can fail. One with an explicit `Require`/`Fail` says that the
    /// enclosing region should fail, as `If(Require[N>=0], N, Fail["negative"])` does, and
    /// one that is already a single `Attempt(...)` is left alone.
    fn failableCondition(self: *Workspace, first: usize) ParseError!?usize {
        var comma = first;
        var depth: usize = 0;
        // A condition that an earlier compile found to fail without a bracket counts as one
        // with a bracket; what exempts a condition below exempts it too.
        var bracket = self.conditionForced(first);
        while (comma < self.token_count) : (comma += 1) {
            const kind = self.tokens[comma].kind;
            if (kind == .eof) return null;
            if (kind == .left_bracket) bracket = true;
            if (kind == .synthetic_first) {
                // A `First[...]` fails when nothing matches, and catches what fails inside it:
                // its filters are `Require` in generated text, which says nothing about the
                // condition around it.
                bracket = true;
                comma = self.segmentClose(comma + 1);
                continue;
            }
            if (kind == .synthetic_attempt) {
                // The attempt a `Case` guard runs in catches its own failures: nothing inside it
                // says whether the condition around it can fail.
                comma = self.segmentClose(comma + 1);
                continue;
            }
            if (self.isName(comma, "Require") or self.isName(comma, "Fail") or kind == .synthetic_require) return null;
            if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) {
                depth += 1;
                if (depth > types.limits.expression_depth) return self.fail(self.tokens[comma].span, .expression_limit);
            }
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) {
                if (depth == 0) return null;
                depth -= 1;
            }
            if (depth == 0 and kind == .comma) break;
        }
        if (!bracket or comma >= self.token_count or self.tokens[comma].kind != .comma) return null;
        if (self.isName(first, "Attempt") and self.tokens[first + 1].kind == .left_paren) {
            const close = self.segmentClose(first + 1);
            if (close + 1 == comma) return null;
        }
        return comma;
    }

    /// The index of the `)` that matches the `(` at `open`, or the end of input.
    fn segmentClose(self: *const Workspace, open: usize) usize {
        var depth: usize = 0;
        var at = open;
        while (at < self.token_count) : (at += 1) {
            const kind = self.tokens[at].kind;
            if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) depth += 1;
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) {
                depth -= 1;
                if (depth == 0) return at;
            }
            if (kind == .eof) return at;
        }
        return self.token_count - 1;
    }

    /// A failure inside an `If` condition selects the else branch: a failable condition is
    /// rewritten from `If(c, a, b)` to `If(Attempt(c, false), a, b)` with compiler-inserted
    /// tokens. Bracket-free conditions cannot fail and keep their original IR and cost.
    fn desugarFailableConditions(self: *Workspace) ParseError!void {
        var rw: Rewrite = .{};
        var started = false;
        var at: usize = 0;
        while (at + 2 < self.token_count) {
            if (started) try self.settle(&rw, at);
            const keyword = self.tokens[at];
            if ((self.isName(at, "If") or keyword.kind == .synthetic_if) and self.tokens[at + 1].kind == .left_paren) {
                if (try self.failableCondition(at + 2)) |comma| {
                    if (!started) {
                        self.beginRewrite(&rw, at);
                        started = true;
                    }
                    const first = self.tokens[at + 2].span;
                    const here = zeroWidth(self.tokens[comma].span.start);
                    try self.emitTo(&rw, keyword);
                    try self.emitTo(&rw, self.tokens[at + 1]);
                    try self.emitTo(&rw, .{ .kind = .synthetic_attempt, .span = zeroWidth(first.start) });
                    try self.emitTo(&rw, .{ .kind = .left_paren, .span = zeroWidth(first.start) });
                    try self.owe(&rw, comma, &.{
                        .{ .kind = .comma, .span = here },
                        .{ .kind = .synthetic_false, .span = here },
                        .{ .kind = .right_paren, .span = here },
                    });
                    at += 2;
                    continue;
                }
            }
            if (started) try self.emitTo(&rw, keyword);
            at += 1;
        }
        if (started) {
            while (at < self.token_count) : (at += 1) {
                try self.settle(&rw, at);
                try self.emitTo(&rw, self.tokens[at]);
            }
            self.finishRewrite(&rw);
        }
    }

    /// Keeps a diagnostic of the lexer inside the module's own text.
    fn clampToUserText(self: *const Workspace, diagnostic: Diagnostic) Diagnostic {
        const module = self.libraryModule(.{ .start = diagnostic.span.end, .end = diagnostic.span.end }) orelse return diagnostic;
        const base = self.library_base[module];
        var result = diagnostic;
        if (result.span.start > base) result.span.start = base;
        if (result.span.end > base) result.span.end = base;
        return result;
    }

    /// Lexes every macro template once; their spans are relative to the template text.
    fn lexLibrary(self: *Workspace) ParseError!void {
        if (self.library_lexed) return;
        self.library_lexed = true;
        var used: u32 = 0;
        for (0..macros.template_count) |index| {
            const template = macros.templateText(@fromBackingInt(@intCast(index)));
            const lexed_count = switch (lexer.tokenize(template, self.library_tokens[used..])) {
                .failed => return self.fail(.{ .start = 0, .end = 0 }, .token_limit),
                .ok => |lexed| lexed.len - 1,
            };
            self.library_ranges[index] = .{ used, used + @as(u32, @intCast(lexed_count)) };
            used += @intCast(lexed_count);
        }
        switch (lexer.tokenize(macros.exit_words, &self.exit_tokens)) {
            .failed => return self.fail(.{ .start = 0, .end = 0 }, .token_limit),
            .ok => |lexed| std.debug.assert(lexed.len == self.exit_tokens.len),
        }
    }

    fn shifted(_: *const Workspace, token: Token, by: u32) Token {
        return .{ .kind = token.kind, .span = .{ .start = token.span.start + by, .end = token.span.end + by } };
    }

    /// The span an anonymous function specialized from `template` is identified within. A `Fn`
    /// word pooled in a module's library block lies after the module's text, so the span reaches it.
    fn genericSourceFor(self: *const Workspace, template: Span, name: Span) Span {
        const module = self.libraryModule(name) orelse return template;
        return .{ .start = template.start, .end = self.moduleEnd(module) };
    }

    /// Where a module's own text ends: before its library block, if it has one.
    fn userEnd(self: *const Workspace, module: u32) u32 {
        const base = if (self.has_library) self.library_base[module] else 0;
        return if (base != 0) base else self.moduleEnd(module);
    }

    fn moduleEnd(self: *const Workspace, module: u32) u32 {
        return if (self.module_storage.module_count == 0) @intCast(self.source.len) else self.module_storage.modules[module].source.end;
    }

    /// The module whose library block contains `span`, if it lies in one.
    /// RFC-0085, I11: notes that the identifier at `at` resolves to the definition whose name is
    /// at `declared` (`qualify.none` for a built-in), when the host asked for the table and the
    /// author wrote the identifier: text a macro generated is not noted. A position is noted
    /// once; noting it again with another meaning is counted, which a consistent compile never
    /// does.
    fn noteName(self: *Workspace, at: Span, declared: u32, kind: qualify.Kind, owner: u32) void {
        if (!self.qualify) return;
        if (at.start >= at.end or at.end > self.source.len or self.libraryModule(at) != null) return;
        // A local a macro's function carries is named where the author wrote it: what names the
        // carrier names the local.
        var target = declared;
        if (kind == .local and declared < self.source.len) {
            const carrier = self.resolution_at[declared];
            if (carrier < self.resolution_count and self.resolutions[carrier].at == declared and self.resolutions[carrier].kind == .local) target = self.resolutions[carrier].declared;
        }
        const slot = self.resolution_at[at.start];
        if (slot < self.resolution_count and self.resolutions[slot].at == at.start) {
            const known = self.resolutions[slot];
            if (known.kind == .varies) return;
            if (known.declared != target or known.kind != kind or (owner != qualify.none and known.owner != owner)) {
                // The body of a generic function or a parametric type is read once for each
                // specialization, and a name in it may mean something else in each: it has no
                // one qualified form.
                if (self.inTemplate(at.start)) {
                    self.resolutions[slot] = .{ .at = at.start, .kind = .varies };
                    return;
                }
                if (self.resolution_conflicts == 0) self.resolution_conflict = at.start;
                self.resolution_conflicts += 1;
            }
            return;
        }
        // One entry per identifier token, and there are no more of those than tokens.
        std.debug.assert(self.resolution_count < self.resolutions.len);
        self.resolution_at[at.start] = self.resolution_count;
        self.resolutions[self.resolution_count] = .{ .at = at.start, .declared = target, .owner = owner, .kind = kind };
        self.resolution_count += 1;
    }
    /// Whether some function of the file is named `ToString`, read from the tokens once.
    fn declaresText(self: *Workspace) bool {
        if (self.text_declared == 0) {
            self.text_declared = 1;
            var starts: StatementStarts = .{};
            for (0..self.token_count) |at| {
                if (!starts.next(self, at)) continue;
                if (self.tokens[at].kind == .identifier and std.mem.eql(u8, self.tokens[at].span.text(self.source), "ToString") and (self.functionShapeAt(at, false) or self.functionShapeAt(at, true))) {
                    self.text_declared = 2;
                    break;
                }
            }
        }
        return self.text_declared == 2;
    }

    /// Notes that the identifier at `at` has no one qualified form: what it means depends on the
    /// type of its argument (a built-in `ToString` in a file that declares one).
    fn noteVaries(self: *Workspace, at: Span) void {
        if (!self.qualify) return;
        if (at.start >= at.end or at.end > self.source.len or self.libraryModule(at) != null) return;
        const slot = self.resolution_at[at.start];
        if (slot < self.resolution_count and self.resolutions[slot].at == at.start) {
            self.resolutions[slot] = .{ .at = at.start, .kind = .varies };
            return;
        }
        std.debug.assert(self.resolution_count < self.resolutions.len);
        self.resolution_at[at.start] = self.resolution_count;
        self.resolutions[self.resolution_count] = .{ .at = at.start, .kind = .varies };
        self.resolution_count += 1;
    }
    /// Whether position `at` lies in the text of a generic template of this pass.
    fn inTemplate(self: *const Workspace, at: u32) bool {
        for (self.generic_templates[0..self.generic_count]) |template| {
            if (template.end <= template.header or template.end > self.token_count) continue;
            if (at >= template.name.start and at < self.tokens[template.end - 1].span.end) return true;
        }
        return false;
    }
    /// The local declared at `at` is in scope from position `begin` on.
    fn beginScope(self: *Workspace, at: u32, begin: u32) void {
        if (!self.qualify or at >= self.source.len) return;
        const slot = self.resolution_at[at];
        if (slot < self.resolution_count and self.resolutions[slot].at == at and self.resolutions[slot].declared == at) self.resolutions[slot].begin = begin;
    }
    /// The local declared at `at` is out of scope from position `end` on.
    fn endScope(self: *Workspace, at: u32, end: u32) void {
        if (!self.qualify or at >= self.source.len or end == 0) return;
        // A scope that ends in generated text has no end the author wrote.
        if (self.libraryModule(.{ .start = end - 1, .end = end }) != null) return;
        const slot = self.resolution_at[at];
        if (slot < self.resolution_count and self.resolutions[slot].at == at and self.resolutions[slot].declared == at) self.resolutions[slot].end = end;
    }
    /// Notes the declaration whose name is `name`: it resolves to itself.
    fn noteDeclaration(self: *Workspace, name: Span, kind: qualify.Kind, owner: u32) void {
        self.noteName(name, name.start, kind, owner);
    }

    /// RFC-0085, I11: the table of the last compile, ordered for `qualify.write` and
    /// `qualify.verify`, with the parts of `program`'s text the author wrote: one per file,
    /// without the library block a macro appended. `written` holds them: it has room for one
    /// per file.
    pub fn qualification(self: *Workspace, program: types.Program, written: []Span) qualify.Text {
        std.debug.assert(self.qualify);
        std.debug.assert(written.len >= @max(program.modules.len, 1));
        const entries = self.resolutions[0..self.resolution_count];
        qualify.sort(entries);
        // Sorting moved the entries: they point back from their new places.
        for (entries, 0..) |entry, index| self.resolution_at[entry.at] = @intCast(index);
        var parts: usize = 0;
        if (program.modules.len == 0) {
            const base = if (self.has_library) self.library_base[0] else 0;
            written[0] = .{ .start = 0, .end = if (base != 0) base else @intCast(program.source.len) };
            parts = 1;
        } else for (program.modules, 0..) |module, index| {
            const base = if (self.has_library) self.library_base[index] else 0;
            written[index] = .{ .start = module.source.start, .end = if (base != 0) base else module.source.end };
            parts += 1;
        }
        return .{ .source = program.source, .paths = program.paths, .modules = program.modules, .nested = program.nested, .written = written[0..parts], .entries = entries };
    }

    /// RFC-0085, I11: `qualify.verify` of the table `text` of `program`, the last compile, with
    /// what this compile knows besides the program: its functions, and the members its
    /// catalogue does not list (methods, interface fields, fields with accessors) with the
    /// types that declare them.
    pub fn verifyQualification(self: *const Workspace, program: types.Program, text: qualify.Text) ?qualify.Problem {
        const capacity = self.accessor_count + self.method_count + self.slot_count;
        var empty: [0][2]u32 = .{};
        const pairs: [][2]u32 = if (capacity == 0) &empty else scratch.alloc([2]u32, capacity) orelse return .{ .at = 0, .reason = "no room to verify" };
        defer if (capacity != 0) scratch.free(pairs);
        var count: usize = 0;
        for (self.accessor_fields[0..self.accessor_count]) |field| if (declaredAt(program, field.owner)) |owner| {
            pairs[count] = .{ field.name.start, owner };
            count += 1;
        };
        for (self.methods[0..self.method_count]) |method| if (!method.synthetic) if (declaredAt(program, method.class)) |owner| {
            pairs[count] = .{ method.name.start, owner };
            count += 1;
        };
        for (self.slots[0..self.slot_count], self.slot_kind[0..self.slot_count]) |slot, kind| if (kind == .getter) if (declaredAt(program, slot.owner)) |owner| {
            pairs[count] = .{ slot.name.start, owner };
            count += 1;
        };
        return qualify.verify(text, .{ .program = program, .functions = self.functions.definitions[0..self.functions.count], .members = pairs[0..count] });
    }
    fn declaredAt(program: types.Program, value_type: types.Type) ?u32 {
        const item = catalogue.definition(value_type, program.definitions) orelse return null;
        return (catalogue.declaredName(item) orelse return null).start;
    }

    fn libraryModule(self: *const Workspace, span: Span) ?u32 {
        if (!self.has_library) return null;
        const count = self.module_storage.module_count;
        const index = if (count == 0) 0 else modules.owner(span, self.module_storage.modules[0..count]) orelse return null;
        const base = self.library_base[index];
        return if (base != 0 and span.start >= base) index else null;
    }

    /// The macros: `For(...)` (RFC-0056), `If(C1, C2, ..., Then, Else)` with several conditions
    /// that may bind names (`Name := value`), and tuple destructuring `(A, B) := value`. Each
    /// expands to the templates in `macros.zig` with the user's token ranges spliced in; the
    /// pieces are ordinary user tokens, so nested macros and every earlier pass apply inside them.
    /// A module that uses one carries a library block; without it the whole compile is retried
    /// with the block appended (`macro_unavailable`).
    fn desugarMacros(self: *Workspace) ParseError!void {
        // Asked of the program as written, before any expansion adds tokens.
        self.sort_by_standard = self.sortByStandard();
        self.spawn_named = self.namesSpawn();
        self.sync_named = self.namesForm("Sync") or self.namesTyped("Sync");
        self.race_named = self.namesForm("Race") or self.namesTyped("Race");
        self.rush_named = self.namesForm("Rush") or self.namesTyped("Rush");
        self.branch_named = self.namesForm("Branch");
        self.upon_named = self.namesForm("Upon") or self.namesTyped("Upon");
        self.when_named = self.namesForm("When") or self.namesTyped("When");
        self.batch_named = self.namesForm("Batch") or self.namesTyped("Batch");
        self.await_named = self.namesAwait();
        var first: ?usize = null;
        for (0..self.token_count - 1) |index| {
            // An arm that an exit leaves is rewritten too (RFC-0082, P3.6).
            if (self.macroAt(index) != null or self.exitingArmsAt(index)) {
                first = index;
                break;
            }
        }
        var start = first orelse return;
        if (!self.has_library) return self.fail(self.tokens[start].span, .macro_unavailable);
        try self.lexLibrary();
        defer self.dropCellNames();
        self.exit_frame_count = 0;
        self.exit_defer_count = 0;
        // An expansion may itself contain a macro call (a loop's conditions), so rewrite until none is left.
        var rounds: usize = 0;
        while (true) {
            var rw: Rewrite = .{};
            self.beginRewrite(&rw, start);
            self.library_names_before = self.library_names;
            self.depth_index = 0;
            self.depth_value = 0;
            try self.streamMacros(&rw, start, self.token_count, 0);
            self.finishRewrite(&rw);
            rounds += 1;
            var again: ?usize = null;
            for (start..self.token_count - 1) |index| {
                if (self.macroAt(index) != null) {
                    again = index;
                    break;
                }
            }
            start = again orelse return;
            if (rounds == 8) return self.fail(self.tokens[start].span, .macro_limit);
        }
    }

    /// Whether `Sync(`, `Race(` or `Rush(` at `at` is the form and an exit leaves one of its arms
    /// (RFC-0082, P3.6). Finding the close of the form costs its length, as for `Spawn(` (E3).
    fn exitingArmsAt(self: *Workspace, at: usize) bool {
        if (!self.armsAt(at)) return false;
        const close = self.segmentClose(at + 1);
        if (close >= self.token_count) return false;
        const exits = self.exitsIn(at + 2, close);
        return exits.returns or exits.breaks;
    }

    const MacroKind = enum { for_call, if_call, destructure, while_call, not_call, first_call, loop_block, defer_statement, sort_by };

    fn macroAt(self: *Workspace, at: usize) ?MacroKind {
        if (at + 1 >= self.token_count) return null;
        if (self.isName(at, "For") and self.tokens[at + 1].kind == .left_paren) return .for_call;
        if (self.isName(at, "While") and self.tokens[at + 1].kind == .left_paren) return .while_call;
        if (self.isName(at, "Not") and self.tokens[at + 1].kind == .left_bracket) return .not_call;
        if (self.isName(at, "First") and self.tokens[at + 1].kind == .left_bracket and self.generatorAhead(at + 2)) return .first_call;
        // The brace tells the Book's loop from the state loop `Loop(Step, Initial)`.
        if (self.isName(at, "Loop") and self.tokens[at + 1].kind == .left_brace) return .loop_block;
        if (self.isName(at, "Defer") and self.tokens[at + 1].kind == .left_brace) return .defer_statement;
        if (self.isName(at, "If") and self.tokens[at + 1].kind == .left_paren and self.argumentCount(at + 1) >= 4) return .if_call;
        // One condition that binds (`If(N:=Next[I], Then, Else)`) is the same form: no
        // expression starts `Name:=`, so no three-argument `If` that compiled is taken for it.
        if (self.isName(at, "If") and self.tokens[at + 1].kind == .left_paren and self.bindingAhead(at + 2) and self.argumentCount(at + 1) == 3) return .if_call;
        // RFC-0090: and so is one without an else (`If(N:=Next[I], Then)`), which no two-argument
        // `If` that compiled was.
        if (self.isName(at, "If") and self.tokens[at + 1].kind == .left_paren and self.bindingAhead(at + 2) and self.argumentCount(at + 1) == 2) return .if_call;
        if (self.destructureEnd(at) != null) return .destructure;
        if (self.sort_by_standard and self.isName(at, "SortBy") and self.tokens[at + 1].kind == .left_paren and (at == 0 or self.tokens[at - 1].kind != .dot)) return .sort_by;
        return null;
    }

    /// Whether `SortBy(Items, Less)` is the standard function (RFC-0081): the name is not a
    /// reserved word, so a program may declare something of that name anywhere, and then every
    /// use of the name in the bundle is the program's. A token decides it, before any name is
    /// resolved: the name is standard in a bundle whose every `SortBy` is the name of a call
    /// that is not the header of a declaration (`SortBy(...)` followed by `<` or `:`).
    fn sortByStandard(self: *const Workspace) bool {
        for (0..self.token_count) |at| {
            if (!self.isName(at, "SortBy")) continue;
            if (at != 0 and self.tokens[at - 1].kind == .dot) return false;
            if (at + 1 >= self.token_count or self.tokens[at + 1].kind != .left_paren) return false;
            const close = self.segmentClose(at + 1);
            if (close + 1 >= self.token_count) return false;
            const after = self.tokens[close + 1].kind;
            if (after == .less or after == .colon) return false;
        }
        return true;
    }

    /// Whether the argument that starts at `from` opens `Name:=`.
    fn bindingAhead(self: *const Workspace, from: usize) bool {
        var at = from;
        while (at < self.token_count and self.tokens[at].kind == .newline) at += 1;
        if (at + 2 >= self.token_count or self.tokens[at].kind != .identifier) return false;
        const colon = self.tokens[at + 1];
        const equal = self.tokens[at + 2];
        return colon.kind == .colon and equal.kind == .equal and colon.span.end == equal.span.start;
    }

    /// Whether the argument that starts at `from` opens like a generator: `Name:` (but not
    /// `Name:=`) or `Key->`. This is what tells `First[X:Items, ...]` from a call `First[Items]`
    /// or `First[i64](X)` of a program's own function, which no argument of that shape can be,
    /// and from the header `First[T:type](...)` of a generic function of that name, whose
    /// parameters are followed by one of the three kind words and never by a source.
    fn generatorAhead(self: *const Workspace, from: usize) bool {
        var at = from;
        while (at < self.token_count and self.tokens[at].kind == .newline) at += 1;
        if (at + 2 >= self.token_count or self.tokens[at].kind != .identifier) return false;
        const next = self.tokens[at + 1];
        const after = self.tokens[at + 2];
        if (next.kind == .colon) {
            if (after.kind == .identifier and macros.kindWord(after.span.text(self.source))) return false;
            return after.kind != .equal or next.span.end != after.span.start;
        }
        return next.kind == .minus and after.kind == .greater and next.span.end == after.span.start;
    }

    /// The number of top-level arguments of the call whose `(` is at `open`.
    fn argumentCount(self: *Workspace, open: usize) usize {
        var count: usize = 1;
        var depth: usize = 0;
        var at = open + 1;
        while (at < self.token_count) : (at += 1) {
            const kind = self.tokens[at].kind;
            if (kind == .eof) return 0;
            if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) depth += 1;
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) {
                if (depth == 0) return count;
                depth -= 1;
            }
            if (depth == 0 and kind == .comma) count += 1;
        }
        return 0;
    }

    /// The `:=` that ends a tuple pattern `(A, B, ...)` at the start of a statement, if one starts at `at`.
    fn destructureEnd(self: *Workspace, at: usize) ?usize {
        if (self.tokens[at].kind != .left_paren) return null;
        if (at != 0 and self.tokens[at - 1].kind != .left_brace and self.tokens[at - 1].kind != .separator and self.tokens[at - 1].kind != .newline) return null;
        var cursor = at + 1;
        var names: usize = 0;
        while (cursor + 1 < self.token_count and self.tokens[cursor].kind == .identifier) {
            names += 1;
            cursor += 1;
            if (self.tokens[cursor].kind == .comma) {
                cursor += 1;
                continue;
            }
            break;
        }
        if (names < 2 or cursor + 2 >= self.token_count or self.tokens[cursor].kind != .right_paren) return null;
        const colon = self.tokens[cursor + 1];
        const equal = self.tokens[cursor + 2];
        if (colon.kind != .colon or equal.kind != .equal or colon.span.end != equal.span.start) return null;
        return cursor + 2;
    }

    /// Where a macro call lives: the library block of its module.
    const Site = struct { module: u32, base: u32, templates: u32, library_end: u32, extension: macros.Extension, keyword: Token };

    /// What the placeholders of a template stand for.
    const Fill = struct {
        name: ?Token = null,
        index_name: ?Token = null,
        temp: ?Token = null,
        number: u32 = 0,
        first: [2]usize = .{ 0, 0 },
        second: [2]usize = .{ 0, 0 },
        third: [2]usize = .{ 0, 0 },
        conditions: []const [2]usize = &.{},
        checks: []const Check = &.{},
        variables: []const Token = &.{},
        rest: ?ForRest = null,
        /// The user's expression that a `Require` of the template checks: a failure of the
        /// requirement is reported there, not at a word of the library block.
        blame: ?Span = null,
        /// RFC-0090: the `If` of the template has no else, so `,__ELSE` is left out and the
        /// expansion is an `If` without an else.
        no_else: bool = false,
    };
    /// One argument of a `For` before its body (RFC-0064).
    const ForClause = struct {
        kind: enum { generator, range, binding, filter },
        /// What a generator or binding names; `index_name` is the `Key` of `Key->Value:Items`.
        name: ?Token = null,
        index_name: ?Token = null,
        /// The source of a generator, the low bound of a range, the value of a binding, the filter.
        expr: [2]usize,
        /// The high bound of a range.
        high: [2]usize = .{ 0, 0 },
    };
    /// `first` selects the templates of `First[...]` (RFC-0072), which has the clauses of a `For`.
    const ForPlan = struct {
        clauses: []const ForClause,
        body: [2]usize,
        first: bool = false,
        /// The outer `var` locals the loop assigns and so carries from one iteration to the next.
        variables: []const Token = &.{},
        /// RFC-0082, P3.8: an earlier compile found a site in an iteration, so no iteration has
        /// a region: nothing in one may fail (`expandForRest`).
        suspends: bool = false,
    };
    /// What `__REST` stands for: the clauses from `next` on. `checked` says the bindings and
    /// filters at `next` are already emitted, so the generator or body after them follows.
    /// `opened` says the wrapper a `First` puts around an inner generator is emitted too.
    const ForRest = struct { plan: *const ForPlan, next: usize, checked: bool, opened: bool = false };
    const Check = struct { name: ?Token, expr: [2]usize };
    const max_checks = 64;

    fn siteFor(self: *Workspace, keyword: Token) ParseError!Site {
        const count = self.module_storage.module_count;
        const module: u32 = if (count == 0) 0 else modules.owner(keyword.span, self.module_storage.modules[0..count]) orelse return self.fail(keyword.span, .macro_unavailable);
        const base = self.library_base[module];
        if (base == 0) return self.fail(keyword.span, .macro_unavailable);
        if (self.library_blame[module].start == base) self.library_blame[module] = keyword.span;
        return .{ .module = module, .base = base, .templates = self.library_templates[module], .library_end = self.moduleEnd(module), .extension = self.library_extension[module], .keyword = keyword };
    }

    /// The block of `site` lacks generated text its call needs. The caller of the compiler sees
    /// `macro_unavailable` with `library_wanted` set and compiles again with the block extended.
    fn requestExtension(self: *Workspace, site: Site, wanted: macros.Extension) ParseError {
        std.debug.assert(wanted.exceeds(site.extension));
        self.library_wanted = wanted;
        return self.fail(site.keyword.span, .macro_unavailable);
    }

    /// A call that uses positions `0 ... count - 1` needs the numerals for them in its block.
    fn requireNumerals(self: *Workspace, site: Site, count: usize) ParseError!void {
        std.debug.assert(count <= macros.numeral_count);
        if (count <= macros.fixed_numerals or site.extension.numerals) return;
        return self.requestExtension(site, .{ .numerals = true });
    }

    fn numeralToken(self: *Workspace, site: Site, number: usize) Token {
        if (number < macros.fixed_numerals) return self.libraryToken(site, .numerals, number);
        const span = site.extension.numeral(number);
        return .{ .kind = .integer, .span = .{ .start = site.templates + span[0], .end = site.templates + span[1] } };
    }

    /// The next unused temporary of the module of `site`. Each tuple pattern takes its own, so
    /// several fit in one scope: the fixed ones first, then the generated ones.
    fn temporaryToken(self: *Workspace, site: Site) ParseError!Token {
        const taken = self.library_names[site.module];
        if (taken < macros.fixed_temporaries) {
            self.library_names[site.module] += 1;
            return self.libraryToken(site, .temporaries, taken);
        }
        const index = taken - macros.fixed_temporaries;
        if (index >= site.extension.temporaries) {
            // The count below covers every pattern, so a block that got its temporaries has enough.
            if (site.extension.temporaries != 0) return self.fail(site.keyword.span, .macro_limit);
            // Earlier rounds took a temporary per pattern they rewrote; the rest are in this round's tokens.
            const patterns = self.library_names_before[site.module] + self.patternCount(site.module);
            std.debug.assert(patterns > taken);
            return self.requestExtension(site, .{ .temporaries = patterns - macros.fixed_temporaries });
        }
        self.library_names[site.module] += 1;
        const span = site.extension.temporary(index);
        return .{ .kind = .identifier, .span = .{ .start = site.templates + span[0], .end = site.templates + span[1] } };
    }

    /// At least the number of tuple patterns of `module` that this and later rounds of
    /// `desugarMacros` rewrite, counted in the tokens this round began with. A pattern ends `):=`,
    /// the user's tokens pass through every expansion in order, and no template puts `:=` after a
    /// range of them, so counting that ending misses none; it is exact unless something that is
    /// not a pattern ends the same way.
    fn patternCount(self: *const Workspace, module: u32) u32 {
        const start: u32 = if (self.module_storage.module_count == 0) 0 else self.module_storage.modules[module].source.start;
        const end = self.userEnd(module);
        var patterns: u32 = 0;
        for (2..self.token_count) |index| {
            const colon = self.tokens[index - 1];
            const equal = self.tokens[index];
            if (self.tokens[index - 2].kind != .right_paren or colon.kind != .colon or equal.kind != .equal or colon.span.end != equal.span.start) continue;
            if (colon.span.start >= start and colon.span.start < end) patterns += 1;
        }
        return patterns;
    }

    /// The `ordinal`-th token of a template, with its place in the library block.
    fn libraryToken(self: *Workspace, site: Site, template: macros.Template, ordinal: usize) Token {
        const range = self.library_ranges[@backingInt(template)];
        return self.shifted(self.library_tokens[range[0] + ordinal], site.templates + site.extension.offset(template));
    }

    fn libraryWord(self: *Workspace, site: Site, template: macros.Template) Token {
        return self.libraryToken(site, template, 0);
    }

    fn streamMacros(self: *Workspace, rw: *Rewrite, from: usize, to: usize, depth: usize) ParseError!void {
        var at = from;
        while (at < to) {
            if (self.macroAt(at)) |kind| {
                const keyword = self.tokens[at];
                const emitted = rw.out;
                defer self.tagSite(rw, emitted, keyword);
                at = switch (kind) {
                    .for_call => try self.rewriteFor(rw, at, depth),
                    .if_call => try self.rewriteIf(rw, at, depth),
                    .destructure => try self.rewriteDestructure(rw, at, depth),
                    .while_call => try self.rewriteWhile(rw, at, depth),
                    .not_call => try self.rewriteNot(rw, at, depth),
                    .first_call => try self.rewriteFirst(rw, at, depth),
                    .loop_block => try self.rewriteLoopBlock(rw, at, depth),
                    .defer_statement => try self.rewriteDefer(rw, at, to, depth),
                    .sort_by => try self.rewriteSortBy(rw, at, depth),
                };
                continue;
            }
            if (self.exit_frame_count != 0 or self.exit_defer_count != 0) {
                // Inside a loop or after a `Defer`, an exit has more to do than return.
                if (self.exitAt(at)) |kind| {
                    const keyword = self.tokens[at];
                    const emitted = rw.out;
                    at = try self.rewriteExit(rw, at, kind, depth);
                    self.tagSite(rw, emitted, keyword);
                    continue;
                }
                if (self.isName(at, "Fn")) if (self.functionBody(at, to)) |body| {
                    at = try self.streamFunction(rw, at, body, depth);
                    continue;
                };
                // So is a nested function (RFC-0085, I3), whose body ends with its statement.
                if (self.statementStart(at)) if (self.nestedHeaderAt(at)) |body| {
                    at = try self.streamNested(rw, at, body, to, depth);
                    continue;
                };
                if (self.tokens[at].kind == .synthetic_guard and at + 1 < to and self.tokens[at + 1].kind == .left_brace) {
                    at = try self.streamGuard(rw, at, depth);
                    continue;
                }
            }
            // So is each arm of a `Sync` or a `Race` (P3.3).
            if (at + 1 < to and self.armsAt(at)) {
                at = try self.streamArms(rw, at, depth);
                continue;
            }
            // A task's body is a frame of its own wherever it stands, so that an exit inside a
            // loop inside it is refused as one in the body.
            if (!self.spawn_named and self.isName(at, "Spawn") and at + 1 < to and self.tokens[at + 1].kind == .left_brace) {
                at = try self.streamTask(rw, at, depth);
                continue;
            }
            // So is a `Branch{...}`'s (P3.4).
            if (!self.branch_named and self.isName(at, "Branch") and at + 1 < to and self.tokens[at + 1].kind == .left_brace) {
                at = try self.streamTask(rw, at, depth);
                continue;
            }
            // And a `Batch{...}`'s (RFC-0084, P4.5), which no exit leaves either.
            if (!self.batch_named and self.isName(at, "Batch") and at + 1 < to and self.tokens[at + 1].kind == .left_brace) {
                at = try self.streamTask(rw, at, depth);
                continue;
            }
            try self.emitTo(rw, self.tokens[at]);
            at += 1;
        }
    }

    /// Splices one template: placeholders become the user's tokens and ranges (rewritten in turn).
    fn expandTemplate(self: *Workspace, rw: *Rewrite, site: Site, template: macros.Template, fill: *const Fill, depth: usize) ParseError!void {
        const template_text = macros.templateText(template);
        const range = self.library_ranges[@backingInt(template)];
        const shift = site.templates + site.extension.offset(template);
        const keyword = site.keyword;
        // What a template puts inside one of its functions is compiled in that function: a
        // `Defer` there counts from the function's first, and no `Defer` outside is its business.
        var function_pending = false;
        var level: u32 = 0;
        var bodies: [4]u32 = undefined;
        var body_count: usize = 0;
        for (self.library_tokens[range[0]..range[1]], range[0]..) |raw, ordinal| {
            const token = self.shifted(raw, shift);
            if (raw.kind == .comma and fill.no_else and ordinal + 1 < range[1] and std.mem.eql(u8, self.library_tokens[ordinal + 1].span.text(template_text), "__ELSE")) continue;
            if (raw.kind != .identifier) {
                if (raw.kind == .left_brace) {
                    level += 1;
                    if (function_pending) {
                        function_pending = false;
                        std.debug.assert(body_count < bodies.len);
                        try self.pushExitFrame(keyword.span, .{ .kind = .function, .defers = self.exit_defer_count, .marks = self.exit_defer_count });
                        bodies[body_count] = level;
                        body_count += 1;
                    }
                } else if (raw.kind == .right_brace) {
                    if (body_count != 0 and bodies[body_count - 1] == level) {
                        body_count -= 1;
                        self.exit_frame_count -= 1;
                    }
                    level -= 1;
                }
                // The unwrap of an inner level of a `First` fails for the call, not for a
                // character of the library block.
                try self.emitTo(rw, if (raw.kind == .question) .{ .kind = .question, .span = keyword.span } else token);
                continue;
            }
            const word = raw.span.text(template_text);
            if (fill.blame != null and std.mem.eql(u8, word, "Require")) {
                // The requirement is the user's: a failure of it is traced to their expression.
                try self.emitTo(rw, .{ .kind = .synthetic_require, .span = fill.blame.? });
            } else if (std.mem.eql(u8, word, "Fn")) {
                function_pending = true;
                // Each anonymous function is identified by its own `Fn` token.
                const position = try self.fnWord(site);
                if (position + 4 > site.library_end) return self.fail(keyword.span, .macro_limit);
                self.library_used[site.module] += 1;
                try self.emitTo(rw, .{ .kind = .identifier, .span = .{ .start = position, .end = position + 2 } });
            } else if (std.mem.eql(u8, word, "__REST")) {
                try self.expandForRest(rw, site, fill.rest.?, depth + 1);
            } else if (std.mem.eql(u8, word, "__HIGH")) {
                try self.streamMacros(rw, fill.third[0], fill.third[1], depth + 1);
            } else if (std.mem.eql(u8, word, "__X") or std.mem.eql(u8, word, "__NAME")) {
                try self.emitTo(rw, fill.name.?);
            } else if (std.mem.eql(u8, word, "__TEMP")) {
                try self.emitTo(rw, fill.temp.?);
            } else if (std.mem.eql(u8, word, "__I")) {
                try self.emitTo(rw, fill.index_name.?);
            } else if (std.mem.eql(u8, word, "__INDEX")) {
                try self.emitTo(rw, self.numeralToken(site, fill.number));
            } else if (std.mem.eql(u8, word, "__ITEMS") or std.mem.eql(u8, word, "__EXPR")) {
                try self.streamMacros(rw, fill.first[0], fill.first[1], depth + 1);
            } else if (std.mem.eql(u8, word, "__BODY") or std.mem.eql(u8, word, "__THEN")) {
                try self.streamMacros(rw, fill.second[0], fill.second[1], depth + 1);
            } else if (std.mem.eql(u8, word, "__STMTS")) {
                // A loop body is a list of statements: the interior of a lone `Block{...}`, or one expression.
                var statements = fill.second;
                if (statements[1] - statements[0] >= 3 and self.isName(statements[0], "Block") and self.tokens[statements[0] + 1].kind == .left_brace and self.tokens[statements[1] - 1].kind == .right_brace and self.segmentClose(statements[0] + 1) == statements[1] - 1) {
                    statements = self.trimmed(statements[0] + 2, statements[1] - 1);
                }
                if (statements[0] != statements[1]) {
                    try self.streamMacros(rw, statements[0], statements[1], depth + 1);
                    try self.emitTo(rw, .{ .kind = .separator, .span = keyword.span });
                }
            } else if (std.mem.eql(u8, word, "__ELSE")) {
                try self.streamMacros(rw, fill.third[0], fill.third[1], depth + 1);
            } else if (std.mem.eql(u8, word, "__COND")) {
                for (fill.conditions, 0..) |condition, item| {
                    if (item > 0) try self.emitTo(rw, self.libraryWord(site, .and_word));
                    try self.emitTo(rw, .{ .kind = .left_paren, .span = keyword.span });
                    try self.streamMacros(rw, condition[0], condition[1], depth + 1);
                    try self.emitTo(rw, .{ .kind = .right_paren, .span = keyword.span });
                }
            } else if (std.mem.eql(u8, word, "__CONDS")) {
                for (fill.conditions, 0..) |condition, item| {
                    if (item > 0) try self.emitTo(rw, .{ .kind = .comma, .span = keyword.span });
                    try self.streamMacros(rw, condition[0], condition[1], depth + 1);
                }
            } else if (std.mem.eql(u8, word, "__VARTYPES") or std.mem.eql(u8, word, "__VARNAMES")) {
                for (fill.variables) |variable| {
                    const piece: Fill = .{ .name = variable };
                    try self.expandTemplate(rw, site, if (word[5] == 'T') .loop_type else .loop_name, &piece, depth + 1);
                }
            } else if (std.mem.eql(u8, word, "__VARDECLS") or std.mem.eql(u8, word, "__VARSTORES")) {
                for (fill.variables, 0..) |variable, index| {
                    const piece: Fill = .{ .name = variable, .number = @intCast(index + 1) };
                    try self.expandTemplate(rw, site, if (word[5] == 'D') .loop_decl else .loop_store, &piece, depth + 1);
                }
            } else if (std.mem.eql(u8, word, "__CHECKS")) {
                for (fill.checks) |check| {
                    const piece: Fill = .{ .name = check.name, .first = check.expr, .blame = self.userSpan(check.expr) };
                    try self.expandTemplate(rw, site, if (check.name != null) .check_bind else .check_test, &piece, depth + 1);
                }
            } else if (std.mem.eql(u8, word, "__PACK")) {
                var bound: usize = 0;
                for (fill.checks) |check| {
                    if (check.name == null) continue;
                    if (bound == 0) {
                        try self.emitTo(rw, self.libraryToken(site, .tuple_word, 0));
                        try self.emitTo(rw, self.libraryToken(site, .tuple_word, 1));
                    } else try self.emitTo(rw, self.libraryToken(site, .tuple_word, 2));
                    try self.emitTo(rw, check.name.?);
                    bound += 1;
                }
                if (bound == 0) try self.emitTo(rw, self.libraryWord(site, .true_word)) else try self.emitTo(rw, self.libraryToken(site, .tuple_word, 3));
            } else if (std.mem.eql(u8, word, "__UNPACK")) {
                var bound: u32 = 0;
                for (fill.checks) |check| {
                    if (check.name == null) continue;
                    const piece: Fill = .{ .name = check.name, .number = bound };
                    try self.expandTemplate(rw, site, .unpack_if, &piece, depth + 1);
                    bound += 1;
                }
            } else try self.emitTo(rw, token);
        }
    }

    /// The close of the call whose `(` or `[` is at `open`, with the argument ranges (newlines trimmed).
    fn splitCall(self: *Workspace, keyword: Token, open: usize, bounds: []usize, code: Diagnostic.Code) ParseError!struct { items: usize, close: usize } {
        var items: usize = 1;
        var level: usize = 0;
        var close = open + 1;
        bounds[0] = open + 1;
        while (close < self.token_count) : (close += 1) {
            const kind = self.tokens[close].kind;
            if (kind == .eof) return self.fail(keyword.span, code);
            if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) level += 1;
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) {
                if (level == 0) break;
                level -= 1;
            }
            if (level == 0 and kind == .comma) {
                if (items + 2 > bounds.len) return self.fail(keyword.span, code);
                bounds[items] = close + 1;
                items += 1;
            }
        }
        const closer: Token.Kind = if (self.tokens[open].kind == .left_bracket) .right_bracket else .right_paren;
        if (close >= self.token_count or self.tokens[close].kind != closer) return self.fail(keyword.span, code);
        bounds[items] = close + 1;
        return .{ .items = items, .close = close };
    }

    /// `For(Clause, ..., Body)` (RFC-0056, RFC-0064). The forms RFC-0056 defined (one array or map
    /// generator and filters) keep their four templates and so their IR, unless an earlier compile
    /// found that the call needs a failure context (`forceFor`); every other form is lowered one
    /// generator at a time by `expandForGenerator`.
    fn rewriteFor(self: *Workspace, rw: *Rewrite, at: usize, depth: usize) ParseError!usize {
        const keyword = self.tokens[at];
        if (depth >= rewrite_depth) return self.fail(keyword.span, .expression_limit);
        var bounds: [types.limits.record_fields + 3]usize = undefined;
        const call = try self.splitCall(keyword, at + 1, &bounds, .for_syntax);
        const items = call.items;
        if (items < 2) return self.fail(keyword.span, .for_syntax);
        const body = self.trimmed(bounds[items - 1], bounds[items] - 1);
        if (body[0] == body[1]) return self.fail(keyword.span, .for_syntax);
        // The head and as many filters as RFC-0056 allowed.
        var clauses: [max_checks + 1]ForClause = undefined;
        const count = items - 1;
        if (count > clauses.len) return self.fail(keyword.span, .for_syntax);
        var conditions: [max_checks][2]usize = undefined;
        var established = true;
        for (0..count) |item| {
            const range = self.trimmed(bounds[item], bounds[item + 1] - 1);
            if (range[0] == range[1]) return self.fail(keyword.span, .for_syntax);
            clauses[item] = try self.forClause(range);
            if (item == 0) {
                // The head is a generator: `X:Items`, `I->X:Items` or `X:Low..High`, or, since
                // RFC-0090, a binding or a filter, which the general lowering runs first.
                established = clauses[0].kind == .generator;
            } else {
                conditions[item - 1] = range;
                established = established and clauses[item].kind == .filter;
            }
        }
        // The last argument is the body, so one shaped like a clause has lost its body.
        if ((try self.forClause(body)).kind != .filter) return self.fail(self.tokens[body[0]].span, .for_syntax);
        const site = try self.siteFor(keyword);
        // RFC-0082, P3.8: an earlier compile found a site in an iteration of this call.
        const suspends = self.forSuspended(site, keyword);
        // The locals of the code around the loop that it assigns travel through it, as through
        // a `While`. The first generator's source runs before the loop, in the code around it:
        // an assignment or an exit there belongs to that code and not to this `For`.
        var variables: [max_exit_variables]Token = undefined;
        const carried = try self.forVariables(keyword, at, bounds[1], call.close, &variables);
        const exits = self.exitsIn(bounds[1], call.close);
        // RFC-0090: a `For` whose first clause is not a generator runs its leading bindings and
        // filters in one region in the code around it, and then the generators after them, or
        // the body at most once. A loop that can be left has a generator at its head.
        const leading = clauses[0].kind != .generator and clauses[0].kind != .range;
        if (leading and (exits.returns or exits.breaks)) return self.fail(self.tokens[exits.first].span, .for_clause_exit);
        if (exits.returns or exits.breaks) {
            // Something leaves this `For` early (RFC-0068): it is a loop that can stop.
            const plan: ForPlan = .{ .clauses = clauses[0..count], .body = body, .variables = variables[0..carried], .suspends = suspends };
            try self.expandExitFor(rw, site, &plan, 0, exits, depth);
            return call.close + 1;
        }
        if (carried != 0) {
            // No such loop compiled before it carried its locals, so none has a lowering to
            // keep: every form goes through the levels of the general `For`, which take the
            // locals in and hand them back.
            if (!site.extension.loops or !site.extension.carries) return self.requestExtension(site, .{ .loops = true, .carries = true });
            try self.requireNumerals(site, carried + 1);
            const plan: ForPlan = .{ .clauses = clauses[0..count], .body = body, .variables = variables[0..carried], .suspends = suspends };
            try self.expandForHead(rw, site, &plan, depth);
            return call.close + 1;
        }
        // A `For` that assigns a shared local keeps the general lowering it had while the compile
        // that shared the local carried it (RFC-0085, I2): one compile more, not two.
        if (established and !self.for_shared and !suspends and !self.forForced(site, keyword)) {
            const filtered = count > 1;
            self.recordFor(site, keyword, self.tokens[call.close].span.end, filtered);
            const indexed = clauses[0].index_name != null;
            const template: macros.Template = if (indexed) (if (filtered) .for_filter_indexed else .for_each_indexed) else if (filtered) .for_filter else .for_each;
            try self.expandTemplate(rw, site, template, &.{
                .name = clauses[0].name,
                .index_name = clauses[0].index_name,
                .first = clauses[0].expr,
                .second = body,
                .conditions = conditions[0 .. count - 1],
            }, depth);
        } else {
            // Only a module with such a call carries the general templates (`Extension.loops`).
            if (!site.extension.loops) return self.requestExtension(site, .{ .loops = true });
            const plan: ForPlan = .{ .clauses = clauses[0..count], .body = body, .suspends = suspends };
            try self.expandForHead(rw, site, &plan, depth);
        }
        return call.close + 1;
    }

    /// The general `For` from its first clause: the level of the generator at its head, or
    /// (RFC-0090) the bindings and filters before its first generator, in the region
    /// `expandForRest` gives every iteration, run once in the code around the loop:
    /// `Attempt(Block{ Y:=(V); Require[(F)]; Rest }, array{})`. A failing clause skips the
    /// generators after it, whose sources it may feed, and the body, and undoes its writes;
    /// without a generator the body runs at most once and the array has one element or none.
    fn expandForHead(self: *Workspace, rw: *Rewrite, site: Site, plan: *const ForPlan, depth: usize) ParseError!void {
        const head = plan.clauses[0].kind;
        if (head == .generator or head == .range) return self.expandForGenerator(rw, site, plan, 0, depth);
        try self.expandForRest(rw, site, .{ .plan = plan, .next = 0, .checked = false }, depth);
    }

    /// `First[Clause, ..., Body]` (RFC-0072): the clauses of a `For`, but the value is the body
    /// of the first iteration that succeeds, and the expression fails when there is none. Each
    /// generator is a level as in the general `For`; the level yields an option and stops at
    /// its first success, and the whole is unwrapped where the call stands.
    fn rewriteFirst(self: *Workspace, rw: *Rewrite, at: usize, depth: usize) ParseError!usize {
        const keyword = self.tokens[at];
        if (depth >= rewrite_depth) return self.fail(keyword.span, .expression_limit);
        var bounds: [types.limits.record_fields + 3]usize = undefined;
        const call = try self.splitCall(keyword, at + 1, &bounds, .for_syntax);
        const items = call.items;
        if (items < 2) return self.fail(keyword.span, .for_syntax);
        const body = self.trimmed(bounds[items - 1], bounds[items] - 1);
        if (body[0] == body[1]) return self.fail(keyword.span, .for_syntax);
        var clauses: [max_checks + 1]ForClause = undefined;
        const count = items - 1;
        if (count > clauses.len) return self.fail(keyword.span, .for_syntax);
        for (0..count) |item| {
            const range = self.trimmed(bounds[item], bounds[item + 1] - 1);
            if (range[0] == range[1]) return self.fail(keyword.span, .for_syntax);
            clauses[item] = try self.forClause(range);
        }
        // `macroAt` saw a generator at the head; a body shaped like a clause has lost the body.
        std.debug.assert(clauses[0].kind == .generator or clauses[0].kind == .range);
        if ((try self.forClause(body)).kind != .filter) return self.fail(self.tokens[body[0]].span, .for_syntax);
        // Everything after the first source runs in the functions of the levels, which have no
        // state that could carry an exit out (RFC-0068 gives that to `For`, `While` and
        // `Loop{}` only), so a `Return` or `Break` that would leave the form is refused here,
        // by name, rather than taken for an exit of one of those functions.
        const exits = self.exitsIn(bounds[1], call.close);
        if (exits.returns or exits.breaks) return self.fail(self.tokens[exits.first].span, .first_exit);
        const site = try self.siteFor(keyword);
        // Only a module that uses the form carries its templates, and the pool of `Fn` words is
        // sized without it (`macros.callCount`), so its words are asked for in the same breath.
        if (!site.extension.first) return self.requestExtension(site, .{ .first = true, .words = site.extension.words + self.wordsNeeded(site.module) });
        const plan: ForPlan = .{ .clauses = clauses[0..count], .body = body, .first = true };
        // `(level)?`: the unwrap carries the span of `First`, so that a call outside a failure
        // context is reported at the call and not somewhere in the library block.
        try self.emitTo(rw, .{ .kind = .synthetic_first, .span = keyword.span });
        try self.emitTo(rw, .{ .kind = .left_paren, .span = keyword.span });
        try self.expandForGenerator(rw, site, &plan, 0, depth);
        try self.emitTo(rw, .{ .kind = .right_paren, .span = keyword.span });
        try self.emitTo(rw, .{ .kind = .question, .span = keyword.span });
        return call.close + 1;
    }

    /// Classifies one `For` argument: `Name:=value` binds, `Name:source` and `Key->Value:source`
    /// generate (`Low..High` at the top level of the source makes it a range), anything else filters.
    fn forClause(self: *Workspace, range: [2]usize) ParseError!ForClause {
        std.debug.assert(range[0] < range[1]);
        const first = self.tokens[range[0]];
        var cursor = range[0];
        var index_name: ?Token = null;
        if (cursor + 2 < range[1] and first.kind == .identifier and self.tokens[cursor + 1].kind == .minus and self.tokens[cursor + 2].kind == .greater and self.tokens[cursor + 1].span.end == self.tokens[cursor + 2].span.start) {
            index_name = first;
            cursor += 3;
            // After `Key->` only `Value:source` makes sense.
            if (cursor + 1 >= range[1] or self.tokens[cursor].kind != .identifier or self.tokens[cursor + 1].kind != .colon) return self.fail(first.span, .for_syntax);
        }
        if (cursor + 1 >= range[1] or self.tokens[cursor].kind != .identifier or self.tokens[cursor + 1].kind != .colon) return .{ .kind = .filter, .expr = range };
        const name = self.tokens[cursor];
        const colon = self.tokens[cursor + 1];
        if (cursor + 2 < range[1] and self.tokens[cursor + 2].kind == .equal and colon.span.end == self.tokens[cursor + 2].span.start) {
            if (index_name != null or cursor + 3 >= range[1]) return self.fail(first.span, .for_syntax);
            return .{ .kind = .binding, .name = name, .expr = .{ cursor + 3, range[1] } };
        }
        const source: [2]usize = .{ cursor + 2, range[1] };
        if (source[0] == source[1]) return self.fail(first.span, .for_syntax);
        // `..` is two adjacent dots outside every bracket of the source.
        var level: usize = 0;
        for (source[0]..source[1] - 1) |index| {
            const kind = self.tokens[index].kind;
            if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) level += 1;
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) level -|= 1;
            if (level != 0 or kind != .dot or self.tokens[index + 1].kind != .dot or self.tokens[index].span.end != self.tokens[index + 1].span.start) continue;
            // A range has both bounds and no key: its elements are their own positions.
            if (index == source[0] or index + 2 == source[1] or index_name != null) return self.fail(first.span, .for_syntax);
            return .{ .kind = .range, .name = name, .expr = .{ source[0], index }, .high = .{ index + 2, source[1] } };
        }
        return .{ .kind = .generator, .name = name, .index_name = index_name, .expr = source };
    }

    /// Where a `For` call is, in a way that survives a retry: library blocks grow between
    /// compiles of a bundle and move the modules after them, but not a call within its module.
    const ForKey = struct { module: u32, offset: u32 };
    /// An established `For` of this compile: its key and its extent in the source.
    /// `pending`: the pass in progress has noted it for the general lowering (`wantFor`).
    /// `filtered`: it has filters (RFC-0082, P3.8: a site in its body sends it to the general
    /// lowering without regions, `Parser.filteredForBody`).
    const ForCall = struct { key: ForKey, span: Span, pending: bool = false, filtered: bool = false };
    /// Every `For` defines at least two functions, so no program that compiles has more calls.
    const max_for_calls = types.limits.functions;
    /// A clause or the body of a `For` lowered without regions (RFC-0082, P3.8), and the
    /// `Token.site` of the code generated for that `For`.
    const SuspendClause = struct { span: Span, body: bool, site: u32 };

    fn forKey(self: *const Workspace, site: Site, keyword: Token) ForKey {
        const start: u32 = if (self.module_storage.module_count == 0) 0 else self.module_storage.modules[site.module].source.start;
        return .{ .module = site.module, .offset = keyword.span.start - start };
    }

    /// Whether an earlier compile of this source found that this call needs a failure context.
    fn forForced(self: *const Workspace, site: Site, keyword: Token) bool {
        const key = self.forKey(site, keyword);
        var low: usize = 0;
        var high: usize = self.for_forced_sorted;
        while (low < high) {
            const middle = low + (high - low) / 2;
            const entry = self.for_forced[middle];
            if (entry.module == key.module and entry.offset == key.offset) return true;
            if (optionBefore({}, entry, key)) low = middle + 1 else high = middle;
        }
        // The few that `forceFor` added since the known ones were last put in order.
        for (self.for_forced[self.for_forced_sorted..self.for_forced_count]) |forced| {
            if (forced.module == key.module and forced.offset == key.offset) return true;
        }
        return false;
    }

    /// RFC-0082, P3.8: whether `span` is the `Attempt` of the region of an iteration of a general
    /// `For`: the one of the template `for_try`, or the exit word a `For` that can be left uses
    /// for it (`expandExitFor`, its only use).
    fn forRegion(self: *const Workspace, span: Span) bool {
        const module = self.libraryModule(span) orelse return false;
        const extension = self.library_extension[module];
        const templates = self.library_templates[module];
        if (extension.loops and span.start == templates + extension.offset(.for_try)) return true;
        return extension.exits and span.start == templates + extension.exitWords() + self.exit_tokens[@backingInt(macros.ExitWord.attempt)].span.start;
    }

    /// Notes for the next compile the call whose keyword is written at `start`, which has a
    /// site in an iteration (`Parser.noteSuspendingFor`). False if no more can be noted.
    fn noteSuspended(self: *Workspace, start: u32) bool {
        const count = self.module_storage.module_count;
        const module: u32 = if (count == 0) 0 else modules.owner(self.keywordSpan(start), self.module_storage.modules[0..count]) orelse return false;
        const base: u32 = if (count == 0) 0 else self.module_storage.modules[module].source.start;
        const key: ForKey = .{ .module = module, .offset = start - base };
        const all = self.for_suspended[0 .. self.for_suspended_count + self.for_suspended_pending];
        for (all[self.for_suspended_count..]) |noted| if (noted.module == key.module and noted.offset == key.offset) return true;
        if (all.len == self.for_suspended.len) return false;
        self.for_suspended[all.len] = key;
        self.for_suspended_pending += 1;
        return true;
    }

    /// Whether an earlier compile of this source found a site in an iteration of this call.
    fn forSuspended(self: *const Workspace, site: Site, keyword: Token) bool {
        const key = self.forKey(site, keyword);
        var low: usize = 0;
        var high: usize = self.for_suspended_count;
        while (low < high) {
            const middle = low + (high - low) / 2;
            const entry = self.for_suspended[middle];
            if (entry.module == key.module and entry.offset == key.offset) return true;
            if (optionBefore({}, entry, key)) low = middle + 1 else high = middle;
        }
        return false;
    }

    /// Makes the calls the last pass noted for a site in an iteration known from now on, in key
    /// order; false when it noted none, and its result stands.
    fn adoptSuspendingFors(self: *Workspace) bool {
        if (self.for_suspended_pending == 0) return false;
        const known = self.for_suspended[0 .. self.for_suspended_count + self.for_suspended_pending];
        self.for_suspended_pending = 0;
        std.sort.pdq(ForKey, known, {}, optionBefore);
        self.for_suspended_count = distinctKeys(known);
        return true;
    }

    /// Remembers an established call, so that a `failure_context_required` inside it can be
    /// answered by compiling it again as a general `For`. Calls beyond the capacity are not
    /// remembered: such a program has too many functions to compile anyway.
    fn recordFor(self: *Workspace, site: Site, keyword: Token, end: u32, filtered: bool) void {
        std.debug.assert(keyword.span.start < end);
        if (self.for_call_count == self.for_calls.len) return;
        // Calls are met in source order, a call before the calls inside it; `wantFor` relies
        // on that only while it holds.
        if (self.for_call_count == 0) self.for_calls_ordered = true else if (self.for_calls[self.for_call_count - 1].span.start >= keyword.span.start) self.for_calls_ordered = false;
        self.for_calls[self.for_call_count] = .{ .key = self.forKey(site, keyword), .span = .{ .start = keyword.span.start, .end = end }, .filtered = filtered };
        self.for_call_count += 1;
    }

    /// The compile failed because something that can fail is outside a failure context. If
    /// that is inside an established `For`, an iteration of a `For` is such a context
    /// (RFC-0064): the innermost such call is marked for the general lowering and the caller
    /// compiles again. Only programs that did not compile before RFC-0064 get here, so every
    /// program that did keeps its lowering exactly.
    fn forceFor(self: *Workspace) bool {
        if (self.diagnostic.code != .failure_context_required) return false;
        const at = self.diagnostic.span;
        var chosen: ?ForCall = null;
        for (self.for_calls[0..self.for_call_count]) |call| {
            if (call.span.start > at.start or at.end > call.span.end) continue;
            if (chosen == null or call.span.end - call.span.start < chosen.?.span.end - chosen.?.span.start) chosen = call;
        }
        const call = chosen orelse return false;
        if (self.for_forced_count == self.for_forced.len) return false;
        self.for_forced[self.for_forced_count] = call.key;
        self.for_forced_count += 1;
        return true;
    }

    /// The established call whose keyword starts at `start`, as an index into `for_calls`.
    fn forCallAt(self: *const Workspace, start: u32) u32 {
        const calls = self.for_calls[0..self.for_call_count];
        if (!self.for_calls_ordered) {
            for (calls, 0..) |call, index| if (call.span.start == start) return @intCast(index);
            return no_member;
        }
        var low: usize = 0;
        var high: usize = calls.len;
        while (low < high) {
            const middle = low + (high - low) / 2;
            if (calls[middle].span.start == start) return @intCast(middle);
            if (calls[middle].span.start < start) low = middle + 1 else high = middle;
        }
        return no_member;
    }

    /// The established call a generated `Fn` belongs to: a template's functions carry the
    /// call they were generated for (`Token.site`), and the user's own `Fn` carries none.
    fn forCallOf(self: *const Workspace, token: Token) u32 {
        if (token.site == 0 or self.for_call_count == 0 or self.libraryModule(token.span) == null) return no_member;
        return self.forCallAt(token.site - 1);
    }

    /// The innermost established call around `at` that this pass has not noted yet: what
    /// `forceFor` picks for a diagnostic at `at` once the noted ones are lowered generally.
    fn forAround(self: *const Workspace, at: Span) u32 {
        const calls = self.for_calls[0..self.for_call_count];
        if (!self.for_calls_ordered) {
            var chosen: u32 = no_member;
            for (calls, 0..) |call, index| {
                if (call.pending or call.span.start > at.start or at.end > call.span.end) continue;
                if (chosen == no_member or call.span.end - call.span.start < calls[chosen].span.end - calls[chosen].span.start) chosen = @intCast(index);
            }
            return chosen;
        }
        // The last call that starts at or before `at`, then outwards: of the calls around a
        // position the innermost starts last.
        var low: usize = 0;
        var high: usize = calls.len;
        while (low < high) {
            const middle = low + (high - low) / 2;
            if (calls[middle].span.start <= at.start) low = middle + 1 else high = middle;
        }
        while (low != 0) {
            low -= 1;
            if (!calls[low].pending and at.end <= calls[low].span.end) return @intCast(low);
        }
        return no_member;
    }

    /// Where in the source the token at `index` of the stream being parsed stands, as a
    /// diagnostic about it would say: its own span, or for a generated token the keyword of
    /// the call it was generated for. Null for a generated token that knows no call.
    fn sourcePlace(self: *const Workspace, index: usize) ?Span {
        const token = self.tokens[index];
        if (self.libraryModule(token.span) == null) return if (token.span.start < token.span.end) token.span else null;
        return if (token.site == 0) null else self.keywordSpan(token.site - 1);
    }

    /// Something that can fail is being parsed outside every failure context, and neither an
    /// `option{...}` nor a condition takes it. If it stands in an established `For`, the
    /// compile would end here with `failure_context_required`, `forceFor` would send the
    /// innermost such call to the general lowering, and the next compile would get one loop
    /// further: a compile per loop. Instead the call is noted and the parse goes on as if in
    /// a failure context, which is what the iteration of that call is once it is lowered
    /// generally; the program of this parse is never used. The caller compiles again
    /// (`adoptFors`) with every call noted in this pass lowered generally, so the number of
    /// compiles does not grow with the number of loops.
    ///
    /// What is noted is what the compiles one at a time would have forced, in the same order:
    /// while the position is not directly inside a noted call's body or filter, the innermost
    /// call around it that is not noted yet is noted, as `forceFor` would pick it for the
    /// diagnostic of the next compile; when no call is left the parse fails as it would have.
    /// The position is taken from the token just read and the one being read. Where the two
    /// disagree about the call, nothing is noted and `forceFor` decides from the diagnostic.
    fn wantFor(self: *Workspace) bool {
        if (self.for_one_at_a_time or self.for_call_count == 0 or self.token_count == 0) return false;
        const cursor = @min((self.parse_cursor orelse return false).*, self.token_count - 1);
        const read = self.sourcePlace(cursor -| 1);
        const next = self.sourcePlace(cursor);
        while (true) {
            if (self.anonymous_count != 0) {
                const own = self.anonymous_frames[self.anonymous_count - 1].for_call;
                if (own != no_member and self.for_calls[own].pending) {
                    // The function being parsed is the body or filter of a noted call: once
                    // that call is lowered generally this point is inside its attempt.
                    const around = self.for_calls[own].span;
                    const place = read orelse next orelse return false;
                    if (around.start <= place.start and place.end <= around.end) return true;
                }
            }
            const first = if (read) |place| self.forAround(place) else no_member;
            const second = if (next) |place| self.forAround(place) else no_member;
            const chosen = if (read == null) second else if (next == null) first else if (first == second) first else return false;
            if (chosen == no_member) return false;
            if (self.for_forced_count + self.for_pending == self.for_forced.len) return false;
            self.for_forced[self.for_forced_count + self.for_pending] = self.for_calls[chosen].key;
            self.for_pending += 1;
            self.for_calls[chosen].pending = true;
        }
    }

    /// Makes the calls the last pass noted known from now on, and puts the known ones in key
    /// order; false when it noted none, and its result stands.
    fn adoptFors(self: *Workspace) bool {
        const noted = self.for_pending != 0;
        if (!noted and self.for_forced_sorted == self.for_forced_count) return false;
        const known = self.for_forced[0 .. self.for_forced_count + self.for_pending];
        self.for_pending = 0;
        std.sort.pdq(ForKey, known, {}, optionBefore);
        self.for_forced_count = distinctKeys(known);
        self.for_forced_sorted = self.for_forced_count;
        return noted;
    }

    /// An `option{...}` outside every failure context that the parser is inside of: where it
    /// is, the function body it was opened in (`anonymous_count` then), and what was decided
    /// when something that can fail was found directly inside it.
    const OptionCall = struct { key: ForKey, start: u32, frame: u32, state: enum { open, wanted, refused } = .open };
    /// A constructor that holds something failable has at least five tokens (`option{X?}`), so
    /// no program has more distinct ones than this. One in a generic body is noted again by each
    /// specialization; `wantOption` drops the repeats when the room is used up, so no
    /// constructor is turned away for want of it.
    const max_caught_options = types.limits.tokens / 4;

    /// Where the `option` of a constructor is, in a way that survives a retry (see `ForKey`).
    /// Constructors in generated text are never candidates.
    fn optionKey(self: *const Workspace, span: Span) ?ForKey {
        if (self.libraryModule(span) != null) return null;
        const count = self.module_storage.module_count;
        if (count == 0) return .{ .module = 0, .offset = span.start };
        const module = modules.owner(span, self.module_storage.modules[0..count]) orelse return null;
        return .{ .module = module, .offset = span.start - self.module_storage.modules[module].source.start };
    }

    /// Whether `span` is the `Attempt` of the template that runs one iteration of a `First`.
    fn firstRegion(self: *const Workspace, span: Span) bool {
        const module = self.libraryModule(span) orelse return false;
        const extension = self.library_extension[module];
        return extension.first and span.start == self.library_templates[module] + extension.offset(.first_try);
    }

    fn optionBefore(_: void, a: ForKey, b: ForKey) bool {
        return if (a.module != b.module) a.module < b.module else a.offset < b.offset;
    }

    /// Whether an earlier compile of this source found that this constructor must catch.
    fn optionCaught(self: *const Workspace, key: ForKey) bool {
        var low: usize = 0;
        var high: usize = self.option_caught_count;
        while (low < high) {
            const middle = low + (high - low) / 2;
            const entry = self.option_caught[middle];
            if (entry.module == key.module and entry.offset == key.offset) return true;
            if (optionBefore({}, entry, key)) low = middle + 1 else high = middle;
        }
        return false;
    }

    /// Something that can fail is being parsed outside every failure context. `option{E}`
    /// turns the failure of `E` into the empty option (RFC-0072), so if the parser is directly
    /// inside such a constructor (in the same function body), that constructor is what the
    /// program lacks: it is noted, and the parse goes on as if in a failure context. The
    /// program of that parse is never used. The caller compiles again (`adoptOptions`) with
    /// every constructor noted in this pass opening a region, so the number of compiles does
    /// not grow with the number of constructors. Only a program that did not compile before
    /// RFC-0072 gets here, so every program that did keeps its IR exactly.
    fn wantOption(self: *Workspace) bool {
        if (self.option_open_count == 0) return false;
        const call = &self.option_open[self.option_open_count - 1];
        // A function body inside the constructor is its own context: its failures are not caught.
        if (call.frame != self.anonymous_count) return false;
        if (call.state != .open) return call.state == .wanted;
        call.state = .refused;
        if (self.option_caught_count + self.option_pending == self.option_caught.len) {
            // A constructor in a generic body is noted once for each specialization: make room
            // by keeping one note of each. Distinct constructors always fit.
            const pending = self.option_caught[self.option_caught_count..];
            std.sort.pdq(ForKey, pending, {}, optionBefore);
            self.option_pending = distinctKeys(pending);
            if (self.option_caught_count + self.option_pending == self.option_caught.len) return false;
        }
        self.option_caught[self.option_caught_count + self.option_pending] = call.key;
        self.option_pending += 1;
        call.state = .wanted;
        return true;
    }

    /// Moves the distinct keys of a sorted run to its front and returns how many there are.
    fn distinctKeys(keys: []ForKey) u32 {
        var kept: u32 = 0;
        for (keys) |key| {
            if (kept != 0 and keys[kept - 1].module == key.module and keys[kept - 1].offset == key.offset) continue;
            keys[kept] = key;
            kept += 1;
        }
        return kept;
    }

    /// Makes the constructors the last pass noted catch from now on; false when it noted none,
    /// and its result stands.
    fn adoptOptions(self: *Workspace) bool {
        if (self.option_pending == 0) return false;
        const noted = self.option_caught[0 .. self.option_caught_count + self.option_pending];
        self.option_pending = 0;
        std.sort.pdq(ForKey, noted, {}, optionBefore);
        self.option_caught_count = distinctKeys(noted);
        return true;
    }

    /// An `If` whose condition can fail holds, at the least, the six tokens of `If(A?,B,C)`
    /// around its three arguments, so no program has more conditions to note than this.
    const max_forced_conditions = types.limits.tokens / 8;

    /// Whether an earlier compile found that the condition starting at token `first` must be
    /// a failable condition.
    fn conditionForced(self: *const Workspace, first: usize) bool {
        if (self.condition_forced_count == 0 or first < 2 or first >= self.token_count) return false;
        const key = self.conditionKey(self.conditionPlace(self.tokens[first - 2].span, self.tokens[first].span)) orelse return false;
        return self.conditionKnown(key);
    }

    /// What a condition is known by across compiles: the `If` the user wrote, or, for an `If`
    /// that is generated (the conditions of a `While`), the first token of the condition if
    /// that is the user's. Twice the position, plus one for the second kind, so that a
    /// condition which begins with an `If` of its own is not taken for that `If`'s. Zero for
    /// a condition that is generated from its keyword to its first token (the tests of a
    /// `Case`): it has no place of its own.
    fn conditionPlace(self: *const Workspace, keyword: Span, first: Span) u64 {
        if (self.libraryModule(keyword) == null and std.mem.eql(u8, keyword.text(self.source), "If")) return 2 * @as(u64, keyword.start) + 2;
        if (self.libraryModule(first) == null and first.start < first.end) return 2 * @as(u64, first.start) + 3;
        return 0;
    }

    fn conditionKey(self: *const Workspace, place: u64) ?ForKey {
        if (place == 0) return null;
        const position: u32 = @intCast((place - 2) / 2);
        var key = self.optionKey(zeroWidth(position)) orelse return null;
        key.offset = 2 * key.offset + @as(u32, @intCast(place & 1));
        return key;
    }

    fn conditionKnown(self: *const Workspace, key: ForKey) bool {
        var low: usize = 0;
        var high: usize = self.condition_forced_count;
        while (low < high) {
            const middle = low + (high - low) / 2;
            const entry = self.condition_forced[middle];
            if (entry.module == key.module and entry.offset == key.offset) return true;
            if (optionBefore({}, entry, key)) low = middle + 1 else high = middle;
        }
        return false;
    }

    /// Something that can fail is being parsed outside every failure context, in the condition
    /// of an `If` whose text starts at `start`, and nothing in that text told
    /// `failableCondition` so (a lone `?` has no bracket). The Book's condition is a failure
    /// context (RFC-0049), so the condition is noted and the parse goes on as if it were one;
    /// the caller compiles again (`adoptConditions`) with every condition noted in this pass
    /// wrapped as the bracketed ones are, so the number of compiles does not grow with the
    /// number of conditions. Only a program that did not compile before gets here, so every
    /// program that did keeps its meaning and its IR.
    fn wantCondition(self: *Workspace, place: u64) bool {
        // A condition in generated text has no place of its own to be known by.
        const key = self.conditionKey(place) orelse return false;
        // One that is forced and still asks is exempt (`Require`, `Fail`): the error stands.
        if (self.conditionKnown(key)) return false;
        const pending = self.condition_forced[self.condition_forced_count..][0..self.condition_pending];
        // A condition with several unwraps asks once for each.
        if (pending.len != 0 and pending[pending.len - 1].module == key.module and pending[pending.len - 1].offset == key.offset) return true;
        if (self.condition_forced_count + self.condition_pending == self.condition_forced.len) {
            // One in a generic body is noted once for each specialization: make room by keeping
            // one note of each. Distinct conditions always fit.
            std.sort.pdq(ForKey, pending, {}, optionBefore);
            self.condition_pending = distinctKeys(pending);
            if (self.condition_forced_count + self.condition_pending == self.condition_forced.len) return false;
        }
        self.condition_forced[self.condition_forced_count + self.condition_pending] = key;
        self.condition_pending += 1;
        return true;
    }

    /// Makes the conditions the last pass noted failable from now on; false when it noted
    /// none, and its result stands.
    fn adoptConditions(self: *Workspace) bool {
        if (self.condition_pending == 0) return false;
        const noted = self.condition_forced[0 .. self.condition_forced_count + self.condition_pending];
        self.condition_pending = 0;
        std.sort.pdq(ForKey, noted, {}, optionBefore);
        self.condition_forced_count = distinctKeys(noted);
        return true;
    }

    /// A path assignment has at least the six tokens of `set A[0]=1`.
    const max_carry_sites = types.limits.tokens / 6;

    /// Whether an earlier compile found that the path assignment whose target is written at
    /// `span` updated nothing.
    fn carrySite(self: *const Workspace, span: Span) bool {
        if (self.carry_site_count == 0) return false;
        const key = self.optionKey(span) orelse return false;
        var low: usize = 0;
        var high: usize = self.carry_site_count;
        while (low < high) {
            const middle = low + (high - low) / 2;
            const entry = self.carry_sites[middle];
            if (entry.module == key.module and entry.offset == key.offset) return true;
            if (optionBefore({}, entry, key)) low = middle + 1 else high = middle;
        }
        return false;
    }

    /// `set Name.Field=V` or `set Name[I]=V` at `span` updated no instance and `Name` cannot be
    /// assigned where it stands. In the body of a `For` that is what a local of the code around
    /// the loop looks like: the body is a function and sees a copy. Whether `Name` is such a
    /// local is a question of types, so it is answered here and not where tokens are rewritten:
    /// the assignment is noted and the parse goes on as if it had been made. The caller compiles
    /// again (`adoptCarries`) and every `For` around a noted assignment carries its target
    /// (`forVariables`), so the number of compiles does not grow with the number of loops. A
    /// noted assignment that lies in no `For`, or whose target is no `var` local, fails the next
    /// compile as it would have failed this one. Only a program that did not compile gets here.
    fn wantCarry(self: *Workspace, span: Span) bool {
        const key = self.optionKey(span) orelse return false;
        if (self.carrySite(span)) return false;
        const pending = self.carry_sites[self.carry_site_count..][0..self.carry_pending];
        if (self.carry_site_count + self.carry_pending == self.carry_sites.len) {
            // One in a generic body is noted once for each specialization: keep one note of each.
            std.sort.pdq(ForKey, pending, {}, optionBefore);
            self.carry_pending = distinctKeys(pending);
            if (self.carry_site_count + self.carry_pending == self.carry_sites.len) return false;
        }
        self.carry_sites[self.carry_site_count + self.carry_pending] = key;
        self.carry_pending += 1;
        return true;
    }

    /// Makes the path assignments the last pass noted known from now on; false when it noted
    /// none, and its result stands.
    fn adoptCarries(self: *Workspace) bool {
        if (self.carry_pending == 0) return false;
        const noted = self.carry_sites[0 .. self.carry_site_count + self.carry_pending];
        self.carry_pending = 0;
        std.sort.pdq(ForKey, noted, {}, optionBefore);
        self.carry_site_count = distinctKeys(noted);
        return true;
    }

    /// A `Defer` has at least the four tokens of `Defer{X}`.
    const max_landing_keys = types.limits.tokens / 4;

    /// Whether an earlier compile found the `Defer` whose word stands at `span` open at a site.
    fn landingKnown(self: *const Workspace, span: Span) bool {
        if (self.landing_key_count == 0) return false;
        const key = self.optionKey(span) orelse return false;
        var low: usize = 0;
        var high: usize = self.landing_key_count;
        while (low < high) {
            const middle = low + (high - low) / 2;
            const entry = self.landing_keys[middle];
            if (entry.module == key.module and entry.offset == key.offset) return true;
            if (optionBefore({}, entry, key)) low = middle + 1 else high = middle;
        }
        return false;
    }

    /// The `Defer` whose word stands at `span` is open at a suspension site (RFC-0082, P3.3): a
    /// cancellation there runs its body, which is not compiled as a function yet. Which sites
    /// are sites is known only to the parser (a call is one by its callee), and the copies of a
    /// `Defer` are written by the macro pass before it, so the `Defer` is noted and the parse
    /// goes on; the caller compiles again (`adoptLandings`) with a copy of the body of every
    /// noted `Defer` after its mark, which the parser compiles as that function. One more
    /// compile, whatever the number of `Defer`s; a program with none open at a site has none.
    fn wantLanding(self: *Workspace, span: Span) bool {
        const key = self.optionKey(span) orelse return false;
        // A known one has its copy after its mark, compiled there: a site that finds none was
        // not written by this compiler's macro pass.
        if (self.landingKnown(span)) return false;
        const pending = self.landing_keys[self.landing_key_count..][0..self.landing_pending];
        if (pending.len != 0 and pending[pending.len - 1].module == key.module and pending[pending.len - 1].offset == key.offset) return true;
        if (self.landing_key_count + self.landing_pending == self.landing_keys.len) {
            // One in a generic body is noted once for each specialization: keep one note of each.
            std.sort.pdq(ForKey, pending, {}, optionBefore);
            self.landing_pending = distinctKeys(pending);
            if (self.landing_key_count + self.landing_pending == self.landing_keys.len) return false;
        }
        self.landing_keys[self.landing_key_count + self.landing_pending] = key;
        self.landing_pending += 1;
        return true;
    }

    /// Makes the `Defer`s the last pass noted known from now on, if that pass compiled a program
    /// in which a task can be cancelled (`structured_compiled`): a program that failed keeps its
    /// diagnostic, and one with no `Sync` or `Race` its IR, whose landings no task can take.
    /// False when it noted none, or the notes are dropped.
    fn adoptLandings(self: *Workspace, compiled: bool) bool {
        if (self.landing_pending == 0) return false;
        if (!compiled) {
            self.landing_pending = 0;
            return false;
        }
        const noted = self.landing_keys[0 .. self.landing_key_count + self.landing_pending];
        self.landing_pending = 0;
        std.sort.pdq(ForKey, noted, {}, optionBefore);
        self.landing_key_count = distinctKeys(noted);
        return true;
    }

    /// A local `var` declaration has at least the six tokens of `var X:i64=0`.
    const max_share_keys = types.limits.tokens / 6;

    /// Whether an earlier compile found the local `var` whose name stands at `span` shared
    /// (RFC-0085, S1).
    fn shareKnown(self: *const Workspace, span: Span) bool {
        if (self.share_key_count == 0) return false;
        const key = self.optionKey(span) orelse return false;
        var low: usize = 0;
        var high: usize = self.share_key_count;
        while (low < high) {
            const middle = low + (high - low) / 2;
            const entry = self.share_keys[middle];
            if (entry.module == key.module and entry.offset == key.offset) return true;
            if (optionBefore({}, entry, key)) low = middle + 1 else high = middle;
        }
        return false;
    }

    /// RFC-0085, "How the compiler decides S1": a use shares the local `var` whose name stands
    /// at `span`, which was declared before the use was read. The declaration is noted and the
    /// parse goes on as if the use had not shared it; the caller compiles again
    /// (`adoptShares`) and the declaration makes a variable cell. False when it is known
    /// already (a use that finds the local not shared then was not written by this compiler)
    /// or there is no room, and the use fails as it did before sharing.
    fn wantShare(self: *Workspace, span: Span) bool {
        const key = self.optionKey(span) orelse return false;
        if (self.shareKnown(span)) return false;
        const pending = self.share_keys[self.share_key_count..][0..self.share_pending];
        if (pending.len != 0 and pending[pending.len - 1].module == key.module and pending[pending.len - 1].offset == key.offset) return true;
        if (self.share_key_count + self.share_pending == self.share_keys.len) {
            // One in a generic body is noted once for each specialization: keep one note of each.
            std.sort.pdq(ForKey, pending, {}, optionBefore);
            self.share_pending = distinctKeys(pending);
            if (self.share_key_count + self.share_pending == self.share_keys.len) return false;
        }
        self.share_keys[self.share_key_count + self.share_pending] = key;
        self.share_pending += 1;
        return true;
    }

    /// Makes the declarations the last pass noted shared from now on; false when it noted none,
    /// and its result stands. A pass that noted one compiled its uses as copies, so whatever
    /// it produced, a program or a diagnostic, is not the program's.
    fn adoptShares(self: *Workspace) bool {
        if (self.share_pending == 0) return false;
        const noted = self.share_keys[0 .. self.share_key_count + self.share_pending];
        self.share_pending = 0;
        std.sort.pdq(ForKey, noted, {}, optionBefore);
        self.share_key_count = distinctKeys(noted);
        return true;
    }

    /// Whether the `var` named `name` in a scope open at token `at` is shared (RFC-0085, S2):
    /// no loop carries it, since its body reaches the cell through its captures. The walk is
    /// that of `enclosingVar`; a program that shares nothing never takes it.
    fn sharedVar(self: *Workspace, at: usize, name: []const u8) bool {
        if (self.share_key_count == 0) return false;
        var outside = self.depthAt(at);
        var closed: usize = 0;
        var index = at;
        while (index != 0) {
            index -= 1;
            if (self.moduleBrace(self.tokens[index])) break;
            switch (self.tokens[index].kind) {
                .right_paren, .right_bracket, .right_brace => closed += 1,
                .left_paren, .left_bracket, .left_brace => {
                    if (closed != 0) closed -= 1 else outside -|= 1;
                },
                .newline, .separator => if (closed == 0 and outside == 0) break,
                .identifier => {
                    // No shadowing: the first declaration of the name in an open scope is it.
                    if (closed == 0 and outside != 0 and index + 1 < at and self.tokens[index + 1].kind == .identifier and self.isName(index, "var") and std.mem.eql(u8, self.tokens[index + 1].span.text(self.source), name)) return self.shareKnown(self.tokens[index + 1].span);
                },
                else => {},
            }
        }
        return false;
    }

    /// The locals that the clauses and body of a `For`, `[from, to)`, assign and do not
    /// declare, and that are not source cells: what the loop carries (RFC-0064, "Assigned
    /// locals"). A plain `set Name=V` on such a name never compiled in a `For`, whose body is a
    /// function, so carrying it changes no program that did. A path assignment
    /// (`set Name[I]=V`, which is `set Name=...` by now) did compile where `Name` holds a class
    /// instance, which is updated in place and needs no carrying: it counts only once a compile
    /// has shown that it updates nothing (`wantCarry`).
    ///
    /// A name is carried only if a `var` of that name is declared in a scope around the loop
    /// (`enclosingVar`) and nothing in the loop binds it: a generator, a key, a binding clause,
    /// a parameter or a typed name of that spelling (`boundBetween`) is what the body means by
    /// the name, and assigning that is the diagnostic it always was. `at` is the `For`.
    fn forVariables(self: *Workspace, keyword: Token, at: usize, from: usize, to: usize, variables: *[max_exit_variables]Token) ParseError!usize {
        var count: usize = 0;
        self.for_shared = false;
        for (from..to) |index| {
            if (self.tokens[index].kind != .identifier or index + 3 >= to or !self.isName(index, "set")) continue;
            const target = self.tokens[index + 1];
            if (target.kind != .identifier or self.tokens[index + 2].kind != .equal) continue;
            const value = self.tokens[index + 3].kind;
            if ((value == .synthetic_with_field or value == .synthetic_with_index) and !self.carrySite(target.span)) continue;
            const name = target.span.text(self.source);
            var known = false;
            for (variables[0..count]) |earlier| known = known or std.mem.eql(u8, earlier.span.text(self.source), name);
            if (known or self.declaredBetween(from, to, name) or self.boundBetween(at + 2, to, name) or self.isSourceCell(name) or !self.enclosingVar(at, name)) continue;
            // RFC-0085, S2: the body reaches a shared local through its captures.
            if (self.sharedVar(at, name)) {
                self.for_shared = true;
                continue;
            }
            if (count == variables.len) return self.fail(keyword.span, .parameter_limit);
            variables[count] = target;
            count += 1;
        }
        return count;
    }

    /// Whether `[from, to)` binds `name` other than by `var`: `name:` (a generator, a binding
    /// `name:=`, a parameter, a typed local, a typed pattern) or `name->` (the key of a
    /// generator). A named argument or a field of a literal spelled like an outer local counts
    /// too: the loop then leaves that local alone, and assigning it is refused as before.
    fn boundBetween(self: *const Workspace, from: usize, to: usize, name: []const u8) bool {
        for (from..to -| 1) |index| {
            const token = self.tokens[index];
            if (token.kind != .identifier) continue;
            const next = self.tokens[index + 1];
            const binds = next.kind == .colon or (next.kind == .minus and index + 2 < to and self.tokens[index + 2].kind == .greater and next.span.end == self.tokens[index + 2].span.start);
            if (binds and std.mem.eql(u8, token.span.text(self.source), name)) return true;
        }
        return false;
    }

    /// How many brackets are open at token `at` of the round of `desugarMacros` in progress.
    /// The calls of a round are met in order, so the count goes on from the last one asked.
    fn depthAt(self: *Workspace, at: usize) usize {
        if (at < self.depth_index) {
            self.depth_index = 0;
            self.depth_value = 0;
        }
        while (self.depth_index < at) : (self.depth_index += 1) {
            // The braces of a nested module open no scope: its body is a top level (RFC-0074).
            if (self.moduleBrace(self.tokens[self.depth_index])) continue;
            switch (self.tokens[self.depth_index].kind) {
                .left_paren, .left_bracket, .left_brace => self.depth_value += 1,
                .right_paren, .right_bracket, .right_brace => self.depth_value -|= 1,
                else => {},
            }
        }
        return self.depth_value;
    }

    /// Whether a `var` named `name` is declared in a scope that is open at token `at`: in a
    /// block around it, before it. Going back from `at`, what lies in brackets that have closed
    /// is another scope and is passed over; the walk ends where the declaration at the top
    /// level that holds `at` begins (a `var` there is a source cell, which is not carried).
    ///
    /// This is the rule of `writesThrough`, read backwards. The body of a nested module is a
    /// top level too (RFC-0074), so its braces are where the walk ends and its cells are no
    /// locals; and a `var` directly inside a class body is a field, which is reached through
    /// an instance and never carried.
    fn enclosingVar(self: *Workspace, at: usize, name: []const u8) bool {
        var outside = self.depthAt(at);
        var closed: usize = 0;
        var index = at;
        // A `var` of the name one bracket in: a local, unless that bracket is a class body,
        // which is known only where the declaration begins.
        var candidate = false;
        var class_body = false;
        while (index != 0) {
            index -= 1;
            if (self.moduleBrace(self.tokens[index])) break;
            switch (self.tokens[index].kind) {
                .right_paren, .right_bracket, .right_brace => closed += 1,
                .left_paren, .left_bracket, .left_brace => {
                    if (closed != 0) closed -= 1 else outside -|= 1;
                },
                .newline, .separator => if (closed == 0 and outside == 0) break,
                .identifier => {
                    if (closed == 0 and outside == 0 and (self.isName(index, "class") or self.isName(index, "interface"))) class_body = true;
                    if (closed == 0 and outside != 0 and index + 1 < at and self.tokens[index + 1].kind == .identifier and self.isName(index, "var") and std.mem.eql(u8, self.tokens[index + 1].span.text(self.source), name)) {
                        if (outside != 1) return true;
                        candidate = true;
                    }
                },
                else => {},
            }
        }
        return candidate and !class_body;
    }

    /// The index of the names declared `var` at the top level, or null when the host has no
    /// memory for one; `isSourceCell` then looks through the tokens as it always did.
    fn cellNames(self: *Workspace) ?*name_index.Index {
        if (self.cell_names_tried) return if (self.cell_names) |*names| names else null;
        self.cell_names_tried = true;
        var declared: usize = 0;
        var depth: usize = 0;
        for (0..self.token_count) |index| {
            // The braces of a nested module do not hide its cells: its body is a top level too.
            if (self.moduleBrace(self.tokens[index])) continue;
            switch (self.tokens[index].kind) {
                .left_paren, .left_bracket, .left_brace => depth += 1,
                .right_paren, .right_bracket, .right_brace => depth -|= 1,
                else => {},
            }
            if (depth == 0 and self.isName(index, "var") and index + 1 < self.token_count and self.tokens[index + 1].kind == .identifier) declared += 1;
        }
        const spans = scratch.alloc(Span, declared) orelse return null;
        var names = name_index.Index.create(declared) orelse {
            scratch.free(spans);
            return null;
        };
        var entered: u32 = 0;
        depth = 0;
        for (0..self.token_count) |index| {
            if (self.moduleBrace(self.tokens[index])) continue;
            switch (self.tokens[index].kind) {
                .left_paren, .left_bracket, .left_brace => depth += 1,
                .right_paren, .right_bracket, .right_brace => depth -|= 1,
                else => {},
            }
            if (!(depth == 0 and self.isName(index, "var") and index + 1 < self.token_count and self.tokens[index + 1].kind == .identifier)) continue;
            const span = self.tokens[index + 1].span;
            spans[entered] = span;
            // Namesakes share a probe; one entry answers for all of them.
            var probe = names.probe(name_index.hashName(0, span.text(self.source)));
            while (probe.next()) |_| {}
            probe.claim(entered);
            entered += 1;
        }
        std.debug.assert(entered == declared);
        self.cell_spans = spans;
        self.cell_names = names;
        return &self.cell_names.?;
    }

    fn dropCellNames(self: *Workspace) void {
        if (self.cell_names) |names| {
            names.destroy();
            scratch.free(self.cell_spans);
        }
        self.cell_names = null;
        self.cell_spans = &.{};
        self.cell_names_tried = false;
    }

    /// One generator of a general `For`: a function of what it binds that returns the array the
    /// clauses after it produce, called for each element in order with the results joined.
    fn expandForGenerator(self: *Workspace, rw: *Rewrite, site: Site, plan: *const ForPlan, index: usize, depth: usize) ParseError!void {
        const clause = plan.clauses[index];
        std.debug.assert(clause.kind == .generator or clause.kind == .range);
        const template: macros.Template = if (plan.first)
            (if (clause.kind == .range) .first_range else if (clause.index_name != null) .first_gen_indexed else .first_gen)
        else if (plan.variables.len != 0)
            (if (clause.kind == .range) .for_carry_range else if (clause.index_name != null) .for_carry_indexed else .for_carry)
        else if (clause.kind == .range) .for_range else if (clause.index_name != null) .for_gen_indexed else .for_gen;
        // An inner generator's source runs in the iteration around it (RFC-0082, P3.8).
        if (plan.suspends and index != 0) self.noteSuspendClause(site, self.forClauseSpan(clause), false);
        try self.expandTemplate(rw, site, template, &.{
            .name = clause.name,
            .index_name = clause.index_name,
            .first = clause.expr,
            .third = clause.high,
            .rest = .{ .plan = plan, .next = index + 1, .checked = false },
            .variables = plan.variables,
        }, depth);
    }

    /// The clauses of a general `For` from `rest.next` on: the bindings and filters up to the next
    /// generator or the body, inside an attempt together with whatever follows (so a failure
    /// skips the iteration and undoes its writes), then that generator or body.
    fn expandForRest(self: *Workspace, rw: *Rewrite, site: Site, rest: ForRest, depth: usize) ParseError!void {
        if (depth >= rewrite_depth) return self.fail(site.keyword.span, .expression_limit);
        const clauses = rest.plan.clauses;
        var stop = rest.next;
        while (stop < clauses.len and (clauses[stop].kind == .binding or clauses[stop].kind == .filter)) stop += 1;
        if (!rest.checked and rest.plan.suspends) return self.expandForRestFree(rw, site, rest, stop, depth);
        if (!rest.checked) {
            // Whether the next source or the body can fail is a question of types, which do not
            // exist yet, so every iteration gets its region.
            var checks: [max_checks]Check = undefined;
            for (clauses[rest.next..stop], 0..) |clause, item| checks[item] = .{ .name = clause.name, .expr = clause.expr };
            return self.expandTemplate(rw, site, if (rest.plan.first) .first_try else .for_try, &.{
                .checks = checks[0 .. stop - rest.next],
                .rest = .{ .plan = rest.plan, .next = rest.next, .checked = true },
            }, depth);
        }
        if (stop < clauses.len) {
            // A level of a `First` yields an option; the iteration around it fails when that is empty.
            if (rest.plan.first and !rest.opened) return self.expandTemplate(rw, site, .first_inner, &.{
                .rest = .{ .plan = rest.plan, .next = rest.next, .checked = true, .opened = true },
            }, depth);
            return self.expandForGenerator(rw, site, rest.plan, stop, depth);
        }
        if (rest.plan.suspends) self.noteSuspendClause(site, self.userSpan(rest.plan.body), true);
        try self.expandTemplate(rw, site, if (rest.plan.first) .first_yield else .for_yield, &.{ .second = rest.plan.body }, depth);
    }

    /// RFC-0082, P3.8: the bindings and filters of an iteration of a `For` whose body holds a
    /// site, without the region `for_try` gives them, so that no region is open at the site:
    /// `Block{ Y:=(V); __for_keep:=(F); If(__for_keep, Block{ ... Rest }, array{}) }`. A
    /// binding is a binding; a filter is bound first, outside every failure context, so that
    /// one that can fail is refused, and then its value chooses between the rest of the
    /// iteration and nothing. What can fail in a clause is refused there (`suspending_for_fails`).
    fn expandForRestFree(self: *Workspace, rw: *Rewrite, site: Site, rest: ForRest, stop: usize, depth: usize) ParseError!void {
        const here = site.keyword.span;
        const block = self.templateWord(site, .for_try, "Block");
        const keep = self.templateWord(site, .for_filter, "__for_keep");
        try self.emitTo(rw, block);
        try self.emitKind(rw, .left_brace, here);
        var opened: usize = 0;
        for (rest.plan.clauses[rest.next..stop]) |clause| {
            self.noteSuspendClause(site, self.forClauseSpan(clause), false);
            try self.expandTemplate(rw, site, .check_bind, &.{ .name = clause.name orelse keep, .first = clause.expr }, depth + 1);
            if (clause.kind == .binding) continue;
            try self.emitTo(rw, self.templateWord(site, .for_range, "If"));
            try self.emitKind(rw, .left_paren, here);
            try self.emitTo(rw, keep);
            try self.emitKind(rw, .comma, here);
            try self.emitTo(rw, block);
            try self.emitKind(rw, .left_brace, here);
            opened += 1;
        }
        try self.expandForRest(rw, site, .{ .plan = rest.plan, .next = rest.next, .checked = true }, depth + 1);
        // The empty array is the template's own `array{}`: an aggregate's braces lie in order.
        const empty = self.templateOrdinal(.for_try, "array");
        for (0..opened) |_| {
            try self.emitKind(rw, .right_brace, here);
            try self.emitKind(rw, .comma, here);
            for (0..3) |offset| try self.emitTo(rw, self.libraryToken(site, .for_try, empty + offset));
            try self.emitKind(rw, .right_paren, here);
        }
        try self.emitKind(rw, .right_brace, here);
    }

    /// The identifier `word` of `template`, placed in the block of `site`.
    fn templateWord(self: *Workspace, site: Site, template: macros.Template, comptime word: []const u8) Token {
        return self.libraryToken(site, template, self.templateOrdinal(template, word));
    }
    /// Where the first identifier `word` is among the tokens of `template`.
    fn templateOrdinal(self: *const Workspace, template: macros.Template, comptime word: []const u8) usize {
        const range = self.library_ranges[@backingInt(template)];
        const text = macros.templateText(template);
        for (self.library_tokens[range[0]..range[1]], 0..) |raw, ordinal| {
            if (raw.kind == .identifier and std.mem.eql(u8, raw.span.text(text), word)) return ordinal;
        }
        unreachable;
    }

    /// The user's text of a clause of a `For`: from its first name to the end of its expression.
    fn forClauseSpan(self: *const Workspace, clause: ForClause) ?Span {
        const end = if (clause.kind == .range) clause.high[1] else clause.expr[1];
        const tail = self.userSpan(.{ clause.expr[0], end }) orelse return null;
        const first = clause.index_name orelse clause.name orelse return tail;
        if (first.site != 0 or self.libraryModule(first.span) != null or first.span.start > tail.start) return null;
        return .{ .start = first.span.start, .end = tail.end };
    }

    /// Records a clause or body of a `For` lowered without regions (RFC-0082, P3.8). A clause
    /// has two tokens at least, its comma included, so the table has room for every clause of
    /// a round of the rewrite. One that finds it full, after copies of `Defer` bodies, goes
    /// unrecorded: what fails in it is then reported as `failure_context_required`.
    fn noteSuspendClause(self: *Workspace, site: Site, span: ?Span, body: bool) void {
        const clause = span orelse return;
        if (self.suspend_clause_count == self.suspend_clauses.len) return;
        // The site `tagSite` gives the tokens generated for this call.
        const tag: u32 = if (site.keyword.site != 0) site.keyword.site else site.keyword.span.start + 1;
        self.suspend_clauses[self.suspend_clause_count] = .{ .span = clause, .body = body, .site = tag };
        self.suspend_clause_count += 1;
    }

    /// The innermost clause or body of a `For` lowered without regions that holds `span`, when
    /// `span` stands directly in a function that `For`'s templates wrote: one the program
    /// writes in it (an `Fn`, a task's body) or another macro's (an arm, a `While`'s visit) is
    /// code of its own, whose failures and sites are its own business.
    fn suspendClause(self: *const Workspace, span: Span) ?SuspendClause {
        if (self.suspend_clause_count == 0) return null;
        var index = self.anonymous_count;
        const here: u32 = while (index != 0) {
            index -= 1;
            if (self.anonymous_frames[index].phase == .body) break self.anonymous_frames[index].macro_site;
        } else return null;
        if (here == 0) return null;
        var chosen: ?SuspendClause = null;
        for (self.suspend_clauses[0..self.suspend_clause_count]) |clause| {
            if (clause.site != here or clause.span.start > span.start or span.end > clause.span.end) continue;
            if (chosen == null or clause.span.end - clause.span.start < chosen.?.span.end - chosen.?.span.start) chosen = clause;
        }
        return chosen;
    }

    /// Where the next unused `Fn` word of the block of `site` is: in its pool, which holds enough
    /// for calls with one generator, and then on the line of words its extension adds.
    fn fnWord(self: *Workspace, site: Site) ParseError!u32 {
        const used = self.library_used[site.module];
        const pooled = macros.pooledWords(site.templates - site.base);
        if (used < pooled) return site.base + macros.pool_offset + 3 * used;
        const index = used - pooled;
        if (index < site.extension.words) return site.templates + site.extension.word(index);
        // The count below covers every call as written. A `Defer` body that is copied to several
        // exits takes its words once per copy, which no count of the text foresees: such a block
        // asks again, for twice as many, so the number of compiles stays logarithmic.
        if (site.extension.words != 0) {
            if (site.extension.words > types.limits.tokens / 2) return self.fail(site.keyword.span, .macro_limit);
            return self.requestExtension(site, .{ .words = 2 * site.extension.words });
        }
        return self.requestExtension(site, .{ .words = index + 1 + self.wordsNeeded(site.module) });
    }

    /// At least the `Fn` words the calls of `module` still to be rewritten take, counted in the
    /// tokens this round began with (the user's tokens pass through every expansion): two for each
    /// generator of a `For`, which has fewer generators than arguments, and one for a `While`.
    fn wordsNeeded(self: *Workspace, module: u32) u32 {
        const start: u32 = if (self.module_storage.module_count == 0) 0 else self.module_storage.modules[module].source.start;
        const end = self.userEnd(module);
        var words: u32 = 0;
        for (0..self.token_count - 1) |index| {
            const position = self.tokens[index].span.start;
            if (position < start or position >= end) continue;
            if (self.tokens[index + 1].kind == .left_brace and self.isName(index, "Loop")) words += 1;
            if (self.tokens[index + 1].kind == .left_bracket and self.isName(index, "First")) words += @intCast(2 * self.argumentCount(index + 1));
            // The body of a `Batch{...}` is named by a word (RFC-0084, P4.5).
            if (!self.batch_named and self.tokens[index + 1].kind == .left_brace and self.isName(index, "Batch")) words += 1;
            if (self.tokens[index + 1].kind != .left_paren) continue;
            if (self.isName(index, "For")) words += @intCast(2 * self.argumentCount(index + 1));
            if (self.tokens[index + 1].kind == .left_paren and self.isName(index, "While")) words += 1;
            // An arm of `Sync` or `Race` is named by a word (RFC-0082, P3.3).
            if (self.isName(index, "Sync") or self.isName(index, "Race")) words += @intCast(self.argumentCount(index + 1));
            // So is an arm of `Rush` (P3.4), where the program declares nothing by the name: a
            // program's own `Rush` keeps the block it had.
            if (!self.rush_named and self.isName(index, "Rush")) words += @intCast(self.argumentCount(index + 1));
            // So are the guard and the body of `Upon` and `When` (RFC-0084, P4.4).
            if ((!self.upon_named and self.isName(index, "Upon")) or (!self.when_named and self.isName(index, "When"))) words += @intCast(self.argumentCount(index + 1));
            // And the guard of `Await` (P4.6), which is no method of a handle after a dot.
            if (!self.await_named and self.isName(index, "Await") and (index == 0 or self.tokens[index - 1].kind != .dot)) words += 1;
            if (self.sort_by_standard and self.isName(index, "SortBy") and (index == 0 or self.tokens[index - 1].kind != .dot)) words += macros.sort_words;
        }
        return words;
    }

    // Early exit (RFC-0068). `Return`, `Break` and `Defer` are resolved by this pass wherever a
    // loop or a `Defer` is involved; a `Return` in plain code goes to the parser untouched.
    //
    // A loop body runs in a generated function, one call per visit, so leaving the loop or the
    // enclosing function from inside it cannot be a jump. It is a `Return` of the generated
    // function with a state whose first element, the mode, says why the visit ended; the code
    // after the loop reads the mode and exits again, in its own frame. A `Defer` is not registered
    // at run time either: its body is copied to every place its scope is left.

    /// Every level of the rewrite pushes at most two: a loop's function and a copy in it.
    const max_exit_frames = 2 * rewrite_depth + 8;
    const max_exit_defers = 64;
    /// The locals a loop carries: its function has them as captures beside the state parameter.
    const max_exit_variables = @min(types.limits.tuple_arity, types.limits.parameters) - 1;
    /// Modes of a loop state: still running; left by `Break`; a `Return` is pending, its value in
    /// the last element; a `Break` for an enclosing `Loop{}` is pending.
    const exit_running = 0;
    const exit_broken = 1;
    const exit_returning = 2;
    const exit_breaking = 3;

    /// What code being rewritten runs in, innermost last. With no frame it is a function body or
    /// a root expression, which the parser tells apart.
    const ExitFrame = struct {
        /// `function` is the body of a user's `Fn`. `loop` is a `Loop{}`, which a `Break` leaves;
        /// `repeat` (a `While`) and `each` (a `For`) pass a `Break` on. `deferred` is a copy of a
        /// `Defer` body, which nothing may leave. `task` is the body of a `Spawn{...}`, which no
        /// `Return` and no `Break` outside a loop of its own may leave (RFC-0082).
        kind: enum { function, loop, repeat, each, deferred, task, arm },
        /// The `Defer`s from this index on were written in this frame, so an exit here runs them.
        defers: u32,
        /// The first `Defer` of the function this code is compiled in: the parser counts from it.
        marks: u32,
        variables: []const Token = &.{},
        /// The state of this loop has room for the value of a pending `Return`.
        payload: bool = false,
        /// This text is being written out a second time (a later copy of a `Defer` body), so
        /// whatever in it is identified by where it stands needs a place of its own.
        repeated: bool = false,
        /// For an `arm` (RFC-0082, P3.6): the exits that leave the arms of its expression, which
        /// say how a pending exit is carried out of an arm (`armEncoding`).
        arm_exits: Exits = .{},
    };
    const ExitDefer = struct { body: [2]usize, copies: u32 = 0 };
    const ExitKind = enum { leave, stop };
    /// `first` is the token of the first exit found, for a caller that has to refuse it.
    const Exits = struct { returns: bool = false, breaks: bool = false, first: usize = 0 };

    fn exitAt(self: *Workspace, at: usize) ?ExitKind {
        if (at + 1 >= self.token_count or self.tokens[at + 1].kind != .left_paren) return null;
        if (self.isName(at, "Return")) return .leave;
        if (self.isName(at, "Break")) return .stop;
        return null;
    }

    fn exitWord(self: *Workspace, site: Site, word: macros.ExitWord) Token {
        return self.shifted(self.exit_tokens[@backingInt(word)], site.templates + site.extension.exitWords());
    }

    /// The early-exit lowering spells its generated code with words that only a module using it
    /// carries; one that lacks them is compiled again with the line added.
    fn requireExitWords(self: *Workspace, site: Site) ParseError!void {
        if (!site.extension.exits) return self.requestExtension(site, .{ .exits = true });
    }

    /// The body `{ ... }` of the anonymous function whose `Fn` is at `at`: its braces, if both lie before `limit`.
    fn functionBody(self: *const Workspace, at: usize, limit: usize) ?[2]usize {
        var cursor = at + 1;
        if (cursor < limit and self.tokens[cursor].kind == .left_bracket) cursor = self.segmentClose(cursor) + 1;
        if (cursor >= limit or self.tokens[cursor].kind != .left_paren) return null;
        cursor = self.segmentClose(cursor) + 1;
        // The effects and the result type lie between the parameters and the body.
        var level: usize = 0;
        while (cursor < limit) : (cursor += 1) {
            const kind = self.tokens[cursor].kind;
            if (kind == .left_brace and level == 0) {
                const close = self.segmentClose(cursor);
                return if (close < limit and self.tokens[close].kind == .right_brace) .{ cursor, close } else null;
            }
            if (kind == .left_paren or kind == .left_bracket) level += 1;
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) {
                if (level == 0) return null;
                level -= 1;
            }
            if (kind == .eof or kind == .separator) return null;
        }
        return null;
    }

    /// Whether a `Return` or a `Break` in `[from, to)` would leave this range: one that is not
    /// inside an anonymous function and, for a `Break`, not inside a `Loop{}` of its own.
    fn exitsIn(self: *Workspace, from: usize, to: usize) Exits {
        var found: Exits = .{};
        // A `Break` inside a nested `Loop{}` belongs to that loop; `inner` is where it ends.
        var inner: usize = 0;
        var at = from;
        while (at < to) : (at += 1) {
            // A live guard is a function of its own (RFC-0084).
            if (self.tokens[at].kind == .synthetic_guard and at + 1 < to and self.tokens[at + 1].kind == .left_brace) {
                at = self.segmentClose(at + 1);
                continue;
            }
            if (self.tokens[at].kind != .identifier) continue;
            if (self.isName(at, "Fn")) {
                if (self.functionBody(at, to)) |body| at = body[1];
                continue;
            }
            // So is a nested function (RFC-0085, I3).
            if (self.statementStart(at)) if (self.nestedHeaderAt(at)) |body| {
                at = self.nestedEnd(body) -| 1;
                continue;
            };
            if (at + 1 >= to) break;
            // Nothing in a task's body leaves the code around it. An exit in an arm of `Sync`,
            // `Race` or `Rush` leaves it, and then the code around (RFC-0082, P3.6).
            if (!self.spawn_named and self.isName(at, "Spawn") and self.tokens[at + 1].kind == .left_brace) {
                at = self.segmentClose(at + 1);
                continue;
            }
            if (!self.branch_named and self.isName(at, "Branch") and self.tokens[at + 1].kind == .left_brace) {
                at = self.segmentClose(at + 1);
                continue;
            }
            if (!self.batch_named and self.isName(at, "Batch") and self.tokens[at + 1].kind == .left_brace) {
                at = self.segmentClose(at + 1);
                continue;
            }
            if (self.isName(at, "Loop") and self.tokens[at + 1].kind == .left_brace and at >= inner) {
                inner = self.segmentClose(at + 1);
                continue;
            }
            if (self.tokens[at + 1].kind != .left_paren) continue;
            const leaves = self.isName(at, "Return") or (self.isName(at, "Break") and at >= inner);
            if (leaves and !found.returns and !found.breaks) found.first = at;
            if (self.isName(at, "Return")) found.returns = true;
            if (self.isName(at, "Break") and at >= inner) found.breaks = true;
        }
        return found;
    }

    /// `[from, to)` without the newlines and separators at either end.
    fn trimmedStatements(self: *const Workspace, from: usize, to: usize) [2]usize {
        var low = from;
        var high = to;
        while (low < high and (self.tokens[low].kind == .newline or self.tokens[low].kind == .separator)) low += 1;
        while (high > low and (self.tokens[high - 1].kind == .newline or self.tokens[high - 1].kind == .separator)) high -= 1;
        return .{ low, high };
    }

    fn pushExitFrame(self: *Workspace, span: Span, frame: ExitFrame) ParseError!void {
        if (self.exit_frame_count == max_exit_frames) return self.fail(span, .expression_limit);
        self.exit_frames[self.exit_frame_count] = frame;
        self.exit_frame_count += 1;
    }

    /// The index of the first `Defer` of the function that the code being rewritten belongs to.
    fn exitMarks(self: *const Workspace) u32 {
        return if (self.exit_frame_count == 0) 0 else self.exit_frames[self.exit_frame_count - 1].marks;
    }

    /// An anonymous function of the user's is a function of its own: a `Return` inside returns
    /// from it, a `Break` cannot leave it, and the `Defer`s around it are not its business.
    fn streamFunction(self: *Workspace, rw: *Rewrite, at: usize, body: [2]usize, depth: usize) ParseError!usize {
        if (depth >= rewrite_depth) return self.fail(self.tokens[at].span, .expression_limit);
        var repeated = false;
        for (self.exit_frames[0..self.exit_frame_count]) |frame| repeated = repeated or frame.repeated;
        if (repeated) {
            // An anonymous function is identified by its `Fn` token, and this one's is already
            // taken by the first copy of the `Defer` body it stands in.
            const site = try self.siteFor(self.tokens[at]);
            const position = try self.fnWord(site);
            if (position + 4 > site.library_end) return self.fail(self.tokens[at].span, .macro_limit);
            self.library_used[site.module] += 1;
            if (self.renamed_fn_count < self.renamed_fns.len) {
                self.renamed_fns[self.renamed_fn_count] = position;
                self.renamed_fn_count += 1;
            }
            try self.emitTo(rw, .{ .kind = .identifier, .span = .{ .start = position, .end = position + 2 } });
        } else try self.emitTo(rw, self.tokens[at]);
        // The captures are evaluated by the code around the function.
        try self.streamMacros(rw, at + 1, body[0] + 1, depth + 1);
        try self.pushExitFrame(self.tokens[at].span, .{ .kind = .function, .defers = self.exit_defer_count, .marks = self.exit_defer_count });
        try self.streamMacros(rw, body[0] + 1, body[1], depth + 1);
        self.exit_frame_count -= 1;
        return body[1];
    }

    /// RFC-0085, I3 (S7): a nested function is a function of its own, as an `Fn` is. Its header
    /// at `at` is written out as it is, and its body, from `body` to the end of its statement,
    /// as an `Fn`'s. No copy of a `Defer` body holds one (`rewriteDefer`).
    fn streamNested(self: *Workspace, rw: *Rewrite, at: usize, body: usize, to: usize, depth: usize) ParseError!usize {
        if (depth >= rewrite_depth) return self.fail(self.tokens[at].span, .expression_limit);
        for (self.exit_frames[0..self.exit_frame_count]) |frame| if (frame.repeated) return self.fail(self.tokens[at].span, .nested_position);
        const end = @min(self.nestedEnd(body), to);
        try self.pushExitFrame(self.tokens[at].span, .{ .kind = .function, .defers = self.exit_defer_count, .marks = self.exit_defer_count });
        // RFC-0085, I4: the defaults in its parameter list are rewritten as any code is, inside
        // its frame, so that no exit there is taken for one of the code around it (review).
        try self.emitTo(rw, self.tokens[at]);
        try self.streamMacros(rw, at + 1, body, depth + 1);
        try self.streamMacros(rw, body, end, depth + 1);
        self.exit_frame_count -= 1;
        return end;
    }

    fn nestedBucket(name: []const u8) usize {
        return @intCast(name_index.hashName(0, name) & (nested_bucket_count - 1));
    }

    /// Enters nested function `entry` into scope, its index the result.
    fn pushNested(self: *Workspace, entry: NestedFunction) u32 {
        std.debug.assert(self.nested_count < self.nested_functions.len);
        if (!self.nested_buckets_ready) {
            @memset(&self.nested_buckets, 0);
            self.nested_buckets_ready = true;
        }
        const index = self.nested_count;
        const bucket = nestedBucket(entry.name.text(self.source));
        self.nested_functions[index] = entry;
        self.nested_functions[index].bucket = @intCast(bucket);
        self.nested_functions[index].next = self.nested_buckets[bucket];
        self.nested_buckets[bucket] = index + 1;
        self.nested_count += 1;
        return index;
    }

    /// Takes the latest nested function out of scope, and its captures.
    fn dropNested(self: *Workspace) void {
        std.debug.assert(self.nested_count != 0 and self.nested_buckets_ready);
        const index = self.nested_count - 1;
        const entry = self.nested_functions[index];
        // The bucket it was entered in: a compile that failed leaves its entries to the next
        // one, whose source is another.
        const bucket = entry.bucket;
        std.debug.assert(self.nested_buckets[bucket] == index + 1);
        self.nested_buckets[bucket] = entry.next;
        if (entry.runtime != no_member) self.nested_capture_count = entry.captures.start;
        self.nested_count = index;
    }

    /// The end of the body of a nested function that begins at `body`: the line break or
    /// separator that ends its statement, or the closer of the block around it.
    fn nestedEnd(self: *const Workspace, body: usize) usize {
        var level: usize = 0;
        var at = body;
        while (at < self.token_count) : (at += 1) {
            switch (self.tokens[at].kind) {
                .left_paren, .left_bracket, .left_brace => level += 1,
                .right_paren, .right_bracket, .right_brace => {
                    if (level == 0) return at;
                    level -= 1;
                },
                .newline, .separator => if (level == 0) return at,
                .eof => return at,
                else => {},
            }
        }
        return self.token_count - 1;
    }

    /// Whether `Sync(` or `Race(` at `at` is the form (RFC-0082, P3.3): the program declares
    /// nothing by the name (`namesForm`), and it is no method, after a dot.
    fn armsAt(self: *const Workspace, at: usize) bool {
        if (at + 1 >= self.token_count or self.tokens[at + 1].kind != .left_paren) return false;
        if (at != 0 and self.tokens[at - 1].kind == .dot) return false;
        return (!self.sync_named and self.isName(at, "Sync")) or (!self.race_named and self.isName(at, "Race")) or (!self.rush_named and self.isName(at, "Rush")) or self.reactionAt(at);
    }
    /// RFC-0084, P4.6: whether the program declares something named `Await`, by the rule of
    /// `namesForm` and `namesTyped`, and moreover a declaration `Await<...>(...)`, `Await(...):`
    /// or `Await[` at any depth (a module's or a class's function), not after a dot: a program
    /// that declared its own `Await` before P4.6 keeps it, its calls and its exits.
    fn namesAwait(self: *const Workspace) bool {
        if (self.namesForm("Await") or self.namesTyped("Await")) return true;
        for (0..self.token_count -| 1) |at| {
            if (!self.isName(at, "Await") or (at != 0 and self.tokens[at - 1].kind == .dot)) continue;
            const next = self.tokens[at + 1].kind;
            if (next == .less or next == .left_bracket) return true;
            if (next != .left_paren) continue;
            const close = self.segmentClose(at + 1);
            if (close + 1 < self.token_count and (self.tokens[close + 1].kind == .colon or self.tokens[close + 1].kind == .less)) return true;
        }
        return false;
    }
    /// Whether `Upon(` or `When(` at `at` is the form (RFC-0084, P4.4), by the rule of `armsAt`;
    /// or from P4.6 `Await(` without a receiver, whose guard is left by no exit either.
    fn reactionAt(self: *const Workspace, at: usize) bool {
        return (!self.upon_named and self.isName(at, "Upon")) or (!self.when_named and self.isName(at, "When")) or (!self.await_named and self.isName(at, "Await") and (at == 0 or self.tokens[at - 1].kind != .dot));
    }

    /// `Sync(A1, ..., An)` or `Race(A1, ..., An)` at `at`: each arm is a function of its own
    /// (RFC-0082, P3.3), whose `Defer`s are counted from its first. An exit that leaves an arm
    /// (P3.6) ends it with a pending exit (`emitArmExit`), and the expression carries that exit
    /// on where it stands: after the last arm the form gets `<arm_reissue>` and that code.
    fn streamArms(self: *Workspace, rw: *Rewrite, at: usize, depth: usize) ParseError!usize {
        const keyword = self.tokens[at];
        if (depth >= rewrite_depth) return self.fail(keyword.span, .expression_limit);
        var bounds: [types.limits.parameters + 2]usize = undefined;
        const split = try self.splitCall(keyword, at + 1, &bounds, .concurrency_arms);
        // The guard and the body of a reaction are left by no exit, as a task's body is not
        // (RFC-0084, P4.4): an exit inside one is refused where it is written.
        const reaction = self.reactionAt(at);
        // The exits that leave the arms, also through the arms of expressions inside them.
        var exits: Exits = .{};
        if (!reaction) for (0..split.items) |item| {
            const found = self.exitsIn(bounds[item], bounds[item + 1] - 1);
            if (!exits.returns and !exits.breaks) exits.first = found.first;
            exits.returns = exits.returns or found.returns;
            exits.breaks = exits.breaks or found.breaks;
        };
        const exiting = exits.returns or exits.breaks;
        if (exiting) {
            const site = try self.siteFor(keyword);
            try self.requireExitWords(site);
            try self.requireNumerals(site, exit_breaking + 1);
        }
        try self.emitTo(rw, keyword);
        try self.emitTo(rw, self.tokens[at + 1]);
        for (0..split.items) |item| {
            const end = bounds[item + 1] - 1;
            try self.pushExitFrame(keyword.span, .{ .kind = if (reaction) .task else .arm, .defers = self.exit_defer_count, .marks = self.exit_defer_count, .arm_exits = exits });
            try self.streamMacros(rw, bounds[item], end, depth + 1);
            self.exit_frame_count -= 1;
            if (exiting and item + 1 == split.items) try self.emitArmReissue(rw, keyword, exits, depth);
            // The comma after the arm, or the parenthesis that closes the form.
            try self.emitTo(rw, self.tokens[end]);
        }
        return split.close + 1;
    }

    /// How the arms of an expression carry a pending exit (RFC-0082, P3.6): 0, the value of a
    /// `Return`; 1, `true` for a `Break`; 2, when both occur, `tuple{mode, option{value}}` with
    /// the mode of a loop state (`exit_returning` or `exit_breaking`).
    fn armEncoding(exits: Exits) u32 {
        if (!exits.breaks) return 0;
        return if (exits.returns) 2 else 1;
    }
    /// What `emitPending` writes for the value of a pending exit where its expression stands:
    /// the whole value, or the value of the `Return` in a pair of encoding 2.
    const arm_value_pending = std.math.maxInt(u32);
    const arm_wrapped_pending = std.math.maxInt(u32) - 1;

    /// `, <arm_reissue> Code` after the last arm of an expression whose arms an exit leaves
    /// (RFC-0082, P3.6). `Code` runs where the expression stands when an arm ended with a
    /// pending exit: it is that exit, written again in the code around the expression, so it
    /// runs the `Defer`s there and leaves as far as an exit written there would.
    fn emitArmReissue(self: *Workspace, rw: *Rewrite, keyword: Token, exits: Exits, depth: usize) ParseError!void {
        const here = keyword.span;
        const none: [2]usize = .{ 0, 0 };
        try self.emitKind(rw, .comma, here);
        try self.emitKind(rw, .synthetic_arm_reissue, here);
        switch (armEncoding(exits)) {
            0 => try self.emitExit(rw, keyword, .leave, none, arm_value_pending, depth + 1),
            1 => try self.emitExit(rw, keyword, .stop, none, null, depth + 1),
            else => {
                // If(<arm value>(0)==3, Break(), Return(__case_value(<arm value>(1))))
                const site = try self.siteFor(keyword);
                try self.emitTo(rw, self.exitWord(site, .if_word));
                try self.emitKind(rw, .left_paren, here);
                try self.emitKind(rw, .synthetic_arm_value, here);
                try self.emitKind(rw, .left_paren, here);
                try self.emitTo(rw, self.numeralToken(site, 0));
                try self.emitKind(rw, .right_paren, here);
                try self.emitKind(rw, .equal_equal, here);
                try self.emitTo(rw, self.numeralToken(site, exit_breaking));
                try self.emitKind(rw, .comma, here);
                try self.emitExit(rw, keyword, .stop, none, null, depth + 1);
                try self.emitKind(rw, .comma, here);
                try self.emitExit(rw, keyword, .leave, none, arm_wrapped_pending, depth + 1);
                try self.emitKind(rw, .right_paren, here);
            },
        }
    }

    /// An exit that leaves an arm of `Sync`, `Race` or `Rush` (RFC-0082, P3.6): the arm's own
    /// `Defer`s run, the newest first, and the arm ends with its pending exit,
    /// `<arm_exit> N (Payload)`, `N` being the encoding of its expression (`armEncoding`). The
    /// value of a `Return` is computed before any deferred code runs, as for every `Return`.
    fn emitArmExit(self: *Workspace, rw: *Rewrite, keyword: Token, kind: ExitKind, operand: [2]usize, pending: ?u32, arm: ExitFrame, depth: usize) ParseError!void {
        const here = keyword.span;
        const site = try self.siteFor(keyword);
        try self.requireExitWords(site);
        try self.requireNumerals(site, exit_breaking + 1);
        const encoding = armEncoding(arm.arm_exits);
        std.debug.assert(kind == .stop or arm.arm_exits.returns);
        std.debug.assert(kind == .leave or arm.arm_exits.breaks);
        const deferred = self.exit_defer_count > arm.defers;
        const bound = kind == .leave and (deferred or encoding == 2);
        if (deferred or bound) {
            try self.emitTo(rw, self.exitWord(site, .block));
            try self.emitKind(rw, .left_brace, here);
        }
        if (bound) {
            // __exit_v:__ret=(E);
            try self.emitTo(rw, self.exitWord(site, .value));
            try self.emitKind(rw, .colon, here);
            try self.emitTo(rw, self.exitWord(site, .result_type));
            try self.emitKind(rw, .equal, here);
            try self.emitKind(rw, .left_paren, here);
            if (pending) |index| try self.emitPending(rw, site, index) else try self.streamMacros(rw, operand[0], operand[1], depth + 1);
            try self.emitKind(rw, .right_paren, here);
            try self.emitKind(rw, .separator, here);
        }
        var index = self.exit_defer_count;
        while (index > arm.defers) {
            index -= 1;
            try self.emitDeferred(rw, site, index, depth + 1);
            try self.emitKind(rw, .separator, here);
        }
        try self.emitKind(rw, .synthetic_arm_exit, here);
        try self.emitTo(rw, self.numeralToken(site, encoding));
        try self.emitKind(rw, .left_paren, here);
        switch (encoding) {
            0 => if (bound) try self.emitTo(rw, self.exitWord(site, .value)) else if (pending) |at| try self.emitPending(rw, site, at) else {
                try self.emitKind(rw, .left_paren, here);
                try self.streamMacros(rw, operand[0], operand[1], depth + 1);
                try self.emitKind(rw, .right_paren, here);
            },
            1 => try self.emitTo(rw, self.exitWord(site, .true_word)),
            else => {
                // tuple{mode,option{__exit_v}}, or tuple{3,option{}} for a `Break`
                try self.emitTo(rw, self.exitWord(site, .tuple_word));
                try self.emitKind(rw, .left_brace, here);
                try self.emitTo(rw, self.numeralToken(site, if (kind == .leave) exit_returning else exit_breaking));
                try self.emitKind(rw, .comma, here);
                try self.emitTo(rw, self.exitWord(site, .option_word));
                try self.emitKind(rw, .left_brace, here);
                if (bound) try self.emitTo(rw, self.exitWord(site, .value));
                try self.emitAggregateEnd(rw, site);
                try self.emitAggregateEnd(rw, site);
            },
        }
        try self.emitKind(rw, .right_paren, here);
        if (deferred or bound) try self.emitKind(rw, .right_brace, here);
    }

    /// The guard of a live variable (RFC-0084) is the body of a function of its own, as an
    /// `Fn`'s is: an exit inside it leaves the guard. It is identified by its word `live`, which
    /// a second copy of a `Defer` body cannot give it again.
    fn streamGuard(self: *Workspace, rw: *Rewrite, at: usize, depth: usize) ParseError!usize {
        if (depth >= rewrite_depth) return self.fail(self.tokens[at].span, .expression_limit);
        const close = self.segmentClose(at + 1);
        if (close >= self.token_count or self.tokens[close].kind != .right_brace) return self.fail(self.tokens[at].span, .macro_syntax);
        for (self.exit_frames[0..self.exit_frame_count]) |frame| if (frame.repeated) return self.fail(self.tokens[at].span, .live_deferred);
        try self.emitTo(rw, self.tokens[at]);
        try self.emitTo(rw, self.tokens[at + 1]);
        try self.pushExitFrame(self.tokens[at].span, .{ .kind = .function, .defers = self.exit_defer_count, .marks = self.exit_defer_count });
        try self.streamMacros(rw, at + 2, close, depth + 1);
        self.exit_frame_count -= 1;
        try self.emitTo(rw, self.tokens[close]);
        return close + 1;
    }

    /// The body of a `Spawn{...}` is a function of its own (RFC-0082) that nothing leaves: an
    /// exit inside it, outside a loop of its own, is refused where it is written.
    fn streamTask(self: *Workspace, rw: *Rewrite, at: usize, depth: usize) ParseError!usize {
        if (depth >= rewrite_depth) return self.fail(self.tokens[at].span, .expression_limit);
        const close = self.segmentClose(at + 1);
        if (close >= self.token_count or self.tokens[close].kind != .right_brace) return self.fail(self.tokens[at].span, .macro_syntax);
        var repeated = false;
        for (self.exit_frames[0..self.exit_frame_count]) |frame| repeated = repeated or frame.repeated;
        if (repeated and self.isName(at, "Branch")) {
            // So is a branch's body by its `Branch` token (P3.4): one in a `Fn` in a copied `Defer`
            // body takes a `Branch` word of the block for each copy after the first.
            const site = try self.siteFor(self.tokens[at]);
            const index = self.library_branches[site.module];
            if (index >= site.extension.branches) {
                if (site.extension.branches > types.limits.tokens / 2) return self.fail(self.tokens[at].span, .macro_limit);
                return self.requestExtension(site, .{ .branches = @max(4, 2 * site.extension.branches) });
            }
            const position = site.templates + site.extension.branchWord(index);
            if (position + 6 > site.library_end) return self.fail(self.tokens[at].span, .macro_limit);
            self.library_branches[site.module] += 1;
            try self.emitTo(rw, .{ .kind = .identifier, .span = .{ .start = position, .end = position + 6 } });
        } else if (repeated and !self.isName(at, "Batch")) {
            // A task body is identified by its `Spawn` token, as a function by its `Fn` token,
            // and this one's is already taken by the first copy of the `Defer` body it stands in.
            const site = try self.siteFor(self.tokens[at]);
            const index = self.library_spawns[site.module];
            if (index >= site.extension.spawns) {
                if (site.extension.spawns > types.limits.tokens / 2) return self.fail(self.tokens[at].span, .macro_limit);
                return self.requestExtension(site, .{ .spawns = @max(4, 2 * site.extension.spawns) });
            }
            const position = site.templates + site.extension.spawnWord(index);
            if (position + 5 > site.library_end) return self.fail(self.tokens[at].span, .macro_limit);
            self.library_spawns[site.module] += 1;
            try self.emitTo(rw, .{ .kind = .identifier, .span = .{ .start = position, .end = position + 5 } });
        } else try self.emitTo(rw, self.tokens[at]);
        try self.emitTo(rw, self.tokens[at + 1]);
        try self.pushExitFrame(self.tokens[at].span, .{ .kind = .task, .defers = self.exit_defer_count, .marks = self.exit_defer_count });
        try self.streamMacros(rw, at + 2, close, depth + 1);
        self.exit_frame_count -= 1;
        try self.emitTo(rw, self.tokens[close]);
        return close + 1;
    }

    /// `Return(E)` or `Break()` written by the user at `at`.
    fn rewriteExit(self: *Workspace, rw: *Rewrite, at: usize, kind: ExitKind, depth: usize) ParseError!usize {
        const keyword = self.tokens[at];
        const close = self.segmentClose(at + 1);
        if (close >= self.token_count or self.tokens[close].kind != .right_paren) return self.fail(keyword.span, .macro_syntax);
        const operand = self.trimmed(at + 2, close);
        if (kind == .stop and operand[0] != operand[1]) return self.fail(keyword.span, .argument_count);
        try self.emitExit(rw, keyword, kind, operand, null, depth);
        return close + 1;
    }

    /// Leaves the code being rewritten. A `Return` hands on `operand`, or (after a loop that
    /// ended with one pending) the value at `pending` of the loop's final state. First the
    /// `Defer`s of this frame run, the newest first; then the frame is left: a function with its
    /// result, a loop's function with a state that tells the code after the loop what to do.
    fn emitExit(self: *Workspace, rw: *Rewrite, keyword: Token, kind: ExitKind, operand: [2]usize, pending: ?u32, depth: usize) ParseError!void {
        if (depth >= rewrite_depth) return self.fail(keyword.span, .expression_limit);
        const here = keyword.span;
        // What the exit has to cross on its way to its target.
        var reaches_loop = false;
        var level = self.exit_frame_count;
        while (level != 0) {
            level -= 1;
            const crossed = self.exit_frames[level].kind;
            if (crossed == .deferred) return self.fail(here, .defer_exit);
            if (crossed == .task) return self.fail(here, .return_in_task_body);
            if (crossed == .function) break;
            if (kind == .stop and crossed == .loop) {
                reaches_loop = true;
                break;
            }
        }
        if (kind == .stop and !reaches_loop) return self.fail(here, .break_outside_loop);
        const frame: ?ExitFrame = if (self.exit_frame_count != 0) self.exit_frames[self.exit_frame_count - 1] else null;
        const carrier: ?ExitFrame = if (frame != null and frame.?.kind != .function) frame else null;
        const first_defer: u32 = if (frame) |top| top.defers else 0;
        const deferred = self.exit_defer_count > first_defer;
        if (carrier == null and !deferred) {
            // Nothing to do here but return: the parser's own `Return`.
            std.debug.assert(kind == .leave);
            if (pending) |index| {
                const site = try self.siteFor(keyword);
                try self.requireExitWords(site);
                try self.emitKind(rw, .synthetic_exit, here);
                try self.emitKind(rw, .left_paren, here);
                try self.emitPending(rw, site, index);
                try self.emitKind(rw, .right_paren, here);
                return;
            }
            try self.emitTo(rw, keyword);
            try self.emitKind(rw, .left_paren, here);
            try self.streamMacros(rw, operand[0], operand[1], depth + 1);
            try self.emitKind(rw, .right_paren, here);
            return;
        }
        // An arm on top ends with the exit pending (RFC-0082, P3.6).
        if (carrier) |arm| if (arm.kind == .arm) return self.emitArmExit(rw, keyword, kind, operand, pending, arm, depth);
        const site = try self.siteFor(keyword);
        try self.requireExitWords(site);
        if (carrier) |loop| if (kind == .leave and !loop.payload) return self.fail(here, .macro_limit);
        if (deferred) {
            // `Block{ __exit_v:__ret=(E); <the Defers>; <exit> }`: the value is ready before any deferred code runs.
            try self.emitTo(rw, self.exitWord(site, .block));
            try self.emitKind(rw, .left_brace, here);
            if (kind == .leave) {
                try self.emitTo(rw, self.exitWord(site, .value));
                try self.emitKind(rw, .colon, here);
                try self.emitTo(rw, self.exitWord(site, .result_type));
                try self.emitKind(rw, .equal, here);
                try self.emitKind(rw, .left_paren, here);
                if (pending) |index| try self.emitPending(rw, site, index) else try self.streamMacros(rw, operand[0], operand[1], depth + 1);
                try self.emitKind(rw, .right_paren, here);
                try self.emitKind(rw, .separator, here);
            }
            var index = self.exit_defer_count;
            while (index > first_defer) {
                index -= 1;
                try self.emitDeferred(rw, site, index, depth + 1);
                try self.emitKind(rw, .separator, here);
            }
        }
        try self.emitKind(rw, .synthetic_exit, here);
        try self.emitKind(rw, .left_paren, here);
        if (carrier) |loop| {
            const mode: u32 = if (kind == .leave) exit_returning else if (loop.kind == .loop) exit_broken else exit_breaking;
            try self.emitTo(rw, self.exitWord(site, .option_word));
            try self.emitKind(rw, .left_brace, here);
            try self.emitExitState(rw, site, loop, mode, if (kind == .stop) .none else if (deferred) .value else if (pending) |index| .{ .pending = index } else .{ .operand = operand }, depth + 1);
            try self.emitAggregateEnd(rw, site);
        } else {
            std.debug.assert(kind == .leave and deferred);
            try self.emitTo(rw, self.exitWord(site, .value));
        }
        try self.emitKind(rw, .right_paren, here);
        if (deferred) try self.emitKind(rw, .right_brace, here);
    }

    /// `__case_value(__exit_w(index))`: the value a loop's final state carries out. Or, where an
    /// expression carries the pending exit of an arm on (RFC-0082, P3.6), `<arm_value>` or
    /// `__case_value(<arm_value>(1))`.
    fn emitPending(self: *Workspace, rw: *Rewrite, site: Site, index: u32) ParseError!void {
        const here = site.keyword.span;
        if (index == arm_value_pending) return self.emitKind(rw, .synthetic_arm_value, here);
        try self.emitTo(rw, self.exitWord(site, .unwrap));
        try self.emitKind(rw, .left_paren, here);
        if (index == arm_wrapped_pending) try self.emitKind(rw, .synthetic_arm_value, here) else try self.emitTo(rw, self.exitWord(site, .ended));
        try self.emitKind(rw, .left_paren, here);
        try self.emitTo(rw, self.numeralToken(site, if (index == arm_wrapped_pending) 1 else index));
        try self.emitKind(rw, .right_paren, here);
        try self.emitKind(rw, .right_paren, here);
    }

    const ExitPayload = union(enum) { none, value, pending: u32, operand: [2]usize };

    /// `tuple{mode, V1, ..., payload}`: a state of the loop `loop`. A `For` has its position where
    /// the variables are; one that leaves needs it no more.
    fn emitExitState(self: *Workspace, rw: *Rewrite, site: Site, loop: ExitFrame, mode: u32, payload: ExitPayload, depth: usize) ParseError!void {
        const here = site.keyword.span;
        try self.emitTo(rw, self.exitWord(site, .tuple_word));
        try self.emitKind(rw, .left_brace, here);
        try self.emitTo(rw, self.numeralToken(site, mode));
        if (loop.kind == .each) {
            try self.emitKind(rw, .comma, here);
            try self.emitTo(rw, self.numeralToken(site, 0));
        }
        for (loop.variables) |variable| {
            try self.emitKind(rw, .comma, here);
            try self.emitTo(rw, variable);
        }
        if (loop.payload) {
            try self.emitKind(rw, .comma, here);
            try self.emitTo(rw, self.exitWord(site, .option_word));
            try self.emitKind(rw, .left_brace, here);
            switch (payload) {
                .none => {},
                .value => try self.emitTo(rw, self.exitWord(site, .value)),
                .pending => |index| try self.emitPending(rw, site, index),
                .operand => |range| {
                    try self.emitKind(rw, .left_paren, here);
                    try self.streamMacros(rw, range[0], range[1], depth + 1);
                    try self.emitKind(rw, .right_paren, here);
                },
            }
            try self.emitAggregateEnd(rw, site);
        }
        try self.emitAggregateEnd(rw, site);
    }

    /// The `}` of a generated `option{` or `tuple{`. An aggregate's span runs from its word to its
    /// brace, so the brace lies after every word of the library line the word came from.
    fn emitAggregateEnd(self: *Workspace, rw: *Rewrite, site: Site) ParseError!void {
        try self.emitKind(rw, .right_brace, self.exitWord(site, .integer).span);
    }

    /// Whether the program declares something named `Spawn` that `Spawn{` could mean instead of
    /// the form (RFC-0082, C17): a module binding or type (`Spawn:`, `Spawn<` or `Spawn :=` at
    /// the top of a module), a local, class or type declared with `Spawn :=` anywhere but in
    /// parentheses, or a function or method (`Spawn(...)` or `Spawn[...](...)` followed by its
    /// effects or result type). A field, a parameter or a named argument called `Spawn` is not
    /// such a declaration (D1). Where one exists the macro layer, which runs before names are
    /// resolved, treats no `Spawn{` as the form: it neither frames a body for exits (E3) nor
    /// renames it in a copied `Defer` (E1), and the parser, which decides by scope, still
    /// refuses an exit from a body that is the form. Like the scan of `If(` in `macroAt`, finding
    /// the close of a `Spawn(` costs its length, so nested `Spawn(` calls cost the square of
    /// their depth.
    fn namesSpawn(self: *const Workspace) bool {
        return self.namesForm("Spawn");
    }
    /// Whether `name` stands anywhere before a `:`: a parameter, a field, a named argument or a
    /// local. A parameter called `Sync` or `Race` is called as `Race(...)` like the form, so for
    /// those names (P3.3) any such declaration keeps the macro pass from reading arms; the
    /// parser, which decides by scope, still reads the form where nothing is declared.
    fn namesTyped(self: *const Workspace, name: []const u8) bool {
        for (0..self.token_count -| 1) |at| if (self.isName(at, name) and self.tokens[at + 1].kind == .colon) return true;
        return false;
    }
    /// The same question for any name of a form the macro pass frames (`Spawn`, and from P3.3
    /// `Sync` and `Race`).
    fn namesForm(self: *const Workspace, name: []const u8) bool {
        // The innermost open bracket of each position, kept as far as `kinds` reaches;
        // deeper ones count as braces, which only widens the answer.
        var kinds: [64]Token.Kind = undefined;
        var depth: usize = 0;
        for (0..self.token_count -| 1) |at| {
            switch (self.tokens[at].kind) {
                .left_paren, .left_bracket, .left_brace => {
                    if (depth < kinds.len) kinds[depth] = self.tokens[at].kind;
                    depth += 1;
                    continue;
                },
                .right_paren, .right_bracket, .right_brace => {
                    depth -|= 1;
                    continue;
                },
                else => {},
            }
            if (!self.isName(at, name)) continue;
            const next = self.tokens[at + 1].kind;
            const inner: Token.Kind = if (depth == 0) .eof else if (depth <= kinds.len) kinds[depth - 1] else .left_brace;
            if (depth == 0 and (next == .colon or next == .less)) return true;
            if (inner != .left_paren and next == .colon and at + 2 < self.token_count and self.tokens[at + 2].kind == .equal) return true;
            var after = at + 1;
            if (next == .left_bracket) after = self.segmentClose(after) + 1;
            if (after >= self.token_count or self.tokens[after].kind != .left_paren) continue;
            const close = self.segmentClose(after);
            if (close + 1 < self.token_count and (self.tokens[close + 1].kind == .colon or self.tokens[close + 1].kind == .less)) return true;
        }
        return false;
    }

    /// Whether the token at `at` starts a statement of a `Block{}`, a `Loop{}`, a `Defer{}` or
    /// the body of a `Spawn{}` (RFC-0082), which is a statement list like a `Defer`'s.
    fn statementOfScope(self: *const Workspace, at: usize) bool {
        if (at == 0) return false;
        const before = self.tokens[at - 1].kind;
        if (before != .left_brace and before != .separator and before != .newline) return false;
        var level: usize = 0;
        var index = at;
        while (index != 0) {
            index -= 1;
            const kind = self.tokens[index].kind;
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) level += 1;
            if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) {
                if (level != 0) {
                    level -= 1;
                    continue;
                }
                return kind == .left_brace and index != 0 and (self.isName(index - 1, "Block") or self.isName(index - 1, "Loop") or self.isName(index - 1, "Defer") or self.isName(index - 1, "Spawn") or self.isName(index - 1, "Branch") or self.isName(index - 1, "Batch"));
            }
        }
        return false;
    }

    /// RFC-0085, I3: the token after the `=` (or the `:=`) of a nested function header that
    /// starts at `at`: a name with `(` right after it (or `[`, a generic one, or `<word>`s, which
    /// are refused), a parameter list that opens with `Name:` or is empty, any `<word>`s, then
    /// `:`, a result type and `=`, or `:=`. No
    /// expression has this shape: after a call's `)` an expression never continues with `:`,
    /// nor with `<word>` and then `:`. Whether it stands where a nested function may is the
    /// caller's to say. A result type holds no brace, no `=` and no separator, and a parameter
    /// list none outside its defaults (RFC-0085, I4), so the scan stops at the first one; only
    /// a list that opens as a header's (`Name:` or `)`) is read past its first token, so a
    /// token is read once for each header shape around it.
    /// RFC-0091 (B3): whether a destructured parameter opens at `at`: parentheses, then a name
    /// and the `:` or `,` after it. No expression starts so: a tuple is written `tuple{...}`.
    fn patternOpensAt(self: *const Workspace, at: usize) bool {
        var index = at;
        while (index < self.token_count and self.tokens[index].kind == .left_paren) index += 1;
        if (index == at or index + 1 >= self.token_count or self.tokens[index].kind != .identifier) return false;
        return self.tokens[index + 1].kind == .colon or self.tokens[index + 1].kind == .comma;
    }

    fn nestedHeaderAt(self: *const Workspace, at: usize) ?usize {
        if (at + 2 >= self.token_count) return null;
        const name = self.tokens[at];
        if (name.kind != .identifier or (at != 0 and self.tokens[at - 1].kind == .dot)) return null;
        const text = name.span.text(self.source);
        if (reserved(text) or generatedName(text)) return null;
        if (self.tokens[at + 1].span.start != name.span.end) return null;
        var index = at + 1;
        // Specifiers after the name, as a top-level function writes its access: refused where
        // the header is read (`nested_access`).
        while (index + 2 < self.token_count and self.tokens[index].kind == .less and self.tokens[index + 1].kind == .identifier and self.tokens[index + 2].kind == .greater) index += 3;
        if (index + 1 >= self.token_count) return null;
        const first = self.tokens[index];
        if (first.kind != .left_paren and first.kind != .left_bracket) return null;
        // A parameter list opens with a name and its type, or closes at once: no call does both.
        const second = self.tokens[index + 1];
        if (second.kind != .right_paren and !(second.kind == .identifier and index + 2 < self.token_count and self.tokens[index + 2].kind == .colon) and !self.patternOpensAt(index + 1)) return null;
        var level: usize = 0;
        var lists: usize = 0;
        // RFC-0085, I4: the braces open in a parameter's default (`array{}`, `Block{...}`).
        var braces: usize = 0;
        // The type parameters, if any, then the parameters.
        while (index < self.token_count) : (index += 1) {
            switch (self.tokens[index].kind) {
                .left_paren, .left_bracket => level += 1,
                .right_paren, .right_bracket => {
                    if (level == 0) return null;
                    level -= 1;
                    if (level == 0) {
                        if (braces != 0) return null;
                        lists += 1;
                        if (self.tokens[index].kind == .right_paren) break;
                        if (lists == 2 or index + 1 >= self.token_count or self.tokens[index + 1].kind != .left_paren) return null;
                    }
                },
                // RFC-0085, I4 (V8): a parameter's default, `Name:T = Default`. A named
                // argument's `Name := Value` is a call's, so an `=` right after a `:` in the list
                // itself is none (in a default, it may be a call's or a block's).
                .equal => if (level == 0 or (level == 1 and braces == 0 and self.tokens[index - 1].kind == .colon and self.tokens[index - 1].span.end == self.tokens[index].span.start)) return null,
                .left_brace => if (level == 0) return null else {
                    braces += 1;
                },
                .right_brace => if (braces == 0) return null else {
                    braces -= 1;
                },
                .separator => if (braces == 0) return null,
                .eof => return null,
                else => {},
            }
        } else return null;
        index += 1;
        while (index + 2 < self.token_count and self.tokens[index].kind == .less and self.tokens[index + 1].kind == .identifier and self.tokens[index + 2].kind == .greater) index += 3;
        if (index + 1 >= self.token_count or self.tokens[index].kind != .colon) return null;
        const colon = self.tokens[index];
        if (self.tokens[index + 1].kind == .equal and self.tokens[index + 1].span.start == colon.span.end) return index + 2;
        // The result type ends at the `=` outside its brackets.
        index += 1;
        level = 0;
        while (index < self.token_count) : (index += 1) {
            switch (self.tokens[index].kind) {
                .left_paren, .left_bracket => level += 1,
                .right_paren, .right_bracket => {
                    if (level == 0) return null;
                    level -= 1;
                },
                .equal => return if (level == 0) index + 1 else null,
                .left_brace, .right_brace, .newline, .separator, .eof => return null,
                else => {},
            }
        }
        return null;
    }

    /// RFC-0085, I3: whether the identifier at `at` is a label rather than a use of a name: a
    /// field or parameter an archetype or a call names (`Name := value`), or the field that
    /// `WithField` takes second. S1 says such a name denotes nothing.
    fn labelAt(self: *const Workspace, at: usize) bool {
        if (at + 2 < self.token_count and self.tokens[at + 1].kind == .colon and self.tokens[at + 2].kind == .equal and self.tokens[at + 2].span.start == self.tokens[at + 1].span.end) return true;
        if (at < 2 or self.tokens[at - 1].kind != .comma) return false;
        // The first argument before it, back to the parenthesis that opens the call.
        var level: usize = 0;
        var index = at - 1;
        while (index != 0) {
            index -= 1;
            switch (self.tokens[index].kind) {
                .right_paren, .right_bracket, .right_brace => level += 1,
                .left_paren, .left_bracket, .left_brace => {
                    if (level == 0) return self.tokens[index].kind == .left_paren and index != 0 and self.isName(index - 1, "WithField");
                    level -= 1;
                },
                .comma => if (level == 0) return false,
                .separator => return false,
                else => {},
            }
        }
        return false;
    }

    /// Whether the program wrote what begins at source position `position` at the start of a
    /// statement: after `{`, `;` or a line break, spaces aside. Macros move arguments into
    /// blocks they write, where a token may begin a statement it did not begin as written.
    fn writtenAsStatement(self: *const Workspace, position: u32) bool {
        var at = position;
        while (at != 0) {
            at -= 1;
            switch (self.source[at]) {
                ' ', '\t', '\r' => {},
                '{', ';', '\n' => return true,
                else => return false,
            }
        }
        return false;
    }

    /// Whether token `at` begins a statement: the first token of a block or the one after a
    /// line break or a separator.
    fn statementStart(self: *const Workspace, at: usize) bool {
        if (at == 0) return false;
        const before = self.tokens[at - 1].kind;
        return before == .left_brace or before == .newline or before == .separator;
    }

    /// `Defer{D}` at `at`, in code that is streamed up to `to`. The statements after it, up to the
    /// end of its scope, are streamed with the `Defer` on record, so every exit among them runs
    /// `D` first; then `D` follows them, for the scope that ends normally. A failure runs none of
    /// this: it leaves through the failure machinery, past the copies.
    fn rewriteDefer(self: *Workspace, rw: *Rewrite, at: usize, to: usize, depth: usize) ParseError!usize {
        const keyword = self.tokens[at];
        if (depth >= rewrite_depth) return self.fail(keyword.span, .expression_limit);
        const close = self.segmentClose(at + 1);
        if (close >= to or self.tokens[close].kind != .right_brace) return self.fail(keyword.span, .macro_syntax);
        const body = self.trimmedStatements(at + 2, close);
        if (body[0] == body[1]) return self.fail(keyword.span, .defer_empty);
        if (!self.statementOfScope(at)) return self.fail(keyword.span, .defer_position);
        // RFC-0085, I3 (V7): the body is copied to every exit, and the copies of a nested
        // function would be code entries of one name; none stands in it, at any depth.
        for (body[0]..body[1]) |index| if (self.nestedHeaderAt(index) != null) return self.fail(self.tokens[index].span, .nested_position);
        // The scope ends at the brace that closes it, or where the range being streamed ends.
        var end = close + 1;
        var level: usize = 0;
        while (end < to) : (end += 1) {
            const kind = self.tokens[end].kind;
            if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) level += 1;
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) {
                if (level == 0) break;
                level -= 1;
            }
        }
        if (end < to and self.tokens[end].kind != .right_brace) return self.fail(keyword.span, .defer_position);
        const rest = self.trimmedStatements(close + 1, end);
        // With nothing after it there is no scope left to defer past, and a block needs a value.
        if (rest[0] == rest[1]) return self.fail(keyword.span, .defer_position);
        if (self.exit_defer_count == max_exit_defers) return self.fail(keyword.span, .expression_limit);
        const site = try self.siteFor(keyword);
        try self.requireExitWords(site);
        const index = self.exit_defer_count;
        try self.requireNumerals(site, index - self.exitMarks() + 1);
        // The mark tells the parser which names exist here: the copies of `D` see those and no later one.
        try self.emitKind(rw, .synthetic_defer_mark, keyword.span);
        self.exit_defers[index] = .{ .body = body };
        // A `Defer` that an earlier compile found open at a suspension site (RFC-0082, P3.3): a
        // copy of its body after its mark is the function a cancellation there runs.
        if (self.landingKnown(keyword.span)) try self.emitLanding(rw, site, index, depth + 1);
        try self.emitKind(rw, .separator, keyword.span);
        self.exit_defer_count += 1;
        try self.streamMacros(rw, rest[0], rest[1], depth + 1);
        std.debug.assert(self.exit_defer_count == index + 1);
        // When the scope's last statement is an exit, that exit ran the body and nothing comes after it.
        if (!self.endsInExit(rest)) {
            try self.emitKind(rw, .separator, keyword.span);
            try self.emitDeferred(rw, site, index, depth + 1);
        }
        self.exit_defer_count -= 1;
        return end;
    }

    /// Whether the last statement of `range` is a `Return(...)` or `Break()` and nothing else.
    fn endsInExit(self: *Workspace, range: [2]usize) bool {
        var start = range[0];
        var level: usize = 0;
        for (range[0]..range[1]) |index| {
            const kind = self.tokens[index].kind;
            if (kind == .left_paren or kind == .left_bracket or kind == .left_brace) level += 1;
            if (kind == .right_paren or kind == .right_bracket or kind == .right_brace) level -|= 1;
            if (level == 0 and (kind == .separator or kind == .newline)) start = index + 1;
        }
        if (start >= range[1] or self.exitAt(start) == null) return false;
        return self.segmentClose(start + 1) == range[1] - 1;
    }

    /// The copy of the body of the `Defer` at `index` that a cancellation runs (RFC-0082, P3.3),
    /// `<landing> {Body}`: a function of its own, named by a library word as the functions of
    /// copied code are, which nothing may leave and whose own `Defer`s are counted from its first.
    fn emitLanding(self: *Workspace, rw: *Rewrite, site: Site, index: u32, depth: usize) ParseError!void {
        if (depth >= rewrite_depth) return self.fail(site.keyword.span, .expression_limit);
        const body = self.exit_defers[index].body;
        const repeated = self.exit_defers[index].copies != 0;
        self.exit_defers[index].copies += 1;
        const here = self.tokens[body[0]].span;
        const position = try self.fnWord(site);
        if (position + 4 > site.library_end) return self.fail(site.keyword.span, .macro_limit);
        self.library_used[site.module] += 1;
        try self.emitTo(rw, .{ .kind = .synthetic_landing, .span = .{ .start = position, .end = position + 2 } });
        try self.emitKind(rw, .left_brace, here);
        try self.pushExitFrame(here, .{ .kind = .deferred, .defers = self.exit_defer_count, .marks = self.exit_defer_count, .repeated = repeated });
        try self.streamMacros(rw, body[0], body[1], depth + 1);
        self.exit_frame_count -= 1;
        try self.emitKind(rw, .right_brace, here);
    }

    /// One copy of the body of the `Defer` at `index`, as a block the parser runs for effect.
    fn emitDeferred(self: *Workspace, rw: *Rewrite, site: Site, index: u32, depth: usize) ParseError!void {
        if (depth >= rewrite_depth) return self.fail(site.keyword.span, .expression_limit);
        const body = self.exit_defers[index].body;
        const repeated = self.exit_defers[index].copies != 0;
        self.exit_defers[index].copies += 1;
        const here = self.tokens[body[0]].span;
        const marks = self.exitMarks();
        std.debug.assert(index >= marks);
        try self.emitKind(rw, .synthetic_defer, here);
        try self.emitTo(rw, self.numeralToken(site, index - marks));
        try self.emitKind(rw, .left_brace, here);
        try self.pushExitFrame(here, .{ .kind = .deferred, .defers = self.exit_defer_count, .marks = marks, .repeated = repeated });
        try self.streamMacros(rw, body[0], body[1], depth + 1);
        self.exit_frame_count -= 1;
        try self.emitKind(rw, .right_brace, here);
    }

    /// The locals that `[from, to)` assigns and does not declare, and that are not source cells:
    /// what a loop over that code has to carry from one visit to the next.
    fn loopVariables(self: *Workspace, keyword: Token, from: usize, to: usize, variables: *[max_exit_variables]Token) ParseError!usize {
        var count: usize = 0;
        for (from..to) |index| {
            if (!self.isName(index, "set") or index + 2 >= to) continue;
            const target = self.tokens[index + 1];
            if (target.kind != .identifier or self.tokens[index + 2].kind != .equal) continue;
            const name = target.span.text(self.source);
            var known = false;
            for (variables[0..count]) |earlier| known = known or std.mem.eql(u8, earlier.span.text(self.source), name);
            if (known or self.declaredBetween(from, to, name) or self.isSourceCell(name) or self.writesThrough(index, name) or self.sharedVar(index, name)) continue;
            if (count == variables.len) return self.fail(keyword.span, .parameter_limit);
            variables[count] = target;
            count += 1;
        }
        return count;
    }

    /// `Loop{ Body }` (RFC-0068): the Book's loop. It repeats `Body` until a `Break()` or a `Return`.
    fn rewriteLoopBlock(self: *Workspace, rw: *Rewrite, at: usize, depth: usize) ParseError!usize {
        const keyword = self.tokens[at];
        if (depth >= rewrite_depth) return self.fail(keyword.span, .expression_limit);
        const close = self.segmentClose(at + 1);
        if (close >= self.token_count or self.tokens[close].kind != .right_brace) return self.fail(keyword.span, .macro_syntax);
        const body = self.trimmedStatements(at + 2, close);
        if (body[0] == body[1]) return self.fail(keyword.span, .macro_syntax);
        var variables: [max_exit_variables]Token = undefined;
        const count = try self.loopVariables(keyword, at + 2, close, &variables);
        const site = try self.siteFor(keyword);
        try self.expandExitLoop(rw, site, .loop, &.{}, body, variables[0..count], self.exitsIn(body[0], body[1]), depth);
        return close + 1;
    }

    fn emitBind(self: *Workspace, rw: *Rewrite, name: Token, here: Span) ParseError!void {
        try self.emitTo(rw, name);
        try self.emitKind(rw, .colon, here);
        try self.emitKind(rw, .equal, here);
    }

    /// `__exit_s(index)` or `__exit_w(index)`.
    fn emitStateAt(self: *Workspace, rw: *Rewrite, site: Site, word: macros.ExitWord, index: usize) ParseError!void {
        const here = site.keyword.span;
        try self.emitTo(rw, self.exitWord(site, word));
        try self.emitKind(rw, .left_paren, here);
        try self.emitTo(rw, self.numeralToken(site, index));
        try self.emitKind(rw, .right_paren, here);
    }

    /// The type of a loop state: the mode, then what the loop carries (the locals it assigns, or
    /// the position of a `For`), then the value of a pending `Return` if one can occur.
    fn emitExitStateType(self: *Workspace, rw: *Rewrite, site: Site, loop: ExitFrame) ParseError!void {
        const here = site.keyword.span;
        try self.emitTo(rw, self.exitWord(site, .tuple_word));
        try self.emitKind(rw, .left_paren, here);
        try self.emitTo(rw, self.exitWord(site, .integer));
        if (loop.kind == .each) {
            try self.emitKind(rw, .comma, here);
            try self.emitTo(rw, self.exitWord(site, .integer));
        }
        for (loop.variables) |variable| {
            try self.emitKind(rw, .comma, here);
            try self.emitTo(rw, self.exitWord(site, .var_type));
            try self.emitKind(rw, .left_paren, here);
            try self.emitTo(rw, variable);
            try self.emitKind(rw, .right_paren, here);
        }
        if (loop.payload) {
            try self.emitKind(rw, .comma, here);
            try self.emitTo(rw, self.exitWord(site, .option_word));
            try self.emitKind(rw, .left_paren, here);
            try self.emitTo(rw, self.exitWord(site, .result_type));
            try self.emitKind(rw, .right_paren, here);
        }
        try self.emitKind(rw, .right_paren, here);
    }

    /// `Fn(__exit_s:State):option(State){`: the function of one visit. Its result type is written
    /// out because the visit may end with a `Return` of it, and its effects are those of the code
    /// around the loop, so that a failure in the body is the failure of that code.
    fn emitExitFunction(self: *Workspace, rw: *Rewrite, site: Site, loop: ExitFrame) ParseError!void {
        const here = site.keyword.span;
        const position = try self.fnWord(site);
        if (position + 4 > site.library_end) return self.fail(here, .macro_limit);
        self.library_used[site.module] += 1;
        try self.emitTo(rw, .{ .kind = .identifier, .span = .{ .start = position, .end = position + 2 } });
        try self.emitKind(rw, .left_paren, here);
        try self.emitTo(rw, self.exitWord(site, .state));
        try self.emitKind(rw, .colon, here);
        try self.emitExitStateType(rw, site, loop);
        try self.emitKind(rw, .right_paren, here);
        try self.emitKind(rw, .synthetic_inherit, here);
        try self.emitKind(rw, .colon, here);
        try self.emitTo(rw, self.exitWord(site, .option_word));
        try self.emitKind(rw, .left_paren, here);
        try self.emitExitStateType(rw, site, loop);
        try self.emitKind(rw, .right_paren, here);
        try self.emitKind(rw, .left_brace, here);
    }

    /// `If(__exit_w(0)==mode,`: the start of a test of how a loop ended.
    fn emitEndedWith(self: *Workspace, rw: *Rewrite, site: Site, mode: u32) ParseError!void {
        const here = site.keyword.span;
        try self.emitTo(rw, self.exitWord(site, .if_word));
        try self.emitKind(rw, .left_paren, here);
        try self.emitStateAt(rw, site, .ended, 0);
        try self.emitKind(rw, .equal_equal, here);
        try self.emitTo(rw, self.numeralToken(site, mode));
        try self.emitKind(rw, .comma, here);
    }

    /// What follows a loop: its value, `true`, unless its final state says that a `Return` or an
    /// outer `Break` is pending; then this code exits in its turn. A loop that can only end by a
    /// `Return` has no value, so it fits wherever it stands.
    fn emitExitDispatch(self: *Workspace, rw: *Rewrite, site: Site, kind: @FieldType(ExitFrame, "kind"), exits: Exits, payload_index: u32, depth: usize) ParseError!void {
        const here = site.keyword.span;
        const none: [2]usize = .{ 0, 0 };
        const passes_break = kind != .loop and exits.breaks;
        if (kind == .loop and exits.returns and !exits.breaks) return self.emitExit(rw, site.keyword, .leave, none, payload_index, depth + 1);
        var open: usize = 0;
        if (exits.returns) {
            try self.emitEndedWith(rw, site, exit_returning);
            try self.emitExit(rw, site.keyword, .leave, none, payload_index, depth + 1);
            try self.emitKind(rw, .comma, here);
            open += 1;
        }
        if (passes_break) {
            try self.emitEndedWith(rw, site, exit_breaking);
            try self.emitExit(rw, site.keyword, .stop, none, null, depth + 1);
            try self.emitKind(rw, .comma, here);
            open += 1;
        }
        try self.emitTo(rw, self.exitWord(site, .true_word));
        for (0..open) |_| try self.emitKind(rw, .right_paren, here);
    }

    /// A `Loop{}`, or a `While` that something leaves early: a state loop over
    /// `tuple(mode, V1, ..., pending)`. A visit redeclares the locals from the state and, while
    /// the mode says the loop is running and the conditions hold, runs the body and continues
    /// with the locals as they are then. An exit in the body returns a state with another mode,
    /// which the next visit hands back unchanged, and that ends the loop.
    fn expandExitLoop(self: *Workspace, rw: *Rewrite, site: Site, kind: @FieldType(ExitFrame, "kind"), conditions: []const [2]usize, body: [2]usize, variables: []const Token, exits: Exits, depth: usize) ParseError!void {
        std.debug.assert(kind == .loop or kind == .repeat);
        const here = site.keyword.span;
        const payload_index: u32 = @intCast(variables.len + 1);
        try self.requireExitWords(site);
        try self.requireNumerals(site, variables.len + 2);
        const loop: ExitFrame = .{ .kind = kind, .defers = self.exit_defer_count, .marks = self.exit_defer_count, .variables = variables, .payload = exits.returns };
        // Block{__exit_w:=Loop(Fn(__exit_s:State):option(State){Block{
        try self.emitTo(rw, self.exitWord(site, .block));
        try self.emitKind(rw, .left_brace, here);
        try self.emitBind(rw, self.exitWord(site, .ended), here);
        try self.emitTo(rw, self.exitWord(site, .loop));
        try self.emitKind(rw, .left_paren, here);
        try self.emitExitFunction(rw, site, loop);
        try self.emitTo(rw, self.exitWord(site, .block));
        try self.emitKind(rw, .left_brace, here);
        // var V:__type(V)=__exit_s(i);
        for (variables, 1..) |variable, index| {
            try self.emitTo(rw, self.exitWord(site, .var_word));
            try self.emitTo(rw, variable);
            try self.emitKind(rw, .colon, here);
            try self.emitTo(rw, self.exitWord(site, .type_of));
            try self.emitKind(rw, .left_paren, here);
            try self.emitTo(rw, variable);
            try self.emitKind(rw, .right_paren, here);
            try self.emitKind(rw, .equal, here);
            try self.emitStateAt(rw, site, .state, index);
            try self.emitKind(rw, .separator, here);
        }
        // If(__exit_s(0)==0, [If(Conditions,] Block{Statements option{State}} [,option{})] ,option{})
        try self.emitTo(rw, self.exitWord(site, .if_word));
        try self.emitKind(rw, .left_paren, here);
        try self.emitStateAt(rw, site, .state, 0);
        try self.emitKind(rw, .equal_equal, here);
        try self.emitTo(rw, self.numeralToken(site, exit_running));
        try self.emitKind(rw, .comma, here);
        // The conditions and the body both run in the visit's function: an exit in either leaves it.
        try self.pushExitFrame(here, loop);
        if (conditions.len != 0) {
            try self.emitTo(rw, self.exitWord(site, .if_word));
            try self.emitKind(rw, .left_paren, here);
            for (conditions) |condition| {
                try self.streamMacros(rw, condition[0], condition[1], depth + 1);
                try self.emitKind(rw, .comma, here);
            }
        }
        try self.emitTo(rw, self.exitWord(site, .block));
        try self.emitKind(rw, .left_brace, here);
        // The body is a list of statements: the inside of a lone `Block{...}`, or one expression.
        var statements = body;
        if (statements[1] - statements[0] >= 3 and self.isName(statements[0], "Block") and self.tokens[statements[0] + 1].kind == .left_brace and self.tokens[statements[1] - 1].kind == .right_brace and self.segmentClose(statements[0] + 1) == statements[1] - 1) {
            statements = self.trimmedStatements(statements[0] + 2, statements[1] - 1);
        }
        if (statements[0] != statements[1]) {
            try self.streamMacros(rw, statements[0], statements[1], depth + 1);
            try self.emitKind(rw, .separator, here);
        }
        self.exit_frame_count -= 1;
        try self.emitTo(rw, self.exitWord(site, .option_word));
        try self.emitKind(rw, .left_brace, here);
        try self.emitExitState(rw, site, loop, exit_running, .none, depth + 1);
        try self.emitAggregateEnd(rw, site);
        try self.emitKind(rw, .right_brace, here);
        for (0..@as(usize, if (conditions.len != 0) 2 else 1)) |_| {
            try self.emitKind(rw, .comma, here);
            try self.emitTo(rw, self.exitWord(site, .option_word));
            try self.emitKind(rw, .left_brace, here);
            try self.emitAggregateEnd(rw, site);
            try self.emitKind(rw, .right_paren, here);
        }
        // }},State);
        try self.emitKind(rw, .right_brace, here);
        try self.emitKind(rw, .right_brace, here);
        try self.emitKind(rw, .comma, here);
        try self.emitExitState(rw, site, loop, exit_running, .none, depth + 1);
        try self.emitKind(rw, .right_paren, here);
        try self.emitKind(rw, .separator, here);
        // set V=__exit_w(i);
        for (variables, 1..) |variable, index| {
            try self.emitTo(rw, self.exitWord(site, .set_word));
            try self.emitTo(rw, variable);
            try self.emitKind(rw, .equal, here);
            try self.emitStateAt(rw, site, .ended, index);
            try self.emitKind(rw, .separator, here);
        }
        try self.emitExitDispatch(rw, site, kind, exits, payload_index, depth);
        try self.emitKind(rw, .right_brace, here);
    }

    /// One generator of a `For` that something leaves early: a state loop over
    /// `tuple(mode, position, pending)` that binds the generator's names and runs what follows
    /// (bindings, filters, the next generator or the body) in a region of its own, as every
    /// general `For` does, so that a failure skips the iteration. Such a `For` is run for what it
    /// does: it builds no array and its value is `true`.
    fn expandExitFor(self: *Workspace, rw: *Rewrite, site: Site, plan: *const ForPlan, index: usize, exits: Exits, depth: usize) ParseError!void {
        if (depth >= rewrite_depth) return self.fail(site.keyword.span, .expression_limit);
        const clause = plan.clauses[index];
        std.debug.assert(clause.kind == .generator or clause.kind == .range);
        const here = site.keyword.span;
        const ranged = clause.kind == .range;
        try self.requireExitWords(site);
        // An inner generator's source runs in the iteration around it (RFC-0082, P3.8).
        if (plan.suspends and index != 0) self.noteSuspendClause(site, self.forClauseSpan(clause), false);
        // The state is the mode, the position, the locals the loop carries and the pending value.
        const variables = plan.variables;
        if (variables.len != 0) try self.requireNumerals(site, variables.len + 3);
        const loop: ExitFrame = .{ .kind = .each, .defers = self.exit_defer_count, .marks = self.exit_defer_count, .variables = variables, .payload = exits.returns };
        try self.emitTo(rw, self.exitWord(site, .block));
        try self.emitKind(rw, .left_brace, here);
        if (ranged) {
            // __for_lo:=(Low);__for_hi:=(High);__for_n:=If(__for_lo<=__for_hi,__for_hi-__for_lo+1,0);
            try self.emitBind(rw, self.exitWord(site, .low), here);
            try self.emitKind(rw, .left_paren, here);
            try self.streamMacros(rw, clause.expr[0], clause.expr[1], depth + 1);
            try self.emitKind(rw, .right_paren, here);
            try self.emitKind(rw, .separator, here);
            try self.emitBind(rw, self.exitWord(site, .high), here);
            try self.emitKind(rw, .left_paren, here);
            try self.streamMacros(rw, clause.high[0], clause.high[1], depth + 1);
            try self.emitKind(rw, .right_paren, here);
            try self.emitKind(rw, .separator, here);
            try self.emitBind(rw, self.exitWord(site, .count), here);
            try self.emitTo(rw, self.exitWord(site, .if_word));
            try self.emitKind(rw, .left_paren, here);
            try self.emitTo(rw, self.exitWord(site, .low));
            try self.emitKind(rw, .less_equal, here);
            try self.emitTo(rw, self.exitWord(site, .high));
            try self.emitKind(rw, .comma, here);
            try self.emitTo(rw, self.exitWord(site, .high));
            try self.emitKind(rw, .minus, here);
            try self.emitTo(rw, self.exitWord(site, .low));
            try self.emitKind(rw, .plus, here);
            try self.emitTo(rw, self.numeralToken(site, 1));
            try self.emitKind(rw, .comma, here);
            try self.emitTo(rw, self.numeralToken(site, 0));
            try self.emitKind(rw, .right_paren, here);
        } else {
            // __for_items:=(Items);
            try self.emitBind(rw, self.exitWord(site, .items), here);
            try self.emitKind(rw, .left_paren, here);
            try self.streamMacros(rw, clause.expr[0], clause.expr[1], depth + 1);
            try self.emitKind(rw, .right_paren, here);
        }
        try self.emitKind(rw, .separator, here);
        // __exit_w:=Loop(Fn(__exit_s:State):option(State){If(__exit_s(0)==0 and __exit_s(1)<Count,Block{
        try self.emitBind(rw, self.exitWord(site, .ended), here);
        try self.emitTo(rw, self.exitWord(site, .loop));
        try self.emitKind(rw, .left_paren, here);
        try self.emitExitFunction(rw, site, loop);
        try self.emitTo(rw, self.exitWord(site, .if_word));
        try self.emitKind(rw, .left_paren, here);
        try self.emitStateAt(rw, site, .state, 0);
        try self.emitKind(rw, .equal_equal, here);
        try self.emitTo(rw, self.numeralToken(site, exit_running));
        try self.emitTo(rw, self.exitWord(site, .and_word));
        try self.emitStateAt(rw, site, .state, 1);
        try self.emitKind(rw, .less, here);
        if (ranged) {
            try self.emitTo(rw, self.exitWord(site, .count));
        } else {
            try self.emitTo(rw, self.exitWord(site, .items));
            try self.emitKind(rw, .dot, here);
            try self.emitTo(rw, self.exitWord(site, .length));
        }
        try self.emitKind(rw, .comma, here);
        try self.emitTo(rw, self.exitWord(site, .block));
        try self.emitKind(rw, .left_brace, here);
        // var V:__type(V)=__exit_s(i);
        for (variables, 2..) |variable, place| {
            try self.emitTo(rw, self.exitWord(site, .var_word));
            try self.emitTo(rw, variable);
            try self.emitKind(rw, .colon, here);
            try self.emitTo(rw, self.exitWord(site, .type_of));
            try self.emitKind(rw, .left_paren, here);
            try self.emitTo(rw, variable);
            try self.emitKind(rw, .right_paren, here);
            try self.emitKind(rw, .equal, here);
            try self.emitStateAt(rw, site, .state, place);
            try self.emitKind(rw, .separator, here);
        }
        // X:=ElementAt(__for_items,__exit_s(1));  or  X:=__for_lo+__exit_s(1);
        try self.emitBind(rw, clause.name.?, here);
        if (ranged) {
            try self.emitTo(rw, self.exitWord(site, .low));
            try self.emitKind(rw, .plus, here);
            try self.emitStateAt(rw, site, .state, 1);
        } else {
            try self.emitTo(rw, self.exitWord(site, .element_at));
            try self.emitKind(rw, .left_paren, here);
            try self.emitTo(rw, self.exitWord(site, .items));
            try self.emitKind(rw, .comma, here);
            try self.emitStateAt(rw, site, .state, 1);
            try self.emitKind(rw, .right_paren, here);
        }
        try self.emitKind(rw, .separator, here);
        if (clause.index_name) |key| {
            try self.emitBind(rw, key, here);
            try self.emitTo(rw, self.exitWord(site, .key_at));
            try self.emitKind(rw, .left_paren, here);
            try self.emitTo(rw, self.exitWord(site, .items));
            try self.emitKind(rw, .comma, here);
            try self.emitStateAt(rw, site, .state, 1);
            try self.emitKind(rw, .right_paren, here);
            try self.emitKind(rw, .separator, here);
        }
        // Attempt(Block{Checks Rest;true},false); or, where an iteration holds a site (RFC-0082,
        // P3.8), without the region: Block{Y:=(V);__for_keep:=(F);If(__for_keep,Block{Rest;true},false)};
        if (!plan.suspends) {
            try self.emitTo(rw, self.exitWord(site, .attempt));
            try self.emitKind(rw, .left_paren, here);
        }
        try self.emitTo(rw, self.exitWord(site, .block));
        try self.emitKind(rw, .left_brace, here);
        try self.pushExitFrame(here, loop);
        var stop = index + 1;
        while (stop < plan.clauses.len and (plan.clauses[stop].kind == .binding or plan.clauses[stop].kind == .filter)) stop += 1;
        var opened: usize = 0;
        for (plan.clauses[index + 1 .. stop]) |check| {
            if (plan.suspends) {
                const keep = self.templateWord(site, .for_filter, "__for_keep");
                self.noteSuspendClause(site, self.forClauseSpan(check), false);
                try self.expandTemplate(rw, site, .check_bind, &.{ .name = check.name orelse keep, .first = check.expr }, depth + 1);
                if (check.kind == .binding) continue;
                try self.emitTo(rw, self.exitWord(site, .if_word));
                try self.emitKind(rw, .left_paren, here);
                try self.emitTo(rw, keep);
                try self.emitKind(rw, .comma, here);
                try self.emitTo(rw, self.exitWord(site, .block));
                try self.emitKind(rw, .left_brace, here);
                opened += 1;
                continue;
            }
            const piece: Fill = .{ .name = check.name, .first = check.expr, .blame = self.userSpan(check.expr) };
            try self.expandTemplate(rw, site, if (check.name != null) .check_bind else .check_test, &piece, depth + 1);
        }
        if (stop < plan.clauses.len) try self.expandExitFor(rw, site, plan, stop, exits, depth + 1) else {
            if (plan.suspends) self.noteSuspendClause(site, self.userSpan(plan.body), true);
            try self.streamMacros(rw, plan.body[0], plan.body[1], depth + 1);
        }
        self.exit_frame_count -= 1;
        try self.emitKind(rw, .separator, here);
        try self.emitTo(rw, self.exitWord(site, .true_word));
        for (0..opened) |_| {
            try self.emitKind(rw, .right_brace, here);
            try self.emitKind(rw, .comma, here);
            try self.emitKind(rw, .synthetic_false, here);
            try self.emitKind(rw, .right_paren, here);
        }
        try self.emitKind(rw, .right_brace, here);
        if (!plan.suspends) {
            try self.emitKind(rw, .comma, here);
            try self.emitKind(rw, .synthetic_false, here);
            try self.emitKind(rw, .right_paren, here);
        }
        try self.emitKind(rw, .separator, here);
        // option{tuple{0,__exit_s(1)+1,option{}}}},option{})},tuple{0,0,option{}});
        try self.emitTo(rw, self.exitWord(site, .option_word));
        try self.emitKind(rw, .left_brace, here);
        try self.emitTo(rw, self.exitWord(site, .tuple_word));
        try self.emitKind(rw, .left_brace, here);
        try self.emitTo(rw, self.numeralToken(site, exit_running));
        try self.emitKind(rw, .comma, here);
        try self.emitStateAt(rw, site, .state, 1);
        try self.emitKind(rw, .plus, here);
        try self.emitTo(rw, self.numeralToken(site, 1));
        // A skipped iteration's attempt has put back what it assigned.
        for (variables) |variable| {
            try self.emitKind(rw, .comma, here);
            try self.emitTo(rw, variable);
        }
        if (loop.payload) {
            try self.emitKind(rw, .comma, here);
            try self.emitTo(rw, self.exitWord(site, .option_word));
            try self.emitKind(rw, .left_brace, here);
            try self.emitAggregateEnd(rw, site);
        }
        try self.emitAggregateEnd(rw, site);
        try self.emitAggregateEnd(rw, site);
        try self.emitKind(rw, .right_brace, here);
        try self.emitKind(rw, .comma, here);
        try self.emitTo(rw, self.exitWord(site, .option_word));
        try self.emitKind(rw, .left_brace, here);
        try self.emitAggregateEnd(rw, site);
        try self.emitKind(rw, .right_paren, here);
        try self.emitKind(rw, .right_brace, here);
        try self.emitKind(rw, .comma, here);
        try self.emitExitState(rw, site, loop, exit_running, .none, depth + 1);
        try self.emitKind(rw, .right_paren, here);
        try self.emitKind(rw, .separator, here);
        // set V=__exit_w(i);
        for (variables, 2..) |variable, place| {
            try self.emitTo(rw, self.exitWord(site, .set_word));
            try self.emitTo(rw, variable);
            try self.emitKind(rw, .equal, here);
            try self.emitStateAt(rw, site, .ended, place);
            try self.emitKind(rw, .separator, here);
        }
        try self.emitExitDispatch(rw, site, .each, exits, @intCast(variables.len + 2), depth);
        try self.emitKind(rw, .right_brace, here);
    }

    /// `Return` is the last thing its scope does (the Book's tail position): the whole body of a
    /// function, the last statement of a `Block`, `Loop{}` or `Defer` body, an arm of `If`,
    /// `Attempt` or `Case`, or the body of a `For` or `While`. One pass over the tokens as the
    /// user wrote them, with the brackets open at each point, checks every `Return`.
    fn checkReturns(self: *Workspace) ParseError!void {
        // RFC-0084, P4.6: whether `Await(` is the form is asked here too (`armsAt`), before the
        // macro pass sets the flag again.
        self.await_named = self.namesAwait();
        var first: ?usize = null;
        for (0..self.token_count - 1) |index| {
            if (self.tokens[index].kind == .identifier and self.tokens[index + 1].kind == .left_paren and self.isName(index, "Return")) {
                first = index;
                break;
            }
        }
        if (first == null) return;
        const Open = struct {
            at: u32,
            /// Arguments or statements completed so far.
            items: u32 = 0,
            /// Where the current statement or argument starts.
            start: u32,
            /// The parenthesis of a `Return(`, and whether its statement is a function's whole body.
            exit: bool = false,
            body: bool = false,
        };
        const stack = scratch.alloc(Open, types.limits.expression_depth + 2) orelse return self.fail(self.tokens[first.?].span, .expression_limit);
        defer scratch.free(stack);
        // The file itself is the outermost scope.
        stack[0] = .{ .at = 0, .start = 0 };
        var depth: usize = 1;
        var index: usize = 0;
        while (index < self.token_count) : (index += 1) {
            const kind = self.tokens[index].kind;
            const top = &stack[depth - 1];
            switch (kind) {
                .left_paren, .left_bracket, .left_brace => {
                    if (depth == stack.len) return self.fail(self.tokens[index].span, .expression_limit);
                    var open: Open = .{ .at = @intCast(index), .start = @intCast(index + 1) };
                    if (kind == .left_paren and index != 0 and self.isName(index - 1, "Return")) {
                        open.exit = true;
                        open.body = try self.returnPlace(stack[0..depth], index - 1);
                    }
                    stack[depth] = open;
                    depth += 1;
                },
                .right_paren, .right_bracket, .right_brace => {
                    // Unbalanced brackets are the parser's to report.
                    if (depth == 1) return;
                    depth -= 1;
                    const closed = stack[depth];
                    if (closed.exit and !self.returnEnds(stack[0..depth], index, closed.body)) return self.fail(self.tokens[closed.at - 1].span, .return_not_tail);
                },
                .comma => {
                    top.items += 1;
                    top.start = @intCast(index + 1);
                },
                .separator, .newline => {
                    // Between parentheses a newline separates nothing; it only precedes an argument.
                    const statements = depth == 1 or self.tokens[top.at].kind == .left_brace;
                    if (statements or top.start == index) top.start = @intCast(index + 1);
                },
                else => {},
            }
        }
    }

    /// Whether the `Return` at `at` may start where it does; the result says that it is the whole
    /// body of a function `Name(...)...=Return(...)`. `opens` are the brackets open around it.
    fn returnPlace(self: *Workspace, opens: anytype, at: usize) ParseError!bool {
        const inside = opens[opens.len - 1];
        const keyword = self.tokens[at];
        if (at == 0) return self.fail(keyword.span, .return_not_tail);
        const in_call = opens.len > 1 and self.tokens[inside.at].kind == .left_paren;
        var previous = at - 1;
        while (in_call and previous > inside.at and self.tokens[previous].kind == .newline) previous -= 1;
        const before = self.tokens[previous].kind;
        if (before == .equal) {
            // The body of a function or method: its statement starts `Name(`, `Name<` or `Name[`.
            const start = inside.start;
            const declares = start + 1 < at and self.tokens[start].kind == .identifier and !self.isName(start, "set") and !self.isName(start, "var") and (self.tokens[start + 1].kind == .left_paren or self.tokens[start + 1].kind == .less or self.tokens[start + 1].kind == .left_bracket);
            if (!declares) return self.fail(keyword.span, .return_not_tail);
            return true;
        }
        const opener = self.tokens[inside.at].kind;
        if (opens.len == 1 or opener == .left_bracket) return self.fail(keyword.span, .return_not_tail);
        if (opener == .left_brace) {
            // A statement of a block or the body of a function; never a member of a literal.
            if (before != .left_brace and before != .separator and before != .newline) return self.fail(keyword.span, .return_not_tail);
            if (inside.at != 0) for ([_][]const u8{ "array", "tuple", "map", "option" }) |literal| {
                if (self.isName(inside.at - 1, literal)) return self.fail(keyword.span, .return_not_tail);
            };
            return false;
        }
        // An argument: of `If` after its conditions, of `Attempt`, an arm of `Case`, the body of a loop.
        if (inside.at == 0) return self.fail(keyword.span, .return_not_tail);
        const callee = inside.at - 1;
        if (self.isName(callee, "Case")) {
            if (before != .arrow) return self.fail(keyword.span, .return_not_tail);
            return false;
        }
        if (before != .comma and before != .left_paren) return self.fail(keyword.span, .return_not_tail);
        if (inside.start != at) return self.fail(keyword.span, .return_not_tail);
        const count = self.argumentCount(inside.at);
        const position = inside.items;
        // An arm of `Sync`, `Race` or `Rush` is written like an argument of `Attempt` (P3.6).
        const allowed = if (self.isName(callee, "Attempt") or self.armsAt(callee)) true else if (self.isName(callee, "If")) position >= 1 and position + 2 >= count else if (self.isName(callee, "For") or self.isName(callee, "While")) position + 1 == count else false;
        if (!allowed) return self.fail(keyword.span, .return_not_tail);
        return false;
    }

    /// Whether nothing follows the `Return` whose `)` is at `close` in its scope.
    fn returnEnds(self: *Workspace, opens: anytype, close: usize, body: bool) bool {
        const in_call = !body and opens.len > 1 and self.tokens[opens[opens.len - 1].at].kind == .left_paren;
        var next = close + 1;
        var separated = false;
        while (next < self.token_count and (self.tokens[next].kind == .newline or (!in_call and self.tokens[next].kind == .separator))) : (next += 1) separated = true;
        if (next >= self.token_count) return true;
        const after = self.tokens[next].kind;
        // An argument ends at the comma or parenthesis after it.
        if (in_call) return after == .comma or after == .right_paren;
        if (after == .eof or after == .right_brace) return true;
        // A function's body ends with its line; the next declaration follows.
        return body and (separated or after == .comma or after == .right_paren);
    }

    /// `Not[E]` is a failure-context check that succeeds when `E` fails.
    fn rewriteNot(self: *Workspace, rw: *Rewrite, at: usize, depth: usize) ParseError!usize {
        const keyword = self.tokens[at];
        if (depth >= rewrite_depth) return self.fail(keyword.span, .expression_limit);
        const close = self.segmentClose(at + 1);
        if (close >= self.token_count or self.tokens[close].kind != .right_bracket) return self.fail(keyword.span, .macro_syntax);
        const inner = self.trimmed(at + 2, close);
        if (inner[0] == inner[1]) return self.fail(keyword.span, .macro_syntax);
        const site = try self.siteFor(keyword);
        try self.expandTemplate(rw, site, .not_test, &.{ .first = inner, .blame = self.userSpan(.{ at, close + 1 }) }, depth);
        return close + 1;
    }

    /// `SortBy(Items, Less)` (RFC-0081): the array `Items` in the order `Less` gives, stably.
    /// `Less(Left, Right)` is a failable function that succeeds when `Left` goes before
    /// `Right`; the template evaluates `Items`, then `Less`, once each, and calls `Less` in a
    /// failure context of its own each time, so a comparison that fails undoes its writes.
    fn rewriteSortBy(self: *Workspace, rw: *Rewrite, at: usize, depth: usize) ParseError!usize {
        const keyword = self.tokens[at];
        if (depth >= rewrite_depth) return self.fail(keyword.span, .expression_limit);
        var bounds: [4]usize = undefined;
        const call = try self.splitCall(keyword, at + 1, &bounds, .argument_count);
        if (call.items != 2) return self.fail(keyword.span, .argument_count);
        const items = self.trimmed(bounds[0], bounds[1] - 1);
        const less = self.trimmed(bounds[1], bounds[2] - 1);
        if (items[0] == items[1] or less[0] == less[1]) return self.fail(keyword.span, .expected_expression);
        // A named argument is a call of a function with named parameters, which this is not.
        for ([_][2]usize{ items, less }) |argument| if (argument[1] - argument[0] >= 3 and self.tokens[argument[0]].kind == .identifier and self.tokens[argument[0] + 1].kind == .colon and self.tokens[argument[0] + 2].kind == .equal) return self.fail(self.tokens[argument[0]].span, .unknown_parameter);
        const site = try self.siteFor(keyword);
        if (!site.extension.sorts) return self.requestExtension(site, .{ .sorts = true, .words = site.extension.words + self.wordsNeeded(site.module) });
        try self.expandTemplate(rw, site, .sort_by, &.{ .first = items, .second = less }, depth);
        return call.close + 1;
    }

    /// `While(C1, ..., Body)` runs `Body` while the conditions hold (a failing condition stops the
    /// loop and undoes its own writes). The locals that `Body` assigns with `set` are the loop
    /// state: each visit sees their current values, and their final values are stored back.
    fn rewriteWhile(self: *Workspace, rw: *Rewrite, at: usize, depth: usize) ParseError!usize {
        // The loop is a function of its state, a tuple of a flag and the variables, and its body
        // names each variable, which captures it (`captureFreeNames`). Captures share the
        // parameter list with that one parameter, and that list is shorter than a tuple is wide.
        const max_loop_variables = @min(types.limits.tuple_arity, types.limits.parameters) - 1;
        const keyword = self.tokens[at];
        if (depth >= rewrite_depth) return self.fail(keyword.span, .expression_limit);
        var bounds: [max_checks + 4]usize = undefined;
        const call = try self.splitCall(keyword, at + 1, &bounds, .macro_syntax);
        const items = call.items;
        if (items < 2) return self.fail(keyword.span, .macro_syntax);
        var conditions: [max_checks][2]usize = undefined;
        if (items - 1 > conditions.len) return self.fail(keyword.span, .expression_limit);
        for (0..items - 1) |item| {
            conditions[item] = self.trimmed(bounds[item], bounds[item + 1] - 1);
            if (conditions[item][0] == conditions[item][1]) return self.fail(keyword.span, .macro_syntax);
        }
        const body = self.trimmed(bounds[items - 1], bounds[items] - 1);
        if (body[0] == body[1]) return self.fail(keyword.span, .macro_syntax);
        // The locals assigned inside, but declared outside, the loop and that are not source cells.
        var variables: [max_loop_variables]Token = undefined;
        var count: usize = 0;
        for (at + 2..call.close) |index| {
            if (!self.isName(index, "set") or index + 2 >= call.close) continue;
            const target = self.tokens[index + 1];
            if (target.kind != .identifier or self.tokens[index + 2].kind != .equal) continue;
            const name = target.span.text(self.source);
            var known = false;
            for (variables[0..count]) |earlier| known = known or std.mem.eql(u8, earlier.span.text(self.source), name);
            if (known or self.declaredBetween(at + 2, call.close, name) or self.isSourceCell(name) or self.writesThrough(index, name) or self.sharedVar(index, name)) continue;
            if (count == variables.len) return self.fail(keyword.span, .parameter_limit);
            variables[count] = target;
            count += 1;
        }
        const site = try self.siteFor(keyword);
        const exits = self.exitsIn(at + 2, call.close);
        if (exits.returns or exits.breaks) {
            // Something leaves this loop early (RFC-0068): its state says how each visit ended.
            try self.expandExitLoop(rw, site, .repeat, conditions[0 .. items - 1], body, variables[0..count], exits, depth);
            return call.close + 1;
        }
        try self.requireNumerals(site, count + 1);
        try self.expandTemplate(rw, site, .while_loop, &.{ .second = body, .conditions = conditions[0 .. items - 1], .variables = variables[0..count] }, depth);
        return call.close + 1;
    }

    /// Whether `name` is declared with `var` or by a binding between two token indices.
    fn declaredBetween(self: *Workspace, from: usize, to: usize, name: []const u8) bool {
        for (from..to) |index| {
            if (self.isName(index, "var") and index + 1 < to and self.tokens[index + 1].kind == .identifier and std.mem.eql(u8, self.tokens[index + 1].span.text(self.source), name)) return true;
        }
        return false;
    }

    /// Whether the `set` at `index` is the rewrite of `set Name.Field = v` or `set Name[I] = v` on a
    /// name that is not a `var` local: `Self`, a parameter or an immutable binding. Such a write goes
    /// into the instance the name refers to and assigns nothing (`updatesInstance`), so a loop has
    /// no state to carry for it; carried, the name would be stored back and refused as not mutable.
    fn writesThrough(self: *Workspace, index: usize, name: []const u8) bool {
        const next = self.tokens[index + 3].kind;
        if (next != .synthetic_with_field and next != .synthetic_with_index) return false;
        // A `var` local of that name in a scope still open here is what the `set` assigns. A
        // `var` directly inside a class body is a field, which is reached through an instance.
        var depth: usize = 0;
        var declared: ?usize = null;
        var class_body = false;
        for (0..index) |at| {
            // The body of a nested module is a top level too (RFC-0074): a class declared
            // there has its fields one brace in, as in a file.
            if (self.moduleBrace(self.tokens[at])) continue;
            switch (self.tokens[at].kind) {
                .left_paren, .left_bracket, .left_brace => depth += 1,
                .right_paren, .right_bracket, .right_brace => {
                    depth -|= 1;
                    if (declared) |opened| if (depth < opened) {
                        declared = null;
                    };
                },
                .newline, .separator => if (depth == 0) {
                    class_body = false;
                },
                else => {},
            }
            if (depth == 0 and (self.isName(at, "class") or self.isName(at, "interface"))) class_body = true;
            if (depth == 0 or declared != null or (depth == 1 and class_body)) continue;
            if (self.isName(at, "var") and self.tokens[at + 1].kind == .identifier and std.mem.eql(u8, self.tokens[at + 1].span.text(self.source), name)) declared = depth;
        }
        return declared == null;
    }

    /// Whether `name` is declared `var` at the top level of some module (a source cell, which every
    /// function sees directly and a loop must not copy).
    fn isSourceCell(self: *Workspace, name: []const u8) bool {
        // Asked for every assignment in every loop: one pass over the tokens indexes the
        // declarations, where a pass per question would cost their product.
        if (self.cellNames()) |names| {
            var probe = names.probe(name_index.hashName(0, name));
            while (probe.next()) |entry| if (std.mem.eql(u8, self.cell_spans[entry].text(self.source), name)) return true;
            return false;
        }
        var depth: usize = 0;
        for (0..self.token_count) |index| {
            // The braces of a nested module do not hide its cells: its body is a top level too.
            if (self.moduleBrace(self.tokens[index])) continue;
            switch (self.tokens[index].kind) {
                .left_paren, .left_bracket, .left_brace => depth += 1,
                .right_paren, .right_bracket, .right_brace => depth -|= 1,
                else => {},
            }
            if (depth == 0 and self.isName(index, "var") and index + 1 < self.token_count and self.tokens[index + 1].kind == .identifier and std.mem.eql(u8, self.tokens[index + 1].span.text(self.source), name)) return true;
        }
        return false;
    }

    /// `If(C1, ..., Cn, Then, Else)` with `n >= 2` conditions. A condition `Name := value` binds
    /// `Name` for the later conditions and for `Then`; any other condition must succeed. The first
    /// failure selects `Else` and undoes the writes of the conditions run so far.
    fn rewriteIf(self: *Workspace, rw: *Rewrite, at: usize, depth: usize) ParseError!usize {
        const keyword = self.tokens[at];
        if (depth >= rewrite_depth) return self.fail(keyword.span, .expression_limit);
        var bounds: [max_checks + 4]usize = undefined;
        const call = try self.splitCall(keyword, at + 1, &bounds, .macro_syntax);
        const items = call.items;
        // RFC-0090: two arguments are one binding condition and `Then`, without an else.
        const elseless = items == 2;
        if (items < 2) return self.fail(keyword.span, .macro_syntax);
        var checks: [max_checks]Check = undefined;
        const count = if (elseless) 1 else items - 2;
        var bound: usize = 0;
        for (0..count) |item| {
            const range = self.trimmed(bounds[item], bounds[item + 1] - 1);
            if (range[0] == range[1]) return self.fail(keyword.span, .macro_syntax);
            const binds = range[0] + 3 < range[1] and self.tokens[range[0]].kind == .identifier and self.tokens[range[0] + 1].kind == .colon and self.tokens[range[0] + 2].kind == .equal and self.tokens[range[0] + 1].span.end == self.tokens[range[0] + 2].span.start;
            if (binds) {
                bound += 1;
                checks[item] = .{ .name = self.tokens[range[0]], .expr = .{ range[0] + 3, range[1] } };
            } else checks[item] = .{ .name = null, .expr = range };
        }
        const then = if (elseless) self.trimmed(bounds[1], bounds[2] - 1) else self.trimmed(bounds[items - 2], bounds[items - 1] - 1);
        const otherwise: [2]usize = if (elseless) .{ 0, 0 } else self.trimmed(bounds[items - 1], bounds[items] - 1);
        if (then[0] == then[1] or (!elseless and otherwise[0] == otherwise[1])) return self.fail(keyword.span, .macro_syntax);
        const site = try self.siteFor(keyword);
        // The bound values travel as one tuple, and there are no more of them than checks.
        comptime std.debug.assert(max_checks <= types.limits.tuple_arity);
        try self.requireNumerals(site, bound);
        try self.expandTemplate(rw, site, .if_bound, &.{ .second = then, .third = otherwise, .checks = checks[0..count], .no_else = elseless }, depth);
        return call.close + 1;
    }

    /// `(A, B, C) := value` at the start of a statement binds each name to the matching element of
    /// the tuple, evaluating `value` once.
    fn rewriteDestructure(self: *Workspace, rw: *Rewrite, at: usize, depth: usize) ParseError!usize {
        const keyword = self.tokens[at];
        if (depth >= rewrite_depth) return self.fail(keyword.span, .expression_limit);
        const assign = self.destructureEnd(at).?;
        const stop = try self.statementEnd(assign + 1);
        if (stop == assign + 1) return self.fail(keyword.span, .macro_syntax);
        // The pattern is `(`, names with commas between them, `)`, `:=`: a name at every other token.
        const count = (assign - at - 1) / 2;
        std.debug.assert(count >= 2 and assign == at + 2 * count + 2);
        // The value is one tuple with an element per name.
        if (count > types.limits.tuple_arity) return self.fail(keyword.span, .tuple_limit);
        const site = try self.siteFor(keyword);
        try self.requireNumerals(site, count);
        const temp = try self.temporaryToken(site);
        try self.expandTemplate(rw, site, .tuple_bind, &.{ .temp = temp, .first = .{ assign + 1, stop } }, depth);
        for (0..count) |index| {
            const name = self.tokens[at + 1 + 2 * index];
            std.debug.assert(name.kind == .identifier);
            try self.expandTemplate(rw, site, .unpack_tuple, &.{ .temp = temp, .name = name, .number = @intCast(index) }, depth);
        }
        return stop;
    }

    fn resetCompiler(self: *Workspace, source: []const u8) void {
        self.source = source;
        self.renamed_fn_count = 0;
        // A compile that failed may have left nested functions in scope.
        while (self.nested_count != 0) self.dropNested();
        self.nested_capture_count = 0;
        self.late_overload_count = 0;
        self.late_block_count = 0;
        // What an earlier source declared says nothing about this one.
        self.std_memo_scope = std.math.maxInt(u32);
        self.forward_scope = std.math.maxInt(u32);
        self.failing_arm_count = 0;
        self.failing_case_count = 0;
        self.failing_test_stamp = 0;
        self.current_module = 0;
        self.current_nested = types.no_parent;
        self.root_binding_start = 0;
        self.token_count = 0;
        self.node_count = 0;
        self.binding_count = 0;
        self.local_count = 0;
        self.pattern_count = 0;
        self.for_call_count = 0;
        self.suspend_clause_count = 0;
        self.option_open_count = 0;
        self.option_pending = 0;
        self.failable_uses = 0;
        self.anonymous_count = 0;
        self.generic_count = 0;
        self.native_binding_count = 0;
        self.type_alias_count = 0;
        self.using_count = 0;
        self.local_checkpoint_count = 0;
        self.string_count = 0;
        self.expansion_work = 0;
        self.string_comparisons = 0;
        self.control_ops = 0;
        self.source_cell_count = 0;
        self.live_type_count = 0;
        self.source_ops = 0;
        self.slot_count = 0;
        self.method_count = 0;
        self.bridge_count = 0;
        self.narrowed_count = 0;
        self.dispatch_count = 0;
        self.class_updates = 0;
        self.instance_count = 0;
        self.instance_table.clear();
        self.instantiation_depth = 0;
        self.reserving_depth = 0;
        self.open_count = 0;
        self.declaring = 0;
        self.settled = 0;
        self.staged_fields = 0;
        self.staged_inherited = 0;
        self.dispatch_unsorted = false;
        self.late_count = 0;
        self.block_call_count = 0;
        self.blocks_pending = null;
        self.library_lexed = false;
        self.character_use_high = 0;
        self.functions.reset();
        self.runtime_functions.reset();
        self.call_argument_count = 0;
        self.call_ops = 0;
        self.catalogue.reset();
        self.member_count = 0;
        self.staging_count = 0;
        @memset(&self.symbols, 0);
        self.slot_table.clear();
        self.owner_table.clear();
        self.slots_indexed = 0;
        self.method_name_table.clear();
        self.class_method_table.clear();
        self.methods_indexed = 0;
        self.generic_table.clear();
        self.generics_indexed = 0;
        self.specialization_table.clear();
        self.specializations_indexed = 0;
        self.method_templates = 0;
        self.method_table.clear();
        self.metatype_count = 0;
        self.metatype_table.clear();
        self.alias_count = 0;
        self.alias_table.clear();
        self.witness_count = 0;
        self.witness_table.clear();
        self.accessor_count = 0;
        self.accessor_required = 0;
        self.accessor_archetypes = 0;
        self.accessor_table.clear();
        self.accessor_owners.clear();
        self.accessor_methods.clear();
        self.accessor_type = null;
        self.accessor_name = .{ .start = 0, .end = 0 };
        self.resolution_count = 0;
        self.resolution_conflicts = 0;
        self.resolution_conflict = qualify.none;
        self.text_declared = 0;
        self.persisted.constant_count = 0;
        self.persisted.constant_member_count = 0;
    }

    fn compilePrepared(self: *Workspace, source: []const u8, comptime bundled: bool) Result {
        self.resetCompiler(source);
        defer self.assertCounts();
        if (bundled) {
            self.catalogue.nested = self.nestedModules();
            self.functions.nested = self.nestedModules();
        }
        // A bundle's files were lexed alone to find its modules; here they are lexed joined, and a
        // comment must end with its file as it did there.
        const files = if (bundled) self.module_storage.modules[0..self.module_storage.module_count] else &.{};
        // RFC-0093: in a folder tree, a comment ends with its file, not with its module.
        const lexed = if (bundled and self.module_storage.part_count != 0) lexer.tokenizeParts(source, &self.tokens, self.module_storage.parts[0..self.module_storage.part_count]) else lexer.tokenizeFiles(source, &self.tokens, files);
        const tokens = switch (lexed) {
            .failed => |diagnostic| return .{ .failed = self.clampToUserText(diagnostic) },
            .ok => |tokens| tokens,
        };
        self.token_count = @intCast(tokens.len);
        std.debug.assert(self.token_count > 0);
        std.debug.assert(tokens[tokens.len - 1].kind == .eof);
        self.checkUnderscore() catch return .{ .failed = self.diagnostic };
        self.desugarQualifiers() catch return .{ .failed = self.diagnostic };
        self.desugarLive() catch return .{ .failed = self.diagnostic };
        self.checkReturns() catch return .{ .failed = self.diagnostic };
        self.desugarCompoundSets() catch return .{ .failed = self.diagnostic };
        self.desugarPathSets() catch return .{ .failed = self.diagnostic };
        self.desugarCases() catch return .{ .failed = self.diagnostic };
        self.desugarMacros() catch return .{ .failed = self.diagnostic };
        self.desugarFailableConditions() catch return .{ .failed = self.diagnostic };
        self.desugarLiveTypes() catch return .{ .failed = self.diagnostic };
        var parser: Parser(bundled) = .{ .workspace = self };
        self.parse_cursor = &parser.cursor;
        defer self.parse_cursor = null;
        parser.parseProgram() catch return .{ .failed = self.diagnostic };
        // RFC-0091: every call of a function declared further down names it now.
        if (self.runtime_functions.finish(self.runtime_functions.nodes[0..self.runtime_functions.node_count]) orelse self.runtime_functions.finishRoot(self.nodes[0..self.node_count])) |call| {
            _ = self.fail(call, .unknown_name) catch {};
            return .{ .failed = self.diagnostic };
        }
        // RFC-0087, P5.2: every type is complete, so the rules of `<persistable>` can be read.
        self.checkPersistable() catch return .{ .failed = self.diagnostic };
        // A single file is public too: its `<public>` bindings are what a host reports, so its
        // fields are marked as a bundle's are, though it has no importer to refuse a type to.
        if (bundled) self.checkPublicApi() catch return .{ .failed = self.diagnostic } else self.markHidden();
        if (self.dispatch_unsorted) std.sort.pdq(types.Dispatch, self.dispatch[0..self.dispatch_count], {}, dispatchBefore);
        std.debug.assert(parser.cursor + 1 == self.token_count);
        std.debug.assert(parser.function == null and parser.operator_count == 0 and self.local_count == 0 and self.local_checkpoint_count == 0);
        return .{ .ok = .{
            .source = source,
            .nodes = self.nodes[0..self.node_count],
            .bindings = self.bindings[self.root_binding_start..self.binding_count],
            .strings = self.strings[0..self.string_count],
            .definitions = self.catalogue.definitions[0..self.catalogue.count],
            .fields = self.catalogue.fields[0..self.catalogue.field_count],
            .cases = self.catalogue.cases[0..self.catalogue.case_count],
            .tuple_elements = self.catalogue.tuple_elements[0..self.catalogue.tuple_count],
            .members = self.members[0..self.member_count],
            .paths = self.module_storage.paths[0..self.module_storage.path_count],
            .modules = self.module_storage.modules[0..self.module_storage.module_count],
            .imports = self.module_storage.imports[0..self.module_storage.import_count],
            .nested = if (bundled) self.nestedModules() else &.{},
            .parts = if (bundled) self.module_storage.parts[0..self.module_storage.part_count] else &.{},
            .file_paths = if (bundled) self.module_storage.file_paths[0..self.module_storage.file_path_count] else "",
            .string_comparisons = self.string_comparisons,
            .control_ops = self.control_ops,
            .source_ops = self.source_ops,
            .source_cells = self.source_cells[0..self.source_cell_count],
            .call_ops = self.call_ops,
            .call_arguments = self.call_arguments[0..self.call_argument_count],
            .functions = self.runtime_functions.definitions[0..self.runtime_functions.count],
            .function_nodes = self.runtime_functions.nodes[0..self.runtime_functions.node_count],
            .function_members = self.runtime_functions.members[0..self.runtime_functions.member_count],
            .function_arguments = self.runtime_functions.arguments[0..self.runtime_functions.argument_count],
            .globals = self.runtime_functions.globals[0..self.runtime_functions.global_count],
            .natives = self.natives,
            .string_tail = self.strings[self.string_count..],
            .slots = self.slots[0..self.slot_count],
            .dispatch = self.dispatch[0..self.dispatch_count],
            .constants = self.persisted.constants[0..self.persisted.constant_count],
            .constant_members = self.persisted.constant_members[0..self.persisted.constant_member_count],
        } };
    }

    /// RFC-0087, P5.2: the rules of `<persistable>` types (T3 to T5), checked once the program
    /// is parsed, so that a field may name a persistable class declared after it: a class is
    /// final, not unique, and inherits nothing; no field of a struct or class is `var`, live or
    /// of a type that is not persistable; and each field default is a literal constant, which
    /// becomes the field's `constant`. Definitions are visited in catalogue order and fields
    /// in declaration order, so the first rule broken is reported.
    fn checkPersistable(self: *Workspace) ParseError!void {
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        var flagged = false;
        for (definitions) |item| switch (item) {
            .record => |record| flagged = flagged or record.persistable,
            .class => |class| flagged = flagged or class.persistable,
            .enumeration => |enumeration| flagged = flagged or enumeration.persistable,
            else => {},
        };
        if (!flagged) return;
        const kinds = self.persisted.kinds[0..definitions.len];
        persistable.persistableTypes(definitions, self.catalogue.tuple_elements[0..self.catalogue.tuple_count], kinds);
        for (definitions) |item| switch (item) {
            .record => |record| if (record.persistable) try self.persistableFields(record.fields, kinds),
            .class => |class| if (class.persistable) {
                if (!class.is_final) return self.fail(class.name, .persistable_final);
                if (class.is_unique) return self.fail(class.name, .persistable_unique);
                if (class.parent != null or class.interface_count != 0) return self.fail(class.name, .persistable_inherits);
                try self.persistableFields(class.fields, kinds);
            },
            else => {},
        };
        // A field with accessors (RFC-0085, I8) is a `var` field without a cell: one pass over
        // them, whatever the number of classes.
        for (self.accessor_fields[0..self.accessor_count]) |accessor| {
            const owner = catalogue.definition(accessor.owner, definitions) orelse continue;
            if (owner == .class and owner.class.persistable) return self.fail(accessor.name, .persistable_field);
        }
        try self.distinctConstantKeys();
    }

    /// RFC-0087, P5.3: what `ToJson` and `FromJson` ask of a type: whether it is persistable
    /// (T2), and whether a value of it can hold an instance, which makes an encode read and a
    /// decode allocate (E1, E4). A struct, a class and an enum are persistable by their flag, as
    /// `persistable.persistableTypes` has them, so that a flagged type whose fields break a rule is
    /// reported by `checkPersistable` at the field; a struct's fields are walked for the classes
    /// they reach. Each definition is visited once per walk, so the cost is the size of the type.
    fn jsonShape(self: *Workspace, value_type: types.Type) struct { persistable: bool, reaches_class: bool } {
        return .{ .persistable = self.jsonWalk(value_type, false), .reaches_class = self.jsonWalk(value_type, true) };
    }
    /// One walk of `jsonShape`: whether every part is persistable, or, through the fields of
    /// structs too (`reaching`), whether some part is a class. A definition is marked when it is
    /// first met, so it waits in `json_pending` at most once.
    fn jsonWalk(self: *Workspace, value_type: types.Type, reaching: bool) bool {
        const storage = &self.persisted;
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        if (storage.json_stamp == std.math.maxInt(u32)) storage.json_stamp = 0;
        if (storage.json_stamp == 0) @memset(storage.json_marks[0..], 0);
        storage.json_stamp += 1;
        var count: usize = 0;
        if (value_type == types.Type.any or value_type == types.Type.bottom) return false;
        if (!self.jsonMeet(value_type, &count)) return !reaching;
        while (count != 0) {
            count -= 1;
            const at = storage.json_pending[count];
            const item = catalogue.definition(at, definitions) orelse {
                if (!reaching) return false;
                continue;
            };
            var parts: [2]types.Type = undefined;
            var named: []const types.Type = &.{};
            switch (item) {
                .record => |record| if (reaching) {
                    for (self.catalogue.fields[record.fields.start..record.fields.end]) |field| _ = self.jsonMeet(field.value_type, &count);
                } else if (!record.persistable or record.arguments != null or record.metatype) return false,
                .class => |class| if (reaching) return true else if (!class.persistable or class.arguments != null or class.is_interface) return false,
                .enumeration => |enumeration| if (!reaching and !enumeration.persistable) return false,
                .array => |element| {
                    parts[0] = element;
                    named = parts[0..1];
                },
                .option => |element| {
                    parts[0] = element;
                    named = parts[0..1];
                },
                .map => |shape| {
                    parts = .{ shape.key, shape.value };
                    named = parts[0..2];
                },
                .tuple => |span| named = self.catalogue.tuple_elements[span.start..span.end],
                else => if (!reaching) return false,
            }
            for (named) |part| {
                if ((part == types.Type.any or part == types.Type.bottom) and !reaching) return false;
                _ = self.jsonMeet(part, &count);
            }
        }
        return !reaching;
    }
    /// Queues a part for `jsonWalk` unless it is a scalar, a character type, `any` (which the
    /// walk answers itself) or met before. Each definition is queued once, so the queue, as
    /// long as the catalogue may be, never fills.
    fn jsonMeet(self: *Workspace, part: types.Type, count: *usize) bool {
        const storage = &self.persisted;
        if (part.isCharacter() or @backingInt(part) < 4 or part == types.Type.any) return false;
        const index = @backingInt(part) - 4;
        if (index >= storage.json_marks.len or storage.json_marks[index] == storage.json_stamp) return false;
        storage.json_marks[index] = storage.json_stamp;
        std.debug.assert(count.* < storage.json_pending.len);
        storage.json_pending[count.*] = part;
        count.* += 1;
        return true;
    }

    /// The name of the field whose default made constant `index`: `checkPersistable` makes
    /// them in this order, each field's run ending at its own constant.
    fn constantOwner(self: *const Workspace, index: u32) Span {
        for (self.catalogue.definitions[0..self.catalogue.count]) |item| {
            const span: Span = switch (item) {
                .record => |record| if (record.persistable) record.fields else continue,
                .class => |class| if (class.persistable) class.fields else continue,
                else => continue,
            };
            for (self.catalogue.fields[span.start..span.end]) |field| if (field.constant) |own| if (own >= index) return field.name;
        }
        unreachable;
    }

    fn persistableFields(self: *Workspace, span: Span, kinds: []const bool) ParseError!void {
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        for (span.start..span.end) |index| {
            const field = self.catalogue.fields[index];
            if (field.is_var or field.live_only or !persistable.isPersistable(field.value_type, definitions, kinds)) return self.fail(field.name, .persistable_field);
            const default = self.field_defaults[index];
            if (default.start == default.end) continue;
            self.catalogue.fields[index].constant = try self.defaultConstant(default);
        }
    }

    /// The constant a field default's template stands for (T5): a body made only of literals,
    /// whose root is its value. A negated number is one literal. Any other node (a call, a
    /// name of a binding, an interpolation, an archetype of a class, arithmetic) is
    /// `persistable_default` at that node. The constants of the body's literals that its
    /// aggregates hold or that it yields are appended, members first.
    fn defaultConstant(self: *Workspace, default: functions.Body) ParseError!u32 {
        const storage = &self.functions;
        std.debug.assert(default.start <= default.root and default.root < default.end);
        const body = storage.nodes[default.start..default.end];
        // `mapping` is free once every body is expanded: it marks what the constants need.
        const marks = storage.mapping[default.start..default.end];
        const unused = std.math.maxInt(u32);
        const needed = unused - 1;
        @memset(marks, unused);
        for (body) |template| {
            if (template.input != .operation) return self.fail(template.node.span, .persistable_default);
            switch (template.node.kind) {
                .integer, .floating, .boolean, .string, .character, .enumeration => {},
                .negate => |operand| if (operand < default.start or operand >= default.end or storage.nodes[operand].node.kind != .integer) return self.fail(template.node.span, .persistable_default),
                .float_negate => |operand| if (operand < default.start or operand >= default.end or storage.nodes[operand].node.kind != .floating) return self.fail(template.node.span, .persistable_default),
                .aggregate => |members| for (storage.members[members.start..members.end]) |member| {
                    if (member < default.start or member >= default.end) return self.fail(template.node.span, .persistable_default);
                    marks[member - default.start] = needed;
                },
                else => return self.fail(template.node.span, .persistable_default),
            }
        }
        marks[default.root - default.start] = needed;
        for (body, 0..) |template, offset| {
            if (marks[offset] == unused) continue;
            const node = template.node;
            if (self.persisted.constant_count == self.persisted.constants.len) return self.fail(node.span, .aggregate_limit);
            const kind: @FieldType(types.Constant, "kind") = switch (node.kind) {
                .integer => |value| .{ .integer = value },
                .floating => |value| .{ .floating = types.canonicalFloat(value) },
                .boolean => |value| .{ .boolean = value },
                .string => |value| .{ .string = value },
                .character => |code| .{ .character = code },
                .enumeration => |case| .{ .enumeration = case },
                .negate => |operand| .{ .integer = std.math.negate(storage.nodes[operand].node.kind.integer) catch return self.fail(node.span, .persistable_default) },
                .float_negate => |operand| .{ .floating = types.canonicalFloat(-storage.nodes[operand].node.kind.floating) },
                .aggregate => |members| aggregate: {
                    const count = members.end - members.start;
                    if (count > self.persisted.constant_members.len - self.persisted.constant_member_count) return self.fail(node.span, .aggregate_limit);
                    const start = self.persisted.constant_member_count;
                    for (storage.members[members.start..members.end], self.persisted.constant_members[start..][0..count]) |member, *slot| {
                        // A member is an earlier node of the body, whose constant is made.
                        const made = marks[member - default.start];
                        if (member >= default.start + offset or made == unused or made == needed) return self.fail(node.span, .persistable_default);
                        slot.* = made;
                    }
                    self.persisted.constant_member_count += count;
                    break :aggregate .{ .aggregate = .{ .start = start, .end = start + count } };
                },
                else => unreachable,
            };
            self.persisted.constants[self.persisted.constant_count] = .{ .value_type = node.value_type, .kind = kind };
            marks[offset] = self.persisted.constant_count;
            self.persisted.constant_count += 1;
        }
        return marks[default.root - default.start];
    }

    /// A map default with two keys the language calls equal has no value (a map literal with
    /// them is fatal where it is built): `persistable_default` at the field. Constants are made
    /// field by field, so each field's are the run of them that ends at its own.
    fn distinctConstantKeys(self: *Workspace) ParseError!void {
        const constants = self.persisted.constants[0..self.persisted.constant_count];
        const members = self.persisted.constant_members[0..self.persisted.constant_member_count];
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        var maps = false;
        for (constants) |constant| maps = maps or (constant.kind == .aggregate and catalogue.definition(constant.value_type, definitions).? == .map);
        if (!maps) return;
        const origin: Span = .{ .start = 0, .end = 0 };
        const classes = scratch.alloc(u32, constants.len) orelse return self.fail(origin, .scratch_unavailable);
        defer scratch.free(classes);
        const table = scratch.alloc(u32, persistable.workSize(constants.len)) orelse return self.fail(origin, .scratch_unavailable);
        defer scratch.free(table);
        persistable.equalityClasses(constants, members, self.strings[0..self.string_count], classes, table);
        const claimed = scratch.alloc(u32, constants.len) orelse return self.fail(origin, .scratch_unavailable);
        defer scratch.free(claimed);
        @memset(claimed, std.math.maxInt(u32));
        for (constants, 0..) |constant, index| {
            if (constant.kind != .aggregate or catalogue.definition(constant.value_type, definitions).? != .map) continue;
            const span = constant.kind.aggregate;
            var at = span.start;
            while (at < span.end) : (at += 2) {
                const class = classes[members[at]];
                if (claimed[class] == index) return self.fail(self.constantOwner(@intCast(index)), .persistable_default);
                claimed[class] = @intCast(index);
            }
        }
    }

    /// The late declaration `name` of the scope `scope_id` (a file, or a module nested in one).
    fn lateIn(self: *const Workspace, name: []const u8, scope_id: u32) ?u32 {
        for (self.late[0..self.late_count], 0..) |entry, index| {
            if (entry.scope == scope_id and entry.name.end - entry.name.start == name.len and std.mem.eql(u8, entry.name.text(self.source), name)) return @intCast(index);
        }
        return null;
    }

    /// The scope a declaration of file `module` has when the innermost module of that file
    /// around it is `inner`.
    fn scopeId(self: *const Workspace, module: u32, inner: u32) u32 {
        return if (inner == types.no_parent) module else self.module_storage.module_count + inner;
    }

    /// The late declaration that the identifier at token `at` may name, as the scope
    /// (`module`, `inner`) sees it: its own, or a public one of a module it imports, which
    /// `Alias.Name` selects and a `using` read before `at` makes visible (`late_using`). That
    /// is exact for a single file and for a bundle whose files declare no modules. Where files
    /// declare modules (RFC-0074), with their paths, their `using` of paths and the scopes
    /// around each, a late declaration of that name anywhere counts: resolving a path needs
    /// the modules' reach, which is worked out after this pass. Erring on that side only
    /// declares a class late, which is always sound: what a class declared late for a name it
    /// does not mean changes is only where it enters the catalogue. Names resolve as they
    /// would (a late class is found by `lateClassIn` for shadowing and by `reserveLate` where
    /// it is named), and values, reports and diagnostics are those of the same program with
    /// the other declaration spelt differently (test "a class made late by a template of the
    /// same spelling it cannot name means what it meant").
    fn lateSeen(self: *const Workspace, at: usize, module: u32, inner: u32) ?u32 {
        const text = self.tokens[at].span.text(self.source);
        if (self.module_storage.nested_count != 0) {
            for (self.late[0..self.late_count], 0..) |entry, index| {
                if (entry.name.end - entry.name.start == text.len and std.mem.eql(u8, entry.name.text(self.source), text)) return @intCast(index);
            }
            return null;
        }
        std.debug.assert(inner == types.no_parent);
        const range: types.Span = if (self.module_storage.module_count == 0) .{ .start = 0, .end = 0 } else self.module_storage.modules[module].imports;
        const imports = self.module_storage.imports[range.start..range.end];
        if (at >= 2 and self.tokens[at - 1].kind == .dot and self.tokens[at - 2].kind == .identifier) {
            const alias = self.tokens[at - 2].span.text(self.source);
            for (imports) |edge| if (std.mem.eql(u8, alias, edge.alias.text(self.source))) return self.lateExported(text, edge.target);
            return null;
        }
        if (self.lateIn(text, module)) |found| return found;
        for (imports, self.late_using[range.start..range.end]) |edge, used| if (used) if (self.lateExported(text, edge.target)) |found| return found;
        return null;
    }

    /// A late declaration of file `module` that another file can name: a public one.
    fn lateExported(self: *const Workspace, name: []const u8, module: u32) ?u32 {
        const found = self.lateIn(name, module) orelse return null;
        return if (self.late[found].is_public) found else null;
    }

    fn noteLate(self: *Workspace, at: usize, module: u32, inner: u32, kind: @FieldType(Late, "kind"), is_public: bool) ParseError!void {
        const name = self.tokens[at].span;
        const scope_id = self.scopeId(module, inner);
        if (self.lateIn(name.text(self.source), scope_id) != null) return;
        if (self.late_count == self.late.len) return self.fail(name, .type_limit);
        self.late[self.late_count] = .{ .name = name, .module = module, .nested = inner, .scope = scope_id, .token = @intCast(at), .is_public = is_public, .kind = kind };
        self.late_count += 1;
    }

    /// The scope whose text is `text`: a file, or a module declared in one.
    fn scopeNamed(self: *const Workspace, text: Span) u32 {
        const count = self.module_storage.module_count;
        for (self.module_storage.modules[0..count], 0..) |module, index| if (std.meta.eql(module.source, text)) return @intCast(index);
        const nested = self.nestedModules();
        if (nested.len != 0) if (modules.innermost(text, nested)) |inner| {
            if (std.meta.eql(nested[inner].source, text)) return count + inner;
        };
        return self.currentScope();
    }

    /// The instantiation whose type is `value`, if it is one.
    fn instanceOf(self: *const Workspace, value: types.Type) ?u32 {
        const id = @backingInt(value);
        if (id < catalogue.builtin_count or id - catalogue.builtin_count >= self.instance_by_type.len) return null;
        const entry = self.instance_by_type[id - catalogue.builtin_count];
        if (entry == 0 or entry > self.instance_count or self.instances[entry - 1].value != value) return null;
        return entry - 1;
    }

    fn classOpen(self: *const Workspace, class: types.Type) bool {
        for (self.open_classes[0..self.open_count]) |open| if (open == class) return true;
        return false;
    }

    /// Whether the reserved instantiation `index` can be completed now: each of its supertypes
    /// is complete or can be completed first. One whose declaration is still open cannot, and
    /// then this one waits, as a class waits for a superclass declared before it.
    fn completable(self: *const Workspace, index: u32, depth: u32) bool {
        if (depth == types.limits.instantiation_depth) return false;
        const instance = self.instances[index];
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        for (instance.parents[0..instance.parent_count]) |parent| {
            if (self.classOpen(parent)) return false;
            const item = catalogue.definition(parent, definitions) orelse continue;
            if (item != .class or !catalogue.pendingClass(item.class)) continue;
            const above = self.instanceOf(parent) orelse return false;
            if (self.instances[above].state != .reserved or !self.completable(above, depth + 1)) return false;
        }
        return true;
    }

    fn dispatchBefore(_: void, a: types.Dispatch, b: types.Dispatch) bool {
        return if (a.class != b.class) @backingInt(a.class) < @backingInt(b.class) else a.slot < b.slot;
    }

    fn instanceHash(template: u32, arguments: []const types.Type) u64 {
        return std.hash.Wyhash.hash(template, std.mem.sliceAsBytes(arguments));
    }

    fn instanceIs(self: *const Workspace, index: u32, template: u32, arguments: []const types.Type) bool {
        const instance = self.instances[index];
        if (instance.template != template) return false;
        const shape = catalogue.definition(instance.arguments, self.catalogue.definitions[0..self.catalogue.count]).?.tuple;
        return std.mem.eql(types.Type, arguments, self.catalogue.tuple_elements[shape.start..shape.end]);
    }

    /// The instantiation of `template` for `arguments`, if it has been made. Costs one walk of
    /// the instances that share the hash, whatever the number of instantiations; Debug builds
    /// check the answer against reading every instance, as for every indexed lookup.
    fn findInstance(self: *const Workspace, template: u32, arguments: []const types.Type) ?u32 {
        var same = self.instance_table.walk(&self.instance_slots, instanceHash(template, arguments));
        const found: ?u32 = while (same.next()) |index| {
            if (index < self.instance_count and self.instanceIs(index, template, arguments)) break index;
        } else null;
        if (paired_scans) {
            const scanned: ?u32 = for (0..self.instance_count) |index| {
                if (self.instanceIs(@intCast(index), template, arguments)) break @intCast(index);
            } else null;
            std.debug.assert(found == scanned);
        }
        return found;
    }

    /// Records that `value` is `template` instantiated for the tuple type `arguments`.
    fn addInstance(self: *Workspace, template: u32, arguments: types.Type, value: types.Type, generation: u16, parents: []const types.Type) u32 {
        const shape = catalogue.definition(arguments, self.catalogue.definitions[0..self.catalogue.count]).?.tuple;
        const list = self.catalogue.tuple_elements[shape.start..shape.end];
        std.debug.assert(self.findInstance(template, list) == null and self.instance_count < self.instances.len);
        const index = self.instance_count;
        self.instances[index] = .{ .template = template, .arguments = arguments, .value = value, .generation = generation, .parent_count = @intCast(parents.len) };
        @memcpy(self.instances[index].parents[0..parents.len], parents);
        if (self.instance_table.crowded()) {
            self.instance_table.grow(&self.instance_slots);
            for (self.instances[0..index], 0..) |earlier, at| {
                const earlier_shape = catalogue.definition(earlier.arguments, self.catalogue.definitions[0..self.catalogue.count]).?.tuple;
                self.instance_table.enter(&self.instance_slots, instanceHash(earlier.template, self.catalogue.tuple_elements[earlier_shape.start..earlier_shape.end]), @intCast(at));
            }
        }
        self.instance_table.enter(&self.instance_slots, instanceHash(template, list), index);
        self.instance_count += 1;
        self.instance_by_type[@backingInt(value) - catalogue.builtin_count] = @intCast(self.instance_count);
        return index;
    }

    fn scope(self: *const Workspace) Span {
        return self.scopeOf(self.currentScope());
    }
    /// The text of a scope: a file module by its number, or a module nested in a file by its
    /// index after the files (`modules.home`).
    fn scopeOf(self: *const Workspace, namespace: u32) Span {
        const count = self.module_storage.module_count;
        if (count == 0) return .{ .start = 0, .end = @intCast(self.source.len) };
        return if (namespace < count) self.module_storage.modules[namespace].source else self.module_storage.nested[namespace - count].source;
    }
    fn currentScope(self: *const Workspace) u32 {
        return if (self.current_nested == types.no_parent) self.current_module else self.module_storage.module_count + self.current_nested;
    }
    fn nestedModules(self: *const Workspace) []const types.NestedModule {
        return self.module_storage.nested[0..self.module_storage.nested_count];
    }
    /// The scope that declares the name written at `span`.
    fn homeOf(self: *const Workspace, span: Span) u32 {
        const count = self.module_storage.module_count;
        if (count == 0) return 0;
        return modules.home(span, self.module_storage.modules[0..count], self.nestedModules()).?;
    }
    fn outerScope(self: *const Workspace, id: u32) ?u32 {
        const count = self.module_storage.module_count;
        if (count == 0) return null;
        return modules.enclosing(id, self.module_storage.modules[0..count], self.nestedModules());
    }
    /// Whether scope `inner` is `outer` or a module nested in it.
    fn insideScope(self: *const Workspace, inner: u32, outer: u32) bool {
        if (inner == outer) return true;
        const count = self.module_storage.module_count;
        if (count == 0 or self.module_storage.nested_count == 0) return false;
        return modules.inside(inner, outer, self.module_storage.modules[0..count], self.nestedModules());
    }
    /// Whether the code being compiled is in the module that declares `name` or in one nested
    /// in it, where a declaration is in reach without being `<public>`.
    fn reaches(self: *const Workspace, name: Span) bool {
        if (self.module_storage.nested_count == 0) return modules.contains(self.scope(), name);
        return self.insideScope(self.currentScope(), self.homeOf(name));
    }
    /// The name of the class named `text` that the scope with text `scope` declares late (RFC-0073).
    fn lateClassIn(self: *const Workspace, text: []const u8, scope_text: Span) ?Span {
        if (self.late_count == 0) return null;
        const entry = self.lateIn(text, self.scopeNamed(scope_text)) orelse return null;
        return if (self.late[entry].kind == .class) self.late[entry].name else null;
    }
    /// Whether the specifiers that start at token `at`, the one after `class`, include `<unique>`.
    fn uniqueAhead(self: *const Workspace, at: usize) bool {
        var ahead = at;
        while (ahead + 2 < self.token_count and self.tokens[ahead].kind == .less and self.tokens[ahead + 1].kind == .identifier and self.tokens[ahead + 2].kind == .greater) : (ahead += 3) {
            if (std.mem.eql(u8, self.tokens[ahead + 1].span.text(self.source), "unique")) return true;
        }
        return false;
    }
    /// The diagnostic for a type that has no equality: `not_unique` when a class that does not
    /// say `<unique>` is what stands in the way (RFC-0076, D15), `otherwise` if not.
    fn equalityCode(self: *const Workspace, value_type: types.Type, otherwise: Diagnostic.Code) Diagnostic.Code {
        // RFC-0087: a `weak_map` has no equality by its nature (03:1112), whatever it holds.
        if (catalogue.isWeakMap(value_type, self.catalogue.definitions[0..self.catalogue.count])) return .weak_map_operation;
        return if (self.holdsPlainClass(value_type, 0)) .not_unique else otherwise;
    }
    fn holdsPlainClass(self: *const Workspace, value_type: types.Type, depth: u32) bool {
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        const item = catalogue.definition(value_type, definitions) orelse return false;
        if (depth == 16) return false;
        return switch (item) {
            .class => |class| !class.is_unique,
            .array, .option => |element| self.holdsPlainClass(element, depth + 1),
            .map => |shape| self.holdsPlainClass(shape.key, depth + 1) or self.holdsPlainClass(shape.value, depth + 1),
            .tuple => |span| for (self.catalogue.tuple_elements[span.start..span.end]) |element| {
                if (self.holdsPlainClass(element, depth + 1)) break true;
            } else false,
            .record => |record| for (self.catalogue.fields[record.fields.start..record.fields.end]) |field| {
                if (self.holdsPlainClass(field.value_type, depth + 1)) break true;
            } else false,
            .enumeration, .callable, .rational, .task, .refinement, .event, .live, .scheduled_interface, .cancelable, .ref, .grant, .weak_map => false,
        };
    }
    /// The module named `text` that scope `id` declares before source position `before`: a
    /// module, like everything else, is named after its declaration. The modules of a scope
    /// follow it in the table, so this reads the scope's own modules and those inside them.
    fn childModule(self: *const Workspace, id: u32, text: []const u8, before: u32) ?u32 {
        const nested = self.nestedModules();
        if (nested.len == 0) return null;
        const count = self.module_storage.module_count;
        const range = self.scopeOf(id);
        var low: usize = 0;
        var high: usize = nested.len;
        while (low < high) {
            const middle = low + (high - low) / 2;
            if (nested[middle].source.start <= range.start) low = middle + 1 else high = middle;
        }
        while (low < nested.len and nested[low].source.start < range.end) : (low += 1) {
            const module = nested[low];
            if (module.name.start >= before) return null;
            if (module.parent != (if (id < count) types.no_parent else id - count)) continue;
            if (std.mem.eql(u8, module.name.text(self.source), text)) return @intCast(low);
        }
        return null;
    }
    /// Whether the declaration that holds source offset `position` binds `name` before it as a
    /// parameter, a typed local, a loop variable or a pattern binder: each is written `name:`.
    /// Such a name comes before any module of that name, as locals come before everything.
    fn localNamed(self: *const Workspace, name: []const u8, position: u32) bool {
        // The statement of a module body that holds the position starts after the last line
        // end or separator outside every bracket, or after the brace of the module around it.
        var at: usize = 0;
        while (at < self.token_count and self.tokens[at].span.start < position) at += 1;
        const end = at;
        var level: usize = 0;
        var start: usize = 0;
        var boundary: ?usize = null;
        while (at != 0) {
            at -= 1;
            const token = self.tokens[at];
            if (self.moduleBrace(token)) {
                // A module that closed before the position is skipped whole; the one that is
                // still open is the module body the statement stands in.
                if (token.kind == .right_brace) {
                    level += 1;
                } else if (level == 0) {
                    start = at + 1;
                    break;
                } else level -= 1;
                continue;
            }
            switch (token.kind) {
                .right_paren, .right_bracket, .right_brace => level += 1,
                .left_paren, .left_bracket, .left_brace => {
                    // An opener with nothing to close: the position is inside it, and no line
                    // end seen so far was outside every bracket.
                    if (level == 0) boundary = null else level -= 1;
                },
                .newline, .separator => if (level == 0 and boundary == null) {
                    boundary = at + 1;
                },
                else => {},
            }
        }
        if (boundary) |found| start = @max(start, found);
        for (start..end) |index| {
            if (index + 1 >= end or self.tokens[index].kind != .identifier or self.tokens[index + 1].kind != .colon) continue;
            if (index != 0 and self.tokens[index - 1].kind == .dot) continue;
            if (std.mem.eql(u8, self.tokens[index].span.text(self.source), name)) return true;
        }
        return false;
    }

    /// Whether `token` is the brace that opens or closes the body of a nested module.
    fn moduleBrace(self: *const Workspace, token: Token) bool {
        const nested = self.nestedModules();
        if (nested.len == 0 or (token.kind != .left_brace and token.kind != .right_brace)) return false;
        // The body starts after the opening brace and ends at the closing one, so the innermost
        // module that holds that position is the one the brace belongs to, if any is.
        const edge = if (token.kind == .left_brace) token.span.end else token.span.start;
        const module = modules.innermost(.{ .start = edge, .end = edge }, nested) orelse return false;
        return (if (token.kind == .left_brace) nested[module].source.start else nested[module].source.end) == edge;
    }

    /// The nested module whose declaration starts with the name at `name`.
    fn moduleDeclaredAt(self: *const Workspace, name: Span) ?u32 {
        const nested = self.nestedModules();
        var low: usize = 0;
        var high: usize = nested.len;
        while (low < high) {
            const middle = low + (high - low) / 2;
            if (nested[middle].name.start < name.start) low = middle + 1 else high = middle;
        }
        return if (low < nested.len and nested[low].name.start == name.start) @intCast(low) else null;
    }
    /// The functions that have the name of `first` in its module, `first` among them, in the
    /// order they were declared. Methods of the name are not among them: a call reaches a
    /// method only through a receiver, never as an overload of a function.
    fn overloads(self: *const Workspace, first: u32) functions.Storage.Namesakes {
        const name = self.functions.definitions[first].name;
        return self.functions.functionNamesakes(name.text(self.source), self.source, self.scopeOf(self.homeOf(name)));
    }

    /// The most arguments any definition sharing `first`'s name accepts.
    fn callBound(self: *const Workspace, first: u32) u32 {
        const definition = self.functions.definitions[first];
        if (!definition.overloaded) return definition.parameter_count;
        var most: u32 = 0;
        var others = self.overloads(first);
        while (others.next()) |index| most = @max(most, self.functions.definitions[index].parameter_count);
        return most;
    }

    /// The type every overload expects at `position`, or null where they disagree.
    fn overloadContext(self: *const Workspace, first: u32, position: u32) ?types.Type {
        var found: ?types.Type = null;
        var others = self.overloads(first);
        while (others.next()) |index| {
            const candidate = &self.functions.definitions[index];
            if (position >= candidate.parameter_count) continue;
            const expected = candidate.parameters[position].value_type;
            if (found == null) found = expected else if (found.? != expected) return null;
        }
        return found;
    }

    fn hasArity(self: *const Workspace, first: u32, count: usize) bool {
        var others = self.overloads(first);
        while (others.next()) |index| if (self.functions.definitions[index].parameter_count == count) return true;
        return false;
    }

    /// The overload whose parameter types are exactly `argument_types`, or else the most specific
    /// one that accepts them as subclass instances.
    fn chooseOverload(self: *const Workspace, first: u32, argument_types: []const types.Type) ?u32 {
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        var exact = self.overloads(first);
        while (exact.next()) |index| {
            const candidate = &self.functions.definitions[index];
            if (candidate.parameter_count != argument_types.len) continue;
            const matches = for (candidate.parameters[0..candidate.parameter_count], argument_types) |parameter, argument| {
                if (parameter.value_type != argument) break false;
            } else true;
            if (matches) return index;
        }
        // The most specific definition is the one narrower than every other that takes the call.
        // Two that neither is narrower than the other decide nothing while a third that is narrower
        // than both may follow, so the scan keeps the narrowest seen and the candidate it ends on
        // is then checked against all the others.
        var best: ?u32 = null;
        var others = self.overloads(first);
        while (others.next()) |index| {
            if (!self.accepts(index, argument_types, definitions)) continue;
            const current = best orelse {
                best = index;
                continue;
            };
            if (self.narrowerThan(index, current, definitions)) best = index;
        }
        const chosen = best orelse return null;
        others = self.overloads(first);
        while (others.next()) |index| {
            if (index == chosen or !self.accepts(index, argument_types, definitions)) continue;
            // Two applicable definitions with no most specific one are ambiguous.
            if (!self.narrowerThan(chosen, index, definitions)) return null;
        }
        return chosen;
    }

    /// Whether definition `index` takes arguments of `argument_types`.
    fn accepts(self: *const Workspace, index: u32, argument_types: []const types.Type, definitions: []const types.Definition) bool {
        const candidate = &self.functions.definitions[index];
        if (candidate.parameter_count != argument_types.len) return false;
        return for (candidate.parameters[0..candidate.parameter_count], argument_types) |parameter, argument| {
            if (!catalogue.assignable(argument, parameter.value_type, definitions)) break false;
        } else true;
    }

    /// Whether every parameter of definition `narrow` is assignable to the one of `wide` and some
    /// parameter is not the same type: `narrow` takes fewer values. Both take the same number of
    /// arguments.
    fn narrowerThan(self: *const Workspace, narrow: u32, wide: u32, definitions: []const types.Definition) bool {
        const a = &self.functions.definitions[narrow];
        const b = &self.functions.definitions[wide];
        std.debug.assert(a.parameter_count == b.parameter_count);
        var different = false;
        for (a.parameters[0..a.parameter_count], b.parameters[0..b.parameter_count]) |own, other| {
            if (!catalogue.assignable(own.value_type, other.value_type, definitions)) return false;
            different = different or own.value_type != other.value_type;
        }
        return different;
    }

    /// The definition sharing `first`'s name whose function type is `expected`.
    fn overloadByType(self: *Workspace, parser: anytype, first: u32, expected: types.Type, span: Span) ParseError!?u32 {
        var others = self.overloads(first);
        while (others.next()) |index| {
            if ((try parser.functionType(self.functions.definitions[index], span)) == expected) return index;
        }
        return null;
    }

    fn findFunction(self: *const Workspace, name: []const u8) ?u32 {
        return self.functions.findIn(name, self.source, self.scope());
    }
    /// The function a bare `name` means in `scope`. An extension method is not one: it is
    /// named only after a receiver, and every definition of its name is an extension.
    fn plainFunctionIn(self: *const Workspace, name: []const u8, within: Span) ?u32 {
        const found = self.functions.findIn(name, self.source, within) orelse return null;
        return if (self.functions.definitions[found].is_extension) null else found;
    }
    fn findType(self: *const Workspace, name: []const u8) ?types.Type {
        return self.catalogue.findNamedIn(name, self.source, self.scope());
    }
    fn symbolNamed(self: *const Workspace, name: []const u8) bool {
        return self.findSymbolIn(name, self.scope()) != null;
    }
    /// Whether some class declares a method of this name (a binding or cell may not share it).
    fn methodNamed(self: *Workspace, name: []const u8) bool {
        // Every binding declared asks this; reading every method each time cost their product.
        const hash = name_index.hashName(0, name);
        while (self.methods_indexed < self.method_count) : (self.methods_indexed += 1) {
            const index = self.methods_indexed;
            const text = self.methods[index].name.text(self.source);
            if (self.methodNameEntered(text)) continue;
            if (self.method_name_table.crowded()) {
                self.method_name_table.grow(&self.method_name_slots);
                // One entry per name: a namesake of an earlier method finds that one entered.
                for (0..index) |earlier| {
                    const other = self.methods[earlier].name.text(self.source);
                    if (!self.methodNameEntered(other)) self.method_name_table.enter(&self.method_name_slots, name_index.hashName(0, other), @intCast(earlier));
                }
            }
            self.method_name_table.enter(&self.method_name_slots, name_index.hashName(0, text), index);
        }
        var same = self.method_name_table.walk(&self.method_name_slots, hash);
        const found = while (same.next()) |index| {
            if (std.mem.eql(u8, self.methods[index].name.text(self.source), name)) break true;
        } else false;
        if (paired_scans) {
            const scanned = for (self.methods[0..self.method_count]) |method| {
                if (std.mem.eql(u8, method.name.text(self.source), name)) break true;
            } else false;
            std.debug.assert(found == scanned);
        }
        return found;
    }
    fn methodNameEntered(self: *const Workspace, name: []const u8) bool {
        var same = self.method_name_table.walk(&self.method_name_slots, name_index.hashName(0, name));
        while (same.next()) |index| if (std.mem.eql(u8, self.methods[index].name.text(self.source), name)) return true;
        return false;
    }

    fn slotHash(self: *const Workspace, owner: types.Type, name: []const u8) u64 {
        _ = self;
        return name_index.hashName(@backingInt(owner), name);
    }

    /// Enters the slots added since the slot tables were last asked.
    fn indexSlots(self: *Workspace) void {
        while (self.slots_indexed < self.slot_count) : (self.slots_indexed += 1) {
            const index = self.slots_indexed;
            if (self.slot_table.crowded()) {
                self.slot_table.grow(&self.slot_table_slots);
                for (self.slots[0..index], 0..) |earlier, at| self.slot_table.enter(&self.slot_table_slots, self.slotHash(earlier.owner, earlier.name.text(self.source)), @intCast(at));
            }
            self.slot_table.enter(&self.slot_table_slots, self.slotHash(self.slots[index].owner, self.slots[index].name.text(self.source)), index);
            // Behind the newest slot of its owner, or the first of an owner that had none.
            const owner = self.slots[index].owner;
            self.slot_owner_next[index] = no_member;
            self.slot_owner_last[index] = no_member;
            if (self.ownerSlots(owner)) |first| {
                self.slot_owner_next[self.slot_owner_last[first]] = index;
                self.slot_owner_last[first] = index;
                continue;
            }
            if (self.owner_table.crowded()) {
                self.owner_table.grow(&self.owner_table_slots);
                for (self.slot_owner_last[0..index], 0..) |last, at| {
                    if (last != no_member) self.owner_table.enter(&self.owner_table_slots, ownerHash(self.slots[at].owner), @intCast(at));
                }
            }
            self.slot_owner_last[index] = index;
            self.owner_table.enter(&self.owner_table_slots, ownerHash(owner), index);
        }
    }

    fn ownerHash(owner: types.Type) u64 {
        return name_index.hashSpan(@backingInt(owner), 0);
    }

    /// The first slot `owner` introduced, among the slots indexed so far.
    fn ownerSlots(self: *const Workspace, owner: types.Type) ?u32 {
        var same = self.owner_table.walk(&self.owner_table_slots, ownerHash(owner));
        while (same.next()) |index| if (self.slots[index].owner == owner) return index;
        return null;
    }

    /// The slots whose owner is among `above` (a class and its supertypes), in ascending order:
    /// what a pass over every slot of the program finds, without the pass. Each class asks for
    /// them when it is finished, so the pass cost the number of classes times the number of
    /// slots. The slots of each supertype are listed (`slot_owner_next`), and a supertype is
    /// declared, and gets its slots, before its subtypes: going through the supertypes in
    /// order gives the slots in order. Should that ever not hold, the slots are read as before.
    const VisibleSlots = struct {
        workspace: *const Workspace,
        above: *const catalogue.Supertypes,
        owners: Owners,
        slot: u32 = no_member,
        /// Reading every slot, from `at` on.
        scanning: bool,
        at: usize = 0,

        const Owners = std.StaticBitSet(types.limits.user_types).Iterator(.{});

        fn next(self: *VisibleSlots) ?usize {
            const w = self.workspace;
            if (self.scanning) {
                while (self.at < w.slot_count) {
                    const slot = self.at;
                    self.at += 1;
                    if (self.above.has(w.slots[slot].owner)) return slot;
                }
                return null;
            }
            while (true) {
                if (self.slot != no_member) {
                    const slot = self.slot;
                    self.slot = w.slot_owner_next[slot];
                    return slot;
                }
                const owner = self.owners.next() orelse return null;
                self.slot = w.ownerSlots(@fromBackingInt(@as(u16, @intCast(catalogue.builtin_count + owner)))) orelse no_member;
            }
        }
    };

    fn visibleSlots(self: *Workspace, above: *const catalogue.Supertypes) VisibleSlots {
        self.indexSlots();
        // One look through the lists says whether they are in order.
        var ordered: VisibleSlots = .{ .workspace = self, .above = above, .owners = above.reached.iterator(.{}), .scanning = false };
        var previous: ?usize = null;
        const ascending = while (ordered.next()) |slot| {
            if (previous) |earlier| if (slot <= earlier) break false;
            previous = slot;
        } else true;
        if (paired_scans and ascending) {
            // The lists give exactly the slots a pass over all of them finds.
            var listed: VisibleSlots = .{ .workspace = self, .above = above, .owners = above.reached.iterator(.{}), .scanning = false };
            var scanned: VisibleSlots = .{ .workspace = self, .above = above, .owners = above.reached.iterator(.{}), .scanning = true };
            while (scanned.next()) |slot| std.debug.assert(listed.next() == slot);
            std.debug.assert(listed.next() == null);
        }
        return .{ .workspace = self, .above = above, .owners = above.reached.iterator(.{}), .scanning = !ascending };
    }

    /// The types `findMethod` may have waiting while it walks up from a class, and the slots of
    /// one name it may meet on the way; a hierarchy beyond either is answered by `scanMethod`.
    const method_walk_types = 32;
    const method_walk_slots = 16;
    /// Classes looked at before the walk gives up: it does not mark what it has seen, so a
    /// lattice of interfaces could lead it to the same ones again and again.
    const method_walk_steps = 256;

    /// The slot of the method `name` as `class` sees it: its own, an ancestor's or an interface's.
    /// A name maps to one slot throughout a hierarchy, since an override reuses the slot it replaces.
    ///
    /// The slots are indexed by owner and name, so this asks `class` and each type above it
    /// for a slot of the name, where reading every slot of the program for every call and
    /// every declaration cost the square of their number. The answer is the one that reading
    /// them all in order gives (`scanMethod`): the first, or with bridges the one its fold picks.
    fn findMethod(self: *Workspace, class: types.Type, name: []const u8) ?u32 {
        const found = self.walkMethod(class, name);
        if (paired_scans) std.debug.assert(found == self.scanMethod(class, name));
        return found;
    }

    fn walkMethod(self: *Workspace, class: types.Type, name: []const u8) ?u32 {
        if (self.slot_count == 0) return null;
        self.indexSlots();
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        var waiting: [method_walk_types]types.Type = undefined;
        var matches: [method_walk_slots]u32 = undefined;
        var match_count: usize = 0;
        var depth: usize = 1;
        var steps: usize = 0;
        waiting[0] = class;
        while (depth != 0) {
            steps += 1;
            if (steps > method_walk_steps) return self.scanMethod(class, name);
            depth -= 1;
            const current = waiting[depth];
            var same = self.slot_table.walk(&self.slot_table_slots, self.slotHash(current, name));
            while (same.next()) |index| {
                // A setter is reached through its getter, which precedes it and has its name.
                if (self.slot_kind[index] == .setter or self.slots[index].owner != current or !std.mem.eql(u8, self.slots[index].name.text(self.source), name)) continue;
                // A type reached twice offers its slots twice.
                const seen = for (matches[0..match_count]) |earlier| {
                    if (earlier == index) break true;
                } else false;
                if (seen) continue;
                if (match_count == matches.len) return self.scanMethod(class, name);
                matches[match_count] = index;
                match_count += 1;
            }
            const item = catalogue.definition(current, definitions) orelse continue;
            if (item != .class) continue;
            const above = item.class.implemented();
            if (depth + above.len + 1 > waiting.len) return self.scanMethod(class, name);
            if (item.class.parent) |parent| {
                waiting[depth] = parent;
                depth += 1;
            }
            for (above) |interface| {
                waiting[depth] = interface;
                depth += 1;
            }
        }
        if (match_count == 0) return null;
        std.mem.sort(u32, matches[0..match_count], {}, std.sort.asc(u32));
        var found = matches[0];
        if (self.bridge_count == 0) return found;
        // Two slots of one name meet only where a superclass method stands in for an
        // interface's: the superclass's slot is then the member, the other forwards to it.
        for (matches[1..match_count]) |index| {
            if (self.bridged(class, found)) found = index;
        }
        return found;
    }

    /// `findMethod` by reading every slot in order: what defines its answer, and what answers
    /// for a hierarchy too wide or too tangled for its walk.
    fn scanMethod(self: *const Workspace, class: types.Type, name: []const u8) ?u32 {
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        var found: ?u32 = null;
        for (self.slots[0..self.slot_count], 0..) |slot, index| {
            // A setter is reached through its getter, which precedes it and has its name.
            if (self.slot_kind[index] == .setter) continue;
            if (!std.mem.eql(u8, slot.name.text(self.source), name) or !catalogue.subtype(class, slot.owner, definitions)) continue;
            if (self.bridge_count == 0) return @intCast(index);
            // Two slots of one name meet only where a superclass method stands in for an
            // interface's: the superclass's slot is then the member, the other forwards to it.
            const first = found orelse {
                found = @intCast(index);
                continue;
            };
            if (self.bridged(class, first)) found = @intCast(index);
        }
        return found;
    }
    /// Whether `class` answers `slot` by forwarding to a superclass method of the same name.
    fn bridged(self: *const Workspace, class: types.Type, slot: u32) bool {
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        var at = self.slot_first[slot];
        while (at != no_member) : (at = self.methods[at].next) {
            if (self.methods[at].bridge != no_member and catalogue.subtype(class, self.methods[at].class, definitions)) return true;
        }
        return false;
    }
    fn specializationHash(name: Span, key: types.Type) u64 {
        const words = [2]u32{ name.start, name.end };
        return std.hash.Wyhash.hash(@backingInt(key), std.mem.asBytes(&words));
    }

    /// The published runtime function that is the specialization of the template named at
    /// `name` for the arguments `key`: the first one, as reading every function in order found.
    /// Every use of a generic function asks; the specializations are indexed by template and
    /// arguments, and entered here as they are published.
    fn findSpecialization(self: *Workspace, name: Span, key: types.Type) ?u32 {
        const published = self.runtime_functions.definitions[0..self.runtime_functions.count];
        while (self.specializations_indexed < published.len) : (self.specializations_indexed += 1) {
            const f = published[self.specializations_indexed];
            if (f.anonymous or f.specialization == null) continue;
            if (self.specialization_table.crowded()) {
                self.specialization_table.grow(&self.specialization_slots);
                for (published[0..self.specializations_indexed], 0..) |earlier, at| {
                    if (!earlier.anonymous and earlier.specialization != null) self.specialization_table.enter(&self.specialization_slots, specializationHash(earlier.name, earlier.specialization.?), @intCast(at));
                }
            }
            self.specialization_table.enter(&self.specialization_slots, specializationHash(f.name, f.specialization.?), self.specializations_indexed);
        }
        var same = self.specialization_table.walk(&self.specialization_slots, specializationHash(name, key));
        const found: ?u32 = while (same.next()) |index| {
            const f = published[index];
            if (!f.anonymous and std.meta.eql(f.name, name) and f.specialization == key) break index;
        } else null;
        if (paired_scans) {
            const scanned: ?u32 = for (published, 0..) |f, index| {
                if (!f.anonymous and std.meta.eql(f.name, name) and f.specialization == key) break @intCast(index);
            } else null;
            std.debug.assert(found == scanned);
        }
        return found;
    }
    fn isInterface(self: *const Workspace, class: types.Type) bool {
        const item = catalogue.definition(class, self.catalogue.definitions[0..self.catalogue.count]) orelse return false;
        return item == .class and item.class.is_interface;
    }
    const Resolution = union(enum) { found: u32, none, ambiguous };
    /// The declaration of `slot` that a class whose supertypes are `above` sees. A class in its superclass chain wins: the
    /// nearest one. Otherwise it is the declaration of the most specific interface above the
    /// class; two interfaces that each redeclare the method with neither extending the other
    /// leave no answer. Declarations of one slot are listed in order and a subtype is always
    /// declared after its supertypes, so the last match is the nearest.
    fn resolve(self: *const Workspace, slot: u32, above: *const catalogue.Supertypes, comptime declared_only: bool) Resolution {
        if (self.slot_first[slot] == no_member) return .none;
        // A slot with few declarations is read through; one that many classes declare (the
        // classes below one parent that each override a method) is asked through the
        // supertypes of the class, so that a class does not read what its siblings declared.
        if (!paired_scans and self.slot_declared[slot] <= slot_walk_limit) return self.resolveListed(slot, above, declared_only);
        const found = self.resolveAbove(slot, above, declared_only);
        if (paired_scans) std.debug.assert(std.meta.eql(found, self.resolveListed(slot, above, declared_only)));
        return found;
    }
    /// The declarations of one slot that are read one by one before the index is asked.
    const slot_walk_limit = 16;

    fn classMethodHash(class: types.Type, slot: u32) u64 {
        const words = [2]u32{ @backingInt(class), slot };
        return std.hash.Wyhash.hash(0, std.mem.asBytes(&words));
    }

    /// The newest declaration of `slot` that `class` itself makes, or `no_member`.
    fn methodAt(self: *const Workspace, class: types.Type, slot: u32, comptime declared_only: bool) u32 {
        var found: u32 = no_member;
        var same = self.class_method_table.walk(&self.class_method_slots, classMethodHash(class, slot));
        while (same.next()) |index| {
            const method = &self.methods[index];
            if (method.class != class or method.slot != slot or (declared_only and method.synthetic)) continue;
            if (found == no_member or index > found) found = index;
        }
        return found;
    }

    /// `resolveListed` by asking the supertypes: the nearest class of the superclass chain
    /// that declares the slot, which is the newest such declaration because a subclass is
    /// declared after its superclass; without one, the newest declaration of an interface
    /// above the class, checked against the other interfaces' as there.
    fn resolveAbove(self: *const Workspace, slot: u32, above: *const catalogue.Supertypes, comptime declared_only: bool) Resolution {
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        // The class asked about is the last type its supertypes hold.
        const top = above.reached.findLastSet() orelse return .none;
        var current: types.Type = @fromBackingInt(@as(u16, @intCast(catalogue.builtin_count + top)));
        while (true) {
            const item = catalogue.definition(current, definitions) orelse break;
            if (item != .class) break;
            if (!item.class.is_interface) {
                const own = self.methodAt(current, slot, declared_only);
                if (own != no_member) return .{ .found = own };
            }
            current = item.class.parent orelse break;
        }
        var default: u32 = no_member;
        var owners = above.reached.iterator(.{});
        while (owners.next()) |owner| {
            const interface: types.Type = @fromBackingInt(@as(u16, @intCast(catalogue.builtin_count + owner)));
            if (!self.isInterface(interface)) continue;
            const own = self.methodAt(interface, slot, declared_only);
            if (own != no_member and (default == no_member or own > default)) default = own;
        }
        if (default == no_member) return .none;
        owners = above.reached.iterator(.{});
        while (owners.next()) |owner| {
            const interface: types.Type = @fromBackingInt(@as(u16, @intCast(catalogue.builtin_count + owner)));
            if (interface == self.methods[default].class or !self.isInterface(interface)) continue;
            if (self.methodAt(interface, slot, declared_only) == no_member) continue;
            if (!catalogue.subtype(self.methods[default].class, interface, definitions)) return self.rivals(slot, above, declared_only);
        }
        return .{ .found = default };
    }

    /// Whether a supertype of `class`, or `class` itself, declares `slot` `<final>`.
    fn sealedAbove(self: *const Workspace, class: types.Type, slot: u32) bool {
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        if (self.slot_first[slot] == no_member or self.slot_finals[slot] == 0) return false;
        var listed = false;
        if (paired_scans or self.slot_declared[slot] <= slot_walk_limit) {
            var sealed = self.slot_first[slot];
            while (sealed != no_member) : (sealed = self.methods[sealed].next) {
                if (self.methods[sealed].is_final and catalogue.subtype(class, self.methods[sealed].class, definitions)) listed = true;
            }
            if (!paired_scans) return listed;
        }
        const above = catalogue.Supertypes.of(class, definitions) orelse return false;
        var owners = above.reached.iterator(.{});
        const found = while (owners.next()) |owner| {
            const supertype: types.Type = @fromBackingInt(@as(u16, @intCast(catalogue.builtin_count + owner)));
            var same = self.class_method_table.walk(&self.class_method_slots, classMethodHash(supertype, slot));
            const final = while (same.next()) |index| {
                const method = &self.methods[index];
                if (method.class == supertype and method.slot == slot and method.is_final) break true;
            } else false;
            if (final) break true;
        } else false;
        if (paired_scans) std.debug.assert(found == listed);
        return found;
    }

    /// `resolve` by reading the declarations of the slot: what defines its answer.
    fn resolveListed(self: *const Workspace, slot: u32, above: *const catalogue.Supertypes, comptime declared_only: bool) Resolution {
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        var default: u32 = no_member;
        // Newest first: in a deep chain of overrides the nearest one is found at once.
        var at = self.slot_last[slot];
        if (self.slot_first[slot] == no_member) return .none;
        while (at != no_member) : (at = self.methods[at].previous) {
            const method = self.methods[at];
            // Generated accessors and forwarders implement a slot but declare nothing.
            if (declared_only and method.synthetic) continue;
            if (!above.has(method.class)) continue;
            // The supertypes of a class that are not interfaces are exactly its superclass chain.
            if (!self.isInterface(method.class)) return .{ .found = at };
            if (default == no_member) default = at;
        }
        if (default == no_member) return .none;
        at = self.slot_first[slot];
        while (at != no_member) : (at = self.methods[at].next) {
            const method = self.methods[at];
            if (at == default or (declared_only and method.synthetic) or !self.isInterface(method.class) or !above.has(method.class)) continue;
            if (!catalogue.subtype(self.methods[default].class, method.class, definitions)) return self.rivals(slot, above, declared_only);
        }
        return .{ .found = default };
    }
    /// Several interfaces redeclare `slot` and none of them extends all the others. There is a
    /// choice to make only if one of the most specific declarations offers a body; when they all
    /// leave the method abstract it is simply unimplemented.
    fn rivals(self: *const Workspace, slot: u32, above: *const catalogue.Supertypes, comptime declared_only: bool) Resolution {
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        var at = self.slot_first[slot];
        while (at != no_member) : (at = self.methods[at].next) {
            const method = self.methods[at];
            if (method.runtime == null or (declared_only and method.synthetic) or !self.isInterface(method.class) or !above.has(method.class)) continue;
            var other = self.slot_first[slot];
            const refined = while (other != no_member) : (other = self.methods[other].next) {
                const rival = self.methods[other];
                if (other == at or (declared_only and rival.synthetic) or !self.isInterface(rival.class) or !above.has(rival.class)) continue;
                if (catalogue.subtype(rival.class, method.class, definitions)) break true;
            } else false;
            if (!refined) return .ambiguous;
        }
        return .none;
    }
    /// The method a `class` instance runs for `slot`, if exactly one applies and it has a body.
    fn implementationOf(self: *const Workspace, slot: u32, above: *const catalogue.Supertypes) Resolution {
        return switch (self.resolve(slot, above, false)) {
            // An abstract redeclaration hides the implementations above it.
            .found => |index| if (self.methods[index].runtime != null) .{ .found = index } else .none,
            else => |other| other,
        };
    }
    /// The declaration whose parameter names and defaults a call on a `class` receiver uses.
    fn declarationOf(self: *const Workspace, class: types.Type, slot: u32) u32 {
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        const above = catalogue.Supertypes.of(class, definitions).?;
        return switch (self.resolve(slot, &above, true)) {
            .found => |index| index,
            // Every slot is introduced by a declaration of its owner, which is above `class`.
            .none, .ambiguous => self.slot_first[slot],
        };
    }
    /// Lists method `index` among the declarations of its slot.
    fn linkMethod(self: *Workspace, index: u32) void {
        const slot = self.methods[index].slot;
        if (self.class_method_table.crowded()) {
            self.class_method_table.grow(&self.class_method_slots);
            for (self.methods[0..index], 0..) |earlier, at| self.class_method_table.enter(&self.class_method_slots, classMethodHash(earlier.class, earlier.slot), @intCast(at));
        }
        self.class_method_table.enter(&self.class_method_slots, classMethodHash(self.methods[index].class, slot), index);
        if (self.slot_first[slot] == no_member) {
            self.slot_declared[slot] = 0;
            self.slot_finals[slot] = 0;
            self.slot_narrowings[slot] = 0;
        }
        self.slot_declared[slot] += 1;
        self.slot_finals[slot] += @intFromBool(self.methods[index].is_final);
        self.slot_narrowings[slot] += @intFromBool(self.methods[index].narrowed != null);
        self.methods[index].next = no_member;
        self.methods[index].previous = if (self.slot_first[slot] == no_member) no_member else self.slot_last[slot];
        if (self.slot_first[slot] == no_member) self.slot_first[slot] = index else self.methods[self.slot_last[slot]].next = index;
        self.slot_last[slot] = index;
    }
    /// Whether the class declared at `name` was reserved by the declaration pre-pass and awaits its fields.
    fn reservedClassAt(self: *const Workspace, name: Span) bool {
        const found = self.findType(name.text(self.source)) orelse return false;
        const item = catalogue.definition(found, self.catalogue.definitions[0..self.catalogue.count]).?;
        return item == .class and catalogue.pendingClass(item.class) and std.meta.eql(item.class.name, name);
    }
    /// The builtin character type `name` spells, when it spells one.
    fn characterType(name: []const u8) ?types.Type {
        if (std.mem.eql(u8, name, "char")) return types.Type.char;
        if (std.mem.eql(u8, name, "char32")) return types.Type.char32;
        return null;
    }
    fn characterBit(value_type: types.Type) u8 {
        return if (value_type == types.Type.char) 1 else 2;
    }
    /// Records that the current module read `value_type`'s name as the builtin.
    fn useCharacter(self: *Workspace, value_type: types.Type) void {
        const module = self.current_module;
        if (module >= self.character_use_high) {
            @memset(self.character_uses[self.character_use_high .. module + 1], 0);
            self.character_use_high = module + 1;
        }
        self.character_uses[module] |= characterBit(value_type);
    }
    fn usedCharacter(self: *const Workspace, value_type: types.Type) bool {
        return self.current_module < self.character_use_high and self.character_uses[self.current_module] & characterBit(value_type) != 0;
    }
    /// RFC-0093: the import that the preparation recorded for the module path written at `at`.
    fn pathImport(self: *const Workspace, at: Span) ?types.Import {
        if (self.module_storage.module_count == 0) return null;
        const holder = modules.owner(at, self.module_storage.modules[0..self.module_storage.module_count]) orelse return null;
        const range = self.module_storage.modules[holder].imports;
        for (self.module_storage.imports[range.start..range.end]) |edge| if (edge.path.start == at.start and edge.alias.start == edge.alias.end) return edge;
        return null;
    }
    fn findAlias(self: *const Workspace, name: []const u8) ?types.Import {
        if (self.module_storage.module_count == 0) return null;
        const range = self.module_storage.modules[self.current_module].imports;
        for (self.module_storage.imports[range.start..range.end]) |edge| if (std.mem.eql(u8, name, edge.alias.text(self.source))) return edge;
        return null;
    }

    /// The public API of a bundle whose files declare modules (RFC-0074): a `<public>`
    /// declaration is used as far out as the modules around it are public, and every type in
    /// its signature must be nameable there.
    fn checkNestedApi(self: *Workspace) ParseError!void {
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        const fields = self.catalogue.fields[0..self.catalogue.field_count];
        const privacy = catalogue.Privacy.create(definitions, self.catalogue.tuple_elements[0..self.catalogue.tuple_count], self.module_storage.modules[0..self.module_storage.module_count], self.nestedModules()) orelse return self.fail(.{ .start = 0, .end = 0 }, .type_limit);
        defer privacy.destroy();
        // A member that does not leave its module takes no type out of it: the field is
        // hidden instead (`markHidden`, RFC-0076 D14).
        self.markHidden();
        for (definitions) |item| {
            // A public template's member types are checked where it is declared
            // (`checkTemplateTypes`); what an instantiation adds is its arguments, which its
            // reach has weighed.
            if ((item != .record and item != .class) or !catalogue.declaredPublic(item) or catalogue.typeArguments(item) != null) continue;
            const range = if (item == .record) item.record.fields else item.class.fields;
            for (fields[range.start..range.end]) |field| if (!field.hidden and !privacy.admits(field.value_type, catalogue.declaredName(item).?, true)) return self.fail(field.name, .private_type_escape);
        }
        for (self.bindings[0..self.binding_count]) |binding| if (!privacy.admits(binding.value_type, binding.name, binding.is_public)) return self.fail(binding.name, .private_type_escape);
        for (self.type_aliases[0..self.type_alias_count]) |alias| if (!privacy.admits(alias.value, alias.name, alias.is_public)) return self.fail(alias.name, .private_type_escape);
        for (self.functions.definitions[0..self.functions.count]) |function| {
            if (!function.is_public) continue;
            if (!privacy.admits(function.value_type, function.name, true)) return self.fail(function.name, .private_type_escape);
            for (function.parameters[0..function.parameter_count]) |parameter| if (!privacy.admits(parameter.value_type, function.name, true)) return self.fail(parameter.name, .private_type_escape);
        }
    }

    /// Whether the class field at catalogue index `index` is `<internal>` or `<private>`: no
    /// other module reads, writes or names it.
    fn staysInside(self: *const Workspace, index: usize) bool {
        return self.field_access[index] == .internal or self.field_access[index] == .private;
    }

    /// Marks the fields that no public report shows (`types.Field.hidden`): every field of a
    /// public class that is `<internal>` or `<private>`, so that no other module reads it.
    /// Its value is not something the public API reaches, and its type does not travel with
    /// the class: what is exportable is weighed without it (`catalogue.exportableTypes`).
    /// (RFC-0076 hid such a field only when its type was private; `fix2` hides it whatever
    /// its type, because a public report shows only what the public API reaches.)
    ///
    /// Admission requires a subclass to repeat its parent's fields exactly, marks included,
    /// so the classes above a public one are marked the same way (a private parent of a
    /// public class hides its internal fields in both), and every other class takes its
    /// parent's marks for the fields it inherits and shows its own. A parent comes before its
    /// subclasses in the catalogue, as admission requires: one pass from the end finds the
    /// classes above a public one, and one pass in order marks them.
    fn markHidden(self: *Workspace) void {
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        const above = self.hidden_owners[0..definitions.len];
        @memset(above, false);
        var index = definitions.len;
        while (index != 0) {
            index -= 1;
            const item = definitions[index];
            if (item != .class or catalogue.pendingClass(item.class)) continue;
            if (item.class.is_public) above[index] = true;
            if (!above[index]) continue;
            const parent = item.class.parent orelse continue;
            const position = @backingInt(parent) - catalogue.builtin_count;
            std.debug.assert(position < index);
            above[position] = true;
        }
        for (definitions, 0..) |item, position| {
            if (item != .class or catalogue.pendingClass(item.class)) continue;
            const range = item.class.fields;
            if (above[position]) {
                for (range.start..range.end) |field| self.catalogue.fields[field].hidden = self.staysInside(field);
                continue;
            }
            for (range.start + item.class.inherited..range.end) |field| self.catalogue.fields[field].hidden = false;
        }
        self.inheritHidden();
    }

    /// Gives the copies that every class holds of its parent's fields the parent's marks:
    /// both admissions require a subclass to repeat its parent's fields exactly, and a field
    /// hidden in the parent must not be printed through an instance of a subclass, private
    /// ones and instantiations included. A parent comes before its subclasses in the
    /// catalogue (as admission requires), so one pass in order carries a mark all the way down.
    fn inheritHidden(self: *Workspace) void {
        const definitions = self.catalogue.definitions[0..self.catalogue.count];
        for (definitions, 0..) |item, index| {
            if (item != .class or catalogue.pendingClass(item.class)) continue;
            const parent = item.class.parent orelse continue;
            const above = catalogue.definition(parent, definitions) orelse continue;
            if (above != .class or catalogue.pendingClass(above.class)) continue;
            std.debug.assert(@backingInt(parent) - catalogue.builtin_count < index);
            std.debug.assert(item.class.inherited <= above.class.fields.end - above.class.fields.start);
            for (0..item.class.inherited) |offset| {
                self.catalogue.fields[item.class.fields.start + offset].hidden = self.catalogue.fields[above.class.fields.start + offset].hidden;
            }
        }
    }

    fn checkPublicApi(self: *Workspace) ParseError!void {
        if (self.module_storage.nested_count != 0) return self.checkNestedApi();
        var exposed: [types.limits.user_types]bool = undefined;
        self.markHidden();
        catalogue.exportableTypes(self.catalogue.definitions[0..self.catalogue.count], self.catalogue.fields[0..self.catalogue.field_count], self.catalogue.tuple_elements[0..self.catalogue.tuple_count], &exposed);
        if (paired_scans) {
            // The marks left standing give the table they were chosen under.
            var again: [types.limits.user_types]bool = undefined;
            catalogue.exportableTypes(self.catalogue.definitions[0..self.catalogue.count], self.catalogue.fields[0..self.catalogue.field_count], self.catalogue.tuple_elements[0..self.catalogue.tuple_count], &again);
            std.debug.assert(std.mem.eql(bool, exposed[0..self.catalogue.count], again[0..self.catalogue.count]));
        }
        const admitted = exposed[0..self.catalogue.count];
        for (self.catalogue.definitions[0..self.catalogue.count]) |item| {
            // A public template's member types are checked where it is declared; what an
            // instantiation adds is its arguments, which make it private when they are.
            if ((item == .record or item == .class) and catalogue.declaredPublic(item) and catalogue.typeArguments(item) == null) for (self.catalogue.fields[(if (item == .record) item.record.fields else item.class.fields).start..(if (item == .record) item.record.fields else item.class.fields).end]) |field| {
                if (catalogue.exportable(field.value_type, admitted) or field.hidden) continue;
                // A field inherited from a type of another module is written there: the
                // declaration that exposes the private type is the class itself.
                const declared = catalogue.declaredName(item).?;
                const own = self.module_storage.module_count == 0 or modules.owner(field.name, self.module_storage.modules[0..self.module_storage.module_count]) == modules.owner(declared, self.module_storage.modules[0..self.module_storage.module_count]);
                return self.fail(if (own) field.name else declared, .private_type_escape);
            };
        }
        for (self.bindings[0..self.binding_count]) |binding| if (binding.is_public and !catalogue.exportable(binding.value_type, admitted)) return self.fail(binding.name, .private_type_escape);
        for (self.type_aliases[0..self.type_alias_count]) |alias| if (alias.is_public and !catalogue.exportable(alias.value, admitted)) return self.fail(alias.name, .private_type_escape);
        for (self.functions.definitions[0..self.functions.count]) |function| {
            if (!function.is_public) continue;
            if (!catalogue.exportable(function.value_type, admitted)) return self.fail(function.name, .private_type_escape);
            for (function.parameters[0..function.parameter_count]) |parameter| if (!catalogue.exportable(parameter.value_type, admitted)) return self.fail(parameter.name, .private_type_escape);
        }
    }

    fn assertCounts(self: *const Workspace) void {
        std.debug.assert(self.anonymous_count <= self.anonymous_frames.len);
        std.debug.assert(self.generic_count + self.functions.count <= types.limits.functions);
        std.debug.assert(self.token_count <= self.tokens.len);
        std.debug.assert(self.node_count <= self.nodes.len);
        std.debug.assert(self.binding_count <= self.bindings.len);
        std.debug.assert(self.local_count <= self.locals.len and self.local_checkpoint_count <= self.local_checkpoints.len);
        std.debug.assert(self.source_cell_count <= self.source_cells.len and self.source_ops <= self.node_count);
        std.debug.assert(self.string_count <= self.strings.len);
        std.debug.assert(self.string_comparisons <= self.node_count);
        std.debug.assert(self.functions.count <= self.functions.definitions.len);
        std.debug.assert(self.functions.node_count <= self.functions.nodes.len);
        std.debug.assert(self.expansion_work <= types.limits.compiler_work);
        std.debug.assert(self.member_count <= self.members.len and self.functions.member_count <= self.functions.members.len);
        std.debug.assert(self.staging_count <= self.staging.len);
        std.debug.assert(self.catalogue.count <= self.catalogue.definitions.len);
        std.debug.assert(self.catalogue.field_count <= self.catalogue.fields.len);
        std.debug.assert(self.catalogue.case_count <= self.catalogue.cases.len);
        std.debug.assert(self.catalogue.tuple_count <= self.catalogue.tuple_elements.len);
    }

    fn fail(self: *Workspace, span: Span, code: Diagnostic.Code) ParseError {
        std.debug.assert(span.start <= span.end and span.end <= self.source.len);
        // What cannot fail inside a `Defer` is reported as that, not as a missing failure context.
        self.diagnostic = .{ .span = if (self.libraryModule(span)) |module| self.siteBlame(span) orelse self.library_blame[module] else span, .code = if (code == .failure_context_required and self.defer_barrier) .defer_failure else code };
        // RFC-0082, P3.8: what can fail in an iteration of a `For` that has no regions is
        // reported as that, at the clause it stands in.
        if (self.diagnostic.code == .failure_context_required) if (self.suspendClause(self.diagnostic.span)) |clause| {
            self.diagnostic.code = .suspending_for_fails;
            self.diagnostic.span = clause.span;
        };
        return error.InvalidSource;
    }

    /// How far back from the parser's cursor `siteBlame` looks for a generated token.
    const blame_window = 16;

    /// The macro call that the generated code at `span` (a place in a library block) was
    /// generated for, while a parse is in progress: the keyword of that call, so that a
    /// diagnostic about the code of one loop names that loop and not the first macro call of
    /// its module. Every generated token knows its call (`Token.site`); the token at `span`
    /// is the one the parser is reading or one it read just before, and failing that the
    /// nearest generated token it has read is of the same expansion, because a template's
    /// brackets balance. Null when no token near the cursor says, and the module's first call
    /// is named as before.
    fn siteBlame(self: *const Workspace, span: Span) ?Span {
        const cursor = (self.parse_cursor orelse return null).*;
        if (self.token_count == 0) return null;
        // A call of another module is never to blame for this module's generated code.
        const module = self.libraryModule(span) orelse return null;
        const last = @min(cursor, self.token_count - 1);
        const first = last -| (blame_window - 1);
        var index = last + 1;
        while (index > first) {
            index -= 1;
            const token = self.tokens[index];
            if (token.span.start == span.start) if (self.siteOf(token, module)) |call| return call;
        }
        // The tokens already read, the nearest first; the one being read last.
        index = last;
        while (index > first) {
            index -= 1;
            if (self.siteOf(self.tokens[index], module)) |call| return call;
        }
        return self.siteOf(self.tokens[last], module);
    }

    /// The call a generated token was generated for, if that call is written in `module`.
    fn siteOf(self: *const Workspace, token: Token, module: u32) ?Span {
        if (token.site == 0) return null;
        const call = self.keywordSpan(token.site - 1);
        const count = self.module_storage.module_count;
        if (count != 0 and modules.owner(call, self.module_storage.modules[0..count]) != module) return null;
        return call;
    }

    /// The span of the keyword (or the opening parenthesis of a pattern) written at `start`.
    fn keywordSpan(self: *const Workspace, start: u32) Span {
        var end = start;
        while (end < self.source.len and (std.ascii.isAlphanumeric(self.source[end]) or self.source[end] == '_')) end += 1;
        return .{ .start = start, .end = @max(end, @min(start + 1, @as(u32, @intCast(self.source.len)))) };
    }

    /// Marks the generated tokens a macro call just emitted, `spare_tokens[from..rw.out]`, as
    /// that call's. Tokens of calls inside it are marked already and keep their own call; a
    /// call that is itself generated (the `If` of a `While`) hands on the call it came from.
    fn tagSite(self: *Workspace, rw: *const Rewrite, from: usize, keyword: Token) void {
        const count = self.module_storage.module_count;
        const module: u32 = if (count == 0) 0 else modules.owner(keyword.span, self.module_storage.modules[0..count]) orelse return;
        const base = self.library_base[module];
        if (base == 0) return;
        const site: u32 = if (keyword.site != 0) keyword.site else if (keyword.span.start < base) keyword.span.start + 1 else return;
        const end = self.moduleEnd(module);
        for (self.spare_tokens[from..rw.out]) |*token| {
            if (token.site == 0 and token.span.start >= base and token.span.start < end) token.site = site;
        }
    }

    /// The span of the user's tokens `range`, if that is one stretch of a module's own text.
    fn userSpan(self: *const Workspace, range: [2]usize) ?Span {
        if (range[0] >= range[1]) return null;
        const first = self.tokens[range[0]];
        const last = self.tokens[range[1] - 1];
        if (first.site != 0 or last.site != 0 or first.span.start >= last.span.end) return null;
        const span: Span = .{ .start = first.span.start, .end = last.span.end };
        if (self.libraryModule(first.span) != null or self.libraryModule(last.span) != null) return null;
        const count = self.module_storage.module_count;
        if (count != 0 and modules.owner(span, self.module_storage.modules[0..count]) == null) return null;
        return span;
    }

    fn emit(self: *Workspace, node_in: types.Node) ParseError!u32 {
        var node = node_in;
        if (self.libraryModule(node.span)) |module| node.span = self.siteBlame(node.span) orelse self.library_blame[module];
        if (self.node_count == self.nodes.len) return self.fail(node.span, .node_limit);
        const index = self.node_count;
        if (node.kind == .compare and catalogue.walkedEquality(self.nodes[node.kind.compare.lhs].value_type, self.catalogue.definitions[0..self.catalogue.count])) self.string_comparisons += 1;
        if (types.controlOp(node)) self.control_ops += 1;
        if (types.sourceOp(node)) self.source_ops += 1;
        if (node.kind == .call or node.kind == .invoke) self.call_ops += 1;
        self.nodes[index] = node;
        self.literal_nodes.unset(index);
        self.node_count += 1;
        std.debug.assert(index < self.node_count);
        return index;
    }

    fn findSymbol(self: *const Workspace, name: []const u8) ?u32 {
        return self.findSymbolIn(name, self.scope());
    }
    fn findTypeAliasIn(self: *const Workspace, name: []const u8, scope_range: Span) ?TypeAlias {
        for (self.type_aliases[0..self.type_alias_count]) |alias| {
            if (modules.contains(scope_range, alias.name) and std.mem.eql(u8, name, alias.name.text(self.source)) and modules.owned(scope_range, alias.name, self.nestedModules())) return alias;
        }
        return null;
    }

    fn findNativeIn(self: *const Workspace, name: []const u8, scope_range: Span) ?u32 {
        for (self.native_bindings[0..self.native_binding_count], 0..) |binding, index| {
            if (modules.contains(scope_range, binding.name) and std.mem.eql(u8, name, binding.name.text(self.source)) and modules.owned(scope_range, binding.name, self.nestedModules())) return @intCast(index);
        }
        return null;
    }

    fn findSymbolIn(self: *const Workspace, name: []const u8, scope_range: Span) ?u32 {
        const start = std.hash.Wyhash.hash(scope_range.start, name) % self.symbols.len;
        for (0..self.symbols.len) |probe| {
            const entry = self.symbols[(start + probe) % self.symbols.len];
            if (entry == 0) return null;
            const index: u32 = entry - 1;
            std.debug.assert(index < self.binding_count);
            if (self.bindingIn(index, scope_range) and std.mem.eql(u8, name, self.bindings[index].name.text(self.source))) return index;
        }
        return null;
    }

    /// Whether binding `index` was declared by the scope whose text is `scope_range`.
    fn bindingIn(self: *const Workspace, index: u32, scope_range: Span) bool {
        if (self.module_storage.nested_count == 0) return modules.contains(scope_range, self.bindings[index].name);
        const declared = self.scopeOf(self.binding_scope[index]);
        return declared.start == scope_range.start and declared.end == scope_range.end;
    }

    fn insertSymbol(self: *Workspace, binding: types.Binding, cell: ?u32) void {
        std.debug.assert(self.binding_count < self.bindings.len);
        std.debug.assert(self.findSymbol(binding.name.text(self.source)) == null);
        std.debug.assert(binding.node < self.node_count);
        std.debug.assert(self.nodes[binding.node].value_type == binding.value_type);
        const start = std.hash.Wyhash.hash(self.scope().start, binding.name.text(self.source)) % self.symbols.len;
        for (0..self.symbols.len) |probe| {
            const slot = (start + probe) % self.symbols.len;
            if (self.symbols[slot] != 0) continue;
            self.bindings[self.binding_count] = binding;
            self.binding_cells[self.binding_count] = if (cell) |id| @intCast(id) else std.math.maxInt(u16);
            self.binding_scope[self.binding_count] = self.currentScope();
            self.symbols[slot] = @intCast(self.binding_count + 1);
            self.binding_count += 1;
            return;
        }
        unreachable; // Table capacity is twice the maximum binding count.
    }
};

/// A method declared by a class: its slot, and the runtime function once its body is compiled.
const MethodInfo = struct {
    class: types.Type,
    name: Span,
    slot: u32,
    runtime: ?u32 = null,
    function: u32 = 0,
    is_final: bool = false,
    is_abstract: bool = false,
    /// A generated implementation: the accessor of an interface field, or a forwarder.
    synthetic: bool = false,
    /// For a forwarder, the slot of the superclass method it calls.
    bridge: u32 = no_member,
    /// B4 (RFC-0092): the access an override narrowed the method to, here or above, and the
    /// class that narrowed it; null where the slot's own access holds.
    narrowed: ?Narrowing = null,
    /// B4 (RFC-0092): for an override with a narrower result, the slot it replaced, which a
    /// forwarder of its class answers.
    refines: u32 = no_member,
    /// The next and the previous declaration of the same slot.
    next: u32 = no_member,
    previous: u32 = no_member,
};
const SlotKind = enum(u8) { method, getter, setter };
/// B4 (RFC-0092): who may call a method below the class that narrowed its access.
const Narrowing = struct { access: Access, declaring: types.Type };
const InterfaceField = struct { value_type: types.Type, is_var: bool, default: functions.Body, is_final: bool = false };
const MethodParameter = struct { name: Span, default: functions.Body };
/// Macro calls nested inside one another are rewritten by native recursion with sizeable frames,
/// so their depth is bound by the native stack rather than by the operator stack.
const rewrite_depth = @min(types.limits.expression_depth, 128);
/// `Defer`s whose scope is open in one function, and copies of `Defer` bodies nested in one another.
const max_defer_marks = 64;
const max_defer_copies = 16;
const DeferMark = struct { locals: u32, operator: u32, span: Span = .{ .start = 0, .end = 0 } };
/// The function a cancellation runs for a `Defer` (RFC-0082, P3.3), compiled once where the
/// `Defer` stands: its type, its type once its captures are bound, its result (the unit value),
/// and the names it captures, which each site reads again as they are there.
const Landing = struct {
    function: u32 = no_member,
    closure: types.Type = undefined,
    bound: types.Type = undefined,
    result: types.Type = undefined,
    capture_count: u32 = 0,
    names: [types.limits.parameters]Span = undefined,
};
/// A copy of a `Defer` body being compiled: the block operator it is, and the locals it does
/// not see, `from ... to - 1`, declared after its `Defer` was written.
const DeferCopy = struct { operator: u32, from: u32, to: u32 };
/// A class's method declarations are found before any is compiled; their positions wait on the stack.
const max_class_methods = @min(types.limits.methods, 4096);
/// `Block{...}` clauses written in one class body.
const max_class_blocks = 64;
/// A live field of a class being declared (RFC-0084, P4.2): its index in the class, the
/// `synthetic_guard` token of its guard, its name, and the word `class` of its class's
/// declaration, which names the class's clauses when it has no `Block{...}` (C34).
const LiveField = struct { index: u32, guard: u32, name: Token, keyword: Token, raw: u32 = no_member };
/// RFC-0085, I8: `var<W> F<R><getter(G)><setter(S)>:T = external{}` in class or interface
/// `owner`. `getter` and `setter` are the slots of `G` and `S`, `no_member` until the owner's
/// methods are declared (`resolveAccessors`).
/// RFC-0087, P5.2: the field defaults of `<persistable>` types as values (T5), which the
/// program publishes as `constants`, and the members of those that are aggregates. Every
/// constant comes from a template node, and every member from a template member.
const ConstantStorage = struct {
    constants: [types.limits.template_nodes]types.Constant = undefined,
    constant_count: u32 = 0,
    constant_members: [types.limits.aggregate_elements]u32 = undefined,
    constant_member_count: u32 = 0,
    /// What `persistable.persistableTypes` says of the catalogue, while the rules are checked.
    kinds: [types.limits.user_types]bool = undefined,
    /// RFC-0087, P5.3: the walk of a type that `ToJson` or `FromJson` names (`jsonShape`): the
    /// definitions to visit, and per definition the walk that last visited it. `json_stamp` is 0
    /// until the first walk of a compile, which clears the marks.
    json_pending: [types.limits.user_types]types.Type = undefined,
    json_marks: [types.limits.user_types]u32 = undefined,
    json_stamp: u32 = 0,
};

const AccessorField = struct {
    owner: types.Type,
    value_type: types.Type,
    name: Span,
    getter_name: Span,
    setter_name: Span,
    getter: u32 = no_member,
    setter: u32 = no_member,
    read: Access,
    write: Access,
    /// RFC-0085, I9: declared without a default, so every archetype of a class that has it
    /// gives it a value, which the setter receives once the instance is built.
    required: bool = false,
};
/// RFC-0085, I9: the value `node` the archetype numbered `archetype` gave a field with accessors.
const AccessorGiven = struct { archetype: u32 = 0, node: u32 = no_member };
/// A variable whose type is a function (RFC-0084, P4.3). `out` follows `F(raw)`: a module cell
/// (`class` null), or a field by its index in `class`, the class that declares it; `raw` is where
/// the raw value is kept, in the same place. The program's writes of `out` are writes of `raw`.
/// `fixed`: the program never assigns the raw value (the immutable forms); `hidden`: it cannot
/// name it (`var X:F = E`).
const LiveType = struct { class: ?types.Type = null, out: u32, raw: u32, fixed: bool, hidden: bool };
/// Where the guard of a variable whose type is a function finds the raw value (RFC-0084, P4.3):
/// a module cell, or a field of `Self` by its index in the class.
const LiveRaw = union(enum) { cell: u32, field: u32 };
const MethodSignature = struct { function: functions.Definition, is_override: bool = false, is_final: bool = false, is_abstract: bool = false, access: ?Access = null, converges: bool = false, discards: bool = false };
/// What a parameter list does with `= default`: reject it, compile it, or step over one that
/// an earlier reading of the same tokens compiled.
/// `nested`: a nested function's (RFC-0085, I4), read as a top-level function's are (`nestedDefault`).
const Defaults = enum { none, parse, skip, nested };
/// `<public>` anywhere; `<internal>` (the default, RFC-0076) in the module that declares the
/// class and the modules nested in it; `<protected>` in the class and its subclasses;
/// `<private>` in the class.
const Access = enum(u8) {
    public,
    protected,
    private,
    internal,

    fn named(text: []const u8) ?Access {
        if (std.mem.eql(u8, text, "public")) return .public;
        if (std.mem.eql(u8, text, "internal")) return .internal;
        if (std.mem.eql(u8, text, "protected")) return .protected;
        if (std.mem.eql(u8, text, "private")) return .private;
        return null;
    }

    /// Whether everyone who has access `self` also has access `other`: who may assign a field
    /// may read it. `internal` and `protected` are not ordered: a subclass in another module
    /// has one and not the other.
    fn within(self: Access, other: Access) bool {
        return self == other or other == .public or self == .private;
    }
};

/// `Operator.head` of a `with_field` that is `set live E.F = G` (RFC-0084, P4.2).
const live_field_head: u32 = no_member - 1;
/// `Operator.head` of a `with_field` that assigns a field with accessors (RFC-0085, I8), whose
/// index in `Workspace.accessor_fields` is then `Operator.method`.
const accessor_field_head: u32 = no_member - 2;
/// `Operator.head` of an `index` that reads a keyed cell, `X[K]`, or of a `with_index` that
/// writes one, `set X[K] = V` (RFC-0087, P5.4): the cell is then `Operator.method`, and the
/// operator has no base operand.
const keyed_cell_head: u32 = no_member - 3;
/// `Operator.selected` of a `Set(X, E)` whose `X` is a shared local (`function` is the node
/// of its cell), or an assignment that shares it in a discarded compile (RFC-0085, I2).
const set_ref: u32 = no_member - 1;
const set_noted: u32 = no_member - 2;
/// `Operator.selected` of a class archetype whose pending entry gives a field with accessors
/// and no default (RFC-0085, I9); its index in `Workspace.accessor_fields` is `Operator.accessor`.
const accessor_selected: u32 = no_member - 1;
const Operator = struct {
    kind: enum { open, anonymous_capture, block, call, invoke, recur, iterate, iterate_value, loop, bind, conditional, attempt, demand, fail, exit, err, set_value, set_local_value, record, array, tuple, option, map, lookup, option_or, index, convert, native_call, with_field, with_index, element_at, exhaustive, text_method, positive, negative, add, subtract, multiply, divide, equal, unequal, less, less_equal, greater, greater_equal, logical_not, logical_and, logical_or },
    span: Span,
    function: u32 = 0,
    operand_base: u32 = 0,
    arguments: u32 = 0,
    value_type: ?types.Type = null,
    head: u32 = no_member,
    tail: u32 = no_member,
    selected: u32 = no_member,
    /// For calls: parameter of each named argument, one nibble per argument after the positional ones.
    names: u64 = 0,
    /// A call that opened with its receiver already in place as the first argument: a method
    /// call (`invoke`) or an extension method call (`call`).
    receiver: bool = false,
    /// For a method call, the declaration that names its parameters and gives their defaults.
    method: u32 = no_member,
    /// On a call: `Name<constructor>(...)` inside an archetype, which yields the field values
    /// that constructor computes instead of an instance. On the archetype's record: such an
    /// entry is next or has just been staged, so no `Field := value` is pending.
    delegation: bool = false,
    /// RFC-0085, I9: on a class archetype, the field with accessors its pending entry gives,
    /// the number under which it marks in `Workspace.accessor_given` the fields it gave (0
    /// while it gave none), and the chain of their values (`Member.field` is the field's index
    /// in `Workspace.accessor_fields`).
    accessor: u32 = no_member,
    accessors: u32 = 0,
    accessor_head: u32 = no_member,
    accessor_tail: u32 = no_member,
    /// RFC-0082, P3.8: on an attempt, the `Token.site` of its `Attempt` when that is the region
    /// of an iteration of a general `For` (`Workspace.forRegion`), zero otherwise.
    for_site: u32 = 0,
    /// RFC-0091 (B3): a `call` of a function declared further down; `function` is its entry in
    /// `runtime_functions.forward`, not a template.
    forward: bool = false,
    /// RFC-0091 (B3): a `call` of the generic function `function` whose type arguments its
    /// arguments give; `bound` is how many value parameters its header declares.
    infer: bool = false,
    bound: u32 = 0,
    fn precedence(self: Operator) u8 {
        return switch (self.kind) {
            .open, .anonymous_capture, .block, .call, .invoke, .recur, .iterate, .iterate_value, .loop, .bind, .conditional, .attempt, .demand, .fail, .exit, .err, .set_value, .set_local_value, .record, .array, .tuple, .option, .map, .lookup, .option_or, .index, .convert, .native_call, .with_field, .with_index, .element_at, .exhaustive, .text_method => 0,
            .logical_or => 1,
            .logical_and => 2,
            .equal, .unequal, .less, .less_equal, .greater, .greater_equal => 3,
            .add, .subtract => 4,
            .multiply, .divide => 5,
            .positive, .negative, .logical_not => 6,
        };
    }
};

// Separate admitted legacy and bundle parser paths: module partition checks
// remain mandatory for bundles without adding per-token work to plain source.
fn Parser(comptime bundled: bool) type {
    return struct {
        const Self = @This();
        workspace: *Workspace,
        cursor: u32 = 0,
        operator_count: u32 = 0,
        operand_count: u32 = 0,
        function: ?functions.Definition = null,
        /// The frame of the function being compiled when that function declares what its body
        /// uses (`useEffect`); null in every other function and at the root.
        inferring: ?u32 = null,
        default_expression: bool = false,
        expected_type: ?types.Type = null,
        control_depth: usize = 0,
        operator_base: u32 = 0,
        operand_base: u32 = 0,
        local_base: u32 = 0,
        generic: ?GenericContext = null,
        /// The node of the `Super` that a method call is about to use, if any.
        super_value: u32 = no_member,
        /// The class whose method body is being compiled. Its function takes the receiver as the
        /// class that introduced the method, so `Self` is narrowed back to this class.
        method_class: ?types.Type = null,
        /// A method body ends at the comma or brace that closes its class member, like a field default.
        member_expression: bool = false,
        /// A member access started the specialization of a generic method (RFC-0081): the parse
        /// continues in the method's body.
        continued: bool = false,
        /// The bound of a metatype is being read: a metatype is not the bound of another.
        in_metatype: bool = false,
        /// The block clauses of a class are being compiled: there is no result to `Return`.
        class_block: bool = false,
        /// Early exit (RFC-0068). A mark is where a `Defer` stood: the locals declared by then and
        /// the block it stood in. While a copy of a `Defer` body is compiled, the locals declared
        /// between its mark and the copy are hidden from it: it means what it meant where written.
        marks: [max_defer_marks]DeferMark = undefined,
        mark_count: u32 = 0,
        hidden: [max_defer_copies]DeferCopy = undefined,
        hidden_count: u32 = 0,
        /// The token after the `)` of the `Return` or `Err` compiled last.
        exit_end: u32 = 0,
        /// The signature of a template is being read only to check it (RFC-0073): its type
        /// parameters stand for placeholder types, so nothing is instantiated for them.
        /// `trial_public` says the template is public, so every type it names must be too.
        trial: bool = false,
        trial_public: bool = false,
        /// The name of the public declaration whose signature is being read.
        trial_name: Span = .{ .start = 0, .end = 0 },
        /// A name written `(e:)Name` is being read as if unqualified, to see whether `e` is an
        /// enum (RFC-0085, I10).
        enum_qualifier: bool = false,
        /// The node that the comparison, `not`, `and` or `or` applied last yielded, and the
        /// operator's token: a statement that leaves exactly that node drops it (`checkDiscarded`).
        /// `depth` is the operator stack when it was applied, less the parentheses that have
        /// closed around it since: the statement itself is the predicate only if nothing but
        /// its block is open then, so the value of an inner block or call is never mistaken.
        /// `pushes` is `operand_pushes` then: a value pushed since (a name, a call) is another
        /// expression, even where it is the same node.
        predicate: struct { node: u32 = no_member, span: Span = .{ .start = 0, .end = 0 }, depth: u32 = 0, pushes: u64 = 0 } = .{},
        /// RFC-0090: the value of the `If` without an else compiled last, and its span: a place
        /// that needs a value of another type, or binds it, reports `if_without_else` for it.
        valueless: struct { node: u32 = no_member, span: Span = .{ .start = 0, .end = 0 }, in_function: bool = false } = .{},
        /// How many operands have been pushed.
        operand_pushes: u64 = 0,
        /// The name of the module binding whose initialiser is being compiled, empty otherwise.
        pending_binding: Span = .{ .start = 0, .end = 0 },
        /// RFC-0084: the type of the cell whose guard comes next, set by the statement that
        /// attaches it and taken by the guard's mark.
        live_guard_type: ?types.Type = null,
        /// RFC-0087, P5.4: `set X[K] = V` of a keyed cell, which the macro pass wrote as
        /// `set X = WithIndex[X, K, V]`: the cell, and the token of that `WithIndex`.
        keyed_set: ?struct { cell: u32, token: u32 } = null,
        /// RFC-0084, P4.3: where the guard being compiled for a function used as a type reads
        /// the raw value (`<raw>`).
        live_raw: ?LiveRaw = null,
        /// Where the type name that was last read as the builtin `void` (RFC-0080) starts: a
        /// declared type of that name is not one. `parseResultType` reads it to tell a result
        /// written `:void` from `:tuple()`.
        void_at: u32 = std.math.maxInt(u32),
        /// What the place of the standard function being emitted expects (`emitStdIn`).
        std_expected: ?types.Type = null,
        /// RFC-0085, I3: the nested functions below this one belong to a parse that an
        /// interruption suspended (`interrupt`), and are not in scope here.
        nested_floor: u32 = 0,
        /// RFC-0085, I4: the source position of the name of the nested function whose header
        /// `checkShadow` is asked about, which may overload the nested functions of its block.
        nested_header: u32 = no_member,

        fn peek(self: *const Self) Token {
            const token = self.rawPeek();
            const w = self.workspace;
            if (bundled and !modules.contains(w.scopeOf(w.current_module), token.span)) return .{ .kind = .eof, .span = .{ .start = w.userEnd(w.current_module), .end = w.userEnd(w.current_module) } };
            // The brace that closes a nested module ends its declarations, as the end of a file does.
            if (bundled and w.current_nested != types.no_parent and token.kind == .right_brace) {
                const end = w.module_storage.nested[w.current_nested].source.end;
                if (token.span.start == end) return .{ .kind = .eof, .span = .{ .start = end, .end = end } };
            }
            return token;
        }
        fn rawPeek(self: *const Self) Token {
            std.debug.assert(self.cursor < self.workspace.token_count);
            return self.workspace.tokens[self.cursor];
        }
        fn take(self: *Self, expected: Token.Kind, code: Diagnostic.Code) ParseError!Token {
            const token = self.peek();
            if (token.kind != expected) return self.workspace.fail(token.span, code);
            self.cursor += 1;
            return token;
        }
        fn parseProgram(self: *Self) ParseError!void {
            const w = self.workspace;
            var root_entered = false;
            try self.reserveClasses();
            while (self.rawPeek().kind != .eof) {
                if (self.rawPeek().kind == .newline or self.rawPeek().kind == .separator) {
                    self.cursor += 1;
                    continue;
                }
                if (bundled and w.current_nested != types.no_parent) {
                    // Inside `Name := module{...}`: its closing brace returns to the scope around it.
                    const next = self.rawPeek();
                    const here = w.module_storage.nested[w.current_nested];
                    if (!modules.contains(w.scopeOf(w.current_module), next.span)) return w.fail(here.name, .unexpected_token);
                    if (next.kind == .right_brace and next.span.start == here.source.end) {
                        self.cursor += 1;
                        w.current_nested = here.parent;
                        const after = self.peek().kind;
                        if (after != .eof and after != .newline and after != .separator) return w.fail(self.peek().span, .unexpected_token);
                        continue;
                    }
                } else if (bundled) {
                    w.current_module = modules.owner(self.rawPeek().span, w.module_storage.modules[0..w.module_storage.module_count]).?;
                    if (!root_entered and w.current_module + 1 == w.module_storage.module_count) {
                        w.root_binding_start = w.binding_count;
                        root_entered = true;
                    }
                }
                if (self.rawPeek().kind == .left_paren) try self.parseExtension() else try self.parseDeclaration();
            }
            if (bundled and w.current_nested != types.no_parent) return w.fail(w.module_storage.nested[w.current_nested].name, .unexpected_token);
            if (bundled and !root_entered) w.root_binding_start = w.binding_count;
            if (bundled) for (0..w.generic_count) |id| {
                const template = w.generic_templates[id];
                // A parametric alias was checked where it is written (`parseAliasTemplate`).
                if (template.kind != .function and template.kind != .alias and template.is_public) try self.checkTemplateTypes(@intCast(id));
            };
            if (bundled and w.module_storage.nested_count != 0) try self.keepRootBindings();
            // Exports observe final mutable state; immutable aliases keep their
            // earlier register. Imported cells remain available through metadata.
            for (w.bindings[w.root_binding_start..w.binding_count], w.binding_cells[w.root_binding_start..w.binding_count]) |*binding, cell| {
                if (cell == std.math.maxInt(u16)) continue;
                // RFC-0087, P5.4 (W8): a keyed cell is never read whole. Its binding stays its
                // `weak_init`, and a report shows the cell's final value.
                if (w.source_cells[cell].keyed != .none) continue;
                binding.node = try self.emit(.{ .span = binding.name, .value_type = binding.value_type, .kind = .{ .cell_read = cell } });
            }
        }
        /// A program publishes the bindings of its root file. Those of the modules nested in that
        /// file were declared among them, and are moved before them: like the bindings of an
        /// imported file, they are reached through the nodes that name them, not reported.
        fn keepRootBindings(self: *Self) ParseError!void {
            const w = self.workspace;
            const start = w.root_binding_start;
            const count = w.binding_count - start;
            const files = w.module_storage.module_count;
            var inner: u32 = 0;
            for (w.binding_scope[start..w.binding_count]) |declared| inner += @intFromBool(declared >= files);
            if (inner == 0) return;
            const saved = scratch.alloc(types.Binding, count) orelse return w.fail(.{ .start = 0, .end = 0 }, .binding_limit);
            defer scratch.free(saved);
            const cells = scratch.alloc(u16, count) orelse return w.fail(.{ .start = 0, .end = 0 }, .binding_limit);
            defer scratch.free(cells);
            @memcpy(saved, w.bindings[start..w.binding_count]);
            @memcpy(cells, w.binding_cells[start..w.binding_count]);
            var low: u32 = start;
            var high: u32 = start + inner;
            // The scopes stay where they were: they are read in the old order and not after this.
            for (saved, cells, w.binding_scope[start..w.binding_count]) |binding, cell, declared| {
                const target = if (declared >= files) &low else &high;
                w.bindings[target.*] = binding;
                w.binding_cells[target.*] = cell;
                target.* += 1;
            }
            std.debug.assert(low == start + inner and high == w.binding_count);
            // The index of bindings by name is not read once every declaration is compiled.
            w.root_binding_start = start + inner;
        }

        /// `<public>`, or `<internal>`: the access a declaration of a module has without either.
        fn moduleAccess(self: *Self) ParseError!bool {
            _ = try self.take(.less, .unsupported_specifier);
            const token = try self.take(.identifier, .unsupported_specifier);
            const text = token.span.text(self.workspace.source);
            const is_public = std.mem.eql(u8, text, "public");
            if (!is_public and !std.mem.eql(u8, text, "internal")) return self.workspace.fail(token.span, .unsupported_specifier);
            _ = try self.take(.greater, .unsupported_specifier);
            return is_public;
        }

        /// `Name := module{ declarations }` (RFC-0074). The module table already has it, found
        /// before parsing; the declarations up to its closing brace are compiled in its scope.
        fn parseModule(self: *Self, index: u32) ParseError!void {
            const w = self.workspace;
            std.debug.assert(w.module_storage.nested[index].parent == w.current_nested);
            _ = try self.take(.colon, .expected_equal);
            _ = try self.take(.equal, .expected_equal);
            _ = try self.take(.identifier, .unexpected_token);
            _ = try self.take(.left_brace, .unexpected_token);
            w.current_nested = index;
        }

        fn parseDeclaration(self: *Self) ParseError!void {
            const w = self.workspace;
            var name = try self.take(.identifier, .expected_name);
            if (std.mem.eql(u8, name.span.text(w.source), "set")) return self.parseSet();
            if (std.mem.eql(u8, name.span.text(w.source), "using")) return self.parseUsing(name);
            const mutable = std.mem.eql(u8, name.span.text(w.source), "var");
            if (mutable) name = try self.take(.identifier, .expected_name);
            // RFC-0084: `var live X:T = G` and `live Y:T = G`; `live` stands before a name.
            const live = std.mem.eql(u8, name.span.text(w.source), "live") and self.peek().kind == .identifier;
            if (live) name = try self.take(.identifier, .expected_name);
            const name_text = name.span.text(w.source);
            // RFC-0053, B5: `ToString` is reserved for every use but one, the name of a function.
            const text_function = std.mem.eql(u8, name_text, "ToString");
            if ((reserved(name_text) and !text_function) or (generatedName(name_text) and w.libraryModule(name.span) == null)) return w.fail(name.span, .expected_name);
            // A declaration of a module is no local (RFC-0083).
            if (w.localQualified(name.span.start)) return w.fail(name.span, .invalid_qualifier);
            // `<constructor>` stands before or after `<public>`.
            const constructor_first = self.constructorSpecifier();
            const is_public = if (self.peek().kind == .less) try self.moduleAccess() else false;
            const is_constructor = constructor_first or self.constructorSpecifier();
            if (text_function and (mutable or live or is_constructor or self.peek().kind != .left_paren)) return w.fail(name.span, .expected_name);
            if (!mutable and self.peek().kind == .colon and w.tokens[self.cursor + 1].kind == .equal and w.tokens[self.cursor + 2].kind == .identifier and std.mem.eql(u8, w.tokens[self.cursor + 2].span.text(w.source), "import")) return self.parseImport(name, is_public);
            if (bundled and w.childModule(w.currentScope(), name_text, name.span.start) != null) return w.fail(name.span, .duplicate_name);
            if (w.findAlias(name_text) != null or w.findSymbol(name_text) != null or (w.findFunction(name_text) != null and self.peek().kind != .left_paren) or (w.findType(name_text) != null and !w.reservedClassAt(name.span)) or (self.peek().kind != .left_paren and w.methodNamed(name_text)) or w.findNativeIn(name_text, w.scope()) != null or w.findTypeAliasIn(name_text, w.scope()) != null or self.findGeneric(name_text, w.scope()) != null) return w.fail(name.span, .duplicate_name);
            // A declaration of a module may not reuse a name of a scope around the module, nor
            // one that a `using` brings in (RFC-0076, D5).
            if (bundled and (w.module_storage.nested_count != 0 or w.using_count != 0)) try self.checkOuterShadow(name);
            w.noteDeclaration(name.span, .global, qualify.none);
            // RFC-0084, P4.3: `In->Out:F = E`, and a variable whose type is a function.
            if (self.arrowAhead()) {
                if (is_constructor) return w.fail(name.span, .unsupported_specifier);
                return self.parseLiveTypePair(name, is_public, mutable, live);
            }
            if (!is_constructor) if (try self.functionTypeAhead()) |form| return self.declareLiveType(null, false, name, is_public, mutable, live, form);
            if (live) return self.parseLiveDeclaration(name, is_public, !mutable);
            if (is_constructor) {
                if (mutable or self.peek().kind != .left_paren) return w.fail(name.span, .unsupported_specifier);
                return self.parseConstructor(name, is_public);
            }
            if (bundled and !mutable) if (w.moduleDeclaredAt(name.span)) |index| return self.parseModule(index);
            if (!mutable and self.peek().kind == .colon and w.tokens[self.cursor + 1].kind == .equal and w.tokens[self.cursor + 2].kind == .identifier and std.mem.eql(u8, w.tokens[self.cursor + 2].span.text(w.source), "native")) return self.parseNative(name, is_public);
            if (!mutable and self.peek().kind == .left_bracket) return self.parseGenericDeclaration(name, is_public, null);
            if (!mutable and self.peek().kind == .left_paren) return self.parseFunction(name, is_public);
            if (!mutable and self.peek().kind == .colon and w.tokens[self.cursor + 1].kind == .equal) {
                if (bundled and self.typePathAhead()) return self.parseDefinition(name, is_public);
                if (self.valueAhead()) return self.parseInferredBinding(name, is_public);
                return self.parseDefinition(name, is_public);
            }
            if (w.binding_count == w.bindings.len) return w.fail(name.span, .binding_limit);
            const value_type = try self.parseType();
            _ = try self.take(.equal, .expected_equal);
            if (mutable and catalogue.keyedKind(value_type, self.definitions()) != .none) return self.declareKeyed(name, value_type, is_public);
            self.pending_binding = name.span;
            const root = try self.coerce(try self.parseExpression(value_type), value_type);
            self.pending_binding = .{ .start = 0, .end = 0 };
            var published = root;
            var cell: ?u32 = null;
            if (mutable) {
                if (w.source_cell_count == w.source_cells.len) return w.fail(name.span, .source_cell_limit);
                cell = w.source_cell_count;
                published = try self.emit(.{ .span = name.span, .value_type = value_type, .kind = .{ .cell_init = .{ .cell = cell.?, .value = root } } });
                w.source_cells[cell.?] = .{ .name = name.span, .value_type = value_type, .initial = published, .is_public = is_public };
                w.source_cell_count += 1;
            }
            w.insertSymbol(.{ .name = name.span, .node = published, .value_type = value_type, .is_public = is_public }, cell);
        }

        /// RFC-0087, P5.4 (W4, W5): `var X:weak_map(session, V) = map{}`, the cursor after the `=`.
        /// The cell is declared by its `weak_init`, which yields the empty map: the initialiser
        /// is checked to be `map{}` and leaves no node.
        fn declareKeyed(self: *Self, name: Token, value_type: types.Type, is_public: bool) ParseError!void {
            const w = self.workspace;
            std.debug.assert(self.function == null);
            // RFC-0087, P5.5 (W7): a persistent cell saves its entries, so its value type is persistable.
            if (catalogue.keyedKind(value_type, self.definitions()) == .persistent) {
                const entry = persistable.persistentValue(value_type, self.definitions()).?;
                if (!w.jsonShape(entry).persistable) return w.fail(name.span, .weak_map_value);
            }
            self.pending_binding = name.span;
            const before = w.node_count;
            const first = self.cursor;
            const root = try self.coerce(try self.parseExpression(value_type), value_type);
            self.pending_binding = .{ .start = 0, .end = 0 };
            const initialiser = self.node(root);
            // Located at the initialiser as written: a name may stand for a node made earlier.
            if (root + 1 != w.node_count or root != before or initialiser.kind != .aggregate or initialiser.kind.aggregate.start != initialiser.kind.aggregate.end) return w.fail(.{ .start = w.tokens[first].span.start, .end = w.tokens[self.cursor - 1].span.end }, .weak_map_initializer);
            // The empty literal was the last node, and nothing names it.
            w.node_count -= 1;
            if (w.source_cell_count == w.source_cells.len) return w.fail(name.span, .source_cell_limit);
            const cell = w.source_cell_count;
            // The cell is known before its declaration is emitted, which `assertNode` checks.
            w.source_cells[cell] = .{ .name = name.span, .value_type = value_type, .initial = w.node_count, .is_public = is_public, .keyed = catalogue.keyedKind(value_type, self.definitions()) };
            const published = try self.emit(.{ .span = name.span, .value_type = value_type, .kind = .{ .weak_init = cell } });
            std.debug.assert(published == w.source_cells[cell].initial);
            w.source_cell_count += 1;
            w.insertSymbol(.{ .name = name.span, .node = published, .value_type = value_type, .is_public = is_public }, cell);
        }
        /// RFC-0087, P5.4: the keyed cell a name means, null when it means anything else. A
        /// local or a parameter of the name comes first, as for every module name.
        fn keyedCell(self: *const Self, name: Name) ?u32 {
            const w = self.workspace;
            const text = name.token.span.text(w.source);
            if (!name.qualified and (self.findLocal(text) != null or self.parameter(text) != null)) return null;
            const binding = w.findSymbolIn(text, name.scope) orelse return null;
            const cell = w.binding_cells[binding];
            if (cell == std.math.maxInt(u16) or w.source_cells[cell].keyed == .none) return null;
            return cell;
        }
        /// The checks a use of the keyed cell `name` means passes, as for every module cell.
        fn keyedAccess(self: *Self, name: Name) ParseError!void {
            const w = self.workspace;
            const binding = w.findSymbolIn(name.token.span.text(w.source), name.scope).?;
            if (!self.visible(w.bindings[binding].name)) return w.fail(name.span, .unknown_name);
            if (name.sealed() and !w.bindings[binding].is_public) return w.fail(name.span, .private_name);
            w.noteName(name.token.span, w.bindings[binding].name.start, .global, qualify.none);
        }
        /// `set X[K] = V` of the keyed cell `cell` named `name`, the cursor at the `=`: the macro
        /// pass wrote it `set X = WithIndex[X, K, V]`, and every nested or compound update of an
        /// entry the same way. Anything else assigns the cell whole (`weak_map_whole`).
        fn startKeyedSet(self: *Self, name: Name, cell: u32) ParseError!void {
            const w = self.workspace;
            try self.keyedAccess(name);
            const at = self.cursor;
            // `set M.X[K] = V` through a qualified name is no form for any cell yet: the macro
            // pass rewrites only a path that starts with a plain name. It is refused as an
            // ordinary cell's is, at the `[`.
            if (name.qualified and at < w.token_count and w.tokens[at].kind == .left_bracket) return w.fail(w.tokens[at].span, .expected_equal);
            if (at + 4 >= w.token_count or w.tokens[at].kind != .equal or w.tokens[at + 1].kind != .synthetic_with_index or w.tokens[at + 2].kind != .left_bracket or w.tokens[at + 3].kind != .identifier or !std.meta.eql(w.tokens[at + 3].span, name.token.span) or w.tokens[at + 4].kind != .comma) return w.fail(name.span, .weak_map_whole);
            try self.stateEffect(name.span, .set);
            self.keyed_set = .{ .cell = cell, .token = @intCast(at + 1) };
        }
        /// A read, a `set` or a construction needs its heap effect declared by the function it is
        /// in (RFC-0078). A module's own initialisers run once, in order, and may do all three.
        fn stateEffect(self: *Self, span: Span, comptime use: StateUse) ParseError!void {
            const function = self.function orelse return;
            const have = Effect.of(function).set();
            self.useEffect(switch (use) {
                .variable_read, .field_read, .local_read => .{ .reads = true, .diverges = false },
                .set, .local_var => .{ .writes = true, .diverges = false },
                .construction => .{ .allocates = true, .diverges = false },
            });
            switch (use) {
                .variable_read => if (!have.reads) return self.effectFailure(span, .variable_read_requires_reads),
                .field_read => if (!have.reads) return self.effectFailure(span, .field_read_requires_reads),
                .set => if (!have.writes) return self.effectFailure(span, .set_requires_writes),
                .construction => if (!have.allocates) return self.effectFailure(span, .construction_requires_allocates),
                .local_var => if (!have.writes) return self.effectFailure(span, .local_var_requires_writes),
                // RFC-0085, S6: another function can change a shared local.
                .local_read => if (!have.reads) return self.effectFailure(span, .local_read_requires_reads),
            }
        }
        /// Whether the code being compiled is a live guard's (RFC-0084): the guard itself, or a
        /// function a macro wrote for a loop inside it. A function the program writes in a guard
        /// is a function of its own, with its own effect.
        fn inGuard(self: *const Self) bool {
            if (self.function == null) return false;
            const w = self.workspace;
            var index = w.anonymous_count;
            while (index != 0) {
                index -= 1;
                const frame = &w.anonymous_frames[index];
                if (frame.phase != .body) continue;
                if (frame.guard_body) return true;
                if (w.libraryModule(frame.definition.name) == null) return false;
            }
            return false;
        }
        /// An effect the code lacks: in a guard it is the guard's, which may only read.
        fn effectFailure(self: *Self, span: Span, code: Diagnostic.Code) ParseError {
            return self.workspace.fail(span, if (self.inGuard()) .guard_effect else code);
        }
        /// The diagnostic naming the first effect of `need` that `have` lacks, in the order
        /// reads, writes, allocates, decides, suspends; null when `need` lies within `have`.
        fn missingEffect(need: types.EffectSet, have: types.EffectSet, comptime codes: [5]?Diagnostic.Code) ?Diagnostic.Code {
            if (need.reads and !have.reads) return codes[0];
            if (need.writes and !have.writes) return codes[1];
            if (need.allocates and !have.allocates) return codes[2];
            if (need.decides and !have.decides) return codes[3];
            if (need.suspends and !have.suspends) return codes[4];
            return null;
        }
        const override_codes = [5]?Diagnostic.Code{ .override_widens_reads, .override_widens_writes, .override_widens_allocates, .override_widens_decides, .override_widens_suspends };
        const narrower_codes = [5]?Diagnostic.Code{ .class_effect_narrower_reads, .class_effect_narrower_writes, .class_effect_narrower_allocates, null, null };
        const required_codes = [5]?Diagnostic.Code{ .class_effect_required_reads, .class_effect_required_writes, .class_effect_required_allocates, null, null };
        const struct_codes = [5]?Diagnostic.Code{ .struct_effect_required_reads, .struct_effect_required_writes, .struct_effect_required_allocates, null, null };
        /// A call needs every heap effect of what it calls, and a `<suspends>` function is called
        /// only from one, outside every failure context and `Defer`. Whether a failable call
        /// stands in a failure context is checked where its brackets are read.
        fn callEffect(self: *Self, span: Span, callee: types.EffectSet) ParseError!void {
            const w = self.workspace;
            if (callee.suspends) {
                const function = self.function orelse return w.fail(span, .call_requires_suspends);
                if (!function.detail.suspends) if (self.bodyBarred()) |code| return w.fail(span, code);
                // The filter of an RFC-0056 `For` is the condition of an `If` (P3.8).
                if (!function.detail.suspends and self.filterBody()) return w.fail(span, .suspends_in_failure_context);
                // RFC-0082, P3.8: a loop function in an iteration of a general `For` was not given
                // `suspends`. Once the calls around it are noted the next compile gives it, so
                // this one goes on, as below, but writes no check at such a site (`checkSite`),
                // and a form that compiles functions of its own ends it (`suspendingForm`).
                if (!function.detail.suspends and !self.noteSuspendingFor()) return self.effectFailure(span, .call_requires_suspends);
                // P3.8: inside the region of an iteration of a general `For` and no other, the
                // site is noted; the next compile lowers that `For` without its regions, and this
                // one goes on as if it had, so that one more compile notes every such loop.
                if (self.suspensionBarred() and !self.noteSuspendingFor()) return w.fail(span, .suspends_in_failure_context);
                // Only the body of a `For` without regions may suspend: its clauses stay what
                // the condition of an `If` is in the forms of RFC-0056 (P3.8).
                if (w.suspend_clause_count != 0) if (w.suspendClause(span)) |clause| if (!clause.body) return w.fail(span, .suspends_in_failure_context);
                // A site in the body of a filtered RFC-0056 `For` sends that call to the general
                // lowering without regions from the next compile on, where its filter may not
                // fail either (C128); this compile goes on and is not used.
                if (self.filteredForBody()) |start| _ = w.noteSuspended(start);
            }
            const function = self.function orelse return;
            const have = Effect.of(function).set();
            self.useEffect(callee.heap());
            // The diagnostic names every heap effect the call needs and the function lacks.
            const reads = callee.reads and !have.reads;
            const writes = callee.writes and !have.writes;
            const allocates = callee.allocates and !have.allocates;
            if (reads and writes and allocates) return self.effectFailure(span, .call_requires_transacts);
            if (reads and writes) return self.effectFailure(span, .call_requires_reads_writes);
            if (reads and allocates) return self.effectFailure(span, .call_requires_reads_allocates);
            if (writes and allocates) return self.effectFailure(span, .call_requires_writes_allocates);
            if (reads) return self.effectFailure(span, .call_requires_reads);
            if (writes) return self.effectFailure(span, .call_requires_writes);
            if (allocates) return self.effectFailure(span, .call_requires_allocates);
            // RFC-0085, I12: a `<predicts>` function calls only what predicts.
            if (callee.dictates and !have.dictates) return w.fail(span, .call_requires_dictates);
        }
        /// Whether the code being compiled predicts (RFC-0085, I12): a function declared
        /// `<predicts>`, or a closure or loop function that inherits it. The root dictates.
        fn predicting(self: *const Self) bool {
            const function = self.function orelse return false;
            return function.detail.predicts;
        }
        /// RFC-0085, I12: live state is authoritative; `set live`, `Upon`, `When`, `Await(G)`
        /// and `Batch{}` dictate, and their guard and body types are fixed without the bit.
        fn liveForm(self: *const Self, span: Span) ParseError!void {
            if (self.predicting()) return self.workspace.fail(span, .form_requires_dictates);
        }
        /// RFC-0085, I12: whether template nodes `start..end` (a default's, expanded where it is
        /// used) run something that dictates, by admission rule 9.
        fn dictatingTemplate(self: *const Self, start: u32, end: u32) bool {
            const w = self.workspace;
            const nodes = w.functions.nodes[start..end];
            for (nodes) |entry| if (entry.input == .operation and self.dictatingNode(entry.node, w.functions.nodes[0..end])) return true;
            return false;
        }
        /// Whether `node` runs code that dictates (admission rule 9); `prior` are the nodes its
        /// operands index, templates or the function's own.
        fn dictatingNode(self: *const Self, item: types.Node, prior: []const functions.Template) bool {
            const w = self.workspace;
            const operand: u32 = switch (item.kind) {
                .call => |c| return w.runtime_functions.signature(c.function).effects().dictates,
                .iterate => |i| return w.runtime_functions.definitions[i.function].effects().dictates,
                .native_call => |c| return native.dictates(w.natives[c.native]),
                .cell_live, .object_live, .reaction, .batch, .await_guard, .event_notify => return true,
                .invoke => |i| i.callable,
                .loop => |l| l.callable,
                .iterate_value => |i| i.callable,
                .spawn => |n| n,
                .branch => |n| n,
                .structured => |c| {
                    for (w.functions.arguments[c.arms.start..c.arms.end]) |arm| if (self.closureDictates(prior[arm].node.value_type)) return true;
                    return false;
                },
                else => return false,
            };
            return self.closureDictates(prior[operand].node.value_type);
        }
        fn closureDictates(self: *const Self, value_type: types.Type) bool {
            const shape = catalogue.definition(value_type, self.definitions()) orelse return true;
            return shape != .callable or shape.callable.effects().dictates;
        }
        /// RFC-0085, I12: the body of a predicting function holds nothing that dictates. Every
        /// form checks this where it is written; this is the last word, so that what the
        /// compiler hands on is never refused by rule 9 of the admissions.
        fn checkPredicting(self: *Self, function: functions.Definition) ParseError!void {
            if (!function.detail.predicts) return;
            const w = self.workspace;
            for (w.functions.nodes[function.start..function.end]) |entry| if (entry.input == .operation and self.dictatingNode(entry.node, w.functions.nodes[0..function.end])) return w.fail(entry.node.span, .call_requires_dictates);
        }
        /// An effect native acts on the world or draws from it (RFC-0079): the function that
        /// calls it declares `<transacts>`, all three heap effects, as for a call of a
        /// `<transacts>` function (RFC-0078). Root code may.
        fn nativeEffect(self: *Self, span: Span) ParseError!void {
            return self.callEffect(span, .{ .reads = true, .writes = true, .allocates = true, .diverges = false, .dictates = false });
        }
        /// Whether a suspension here would fall inside what must finish at once: an `Attempt`
        /// body, a condition, an `option{...}` or deferred code. It asks without deciding
        /// anything, unlike `failureContext`.
        fn suspensionBarred(self: *const Self) bool {
            var index = self.operator_count;
            while (index > self.operator_base) {
                index -= 1;
                const op = self.workspace.operators[index];
                // A test that forges IR keeps the regions of iterations and lets sites stand in them.
                if (op.kind == .attempt and op.for_site != 0 and self.workspace.for_regions_kept) continue;
                if ((op.kind == .attempt or op.kind == .conditional) and op.arguments == 0) return true;
                if (op.kind == .option and op.names == open_option) return true;
                if (op.kind == .block and self.deferredBlock(index)) return true;
            }
            return false;
        }
        /// RFC-0082, P3.8: a site stands here, where it may not. If what keeps it out is only the
        /// regions of iterations of general `For` calls, those calls are noted (`for_suspended`)
        /// and the result is true: lowered without regions, they let it stand. Those regions are
        /// the barriers of this function, then, while the function lacks `suspends`, those of the
        /// function around it at the place its `Fn` stands, for as long as that is a loop function
        /// the macro pass wrote: such a function inherits `suspends` unless a barrier withholds it
        /// (`inheritedEffect`). Any other barrier, or a function that never had `suspends` to
        /// inherit, leaves the refusal as it was, and nothing is noted.
        fn noteSuspendingFor(self: *Self) bool {
            const w = self.workspace;
            const start = w.for_suspended_count + w.for_suspended_pending;
            var function = self.function orelse return false;
            var found = self.forBarriers(self.operator_base, self.operator_count) orelse return self.dropSuspending(start);
            var index = w.anonymous_count;
            while (!function.detail.suspends) {
                // The frame of `function`: the innermost one whose body is being read.
                while (index != 0 and w.anonymous_frames[index - 1].phase != .body) index -= 1;
                if (index == 0) return self.dropSuspending(start);
                index -= 1;
                const frame = &w.anonymous_frames[index];
                if (frame.kind != .anonymous or w.libraryModule(frame.definition.name) == null) return self.dropSuspending(start);
                found = self.forBarriers(frame.operator_base, frame.operators) orelse return self.dropSuspending(start);
                function = frame.parent_function orelse return self.dropSuspending(start);
                // A function that suspends gave this one nothing only because of a barrier.
                if (function.detail.suspends and found == 0) return self.dropSuspending(start);
            }
            if (w.for_suspended_count + w.for_suspended_pending == start and found == 0) return false;
            return true;
        }
        /// Notes the call of every region of a `For` iteration among the barriers of operators
        /// `from..to`, and gives how many barriers there are; null if one is anything else.
        fn forBarriers(self: *Self, from: u32, to: u32) ?u32 {
            const w = self.workspace;
            var found: u32 = 0;
            var index = to;
            while (index > from) {
                index -= 1;
                const op = w.operators[index];
                const barrier = ((op.kind == .attempt or op.kind == .conditional) and op.arguments == 0) or (op.kind == .option and op.names == open_option) or (op.kind == .block and self.deferredBlock(index));
                if (!barrier) continue;
                if (op.kind != .attempt or op.for_site == 0) return null;
                if (!w.noteSuspended(op.for_site - 1)) return null;
                found += 1;
            }
            return found;
        }
        /// A form whose arms or body are functions that suspend stands where `callEffect` let it:
        /// in a function that suspends, or (P3.8) in a loop function a noted `For` kept from
        /// suspending. There this compile, which is not used, goes on as at any site: its arms and
        /// body suspend as theirs, and `checkSite` writes no check after the form.
        fn suspendingForm(self: *Self, span: Span) ParseError!void {
            _ = span;
            if (self.function.?.detail.suspends) return;
            std.debug.assert(self.workspace.for_suspended_pending != 0);
        }
        /// Whether the innermost function is the filter of an RFC-0056 `For` (P3.8) in code that
        /// suspends, where it would have inherited `suspends`: a site in it is one in a
        /// condition. Elsewhere such a site is refused as one in code that does not suspend.
        fn filterBody(self: *const Self) bool {
            const w = self.workspace;
            if (self.function == null or w.anonymous_count == 0) return false;
            const frame = &w.anonymous_frames[w.anonymous_count - 1];
            if (frame.phase != .body or !frame.filter) return false;
            const around = frame.parent_function orelse return false;
            return around.detail.suspends;
        }
        /// The keyword of the filtered RFC-0056 `For` whose body is the innermost function, as
        /// `Workspace.noteSuspended` takes it (P3.8). Its loop's visit calls the body, which is
        /// a site whether the body holds one or not, so only the body's own sites count.
        fn filteredForBody(self: *const Self) ?u32 {
            const w = self.workspace;
            if (self.function == null or w.anonymous_count == 0) return null;
            const frame = &w.anonymous_frames[w.anonymous_count - 1];
            if (frame.phase != .body or !frame.for_body or frame.for_call == no_member) return null;
            const call = w.for_calls[frame.for_call];
            return if (call.filtered) call.span.start else null;
        }
        /// Takes back what a refused `noteSuspendingFor` noted.
        fn dropSuspending(self: *Self, start: u32) bool {
            const w = self.workspace;
            w.for_suspended_pending = start - w.for_suspended_count;
            return false;
        }
        fn mutableTarget(self: *Self, name: Name) ParseError!u32 {
            const w = self.workspace;
            // A `Spawn` captures by value: what it captured is a copy (RFC-0082).
            if (!name.qualified and self.findLocal(name.token.span.text(w.source)) == null) if (self.capturedBy(name.token.span.text(w.source))) |code| return w.fail(name.span, code);
            if (!name.qualified and (self.findLocal(name.token.span.text(w.source)) != null or self.parameter(name.token.span.text(w.source)) != null)) return w.fail(name.span, .not_mutable);
            const binding = w.findSymbolIn(name.token.span.text(w.source), name.scope) orelse return w.fail(name.span, .unknown_name);
            if (!self.visible(w.bindings[binding].name)) return w.fail(name.span, .unknown_name);
            if (name.sealed() and !w.bindings[binding].is_public) return w.fail(name.span, .private_name);
            w.noteName(name.token.span, w.bindings[binding].name.start, .global, qualify.none);
            var cell: u32 = w.binding_cells[binding];
            if (cell == std.math.maxInt(u16)) return w.fail(name.span, .not_mutable);
            // RFC-0087, P5.4 (W5): a keyed cell is set one key at a time (`startKeyedSet`).
            if (w.source_cells[cell].keyed != .none) return w.fail(name.span, .weak_map_whole);
            // A variable whose type is a function is assigned its raw value (RFC-0084, P4.3),
            // which the immutable forms never are.
            if (w.live_type_count != 0) if (self.liveTypeOfCell(cell)) |entry| {
                if (entry.fixed) return w.fail(name.span, .live_assigned);
                cell = entry.raw;
            };
            // Only its guard writes a live-only cell (RFC-0084).
            if (w.source_cells[cell].live_only) return w.fail(name.span, .live_assigned);
            try self.stateEffect(name.span, .set);
            return cell;
        }
        /// Whether this assignment is the rewrite of `set Object.Field = e` on a name that cannot itself
        /// be assigned: the update happens inside the instance and nothing is stored back.
        fn updatesInstance(self: *Self, name: Name) bool {
            const w = self.workspace;
            if (self.peek().kind != .equal) return false;
            const next = w.tokens[self.cursor + 1].kind;
            if (next != .synthetic_with_field and next != .synthetic_with_index) return false;
            const text = name.token.span.text(w.source);
            if (!name.qualified) {
                if (self.findLocal(text)) |id| return !w.locals[id].mutable and !w.locals[id].shared;
                // A cell a closure captured is assigned, unless the closure is a form that may not
                // assign it (a guard): there, as without the share, the statement updates the instance.
                if (self.parameter(text)) |index| return !catalogue.isRef(self.function.?.parameters[index].value_type, self.definitions()) or self.capturedBy(text) != null;
            }
            const binding = w.findSymbolIn(text, name.scope) orelse return false;
            return w.binding_cells[binding] == std.math.maxInt(u16);
        }
        /// `var live X:T = G` or, `live_only`, `live Y:T = G` (RFC-0084): the cell is declared by
        /// the `cell_live` that attaches its guard and gives it its first value.
        fn parseLiveDeclaration(self: *Self, name: Token, is_public: bool, live_only: bool) ParseError!void {
            const w = self.workspace;
            if (w.binding_count == w.bindings.len) return w.fail(name.span, .binding_limit);
            if (self.peek().kind != .colon or w.tokens[self.cursor + 1].kind == .equal) return w.fail(self.peek().span, .expected_type);
            const value_type = try self.parseType();
            _ = try self.take(.equal, .expected_equal);
            // RFC-0087, P5.4: a guard would give a keyed cell its value whole.
            if (catalogue.keyedKind(value_type, self.definitions()) != .none) return w.fail(name.span, .weak_map_whole);
            _ = w.catalogue.internLive(value_type) catch |err| return w.fail(name.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            self.pending_binding = name.span;
            self.live_guard_type = value_type;
            const guard = try self.parseExpression(value_type);
            self.pending_binding = .{ .start = 0, .end = 0 };
            try self.takeGuard(guard, value_type);
            if (w.source_cell_count == w.source_cells.len) return w.fail(name.span, .source_cell_limit);
            const cell = w.source_cell_count;
            const published = try self.emit(.{ .span = name.span, .value_type = value_type, .kind = .{ .cell_live = .{ .cell = cell, .guard = guard, .initialize = true } } });
            w.source_cells[cell] = .{ .name = name.span, .value_type = value_type, .initial = published, .is_public = is_public, .live_only = live_only };
            w.source_cell_count += 1;
            w.insertSymbol(.{ .name = name.span, .node = published, .value_type = value_type, .is_public = is_public }, cell);
        }
        /// The guard the statement asked for was compiled where it stood, and is `guard`.
        fn takeGuard(self: *Self, guard: u32, value_type: types.Type) ParseError!void {
            const w = self.workspace;
            if (self.live_guard_type != null) {
                self.live_guard_type = null;
                return w.fail(self.node(guard).span, .expected_expression);
            }
            const shape = catalogue.definition(self.node(guard).value_type, self.definitions()) orelse return w.fail(self.node(guard).span, .type_mismatch);
            if (shape != .callable or shape.callable.result != value_type) return w.fail(self.node(guard).span, .type_mismatch);
        }
        /// The module cell `set live` attaches a guard to (RFC-0084): a module `var`. A local, a
        /// parameter, an immutable binding, a field or an element is no target, and a live-only
        /// cell is never assigned.
        fn liveTarget(self: *Self, name: Name) ParseError!u32 {
            const w = self.workspace;
            const text = name.token.span.text(w.source);
            if (self.peek().kind != .equal) return w.fail(name.span, .live_target);
            if (!name.qualified and (self.findLocal(text) != null or self.parameter(text) != null or self.capturedBy(text) != null)) return w.fail(name.span, .live_target);
            const binding = w.findSymbolIn(text, name.scope) orelse return w.fail(name.span, .unknown_name);
            if (!self.visible(w.bindings[binding].name)) return w.fail(name.span, .unknown_name);
            if (name.sealed() and !w.bindings[binding].is_public) return w.fail(name.span, .private_name);
            w.noteName(name.token.span, w.bindings[binding].name.start, .global, qualify.none);
            const cell = w.binding_cells[binding];
            if (cell == std.math.maxInt(u16)) return w.fail(name.span, .live_target);
            // RFC-0087, P5.4 (W5): a guard would write a keyed cell whole.
            if (w.source_cells[cell].keyed != .none) return w.fail(name.span, .weak_map_whole);
            if (w.source_cells[cell].live_only) return w.fail(name.span, .live_assigned);
            // The raw value of an immutable form is never assigned (RFC-0084, P4.3).
            if (w.live_type_count != 0) if (self.liveTypeOfCell(cell)) |entry| if (entry.fixed) return w.fail(name.span, .live_assigned);
            // It evaluates a guard, writes the cell and builds a record: all three heap effects.
            try self.liveForm(name.span);
            try self.callEffect(name.span, .{ .reads = true, .writes = true, .allocates = true, .diverges = false });
            _ = w.catalogue.internLive(w.source_cells[cell].value_type) catch |err| return w.fail(name.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            return cell;
        }
        /// `set live X = G` (RFC-0084) among a module's declarations.
        fn parseSetLive(self: *Self) ParseError!void {
            const w = self.workspace;
            const name = try self.resolveName(try self.take(.identifier, .expected_name));
            const cell = try self.liveTarget(name);
            const value_type = w.source_cells[cell].value_type;
            _ = try self.take(.equal, .expected_equal);
            self.live_guard_type = value_type;
            const guard = try self.parseExpression(value_type);
            try self.takeGuard(guard, value_type);
            _ = try self.emit(.{ .span = name.span, .value_type = value_type, .kind = .{ .cell_live = .{ .cell = cell, .guard = guard, .initialize = false } } });
        }
        fn parseSet(self: *Self) ParseError!void {
            if (self.peek().kind == .identifier and std.mem.eql(u8, self.peek().span.text(self.workspace.source), "live") and self.workspace.tokens[self.cursor + 1].kind == .identifier) {
                self.cursor += 1;
                return self.parseSetLive();
            }
            // `set live E.F = G` (RFC-0084, P4.2), which the macro pass made one expression.
            if (self.peek().kind == .identifier and std.mem.eql(u8, self.peek().span.text(self.workspace.source), "live") and self.workspace.tokens[self.cursor + 1].kind == .synthetic_live_field) {
                self.cursor += 1;
                _ = try self.parseExpression(null);
                return;
            }
            const token = try self.take(.identifier, .expected_name);
            const name = try self.resolveName(token);
            if (self.updatesInstance(name)) {
                _ = try self.take(.equal, .expected_equal);
                const before = self.workspace.class_updates;
                _ = try self.parseExpression(null);
                if (self.workspace.class_updates == before) return self.workspace.fail(name.span, .not_mutable);
                return;
            }
            // RFC-0087, P5.4: `set X[K] = V` of a keyed cell is its `weak_set`, and writes nothing else.
            if (self.keyedCell(name)) |keyed| {
                try self.startKeyedSet(name, keyed);
                _ = try self.take(.equal, .expected_equal);
                const written = try self.parseExpression(null);
                if (self.keyed_set != null or self.node(written).kind != .weak_set) return self.workspace.fail(name.span, .weak_map_whole);
                return;
            }
            const cell = try self.mutableTarget(name);
            const value_type = self.workspace.source_cells[cell].value_type;
            _ = try self.take(.equal, .expected_equal);
            const value = try self.coerce(try self.parseExpression(value_type), value_type);
            _ = try self.emit(.{ .span = name.span, .value_type = value_type, .kind = .{ .cell_write = .{ .cell = cell, .value = value } } });
        }

        /// Whether `->` follows (RFC-0084, P4.3): the two names of `In->Out:F = E`.
        fn arrowAhead(self: *const Self) bool {
            const w = self.workspace;
            const minus = self.peek();
            const greater = w.tokens[self.cursor + 1];
            return minus.kind == .minus and greater.kind == .greater and minus.span.end == greater.span.start;
        }
        /// `In->Out:F = E` among a module's declarations (RFC-0084, P4.3), the cursor at the
        /// arrow: `In` and its access were read.
        fn parseLiveTypePair(self: *Self, raw: Token, raw_public: bool, mutable: bool, live: bool) ParseError!void {
            const w = self.workspace;
            self.cursor += 2;
            const out = try self.take(.identifier, .expected_name);
            const text = out.span.text(w.source);
            if (reserved(text) or generatedName(text)) return w.fail(out.span, .expected_name);
            if (w.localQualified(out.span.start)) return w.fail(out.span, .invalid_qualifier);
            if (std.mem.eql(u8, text, raw.span.text(w.source))) return w.fail(out.span, .duplicate_name);
            const out_public = if (self.peek().kind == .less) try self.moduleAccess() else false;
            if (bundled and w.childModule(w.currentScope(), text, out.span.start) != null) return w.fail(out.span, .duplicate_name);
            if (w.findAlias(text) != null or w.findSymbol(text) != null or w.findFunction(text) != null or w.findType(text) != null or w.methodNamed(text) or w.findNativeIn(text, w.scope()) != null or w.findTypeAliasIn(text, w.scope()) != null or self.findGeneric(text, w.scope()) != null) return w.fail(out.span, .duplicate_name);
            if (bundled and (w.module_storage.nested_count != 0 or w.using_count != 0)) try self.checkOuterShadow(out);
            w.noteDeclaration(out.span, .global, qualify.none);
            const form = (try self.functionTypeAhead()) orelse return w.fail(self.typeAfterColon(), .live_type_form);
            return self.declareLiveType(raw, raw_public, out, out_public, mutable, live, form);
        }
        /// Where the type of `In->Out:T` is written, which is no function (RFC-0084, P4.3): after
        /// the colon and the guard the macro pass put before it, or the token at the cursor.
        fn typeAfterColon(self: *const Self) Span {
            const w = self.workspace;
            if (self.peek().kind != .colon) return self.peek().span;
            var at = self.cursor + 1;
            if (w.tokens[at].kind == .synthetic_live_type) at = @intCast(w.segmentClose(at + 1) + 2);
            return w.tokens[at].span;
        }
        /// A function used as a type (RFC-0084, P4.3): the guard the macro pass wrote before the
        /// type (`desugarLiveTypes`), where the type as written lies, and the function's one
        /// parameter type and its result.
        const FunctionType = struct { group: u32, path: Span, parameter: types.Type, result: types.Type };
        /// The type of a declaration, the cursor at its colon, when it is a function used as a
        /// type (RFC-0084, P4.3): the cursor is then after the type. Null, the cursor unmoved, when
        /// the type is a type.
        fn functionTypeAhead(self: *Self) ParseError!?FunctionType {
            const w = self.workspace;
            if (self.peek().kind != .colon or w.tokens[self.cursor + 1].kind != .synthetic_live_type) return null;
            const colon = self.cursor;
            self.cursor += 1;
            const form = try self.liveTypeAt();
            if (form == null) self.cursor = colon;
            return form;
        }
        /// The same, the cursor at the guard: after the type when it names a function or a
        /// method path, which is checked; at the type, after the guard, when it is a type.
        /// Not inlined: the declarations of every program pass by its callers, which keep their
        /// frames, and only a program that marks one calls it.
        noinline fn liveTypeAt(self: *Self) ParseError!?FunctionType {
            const w = self.workspace;
            const group = self.cursor;
            std.debug.assert(w.tokens[group].kind == .synthetic_live_type);
            const close = w.segmentClose(group + 1);
            std.debug.assert(w.tokens[close + 1].kind == .synthetic_live_end);
            const head: u32 = @intCast(close + 2);
            var last = head;
            while (w.tokens[last + 1].kind == .dot and w.tokens[last + 2].kind == .identifier) last += 2;
            const path: Span = .{ .start = w.tokens[head].span.start, .end = w.tokens[last].span.end };
            self.cursor = head + 1;
            const found = (try self.liveCallable(try self.resolveTypeName(w.tokens[head]), path)) orelse {
                self.cursor = head;
                return null;
            };
            const shape = catalogue.definition(found.callable, self.definitions()).?.callable;
            const parameters = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
            const skip: u32 = @intFromBool(found.receiver);
            const effects = shape.effects();
            // `F(Mult)` is a call that makes a function, not a function (Book 15:824).
            if (parameters.end - parameters.start != 1 + skip or shape.decides or effects.suspends or effects.writes or effects.allocates) return w.fail(path, .live_type_form);
            switch (self.peek().kind) {
                .equal => {},
                .newline, .separator, .eof, .right_brace, .comma => return w.fail(path, .live_initializer),
                else => return w.fail(path, .live_type_form),
            }
            return .{ .group = group, .path = path, .parameter = w.catalogue.tuple_elements[parameters.start + skip], .result = shape.result };
        }
        const LiveCallable = struct { callable: types.Type, receiver: bool };
        /// What the type `name`, read with the cursor after it, names when it is a function used
        /// as a type: a function of the program, or a method through a binding and its fields
        /// (`Bounds.Apply`, which takes its receiver first). Null when it names a type, or
        /// nothing such a type could be; a value, a call or a generic function is no such type.
        fn liveCallable(self: *Self, name: Name, path: Span) ParseError!?LiveCallable {
            const w = self.workspace;
            const text = name.token.span.text(w.source);
            if (self.typeNamed(name)) return null;
            if (w.functions.findIn(text, w.source, name.scope)) |index| {
                const f = w.functions.definitions[index];
                if (f.is_extension) return null;
                if (f.overloaded or self.peek().kind == .dot) return w.fail(path, .live_type_form);
                return .{ .callable = try self.functionType(f, name.span), .receiver = false };
            }
            if (self.findGeneric(text, name.scope)) |id| if (w.generic_templates[id].kind == .function) return w.fail(path, .live_type_form);
            const binding = w.findSymbolIn(text, name.scope) orelse return null;
            var base = w.bindings[binding].value_type;
            while (self.peek().kind == .dot and w.tokens[self.cursor + 1].kind == .identifier) {
                self.cursor += 1;
                const member = try self.take(.identifier, .expected_field);
                const member_text = member.span.text(w.source);
                const shape = catalogue.definition(base, self.definitions()) orelse break;
                if (shape == .record) {
                    const field = catalogue.findField(base, member_text, self.definitions(), self.fields(), w.source) orelse break;
                    base = catalogue.fieldAt(base, field, self.definitions(), self.fields()).?.value_type;
                    continue;
                }
                if (shape != .class) break;
                if (catalogue.findField(base, member_text, self.definitions(), self.fields(), w.source)) |field| {
                    base = catalogue.classFieldAt(base, field, self.definitions(), self.fields()).?.value_type;
                    continue;
                }
                const slot = w.findMethod(base, member_text) orelse break;
                if (w.slot_kind[slot] != .method or self.peek().kind == .dot) break;
                return .{ .callable = w.slots[slot].callable, .receiver = true };
            }
            return w.fail(path, .live_type_form);
        }
        /// Whether `name`, in a type position, names a type (RFC-0084, P4.3): what `namedType`
        /// finds before anything else. A function or a value of that name yields to it.
        fn typeNamed(self: *Self, name: Name) bool {
            const w = self.workspace;
            const text = name.token.span.text(w.source);
            if (w.findTypeAliasIn(text, name.scope) != null) return true;
            if (!name.qualified) {
                if (self.genericType(text) != null or self.genericParameter(text)) return true;
                if (std.meta.stringToEnum(types.Type, text) != null or Workspace.characterType(text) != null or std.mem.eql(u8, text, "rational")) return true;
                // So do the standard names of types, which a declaration of the name makes no
                // type at all (RFC-0077): `void`, `any`, `comparable`, `type` and the metatypes.
                for ([_][]const u8{ "void", "any", "comparable", "type" }) |standard| if (std.mem.eql(u8, text, standard)) return true;
                if (MetaKind.named(text) != null) return true;
            }
            if (self.findGeneric(text, name.scope)) |id| if (w.generic_templates[id].kind != .function) return true;
            if (w.catalogue.findNamedIn(text, w.source, name.scope) != null) return true;
            return w.late_count != 0 and w.lateIn(text, w.scopeNamed(name.scope)) != null;
        }
        /// Declares a variable whose type is a function, at the module's root (RFC-0084, P4.3,
        /// L8), the cursor at the `=` after the type: the raw cell `In` (named, or hidden when
        /// `raw` is null) holds what is assigned, and the live-only cell `Out` follows the
        /// function of it. The raw cell is declared with `E`, or, with `live`, by a guard `E`
        /// until the first assignment; `Out` is declared by the guard the macro pass wrote.
        fn declareLiveType(self: *Self, raw: ?Token, raw_public: bool, out: Token, out_public: bool, mutable: bool, live: bool, form: FunctionType) ParseError!void {
            const w = self.workspace;
            if (w.binding_count + 2 > w.bindings.len) return w.fail(out.span, .binding_limit);
            if (w.source_cell_count + 2 > w.source_cells.len) return w.fail(out.span, .source_cell_limit);
            if (w.live_type_count == w.live_types.len) return w.fail(out.span, .source_cell_limit);
            _ = try self.take(.equal, .expected_equal);
            // RFC-0087, P5.4: both cells are given their values whole.
            if (catalogue.keyedKind(form.parameter, self.definitions()) != .none or catalogue.keyedKind(form.result, self.definitions()) != .none) return w.fail(out.span, .weak_map_whole);
            const raw_span = if (raw) |token| token.span else try self.rawName(out.span);
            const raw_type = form.parameter;
            self.pending_binding = out.span;
            var raw_node: u32 = undefined;
            const raw_cell = w.source_cell_count;
            if (live) {
                _ = w.catalogue.internLive(raw_type) catch |err| return w.fail(out.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                self.live_guard_type = raw_type;
                const guard = try self.parseExpression(raw_type);
                try self.takeGuard(guard, raw_type);
                raw_node = try self.emit(.{ .span = raw_span, .value_type = raw_type, .kind = .{ .cell_live = .{ .cell = raw_cell, .guard = guard, .initialize = true } } });
            } else {
                const root = try self.coerce(try self.parseExpression(raw_type), raw_type);
                raw_node = try self.emit(.{ .span = raw_span, .value_type = raw_type, .kind = .{ .cell_init = .{ .cell = raw_cell, .value = root } } });
            }
            self.pending_binding = .{ .start = 0, .end = 0 };
            // A cell is named by its declaring node, which for a hidden raw cell is its name in
            // the library block: the emitter placed it at the program's text instead.
            if (raw == null) w.nodes[raw_node].span = raw_span;
            // A raw cell that only a guard writes is live-only; one the program never assigns
            // after its first value is an ordinary cell that the compiler keeps from `set`.
            // The program writes the raw cell when it assigns `Out`, from wherever `Out` may be
            // assigned (C44): the cell is as visible as the wider of the two names, while `In`'s
            // binding keeps its own access. A cell of the root file has the access of its
            // binding, and no other module writes it.
            const root_file = !bundled or (w.current_nested == types.no_parent and w.current_module + 1 == w.module_storage.module_count);
            const raw_visible = (raw != null and raw_public) or (!root_file and out_public);
            w.source_cells[raw_cell] = .{ .name = raw_span, .value_type = raw_type, .initial = raw_node, .is_public = raw_visible, .live_only = live and !mutable };
            w.source_cell_count += 1;
            if (raw) |token| w.insertSymbol(.{ .name = token.span, .node = raw_node, .value_type = raw_type, .is_public = raw_public }, raw_cell);
            const after = self.cursor;
            self.cursor = form.group;
            const result = form.result;
            _ = w.catalogue.internLive(result) catch |err| return w.fail(out.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            self.live_guard_type = result;
            self.live_raw = .{ .cell = raw_cell };
            const guard = try self.parseExpression(result);
            self.live_raw = null;
            try self.takeGuard(guard, result);
            std.debug.assert(self.peek().kind == .synthetic_live_end);
            self.cursor = after;
            const out_cell = w.source_cell_count;
            const published = try self.emit(.{ .span = out.span, .value_type = result, .kind = .{ .cell_live = .{ .cell = out_cell, .guard = guard, .initialize = true } } });
            w.source_cells[out_cell] = .{ .name = out.span, .value_type = result, .initial = published, .is_public = out_public, .live_only = true };
            w.source_cell_count += 1;
            w.insertSymbol(.{ .name = out.span, .node = published, .value_type = result, .is_public = out_public }, out_cell);
            w.live_types[w.live_type_count] = .{ .out = out_cell, .raw = raw_cell, .fixed = !mutable, .hidden = raw == null };
            w.live_type_count += 1;
        }
        /// The name of a hidden raw cell or field (RFC-0084, P4.3): the next of the block's raw
        /// names, which no program can reach (`__raw0`, ...).
        fn rawName(self: *Self, at: Span) ParseError!Span {
            const w = self.workspace;
            if (!w.has_library) return w.fail(at, .macro_unavailable);
            const site = try w.siteFor(.{ .kind = .identifier, .span = at });
            const index = w.library_raws[site.module];
            if (index >= site.extension.raws) {
                if (site.extension.raws > types.limits.tokens / 2) return w.fail(at, .macro_limit);
                return w.requestExtension(site, .{ .raws = @max(4, 2 * site.extension.raws) });
            }
            const word = site.extension.rawWord(index);
            if (site.templates + word[1] > site.library_end) return w.fail(at, .macro_limit);
            w.library_raws[site.module] += 1;
            return .{ .start = site.templates + word[0], .end = site.templates + word[1] };
        }
        /// The raw cell, or the raw field, the program writes when it assigns the cell `out`
        /// (RFC-0084, P4.3).
        fn liveTypeOfCell(self: *const Self, cell: u32) ?LiveType {
            const w = self.workspace;
            for (w.live_types[0..w.live_type_count]) |entry| if (entry.class == null and (entry.out == cell or entry.raw == cell)) return entry;
            return null;
        }

        /// `Name := native{"id"}` binds a host function. Its signature is derived from
        /// the Zig function, so source and host cannot disagree.
        fn parseNative(self: *Self, name: Token, is_public: bool) ParseError!void {
            const w = self.workspace;
            if (is_public) return w.fail(name.span, .unsupported_specifier);
            if (w.native_binding_count == w.native_bindings.len) return w.fail(name.span, .function_limit);
            _ = try self.take(.colon, .expected_equal);
            _ = try self.take(.equal, .expected_equal);
            _ = try self.take(.identifier, .unexpected_token);
            _ = try self.take(.left_brace, .unexpected_token);
            self.skipNewlines();
            const id_token = try self.take(.string, .unknown_native);
            const id = w.source[id_token.span.start + 1 .. id_token.span.end - 1];
            self.skipNewlines();
            _ = try self.take(.right_brace, .unexpected_token);
            var found: ?u16 = null;
            for (w.natives, 0..) |candidate, index| if (std.mem.eql(u8, candidate.id, id)) {
                found = std.math.cast(u16, index) orelse return w.fail(id_token.span, .unknown_native);
                break;
            };
            const entry_index = found orelse return w.fail(id_token.span, .unknown_native);
            const host = w.natives[entry_index];
            if (!native.wellFormed(host)) return w.fail(id_token.span, .unknown_native);
            var binding: NativeBinding = .{ .name = name.span, .entry = entry_index, .params = undefined, .param_count = @intCast(host.params.len), .result = undefined };
            for (host.params, binding.params[0..host.params.len]) |shape, *slot| slot.* = try self.nativeType(shape, id_token.span);
            binding.result = try self.nativeType(host.result, id_token.span);
            w.native_bindings[w.native_binding_count] = binding;
            w.native_binding_count += 1;
        }
        fn nativeType(self: *Self, shape: native.Shape, span: Span) ParseError!types.Type {
            const w = self.workspace;
            // A generic native has no one signature to bind a name to: the standard forms
            // that use one choose its types at each call (RFC-0077).
            if (shape.generic()) return w.fail(span, .unsupported_type);
            // RFC-0086, P2.3: a handle is the type `reader` or `writer`, and only ever a scalar
            // (`wellFormed`).
            if (shape.handle()) {
                std.debug.assert(shape.kind == .scalar);
                return w.catalogue.internGrant(if (shape.element == .writer) .writer else .reader) catch w.fail(span, .type_limit);
            }
            const element = shape.builtin();
            return switch (shape.kind) {
                .nested, .map => unreachable,
                .unit => w.catalogue.internTuple(&.{}) catch |err| w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type),
                .scalar => element,
                .array => w.catalogue.internArray(element) catch |err| w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type),
                .option => w.catalogue.internOption(element) catch |err| w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type),
            };
        }
        fn emitNative(self: *Self, operator: Operator, arguments: []const u32) ParseError!u32 {
            const w = self.workspace;
            const binding = w.native_bindings[operator.function];
            if (arguments.len != binding.param_count) return w.fail(operator.span, .argument_count);
            // An effect native acts on the world or draws from it: its caller says so (RFC-0079).
            if (w.natives[binding.entry].effect != .none) try self.nativeEffect(operator.span);
            if (native.dictates(w.natives[binding.entry]) and self.predicting()) return w.fail(operator.span, .call_requires_dictates);
            for (arguments, binding.params[0..binding.param_count]) |operand, required| {
                if (self.node(operand).value_type != required) return w.fail(self.node(operand).span, .type_mismatch);
            }
            var call: types.NativeCall = .{ .native = binding.entry, .count = binding.param_count, .args = @splat(0) };
            @memcpy(call.args[0..arguments.len], arguments);
            return self.emit(.{ .span = operator.span, .value_type = binding.result, .kind = .{ .native_call = call } });
        }

        /// `using{M}` makes the public names of the module imported as `M` visible without qualification.
        fn parseUsing(self: *Self, name: Token) ParseError!void {
            const w = self.workspace;
            if (!bundled) return w.fail(name.span, .module_bundle_required);
            _ = try self.take(.left_brace, .unexpected_token);
            self.skipNewlines();
            if (self.peek().kind == .path) return self.parsePathUsing(name);
            const alias = try self.take(.identifier, .expected_name);
            var target: u32 = undefined;
            if (w.module_storage.nested_count == 0) {
                self.skipNewlines();
                _ = try self.take(.right_brace, .unexpected_token);
                const edge = w.findAlias(alias.span.text(w.source)) orelse return w.fail(alias.span, .unknown_name);
                target = edge.target;
            } else {
                // `using{Outer.Inner}`: a module in reach, then modules it declares.
                target = (try self.moduleNamed(alias)) orelse return w.fail(alias.span, .unknown_name);
                while (self.peek().kind == .dot) {
                    _ = try self.take(.dot, .expected_name);
                    target = try self.childOf(target, try self.take(.identifier, .expected_name), alias.span.start);
                }
                self.skipNewlines();
                _ = try self.take(.right_brace, .unexpected_token);
            }
            if (w.using_count == w.using_edges.len) return w.fail(name.span, .import_limit);
            // RFC-0076 (D5): what the module exports becomes visible here, so none of it may
            // be a name that this scope or one around it has already declared.
            if (self.usingClash(target, name.span.start)) |earlier| return self.failShadowed(alias.span, earlier);
            w.using_edges[w.using_count] = .{ .module = w.currentScope(), .target = target };
            w.using_count += 1;
        }

        /// RFC-0093: `using{/Domain/Folder/Inner}`, from the path. The import the preparation
        /// recorded for the path names the folder's module, the longest one the path begins
        /// with; every further segment, and every `.Name` after the path, is a module declared
        /// by the one before it, as in `using{Outer.Inner}`.
        fn parsePathUsing(self: *Self, name: Token) ParseError!void {
            const w = self.workspace;
            const path = try self.take(.path, .expected_name);
            const edge = w.pathImport(path.span) orelse return w.fail(path.span, .invalid_module_metadata);
            var target = edge.target;
            var at = edge.path.end;
            const text = w.source;
            while (at < path.span.end) {
                std.debug.assert(text[at] == '/');
                var end = at + 1;
                while (end < path.span.end and text[end] != '/') end += 1;
                const member: Token = .{ .kind = .identifier, .span = .{ .start = at + 1, .end = end } };
                if (w.module_storage.nested_count == 0) return w.fail(member.span, .unknown_name);
                target = try self.childOf(target, member, path.span.start);
                at = end;
            }
            while (self.peek().kind == .dot) {
                _ = try self.take(.dot, .expected_name);
                const member = try self.take(.identifier, .expected_name);
                if (w.module_storage.nested_count == 0) return w.fail(member.span, .unknown_name);
                target = try self.childOf(target, member, path.span.start);
            }
            self.skipNewlines();
            _ = try self.take(.right_brace, .unexpected_token);
            if (w.using_count == w.using_edges.len) return w.fail(name.span, .import_limit);
            if (self.usingClash(target, name.span.start)) |earlier| return self.failShadowed(path.span, earlier);
            w.using_edges[w.using_count] = .{ .module = w.currentScope(), .target = target };
            w.using_count += 1;
        }

        /// Whether the module `target` exports a name that a scope around this point declared
        /// before source position `before`. Every public declaration written inside the
        /// module is asked once; a module around this point brings in nothing that is not
        /// visible already, and what another `using` brings in is no declaration.
        fn usingClash(self: *const Self, target: u32, before: u32) ?Span {
            const w = self.workspace;
            if (w.insideScope(w.currentScope(), target)) return null;
            // A `using` of the same module here or around here was asked already: what was
            // declared before it clashed then, and what was declared after it was refused
            // where it was declared (`usingExports`). So repeating one costs no scan.
            for (w.using_edges[0..w.using_count]) |edge| if (edge.target == target and w.insideScope(w.currentScope(), edge.module)) return null;
            const scope = w.scopeOf(target);
            for (w.functions.definitions[0..w.functions.count]) |function| {
                if (function.is_public and !function.is_extension and !function.anonymous) if (self.clashes(function.name, scope, before)) |earlier| return earlier;
            }
            for (w.bindings[0..w.binding_count]) |binding| if (binding.is_public) if (self.clashes(binding.name, scope, before)) |earlier| return earlier;
            for (self.definitions()) |item| if (catalogue.declaredName(item)) |declared| {
                if (self.clashes(declared, scope, before)) |earlier| return earlier;
            };
            for (w.generic_templates[0..w.generic_count]) |template| if (template.is_public) if (self.clashes(template.name, scope, before)) |earlier| return earlier;
            for (w.type_aliases[0..w.type_alias_count]) |entry| if (entry.is_public) if (self.clashes(entry.name, scope, before)) |earlier| return earlier;
            return null;
        }

        /// The declaration around this point, made before `before`, of `name`, if `name` is
        /// written inside `scope` and is a name that scope exports.
        fn clashes(self: *const Self, name: Span, scope: Span, before: u32) ?Span {
            const w = self.workspace;
            if (name.start < scope.start or name.end > scope.end or w.libraryModule(name) != null) return null;
            const text = name.text(w.source);
            if (generatedName(text) or !self.exportsName(text, scope)) return null;
            if (w.findAlias(text)) |edge| return edge.alias;
            var at = w.currentScope();
            while (true) {
                if (self.declarationBefore(text, w.scopeOf(at), before)) |span| return span;
                if (w.childModule(at, text, before)) |module| return w.module_storage.nested[module].name;
                at = w.outerScope(at) orelse return null;
            }
        }

        /// Whether the scope with text `target` exports `text` to a `using`.
        fn exportsName(self: *const Self, text: []const u8, target: Span) bool {
            const w = self.workspace;
            return if (w.functions.findIn(text, w.source, target)) |index| w.functions.definitions[index].is_public and !w.functions.definitions[index].is_extension else if (w.findSymbolIn(text, target)) |index| w.bindings[index].is_public else if (w.catalogue.findNamedIn(text, w.source, target)) |named| exportedType(self.definitions(), named) else if (self.findGeneric(text, target)) |index| w.generic_templates[index].is_public else if (w.findTypeAliasIn(text, target)) |alias| alias.is_public else false;
        }

        /// Whether the scope with text `scope` declares `text` as something other than a module.
        fn declaresName(self: *const Self, text: []const u8, scope: Span) bool {
            const w = self.workspace;
            // The body of a generic function is compiled when it is asked for, and means what
            // it meant where it was written: what was declared after the template does not count.
            if (w.findSymbolIn(text, scope)) |index| return self.visible(w.bindings[index].name);
            // An extension method is named only after a receiver (RFC-0075), so it leaves the
            // bare name to the scopes further out, as it leaves it to the intrinsics.
            if (w.plainFunctionIn(text, scope)) |index| return self.visible(w.functions.definitions[index].name);
            if (w.catalogue.findNamedIn(text, w.source, scope)) |named| return self.visible(catalogue.declaredName(catalogue.definition(named, self.definitions()).?).?);
            // A class that is declared late (RFC-0073) is one from the start, like every class.
            if (w.late_count != 0) if (w.lateIn(text, w.scopeNamed(scope))) |entry| if (w.late[entry].kind == .class) return true;
            if (w.findNativeIn(text, scope)) |index| return self.visible(w.native_bindings[index].name);
            if (w.findTypeAliasIn(text, scope)) |alias| return self.visible(alias.name);
            if (self.findGeneric(text, scope)) |index| return self.visible(w.generic_templates[index].name);
            return false;
        }

        /// The module that the single name `token` means here, as a scope: one declared by a
        /// scope around this code, an import of the file, or a public module of a module in `using`.
        fn moduleNamed(self: *Self, token: Token) ParseError!?u32 {
            const w = self.workspace;
            const text = token.span.text(w.source);
            const count = w.module_storage.module_count;
            var at = w.currentScope();
            while (true) {
                if (w.childModule(at, text, token.span.start)) |module| return count + module;
                // Another declaration of the name in between hides the modules further out.
                if (self.declaresName(text, w.scopeOf(at))) return null;
                at = w.outerScope(at) orelse break;
            }
            if (w.findAlias(text)) |edge| {
                if (!self.visible(edge.alias)) return w.fail(token.span, .unknown_name);
                return edge.target;
            }
            var found: ?u32 = null;
            for (w.using_edges[0..w.using_count]) |edge| {
                if (!w.insideScope(w.currentScope(), edge.module)) continue;
                const module = w.childModule(edge.target, text, token.span.start) orelse continue;
                if (!w.module_storage.nested[module].is_public) continue;
                if (found != null and found.? != count + module) return w.fail(token.span, .ambiguous_call);
                found = count + module;
            }
            return found;
        }

        /// The module `member` that scope `id` declares, if this code may name it: any module of
        /// a scope around this code, and the `<public>` modules of every other scope.
        fn childOf(self: *Self, id: u32, member: Token, before: u32) ParseError!u32 {
            const w = self.workspace;
            const module = w.childModule(id, member.span.text(w.source), before) orelse return w.fail(member.span, .unknown_name);
            if (!w.module_storage.nested[module].is_public and !w.insideScope(w.currentScope(), id)) return w.fail(member.span, .private_name);
            return w.module_storage.module_count + module;
        }

        /// `Module.Inner.Name` from the dot after the first module, which is scope `first`: every
        /// further segment that is a module of the one before it and is followed by a dot
        /// extends the path; the segment after the last module is the name.
        fn qualifiedName(self: *Self, token: Token, first: u32) ParseError!Name {
            const w = self.workspace;
            var id = first;
            // RFC-0085, I11: the first name is a module of this file or an import's alias.
            if (w.qualify) {
                const count = w.module_storage.module_count;
                if (first >= count) {
                    w.noteName(token.span, w.module_storage.nested[first - count].name.start, .global, qualify.none);
                } else if (w.findAlias(token.span.text(w.source))) |edge| w.noteName(token.span, edge.alias.start, .global, qualify.none);
            }
            while (true) {
                _ = try self.take(.dot, .expected_name);
                const member = try self.take(.identifier, .expected_name);
                if (self.peek().kind == .dot and w.childModule(id, member.span.text(w.source), token.span.start) != null) {
                    id = try self.childOf(id, member, token.span.start);
                    w.noteName(member.span, w.module_storage.nested[id - w.module_storage.module_count].name.start, .global, qualify.none);
                    continue;
                }
                return .{ .token = member, .span = .{ .start = token.span.start, .end = member.span.end }, .scope = w.scopeOf(id), .qualified = true, .inside = w.insideScope(w.currentScope(), id) };
            }
        }

        /// RFC-0076 (D5): a name may not be declared where it is already visible. `name` is a
        /// local, a parameter or a capture about to be declared. Visible are: the locals and
        /// parameters of the function being compiled and, for an anonymous function, of the
        /// functions it is written in (`lexical`); that function's own name; every declaration
        /// of the scopes around the code that was made before (values, functions, types,
        /// aliases, generic templates, natives, modules, imports); and the public names of the
        /// modules in `using`. Generated names and library text are not checked: a macro's
        /// temporaries are unusable by user code, and what it re-declares it declares on purpose.
        fn checkShadow(self: *Self, name: Token, lexical: bool) ParseError!void {
            const w = self.workspace;
            const text = name.span.text(w.source);
            if (generatedName(text) or w.libraryModule(name.span) != null) return;
            // `(local:)Name` (RFC-0083) may share its name with what the scopes around the
            // function declare and what a `using` brings in; inside the function, `Name` is
            // the local. What the function itself declares it may not redeclare.
            const qualified = w.localQualified(name.span.start);
            // Inside a parametric type its own name is visible, though no instantiation is declared yet.
            if (self.generic) |context| if (std.mem.eql(u8, w.generic_templates[context.template].name.text(w.source), text)) return self.failShadowed(name.span, null);
            // So are its type parameters.
            if (self.genericParameter(text)) return self.failShadowed(name.span, null);
            if (lexical and (self.findLocal(text) != null or self.parameter(text) != null or self.enclosingBinding(text) or self.pendingName(text))) return self.failShadowed(name.span, null);
            if (lexical) if (self.function) |f| {
                if (!f.anonymous and !f.is_extension and std.mem.eql(u8, f.name.text(w.source), text)) return self.failShadowed(name.span, null);
            };
            // RFC-0085, I3: so does a nested function in scope, unless this is a nested function
            // of the same block that overloads it (06:1128, I4).
            if (lexical) if (self.findNested(text, std.math.maxInt(u32))) |entry| if (name.span.start != self.nested_header or !self.nestedSibling(entry)) return self.failShadowed(name.span, w.nested_functions[entry].name);
            if (qualified) return;
            if (self.declaredOutside(text, name.span.start, w.currentScope())) return self.failShadowed(name.span, null);
            // RFC-0091 (B3): a module function declared further down that this body has called
            // is as visible here as one declared before it (c3-1).
            if (self.forwardCalledBefore(text, name.span.start)) |declaration| return self.failShadowed(name.span, declaration);
        }

        /// The module function `text`, declared further down, if the body being compiled
        /// called it before source position `before`. The body is that of the outermost
        /// function or module value around the cursor, nested functions and `Fn`s included.
        /// Only the latest call of each declaration is kept: bodies are compiled one after
        /// another and in source order, so a call of this body is the latest one.
        fn forwardCalledBefore(self: *const Self, text: []const u8, before: u32) ?Span {
            const w = self.workspace;
            const runtime = &w.runtime_functions;
            if (runtime.forward_count == 0 or self.generic != null) return null;
            // A forward call indexes the headers of its scope, so a scope whose index is not
            // current made no forward call since; asking would index it.
            if (w.forward_pass != w.passes or w.forward_scope != w.currentScope()) return null;
            // A generic body is compiled where it is called, away from its text.
            for (w.anonymous_frames[0..w.anonymous_count]) |frame| if (frame.kind == .generic) return null;
            const outermost: Span = if (w.anonymous_count != 0)
                if (w.anonymous_frames[0].parent_function) |f| f.name else if (self.pending_binding.start != self.pending_binding.end) self.pending_binding else w.anonymous_frames[0].definition.name
            else if (self.function) |f| f.name else return null;
            var same = w.forward_table.walk(&w.forward_slots, name_index.hashName(0, text));
            while (same.next()) |index| {
                const header = w.tokens[w.forward_headers[index]].span;
                if (header.start <= before or !std.mem.eql(u8, header.text(w.source), text)) continue;
                const entry = runtime.findForward(header) orelse continue;
                const call = runtime.forward[entry].last_call;
                if (call >= outermost.start and call < before) return header;
            }
            return null;
        }

        /// A declaration of the current scope: the same check against the scopes around it.
        fn checkOuterShadow(self: *Self, name: Token) ParseError!void {
            const w = self.workspace;
            const text = name.span.text(w.source);
            if (generatedName(text) or w.libraryModule(name.span) != null) return;
            if (self.usingExports(text)) return self.failShadowed(name.span, null);
            const outer = w.outerScope(w.currentScope()) orelse return;
            if (self.declaredOutside(text, name.span.start, outer)) return self.failShadowed(name.span, null);
        }

        /// Whether scope `from` or a scope around it declares `text` before source position
        /// `before`, or a `using` in effect exports it. Every lookup is hashed by scope and
        /// name except those of natives and aliases, which are few.
        fn declaredOutside(self: *const Self, text: []const u8, before: u32, from: u32) bool {
            const w = self.workspace;
            if (bundled and w.findAlias(text) != null) return true;
            var at = from;
            while (true) {
                if (self.declaresBefore(text, w.scopeOf(at), before) or (bundled and w.childModule(at, text, before) != null)) return true;
                at = w.outerScope(at) orelse break;
            }
            return self.usingExports(text);
        }

        /// `declaresName`, for a declaration written before source position `before`. Classes
        /// are in the catalogue ahead of their declarations, so that they may name each other;
        /// for shadowing a class counts from where it is written, like everything else.
        fn declaresBefore(self: *const Self, text: []const u8, scope: Span, before: u32) bool {
            return self.declarationBefore(text, scope, before) != null;
        }
        /// The declaration `declaresBefore` finds.
        fn declarationBefore(self: *const Self, text: []const u8, scope: Span, before: u32) ?Span {
            const w = self.workspace;
            const name: Span = if (w.findSymbolIn(text, scope)) |index| w.bindings[index].name else if (w.plainFunctionIn(text, scope)) |index| w.functions.definitions[index].name else if (w.catalogue.findNamedIn(text, w.source, scope)) |named| catalogue.declaredName(catalogue.definition(named, self.definitions()).?).? else if (w.lateClassIn(text, scope)) |late| late else if (w.findNativeIn(text, scope)) |index| w.native_bindings[index].name else if (w.findTypeAliasIn(text, scope)) |alias| alias.name else if (self.findGeneric(text, scope)) |index| w.generic_templates[index].name else return null;
            // A name of the library block is no declaration of the program's.
            if (w.libraryModule(name) != null) return null;
            return if (name.start < before and self.visible(name)) name else null;
        }

        /// Refuses the declaration at `span` as `shadowed_name`, naming the declaration that
        /// already gives its name a meaning (`related`, or found again by `shadowedSite`) as a
        /// second place of the diagnostic. Only the failure looks for it.
        fn failShadowed(self: *const Self, span: Span, related: ?Span) ParseError {
            const w = self.workspace;
            const earlier = related orelse self.shadowedSite(span.text(w.source), span.start);
            const failure = w.fail(span, .shadowed_name);
            if (earlier) |site| if (site.start < site.end and w.libraryModule(site) == null) {
                w.diagnostic.related = site;
            };
            return failure;
        }

        /// The declaration that makes `text` visible where a declaration of it at `before` is
        /// refused, asked in the order of `checkShadow`. Null for a name that only a `using`
        /// brings in, which is declared in another file.
        fn shadowedSite(self: *const Self, text: []const u8, before: u32) ?Span {
            const w = self.workspace;
            if (self.generic) |context| {
                const template = w.generic_templates[context.template];
                if (std.mem.eql(u8, template.name.text(w.source), text)) return template.name;
                for (template.parameters[0..template.parameter_count]) |span| if (std.mem.eql(u8, span.text(w.source), text)) return span;
            }
            if (self.findLocal(text)) |index| return w.locals[index].name;
            if (self.parameter(text)) |index| return self.function.?.parameters[index].name;
            var index = w.anonymous_count;
            while (index > 0) {
                index -= 1;
                const frame = &w.anonymous_frames[index];
                if (frame.phase != .body) continue;
                if (frame.kind == .generic) break;
                if (frame.parent_function) |f| {
                    for (f.parameters[0..f.parameter_count]) |entry| if (std.mem.eql(u8, entry.name.text(w.source), text)) return entry.name;
                    if (!f.anonymous and !f.is_extension and std.mem.eql(u8, f.name.text(w.source), text)) return f.name;
                }
                for (w.locals[frame.local_base..frame.locals]) |entry| if (std.mem.eql(u8, entry.name.text(w.source), text)) return entry.name;
            }
            if (self.pending_binding.start != self.pending_binding.end and std.mem.eql(u8, self.pending_binding.text(w.source), text)) return self.pending_binding;
            if (self.function) |f| if (!f.anonymous and !f.is_extension and std.mem.eql(u8, f.name.text(w.source), text)) return f.name;
            if (bundled) if (w.findAlias(text)) |edge| return edge.alias;
            var at = w.currentScope();
            while (true) {
                if (self.declarationBefore(text, w.scopeOf(at), before)) |span| return span;
                if (bundled) if (w.childModule(at, text, before)) |module| return w.module_storage.nested[module].name;
                at = w.outerScope(at) orelse return null;
            }
        }

        /// Whether `text` is the name of a declaration whose value is being read: the binding
        /// of the module that this expression initialises, or a local of a block around this
        /// point whose value is still being evaluated. Neither is published yet, and neither
        /// may be declared again inside its own initialiser.
        fn pendingName(self: *const Self, text: []const u8) bool {
            const w = self.workspace;
            if (self.pending_binding.start != self.pending_binding.end and std.mem.eql(u8, self.pending_binding.text(w.source), text)) {
                // The body of a generic function is compiled where it is called and is not
                // written inside the binding that calls it.
                const apart = for (w.anonymous_frames[0..w.anonymous_count]) |frame| {
                    if (frame.kind == .generic) break true;
                } else false;
                if (!apart) return true;
            }
            var index = self.operator_count;
            while (index > self.operator_base) {
                index -= 1;
                const op = w.operators[index];
                // Only a declaration is pending under its name; a `set` names what exists.
                if (op.kind == .block and op.head != no_member and op.arguments <= 1) {
                    const pending: Span = .{ .start = op.head, .end = op.tail };
                    if (std.mem.eql(u8, pending.text(w.source), text)) return true;
                }
            }
            return false;
        }

        /// Whether a module that a `using` in effect here names exports `text`.
        fn usingExports(self: *const Self, text: []const u8) bool {
            const w = self.workspace;
            if (!bundled) return false;
            for (w.using_edges[0..w.using_count]) |edge| {
                if (!w.insideScope(w.currentScope(), edge.module)) continue;
                if (self.exportsName(text, w.scopeOf(edge.target))) return true;
            }
            return false;
        }

        /// Whether a function that the anonymous function being compiled is written in has a
        /// local or a parameter named `text`. The body of a generic function is compiled where
        /// it is called and means what it meant where it was written, so the search ends there.
        fn enclosingBinding(self: *const Self, text: []const u8) bool {
            const w = self.workspace;
            var index = w.anonymous_count;
            while (index > 0) {
                index -= 1;
                const frame = &w.anonymous_frames[index];
                // A frame whose parameters are still being read has not replaced its parent yet.
                if (frame.phase != .body) continue;
                if (frame.kind == .generic) return false;
                if (frame.parent_function) |f| {
                    for (f.parameters[0..f.parameter_count]) |entry| if (std.mem.eql(u8, entry.name.text(w.source), text)) return true;
                    if (!f.anonymous and !f.is_extension and std.mem.eql(u8, f.name.text(w.source), text)) return true;
                }
                for (w.locals[frame.local_base..frame.locals]) |entry| if (std.mem.eql(u8, entry.name.text(w.source), text)) return true;
            }
            return false;
        }

        /// Whether a scope around this code gives `text` a meaning: a declaration, a module or
        /// an import. Such a name is never taken from a module in `using`.
        fn declaredAround(self: *const Self, text: []const u8, before: u32) bool {
            const w = self.workspace;
            if (w.findAlias(text) != null) return true;
            var at = w.currentScope();
            while (true) {
                // An extension method is named only after a receiver, so it does not keep the
                // bare name from a module in `using` (RFC-0076).
                if (self.declaresName(text, w.scopeOf(at)) or w.childModule(at, text, before) != null) return true;
                at = w.outerScope(at) orelse return false;
            }
        }

        /// The module scope that supplies `token` through a `using`, if the current module does not
        /// define the name itself and exactly one used module exports it.
        fn usingScope(self: *Self, token: Token) ParseError!?Span {
            return self.usingScopeOf(token.span.text(self.workspace.source), token.span);
        }

        /// `usingScope` for a name that is not written at the place it is resolved from.
        fn usingScopeOf(self: *Self, text: []const u8, at: Span) ParseError!?Span {
            const w = self.workspace;
            const scope = w.scope();
            if (w.module_storage.nested_count == 0) {
                if (w.findAlias(text) != null or w.findSymbolIn(text, scope) != null or w.plainFunctionIn(text, scope) != null or w.findType(text) != null or w.findNativeIn(text, scope) != null or w.findTypeAliasIn(text, scope) != null or self.findGeneric(text, scope) != null) return null;
            } else if (self.declaredAround(text, at.start)) return null;
            var found: ?Span = null;
            for (w.using_edges[0..w.using_count]) |edge| {
                // A `using` holds for its scope and for the modules nested in it.
                if (!w.insideScope(w.currentScope(), edge.module)) continue;
                const target = w.scopeOf(edge.target);
                const exported = if (w.functions.findIn(text, w.source, target)) |index| w.functions.definitions[index].is_public and !w.functions.definitions[index].is_extension else if (w.findSymbolIn(text, target)) |index| w.bindings[index].is_public else if (w.catalogue.findNamedIn(text, w.source, target)) |named| exportedType(self.definitions(), named) else if (self.findGeneric(text, target)) |index| w.generic_templates[index].is_public else if (w.findTypeAliasIn(text, target)) |alias| alias.is_public else false;
                if (!exported) continue;
                // Which `ToString` a call means is the type's to say (`chooseText`).
                if (found != null and !std.meta.eql(found.?, target)) {
                    if (std.mem.eql(u8, text, "ToString")) continue;
                    return w.fail(at, .ambiguous_call);
                }
                found = target;
            }
            return found;
        }

        fn parseImport(self: *Self, name: Token, is_public: bool) ParseError!void {
            const w = self.workspace;
            if (is_public) return w.fail(name.span, .unsupported_specifier);
            if (!bundled) return w.fail(name.span, .module_bundle_required);
            const edge = w.findAlias(name.span.text(w.source)) orelse return w.fail(name.span, .late_import);
            if (edge.alias.start != name.span.start) return w.fail(name.span, .late_import);
            w.noteDeclaration(name.span, .global, qualify.none);
            _ = try self.take(.colon, .expected_equal);
            _ = try self.take(.equal, .expected_equal);
            _ = try self.take(.identifier, .unexpected_token);
            _ = try self.take(.left_brace, .unexpected_token);
            self.skipNewlines();
            // RFC-0093: a folder tree imports a folder's module by its path.
            const path = try self.take(if (w.module_storage.part_count != 0) .path else .string, .invalid_module_path);
            std.debug.assert(if (path.kind == .path) std.meta.eql(path.span, edge.path) else path.span.start + 1 == edge.path.start and path.span.end - 1 == edge.path.end);
            self.skipNewlines();
            _ = try self.take(.right_brace, .unexpected_token);
        }

        fn specifier(self: *Self, name: []const u8, code: Diagnostic.Code) ParseError!void {
            _ = try self.take(.less, code);
            const token = try self.take(.identifier, code);
            if (!std.mem.eql(u8, token.span.text(self.workspace.source), name)) return self.workspace.fail(token.span, code);
            _ = try self.take(.greater, code);
        }

        fn parseType(self: *Self) ParseError!types.Type {
            _ = try self.take(.colon, .expected_type);
            return self.parseTypeValue();
        }
        /// The result type of a function, method or `Fn`. `discards` says it was written `void`
        /// (RFC-0080): the body may then have any type, its value is dropped, and the function
        /// yields the unit value `tuple{}`. The type itself is `tuple()` either way.
        fn parseResultType(self: *Self) ParseError!struct { value_type: types.Type, discards: bool } {
            const start = self.cursor;
            self.void_at = std.math.maxInt(u32);
            const value_type = try self.parseType();
            const bare = self.cursor == start + 2 and self.void_at == self.workspace.tokens[start + 1].span.start;
            return .{ .value_type = value_type, .discards = bare };
        }
        /// The body of a function whose result is `void`: any expression, whose value is dropped.
        /// A body that is itself a comparison is a dropped comparison like any other (RFC-0076).
        fn discardedBody(self: *Self, span: Span) ParseError!u32 {
            const value = try self.parseExpression(null);
            try self.checkDiscarded(value);
            return self.packTuple(&.{}, span);
        }
        fn parseTypeValue(self: *Self) ParseError!types.Type {
            // RFC-0084, P4.3: the guard the macro pass wrote before a type that might have been a
            // function. Where a function cannot be a type, naming one is refused.
            if (self.peek().kind == .synthetic_live_type) if (try self.liveTypeAt()) |form| return self.workspace.fail(form.path, .live_type_form);
            const token = self.peek();
            if (token.kind == .identifier and !compoundName(token.span.text(self.workspace.source)) and !projectionName(token.span.text(self.workspace.source)) and !self.taskTypeAt(token, self.workspace.tokens[self.cursor + 1])) {
                self.cursor += 1;
                return self.namedType(try self.resolveTypeName(token));
            }
            return self.parseCompoundType();
        }

        /// `__elem(Items)` and `__result(F)` name the element type of an array and the result type
        /// of a function that is a local or parameter in scope. Compiler-generated code uses
        /// them where it cannot spell a type that depends on a user expression.
        fn parseProjection(self: *Self, token: Token, name: []const u8) ParseError!types.Type {
            const w = self.workspace;
            if (std.mem.eql(u8, name, "__ret")) {
                if (w.libraryModule(token.span) == null) return w.fail(token.span, .expected_type);
                // The word is library text; the token before it carries the place of the `Return`
                // or of the loop it is in, which is where a diagnostic belongs.
                std.debug.assert(self.cursor >= 2);
                return self.exitType(w.tokens[self.cursor - 2].span);
            }
            _ = try self.take(.left_paren, .expected_type);
            const subject = try self.take(.identifier, .expected_type);
            _ = try self.take(.right_paren, .expected_type);
            const text = subject.span.text(w.source);
            const subject_type = if (self.findLocal(text)) |index| self.localType(index) else if (self.parameter(text)) |index| self.parameterType(index) else if (w.findSymbolIn(text, w.scope())) |binding| w.bindings[binding].value_type else return w.fail(subject.span, .unknown_name);
            if (std.mem.eql(u8, name, "__type")) return subject_type;
            // A loop over a string binds a byte position and the code unit there (RFC-0069).
            if (subject_type == .string and (std.mem.eql(u8, name, "__elem") or std.mem.eql(u8, name, "__key"))) return if (std.mem.eql(u8, name, "__key")) .i64 else types.Type.char;
            if (std.mem.eql(u8, name, "__var")) {
                // The type of a local declared `var`; anything else cannot be assigned, and what
                // a `Spawn` captured is a copy (RFC-0082).
                if (self.findLocal(text) == null) if (self.capturedBy(text)) |code| return w.fail(subject.span, code);
                // RFC-0085, I2: a loop in an `Fn` that assigns what the `Fn` captured for a local
                // `var` shares it; the compile that notes it is discarded, and no loop carries it.
                if (self.findLocal(text) == null and self.sharesCapture(text)) return subject_type;
                const index = self.findLocal(text) orelse return w.fail(subject.span, .not_mutable);
                if (!w.locals[index].mutable) return w.fail(subject.span, .not_mutable);
                return subject_type;
            }
            const shape = catalogue.definition(subject_type, self.definitions()) orelse return w.fail(subject.span, .type_mismatch);
            if (std.mem.eql(u8, name, "__elem") or std.mem.eql(u8, name, "__key")) {
                // What a loop over the subject binds: an array's index and element, a map's key and value.
                const keyed = std.mem.eql(u8, name, "__key");
                // RFC-0087: no loop walks a `weak_map` (03:1112).
                if (shape == .weak_map) return w.fail(subject.span, .weak_map_operation);
                if (shape == .map) return if (keyed) shape.map.key else shape.map.value;
                if (shape != .array) return w.fail(subject.span, .type_mismatch);
                return if (keyed) .i64 else shape.array;
            }
            if (shape != .callable) return w.fail(subject.span, .not_callable);
            return shape.callable.result;
        }

        // Scalar/named annotations avoid this bounded scratch frame. Only compound
        // array/tuple/option/map syntax enters the iterative structural-type parser.
        fn parseCompoundType(self: *Self) ParseError!types.Type {
            const w = self.workspace;
            const Frame = struct { start: u32, arrays: u32, span: Span, kind: enum { tuple, option, map, callable, callable_decides, transacts, transacts_decides, task, event, awaitable, signalable, sticky_event, subscribable_event, weak_map }, detail: types.EffectDetail = .{} };
            var frames: [types.limits.expression_depth]Frame = undefined;
            var elements: [types.limits.tuple_elements]types.Type = undefined;
            var depth: u32 = 0;
            var used: u32 = 0;
            while (true) {
                var arrays: u32 = 0;
                while (self.peek().kind == .left_bracket) {
                    const bracket = try self.take(.left_bracket, .expected_type);
                    _ = try self.take(.right_bracket, .expected_type);
                    arrays += 1;
                    if (arrays > types.limits.user_types) return w.fail(bracket.span, .type_limit);
                }
                var token = try self.take(.identifier, .expected_type);
                const name = token.span.text(w.source);
                var value_type: types.Type = undefined;
                if (projectionName(name)) {
                    value_type = try self.parseProjection(token, name);
                } else if (compoundName(name) or self.taskTypeAt(token, self.peek())) {
                    w.noteName(token.span, qualify.none, .builtin, qualify.none);
                    var shape: @FieldType(Frame, "kind") = if (std.mem.eql(u8, name, "tuple")) .tuple else if (std.mem.eql(u8, name, "option")) .option else if (std.mem.eql(u8, name, "function")) .callable else if (std.mem.eql(u8, name, "task")) .task else if (std.mem.eql(u8, name, "event")) .event else if (std.mem.eql(u8, name, "awaitable")) .awaitable else if (std.mem.eql(u8, name, "signalable")) .signalable else if (std.mem.eql(u8, name, "sticky_event")) .sticky_event else if (std.mem.eql(u8, name, "subscribable_event")) .subscribable_event else if (std.mem.eql(u8, name, "weak_map")) .weak_map else .map;
                    var detail: types.EffectDetail = .{};
                    if (shape == .callable and self.peek().kind == .less) {
                        const effect = try self.parseEffectIn(.unsupported_specifier, true);
                        shape = if (effect.transacts) (if (effect.decides) .transacts_decides else .transacts) else if (effect.decides) .callable_decides else .callable;
                        detail = effect.detail;
                    }
                    _ = try self.take(.left_paren, .expected_type);
                    if (depth == frames.len) return w.fail(token.span, .expression_limit);
                    frames[depth] = .{ .start = used, .arrays = arrays, .span = token.span, .kind = shape, .detail = detail };
                    depth += 1;
                    self.skipNewlines();
                    if (self.peek().kind != .right_paren) continue;
                    self.cursor += 1;
                    value_type = try self.internShape(frames[depth - 1], &.{});
                    depth -= 1;
                } else value_type = try self.namedType(try self.resolveTypeName(token));
                while (true) {
                    for (0..arrays) |_| value_type = w.catalogue.internArray(value_type) catch |err| return w.fail(token.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                    if (depth == 0) return value_type;
                    const frame = frames[depth - 1];
                    if (used - frame.start == types.limits.tuple_arity or used == elements.len) return w.fail(token.span, .tuple_limit);
                    elements[used] = value_type;
                    used += 1;
                    self.skipNewlines();
                    if (self.peek().kind == .comma) {
                        self.cursor += 1;
                        self.skipNewlines();
                        if (self.peek().kind != .right_paren) break;
                    }
                    _ = try self.take(.right_paren, .expected_type);
                    value_type = try self.internShape(frame, elements[frame.start..used]);
                    used = frame.start;
                    depth -= 1;
                    arrays = frame.arrays;
                    token.span = frame.span;
                }
            }
        }

        fn resolveName(self: *Self, token: Token) ParseError!Name {
            return self.resolveNameIn(token, true);
        }
        fn resolveTypeName(self: *Self, token: Token) ParseError!Name {
            return self.resolveNameIn(token, false);
        }
        fn resolveNameIn(self: *Self, token: Token, expression: bool) ParseError!Name {
            const w = self.workspace;
            const local: Name = .{ .token = token, .span = token.span, .scope = w.scope() };
            if (w.qualifier_count != 0 and !self.enum_qualifier) if (w.qualifierFor(token.span.start)) |qualifier| {
                const text = token.span.text(w.source);
                // `(local:)Name` is a value: a local or a parameter of the code it is written in.
                if (qualifier.local) {
                    if (!expression) return w.fail(token.span, .invalid_qualifier);
                    if (self.findLocal(text) == null and self.parameter(text) == null) return w.fail(token.span, .unknown_name);
                    return local;
                }
                // `(Module:)Name`, now `Module.Name`: the first name is a module, whatever else
                // has that name here.
                if (bundled) if (try self.moduleNamed(token)) |first| return self.qualifiedName(token, first);
                // RFC-0085, I10: `(e:)Name`, now `e.Name`, is the enumerator `Name` of the enum
                // `e` in reach: `e` is read as it would be without the qualifier, and must be an enum.
                if (expression and !self.enum_qualifier) {
                    self.enum_qualifier = true;
                    defer self.enum_qualifier = false;
                    const plain = try self.resolveNameIn(token, true);
                    if (w.catalogue.findNamedIn(text, w.source, plain.scope)) |found| if (catalogue.definition(found, self.definitions()).? == .enumeration) return plain;
                }
                return w.fail(token.span, .invalid_qualifier);
            };
            if (bundled and w.using_count != 0 and !(expression and (self.findLocal(token.span.text(w.source)) != null or self.parameter(token.span.text(w.source)) != null))) {
                if (try self.usingScope(token)) |target| return .{ .token = token, .span = token.span, .scope = target, .qualified = true };
            }
            if (bundled and w.module_storage.nested_count != 0) {
                const text = token.span.text(w.source);
                if (expression and (self.findLocal(text) != null or self.parameter(text) != null)) return local;
                // The function being compiled is the nearest declaration of its own name: it is
                // not published yet, and a function of that name further out must not stand in.
                if (expression and !self.default_expression) if (self.function) |own| {
                    if (!own.is_extension and std.mem.eql(u8, text, own.name.text(w.source))) return local;
                };
                const dotted = self.peek().kind == .dot;
                // The innermost scope around this code that declares the name gives it its
                // meaning: a module starts a path, anything else is the name itself.
                var at = w.currentScope();
                while (true) {
                    if (dotted) if (w.childModule(at, text, token.span.start)) |module| return self.qualifiedName(token, w.module_storage.module_count + module);
                    if (self.declaresName(text, w.scopeOf(at))) return .{ .token = token, .span = token.span, .scope = w.scopeOf(at) };
                    at = w.outerScope(at) orelse break;
                }
                if (!dotted) return local;
                const first = (try self.moduleNamed(token)) orelse return local;
                return self.qualifiedName(token, first);
            }
            // Only a following dot can qualify a name, so skip every lookup otherwise.
            if (!bundled or self.peek().kind != .dot or (expression and (self.findLocal(token.span.text(w.source)) != null or self.parameter(token.span.text(w.source)) != null))) return local;
            const edge = w.findAlias(token.span.text(w.source)) orelse return local;
            if (self.peek().kind != .dot) return local;
            if (!self.visible(edge.alias)) return w.fail(token.span, .unknown_name);
            w.noteName(token.span, edge.alias.start, .global, qualify.none);
            _ = try self.take(.dot, .expected_name);
            const member = try self.take(.identifier, .expected_name);
            return .{ .token = member, .span = .{ .start = token.span.start, .end = member.span.end }, .scope = w.scopeOf(edge.target), .qualified = true };
        }
        fn namedType(self: *Self, name: Name) ParseError!types.Type {
            const w = self.workspace;
            const text = name.token.span.text(w.source);
            // `Module.Alias`: an alias another module exports (RFC-0074).
            if (name.qualified) if (w.findTypeAliasIn(text, name.scope)) |alias| {
                if (!self.visible(alias.name)) return w.fail(name.span, .unsupported_type);
                if (name.sealed() and !alias.is_public) return w.fail(name.span, .private_name);
                w.noteName(name.token.span, alias.name.start, .global, qualify.none);
                return alias.value;
            };
            if (!name.qualified) {
                if (self.genericType(text)) |t| {
                    if (w.qualify) if (self.typeParameterSpan(text)) |declared| w.noteName(name.token.span, declared.start, .local, qualify.none);
                    return t;
                }
                // An effect parameter hides any same-named type instead of acting as one.
                if (self.genericParameter(text)) return w.fail(name.span, .unsupported_type);
                if (w.findTypeAliasIn(text, name.scope)) |alias| {
                    if (!self.visible(alias.name)) return w.fail(name.span, .unsupported_type);
                    w.noteName(name.token.span, alias.name.start, .global, qualify.none);
                    return alias.value;
                }
                if (std.meta.stringToEnum(types.Type, text)) |builtin| {
                    w.noteName(name.token.span, qualify.none, .builtin, qualify.none);
                    return builtin;
                }
                // `char` and `char32` are not reserved: a type the module declared under either
                // name is found first, as it was before the character types existed. Reading
                // the name as the builtin is recorded, so that a later declaration in the same
                // module cannot give it a second meaning (`parseDefinition`).
                if (w.catalogue.findNamedIn(text, w.source, name.scope) == null) if (Workspace.characterType(text)) |builtin| {
                    w.useCharacter(builtin);
                    w.noteName(name.token.span, qualify.none, .builtin, qualify.none);
                    return builtin;
                };
            }
            if (self.findGeneric(text, name.scope)) |id| if (w.generic_templates[id].kind != .function) {
                w.noteName(name.token.span, w.generic_templates[id].name.start, .global, qualify.none);
                return self.instantiateNamed(id, name);
            };
            const result = (try self.findNominal(text, name.scope, name.span)) orelse {
                // RFC-0085, I8: nor is `accessor`, the type of the unnamed parameter of a getter
                // and a setter, by the rule of the names below.
                if (!name.qualified and std.mem.eql(u8, text, "accessor")) {
                    if (self.stdDeclared(@backingInt(stdlib.Form.accessor_type), text, null)) return w.fail(name.span, .unsupported_type);
                    w.noteName(name.token.span, qualify.none, .builtin, qualify.none);
                    return self.accessorType(name.span);
                }
                // `rational` is not reserved: a declared type or alias of that name hides it.
                if (!name.qualified and std.mem.eql(u8, text, "rational")) {
                    w.noteName(name.token.span, qualify.none, .builtin, qualify.none);
                    return self.rationalType(name.span);
                }
                // Nor is `cancelable` (RFC-0082, P3.9), the type of a subscription.
                if (!name.qualified and std.mem.eql(u8, text, "cancelable")) {
                    if (self.stdDeclared(@backingInt(stdlib.Form.cancelable_type), text, null)) return w.fail(name.span, .unsupported_type);
                    w.noteName(name.token.span, qualify.none, .builtin, qualify.none);
                    return w.catalogue.internCancelable() catch w.fail(name.span, .type_limit);
                }
                // Nor is `session` (RFC-0087, P5.4), the type of the run's one session.
                if (!name.qualified and std.mem.eql(u8, text, "session")) {
                    if (self.stdDeclared(@backingInt(stdlib.Form.session_type), text, null)) return w.fail(name.span, .unsupported_type);
                    w.noteName(name.token.span, qualify.none, .builtin, qualify.none);
                    return w.catalogue.internGrant(.session) catch w.fail(name.span, .type_limit);
                }
                // Nor is `persistent_key` (RFC-0087, P5.5), the type of the keys the host grants.
                if (!name.qualified and std.mem.eql(u8, text, "persistent_key")) {
                    if (self.stdDeclared(@backingInt(stdlib.Form.persistent_key_type), text, null)) return w.fail(name.span, .unsupported_type);
                    w.noteName(name.token.span, qualify.none, .builtin, qualify.none);
                    return w.catalogue.internGrant(.key) catch w.fail(name.span, .type_limit);
                }
                // Nor are `reader` and `writer` (RFC-0086, P2.3), the types of handles.
                if (!name.qualified and (std.mem.eql(u8, text, "reader") or std.mem.eql(u8, text, "writer"))) {
                    const writer = text[0] == 'w';
                    if (self.stdDeclared(@backingInt(if (writer) stdlib.Form.writer_type else stdlib.Form.reader_type), text, null)) return w.fail(name.span, .unsupported_type);
                    w.noteName(name.token.span, qualify.none, .builtin, qualify.none);
                    return w.catalogue.internGrant(if (writer) .writer else .reader) catch w.fail(name.span, .type_limit);
                }
                // Nor are the names of RFC-0080: `void` is the unit type `tuple()`, `any` the top
                // type. One name has one meaning in a scope (RFC-0077 "Names"): where the module
                // declares the name further down, a use above it means that declaration, which is
                // not in reach yet, as it is for a template compiled after the declaration.
                if (!name.qualified and std.mem.eql(u8, text, "void")) {
                    if (self.stdDeclared(@backingInt(stdlib.Form.to_void), text, null)) return w.fail(name.span, .unsupported_type);
                    w.noteName(name.token.span, qualify.none, .builtin, qualify.none);
                    self.void_at = name.span.start;
                    return self.internTuple(&.{}, name.span);
                }
                if (!name.qualified and std.mem.eql(u8, text, "any")) {
                    if (self.stdDeclared(@backingInt(stdlib.Form.to_any), text, null)) return w.fail(name.span, .unsupported_type);
                    w.noteName(name.token.span, qualify.none, .builtin, qualify.none);
                    return types.Type.any;
                }
                // RFC-0091 (B3): `false` is the bottom type. The word is a literal, which no
                // program declares, so it means nothing else where a type is expected.
                if (!name.qualified and std.mem.eql(u8, text, "false")) {
                    w.noteName(name.token.span, qualify.none, .builtin, qualify.none);
                    return types.Type.bottom;
                }
                // `subtype(T)`, `castable_subtype(T)`, `concrete_subtype(T)` (RFC-0081), by the
                // same rule.
                if (!name.qualified and self.peek().kind == .left_paren) if (MetaKind.named(text)) |kind| {
                    if (self.stdDeclared(kind.bit(), text, null)) return w.fail(name.span, .unsupported_type);
                    return self.parseMetatype(name.token, kind);
                };
                return w.fail(name.span, .unsupported_type);
            };
            // The standard `accessor` is named where it is first written, which says nothing of where it is visible.
            if (w.standardAccessor()) |standard| if (result == standard) {
                w.noteName(name.token.span, qualify.none, .builtin, qualify.none);
                return result;
            };
            const declaration = catalogue.definition(result, self.definitions()).?;
            if (!self.visible(catalogue.declaredName(declaration) orelse return w.fail(name.span, .unsupported_type)) and !(declaration == .class and self.typesVisible())) return w.fail(name.span, .unsupported_type);
            if (name.sealed() and !catalogue.declaredPublic(declaration)) return w.fail(name.span, .private_name);
            self.noteType(name.token.span, result);
            return result;
        }

        fn rationalType(self: *Self, span: Span) ParseError!types.Type {
            return self.workspace.catalogue.internRational() catch self.workspace.fail(span, .type_limit);
        }

        /// `subtype(T)`, `castable_subtype(T)` or `concrete_subtype(T)` (RFC-0081), the cursor at
        /// the parenthesis. The two last need a class or interface. A signature read only to check
        /// it makes no type: the bound stands in, and is what such a signature names.
        fn parseMetatype(self: *Self, word: Token, kind: MetaKind) ParseError!types.Type {
            const w = self.workspace;
            _ = try self.take(.left_paren, .expected_type);
            self.skipNewlines();
            // A metatype of a metatype would read one more level of the native stack each time.
            if (self.in_metatype) return w.fail(word.span, .unsupported_type);
            self.in_metatype = true;
            const read = self.parseTypeValue();
            self.in_metatype = false;
            const bound = try read;
            self.skipNewlines();
            _ = try self.take(.right_paren, .expected_type);
            const shape = catalogue.definition(bound, self.definitions());
            const class = shape != null and shape.? == .class;
            if (kind != .subtype and !class) return w.fail(word.span, .unsupported_type);
            if (self.trial) return bound;
            return self.internMetatype(kind, bound, class, word.span);
        }

        fn metatypeHash(kind: MetaKind, bound: types.Type) u64 {
            return std.hash.Wyhash.hash(@backingInt(kind), std.mem.asBytes(&bound));
        }

        /// The struct of the metatype `kind` of `bound`: one for each in a compile, named by the
        /// first place that writes it, as public as its bound.
        fn internMetatype(self: *Self, kind: MetaKind, bound: types.Type, class: bool, span: Span) ParseError!types.Type {
            return self.internMetatypeIn(kind, bound, class, span, self.workspace.scope());
        }

        /// `internMetatype` named in `scope`: B4 (RFC-0092) names a metatype by the word of a
        /// file's library block, which lies in the file's scope and in no nested module's.
        fn internMetatypeIn(self: *Self, kind: MetaKind, bound: types.Type, class: bool, span: Span, scope: Span) ParseError!types.Type {
            const w = self.workspace;
            var same = w.metatype_table.walk(&w.metatype_slots, metatypeHash(kind, bound));
            while (same.next()) |index| {
                if (w.metatypes[index].kind == kind and w.metatypes[index].bound == bound) return w.metatypes[index].value;
            }
            if (w.metatype_count == w.metatypes.len) return w.fail(span, .type_limit);
            const arguments = try self.internTuple(&.{bound}, span);
            var held: [2]types.Field = undefined;
            var field_count: usize = 0;
            if (kind == .castable_concrete) {
                held[0] = .{ .name = span, .value_type = try self.testerType(bound, span) };
                // Two fields of a struct have two names: the construction's is the word's tail.
                held[1] = .{ .name = .{ .start = span.end - @as(u32, @intCast("concrete_subtype".len)), .end = span.end }, .value_type = try self.makerType(bound, span) };
                field_count = 2;
            } else if (kind == .concrete) {
                held[0] = .{ .name = span, .value_type = try self.makerType(bound, span) };
                field_count = 1;
            } else if (class) {
                held[0] = .{ .name = span, .value_type = try self.testerType(bound, span) };
                field_count = 1;
            }
            const value = w.catalogue.addRecordInstance(span, arguments, held[0..field_count], true, w.source, scope) catch |err| return w.fail(span, switch (err) {
                error.TypeLimit => .type_limit,
                error.FieldLimit => .field_limit,
                else => .unsupported_type,
            });
            w.catalogue.definitions[classIndex(value)].record.metatype = true;
            w.class_effects[classIndex(value)] = .{};
            const index = w.metatype_count;
            w.metatypes[index] = .{ .kind = kind, .bound = bound, .value = value };
            w.metatype_count += 1;
            w.metatype_by_type[classIndex(value)] = index;
            if (w.metatype_table.crowded()) {
                w.metatype_table.grow(&w.metatype_slots);
                for (w.metatypes[0..index], 0..) |earlier, at| w.metatype_table.enter(&w.metatype_slots, metatypeHash(earlier.kind, earlier.bound), @intCast(at));
            }
            w.metatype_table.enter(&w.metatype_slots, metatypeHash(kind, bound), index);
            return value;
        }

        /// The metatype whose struct is `value_type`, if it is one.
        fn metatypeOf(self: *const Self, value_type: types.Type) ?Metatype {
            const w = self.workspace;
            const id = @backingInt(value_type);
            if (id < catalogue.builtin_count or id - catalogue.builtin_count >= w.catalogue.count) return null;
            const index = w.metatype_by_type[id - catalogue.builtin_count];
            if (index >= w.metatype_count or w.metatypes[index].value != value_type) return null;
            return w.metatypes[index];
        }

        /// `function<computes><decides>(tuple(Bound), Bound)`: the test a type value holds.
        fn testerType(self: *Self, bound: types.Type, span: Span) ParseError!types.Type {
            return self.internCallable(.{ .parameters = try self.internTuple(&.{bound}, span), .result = bound, .decides = true }, span);
        }

        /// `function<allocates...>(tuple(option(Bound)), Bound)`: the construction a
        /// `concrete_subtype` value holds. It may do what building an instance of the bound may:
        /// allocate it, and what the bound states its construction does (RFC-0078).
        fn makerType(self: *Self, bound: types.Type, span: Span) ParseError!types.Type {
            var effect: Effect = .{ .transacts = true, .detail = types.heapDetail(false, false, true) };
            var stated = false;
            self.joinClassEffect(bound, &effect, &stated);
            const marker = self.workspace.catalogue.internOption(bound) catch |err| return self.workspace.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            return self.internCallable(.{ .parameters = try self.internTuple(&.{marker}, span), .result = bound, .transacts = effect.transacts, .detail = effect.detail }, span);
        }

        /// Whether a type value of `class` may be a `castable_subtype`: a class declared
        /// `<castable>`, or one below such a class.
        fn castableClass(self: *const Self, class: types.Type) bool {
            const shape = catalogue.definition(class, self.definitions()) orelse return false;
            if (shape != .class or catalogue.pendingClass(shape.class)) return false;
            return self.workspace.class_kinds[classIndex(class)] & class_castable != 0;
        }

        /// Whether a type value of `class` may be a `concrete_subtype`: a class declared
        /// `<concrete>` (every field has a default) that is not abstract. It is not inherited.
        fn concreteClass(self: *const Self, class: types.Type) bool {
            const shape = catalogue.definition(class, self.definitions()) orelse return false;
            if (shape != .class or catalogue.pendingClass(shape.class)) return false;
            return self.workspace.class_kinds[classIndex(class)] & class_concrete != 0;
        }

        /// The metatype the place being parsed expects a value of, if it expects one.
        fn metatypeExpected(self: *const Self) ?Metatype {
            const expected = self.expectedContext() orelse return null;
            return self.metatypeOf(expected);
        }

        /// The value of metatype `meta` that the type `name` is (RFC-0081): the struct holding
        /// the function the metatype asks of the class. A type of the bound and nothing else is
        /// one, and only a class or interface type that has been declared, and is not an
        /// instantiation of a parametric type, can be a type value of a class bound.
        fn typeValue(self: *Self, name: Name, meta: Metatype) ParseError!u32 {
            const w = self.workspace;
            const span = name.span;
            const named = try self.namedType(name);
            const shape = catalogue.definition(meta.bound, self.definitions());
            if (shape == null or shape.? != .class) {
                // `subtype(i64)`: the one subtype of a type that is not a class is itself.
                std.debug.assert(meta.kind == .subtype);
                if (named != meta.bound) return w.fail(span, .type_mismatch);
                return self.emit(.{ .span = span, .value_type = meta.value, .kind = .{ .aggregate = try self.reserveMembers(0, span) } });
            }
            const item = catalogue.definition(named, self.definitions()) orelse return w.fail(span, .type_mismatch);
            if (item != .class or !catalogue.assignable(named, meta.bound, self.definitions())) return w.fail(span, .type_mismatch);
            if (catalogue.pendingClass(item.class)) return w.fail(span, .unknown_name);
            // A witness is named by its class, and an instantiation's name is its template's.
            if (w.instanceOf(named) != null) return w.fail(span, .unsupported_type);
            if (meta.kind.casts() and !self.castableClass(named)) return w.fail(span, .not_castable);
            if (meta.kind.builds() and !self.concreteClass(named)) return w.fail(span, .not_concrete);
            // One function for each thing the value can do: the test, then the construction.
            const count: u32 = if (meta.kind == .castable_concrete) 2 else 1;
            var held: [2]u32 = undefined;
            for (0..count) |at| {
                const role: WitnessRole = if (meta.kind.builds() and at == meta.kind.makerField()) .make else .test_class;
                const field_type = catalogue.fieldAt(meta.value, @intCast(at), self.definitions(), self.fields()).?;
                const function = try self.typeWitness(role, meta.bound, named, field_type.value_type, span);
                held[at] = try self.emit(.{ .span = span, .value_type = field_type.value_type, .kind = .{ .function_value = function } });
            }
            const range = try self.reserveMembers(count, span);
            @memcpy(self.memberPool()[range.start..][0..count], held[0..count]);
            return self.emit(.{ .span = span, .value_type = meta.value, .kind = .{ .aggregate = range } });
        }

        /// Whether the declaration at `name` can be named from every module that imports its
        /// own: it is public, and so is every module declared in a file around it.
        fn reachesAll(self: *const Self, name: Span, is_public: bool) bool {
            if (!is_public) return false;
            const w = self.workspace;
            const count = w.module_storage.module_count;
            if (count == 0) return true;
            const table = w.module_storage.modules[0..count];
            const nested = w.nestedModules();
            var scope = modules.home(name, table, nested) orelse return false;
            for (0..types.limits.module_depth + 2) |_| {
                if (scope < count) return true;
                if (!nested[scope - count].is_public) return false;
                scope = modules.enclosing(scope, table, nested) orelse return false;
            }
            return false;
        }

        fn witnessHash(role: WitnessRole, bound: types.Type, class: types.Type) u64 {
            const words = [2]types.Type{ bound, class };
            return std.hash.Wyhash.hash(@backingInt(role), std.mem.asBytes(&words));
        }

        /// The function a type value of `class` holds for `role` and `bound`, made the first time
        /// it is asked for. It is named by the class, which no other function of its module may
        /// be (`duplicate_name`), and its parameter tells it from the other functions so named.
        fn typeWitness(self: *Self, role: WitnessRole, bound: types.Type, class: types.Type, value_type: types.Type, span: Span) ParseError!u32 {
            const w = self.workspace;
            // The witness is named by the class, in the class's module. Used from another, it
            // is public, which it can be when its class and its bound are.
            const name = catalogue.declaredName(catalogue.definition(class, self.definitions()).?).?;
            const bound_item = catalogue.definition(bound, self.definitions()).?;
            const exported = self.reachesAll(name, catalogue.declaredPublic(catalogue.definition(class, self.definitions()).?)) and w.instanceOf(bound) == null and self.reachesAll(catalogue.declaredName(bound_item).?, catalogue.declaredPublic(bound_item));
            if (!exported and w.homeOf(name) != w.homeOf(span)) return w.fail(span, .private_name);
            var same = w.witness_table.walk(&w.witness_slots, witnessHash(role, bound, class));
            while (same.next()) |index| {
                const entry = w.witnesses[index];
                if (entry.role == role and entry.bound == bound and entry.class == class) return entry.function;
            }
            if (w.witness_count == w.witnesses.len or w.runtime_functions.count == types.limits.functions) return w.fail(span, .function_limit);
            const shape = catalogue.definition(value_type, self.definitions()).?.callable;
            var definition: functions.Definition = .{ .name = name, .value_type = bound, .is_public = exported, .transacts = shape.transacts, .decides = shape.decides, .detail = shape.detail, .start = w.functions.node_count, .end = 0, .root = 0 };
            definition.parameters[0] = .{ .name = name, .value_type = catalogue.tupleElementAt(shape.parameters, 0, self.definitions(), w.catalogue.tuple_elements[0..w.catalogue.tuple_count]).? };
            definition.parameter_count = 1;
            // The body is compiled after whatever is being compiled now, published, and its
            // storage given back, as an anonymous function's is (`finishAnonymous`).
            const saved_function = self.function;
            const saved_class = self.method_class;
            const saved_depth = self.control_depth;
            const nodes = w.functions.node_count;
            const members = w.functions.member_count;
            const arguments = w.functions.argument_count;
            self.function = definition;
            self.method_class = null;
            self.control_depth = 0;
            defer {
                self.function = saved_function;
                self.method_class = saved_class;
                self.control_depth = saved_depth;
            }
            const root = switch (role) {
                .test_class => tested: {
                    const operand = try self.emitTemplate(.{ .node = .{ .span = span, .value_type = bound, .kind = .{ .integer = 0 } }, .input = .{ .parameter = 0 } });
                    if (class == bound) break :tested operand;
                    const is_one = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .instance_of = .{ .value = operand, .class = class } } });
                    _ = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .demand = is_one } });
                    break :tested try self.coerce(try self.emit(.{ .span = span, .value_type = class, .kind = .{ .downcast = operand } }), bound);
                },
                .make => made: {
                    // What `Class{}` compiles to (`closeAggregate`), with every field its default.
                    if (self.blocksUnknown(class)) return w.fail(span, .construction_cycle);
                    try self.constructionEffect(class, span);
                    const layout = catalogue.definition(class, self.definitions()).?.class.fields;
                    var roots: [types.limits.record_fields]u32 = undefined;
                    const count = try self.fieldRoots(.{ .kind = .record, .span = span, .value_type = class }, layout, &roots);
                    const range = try self.reserveArguments(roots[0..count], span);
                    const object = try self.emit(.{ .span = span, .value_type = class, .kind = .{ .object_new = .{ .arguments = range } } });
                    try self.emitBlockCalls(class, object);
                    break :made try self.coerce(object, bound);
                },
            };
            definition.root = root;
            definition.end = w.functions.node_count;
            definition.work = self.body(definition.start, root).work;
            const target = w.runtime_functions.publishAlias(definition, &w.functions, self.definitions(), w.bindings[0..w.binding_count], w.binding_cells[0..w.binding_count], w.node_count) catch |err| return w.fail(span, switch (err) {
                error.FunctionLimit => .function_limit,
                error.NodeLimit => .template_limit,
                error.MemberLimit => .aggregate_limit,
                error.ArgumentLimit => .call_argument_limit,
                error.GlobalLimit => .binding_limit,
            });
            w.functions.node_count = nodes;
            w.functions.member_count = members;
            w.functions.argument_count = arguments;
            const index = w.witness_count;
            w.witnesses[index] = .{ .role = role, .bound = bound, .class = class, .function = target.? };
            w.witness_count += 1;
            if (w.witness_table.crowded()) {
                w.witness_table.grow(&w.witness_slots);
                for (w.witnesses[0..index], 0..) |earlier, at| w.witness_table.enter(&w.witness_slots, witnessHash(earlier.role, earlier.bound, earlier.class), @intCast(at));
            }
            w.witness_table.enter(&w.witness_slots, witnessHash(role, bound, class), index);
            return target.?;
        }

        /// `Value[Instance]` through a `castable_subtype` value: its test, called in a failure
        /// context with the instance seen as the bound. The bracket is now open.
        fn startTypeCast(self: *Self, value: u32, meta: Metatype, open: Token) ParseError!bool {
            const w = self.workspace;
            if (!meta.kind.casts()) return w.fail(open.span, .not_castable);
            if (!self.failureContext()) return w.fail(open.span, .failure_context_required);
            const field = catalogue.fieldAt(meta.value, 0, self.definitions(), self.fields()).?;
            const test_value = try self.emit(.{ .span = open.span, .value_type = field.value_type, .kind = .{ .field = .{ .value = value, .index = 0 } } });
            self.operand_count -= 1;
            try self.pushOperator(.{ .kind = .invoke, .span = open.span, .function = test_value, .operand_base = self.operand_count, .selected = 1 });
            return true;
        }

        /// `Value{}` through a `concrete_subtype` value: an instance of its class, seen as the
        /// bound. The archetype is empty: the class's defaults are what it is built with.
        fn constructThrough(self: *Self, value: u32, open: Token) ParseError!u32 {
            const w = self.workspace;
            const meta = self.metatypeOf(self.node(value).value_type).?;
            if (!meta.kind.builds()) return w.fail(open.span, .not_concrete);
            const close = self.peek();
            if (close.kind != .right_brace) return w.fail(close.span, .not_concrete);
            self.cursor += 1;
            const field = catalogue.fieldAt(meta.value, meta.kind.makerField(), self.definitions(), self.fields()).?;
            const shape = catalogue.definition(field.value_type, self.definitions()).?.callable;
            try self.callEffect(open.span, shape.effects());
            const span: Span = .{ .start = open.span.start, .end = close.span.end };
            const maker = try self.emit(.{ .span = span, .value_type = field.value_type, .kind = .{ .field = .{ .value = value, .index = meta.kind.makerField() } } });
            const marker = catalogue.tupleElementAt(shape.parameters, 0, self.definitions(), w.catalogue.tuple_elements[0..w.catalogue.tuple_count]).?;
            var arguments = [1]u32{try self.emit(.{ .span = span, .value_type = marker, .kind = .{ .aggregate = try self.reserveMembers(0, span) } })};
            const range = try self.reserveArguments(&arguments, span);
            return self.emit(.{ .span = span, .value_type = shape.result, .kind = .{ .invoke = .{ .callable = maker, .arguments = range } } });
        }
        /// Whether a call of `name` already means something a program declared, so that a
        /// division builtin of the same name must stand aside.
        fn declaredCallee(self: *const Self, name: []const u8, scope: Span) bool {
            const w = self.workspace;
            if (self.findLocal(name) != null or self.parameter(name) != null or w.findSymbolIn(name, scope) != null) return true;
            if (w.findNativeIn(name, scope) != null or w.plainFunctionIn(name, scope) != null or w.catalogue.findNamedIn(name, w.source, scope) != null) return true;
            if (w.findTypeAliasIn(name, scope) != null or self.findGeneric(name, scope) != null) return true;
            // Inside an extension method its own name is not a callee either, nor inside an
            // anonymous function (a `Spawn` body is named by its keyword, RFC-0082).
            if (self.function) |function| if (!function.is_extension and !function.anonymous and std.mem.eql(u8, name, function.name.text(w.source))) return true;
            return false;
        }

        fn internTuple(self: *Self, elements: []const types.Type, span: Span) ParseError!types.Type {
            return self.workspace.catalogue.internTuple(elements) catch |err| return self.workspace.fail(span, switch (err) {
                error.TypeLimit => .type_limit,
                error.TupleLimit => .tuple_limit,
                error.InvalidType => .unsupported_type,
            });
        }

        fn internShape(self: *Self, frame: anytype, elements: []const types.Type) ParseError!types.Type {
            const w = self.workspace;
            if (frame.kind == .tuple) return self.internTuple(elements, frame.span);
            if (elements.len != @as(usize, if (frame.kind == .option or frame.kind == .task or frame.kind == .event or frame.kind == .awaitable or frame.kind == .signalable or frame.kind == .sticky_event or frame.kind == .subscribable_event) 1 else 2)) return w.fail(frame.span, .expected_type);
            // P3.9: the two kinds of event with more than an event's rendezvous.
            if (frame.kind == .sticky_event or frame.kind == .subscribable_event) return w.catalogue.internEventOf(.{ .value = elements[0], .kind = if (frame.kind == .sticky_event) .sticky else .subscribable }) catch |err| return w.fail(frame.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            // The interfaces a handle and an event implement (RFC-0082, P3.7).
            if (frame.kind == .awaitable or frame.kind == .signalable) return w.catalogue.internScheduledInterface(.{ .kind = if (frame.kind == .awaitable) .awaitable else .signalable, .value = elements[0] }) catch |err| return w.fail(frame.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            // An event whose `Signal` carries the one type written (RFC-0082, P3.2).
            if (frame.kind == .event) return w.catalogue.internEvent(elements[0]) catch |err| return w.fail(frame.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            // The handle of a task whose body yields the one type written (RFC-0082).
            if (frame.kind == .task) return w.catalogue.internTask(elements[0]) catch |err| return w.fail(frame.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            if (frame.kind == .option) return w.catalogue.internOption(elements[0]) catch |err| return w.fail(frame.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            // RFC-0087, P5.1 (W1): a map with single-key access only, keyed as a map is.
            if (frame.kind == .weak_map) return w.catalogue.internWeakMap(elements[0], elements[1]) catch |err| return w.fail(frame.span, switch (err) {
                error.TypeLimit => .type_limit,
                error.InvalidKey => .weak_map_key,
                error.InvalidType => .unsupported_type,
            });
            if (frame.kind != .map) return self.internCallable(.{ .parameters = elements[0], .result = elements[1], .transacts = frame.kind == .transacts or frame.kind == .transacts_decides, .decides = frame.kind == .callable_decides or frame.kind == .transacts_decides, .detail = frame.detail }, frame.span);
            return w.catalogue.internMap(elements[0], elements[1]) catch |err| return w.fail(frame.span, switch (err) {
                error.TypeLimit => .type_limit,
                error.InvalidKey => w.equalityCode(elements[0], .invalid_map_key),
                error.InvalidType => .unsupported_type,
            });
        }

        /// The narrowest function type that functions of the types `a` and `b` are both values
        /// of, if there is one: the wider of the two when one widens the other, else the same
        /// parameters and result with every effect of either (the Book's join of `if` arms,
        /// 13:626). Null for other types, and for effects that cannot stand together
        /// (`<decides>` with `<suspends>`).
        fn joinFunctions(self: *Self, a: types.Type, b: types.Type, span: Span) ParseError!?types.Type {
            const w = self.workspace;
            const tuples = w.catalogue.tuple_elements[0..w.catalogue.tuple_count];
            if (catalogue.widens(a, b, self.definitions(), tuples)) return b;
            if (catalogue.widens(b, a, self.definitions(), tuples)) return a;
            const left = catalogue.definition(a, self.definitions()) orelse return null;
            const right = catalogue.definition(b, self.definitions()) orelse return null;
            if (left != .callable or right != .callable) return null;
            if (left.callable.parameters != right.callable.parameters or left.callable.result != right.callable.result) return null;
            const one = left.callable.effects();
            const other = right.callable.effects();
            const reads = one.reads or other.reads;
            const writes = one.writes or other.writes;
            const allocates = one.allocates or other.allocates;
            const transacts = reads or writes or allocates;
            var detail: types.EffectDetail = if (transacts) types.heapDetail(reads, writes, allocates) else .{};
            detail.suspends = one.suspends or other.suspends;
            detail.converges = !(one.diverges or other.diverges);
            detail.predicts = !(one.dictates or other.dictates);
            const decides = one.decides or other.decides;
            if (!types.effectsCanonical(transacts, decides, detail)) return null;
            return try self.internCallable(.{ .parameters = left.callable.parameters, .result = left.callable.result, .transacts = transacts, .decides = decides, .detail = detail }, span);
        }
        fn internCallable(self: *Self, shape: types.Callable, span: Span) ParseError!types.Type {
            const parameters = catalogue.definition(shape.parameters, self.definitions()) orelse return self.workspace.fail(span, .unsupported_type);
            if (parameters != .tuple) return self.workspace.fail(span, .unsupported_type);
            if (parameters.tuple.end - parameters.tuple.start > types.limits.parameters) return self.workspace.fail(span, .parameter_limit);
            return self.workspace.catalogue.internCallable(shape) catch |err| return self.workspace.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
        }
        fn functionType(self: *Self, f: functions.Definition, span: Span) ParseError!types.Type {
            var parameters: [types.limits.parameters]types.Type = undefined;
            for (f.parameters[0..f.parameter_count], parameters[0..f.parameter_count]) |parameter_type, *target| target.* = parameter_type.value_type;
            const arguments = try self.internTuple(parameters[0..f.parameter_count], span);
            return self.internCallable(.{ .parameters = arguments, .result = f.value_type, .transacts = f.transacts, .decides = f.decides, .detail = f.detail }, span);
        }
        fn referenceTarget(self: *Self, id: u32, span: Span) ParseError!u32 {
            const w = self.workspace;
            const f = w.functions.definitions[id];
            if (f.runtime orelse f.alias_runtime) |target| return target;
            const target = w.runtime_functions.publishAlias(f, &w.functions, self.definitions(), w.bindings[0..w.binding_count], w.binding_cells[0..w.binding_count], w.node_count) catch |err| return w.fail(span, switch (err) {
                error.FunctionLimit => .function_limit,
                error.NodeLimit => .template_limit,
                error.MemberLimit => .aggregate_limit,
                error.ArgumentLimit => .call_argument_limit,
                error.GlobalLimit => .binding_limit,
            });
            if (target == null) return w.fail(span, .not_callable);
            w.functions.definitions[id].alias_runtime = target;
            return target.?;
        }

        fn parseFunction(self: *Self, name: Token, is_public: bool) ParseError!void {
            const w = self.workspace;
            if (w.functions.count + w.generic_count == types.limits.functions) return w.fail(name.span, .function_limit);
            var function: functions.Definition = .{ .name = name.span, .value_type = undefined, .is_public = is_public, .start = w.functions.node_count, .end = 0, .root = 0 };
            _ = try self.take(.left_paren, .expected_parameter);
            try self.parseParameters(&function, .parse);
            return self.finishFunction(&function);
        }

        /// `(Receiver:type).Name<public>(parameters)<effects>:Type = body` declares an extension
        /// method: a function whose first parameter is the receiver, called as `Value.Name(...)`.
        /// It is resolved statically like any function; nothing is dispatched.
        fn parseExtension(self: *Self) ParseError!void {
            const w = self.workspace;
            _ = try self.take(.left_paren, .expected_parameter);
            const receiver = try self.take(.identifier, .expected_parameter);
            if (reserved(receiver.span.text(w.source)) or (generatedName(receiver.span.text(w.source)) and w.libraryModule(receiver.span) == null)) return w.fail(receiver.span, .expected_parameter);
            try self.checkShadow(receiver, false);
            w.noteDeclaration(receiver.span, .local, qualify.none);
            const receiver_type = try self.parseType();
            _ = try self.take(.right_paren, .expected_parameter);
            _ = try self.take(.dot, .expected_name);
            const name = try self.take(.identifier, .expected_name);
            const text = name.span.text(w.source);
            if (reserved(text) or (generatedName(text) and w.libraryModule(name.span) == null)) return w.fail(name.span, .expected_name);
            // An extension method is a function of the module, called after a receiver.
            w.noteDeclaration(name.span, .global, qualify.none);
            const is_public = if (self.peek().kind == .less) try self.moduleAccess() else false;
            if (w.findAlias(text) != null or w.findSymbol(text) != null or w.findType(text) != null or w.findNativeIn(text, w.scope()) != null or w.findTypeAliasIn(text, w.scope()) != null or self.findGeneric(text, w.scope()) != null) return w.fail(name.span, .duplicate_name);
            // A member of the receiver's class always wins, so an extension of its name could never be called.
            if (catalogue.findField(receiver_type, text, self.definitions(), self.fields(), w.source) != null or self.builtinMember(receiver_type, text)) return w.fail(name.span, .duplicate_name);
            if (catalogue.definition(receiver_type, self.definitions())) |item| {
                if (item == .class and !catalogue.pendingClass(item.class) and w.findMethod(receiver_type, text) != null) return w.fail(name.span, .duplicate_name);
            }
            if (w.functions.count + w.generic_count == types.limits.functions) return w.fail(name.span, .function_limit);
            var function: functions.Definition = .{ .name = name.span, .value_type = undefined, .is_public = is_public, .is_extension = true, .start = w.functions.node_count, .end = 0, .root = 0 };
            function.parameters[0] = .{ .name = receiver.span, .value_type = receiver_type };
            function.defaults[0] = .{};
            function.parameter_count = 1;
            _ = try self.take(.left_paren, .expected_parameter);
            try self.parseParameters(&function, .parse);
            return self.finishFunction(&function);
        }

        /// The members every value of a type has without a declaration.
        fn builtinMember(self: *const Self, value_type: types.Type, name: []const u8) bool {
            if (TextMethod.named(value_type, name) != null) return true;
            if (value_type == .string) return std.mem.eql(u8, name, "Length");
            const item = catalogue.definition(value_type, self.definitions()) orelse return false;
            return switch (item) {
                .array, .map => std.mem.eql(u8, name, "Length"),
                .option => std.mem.eql(u8, name, "IsSet"),
                else => false,
            };
        }

        /// What follows the parameters of a function: effects, result type and body.
        fn finishFunction(self: *Self, declared: *functions.Definition) ParseError!void {
            const w = self.workspace;
            var function = declared.*;
            // Default values are templates of their own; the body starts after them.
            function.start = w.functions.node_count;
            const effect = try self.parseEffect(.expected_computes);
            function.transacts = effect.transacts;
            function.decides = effect.decides;
            function.detail = effect.detail;
            // RFC-0085, I7: `Name(...)<effects> := Body` is transparent, its result type the
            // body's. Until the body is compiled the type is not known, and nothing reads it:
            // the body cannot name the function (`transparent_recursion`) or `Return`.
            if (self.peek().kind == .colon and w.tokens[self.cursor + 1].kind == .equal) {
                self.cursor += 2;
                function.is_transparent = true;
                function.value_type = .i64;
                return self.finishBodyAs(&function, false);
            }
            const result = try self.parseResultType();
            function.value_type = result.value_type;
            _ = try self.take(.equal, .expected_equal);
            return self.finishBodyAs(&function, result.discards);
        }

        /// Consumes `<constructor>` if it is next.
        fn constructorSpecifier(self: *Self) bool {
            const w = self.workspace;
            if (self.peek().kind != .less or w.tokens[self.cursor + 1].kind != .identifier or w.tokens[self.cursor + 2].kind != .greater) return false;
            if (!std.mem.eql(u8, w.tokens[self.cursor + 1].span.text(w.source), "constructor")) return false;
            self.cursor += 3;
            return true;
        }

        /// `Name<constructor>(parameters)<effects> := Class{...}` declares a constructor function
        /// (RFC-0075): a function whose body is one archetype of `Class`. It is called like any
        /// function, and an archetype of `Class` or of a subclass may take its field values with
        /// `Name<constructor>(arguments)`. `...<effects>:Class = body` states the class instead,
        /// for a body that binds locals in a `Block{...}` before its archetype.
        fn parseConstructor(self: *Self, name: Token, is_public: bool) ParseError!void {
            const w = self.workspace;
            if (w.functions.count + w.generic_count == types.limits.functions) return w.fail(name.span, .function_limit);
            var function: functions.Definition = .{ .name = name.span, .value_type = undefined, .is_public = is_public, .is_constructor = true, .start = w.functions.node_count, .end = 0, .root = 0 };
            _ = try self.take(.left_paren, .expected_parameter);
            try self.parseParameters(&function, .parse);
            function.start = w.functions.node_count;
            const effect = try self.parseEffect(.expected_computes);
            function.transacts = effect.transacts;
            function.decides = effect.decides;
            function.detail = effect.detail;
            if (self.peek().kind == .colon and w.tokens[self.cursor + 1].kind == .equal) {
                // The archetype names the class; it is read again as the body.
                self.cursor += 2;
                const body_start = self.cursor;
                const class_name = try self.take(.identifier, .constructor_body);
                if (reserved(class_name.span.text(w.source))) return w.fail(class_name.span, .constructor_body);
                function.value_type = try self.namedType(try self.resolveTypeName(class_name));
                self.cursor = body_start;
            } else {
                function.value_type = try self.parseType();
                _ = try self.take(.equal, .expected_equal);
            }
            const item = catalogue.definition(function.value_type, self.definitions()) orelse return w.fail(name.span, .constructor_body);
            if (item != .class or item.class.is_interface or catalogue.pendingClass(item.class)) return w.fail(name.span, .constructor_body);
            return self.finishBody(&function);
        }

        /// Whether `class` is abstract: its constructor functions only ever lend their field values.
        fn abstractClass(self: *const Self, class: types.Type) bool {
            const item = catalogue.definition(class, self.definitions()) orelse return false;
            return item == .class and item.class.is_abstract;
        }

        /// Whether an archetype of `class` written here is the body of a constructor function of
        /// `class`; only there may an abstract class be named, and only as the body itself.
        fn constructs(self: *const Self, class: types.Type) bool {
            const function = self.function orelse return false;
            return function.is_constructor and function.value_type == class and !self.default_expression and self.workspace.anonymous_count == 0;
        }

        /// A constructor function's template is field values, then one `object_new` of exactly
        /// its class, then the calls of that class's block clauses: delegation takes the first
        /// part and leaves the rest to the archetype that delegates.
        fn checkConstructor(self: *Self, function: functions.Definition) ParseError!void {
            const w = self.workspace;
            const root = w.functions.nodes[function.root];
            if (root.input != .operation or root.node.kind != .object_new or root.node.value_type != function.value_type) return w.fail(function.name, .constructor_body);
            if (w.archetype_new != function.root or w.archetype_end != function.end) return w.fail(function.name, .constructor_body);
            // A `Return` would leave whatever archetype this body is expanded into, with another instance.
            for (w.functions.nodes[function.start..function.end]) |entry| {
                if (entry.input == .operation and entry.node.kind == .exit) return w.fail(entry.node.span, .constructor_body);
            }
            if (!self.abstractClass(function.value_type)) return;
            // Naming the abstract class was allowed for the body; no other instance of it is built.
            for (w.functions.nodes[function.start..function.root]) |entry| {
                if (entry.input == .operation and entry.node.kind == .object_new and entry.node.value_type == function.value_type) return w.fail(entry.node.span, .abstract_instance);
            }
        }

        /// The body of a function whose signature has been read, and its publication.
        fn finishBody(self: *Self, declared: *functions.Definition) ParseError!void {
            return self.finishBodyAs(declared, false);
        }
        /// `discards`: the result was written `void`, so the body's value is dropped.
        fn finishBodyAs(self: *Self, declared: *functions.Definition, discards: bool) ParseError!void {
            const w = self.workspace;
            var function = declared.*;
            const name: Token = .{ .kind = .identifier, .span = function.name };
            // A function of the same name must differ in parameter types and agree on failure.
            const ours = parameterTypes(&function);
            var others = w.functions.namesakes(name.span.text(w.source), w.source, w.scope());
            while (others.next()) |index| {
                const other = &w.functions.definitions[index];
                if (other.parameter_count == function.parameter_count and blk: {
                    for (other.parameters[0..other.parameter_count], function.parameters[0..function.parameter_count]) |a, b| if (a.value_type != b.value_type) break :blk false;
                    break :blk true;
                }) return w.fail(name.span, .duplicate_name);
                // RFC-0076 (D16): two definitions must be distinct, so that no value fits both
                // and the one a call reaches never depends on the static type of its argument.
                // A plain call never reaches a method, so only an extension method is checked
                // against one. Where a class still to be declared decides, its declaration does.
                if (other.parameter_count == function.parameter_count and (!other.is_method or function.is_extension)) {
                    const theirs = parameterTypes(other);
                    switch (self.signaturesOverlap(theirs[0..other.parameter_count], ours[0..function.parameter_count])) {
                        .apart => {},
                        .overlap => return w.fail(name.span, self.relatedCode(theirs[0..other.parameter_count], ours[0..function.parameter_count])),
                        .pending => {
                            var first = w.functions.functionNamesakes(name.span.text(w.source), w.source, w.scope());
                            const group = if (first.next()) |earliest| w.functions.definitions[earliest].name.start else name.span.start;
                            try self.noteLateOverload(group, 0, other.name, theirs[0..other.parameter_count]);
                            try self.noteLateOverload(group, 0, name.span, ours[0..function.parameter_count]);
                        },
                    }
                }
                // A name is called either as `Name(...)` or as `Value.Name(...)`, never both.
                if (!other.is_method and other.is_extension != function.is_extension) return w.fail(name.span, .duplicate_name);
                if (other.decides != function.decides and !other.is_method) return w.fail(name.span, .overload_conflict);
            }
            self.function = function;
            w.archetype_new = no_member;
            const locals = try self.bindPatterns(function);
            const root = if (discards) try self.discardedBody(function.name) else if (function.is_transparent) try self.parseExpression(null) else try self.coerce(try self.parseExpression(function.value_type), function.value_type);
            w.local_count = locals;
            // A transparent function's type is its body's (RFC-0085, I7).
            if (function.is_transparent) function.value_type = self.node(root).value_type;
            if (std.mem.eql(u8, name.span.text(w.source), "ToString") and !self.textFunction(function)) return w.fail(name.span, .to_string_signature);
            function.root = root;
            function.end = w.functions.node_count;
            function.work = self.body(function.start, root).work;
            std.debug.assert(function.root >= function.start and function.root < function.end);
            try self.checkPredicting(function);
            if (function.is_constructor) {
                try self.checkConstructor(function);
                function.given = w.archetype_given;
                std.debug.assert(function.given >= function.start and function.given <= function.root);
            }
            // RFC-0091: a function called before its declaration is published even when its
            // body is its parameters alone, so that the calls have something to name.
            const forwarded = w.runtime_functions.findForward(function.name);
            // A constructor function of an abstract class is never called: it stays a template.
            if (!(function.is_constructor and self.abstractClass(function.value_type))) function.runtime = (if (forwarded != null) w.runtime_functions.publishAlias(function, &w.functions, self.definitions(), w.bindings[0..w.binding_count], w.binding_cells[0..w.binding_count], w.node_count) else w.runtime_functions.publish(function, &w.functions, self.definitions(), w.bindings[0..w.binding_count], w.binding_cells[0..w.binding_count], w.node_count)) catch |err| return w.fail(name.span, switch (err) {
                error.FunctionLimit => .function_limit,
                error.NodeLimit => .template_limit,
                error.MemberLimit => .aggregate_limit,
                error.ArgumentLimit => .call_argument_limit,
                error.GlobalLimit => .binding_limit,
            });
            if (forwarded) |entry| try self.resolveForward(entry, function);
            w.functions.publishIn(function, w.source, w.scope());
            self.function = null;
        }

        /// RFC-0091: the declaration that calls before it named is published. It is what its
        /// header said it would be, and the module has emitted nothing since the first call:
        /// the calls and the function have one availability.
        fn resolveForward(self: *Self, entry: u32, function: functions.Definition) ParseError!void {
            const w = self.workspace;
            const forward = &w.runtime_functions.forward[entry];
            const header = forward.definition;
            const same = header.parameter_count == function.parameter_count and header.value_type == function.value_type and header.transacts == function.transacts and header.decides == function.decides and std.meta.eql(header.detail, function.detail) and !function.is_transparent and !function.is_extension and !function.is_constructor and !function.overloaded and blk: {
                for (header.parameters[0..header.parameter_count], function.parameters[0..function.parameter_count]) |a, b| if (a.value_type != b.value_type) break :blk false;
                break :blk true;
            };
            const runtime = function.runtime orelse return self.forwardFailure(forward.call, function.name);
            if (!same) return self.forwardFailure(forward.call, function.name);
            if (w.runtime_functions.definitions[runtime].available_at != forward.available_at) {
                const failure = w.fail(forward.call, .forward_value_between);
                w.diagnostic.related = function.name;
                return failure;
            }
            forward.resolved = runtime;
        }

        /// Whether some value could be passed for a parameter of type `a` and for one of type
        /// `b`: the types are the same, one is a subtype of the other, or a class could still be
        /// declared below both (one is an interface and the other is not a final class). For
        /// function types, whether some function is a value of both (`functionsOverlap`). An
        /// option and `logic` overlap too: the Book's `false` is both (06:1777), so it does not
        /// tell them apart, though the empty option of Forbic is `option{}`.
        fn overlapping(self: *const Self, a: types.Type, b: types.Type) bool {
            const definitions_now = self.definitions();
            if (a == b or catalogue.subtype(a, b, definitions_now) or catalogue.subtype(b, a, definitions_now)) return true;
            if (self.optionBesideLogic(a, b)) return true;
            const first = catalogue.definition(a, definitions_now) orelse return false;
            const second = catalogue.definition(b, definitions_now) orelse return false;
            if (first == .callable and second == .callable) return self.functionsOverlap(first.callable, second.callable);
            if (first != .class or second != .class) return false;
            if (!first.class.is_interface and !second.class.is_interface) return false;
            return !(first.class.is_final and !first.class.is_interface) and !(second.class.is_final and !second.class.is_interface);
        }

        /// Whether one function could be a value of both function types (RFC-0076 D16, `fix2`):
        /// a function with fewer effects is a value of every type that allows more (RFC-0078),
        /// so effects never keep two types apart; a parameter of the function may be a class
        /// above both parameters there, and its result a class below both results. Two
        /// overloads that take such types would let one argument reach either.
        fn functionsOverlap(self: *const Self, a: types.Callable, b: types.Callable) bool {
            const definitions_now = self.definitions();
            const tuples = self.workspace.catalogue.tuple_elements[0..self.workspace.catalogue.tuple_count];
            if (a.result != b.result) {
                const ra = catalogue.definition(a.result, definitions_now) orelse return false;
                const rb = catalogue.definition(b.result, definitions_now) orelse return false;
                if (ra != .class or rb != .class or !self.overlapping(a.result, b.result)) return false;
            }
            if (a.parameters == b.parameters) return true;
            const pa = catalogue.definition(a.parameters, definitions_now).?.tuple;
            const pb = catalogue.definition(b.parameters, definitions_now).?.tuple;
            if (pa.end - pa.start != pb.end - pb.start) return false;
            for (tuples[pa.start..pa.end], tuples[pb.start..pb.end]) |x, y| {
                if (x == y) continue;
                // A class that both lie below: their supertypes meet.
                var above_x = catalogue.Supertypes.of(x, definitions_now) orelse return false;
                const above_y = catalogue.Supertypes.of(y, definitions_now) orelse return false;
                above_x.reached.setIntersection(above_y.reached);
                if (above_x.reached.findFirstSet() == null) return false;
            }
            return true;
        }

        /// Whether one of `a` and `b` is `logic` and the other an option.
        fn optionBesideLogic(self: *const Self, a: types.Type, b: types.Type) bool {
            const definitions_now = self.definitions();
            const other = if (a == .logic) b else if (b == .logic) a else return false;
            const item = catalogue.definition(other, definitions_now) orelse return false;
            return item == .option;
        }

        /// The diagnostic of two overloads that overlap at every position: an option beside
        /// `logic` somewhere says so, since no class is involved there.
        fn relatedCode(self: *const Self, a: []const types.Type, b: []const types.Type) types.Diagnostic.Code {
            std.debug.assert(a.len == b.len);
            for (a, b) |x, y| if (self.optionBesideLogic(x, y)) return .option_logic_overloads;
            return .related_overloads;
        }

        /// RFC-0076 D16 between the parameter types of two overloads: apart where one position
        /// keeps them apart, else pending where a position waits for a class, else overlapping.
        fn signaturesOverlap(self: *const Self, a: []const types.Type, b: []const types.Type) Overlap {
            std.debug.assert(a.len == b.len);
            var result: Overlap = .overlap;
            for (a, b) |x, y| {
                if (x == y) continue;
                if (!self.typeSettled(x) or !self.typeSettled(y)) {
                    result = .pending;
                } else if (!self.overlapping(x, y)) return .apart;
            }
            return result;
        }

        /// Whether what `overlapping` says of `value_type` is final: it is not a class still to be
        /// declared (its supertypes and `<final>` are unknown), nor a function type that takes or
        /// gives one. `functionsOverlap` reads only the classes there; other types it compares
        /// for equality.
        fn typeSettled(self: *const Self, value_type: types.Type) bool {
            const definitions_now = self.definitions();
            const item = catalogue.definition(value_type, definitions_now) orelse return true;
            switch (item) {
                .class => |class| return !catalogue.pendingClass(class),
                .callable => |callable| {
                    if (!settledClass(callable.result, definitions_now)) return false;
                    const parameters = catalogue.definition(callable.parameters, definitions_now).?.tuple;
                    for (self.workspace.catalogue.tuple_elements[parameters.start..parameters.end]) |element| {
                        if (!settledClass(element, definitions_now)) return false;
                    }
                    return true;
                },
                else => return true,
            }
        }
        fn settledClass(value_type: types.Type, definitions_now: []const types.Definition) bool {
            const item = catalogue.definition(value_type, definitions_now) orelse return true;
            return item != .class or !catalogue.pendingClass(item.class);
        }

        /// Keeps overload `name` of `group` and `block`, whose parameter types are `parameters`,
        /// for `recheckLateOverloads`, once.
        fn noteLateOverload(self: *Self, group: u32, block: u32, name: Span, parameters: []const types.Type) ParseError!void {
            const w = self.workspace;
            for (w.late_overloads[0..w.late_overload_count]) |*entry| {
                if (entry.name.start == name.start and entry.group == group and entry.block == block and std.mem.eql(types.Type, entry.parameters[0..entry.count], parameters)) return;
            }
            if (w.late_overload_count == w.late_overloads.len) return w.fail(name, .function_limit);
            const entry = &w.late_overloads[w.late_overload_count];
            entry.* = .{ .group = group, .block = block, .name = name, .count = @intCast(parameters.len), .parameters = undefined };
            @memcpy(entry.parameters[0..parameters.len], parameters);
            w.late_overload_count += 1;
        }

        /// RFC-0076 D16 for overloads declared above a class they name, once a class is declared:
        /// two that it shows to be related are refused at the later one. Once no two wait for a
        /// class, every pair kept has been decided and the list is emptied.
        fn recheckLateOverloads(self: *Self) ParseError!void {
            const w = self.workspace;
            const entries = w.late_overloads[0..w.late_overload_count];
            var waiting = false;
            for (entries, 0..) |*first, at| for (entries[at + 1 ..]) |*second| {
                // One declaration is never its own overload, wherever it is compiled again.
                if (first.group != second.group or first.block != second.block or first.count != second.count or first.name.start == second.name.start) continue;
                switch (self.signaturesOverlap(first.parameters[0..first.count], second.parameters[0..second.count])) {
                    .apart => {},
                    .pending => waiting = true,
                    .overlap => return w.fail(if (first.name.start < second.name.start) second.name else first.name, self.relatedCode(first.parameters[0..first.count], second.parameters[0..second.count])),
                }
            };
            if (!waiting) w.late_overload_count = 0;
        }

        /// After `Name :=`, decides between a value (inferred binding) and a type or
        /// definition (alias, `enum`, `struct`) by looking at the next one or two tokens.
        fn valueAhead(self: *const Self) bool {
            const w = self.workspace;
            const first = w.tokens[self.cursor + 2];
            if (first.kind != .identifier) return first.kind != .left_bracket;
            const text = first.span.text(w.source);
            if (std.mem.eql(u8, text, "enum") or std.mem.eql(u8, text, "struct") or std.mem.eql(u8, text, "class") or std.mem.eql(u8, text, "interface")) return false;
            const after = w.tokens[self.cursor + 3].kind;
            // `Age := type{_X:i64 where ...}` declares a refinement type (RFC-0083).
            if (after == .left_brace and self.refinementWord(text)) return false;
            // `array{..}`, `tuple{..}`, `option{..}`, `map{..}` and `Record{..}` construct values.
            if (after == .left_brace or after == .dot) return true;
            // `Kinds := castable_subtype(Component)` names a metatype (RFC-0081), unless the
            // program has a callee of that name: `subtype` is not reserved.
            if (after == .left_paren and MetaKind.named(text) != null and !self.declaredCallee(text, w.scope()) and !self.usedName(text) and !self.meantAround(text)) return false;
            // `task(T)` and `event(T)` (RFC-0082) are types where the program declares neither
            // name; `event(T){}` builds a value.
            if (after == .left_paren and self.taskTypeAt(first, w.tokens[self.cursor + 3])) {
                const close = self.stdAfterBracket(self.cursor + 3) orelse return false;
                return close < w.token_count and w.tokens[close].kind == .left_brace and eventWord(text);
            }
            if (after == .left_paren) return !(std.mem.eql(u8, text, "tuple") or std.mem.eql(u8, text, "option") or std.mem.eql(u8, text, "map") or std.mem.eql(u8, text, "function"));
            // `Wide := function<transacts>(...)` (RFC-0081): `function` is reserved, so its
            // effects can only open a function type.
            if (after == .less and std.mem.eql(u8, text, "function")) return false;
            if (std.meta.stringToEnum(types.Type, text) != null or self.genericType(text) != null) return false;
            if (w.findTypeAliasIn(text, w.scope()) != null or w.findType(text) != null) return false;
            // A class that is declared late (RFC-0073) is a type from the start, like the classes
            // the pre-pass reserves: `Name := Late` above its declaration is an alias of it too.
            if (w.late_count != 0) if (w.lateIn(text, w.currentScope())) |entry| if (w.late[entry].kind == .class) return false;
            if (bundled and w.current_nested != types.no_parent and self.typeAround(text)) return false;
            // `R := rational` names the type unless the program already means something by it.
            if (std.mem.eql(u8, text, "rational") and !self.declaredCallee(text, w.scope()) and !self.usedName(text) and !self.meantAround(text)) return false;
            // `T := char` aliases the character type unless the program has a value of that name,
            // which is what the word meant before the character types existed.
            if (Workspace.characterType(text) != null and self.findLocal(text) == null and w.findSymbolIn(text, w.scope()) == null and w.plainFunctionIn(text, w.scope()) == null and !self.meantAround(text)) return false;
            // `Ints := Box[i64]` aliases an instantiated type; `B := Box[i64]{...}` builds a value
            // and `B := Box[i64][Value]` casts one.
            if (self.templateAround(text)) |id| if (w.generic_templates[id].kind != .function and after == .left_bracket) {
                var at = self.cursor + 4;
                var depth: u32 = 1;
                while (depth != 0 and at < w.token_count) : (at += 1) switch (w.tokens[at].kind) {
                    .left_bracket, .left_paren => depth += 1,
                    .right_bracket, .right_paren => depth -= 1,
                    .eof => return true,
                    else => {},
                };
                return at >= w.token_count or w.tokens[at].kind == .left_brace or w.tokens[at].kind == .left_bracket;
            };
            return true;
        }
        /// The template that `text` names here: one this scope declares, or, inside a module
        /// declared in a file, the nearest one a scope around it declares (RFC-0074).
        fn templateAround(self: *const Self, text: []const u8) ?u32 {
            const w = self.workspace;
            if (self.findGeneric(text, w.scope())) |id| return id;
            if (!bundled or w.current_nested == types.no_parent) return null;
            var at = w.currentScope();
            while (w.outerScope(at)) |around| : (at = around) {
                if (self.findGeneric(text, w.scopeOf(around))) |id| return id;
                if (self.declaresName(text, w.scopeOf(around))) return null;
            }
            return null;
        }
        /// Whether a scope around the nested module being compiled declares `text`: a name the
        /// compiler would otherwise resolve itself (`rational`, `char`) then means that
        /// declaration, as it does in the scope that makes it. An extension method is no such
        /// declaration (`declaresName`), and a type or an alias was found by `typeAround`.
        fn meantAround(self: *const Self, text: []const u8) bool {
            const w = self.workspace;
            if (!bundled or w.current_nested == types.no_parent) return false;
            var at = w.currentScope();
            while (w.outerScope(at)) |around| : (at = around) {
                if (self.declaresName(text, w.scopeOf(around))) return true;
            }
            return false;
        }
        /// After `Name :=`, whether the rest of the line is a path through modules to a type or an
        /// alias (`Lib.Geo.Grid`): the right-hand side of an alias, where `Lib.Limit` is a value.
        fn typePathAhead(self: *Self) bool {
            const w = self.workspace;
            const first = w.tokens[self.cursor + 2];
            if (first.kind != .identifier or w.tokens[self.cursor + 3].kind != .dot) return false;
            const saved = self.cursor;
            defer self.cursor = saved;
            self.cursor += 3;
            // A path that does not resolve is reported by whoever compiles the line.
            const name = self.resolveTypeName(first) catch return false;
            if (!name.qualified) return false;
            const text = name.token.span.text(w.source);
            // `Ints := Lib.Kit.Box[i64]` aliases an instantiation of a template another module
            // declares (RFC-0080), as `Ints := Box[i64]` does for one of this module. With `{`
            // or `[` after the arguments it builds or casts a value instead.
            if (self.peek().kind == .left_bracket) if (self.findGeneric(text, name.scope)) |id| if (w.generic_templates[id].kind != .function) {
                var at = self.cursor + 1;
                var depth: u32 = 1;
                while (depth != 0 and at < w.token_count) : (at += 1) switch (w.tokens[at].kind) {
                    .left_bracket, .left_paren => depth += 1,
                    .right_bracket, .right_paren => depth -= 1,
                    .eof => return false,
                    else => {},
                };
                // What ends the declaration is what `parseDefinition` takes as its end: a line
                // break, a separator, or the end of the file or nested module (`peek`).
                if (at >= w.token_count) return true;
                self.cursor = @intCast(at);
                const next = self.peek().kind;
                return next == .eof or next == .newline or next == .separator;
            };
            const after = self.peek().kind;
            if (after != .eof and after != .newline and after != .separator) return false;
            return w.findTypeAliasIn(text, name.scope) != null or w.catalogue.findNamedIn(text, w.source, name.scope) != null;
        }

        /// Whether the nearest declaration of `text` in the scopes around this code is a type
        /// or an alias: what `Name := text` then gives a second name to.
        fn typeAround(self: *const Self, text: []const u8) bool {
            const w = self.workspace;
            var at = w.currentScope();
            while (true) {
                const scope = w.scopeOf(at);
                if (w.findTypeAliasIn(text, scope) != null or w.catalogue.findNamedIn(text, w.source, scope) != null) return true;
                if (w.late_count != 0) if (w.lateIn(text, at)) |entry| if (w.late[entry].kind == .class) return true;
                if (self.declaresName(text, scope)) return false;
                at = w.outerScope(at) orelse return false;
            }
        }

        /// Whether a module this one is `using` exports `text`, as `usingScope` finds it.
        fn usedName(self: *const Self, text: []const u8) bool {
            const w = self.workspace;
            if (!bundled) return false;
            for (w.using_edges[0..w.using_count]) |edge| {
                if (!w.insideScope(w.currentScope(), edge.module)) continue;
                const target = w.scopeOf(edge.target);
                if (w.plainFunctionIn(text, target) != null or w.findSymbolIn(text, target) != null or w.catalogue.findNamedIn(text, w.source, target) != null or self.findGeneric(text, target) != null) return true;
            }
            return false;
        }

        /// `Name := expression` binds an immutable value whose type is inferred.
        fn parseInferredBinding(self: *Self, name: Token, is_public: bool) ParseError!void {
            const w = self.workspace;
            if (w.binding_count == w.bindings.len) return w.fail(name.span, .binding_limit);
            _ = try self.take(.colon, .expected_equal);
            _ = try self.take(.equal, .expected_equal);
            self.pending_binding = name.span;
            const root = try self.parseExpression(null);
            self.pending_binding = .{ .start = 0, .end = 0 };
            if (self.valuelessAt(root)) return w.fail(self.node(root).span, .if_without_else);
            w.insertSymbol(.{ .name = name.span, .node = root, .value_type = self.node(root).value_type, .is_public = is_public }, null);
        }

        /// Whether `word` before a brace opens a refinement type (RFC-0083): it is `type`, and the
        /// program gives the word no meaning of its own, so that `type{...}` builds no value of it.
        fn refinementWord(self: *const Self, word: []const u8) bool {
            const w = self.workspace;
            if (!std.mem.eql(u8, word, "type")) return false;
            return !self.declaredCallee(word, w.scope()) and !self.usedName(word) and !self.meantAround(word) and w.findType(word) == null;
        }

        /// `Name := type{_X:Base where Constraint, ...}` (RFC-0083), the cursor at `type`. `Base`
        /// is `i64` or `float`; each constraint compares the placeholder with a literal of the
        /// base by `<`, `<=`, `>` or `>=`, on either side, and there is at most one bound on
        /// each side. Anything else is `refinement_bound`, at the constraint.
        fn parseRefinement(self: *Self, name: Token, is_public: bool) ParseError!void {
            const w = self.workspace;
            std.debug.assert(self.function == null);
            _ = try self.take(.identifier, .unsupported_type);
            const open = try self.take(.left_brace, .unexpected_token);
            self.skipNewlines();
            const placeholder = try self.take(.identifier, .refinement_bound);
            _ = try self.take(.colon, .refinement_bound);
            const base_token = self.peek();
            const base = try self.parseTypeValue();
            if (base != .i64 and base != .float) return w.fail(base_token.span, .refinement_bound);
            const where = self.peek();
            if (where.kind != .identifier or !std.mem.eql(u8, where.span.text(w.source), "where")) return w.fail(where.span, .refinement_bound);
            self.cursor += 1;
            var low: ?RefinementBound = null;
            var high: ?RefinementBound = null;
            while (true) {
                self.skipNewlines();
                const first = self.peek();
                const left_placeholder = first.kind == .identifier and std.mem.eql(u8, first.span.text(w.source), placeholder.span.text(w.source));
                const left: RefinementBound = if (left_placeholder) placeholder_value: {
                    self.cursor += 1;
                    break :placeholder_value .{ .bits = 0 };
                } else try self.refinementLiteral(base);
                const operator = self.peek();
                const op: types.CompareOp = switch (operator.kind) {
                    .less => .less,
                    .less_equal => .less_equal,
                    .greater => .greater,
                    .greater_equal => .greater_equal,
                    else => return w.fail(operator.span, .refinement_bound),
                };
                self.cursor += 1;
                const second = self.peek();
                const right_placeholder = second.kind == .identifier and std.mem.eql(u8, second.span.text(w.source), placeholder.span.text(w.source));
                // Exactly one side is the placeholder: the other is the bound.
                if (left_placeholder == right_placeholder) return w.fail(if (left_placeholder) second.span else first.span, .refinement_bound);
                const right: RefinementBound = if (right_placeholder) placeholder_value: {
                    self.cursor += 1;
                    break :placeholder_value .{ .bits = 0 };
                } else try self.refinementLiteral(base);
                // As `_X op Literal`: a literal on the left turns the comparison round.
                const facing: types.CompareOp = if (left_placeholder) op else switch (op) {
                    .less => .greater,
                    .less_equal => .greater_equal,
                    .greater => .less,
                    .greater_equal => .less_equal,
                    else => unreachable,
                };
                var bound = if (left_placeholder) right else left;
                bound.open = facing == .less or facing == .greater;
                const side = if (facing == .less or facing == .less_equal) &high else &low;
                if (side.* != null) return w.fail(first.span, .refinement_bound);
                side.* = bound;
                self.skipNewlines();
                if (self.peek().kind == .right_brace) break;
                _ = try self.take(.comma, .refinement_bound);
            }
            _ = try self.take(.right_brace, .unexpected_token);
            if (self.peek().kind != .eof and self.peek().kind != .newline and self.peek().kind != .separator) return w.fail(self.peek().span, .unexpected_token);
            var refinement: types.Refinement = .{ .name = name.span, .base = base, .low = 0, .high = 0, .is_public = is_public };
            if (base == .i64) {
                // An integer bound is closed: `_X > 3` is `_X >= 4`. One past the range is no value.
                var lowest: i64 = if (low) |bound| @bitCast(bound.bits) else std.math.minInt(i64);
                var highest: i64 = if (high) |bound| @bitCast(bound.bits) else std.math.maxInt(i64);
                if (low != null and low.?.open) lowest = std.math.add(i64, lowest, 1) catch return w.fail(open.span, .refinement_bound);
                if (high != null and high.?.open) highest = std.math.sub(i64, highest, 1) catch return w.fail(open.span, .refinement_bound);
                refinement.low = @bitCast(lowest);
                refinement.high = @bitCast(highest);
            } else {
                refinement.low = if (low) |bound| bound.bits else @bitCast(-std.math.inf(f64));
                refinement.high = if (high) |bound| bound.bits else @bitCast(std.math.inf(f64));
                refinement.low_open = low != null and low.?.open;
                refinement.high_open = high != null and high.?.open;
            }
            // No value between the bounds: the type could never be given one.
            if (!refinement.wellFormed()) return w.fail(open.span, .refinement_bound);
            _ = w.catalogue.addRefinementIn(refinement, w.source, w.scope()) catch |err| return w.fail(name.span, switch (err) {
                error.TypeLimit => .type_limit,
                error.DuplicateName => .duplicate_name,
                error.InvalidName => .expected_name,
                error.InvalidType => .refinement_bound,
            });
        }

        /// A bound of a refinement over `base`, the cursor at it: an integer literal for `i64`;
        /// a float literal or `Inf` for `float`; either after a `-`. Zero is zero, whatever its
        /// sign, as the Book says (11:691).
        fn refinementLiteral(self: *Self, base: types.Type) ParseError!RefinementBound {
            const w = self.workspace;
            var token = self.peek();
            const start = token.span;
            const negative = token.kind == .minus;
            if (negative) {
                self.cursor += 1;
                token = self.peek();
            }
            self.cursor += 1;
            if (base == .i64) {
                if (token.kind != .integer) return w.fail(start, .refinement_bound);
                const magnitude = lexer.integerMagnitude(token.span.text(w.source)) orelse return w.fail(token.span, .integer_range);
                if (magnitude > @as(u64, std.math.maxInt(i64)) + @intFromBool(negative)) return w.fail(token.span, .integer_range);
                const value: i64 = @intCast(if (negative) -@as(i128, magnitude) else @as(i128, magnitude));
                return .{ .bits = @bitCast(value) };
            }
            const magnitude: f64 = switch (token.kind) {
                .floating => value: {
                    const value = std.fmt.parseFloat(f64, lexer.floatDigits(token.span.text(w.source))) catch return w.fail(token.span, .invalid_number);
                    if (!std.math.isFinite(value)) return w.fail(token.span, .float_range);
                    break :value value;
                },
                .identifier => if (std.mem.eql(u8, token.span.text(w.source), "Inf")) std.math.inf(f64) else return w.fail(start, .refinement_bound),
                else => return w.fail(start, .refinement_bound),
            };
            const value = if (negative) -magnitude else magnitude;
            return .{ .bits = @bitCast(if (value == 0) @as(f64, 0) else value) };
        }

        fn parseDefinition(self: *Self, name: Token, is_public: bool) ParseError!void {
            const w = self.workspace;
            // A module that has already read `char` as the builtin cannot declare its own.
            if (Workspace.characterType(name.span.text(w.source))) |builtin| if (w.usedCharacter(builtin)) return w.fail(name.span, .duplicate_name);
            _ = try self.take(.colon, .expected_equal);
            _ = try self.take(.equal, .expected_equal);
            const next = self.peek();
            const word = if (next.kind == .identifier) next.span.text(w.source) else "";
            if (next.kind == .identifier and w.tokens[self.cursor + 1].kind == .left_brace and self.refinementWord(word)) return self.parseRefinement(name, is_public);
            if (next.kind == .left_bracket or (next.kind == .identifier and !std.mem.eql(u8, word, "enum") and !std.mem.eql(u8, word, "struct") and !std.mem.eql(u8, word, "class") and !std.mem.eql(u8, word, "interface"))) {
                if (w.type_alias_count == w.type_aliases.len) return w.fail(name.span, .type_limit);
                const aliased = try self.parseTypeValue();
                const after = self.peek().kind;
                if (after != .eof and after != .newline and after != .separator) return w.fail(self.peek().span, .unexpected_token);
                w.type_aliases[w.type_alias_count] = .{ .name = name.span, .value = aliased, .is_public = is_public };
                w.type_alias_count += 1;
                return;
            }
            const keyword = try self.take(.identifier, .unsupported_type);
            if (std.mem.eql(u8, keyword.span.text(w.source), "enum")) return self.parseEnum(name, is_public);
            if (std.mem.eql(u8, keyword.span.text(w.source), "class")) return self.parseClass(name, false);
            if (std.mem.eql(u8, keyword.span.text(w.source), "interface")) return self.parseClass(name, true);
            if (!std.mem.eql(u8, keyword.span.text(w.source), "struct")) return w.fail(keyword.span, .unsupported_type);
            return self.parseRecord(name, is_public);
        }

        /// Declares every top-level `Name := class{...}` before anything is parsed, so that class
        /// fields, parameters and results may name classes declared later in the source.
        fn reserveClasses(self: *Self) ParseError!void {
            const w = self.workspace;
            var depth: u32 = 0;
            var at: usize = 0;
            @memset(w.late_using[0..w.module_storage.import_count], false);
            // The braces of a nested module do not hide its declarations: the modules open in
            // table order, which is source order, and each closes at the end of its text.
            const nested = w.nestedModules();
            var open: [types.limits.module_depth]u32 = undefined;
            var open_count: usize = 0;
            var next_module: u32 = 0;
            var opened = false;
            while (at + 3 < w.token_count) : (at += 1) {
                const after_open = opened;
                opened = false;
                switch (w.tokens[at].kind) {
                    .left_brace => if (depth == 0 and next_module < nested.len and w.tokens[at].span.end == nested[next_module].source.start) {
                        std.debug.assert(open_count < open.len);
                        open[open_count] = next_module;
                        open_count += 1;
                        next_module += 1;
                        opened = true;
                    } else {
                        depth += 1;
                    },
                    .left_paren, .left_bracket => depth += 1,
                    .right_brace => if (depth == 0 and open_count != 0 and w.tokens[at].span.start == nested[open[open_count - 1]].source.end) {
                        open_count -= 1;
                    } else {
                        depth -|= 1;
                    },
                    .right_paren, .right_bracket => depth -|= 1,
                    else => {},
                }
                if (depth != 0 or w.tokens[at].kind != .identifier) continue;
                const starts = at == 0 or after_open or w.tokens[at - 1].kind == .newline or w.tokens[at - 1].kind == .separator or (bundled and modules.owner(w.tokens[at - 1].span, w.module_storage.modules[0..w.module_storage.module_count]) != modules.owner(w.tokens[at].span, w.module_storage.modules[0..w.module_storage.module_count]));
                if (!starts) continue;
                // `using{Alias}` in a bundle whose files declare no modules: from here on the
                // public names of that file are seen unqualified (`lateSeen`). Newlines may
                // stand inside the braces, as `parseUsing` reads them. A malformed one is
                // refused where it is parsed.
                if (bundled and nested.len == 0 and w.tokens[at + 1].kind == .left_brace and std.mem.eql(u8, w.tokens[at].span.text(w.source), "using")) {
                    var inside = at + 2;
                    while (inside < w.token_count and w.tokens[inside].kind == .newline) inside += 1;
                    var close = inside + 1;
                    while (close < w.token_count and w.tokens[close].kind == .newline) close += 1;
                    // RFC-0093: `using{/Domain/Folder}` names the module of the import recorded there.
                    if (close < w.token_count and w.tokens[inside].kind == .path and w.tokens[close].kind == .right_brace) {
                        const holder = modules.owner(w.tokens[at].span, w.module_storage.modules[0..w.module_storage.module_count]) orelse continue;
                        const range = w.module_storage.modules[holder].imports;
                        for (w.module_storage.imports[range.start..range.end], range.start..) |edge, index| if (edge.alias.start == edge.alias.end and edge.path.start == w.tokens[inside].span.start and edge.path.end == w.tokens[inside].span.end) {
                            w.late_using[index] = true;
                        };
                        continue;
                    }
                    if (close < w.token_count and w.tokens[inside].kind == .identifier and w.tokens[close].kind == .right_brace) {
                        const holder = modules.owner(w.tokens[at].span, w.module_storage.modules[0..w.module_storage.module_count]) orelse continue;
                        const range = w.module_storage.modules[holder].imports;
                        for (w.module_storage.imports[range.start..range.end], range.start..) |edge, index| if (std.mem.eql(u8, edge.alias.text(w.source), w.tokens[inside].span.text(w.source))) {
                            w.late_using[index] = true;
                        };
                        continue;
                    }
                }
                var cursor = at + 1;
                var is_public = false;
                if (w.tokens[cursor].kind == .less) {
                    if (cursor + 3 >= w.token_count or w.tokens[cursor + 1].kind != .identifier or w.tokens[cursor + 2].kind != .greater) continue;
                    is_public = std.mem.eql(u8, w.tokens[cursor + 1].span.text(w.source), "public");
                    if (!is_public and !std.mem.eql(u8, w.tokens[cursor + 1].span.text(w.source), "internal")) continue;
                    cursor += 3;
                }
                const module: u32 = if (bundled) modules.owner(w.tokens[at].span, w.module_storage.modules[0..w.module_storage.module_count]) orelse continue else 0;
                // The module of the file that holds the declaration, if one does (RFC-0074):
                // the innermost one open here.
                const inner: u32 = if (open_count != 0) open[open_count - 1] else types.no_parent;
                // `Box[T:type] := class{...}`: what it makes is declared when it is named.
                if (w.tokens[cursor].kind == .left_bracket) {
                    var close = cursor + 1;
                    var nesting: u32 = 1;
                    while (close < w.token_count and nesting != 0) : (close += 1) switch (w.tokens[close].kind) {
                        .left_bracket, .left_paren => nesting += 1,
                        .right_bracket, .right_paren => nesting -= 1,
                        .eof, .newline, .left_brace => break,
                        else => {},
                    };
                    if (nesting == 0 and close + 2 < w.token_count and w.tokens[close].kind == .colon and w.tokens[close + 1].kind == .equal and w.tokens[close + 2].kind == .identifier) {
                        const made = w.tokens[close + 2].span.text(w.source);
                        if (std.mem.eql(u8, made, "class") or std.mem.eql(u8, made, "interface") or std.mem.eql(u8, made, "struct")) try w.noteLate(at, module, inner, .template, is_public);
                    }
                    continue;
                }
                // `Ints := Box[i64]` and `Same := Ints`: an alias of a type that is declared late
                // stands for it in a list of supertypes. Only a statement that is such an alias
                // is noted: a value built from a parametric type is not.
                if (w.late_count != 0 and cursor + 3 < w.token_count and w.tokens[cursor].kind == .colon and w.tokens[cursor + 1].kind == .equal and w.tokens[cursor + 2].kind == .identifier) {
                    var last = cursor + 2;
                    while (last + 2 < w.token_count and w.tokens[last + 1].kind == .dot and w.tokens[last + 2].kind == .identifier) last += 2;
                    if (w.lateSeen(last, module, inner)) |aliased| {
                        var end = last + 1;
                        if (w.late[aliased].kind == .template and w.tokens[end].kind == .left_bracket) {
                            var nesting: u32 = 0;
                            while (end < w.token_count) : (end += 1) switch (w.tokens[end].kind) {
                                .left_bracket, .left_paren => nesting += 1,
                                .right_bracket, .right_paren => {
                                    nesting -|= 1;
                                    if (nesting == 0) break;
                                },
                                .eof, .newline => break,
                                else => {},
                            };
                            end = if (nesting == 0 and end < w.token_count and w.tokens[end].kind == .right_bracket) end + 1 else w.token_count;
                        } else if (w.late[aliased].kind == .template) end = w.token_count;
                        if (end < w.token_count and (w.tokens[end].kind == .newline or w.tokens[end].kind == .separator or w.tokens[end].kind == .eof)) try w.noteLate(at, module, inner, .alias, is_public);
                    }
                }
                if (cursor + 3 >= w.token_count or w.tokens[cursor].kind != .colon or w.tokens[cursor + 1].kind != .equal or w.tokens[cursor + 2].kind != .identifier or (!std.mem.eql(u8, w.tokens[cursor + 2].span.text(w.source), "class") and !std.mem.eql(u8, w.tokens[cursor + 2].span.text(w.source), "interface"))) continue;
                const name = w.tokens[at];
                if (reserved(name.span.text(w.source))) return w.fail(name.span, .expected_name);
                // `class(Box[i64])`: a supertype is an earlier definition, and an instantiation is
                // made only when it is named. Such a class is declared when it is first needed
                // (`reserveLate`), and so is every class below one of those.
                var ahead = cursor + 3;
                while (ahead + 2 < w.token_count and w.tokens[ahead].kind == .less and w.tokens[ahead + 1].kind == .identifier and w.tokens[ahead + 2].kind == .greater) ahead += 3;
                const late = late: {
                    if (ahead >= w.token_count or w.tokens[ahead].kind != .left_paren) break :late false;
                    var nesting: u32 = 0;
                    while (ahead < w.token_count) : (ahead += 1) switch (w.tokens[ahead].kind) {
                        .left_bracket => break :late true,
                        .identifier => if (w.late_count != 0 and w.lateSeen(ahead, module, inner) != null) break :late true,
                        .left_paren => nesting += 1,
                        .right_paren => {
                            nesting -= 1;
                            if (nesting == 0) break :late false;
                        },
                        .eof, .newline, .left_brace => break :late false,
                        else => {},
                    };
                    break :late false;
                };
                if (late) {
                    try w.noteLate(at, module, inner, .class, is_public);
                    continue;
                }
                if (bundled and modules.owner(name.span, w.module_storage.modules[0..w.module_storage.module_count]) == null) return w.fail(name.span, .unknown_name);
                const scope = if (bundled) w.scopeOf(w.homeOf(name.span)) else w.scope();
                const reserved_class = w.catalogue.reserveClass(name.span, is_public, w.source, scope) catch |err| return w.fail(name.span, switch (err) {
                    error.TypeLimit => .type_limit,
                    error.DuplicateName => .duplicate_name,
                    error.InvalidName => .expected_name,
                });
                if (w.uniqueAhead(cursor + 3)) w.catalogue.markUnique(reserved_class);
            }
        }

        /// `Name := class{ Field:type, var Field:type = default }`: its values are instances with
        /// identity, built by `Name{Field := value}`; only `var` fields can be assigned.
        fn parseClass(self: *Self, name: Token, is_interface: bool) ParseError!void {
            _ = try self.parseClassAs(name, is_interface, null);
        }

        /// Parses a class or interface from the token after its keyword. With `arguments` it is
        /// the instantiation of a parametric type for them (RFC-0073), named like its template.
        fn parseClassAs(self: *Self, name: Token, is_interface: bool, arguments: ?types.Type) ParseError!types.Type {
            const w = self.workspace;
            // The keyword: it names the clauses of a class whose only clauses are live fields.
            const class_word = w.tokens[self.cursor - 1];
            // The class has its place in the catalogue before its declaration is compiled: from
            // the pre-pass, from being named (`reserveInstance`, `reserveLate`), or, for a class
            // that is declared late and was not named before, from here.
            const reserved_class: ?types.Type = if (arguments == null) w.catalogue.findNamedIn(name.span.text(w.source), w.source, w.scope()) orelse try self.reserveLate(w.lateIn(name.span.text(w.source), w.currentScope()) orelse return w.fail(name.span, .unknown_name), name.span) else reserved: {
                const context = self.generic.?;
                break :reserved w.instances[w.findInstance(context.template, context.arguments[0..w.generic_templates[context.template].parameter_count]).?].value;
            };
            if (reserved_class) |early| std.debug.assert(catalogue.definition(early, self.definitions()).? == .class and catalogue.pendingClass(catalogue.definition(early, self.definitions()).?.class));
            // `class<abstract><final>(Parent){...}`
            var shape: catalogue.ClassShape = .{ .is_interface = is_interface, .is_abstract = is_interface };
            // `class<computes>`, `interface<transacts>`: the effect of building an instance, beyond
            // allocating it (RFC-0078). It bounds the block clauses and binds every construction.
            var effect_words: u16 = 0;
            var is_unique = false;
            var is_concrete = false;
            var is_castable = false;
            // RFC-0087, P5.2: `<persistable>`, whose rules are checked once the program is read.
            var is_persistable = false;
            // B4 (RFC-0092): a restricted hierarchy (Book 10:2904, 11:1673).
            var is_final_super = false;
            var is_final_super_base = false;
            while (self.peek().kind == .less) {
                _ = try self.take(.less, .unsupported_specifier);
                const word = try self.take(.identifier, .unsupported_specifier);
                _ = try self.take(.greater, .unsupported_specifier);
                const text = word.span.text(w.source);
                if (std.meta.stringToEnum(EffectWord, text)) |effect_word| {
                    // A type is not declared in a failure context or in one that can wait.
                    if (effect_word == .decides or effect_word == .suspends or effect_word == .converges) return w.fail(word.span, .class_effect_specifier);
                    try self.addEffectWord(&effect_words, word, effect_word);
                    continue;
                }
                if (is_interface) return w.fail(word.span, .unsupported_specifier);
                // Every class here has identity and compares by it, which is what `<unique>` asks for.
                // Every class can already be the target of a cast, which is all `<castable>` could
                // add until there are `castable_subtype` constraints. `<concrete>` is checked below.
                if (std.mem.eql(u8, text, "abstract") and !shape.is_abstract) shape.is_abstract = true else if (std.mem.eql(u8, text, "final") and !shape.is_final) shape.is_final = true else if (std.mem.eql(u8, text, "unique") and !is_unique) is_unique = true else if (std.mem.eql(u8, text, "concrete") and !is_concrete) is_concrete = true else if (std.mem.eql(u8, text, "castable") and !is_castable) is_castable = true else if (std.mem.eql(u8, text, "persistable") and !is_persistable) is_persistable = true else if (std.mem.eql(u8, text, "final_super") and !is_final_super) is_final_super = true else if (std.mem.eql(u8, text, "final_super_base") and !is_final_super_base) is_final_super_base = true else return w.fail(word.span, .unsupported_specifier);
            }
            if (shape.is_abstract and shape.is_final) return w.fail(name.span, .unsupported_specifier);
            // What is comparable was decided when the class was reserved, from these same words.
            std.debug.assert(reserved_class == null or catalogue.definition(reserved_class.?, self.definitions()).?.class.is_unique == is_unique);
            var inherited: u32 = 0;
            var parent_fields: Span = .{ .start = 0, .end = 0 };
            // What the superclass already is, and what the listed interfaces add to that.
            var parent_above: catalogue.Supertypes = .{};
            var through: catalogue.Supertypes = .{};
            if (self.peek().kind == .left_paren) {
                // `class(Parent, Interface, ...)`: at most one superclass, which gives the fields.
                _ = try self.take(.left_paren, .unexpected_token);
                while (true) {
                    const parent_token = try self.take(.identifier, .expected_type);
                    // A parametric type does not inherit from one of its parameters: what its
                    // instances are made of would then depend on the argument.
                    if (self.genericParameter(parent_token.span.text(w.source))) return w.fail(parent_token.span, .invalid_parent);
                    const parent = try self.namedType(try self.resolveTypeName(parent_token));
                    const item = catalogue.definition(parent, self.definitions()) orelse return w.fail(parent_token.span, .invalid_parent);
                    if (item != .class or catalogue.pendingClass(item.class) or item.class.is_final or parent == reserved_class.?) return w.fail(parent_token.span, .invalid_parent);
                    if (item.class.is_interface) {
                        if (shape.interface_count == shape.interfaces.len) return w.fail(parent_token.span, .invalid_interface);
                        for (shape.interfaces[0..shape.interface_count]) |earlier| if (earlier == parent) return w.fail(parent_token.span, .invalid_interface);
                        shape.interfaces[shape.interface_count] = parent;
                        shape.interface_count += 1;
                        _ = catalogue.supertypes(parent, self.definitions(), &through.reached);
                    } else {
                        if (is_interface or shape.parent != null) return w.fail(parent_token.span, .invalid_interface);
                        // An instance seen as its superclass is compared by identity (RFC-0076, D15).
                        if (item.class.is_unique and !is_unique) return w.fail(name.span, .not_unique);
                        shape.parent = parent;
                        parent_fields = item.class.fields;
                        inherited = parent_fields.end - parent_fields.start;
                        // Inherited fields keep their defaults.
                        const start = w.catalogue.field_count;
                        if (start + inherited > w.field_defaults.len) return w.fail(parent_token.span, .field_limit);
                        @memcpy(w.field_defaults[start..][0..inherited], w.field_defaults[parent_fields.start..parent_fields.end]);
                        @memcpy(w.field_access[start..][0..inherited], w.field_access[parent_fields.start..parent_fields.end]);
                        @memcpy(w.field_final[start..][0..inherited], w.field_final[parent_fields.start..parent_fields.end]);
                        @memcpy(w.field_live[start..][0..inherited], w.field_live[parent_fields.start..parent_fields.end]);
                        @memcpy(w.field_write[start..][0..inherited], w.field_write[parent_fields.start..parent_fields.end]);
                        w.staged_inherited = inherited;
                    }
                    if (self.peek().kind != .comma) break;
                    _ = try self.take(.comma, .unexpected_token);
                }
                _ = try self.take(.right_paren, .unexpected_token);
            }
            const class = reserved_class.?;
            // What a type value of this class can be (RFC-0081): `<castable>` is inherited, so a
            // class below a castable one is castable; `<concrete>` is not, and an abstract class
            // is never built.
            const castable_above = if (shape.parent) |parent| w.class_kinds[classIndex(parent)] & class_castable != 0 else false;
            w.class_kinds[classIndex(class)] = (if (is_castable or castable_above) class_castable else 0) | (if (is_concrete and !shape.is_abstract) class_concrete else 0);
            try self.declareFinalSuper(class, name, shape.parent, is_final_super, is_final_super_base, arguments != null);
            {
                // What the supertypes state is the least this class may state, and what it has
                // when it states nothing: building it builds what they declared.
                var above: Effect = .{};
                var above_stated = false;
                for (shape.interfaces[0..shape.interface_count]) |interface| self.joinClassEffect(interface, &above, &above_stated);
                if (shape.parent) |parent| self.joinClassEffect(parent, &above, &above_stated);
                var own: ClassEffect = .{ .stated = above_stated, .effect = above };
                if (effect_words != 0) {
                    own = .{ .stated = true, .effect = effectOfWords(effect_words) orelse return w.fail(name.span, .expected_computes) };
                    if (above_stated) if (missingEffect(above.set().heap(), own.effect.set(), narrower_codes)) |code| return w.fail(name.span, code);
                }
                w.class_effects[classIndex(class)] = own;
            }
            // From here to its last signature the class collects what the code that uses it
            // needs: a parametric type it names meanwhile is reserved and completed afterwards.
            std.debug.assert(w.open_count < w.open_classes.len);
            w.open_classes[w.open_count] = class;
            w.open_count += 1;
            w.declaring += 1;
            _ = try self.take(.left_brace, .unexpected_token);
            self.skipNewlines();
            // Only a class that lists interfaces asks what its superclass already is.
            if (shape.interface_count != 0) if (shape.parent) |parent| {
                parent_above = catalogue.Supertypes.of(parent, self.definitions()).?;
            };
            var count: u32 = 0;
            // The fields of the interfaces this class adds to its superclass become fields of its
            // own, placed after the superclass's: once each, however many paths lead to the
            // interface. A public superclass field of the same name, type and mutability is that field.
            if (!is_interface and shape.interface_count != 0) for (0..w.slot_count) |slot| {
                if (w.slot_kind[slot] != .getter) continue;
                const owner = w.slots[slot].owner;
                if (!through.has(owner) or parent_above.has(owner)) continue;
                const text = w.slots[slot].name.text(w.source);
                const info = w.slot_field[slot];
                if (shape.parent) |parent| if (catalogue.findField(parent, text, self.definitions(), self.fields(), w.source)) |existing| {
                    const have = catalogue.classFieldAt(parent, existing, self.definitions(), self.fields()).?;
                    if (have.value_type != info.value_type or have.is_var != info.is_var or w.field_access[parent_fields.start + existing] != w.slot_access[slot]) return w.fail(name.span, .duplicate_name);
                    if (w.slot_access[slot] == .internal and !self.sameModule(parent, owner)) return w.fail(name.span, .duplicate_name);
                    // A final interface field has the interface's default, which a field declared elsewhere need not have.
                    if (info.is_final) return w.fail(name.span, .final_field);
                    // An interface's `var` field is assigned by whoever holds the interface, so
                    // the field that stands for it cannot keep its assignment to the class.
                    if (info.is_var and w.field_write[parent_fields.start + existing] != w.slot_access[slot]) return w.fail(name.span, .inaccessible_member);
                    continue;
                };
                // Two unrelated interfaces that each declare the name would need a qualifier to tell apart.
                for (w.record_fields[0..count]) |earlier| if (std.mem.eql(u8, earlier.name.text(w.source), text)) return w.fail(name.span, .duplicate_name);
                if (inherited + count == w.record_fields.len) return w.fail(name.span, .field_limit);
                const field_index = w.catalogue.field_count + inherited + count;
                if (field_index == w.field_defaults.len) return w.fail(name.span, .field_limit);
                w.record_fields[count] = .{ .name = w.slots[slot].name, .value_type = info.value_type, .is_var = info.is_var };
                w.field_defaults[field_index] = info.default;
                // The field is as visible as the interface made it.
                w.field_access[field_index] = w.slot_access[slot];
                w.field_write[field_index] = w.slot_access[slot];
                w.field_final[field_index] = info.is_final;
                w.field_live[field_index] = false;
                count += 1;
            };
            const acquired = count;
            w.staged_fields = count;
            var overridden: std.StaticBitSet(types.limits.record_fields) = .empty;
            // Methods are compiled once the class has its fields, so their bodies can use them.
            var method_cursors: [max_class_methods]u32 = undefined;
            var method_count: u32 = 0;
            // `Block{...}` clauses run on every new instance, so they too wait for the fields.
            var block_cursors: [max_class_blocks]u32 = undefined;
            var block_count: u32 = 0;
            // Live fields (RFC-0084, P4.2): their guards are attached in the block clauses.
            var live_fields: [max_class_blocks]LiveField = undefined;
            var live_count: u32 = 0;
            // Generic methods (RFC-0081) are declared as they are met; the members they must not
            // collide with are known once the body has been read.
            const first_generic = w.generic_count;
            while (self.peek().kind != .right_brace) {
                if (self.blockAhead()) {
                    // Only a class is built, so only a class has code to run when it is.
                    if (is_interface) return w.fail(self.peek().span, .invalid_interface);
                    if (block_count == block_cursors.len) return w.fail(self.peek().span, .method_limit);
                    block_cursors[block_count] = self.cursor;
                    block_count += 1;
                    try self.skipMember();
                } else if (self.methodAhead()) {
                    if (method_count == method_cursors.len) return w.fail(self.peek().span, .method_limit);
                    method_cursors[method_count] = self.cursor;
                    method_count += 1;
                    try self.skipMember();
                } else if (self.genericMethodAhead()) {
                    try self.declareGenericMethod(class, is_interface);
                } else if (self.accessorFieldAhead()) {
                    // RFC-0085, I8: `var F<getter(G)><setter(S)>:T = external{}`, a field without a cell.
                    try self.declareAccessorField(class, &shape, parent_fields, w.record_fields[0..count]);
                } else if (try self.liveTypeFieldAhead()) {
                    // RFC-0084, P4.3: `var In->Out:F = E`, and a field whose type is a function.
                    if (is_interface) return w.fail(self.peek().span, .live_target);
                    if (live_count + 2 > live_fields.len) return w.fail(self.peek().span, .field_limit);
                    try self.declareLiveTypeField(class, inherited, parent_fields, &count, &live_fields, &live_count, class_word);
                } else {
                    var field = try self.take(.identifier, .expected_field);
                    const is_var = std.mem.eql(u8, field.span.text(w.source), "var");
                    // `var<private> Name<public>`: the specifier on `var` is who may assign the field.
                    var write_stated: ?Access = null;
                    if (is_var and self.peek().kind == .less) {
                        _ = try self.take(.less, .unsupported_specifier);
                        const word = try self.take(.identifier, .unsupported_specifier);
                        _ = try self.take(.greater, .unsupported_specifier);
                        write_stated = Access.named(word.span.text(w.source)) orelse return w.fail(word.span, .unsupported_specifier);
                    }
                    if (is_var) field = try self.take(.identifier, .expected_field);
                    // RFC-0084, P4.2: `var live F:T = G` and the live-only `live F:T = G`.
                    const is_live = std.mem.eql(u8, field.span.text(w.source), "live") and self.peek().kind == .identifier;
                    if (is_live) {
                        // An interface's fields are its implementations' to keep.
                        if (is_interface) return w.fail(self.peek().span, .live_target);
                        field = try self.take(.identifier, .expected_field);
                    }
                    if (w.localQualified(field.span.start)) return w.fail(field.span, .invalid_qualifier);
                    // The hidden raw fields of RFC-0084 P4.3 have these names (C37).
                    if (rawNamed(field.span.text(w.source)) and w.libraryModule(field.span) == null) return w.fail(field.span, .expected_field);
                    var stated: ?Access = null;
                    var is_override = false;
                    var is_final = false;
                    while (self.peek().kind == .less) {
                        _ = try self.take(.less, .unsupported_specifier);
                        const word = try self.take(.identifier, .unsupported_specifier);
                        _ = try self.take(.greater, .unsupported_specifier);
                        const text = word.span.text(w.source);
                        if (std.mem.eql(u8, text, "override") and !is_override) is_override = true else if (std.mem.eql(u8, text, "final") and !is_final) is_final = true else if (Access.named(text) != null and stated == null) stated = Access.named(text) else return w.fail(word.span, .unsupported_specifier);
                    }
                    // An interface's members are its contract: declared once, and `<public>` or
                    // `<internal>` (RFC-0076), never kept to a class.
                    if (is_interface and (write_stated != null or is_override)) return w.fail(field.span, .invalid_interface);
                    if (is_interface) if (stated) |access| if (access != .public and access != .internal) return w.fail(field.span, .invalid_interface);
                    const value_type = try self.parseType();
                    // A field restated live would have two guards' worth of meaning.
                    if (is_live and is_override) return w.fail(field.span, .live_target);
                    if (is_override) {
                        // `Name<override>:Type = value` restates an inherited field to give it another default.
                        const text = field.span.text(w.source);
                        const index: u32 = if (shape.parent) |parent| catalogue.findField(parent, text, self.definitions(), self.fields(), w.source) orelse no_member else no_member;
                        const target: u32 = if (index != no_member) index else for (w.record_fields[0..acquired], 0..) |earlier, position| {
                            if (std.mem.eql(u8, earlier.name.text(w.source), text)) break inherited + @as(u32, @intCast(position));
                        } else return w.fail(field.span, if (self.accessorAbove(&shape, text)) .accessor_override else .unexpected_override);
                        // A hidden raw field (RFC-0084, P4.3) is no member to restate.
                        if (target < inherited) if (self.liveTypeOfField(shape.parent.?, target)) |entry| if (entry.hidden and entry.raw == target) return w.fail(field.span, .unexpected_override);
                        const existing: types.Field = if (target < inherited) self.fields()[parent_fields.start + target] else w.record_fields[target - inherited];
                        w.noteName(field.span, existing.name.start, .member, qualify.none);
                        // A live field's guard gives its value (RFC-0084, P4.2), whatever the restatement says.
                        if (w.field_live[w.catalogue.field_count + target]) return w.fail(field.span, .live_assigned);
                        if (existing.value_type != value_type or existing.is_var != is_var) return w.fail(field.span, .override_mismatch);
                        if (stated) |access| if (access != w.field_access[w.catalogue.field_count + target]) return w.fail(field.span, .override_mismatch);
                        if (write_stated) |access| if (access != w.field_write[w.catalogue.field_count + target]) return w.fail(field.span, .override_mismatch);
                        // A private field is invisible below its class, so it cannot be restated there.
                        if (w.field_access[w.catalogue.field_count + target] == .private) return w.fail(field.span, .inaccessible_member);
                        if (w.field_access[w.catalogue.field_count + target] == .internal and index != no_member) try self.checkFieldAccess(shape.parent.?, index, field.span, false);
                        if (overridden.isSet(target)) return w.fail(field.span, .duplicate_field);
                        overridden.set(target);
                        // A live field's guard gives its value (RFC-0084, P4.2).
                        if (w.field_live[w.catalogue.field_count + target]) return w.fail(field.span, .live_assigned);
                        // A final field keeps the default of its declaration in every subclass.
                        if (w.field_final[w.catalogue.field_count + target]) return w.fail(field.span, .final_field);
                        if (self.peek().kind == .equal) {
                            // The default may instantiate a type, which moves the staged fields.
                            const restated = try self.parseDefault(field, value_type);
                            w.field_defaults[w.catalogue.field_count + target] = restated;
                        }
                        // `<override><final>` restates the default and seals it from here down.
                        if (is_final) {
                            const restated = w.field_defaults[w.catalogue.field_count + target];
                            if (restated.start == restated.end) return w.fail(field.span, .final_field);
                            w.field_final[w.catalogue.field_count + target] = true;
                        }
                    } else {
                        if (inherited + count == w.record_fields.len) return w.fail(field.span, .field_limit);
                        if (w.catalogue.field_count + inherited + count == w.field_defaults.len) return w.fail(field.span, .field_limit);
                        for (w.record_fields[0..count]) |earlier| {
                            if (std.mem.eql(u8, earlier.name.text(w.source), field.span.text(w.source))) return w.fail(field.span, if (is_interface) .duplicate_name else .duplicate_field);
                        }
                        for (self.fields()[parent_fields.start..parent_fields.end]) |earlier| {
                            if (std.mem.eql(u8, earlier.name.text(w.source), field.span.text(w.source))) return w.fail(field.span, .duplicate_field);
                        }
                        w.record_fields[count] = .{ .name = field.span, .value_type = value_type, .is_var = is_var, .live_only = is_live and !is_var };
                        w.noteDeclaration(field.span, .member, name.span.start);
                        // The field is staged before its default is read: a struct the default
                        // instantiates moves everything that is staged out of its way, so where
                        // the field's default, accesses and finality go is known only afterwards.
                        w.staged_fields = count + 1;
                        if (is_live and live_count == live_fields.len) return w.fail(field.span, .field_limit);
                        if (is_live) live_fields[live_count] = .{ .index = inherited + count, .guard = self.cursor + 1, .name = field, .keyword = class_word };
                        const default: functions.Body = if (is_live) try self.parseLiveDefault(field, value_type) else if (self.peek().kind == .equal) try self.parseDefault(field, value_type) else .{};
                        if (is_live) live_count += 1;
                        const field_index = w.catalogue.field_count + inherited + count;
                        if (field_index >= w.field_defaults.len) return w.fail(field.span, .field_limit);
                        w.field_defaults[field_index] = default;
                        w.field_access[field_index] = stated orelse .internal;
                        w.field_write[field_index] = write_stated orelse w.field_access[field_index];
                        // Whoever may assign a field may read it: the write access is never the wider one.
                        if (!w.field_write[field_index].within(w.field_access[field_index])) return w.fail(field.span, .unsupported_specifier);
                        // No archetype may give a final field, so its declaration has to.
                        if (is_final and w.field_defaults[field_index].start == w.field_defaults[field_index].end) return w.fail(field.span, .final_field);
                        w.field_final[field_index] = is_final;
                        w.field_live[field_index] = is_live;
                        count += 1;
                        w.staged_fields = count;
                    }
                }
                if (self.peek().kind == .right_brace) break;
                if (self.peek().kind != .comma and self.peek().kind != .newline and self.peek().kind != .separator) return w.fail(self.peek().span, .unexpected_token);
                self.cursor += 1;
                self.skipNewlines();
            }
            _ = try self.take(.right_brace, .unexpected_token);
            const end = self.cursor;
            // An interface keeps no fields of its own: the classes that implement it hold them.
            w.catalogue.completeClass(class, shape, if (is_interface) &.{} else w.record_fields[0..count], w.source) catch |err| return w.fail(name.span, switch (err) {
                error.FieldLimit => .field_limit,
                error.DuplicateName => .duplicate_name,
                error.InvalidParent => .invalid_parent,
                else => .unsupported_type,
            });
            if (is_persistable) w.catalogue.definitions[classIndex(class)].class.persistable = true;
            if (is_final_super) w.catalogue.definitions[classIndex(class)].class.final_super = true;
            if (is_final_super_base) w.catalogue.definitions[classIndex(class)].class.final_super_base = true;
            // Its supertypes and `<final>` are known now: overloads declared above it that named it
            // are distinct or related from here on.
            if (w.late_overload_count != 0) try self.recheckLateOverloads();
            const above = catalogue.Supertypes.of(class, self.definitions()).?;
            // Two supertypes that each introduce a member of one name would make uses ambiguous,
            // except that a method the superclass already has stands in for an interface's.
            if (shape.interface_count != 0) for (w.slots[0..w.slot_count], 0..) |first, at| {
                if (w.slot_kind[at] == .setter or !above.has(first.owner)) continue;
                for (w.slots[at + 1 .. w.slot_count], at + 1..) |second, other| {
                    if (w.slot_kind[other] == .setter or !above.has(second.owner) or !std.mem.eql(u8, first.name.text(w.source), second.name.text(w.source))) continue;
                    try self.reconcile(class, name, @intCast(at), @intCast(other), &parent_above);
                }
            };
            if (is_interface) {
                try self.declareInterfaceFields(class, w.record_fields[0..count]);
            } else {
                // A class that can be built may not get a method from an interface under the name
                // of a field it has: the field would hide it from every use through the class.
                if (!shape.is_abstract and shape.interface_count != 0) for (0..w.slot_count) |slot| {
                    if (w.slot_kind[slot] != .method or !through.has(w.slots[slot].owner) or parent_above.has(w.slots[slot].owner)) continue;
                    if (catalogue.findField(class, w.slots[slot].name.text(w.source), self.definitions(), self.fields(), w.source) != null) return w.fail(name.span, .duplicate_name);
                };
                // A field may not hide a method the class inherits.
                for (w.record_fields[acquired..count]) |field| if (w.findMethod(class, field.name.text(w.source)) != null) return w.fail(field.name, .duplicate_name);
                // Seen as one of its interfaces an instance shows no cells, so each interface field
                // is read and written through an accessor that knows where this class keeps it.
                if (shape.interface_count != 0) for (0..w.slot_count) |slot| {
                    if (w.slot_kind[slot] != .getter or !through.has(w.slots[slot].owner) or parent_above.has(w.slots[slot].owner)) continue;
                    const index = catalogue.findField(class, w.slots[slot].name.text(w.source), self.definitions(), self.fields(), w.source).?;
                    try self.synthesizeAccessor(class, name, @intCast(slot), index, false);
                    if (w.slot_field[slot].is_var) try self.synthesizeAccessor(class, name, @intCast(slot + 1), index, true);
                };
                if (is_concrete) {
                    // `C{}` must be complete: every field, inherited ones included, has a default.
                    const all = catalogue.definition(class, self.definitions()).?.class.fields;
                    for (w.field_defaults[all.start..all.end]) |default| if (default.start == default.end) return w.fail(name.span, .missing_field);
                    // RFC-0085, I9: and no field with accessors lacks one.
                    if (self.requiredAccessors(class) != 0) return w.fail(name.span, .missing_field);
                }
            }
            // Nothing is staged any more: the fields are in the catalogue.
            w.staged_fields = 0;
            w.staged_inherited = 0;
            if (w.method_templates != 0) try self.checkGenericMethods(class, first_generic, w.record_fields[acquired..count], method_cursors[0..method_count]);
            try self.finishMethods(class, name, shape.is_abstract, method_cursors[0..method_count], block_cursors[0..block_count], live_fields[0..live_count]);
            self.cursor = end;
            if (self.peek().kind != .eof and self.peek().kind != .newline and self.peek().kind != .separator) return w.fail(self.peek().span, .unexpected_token);
            std.debug.assert(count <= types.limits.record_fields);
            w.open_count -= 1;
            std.debug.assert(w.open_classes[w.open_count] == class);
            // What this declaration named and could not complete while it was open.
            if (arguments == null) try self.settle(name.span);
            return class;
        }

        /// B4 (RFC-0092): the rules of a restricted hierarchy, read with the class's header. A
        /// `<final_super>` class has a superclass and joins its family, which no query has asked
        /// for yet; a class directly below a `<final_super_base>` class is `<final_super>`. An
        /// instantiation of a parametric type takes neither: its family would grow as it is named.
        fn declareFinalSuper(self: *Self, class: types.Type, name: Token, parent: ?types.Type, is_final_super: bool, is_final_super_base: bool, instantiated: bool) ParseError!void {
            const w = self.workspace;
            w.final_super_first[classIndex(class)] = no_member;
            if ((is_final_super or is_final_super_base) and instantiated) return w.fail(name.span, .unsupported_specifier);
            if (parent) |above| if (catalogue.definition(above, self.definitions()).?.class.final_super_base and !is_final_super) return w.fail(name.span, .final_super_required);
            if (!is_final_super) return;
            const above = parent orelse return w.fail(name.span, .final_super_parent);
            if (w.class_kinds[classIndex(above)] & class_queried != 0) return w.fail(name.span, .final_super_after_query);
            w.final_super_next[classIndex(class)] = w.final_super_first[classIndex(above)];
            w.final_super_first[classIndex(above)] = classIndex(class);
        }

        /// B4 (RFC-0092): `GetCastableFinalSuperClass[Base, Instance]` (Book 11:1707): the type value
        /// of the `<final_super>` class directly below `Base` that the instance is of, as a
        /// `castable_subtype(Base)`; it fails when there is none. `Base` is castable and the
        /// instance is seen as one. The query calls the family function of `Base`, made once,
        /// and fails where it is written when the answer is empty.
        fn emitFinalSuper(self: *Self, operator: Operator, arguments: []const u32) ParseError!u32 {
            const w = self.workspace;
            const span = operator.span;
            if (arguments.len != 1) return w.fail(span, .argument_count);
            const base = operator.value_type.?;
            if (!self.castableClass(base)) return w.fail(span, .not_castable);
            // An instantiation of a parametric type is no type value (RFC-0081), and its family
            // function would be named by its template.
            if (w.instanceOf(base) != null) return w.fail(span, .unsupported_type);
            const instance = try self.coerce(arguments[0], base);
            const meta = self.metatypeOf(self.knownMetatype(.castable, base) orelse made: {
                const word = try self.castableWord(span);
                break :made try self.internMetatypeIn(.castable, base, true, word.span, word.scope);
            }).?;
            const family = try self.familyFunction(base, meta, span);
            const packed_type = try self.internTuple(&.{base}, span);
            const members = try self.reserveMembers(1, span);
            self.memberPool()[members.start] = instance;
            var packed_instance = [1]u32{try self.emit(.{ .span = span, .value_type = packed_type, .kind = .{ .aggregate = members } })};
            const range = try self.reserveArguments(&packed_instance, span);
            const answer_type = w.runtime_functions.definitions[family].value_type;
            const answer = try self.emit(.{ .span = span, .value_type = answer_type, .kind = .{ .call = .{ .function = family, .arguments = range } } });
            try self.emitDemand(span, try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .option_present = answer } }));
            return self.emit(.{ .span = span, .value_type = meta.value, .kind = .{ .option_value = answer } });
        }

        /// B4 (RFC-0092): the family function of `base`, `(tuple(Base))<computes>:
        /// option(castable_subtype(Base))`, empty when no member holds, made by the first query and closing the family: a
        /// `<final_super>` class declared below `base` afterwards is `final_super_after_query`.
        /// Each member of the family is one `instance_of` and an `If` that keeps its type value;
        /// the members are siblings, so at most one holds. Like a type value's witness it is
        /// named by its class, which no function can be, and its parameter, a one-element tuple,
        /// tells it from the witnesses of `base` (`Base` and `option(Base)`).
        fn familyFunction(self: *Self, base: types.Type, meta: Metatype, span: Span) ParseError!u32 {
            const w = self.workspace;
            const item = catalogue.definition(base, self.definitions()).?;
            const name = catalogue.declaredName(item).?;
            // Every query asks: whether another module asked first changes nothing.
            const exported = self.reachesAll(name, catalogue.declaredPublic(item)) and self.familyExported(base);
            if (!exported and w.homeOf(name) != w.homeOf(span)) return w.fail(span, .private_name);
            if (w.class_kinds[classIndex(base)] & class_queried != 0) return w.families[classIndex(base)];
            if (w.runtime_functions.count == types.limits.functions) return w.fail(span, .function_limit);
            const packed_type = try self.internTuple(&.{base}, span);
            const option_type = w.catalogue.internOption(meta.value) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            const field_type = catalogue.fieldAt(meta.value, 0, self.definitions(), self.fields()).?;
            var definition: functions.Definition = .{ .name = name, .value_type = option_type, .is_public = exported, .start = w.functions.node_count, .end = 0, .root = 0 };
            definition.parameters[0] = .{ .name = name, .value_type = packed_type };
            definition.parameter_count = 1;
            // Compiled after whatever is being compiled now, published, and its storage given
            // back, as a witness is (`typeWitness`).
            const saved_function = self.function;
            const saved_class = self.method_class;
            const saved_depth = self.control_depth;
            const nodes = w.functions.node_count;
            const members = w.functions.member_count;
            const arguments = w.functions.argument_count;
            self.function = definition;
            self.method_class = null;
            self.control_depth = 0;
            defer {
                self.function = saved_function;
                self.method_class = saved_class;
                self.control_depth = saved_depth;
            }
            const packed_instance = try self.emitTemplate(.{ .node = .{ .span = span, .value_type = packed_type, .kind = .{ .integer = 0 } }, .input = .{ .parameter = 0 } });
            const instance = try self.emit(.{ .span = span, .value_type = base, .kind = .{ .tuple_element = .{ .value = packed_instance, .index = 0 } } });
            var found = try self.emit(.{ .span = span, .value_type = option_type, .kind = .{ .aggregate = try self.reserveMembers(0, span) } });
            var member = w.final_super_first[classIndex(base)];
            while (member != no_member) : (member = w.final_super_next[member]) {
                const anchor: types.Type = @fromBackingInt(@as(u16, @intCast(member + catalogue.builtin_count)));
                const holds = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .instance_of = .{ .value = instance, .class = anchor } } });
                const begin = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .if_begin = .{ .condition = holds, .alternative = no_member, .end = no_member } } });
                const witness = try self.typeWitness(.test_class, base, anchor, field_type.value_type, span);
                const held = try self.emit(.{ .span = span, .value_type = field_type.value_type, .kind = .{ .function_value = witness } });
                const value_members = try self.reserveMembers(1, span);
                self.memberPool()[value_members.start] = held;
                const value = try self.emit(.{ .span = span, .value_type = meta.value, .kind = .{ .aggregate = value_members } });
                const some_members = try self.reserveMembers(1, span);
                self.memberPool()[some_members.start] = value;
                const some = try self.emit(.{ .span = span, .value_type = option_type, .kind = .{ .aggregate = some_members } });
                _ = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .otherwise = begin } });
                found = try self.emit(.{ .span = span, .value_type = option_type, .kind = .{ .merge = .{ .begin = begin, .left = some, .right = found } } });
            }
            const root = found;
            definition.root = root;
            definition.end = w.functions.node_count;
            definition.work = self.body(definition.start, root).work;
            const target = w.runtime_functions.publishAlias(definition, &w.functions, self.definitions(), w.bindings[0..w.binding_count], w.binding_cells[0..w.binding_count], w.node_count) catch |err| return w.fail(span, switch (err) {
                error.FunctionLimit => .function_limit,
                error.NodeLimit => .template_limit,
                error.MemberLimit => .aggregate_limit,
                error.ArgumentLimit => .call_argument_limit,
                error.GlobalLimit => .binding_limit,
            });
            w.functions.node_count = nodes;
            w.functions.member_count = members;
            w.functions.argument_count = arguments;
            w.families[classIndex(base)] = target.?;
            w.class_kinds[classIndex(base)] |= class_queried;
            return target.?;
        }

        /// B4 (RFC-0092): whether the type value of every member of `base`'s family can be made
        /// from another module: each member is as public as a witness needs (`typeWitness`).
        /// A member that is not makes the family a family of its own module only.
        fn familyExported(self: *const Self, base: types.Type) bool {
            const w = self.workspace;
            var member = w.final_super_first[classIndex(base)];
            while (member != no_member) : (member = w.final_super_next[member]) {
                const item = w.catalogue.definitions[member];
                if (!self.reachesAll(catalogue.declaredName(item).?, catalogue.declaredPublic(item))) return false;
            }
            return true;
        }

        /// B4 (RFC-0092): the struct of the metatype `kind` of `bound`, if this compile made it.
        fn knownMetatype(self: *const Self, kind: MetaKind, bound: types.Type) ?types.Type {
            const w = self.workspace;
            var same = w.metatype_table.walk(&w.metatype_slots, metatypeHash(kind, bound));
            while (same.next()) |index| {
                if (w.metatypes[index].kind == kind and w.metatypes[index].bound == bound) return w.metatypes[index].value;
            }
            return null;
        }

        /// B4 (RFC-0092): the word `castable_subtype` of the library block of the module that
        /// writes `span`: a metatype the program never writes is named by it. A module without
        /// the line asks for it, and the program is compiled again with it.
        fn castableWord(self: *Self, span: Span) ParseError!struct { span: Span, scope: Span } {
            const w = self.workspace;
            const count = w.module_storage.module_count;
            const module: u32 = if (count == 0) 0 else modules.owner(span, w.module_storage.modules[0..count]) orelse return w.fail(span, .macro_unavailable);
            if (!w.has_library or w.library_base[module] == 0 or !w.library_extension[module].castables) {
                w.library_wanted = w.library_wanted.merged(.{ .castables = true });
                return w.fail(span, .macro_unavailable);
            }
            const at = w.library_templates[module] + w.library_extension[module].castableWord();
            return .{ .span = .{ .start = at, .end = at + @as(u32, @intCast("castable_subtype".len)) }, .scope = w.scopeOf(module) };
        }

        /// Two slots of one name reach `class`. Those its superclass already saw were settled there.
        /// Two that arrive through its interfaces are distinct members that only a qualifier could
        /// tell apart. One of each is accepted when the signatures agree: the superclass's method is
        /// the member, and the interface's slot forwards to it.
        fn reconcile(self: *Self, class: types.Type, name: Token, first: u32, second: u32, parent_above: *const catalogue.Supertypes) ParseError!void {
            const w = self.workspace;
            const first_old = parent_above.has(w.slots[first].owner);
            const second_old = parent_above.has(w.slots[second].owner);
            if (first_old and second_old) return;
            if (!first_old and !second_old) return w.fail(name.span, .duplicate_name);
            const primary = if (first_old) first else second;
            const secondary = if (first_old) second else first;
            // RFC-0085, I8: no other method fills the slot of a getter or a setter, nor is one another's.
            if (w.accessor_count != 0 and (self.accessorSlot(primary) or self.accessorSlot(secondary))) return w.fail(name.span, .accessor_override);
            const parent = catalogue.definition(class, self.definitions()).?.class.parent.?;
            // A slot the superclass itself forwards is not its member; the pair with the member decides.
            if (w.bridge_count != 0 and w.bridged(parent, primary)) return;
            // Two interface fields of one name: the class keeps one cell for both, which the
            // field pass has already found to be the same field, and gives each its accessors.
            if (w.slot_kind[primary] == .getter and w.slot_kind[secondary] == .getter) return;
            if (w.slot_kind[primary] != .method or w.slot_kind[secondary] != .method or w.slot_access[primary] != w.slot_access[secondary]) return w.fail(name.span, .duplicate_name);
            // Two internal members are the same access only if one module declares both.
            if (w.slot_access[primary] == .internal and !self.sameModule(w.slots[primary].owner, w.slots[secondary].owner)) return w.fail(name.span, .duplicate_name);
            const have = catalogue.definition(w.slots[primary].callable, self.definitions()).?.callable;
            const want = catalogue.definition(w.slots[secondary].callable, self.definitions()).?.callable;
            // B4 (RFC-0092): the inherited method may narrow the result, as an override may.
            const refines = have.result != want.result;
            if (refines and !self.narrowerResult(have.result, want.result)) return w.fail(name.span, .duplicate_name);
            // The inherited method fills the slot as an override would: it may do less than the
            // slot declares, never more (RFC-0078).
            if (missingEffect(have.effects(), want.effects(), override_codes)) |code| return w.fail(name.span, code);
            if (have.effects().dictates and !want.effects().dictates) return w.fail(name.span, .override_widens_dictates);
            const have_parameters = catalogue.definition(have.parameters, self.definitions()).?.tuple;
            const want_parameters = catalogue.definition(want.parameters, self.definitions()).?.tuple;
            if (have_parameters.end - have_parameters.start != want_parameters.end - want_parameters.start) return w.fail(name.span, .duplicate_name);
            if (!std.mem.eql(types.Type, w.catalogue.tuple_elements[have_parameters.start + 1 .. have_parameters.end], w.catalogue.tuple_elements[want_parameters.start + 1 .. want_parameters.end])) return w.fail(name.span, .duplicate_name);
            // A final method of an interface is its one implementation: nothing stands in for it.
            if (w.sealedAbove(class, secondary)) return w.fail(name.span, .final_method);
            if (refines) return self.synthesizeRefinement(class, name.span, secondary, primary);
            try self.synthesizeBridge(class, name, secondary, primary);
        }

        /// The fields an interface declares become slots: a getter each, and a setter after it when
        /// the field is `var`. No layout is implied; a class that implements the interface says
        /// where the field lives by implementing the slots.
        fn declareInterfaceFields(self: *Self, interface: types.Type, declared: []const types.Field) ParseError!void {
            const w = self.workspace;
            for (declared, 0..) |field, position| {
                const text = field.name.text(w.source);
                // One member per name, and the accessors are functions of this name.
                if (w.findMethod(interface, text) != null or w.symbolNamed(text)) return w.fail(field.name, .duplicate_name);
                const default = w.field_defaults[w.catalogue.field_count + position];
                var elements = [2]types.Type{ interface, field.value_type };
                for (0..@as(usize, if (field.is_var) 2 else 1)) |part| {
                    if (w.slot_count == w.slots.len or w.method_count == w.methods.len) return w.fail(field.name, .method_limit);
                    const parameters = try self.internTuple(elements[0 .. part + 1], field.name);
                    // The getter reads the instance and the setter writes it: each asks only that of its caller.
                    const callable = try self.internCallable(.{ .parameters = parameters, .result = field.value_type, .transacts = true, .decides = false, .detail = if (part == 0) types.heapDetail(true, false, false) else types.heapDetail(false, true, false) }, field.name);
                    const slot = w.slot_count;
                    w.slots[slot] = .{ .owner = interface, .callable = callable, .name = field.name };
                    w.slot_access[slot] = w.field_access[w.catalogue.field_count + position];
                    w.slot_kind[slot] = if (part == 0) .getter else .setter;
                    w.slot_field[slot] = .{ .value_type = field.value_type, .is_var = field.is_var, .default = default, .is_final = w.field_final[w.catalogue.field_count + position] };
                    w.slot_first[slot] = no_member;
                    w.slot_count += 1;
                    // The declaration itself: abstract, so a class that lacks an accessor is incomplete.
                    w.methods[w.method_count] = .{ .class = interface, .name = field.name, .slot = slot, .is_abstract = true, .synthetic = true };
                    w.linkMethod(w.method_count);
                    w.method_count += 1;
                }
            }
        }

        /// RFC-0085, I8: whether the member at the cursor of a class body is a field with
        /// accessors: `var`, its write access, `live`, the name, and among its specifiers a
        /// `<getter(` or a `<setter(`. The cursor is left where it is.
        fn accessorFieldAhead(self: *const Self) bool {
            const w = self.workspace;
            const tokens = w.tokens[0..w.token_count];
            var at: usize = self.cursor;
            if (at + 1 >= tokens.len or tokens[at].kind != .identifier) return false;
            if (std.mem.eql(u8, tokens[at].span.text(w.source), "var")) {
                at += 1;
                if (at + 3 < tokens.len and tokens[at].kind == .less and tokens[at + 1].kind == .identifier and tokens[at + 2].kind == .greater) at += 3;
            }
            if (at + 1 < tokens.len and tokens[at].kind == .identifier and std.mem.eql(u8, tokens[at].span.text(w.source), "live") and tokens[at + 1].kind == .identifier) at += 1;
            if (at >= tokens.len or tokens[at].kind != .identifier) return false;
            at += 1;
            while (at + 2 < tokens.len and tokens[at].kind == .less and tokens[at + 1].kind == .identifier) : (at += 3) {
                if (tokens[at + 2].kind == .greater) continue;
                const word = tokens[at + 1].span.text(w.source);
                return tokens[at + 2].kind == .left_paren and (std.mem.eql(u8, word, "getter") or std.mem.eql(u8, word, "setter"));
            }
            return false;
        }

        /// RFC-0085, I8: declares `var<W> F<R><getter(G)><setter(S)>:T = external{}` of the class
        /// or interface `class`, whose body is being read. The field has no cell: it is no
        /// catalogue field, so the class's layout, reports and every machine are those of its
        /// other fields. `own` are the fields the class has staged so far, those it holds for
        /// its interfaces first.
        fn declareAccessorField(self: *Self, class: types.Type, shape: *const catalogue.ClassShape, parent_fields: Span, own: []const types.Field) ParseError!void {
            const w = self.workspace;
            var field = try self.take(.identifier, .expected_field);
            const is_var = std.mem.eql(u8, field.span.text(w.source), "var");
            var write_stated: ?Access = null;
            if (is_var and self.peek().kind == .less) {
                _ = try self.take(.less, .unsupported_specifier);
                const word = try self.take(.identifier, .unsupported_specifier);
                _ = try self.take(.greater, .unsupported_specifier);
                write_stated = Access.named(word.span.text(w.source)) orelse return w.fail(word.span, .unsupported_specifier);
            }
            if (is_var) field = try self.take(.identifier, .expected_field);
            // It has no cell to attach a guard to.
            if (std.mem.eql(u8, field.span.text(w.source), "live") and self.peek().kind == .identifier) return w.fail(self.peek().span, .accessor_live);
            if (w.localQualified(field.span.start)) return w.fail(field.span, .invalid_qualifier);
            if (rawNamed(field.span.text(w.source)) and w.libraryModule(field.span) == null) return w.fail(field.span, .expected_field);
            var stated: ?Access = null;
            var getter: ?Token = null;
            var setter: ?Token = null;
            while (self.peek().kind == .less) {
                _ = try self.take(.less, .unsupported_specifier);
                const word = try self.take(.identifier, .unsupported_specifier);
                const text = word.span.text(w.source);
                if (self.peek().kind == .left_paren and (std.mem.eql(u8, text, "getter") or std.mem.eql(u8, text, "setter"))) {
                    const is_getter = text[0] == 'g';
                    if ((if (is_getter) getter else setter) != null) return w.fail(word.span, .unsupported_specifier);
                    _ = try self.take(.left_paren, .unsupported_specifier);
                    const method = try self.take(.identifier, .accessor_signature);
                    _ = try self.take(.right_paren, .unsupported_specifier);
                    _ = try self.take(.greater, .unsupported_specifier);
                    if (is_getter) getter = method else setter = method;
                    continue;
                }
                _ = try self.take(.greater, .unsupported_specifier);
                // The accessors of a field are fixed where it is declared (12:878).
                if (std.mem.eql(u8, text, "override")) return w.fail(field.span, .accessor_override);
                // A final field keeps the default of its declaration, which this one does not have.
                if (std.mem.eql(u8, text, "final")) return w.fail(word.span, .unsupported_specifier);
                if (stated != null) return w.fail(word.span, .unsupported_specifier);
                stated = Access.named(text) orelse return w.fail(word.span, .unsupported_specifier);
            }
            if (shape.is_interface and write_stated != null) return w.fail(field.span, .invalid_interface);
            if (shape.is_interface) if (stated) |access| if (access != .public and access != .internal) return w.fail(field.span, .invalid_interface);
            // Both, never one (12:876), and only on a `var` (12:879).
            if (getter == null or setter == null) return w.fail(field.span, .accessor_pair);
            if (!is_var) return w.fail(field.span, .accessor_mutable);
            const value_type = try self.parseType();
            // `= external{}`: the field has no storage (10:3301). One without a default has
            // none either: every archetype gives it a value, which the setter receives once
            // the instance is built (12:877, "archetype initialization"; I9).
            const required = self.peek().kind != .equal;
            if (!required) {
                const equal = try self.take(.equal, .accessor_default);
                const external = self.peek();
                if (external.kind != .identifier or !std.mem.eql(u8, external.span.text(w.source), "external") or w.tokens[self.cursor + 1].kind != .left_brace or w.tokens[self.cursor + 2].kind != .right_brace) return w.fail(equal.span, .accessor_default);
                self.cursor += 3;
            }
            const read = stated orelse .internal;
            const write = write_stated orelse read;
            // Whoever may assign a field may read it.
            if (!write.within(read)) return w.fail(field.span, .unsupported_specifier);
            const text = field.span.text(w.source);
            for (own) |earlier| if (std.mem.eql(u8, earlier.name.text(w.source), text)) return w.fail(field.span, if (shape.is_interface) .duplicate_name else .duplicate_field);
            for (self.fields()[parent_fields.start..parent_fields.end]) |earlier| if (std.mem.eql(u8, earlier.name.text(w.source), text)) return w.fail(field.span, .duplicate_field);
            if (self.accessorAbove(shape, text)) return w.fail(field.span, .accessor_override);
            var same = w.accessor_table.walk(&w.accessor_slots, name_index.hashName(0, text));
            while (same.next()) |index| {
                const earlier = w.accessor_fields[index];
                if (earlier.owner == class and std.mem.eql(u8, earlier.name.text(w.source), text)) return w.fail(field.span, if (shape.is_interface) .duplicate_name else .duplicate_field);
            }
            if (w.accessor_count == w.accessor_fields.len) return w.fail(field.span, .field_limit);
            const index = w.accessor_count;
            w.accessor_fields[index] = .{ .owner = class, .value_type = value_type, .name = field.span, .getter_name = getter.?.span, .setter_name = setter.?.span, .read = read, .write = write, .required = required };
            w.accessor_count += 1;
            w.noteDeclaration(field.span, .member, self.ownerOf(class));
            if (required) w.accessor_required += 1;
            w.accessor_given[index] = .{};
            if (w.accessor_table.crowded()) {
                w.accessor_table.grow(&w.accessor_slots);
                w.accessor_owners.grow(&w.accessor_owner_slots);
                for (w.accessor_fields[0..index], 0..) |earlier, at| {
                    w.accessor_table.enter(&w.accessor_slots, name_index.hashName(0, earlier.name.text(w.source)), @intCast(at));
                    w.accessor_owners.enter(&w.accessor_owner_slots, accessorKey(@backingInt(earlier.owner)), @intCast(at));
                }
            }
            w.accessor_table.enter(&w.accessor_slots, name_index.hashName(0, text), index);
            w.accessor_owners.enter(&w.accessor_owner_slots, accessorKey(@backingInt(class)), index);
        }

        /// The key of a type or a slot in `accessor_owners` and `accessor_methods`.
        fn accessorKey(value: u32) u64 {
            return std.hash.Wyhash.hash(0, std.mem.asBytes(&value));
        }

        /// Enters the getter and the setter of field `index`, just found, in `accessor_methods`.
        fn enterAccessorMethods(self: *Self, index: u32) void {
            const w = self.workspace;
            const table = &w.accessor_methods;
            // Room for both: a table at most half full after them.
            if ((@as(u64, table.used) + 2) * 2 > table.live) {
                table.grow(&w.accessor_method_slots);
                for (w.accessor_fields[0..w.accessor_count], 0..) |earlier, at| {
                    if (at == index or earlier.getter == no_member) continue;
                    table.enter(&w.accessor_method_slots, accessorKey(earlier.getter), @intCast(at));
                    table.enter(&w.accessor_method_slots, accessorKey(earlier.setter), @intCast(at));
                }
            }
            const entry = w.accessor_fields[index];
            table.enter(&w.accessor_method_slots, accessorKey(entry.getter), index);
            table.enter(&w.accessor_method_slots, accessorKey(entry.setter), index);
        }

        /// RFC-0085, I8: the field with accessors named `name` that a value of `value_type` has,
        /// declared by that type or one above it, once its accessors are known.
        fn findAccessor(self: *const Self, value_type: types.Type, name: []const u8) ?u32 {
            const w = self.workspace;
            if (w.accessor_count == 0) return null;
            var same = w.accessor_table.walk(&w.accessor_slots, name_index.hashName(0, name));
            while (same.next()) |index| {
                const entry = w.accessor_fields[index];
                if (entry.getter == no_member or !std.mem.eql(u8, entry.name.text(w.source), name)) continue;
                if (entry.owner == value_type or catalogue.subtype(value_type, entry.owner, self.definitions())) return index;
            }
            return null;
        }

        /// Whether the superclass or an interface of a class being declared has a field with
        /// accessors named `name`.
        fn accessorAbove(self: *const Self, shape: *const catalogue.ClassShape, name: []const u8) bool {
            if (self.workspace.accessor_count == 0) return false;
            if (shape.parent) |parent| if (self.findAccessor(parent, name) != null) return true;
            for (shape.interfaces[0..shape.interface_count]) |interface| if (self.findAccessor(interface, name) != null) return true;
            return false;
        }

        /// Whether `slot` is the getter or the setter of a field with accessors.
        fn accessorSlot(self: *const Self, slot: u32) bool {
            const w = self.workspace;
            var same = w.accessor_methods.walk(&w.accessor_method_slots, accessorKey(slot));
            while (same.next()) |index| {
                const entry = w.accessor_fields[index];
                if (entry.getter == slot or entry.setter == slot) return true;
            }
            return false;
        }

        /// RFC-0085, I8: the standard type `accessor`, an empty struct named where the program
        /// first writes the name. No source expression builds one (`accessor_construction`), so
        /// only the accesses the compiler lowers pass one to a getter or a setter.
        fn accessorType(self: *Self, span: Span) ParseError!types.Type {
            const w = self.workspace;
            if (w.standardAccessor()) |known| return known;
            const made = w.catalogue.addRecordIn(span, &.{}, true, w.source, w.scope()) catch |err| return w.fail(span, switch (err) {
                error.TypeLimit => .type_limit,
                error.FieldLimit => .field_limit,
                error.DuplicateName => .duplicate_name,
                else => .unsupported_type,
            });
            w.accessor_type = made;
            w.accessor_name = span;
            w.class_effects[classIndex(made)] = .{};
            return made;
        }

        /// The one value of `accessor`, which an access hands to the getter or the setter.
        fn accessorValue(self: *Self, span: Span) ParseError!u32 {
            const value_type = self.workspace.standardAccessor().?;
            return self.emit(.{ .span = span, .value_type = value_type, .kind = .{ .aggregate = try self.reserveMembers(0, span) } });
        }

        /// RFC-0085, I8: once the methods of `class` are declared (from `first`), finds the
        /// getter and the setter of each field with accessors it declares and checks them, and
        /// refuses a member of `class` that would restate a field with accessors above it.
        fn resolveAccessors(self: *Self, class: types.Type, name: Token, first: u32) ParseError!void {
            const w = self.workspace;
            const above = catalogue.Supertypes.of(class, self.definitions()).?;
            const shape = catalogue.definition(class, self.definitions()).?.class;
            // A member this class declares under the name of a field with accessors above it
            // would restate the field (12:878, 10:3309): its own fields (those it holds for its
            // interfaces too), methods and generic methods. Each is one probe by name.
            for (self.fields()[shape.fields.start + shape.inherited .. shape.fields.end]) |field| {
                if (self.accessorAboveOf(&above, class, field.name.text(w.source))) return w.fail(field.name, .accessor_override);
            }
            for (w.methods[first..w.method_count]) |method| {
                if (method.class == class and self.accessorAboveOf(&above, class, method.name.text(w.source))) return w.fail(method.name, .accessor_override);
            }
            if (w.method_templates != 0) for (w.generic_templates[0..w.generic_count]) |template| {
                if (template.kind == .method and template.receiver == class and self.accessorAboveOf(&above, class, template.name.text(w.source))) return w.fail(template.name, .accessor_override);
            };
            // The interfaces a class adds bring their fields to members it inherits, and to the
            // fields its other supertypes bring. What its superclass already reached was
            // checked where the superclass was declared, so a chain of classes checks each
            // field once.
            if (shape.interface_count != 0) {
                const parent_above: catalogue.Supertypes = if (shape.parent) |parent| catalogue.Supertypes.of(parent, self.definitions()).? else .{};
                var reached = above.reached.iterator(.{});
                while (reached.next()) |position| {
                    const owner: types.Type = @fromBackingInt(@intCast(position + catalogue.builtin_count));
                    if (owner == class or parent_above.has(owner)) continue;
                    var owned = w.accessor_owners.walk(&w.accessor_owner_slots, accessorKey(@backingInt(owner)));
                    while (owned.next()) |index| {
                        const entry = w.accessor_fields[index];
                        if (entry.owner != owner or entry.getter == no_member) continue;
                        const text = entry.name.text(w.source);
                        if (catalogue.findField(class, text, self.definitions(), self.fields(), w.source)) |field| return w.fail(catalogue.classFieldAt(class, field, self.definitions(), self.fields()).?.name, .accessor_override);
                        if (w.findMethod(class, text)) |slot| return w.fail(w.slots[slot].name, .accessor_override);
                        if (w.method_templates != 0) if (try self.genericMethodOf(class, text, false, name.span)) |found| return w.fail(w.generic_templates[found.id].name, .accessor_override);
                        // Two supertypes that each declare one of the name make its uses ambiguous.
                        var same = w.accessor_table.walk(&w.accessor_slots, name_index.hashName(0, text));
                        while (same.next()) |other| {
                            const rival = w.accessor_fields[other];
                            if (other != index and rival.owner != class and rival.getter != no_member and above.has(rival.owner) and std.mem.eql(u8, rival.name.text(w.source), text)) return w.fail(name.span, .duplicate_name);
                        }
                    }
                }
            }
            // What the class declares itself.
            var owned = w.accessor_owners.walk(&w.accessor_owner_slots, accessorKey(@backingInt(class)));
            while (owned.next()) |index| {
                const entry = &w.accessor_fields[index];
                if (entry.owner != class) continue;
                const text = entry.name.text(w.source);
                if (catalogue.findField(class, text, self.definitions(), self.fields(), w.source) != null) return w.fail(entry.name, .duplicate_field);
                if (w.findMethod(class, text) != null) return w.fail(entry.name, .duplicate_name);
                if (w.method_templates != 0) if (try self.genericMethodOf(class, text, false, entry.name) != null) return w.fail(entry.name, .duplicate_name);
                const void_type = try self.internTuple(&.{}, entry.name);
                entry.getter = try self.accessorMethod(class, first, entry.getter_name, &.{w.standardAccessor() orelse .i64}, entry.value_type);
                entry.setter = try self.accessorMethod(class, first, entry.setter_name, &.{ w.standardAccessor() orelse .i64, entry.value_type }, void_type);
                self.enterAccessorMethods(index);
            }
        }

        /// RFC-0085, I9: every construction of `class` calls the setter of each field with
        /// accessors and no default it has, so a stated class effect bounds those setters, as it
        /// bounds the block clauses (RFC-0078), and a predicting class has setters that predict.
        fn boundAccessors(self: *Self, class: types.Type, name: Token) ParseError!void {
            const w = self.workspace;
            const stated = w.class_effects[classIndex(class)];
            if (!stated.stated) return;
            const count = self.requiredAccessors(class);
            for (w.accessor_order[0..count]) |index| {
                const setter = w.accessor_fields[index].setter;
                std.debug.assert(setter != no_member);
                const effects = catalogue.definition(w.slots[setter].callable, self.definitions()).?.callable.effects();
                if (missingEffect(effects.heap(), stated.effect.set(), narrower_codes)) |code| return w.fail(name.span, code);
                if (stated.effect.detail.predicts and effects.dictates) return w.fail(name.span, .construction_requires_dictates);
            }
        }

        /// Whether a field with accessors named `name` is declared above `class`, among `above`.
        fn accessorAboveOf(self: *const Self, above: *const catalogue.Supertypes, class: types.Type, name: []const u8) bool {
            const w = self.workspace;
            var same = w.accessor_table.walk(&w.accessor_slots, name_index.hashName(0, name));
            while (same.next()) |index| {
                const entry = w.accessor_fields[index];
                if (entry.owner != class and entry.getter != no_member and above.has(entry.owner) and std.mem.eql(u8, entry.name.text(w.source), name)) return true;
            }
            return false;
        }

        /// The slot of the method `name` that `class` declares (from `first`), with a body, the
        /// parameters `parameters` after `Self`, the first of them the unnamed `accessor`, and
        /// the result `result`; neither failing nor suspending.
        fn accessorMethod(self: *Self, class: types.Type, first: u32, name: Span, parameters: []const types.Type, result: types.Type) ParseError!u32 {
            const w = self.workspace;
            const text = name.text(w.source);
            const method = for (w.methods[first..w.method_count], first..) |method, position| {
                if (method.class == class and std.mem.eql(u8, method.name.text(w.source), text)) break position;
            } else return w.fail(name, .accessor_signature);
            const info = w.methods[method];
            // Its own slot: a method that overrides one above has the slot's receiver and
            // parameter names, and a body above it that a field does not reach.
            if (info.is_abstract or w.slots[info.slot].owner != class or w.standardAccessor() == null) return w.fail(name, .accessor_signature);
            const shape = catalogue.definition(w.slots[info.slot].callable, self.definitions()).?.callable;
            const declared = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
            const taken = w.catalogue.tuple_elements[declared.start..declared.end];
            if (taken.len != parameters.len + 1 or !std.mem.eql(types.Type, taken[1..], parameters) or shape.result != result) return w.fail(name, .accessor_signature);
            // Unnamed, so the body cannot hand the value on.
            const unnamed = w.method_parameters[method * types.limits.parameters + 1].name;
            if (unnamed.start != unnamed.end) return w.fail(name, .accessor_signature);
            if (shape.decides or shape.effects().suspends) return w.fail(name, .accessor_effect);
            return info.slot;
        }

        /// A method body is a runtime function named after the method, whose first parameter is the
        /// slot's owner. A plain or extension function of that name with the same parameter list
        /// would be the same function twice; one declared after the method is caught where it is declared.
        fn checkPlainClash(self: *Self, name: Span, class: types.Type, owner: types.Type, rest: []const functions.Parameter, scope: Span) ParseError!void {
            const w = self.workspace;
            const first = w.functions.findIn(name.text(w.source), w.source, scope) orelse return;
            var others = w.overloads(first);
            while (others.next()) |index| {
                const other = &w.functions.definitions[index];
                if (other.is_method or other.parameter_count != rest.len + 1 or other.parameters[0].value_type != owner) continue;
                const same = for (other.parameters[1..other.parameter_count], rest) |theirs, ours| {
                    if (theirs.value_type != ours.value_type) break false;
                } else true;
                if (same) return w.fail(name, .duplicate_name);
            }
            // RFC-0076 (D16): an extension method on a type that overlaps the class would be
            // chosen by the static type of the receiver; declared after the method it is
            // refused where it is declared, declared before it is refused here, or where a
            // class it names that is still to be declared relates the two.
            var ours: [types.limits.parameters]types.Type = undefined;
            ours[0] = class;
            for (rest, ours[1..][0..rest.len]) |declared, *slot| slot.* = declared.value_type;
            others = w.overloads(first);
            while (others.next()) |index| {
                const other = &w.functions.definitions[index];
                if (other.is_method or !other.is_extension or other.parameter_count != rest.len + 1) continue;
                const theirs = parameterTypes(other);
                switch (self.signaturesOverlap(theirs[0..other.parameter_count], ours[0 .. rest.len + 1])) {
                    .apart => {},
                    .overlap => return w.fail(name, self.relatedCode(theirs[0..other.parameter_count], ours[0 .. rest.len + 1])),
                    .pending => {
                        var earliest = w.overloads(first);
                        const group = w.functions.definitions[earliest.next().?].name.start;
                        try self.noteLateOverload(group, 0, other.name, theirs[0..other.parameter_count]);
                        try self.noteLateOverload(group, 0, name, ours[0 .. rest.len + 1]);
                    },
                }
            }
        }

        /// The signature of a generated implementation of `slot`: exactly the slot's.
        fn beginSynthetic(self: *Self, slot: u32) functions.Definition {
            const w = self.workspace;
            const shape = catalogue.definition(w.slots[slot].callable, self.definitions()).?.callable;
            const parameters = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
            var function: functions.Definition = .{ .name = w.slots[slot].name, .value_type = shape.result, .is_public = false, .is_method = true, .transacts = shape.transacts, .decides = shape.decides, .detail = shape.detail, .start = w.functions.node_count, .end = 0, .root = 0 };
            for (w.catalogue.tuple_elements[parameters.start..parameters.end], 0..) |value_type, position| {
                function.parameters[position] = .{ .name = if (position == 0) Span.self_word else w.slots[slot].name, .value_type = value_type };
                function.defaults[position] = .{};
            }
            function.parameter_count = parameters.end - parameters.start;
            return function;
        }

        /// Publishes a generated body and lists it as `class`'s implementation of `slot`, where
        /// the dispatch table finds it for the class and its subclasses.
        fn finishSynthetic(self: *Self, class: types.Type, name: Token, slot: u32, begun: functions.Definition, root: u32, bridge: u32) ParseError!void {
            const w = self.workspace;
            var function = begun;
            function.root = root;
            function.end = w.functions.node_count;
            function.work = self.body(function.start, root).work;
            const runtime = w.runtime_functions.publishAlias(function, &w.functions, self.definitions(), w.bindings[0..w.binding_count], w.binding_cells[0..w.binding_count], w.node_count) catch |err| return w.fail(name.span, switch (err) {
                error.FunctionLimit => .function_limit,
                error.NodeLimit => .template_limit,
                error.MemberLimit => .aggregate_limit,
                error.ArgumentLimit => .call_argument_limit,
                error.GlobalLimit => .binding_limit,
            });
            self.function = null;
            self.method_class = null;
            if (w.method_count == w.methods.len) return w.fail(name.span, .method_limit);
            function.runtime = runtime.?;
            // Listed with the other method bodies, so a function declared later is compared with it.
            const scope = if (w.module_storage.module_count == 0) w.scope() else w.scopeOf(w.homeOf(function.name));
            try self.checkPlainClash(function.name, function.parameters[0].value_type, function.parameters[0].value_type, function.parameters[1..function.parameter_count], scope);
            w.methods[w.method_count] = .{ .class = class, .name = function.name, .slot = slot, .runtime = runtime.?, .function = w.functions.count, .synthetic = true, .bridge = bridge };
            w.functions.publishIn(function, w.source, scope);
            w.linkMethod(w.method_count);
            w.method_count += 1;
        }

        /// `class` keeps the interface field of `slot` in its cell `index`: the getter reads it, the
        /// setter writes it. The receiver arrives as the interface and is narrowed to the class with
        /// a checked `downcast`, so the cell is only ever reached on an instance that has it.
        fn synthesizeAccessor(self: *Self, class: types.Type, name: Token, slot: u32, index: u32, comptime is_setter: bool) ParseError!void {
            const w = self.workspace;
            if (w.functions.count + w.generic_count == types.limits.functions) return w.fail(name.span, .function_limit);
            const function = self.beginSynthetic(slot);
            const span = w.slots[slot].name;
            self.function = function;
            self.method_class = class;
            errdefer {
                self.function = null;
                self.method_class = null;
            }
            const receiver = try self.selfValue(span);
            const root = if (is_setter) root: {
                const value = try self.emitTemplate(.{ .node = .{ .span = span, .value_type = function.value_type, .kind = .{ .integer = 0 } }, .input = .{ .parameter = 1 } });
                break :root try self.emit(.{ .span = span, .value_type = function.value_type, .kind = .{ .object_set = .{ .object = receiver, .index = index, .value = value } } });
            } else try self.emit(.{ .span = span, .value_type = function.value_type, .kind = .{ .object_get = .{ .value = receiver, .index = index } } });
            try self.finishSynthetic(class, name, slot, function, root, no_member);
        }

        /// `class` answers the interface slot `slot` with the method its superclass has in slot
        /// `primary`: the forwarder narrows the receiver to that method's class and calls through
        /// the dispatch table, so an override further down is still the one that runs.
        fn synthesizeBridge(self: *Self, class: types.Type, name: Token, slot: u32, primary: u32) ParseError!void {
            const w = self.workspace;
            if (w.functions.count + w.generic_count == types.limits.functions) return w.fail(name.span, .function_limit);
            const function = self.beginSynthetic(slot);
            const span = w.slots[slot].name;
            self.function = function;
            self.method_class = null;
            errdefer self.function = null;
            var arguments: [types.limits.parameters]u32 = undefined;
            const self_value = try self.emitTemplate(.{ .node = .{ .span = span, .value_type = function.parameters[0].value_type, .kind = .{ .integer = 0 } }, .input = .{ .parameter = 0 } });
            arguments[0] = try self.emit(.{ .span = span, .value_type = w.slots[primary].owner, .kind = .{ .downcast = self_value } });
            const lookup = try self.emit(.{ .span = span, .value_type = w.slots[primary].callable, .kind = .{ .method_value = .{ .receiver = arguments[0], .slot = primary } } });
            for (1..function.parameter_count) |position| {
                arguments[position] = try self.emitTemplate(.{ .node = .{ .span = span, .value_type = function.parameters[position].value_type, .kind = .{ .integer = 0 } }, .input = .{ .parameter = @intCast(position) } });
            }
            const range = try self.reserveArguments(arguments[0..function.parameter_count], span);
            const root = try self.checked(try self.emit(.{ .span = span, .value_type = function.value_type, .kind = .{ .invoke = .{ .callable = lookup, .arguments = range } } }));
            try self.finishSynthetic(class, name, slot, function, root, primary);
            w.bridge_count += 1;
        }

        /// A member `Block{ ... }` of a class body: code that runs on every new instance.
        fn blockAhead(self: *const Self) bool {
            const token = self.peek();
            return token.kind == .identifier and std.mem.eql(u8, token.span.text(self.workspace.source), "Block") and self.workspace.tokens[self.cursor + 1].kind == .left_brace;
        }

        /// The entry of `class_blocks` for a class whose own block clauses are not compiled yet.
        const blocks_unknown: Span = .{ .start = std.math.maxInt(u32), .end = std.math.maxInt(u32) };

        /// Whether `class` cannot be built here because its block clauses are still unknown:
        /// they are being compiled, or a type its declaration named is being completed first.
        fn blocksUnknown(self: *const Self, class: types.Type) bool {
            const w = self.workspace;
            return w.blocks_pending == class or std.meta.eql(w.class_blocks[classIndex(class)], blocks_unknown);
        }

        /// The index of a class in the tables that have one entry per declared type.
        /// Adds what `supertype` states for its construction to `above`.
        fn joinClassEffect(self: *const Self, supertype: types.Type, above: *Effect, stated: *bool) void {
            const declared = self.workspace.class_effects[classIndex(supertype)];
            if (!declared.stated) return;
            const joined = above.set();
            const more = declared.effect.set();
            const reads = joined.reads or more.reads;
            const writes = joined.writes or more.writes;
            const allocates = joined.allocates or more.allocates;
            above.* = if (reads or writes or allocates) .{ .transacts = true, .detail = types.heapDetail(reads, writes, allocates) } else .{};
            stated.* = true;
        }
        fn classIndex(class: types.Type) u32 {
            return @backingInt(class) - catalogue.builtin_count;
        }

        /// Compiles the `Block{...}` clauses of `class`, in the order written, into one function
        /// `(Self:class)<transacts>:logic`, and records what a new instance of `class` is handed to:
        /// the functions of its superclasses, outermost first, then this one. The function is called
        /// by name on an instance the caller just built, so nothing is dispatched; it cannot fail,
        /// which the missing `<decides>` enforces like in any function.
        fn compileBlocks(self: *Self, class: types.Type, name: Token, cursors: []const u32, live: []const LiveField) ParseError!void {
            const w = self.workspace;
            const item = catalogue.definition(class, self.definitions()).?.class;
            const inherited: Span = if (item.parent) |parent| w.class_blocks[classIndex(parent)] else .{ .start = 0, .end = 0 };
            // A stated class effect bounds everything building an instance runs, so the block
            // clauses it inherits from an unstated superclass must lie within it (RFC-0078).
            const stated = w.class_effects[classIndex(class)];
            // RFC-0085, I12: a class that predicts has defaults that predict, as its clauses do.
            if (stated.effect.detail.predicts) for (w.field_defaults[item.fields.start + item.inherited .. item.fields.end]) |default| {
                if (self.dictatingTemplate(default.start, default.end)) return w.fail(name.span, .construction_requires_dictates);
            };
            if (stated.stated) for (w.block_calls[inherited.start..inherited.end]) |target| {
                if (missingEffect(w.runtime_functions.definitions[target].effects().heap(), stated.effect.set(), narrower_codes)) |code| return w.fail(name.span, code);
            };
            if (cursors.len == 0 and live.len == 0) {
                w.class_blocks[classIndex(class)] = inherited;
                return;
            }
            const above = inherited.end - inherited.start;
            const start = w.block_call_count;
            if (above + 1 > w.block_calls.len - start) return w.fail(name.span, .method_limit);
            if (w.functions.count + w.generic_count == types.limits.functions) return w.fail(name.span, .function_limit);
            // A class whose only clauses are its live fields' is named by its word `class`, which
            // no program can declare, as it cannot declare `Block` (C34).
            const keyword = if (cursors.len != 0) w.tokens[cursors[0]] else live[0].keyword;
            var function: functions.Definition = .{ .name = keyword.span, .value_type = .logic, .is_public = false, .is_method = true, .transacts = true, .start = w.functions.node_count, .end = 0, .root = 0 };
            // The clauses may do what the class says building it does; a class that says nothing
            // leaves them `<transacts>`, and whoever builds it is asked for that (RFC-0078).
            const declared = w.class_effects[classIndex(class)];
            if (declared.stated) {
                function.transacts = declared.effect.transacts;
                function.detail = declared.effect.detail;
            }
            function.parameters[0] = .{ .name = Span.self_word, .value_type = class };
            function.defaults[0] = .{};
            function.parameter_count = 1;
            self.function = function;
            self.method_class = class;
            self.member_expression = true;
            self.class_block = true;
            // A type completed inside a clause compiles its own clauses and then goes on here.
            const pending_around = w.blocks_pending;
            w.blocks_pending = class;
            defer {
                self.function = null;
                self.method_class = null;
                self.member_expression = false;
                self.class_block = false;
                w.blocks_pending = pending_around;
            }
            // RFC-0084, P4.2: first the live fields of the class, in the order declared, each
            // attached to the new instance with its guard, which captures `Self`.
            for (live) |entry| try self.attachLiveField(class, entry);
            // The IR is a sequence, so the clauses of one class are one body: each is compiled
            // where the last one ended, and its value is dropped.
            for (cursors) |cursor| {
                self.cursor = cursor;
                _ = try self.parseExpression(null);
            }
            function.root = try self.emit(.{ .span = keyword.span, .value_type = .logic, .kind = .{ .boolean = true } });
            function.end = w.functions.node_count;
            function.work = self.body(function.start, function.root).work;
            try self.checkPredicting(function);
            function.runtime = w.runtime_functions.publishAlias(function, &w.functions, self.definitions(), w.bindings[0..w.binding_count], w.binding_cells[0..w.binding_count], w.node_count) catch |err| return w.fail(keyword.span, switch (err) {
                error.FunctionLimit => .function_limit,
                error.NodeLimit => .template_limit,
                error.MemberLimit => .aggregate_limit,
                error.ArgumentLimit => .call_argument_limit,
                error.GlobalLimit => .binding_limit,
            });
            w.functions.publishIn(function, w.source, w.scope());
            // Only the clauses of a class with live fields of its own attach them (RFC-0084).
            if (live.len != 0) w.runtime_functions.definitions[function.runtime.?].clauses_of = class;
            std.mem.copyForwards(u32, w.block_calls[start..][0..above], w.block_calls[inherited.start..inherited.end]);
            w.block_calls[start + above] = function.runtime.?;
            w.block_call_count = start + above + 1;
            w.class_blocks[classIndex(class)] = .{ .start = start, .end = w.block_call_count };
        }

        /// `object_live(Self, F, <guard>)` for a live field of `class` (RFC-0084, P4.2), in its
        /// block-clause function: the guard is compiled where the field declared it, as the
        /// guard of `set live Self.F = G` is, and is attached to the field of the new instance.
        fn attachLiveField(self: *Self, class: types.Type, entry: LiveField) ParseError!void {
            const w = self.workspace;
            const field = catalogue.classFieldAt(class, entry.index, self.definitions(), self.fields()).?;
            // What attaching does, which the class's clauses must be allowed (`call_requires_*`
            // where a class states less).
            try self.liveForm(entry.name.span);
            try self.callEffect(entry.name.span, .{ .reads = true, .writes = true, .allocates = true, .diverges = false });
            _ = w.catalogue.internLive(field.value_type) catch |err| return w.fail(entry.name.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            const object = try self.selfValue(entry.name.span);
            self.cursor = entry.guard;
            self.live_guard_type = field.value_type;
            // RFC-0084, P4.3: the guard of a field whose type is a function reads its raw field.
            if (entry.raw != no_member) self.live_raw = .{ .field = entry.raw };
            const guard = try self.parseExpression(field.value_type);
            self.live_raw = null;
            try self.takeGuard(guard, field.value_type);
            _ = try self.emit(.{ .span = entry.name.span, .value_type = field.value_type, .kind = .{ .object_live = .{ .object = object, .field = entry.index, .guard = guard } } });
        }

        /// Whether the member at the cursor of a class body is a field whose type is a function
        /// (RFC-0084, P4.3): `In->Out:F = E`, or one whose type names a function or a method
        /// path. The cursor is left where it is.
        fn liveTypeFieldAhead(self: *Self) ParseError!bool {
            const w = self.workspace;
            const start = self.cursor;
            defer self.cursor = start;
            const access = struct {
                fn at(parser: *const Self, index: u32) bool {
                    const tokens = &parser.workspace.tokens;
                    return tokens[index].kind == .less and tokens[index + 1].kind == .identifier and tokens[index + 2].kind == .greater;
                }
            };
            if (self.peek().kind != .identifier) return false;
            if (std.mem.eql(u8, self.peek().span.text(w.source), "var")) {
                self.cursor += 1;
                if (access.at(self, self.cursor)) self.cursor += 3;
            }
            if (self.peek().kind == .identifier and std.mem.eql(u8, self.peek().span.text(w.source), "live") and w.tokens[self.cursor + 1].kind == .identifier) self.cursor += 1;
            if (self.peek().kind != .identifier) return false;
            self.cursor += 1;
            while (access.at(self, self.cursor)) self.cursor += 3;
            if (self.arrowAhead()) return true;
            return (try self.functionTypeAhead()) != null;
        }
        /// `<public>` and the other access specifiers after the name of a field whose type is a
        /// function (RFC-0084, P4.3); `<override>` and `<final>` are not for such a field.
        fn liveTypeFieldAccess(self: *Self) ParseError!?Access {
            const w = self.workspace;
            var stated: ?Access = null;
            while (self.peek().kind == .less) {
                _ = try self.take(.less, .unsupported_specifier);
                const word = try self.take(.identifier, .unsupported_specifier);
                _ = try self.take(.greater, .unsupported_specifier);
                const text = word.span.text(w.source);
                if (std.mem.eql(u8, text, "override")) return w.fail(word.span, .live_target);
                if (stated != null) return w.fail(word.span, .unsupported_specifier);
                stated = Access.named(text) orelse return w.fail(word.span, .unsupported_specifier);
            }
            return stated;
        }
        /// Declares a field whose type is a function (RFC-0084, P4.3, L8) in the class body being
        /// read: the raw field `In` (named, or hidden) and after it the live-only field `Out`,
        /// whose guard the class's clauses attach (`attachLiveField`), after the guard of `In`
        /// when it is declared `live`.
        noinline fn declareLiveTypeField(self: *Self, class: types.Type, inherited: u32, parent_fields: Span, count: *u32, live_fields: []LiveField, live_count: *u32, keyword: Token) ParseError!void {
            const w = self.workspace;
            var first = try self.take(.identifier, .expected_field);
            const is_var = std.mem.eql(u8, first.span.text(w.source), "var");
            var write_stated: ?Access = null;
            if (is_var and self.peek().kind == .less) {
                _ = try self.take(.less, .unsupported_specifier);
                const word = try self.take(.identifier, .unsupported_specifier);
                _ = try self.take(.greater, .unsupported_specifier);
                write_stated = Access.named(word.span.text(w.source)) orelse return w.fail(word.span, .unsupported_specifier);
            }
            if (is_var) first = try self.take(.identifier, .expected_field);
            const is_live = std.mem.eql(u8, first.span.text(w.source), "live") and self.peek().kind == .identifier;
            if (is_live) first = try self.take(.identifier, .expected_field);
            const first_stated = try self.liveTypeFieldAccess();
            var out = first;
            var out_stated = first_stated;
            const named = self.arrowAhead();
            if (named) {
                self.cursor += 2;
                out = try self.take(.identifier, .expected_field);
                out_stated = try self.liveTypeFieldAccess();
            }
            const names = [2]Token{ first, out };
            for (names[@intFromBool(!named)..]) |name| {
                if (w.localQualified(name.span.start)) return w.fail(name.span, .invalid_qualifier);
                if (rawNamed(name.span.text(w.source))) return w.fail(name.span, .expected_field);
                const text = name.span.text(w.source);
                for (w.record_fields[0..count.*]) |earlier| if (std.mem.eql(u8, earlier.name.text(w.source), text)) return w.fail(name.span, .duplicate_field);
                for (self.fields()[parent_fields.start..parent_fields.end]) |earlier| if (std.mem.eql(u8, earlier.name.text(w.source), text)) return w.fail(name.span, .duplicate_field);
            }
            if (named and std.mem.eql(u8, first.span.text(w.source), out.span.text(w.source))) return w.fail(out.span, .duplicate_field);
            const form = (try self.functionTypeAhead()) orelse return w.fail(self.typeAfterColon(), .live_type_form);
            if (inherited + count.* + 2 > w.record_fields.len or w.catalogue.field_count + inherited + count.* + 2 > w.field_defaults.len) return w.fail(out.span, .field_limit);
            if (w.live_type_count == w.live_types.len) return w.fail(out.span, .field_limit);
            const raw_span = if (named) first.span else try self.rawName(out.span);
            // Diagnostics about the raw value are placed at the name the program wrote.
            const raw_place = if (named) first else out;
            // The raw field: what the program assigns, as declared.
            const raw = inherited + count.*;
            w.record_fields[count.*] = .{ .name = raw_span, .value_type = form.parameter, .is_var = is_var, .live_only = is_live and !is_var };
            w.noteDeclaration(raw_span, .member, self.ownerOf(class));
            w.staged_fields = count.* + 1;
            if (is_live) live_fields[live_count.*] = .{ .index = raw, .guard = self.cursor + 1, .name = raw_place, .keyword = keyword };
            const raw_default = if (is_live) try self.parseLiveDefault(raw_place, form.parameter) else try self.parseDefault(raw_place, form.parameter);
            if (is_live) live_count.* += 1;
            var index = w.catalogue.field_count + raw;
            w.field_defaults[index] = raw_default;
            // A hidden raw field is no member any code names: only its class's guard reads it.
            w.field_access[index] = if (named) first_stated orelse .internal else .private;
            w.field_write[index] = if (named) write_stated orelse w.field_access[index] else .private;
            if (!w.field_write[index].within(w.field_access[index])) return w.fail(raw_place.span, .unsupported_specifier);
            w.field_final[index] = false;
            w.field_live[index] = is_live;
            count.* += 1;
            w.staged_fields = count.*;
            // The field that follows `F` of the raw field, live-only and attached by its guard.
            const followed = inherited + count.*;
            w.record_fields[count.*] = .{ .name = out.span, .value_type = form.result, .is_var = false, .live_only = true };
            w.noteDeclaration(out.span, .member, self.ownerOf(class));
            w.staged_fields = count.* + 1;
            live_fields[live_count.*] = .{ .index = followed, .guard = form.group, .name = out, .keyword = keyword, .raw = raw };
            live_count.* += 1;
            const out_default = try self.liveTypeDefault(out, form.result);
            index = w.catalogue.field_count + followed;
            w.field_defaults[index] = out_default;
            w.field_access[index] = out_stated orelse .internal;
            // Whoever may assign the variable assigns it through `Out`, its raw value's writer.
            w.field_write[index] = write_stated orelse w.field_access[index];
            if (!w.field_write[index].within(w.field_access[index])) return w.fail(out.span, .unsupported_specifier);
            w.field_final[index] = false;
            w.field_live[index] = true;
            count.* += 1;
            w.staged_fields = count.*;
            w.live_types[w.live_type_count] = .{ .class = class, .out = followed, .raw = raw, .fixed = !is_var, .hidden = !named };
            w.live_type_count += 1;
        }
        /// The default `object_new` gives the field that follows a function of its raw field
        /// (RFC-0084, P4.3): its type's, as for every live field (C26).
        fn liveTypeDefault(self: *Self, field: Token, value_type: types.Type) ParseError!functions.Body {
            const w = self.workspace;
            std.debug.assert(self.function == null and !self.default_expression);
            const start = w.functions.node_count;
            const members = w.functions.member_count;
            const arguments = w.functions.argument_count;
            self.function = .{ .name = field.span, .value_type = value_type, .is_public = false, .start = start, .end = 0, .root = 0 };
            self.default_expression = true;
            defer {
                self.function = null;
                self.default_expression = false;
            }
            const root = (try self.typeDefault(value_type, field.span)) orelse return w.fail(field.span, .live_field_default);
            const result = self.body(start, root);
            if (w.instantiation_depth != 0) return self.relocateDefault(result, members, arguments, field.span);
            return result;
        }
        /// The variable whose type is a function that field `index` of `class` belongs to
        /// (RFC-0084, P4.3), as its raw field or as the field that follows it. Inherited fields
        /// are first, at the indices the class that declared them gave them.
        fn liveTypeOfField(self: *const Self, class: types.Type, index: u32) ?LiveType {
            const w = self.workspace;
            if (w.live_type_count == 0) return null;
            var owner = class;
            while (catalogue.definition(owner, self.definitions())) |item| {
                if (item != .class) return null;
                const parent = item.class.parent orelse break;
                const above = catalogue.definition(parent, self.definitions()).?.class.fields;
                if (index >= above.end - above.start) break;
                owner = parent;
            } else return null;
            for (w.live_types[0..w.live_type_count]) |entry| if (entry.class == owner and (entry.out == index or entry.raw == index)) return entry;
            return null;
        }
        /// The default a live field (RFC-0084, P4.2) gets from `object_new`, the cursor at the `=`
        /// before its guard `<guard>{ G }`: the default of the field's type, and a type without
        /// one is `live_field_default` (C26). The guard itself is compiled once, with the class's
        /// clauses, which attach it and write the field.
        fn parseLiveDefault(self: *Self, field: Token, value_type: types.Type) ParseError!functions.Body {
            const w = self.workspace;
            std.debug.assert(self.function == null and !self.default_expression);
            if (self.peek().kind != .equal or w.tokens[self.cursor + 1].kind != .synthetic_guard or w.tokens[self.cursor + 2].kind != .left_brace) return w.fail(self.peek().span, .expected_equal);
            const open = self.cursor + 2;
            const close: u32 = @intCast(w.segmentClose(open));
            if (close >= w.token_count or w.tokens[close].kind != .right_brace) return w.fail(field.span, .macro_syntax);
            const start = w.functions.node_count;
            const members = w.functions.member_count;
            const arguments = w.functions.argument_count;
            self.function = .{ .name = field.span, .value_type = value_type, .is_public = false, .start = start, .end = 0, .root = 0 };
            self.default_expression = true;
            defer {
                self.function = null;
                self.default_expression = false;
            }
            const root = (try self.typeDefault(value_type, field.span)) orelse return w.fail(field.span, .live_field_default);
            self.cursor = close + 1;
            const result = self.body(start, root);
            if (w.instantiation_depth != 0) return self.relocateDefault(result, members, arguments, field.span);
            return result;
        }

        /// The default value of a type, built from constants (RFC-0084, P4.2): `0`, `0.0`,
        /// `false`, `""`, the empty array, map or option, the first case of an enum, and a tuple
        /// or struct of those. Null for every other type (a class, a function, `any`, a task, an
        /// event, `rational`, a refinement), which has none.
        fn typeDefault(self: *Self, value_type: types.Type, span: Span) ParseError!?u32 {
            const w = self.workspace;
            if (value_type == .i64) return try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .integer = 0 } });
            if (value_type == .float) return try self.emit(.{ .span = span, .value_type = .float, .kind = .{ .floating = 0.0 } });
            if (value_type == .logic) return try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .boolean = false } });
            if (value_type == .string) return try self.emit(.{ .span = span, .value_type = .string, .kind = .{ .string = .{ .start = 0, .end = 0 } } });
            if (value_type.isCharacter()) return try self.emit(.{ .span = span, .value_type = value_type, .kind = .{ .character = 0 } });
            // RFC-0085, I8: only an access makes an `accessor`.
            if (w.standardAccessor()) |standard| if (value_type == standard) return null;
            const shape = catalogue.definition(value_type, self.definitions()) orelse return null;
            switch (shape) {
                // RFC-0087, W3: an empty `weak_map` is the empty map built at its type.
                .array, .map, .option, .weak_map => return try self.emit(.{ .span = span, .value_type = value_type, .kind = .{ .aggregate = try self.reserveMembers(0, span) } }),
                .enumeration => |enumeration| {
                    if (enumeration.cases.start == enumeration.cases.end) return null;
                    return try self.emit(.{ .span = span, .value_type = value_type, .kind = .{ .enumeration = 0 } });
                },
                .tuple, .record => {
                    const parts: []const types.Type = if (shape == .tuple) w.catalogue.tuple_elements[shape.tuple.start..shape.tuple.end] else &.{};
                    const count: u32 = if (shape == .tuple) @intCast(parts.len) else shape.record.fields.end - shape.record.fields.start;
                    var members: [types.limits.record_fields]u32 = undefined;
                    if (count > members.len) return null;
                    for (0..count) |index| {
                        const part = if (shape == .tuple) parts[index] else self.fields()[shape.record.fields.start + index].value_type;
                        members[index] = (try self.typeDefault(part, span)) orelse return null;
                    }
                    const range = try self.reserveMembers(count, span);
                    @memcpy(self.memberPool()[range.start..range.end], members[0..count]);
                    return try self.emit(.{ .span = span, .value_type = value_type, .kind = .{ .aggregate = range } });
                },
                .callable, .class, .rational, .task, .refinement, .event, .live, .scheduled_interface, .cancelable, .ref, .grant => return null,
            }
        }

        /// Hands the instance `object`, just built, to the block clauses of its class: its
        /// superclasses' first. Each call is blamed on the clause it runs, which also keeps it
        /// inside the module that owns the function when the class is built from another.
        fn emitBlockCalls(self: *Self, class: types.Type, object: u32) ParseError!void {
            const w = self.workspace;
            const range = w.class_blocks[classIndex(class)];
            for (w.block_calls[range.start..range.end]) |target| {
                const callee = w.runtime_functions.definitions[target];
                var receiver = [1]u32{object};
                if (callee.parameters[0] != class) receiver[0] = try self.emit(.{ .span = callee.name, .value_type = callee.parameters[0], .kind = .{ .upcast = object } });
                const arguments = try self.reserveArguments(&receiver, callee.name);
                _ = try self.emit(.{ .span = callee.name, .value_type = .logic, .kind = .{ .call = .{ .function = target, .arguments = arguments } } });
            }
        }

        /// A member that starts `Name(` or `Name<` declares a method; a field starts `Name:` or `var Name:`.
        fn methodAhead(self: *const Self) bool {
            const token = self.peek();
            if (token.kind != .identifier or std.mem.eql(u8, token.span.text(self.workspace.source), "var")) return false;
            // Specifiers sit between the name and either the parameters of a method or the type of a field.
            const tokens = &self.workspace.tokens;
            var at = self.cursor + 1;
            while (tokens[at].kind == .less and tokens[at + 1].kind == .identifier and tokens[at + 2].kind == .greater) at += 3;
            return tokens[at].kind == .left_paren;
        }

        /// `Name<specifiers>[T:type, ...](...)`: a member with type parameters is a generic
        /// method (RFC-0081). No field starts `Name[` and no other method has a bracket there.
        fn genericMethodAhead(self: *const Self) bool {
            const token = self.peek();
            if (token.kind != .identifier or std.mem.eql(u8, token.span.text(self.workspace.source), "var")) return false;
            const tokens = &self.workspace.tokens;
            var at = self.cursor + 1;
            while (tokens[at].kind == .less and tokens[at + 1].kind == .identifier and tokens[at + 2].kind == .greater) at += 3;
            return tokens[at].kind == .left_bracket;
        }

        /// Declares the generic method that starts here (RFC-0081): a template, like a generic
        /// function's, whose receiver is `class`. It has no slot: a list of type arguments makes
        /// another function type, so no slot could hold every specialization. It is therefore
        /// final, has a body, and is called as the class that declares it sees it. An
        /// instantiation of a parametric type reads the declaration its first instantiation made.
        fn declareGenericMethod(self: *Self, class: types.Type, is_interface: bool) ParseError!void {
            const w = self.workspace;
            const name = self.peek();
            if (self.generic) |context| if (w.generic_templates[context.template].kind != .function) {
                if (self.methodTemplateAt(name.span) != null) return self.skipMember();
            };
            self.cursor += 1;
            const text = name.span.text(w.source);
            if (reserved(text) or generatedName(text)) return w.fail(name.span, .expected_name);
            var access: ?Access = null;
            var is_final = false;
            while (self.peek().kind == .less) {
                _ = try self.take(.less, .unsupported_specifier);
                const word = try self.take(.identifier, .unsupported_specifier);
                _ = try self.take(.greater, .unsupported_specifier);
                const stated = word.span.text(w.source);
                // What a slot would allow is what a generic method cannot have.
                if (std.mem.eql(u8, stated, "override") or std.mem.eql(u8, stated, "abstract")) return w.fail(word.span, .generic_method_slot);
                if (std.mem.eql(u8, stated, "final") and !is_final) is_final = true else if (Access.named(stated) != null and access == null) access = Access.named(stated) else return w.fail(word.span, .unsupported_specifier);
            }
            // An interface's members are `<public>` or `<internal>` (RFC-0076).
            if (is_interface) if (access) |stated| if (stated != .public and stated != .internal) return w.fail(name.span, .invalid_interface);
            try self.parseGenericDeclaration(name, false, .{ .class = class, .access = access orelse .internal });
            w.method_templates += 1;
            const id = w.generic_count - 1;
            if (w.method_table.crowded()) {
                w.method_table.grow(&w.method_slots);
                for (w.generic_templates[0..id], 0..) |earlier, at| if (earlier.kind == .method) w.method_table.enter(&w.method_slots, methodHash(methodOwner(earlier), earlier.name.text(w.source)), @intCast(at));
            }
            w.method_table.enter(&w.method_slots, methodHash(methodOwner(w.generic_templates[id]), text), id);
        }

        /// What declares a generic method: its class, or its parametric type's template.
        fn methodOwner(template: GenericTemplate) u32 {
            return if (template.outer == no_member) @backingInt(template.receiver) else parametric_owner + template.outer;
        }
        const parametric_owner: u32 = 1 << 16;
        fn methodHash(owner: u32, name: []const u8) u64 {
            return std.hash.Wyhash.hash(owner, name);
        }

        /// The generic method declared at `name`, if its declaration has been read: the one an
        /// earlier instantiation of the same parametric type made.
        fn methodTemplateAt(self: *const Self, name: Span) ?u32 {
            const w = self.workspace;
            _ = self.findGeneric(name.text(w.source), w.scope());
            var same = w.generic_table.walk(&w.generic_slots, name_index.hashName(0, name.text(w.source)));
            while (same.next()) |index| {
                if (w.generic_templates[index].kind == .method and std.meta.eql(w.generic_templates[index].name, name)) return index;
            }
            return null;
        }

        /// The generic method `name` of `class` (RFC-0081): declared by it, or, with `strict`,
        /// only by a type above it. Null when there is none. Two that the class reaches by
        /// different supertypes are `ambiguous_call` at `span`, as two slots would be.
        fn genericMethodOf(self: *const Self, class: types.Type, name: []const u8, strict: bool, span: Span) ParseError!?MethodFound {
            const w = self.workspace;
            const definition = catalogue.definition(class, self.definitions()) orelse return null;
            if (definition != .class or catalogue.pendingClass(definition.class)) return null;
            // Each supertype of the class, and the template of each that is an instantiation, is
            // asked for a method of the name it declares: one probe each.
            const above = catalogue.Supertypes.of(class, self.definitions()) orelse return null;
            var found: ?MethodFound = null;
            var bits = above.reached.iterator(.{});
            while (bits.next()) |bit| {
                const candidate: types.Type = @fromBackingInt(@as(u16, @intCast(bit + catalogue.builtin_count)));
                if (strict and candidate == class) continue;
                const instance = w.instanceOf(candidate);
                for ([2]?u32{ @backingInt(candidate), if (instance) |index| parametric_owner + w.instances[index].template else null }) |maybe| {
                    const owner = maybe orelse continue;
                    var same = w.method_table.walk(&w.method_slots, methodHash(owner, name));
                    while (same.next()) |id| {
                        const template = w.generic_templates[id];
                        if (methodOwner(template) != owner or !std.mem.eql(u8, name, template.name.text(w.source))) continue;
                        // `class(Box[i64], Box[string])` reaches two: neither is the receiver.
                        if (found != null) return w.fail(span, .ambiguous_call);
                        found = if (template.outer == no_member) .{ .id = id, .receiver = candidate, .instance = no_member } else .{ .id = id, .receiver = candidate, .instance = instance.? };
                    }
                }
            }
            return found;
        }

        /// Whether `argument` may stand for parameter `index` of `template`: each constraint is
        /// checked where the argument is written, before anything is compiled for it.
        fn boundAdmits(self: *Self, template: GenericTemplate, index: usize, argument: types.Type, span: Span) ParseError!void {
            const w = self.workspace;
            const bit = @as(u32, 1) << @intCast(index);
            if (template.comparable_mask & bit != 0 and !self.comparable(argument)) return w.fail(span, w.equalityCode(argument, .not_comparable));
            if (template.subtype_mask & bit != 0 and !catalogue.assignable(argument, template.bounds[index], self.definitions())) return w.fail(span, .type_argument_bound);
            if (template.castable_mask & bit != 0 and !self.castableClass(argument)) return w.fail(span, .not_castable);
            if (template.concrete_mask & bit != 0 and !self.concreteClass(argument)) return w.fail(span, .not_concrete);
        }

        /// A generic method may not take a name that a member of its class, or of a class
        /// above or below it, has: it would hide that member or be hidden by it, and it cannot
        /// be overridden or override. Checked when a class has its fields, before its methods
        /// are declared: the generic methods it declares (from `first` on), the fields it adds
        /// and the methods it writes, against each other and against what is above it.
        fn checkGenericMethods(self: *Self, class: types.Type, first: u32, own_fields: []const types.Field, method_cursors: []const u32) ParseError!void {
            const w = self.workspace;
            for (w.generic_templates[first..w.generic_count], first..) |template, index| {
                if (template.kind != .method or template.receiver != class) continue;
                const text = template.name.text(w.source);
                for (w.generic_templates[first..index]) |earlier| if (earlier.kind == .method and earlier.receiver == class and std.mem.eql(u8, earlier.name.text(w.source), text)) return w.fail(template.name, .duplicate_name);
                for (method_cursors) |cursor| if (std.mem.eql(u8, w.tokens[cursor].span.text(w.source), text)) return w.fail(template.name, .duplicate_name);
                if (catalogue.findField(class, text, self.definitions(), self.fields(), w.source) != null) return w.fail(template.name, .duplicate_name);
                if (w.findMethod(class, text) != null) return w.fail(template.name, .generic_method_slot);
                if (try self.genericMethodOf(class, text, true, template.name) != null) return w.fail(template.name, .generic_method_slot);
            }
            for (own_fields) |field| if (try self.genericMethodOf(class, field.name.text(w.source), true, field.name) != null) return w.fail(field.name, .generic_method_slot);
            for (method_cursors) |cursor| {
                const method_name = w.tokens[cursor].span;
                if (try self.genericMethodOf(class, method_name.text(w.source), true, method_name) != null) return w.fail(method_name, .generic_method_slot);
            }
        }

        /// `Receiver.Name[Types](Arguments)` for a generic method (RFC-0081): the method's
        /// specialization for `Types` with the receiver's declaring class as its first parameter.
        /// A specialization that exists is called, or bound to the receiver when no call
        /// follows, as a method is. One that does not is compiled first: the parse continues in
        /// its body and comes back to read this access again (`AnonymousFrame.method`).
        fn startGenericMethod(self: *Self, receiver: u32, found: MethodFound, name: Token) ParseError!bool {
            const w = self.workspace;
            const template = w.generic_templates[found.id];
            const dot = self.cursor - 2;
            std.debug.assert(w.tokens[dot].kind == .dot);
            try self.checkAccess(template.access, found.receiver, name.span);
            w.noteName(name.span, template.name.start, .member, qualify.none);
            if (self.peek().kind != .left_bracket) return w.fail(name.span, .type_arguments_required);
            _ = try self.take(.left_bracket, .expected_call);
            self.skipNewlines();
            // The method's own arguments, then its receiver's class: what names the
            // specialization, since a parametric type's instantiations share the method's name.
            var arguments: [types.limits.parameters]types.Type = undefined;
            var count: usize = 0;
            while (true) {
                if (count + 1 == arguments.len) return w.fail(name.span, .argument_count);
                arguments[count] = if (count < template.parameter_count and template.effect_mask >> @intCast(count) & 1 != 0) try self.parseEffectArgument() else try self.parseTypeValue();
                count += 1;
                self.skipNewlines();
                if (self.peek().kind == .right_bracket) break;
                _ = try self.take(.comma, .expected_type);
                self.skipNewlines();
            }
            self.cursor += 1;
            if (count != template.parameter_count) return w.fail(name.span, .argument_count);
            for (arguments[0..count], 0..) |argument, index| try self.boundAdmits(template, index, argument, name.span);
            arguments[count] = found.receiver;
            const key = try self.internTuple(arguments[0 .. count + 1], name.span);
            const own = self.generic != null and self.generic.?.template == found.id and self.function != null and std.meta.eql(self.function.?.name, template.name) and self.function.?.specialization == key;
            const method: u32 = if (own) try self.emit(.{ .span = name.span, .value_type = try self.functionType(self.function.?, name.span), .kind = .self_value }) else if (w.findSpecialization(template.name, key)) |target| published: {
                const f = w.runtime_functions.definitions[target];
                var concrete: functions.Definition = .{ .name = f.name, .value_type = f.value_type, .is_public = false, .transacts = f.transacts, .decides = f.decides, .detail = f.detail, .parameter_count = f.parameter_count, .start = 0, .end = 0, .root = 0 };
                for (f.parameters[0..f.parameter_count], concrete.parameters[0..f.parameter_count]) |value_type, *entry| entry.* = .{ .name = f.name, .value_type = value_type };
                break :published try self.emit(.{ .span = name.span, .value_type = try self.functionType(concrete, name.span), .kind = .{ .function_value = @intCast(target) } });
            } else {
                try self.specializeMethod(found, key, arguments[0..count], dot, name.span);
                self.continued = true;
                return true;
            };
            const callable = self.node(method).value_type;
            const shape = catalogue.definition(callable, self.definitions()).?.callable;
            const as_receiver = try self.coerce(receiver, found.receiver);
            const open = self.peek();
            if (open.kind != .left_paren and open.kind != .left_bracket) {
                // Named without a call: a function value that remembers its receiver.
                const parameters = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
                var bound = [1]u32{as_receiver};
                const residual = w.catalogue.internTuple(w.catalogue.tuple_elements[parameters.start + 1 .. parameters.end]) catch |err| return w.fail(name.span, if (err == error.TypeLimit) .type_limit else .tuple_limit);
                const value_type = w.catalogue.internCallable(.{ .parameters = residual, .result = shape.result, .transacts = shape.transacts, .decides = shape.decides, .detail = shape.detail }) catch |err| return w.fail(name.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                const range = try self.reserveArguments(&bound, name.span);
                w.operands[self.operand_count - 1] = try self.emit(.{ .span = name.span, .value_type = value_type, .kind = .{ .bind = .{ .callable = method, .arguments = range } } });
                return false;
            }
            if ((open.kind == .left_bracket) != shape.decides) return w.fail(open.span, .expected_call);
            self.cursor += 1;
            try self.callEffect(open.span, shape.effects());
            if (shape.decides and !self.failureContext()) return w.fail(open.span, .failure_context_required);
            self.operand_count -= 1;
            try self.pushOperator(.{ .kind = .invoke, .span = open.span, .function = method, .operand_base = self.operand_count, .selected = if (shape.decides) 1 else no_member, .arguments = 1, .receiver = true });
            try self.pushOperand(as_receiver);
            return true;
        }

        /// Starts compiling the specialization `key` of a generic method, as `startGeneric` does
        /// for a generic function: in the method's module, with its type parameters bound to
        /// `arguments`, the class's to the receiver's instantiation, and `Self` its receiver.
        fn specializeMethod(self: *Self, found: MethodFound, key: types.Type, arguments: []const types.Type, dot: u32, span: Span) ParseError!void {
            const w = self.workspace;
            const template = w.generic_templates[found.id];
            for (w.anonymous_frames[0..w.anonymous_count]) |frame| if (frame.kind == .generic and std.meta.eql(frame.definition.name, template.name) and frame.definition.specialization == key) return w.fail(span, .recursive_call);
            if (w.anonymous_count == w.anonymous_frames.len or w.runtime_functions.count == types.limits.functions) return w.fail(span, .function_limit);
            const work = template.end - template.header;
            if (work > types.limits.compiler_work - w.expansion_work) return w.fail(span, .compiler_work_limit);
            w.expansion_work += work;
            w.anonymous_frames[w.anonymous_count] = .{
                .kind = .generic,
                .return_cursor = dot,
                .reference_span = span,
                .parent_module = w.current_module,
                .parent_nested = w.current_nested,
                .parent_generic = self.generic,
                .definition = .{ .name = template.name, .value_type = undefined, .is_public = false, .specialization = key, .generic_source = template.source, .template_public = template.access == .public, .start = w.functions.node_count, .end = 0, .root = 0 },
                .parent_function = self.function,
                .expected_type = self.expected_type,
                .default_expression = self.default_expression,
                .control_depth = self.control_depth,
                .operator_base = self.operator_base,
                .operand_base = self.operand_base,
                .local_base = self.local_base,
                .parentheses = 0,
                .operators = self.operator_count,
                .operands = self.operand_count,
                .locals = w.local_count,
                .checkpoints = w.local_checkpoint_count,
                .failable_uses = w.failable_uses,
                .template_nodes = w.functions.node_count,
                .template_members = w.functions.member_count,
                .template_arguments = w.functions.argument_count,
                .staging = w.staging_count,
                .phase = .body,
                .method = true,
                .parent_method_class = self.method_class,
                .parent_member_expression = self.member_expression,
            };
            const frame = &w.anonymous_frames[w.anonymous_count];
            w.anonymous_count += 1;
            w.current_module = template.module;
            w.current_nested = template.nested;
            var context: GenericContext = .{ .template = found.id, .specialization = key, .instance = found.instance };
            @memcpy(context.arguments[0..arguments.len], arguments);
            self.generic = context;
            self.method_class = found.receiver;
            self.member_expression = false;
            self.cursor = template.header;
            var definition = frame.definition;
            frame.discards = try self.genericSignature(&definition);
            frame.definition = definition;
            self.operator_base = self.operator_count;
            self.operand_base = self.operand_count;
            self.local_base = w.local_count;
            self.function = definition;
            self.expected_type = if (frame.discards) null else definition.value_type;
            self.default_expression = false;
            self.control_depth = 0;
            self.skipNewlines();
        }

        /// Moves to the end of the member that starts here: its separator or the closing brace of the class.
        fn skipMember(self: *Self) ParseError!void {
            var depth: u32 = 0;
            while (true) {
                const token = self.peek();
                switch (token.kind) {
                    .eof => return self.workspace.fail(token.span, .unexpected_token),
                    .left_paren, .left_bracket, .left_brace => depth += 1,
                    .right_paren, .right_bracket => depth -|= 1,
                    .right_brace => {
                        if (depth == 0) return;
                        depth -= 1;
                    },
                    .newline, .separator, .comma => if (depth == 0) return,
                    else => {},
                }
                self.cursor += 1;
            }
        }

        /// `Name<override><final><abstract>(parameters)<effects>:Type` with the receiver `Self:Class` first.
        fn parseMethodSignature(self: *Self, class: types.Type, comptime defaults: Defaults) ParseError!MethodSignature {
            const w = self.workspace;
            const name = try self.take(.identifier, .expected_name);
            w.noteDeclaration(name.span, .member, self.ownerOf(class));
            var signature: MethodSignature = .{ .function = .{ .name = name.span, .value_type = undefined, .is_public = false, .start = w.functions.node_count, .end = 0, .root = 0, .is_method = true } };
            while (self.peek().kind == .less) {
                _ = try self.take(.less, .unsupported_specifier);
                const word = try self.take(.identifier, .unsupported_specifier);
                _ = try self.take(.greater, .unsupported_specifier);
                const text = word.span.text(w.source);
                if (std.mem.eql(u8, text, "override") and !signature.is_override) signature.is_override = true else if (std.mem.eql(u8, text, "final") and !signature.is_final) signature.is_final = true else if (std.mem.eql(u8, text, "abstract") and !signature.is_abstract) signature.is_abstract = true else if (Access.named(text) != null and signature.access == null) signature.access = Access.named(text) else return w.fail(word.span, .unsupported_specifier);
            }
            const function = &signature.function;
            _ = try self.take(.left_paren, .expected_parameter);
            function.parameters[0] = .{ .name = Span.self_word, .value_type = class };
            function.defaults[0] = .{};
            function.parameter_count = 1;
            try self.parseParameters(function, defaults);
            function.start = w.functions.node_count;
            var effect = try self.parseEffectIn(.expected_computes, true);
            // An abstract method may promise to converge; nothing yet holds an override to it, so
            // the promise is read and not carried into the slot's type (RFC-0078).
            signature.converges = effect.detail.converges;
            effect.detail.converges = false;
            function.transacts = effect.transacts;
            function.decides = effect.decides;
            function.detail = effect.detail;
            // An override would replace the body a transparent function guarantees (RFC-0085, V11).
            if (self.peek().kind == .colon and w.tokens[self.cursor + 1].kind == .equal) return w.fail(name.span, .transparent_method);
            const result = try self.parseResultType();
            function.value_type = result.value_type;
            signature.discards = result.discards;
            return signature;
        }

        /// Declares every method of a finished class, compiles their bodies, checks that a class that is
        /// not abstract implements everything it inherits, and records what each slot resolves to.
        fn finishMethods(self: *Self, class: types.Type, name: Token, is_abstract: bool, cursors: []const u32, blocks: []const u32, live: []const LiveField) ParseError!void {
            const w = self.workspace;
            const first = w.method_count;
            // Every signature first, so that a body can call any method of its class.
            for (cursors) |cursor| {
                self.cursor = cursor;
                try self.declareMethod(class, first);
            }
            // B4 (RFC-0092): the forwarders of the slots that narrower results replaced, after the
            // declarations, which the cursors and the bodies below are matched with by position.
            const declared = w.method_count;
            for (first..declared) |index| if (w.methods[index].refines != no_member) {
                try self.synthesizeRefinement(class, w.methods[index].name, w.methods[index].refines, w.methods[index].slot);
            };
            // RFC-0085, I8: the getters and setters are methods of the class, now declared.
            if (w.accessor_count != 0) try self.resolveAccessors(class, name, first);
            if (w.accessor_required != 0) try self.boundAccessors(class, name);
            // What a new instance of the class is handed to must be known before anything can
            // build one. A class without clauses of its own has its superclass's, known now;
            // one with clauses is marked, so that a type completed below, whose body builds this
            // class, is refused instead of handing the instance to clauses not compiled yet.
            if (blocks.len == 0 and live.len == 0) try self.compileBlocks(class, name, blocks, live) else w.class_blocks[classIndex(class)] = blocks_unknown;
            // The class has its fields and its signatures: from here on a parametric type that a
            // body names can be completed, and those the declaration named are, if they can be.
            w.declaring -= 1;
            try self.settle(name.span);
            // The block clauses before the method bodies: a method may build its own class,
            // and an instance is handed to every clause of its class.
            if (blocks.len != 0 or live.len != 0) try self.compileBlocks(class, name, blocks, live);
            for (cursors, first..) |cursor, index| {
                self.cursor = cursor;
                try self.compileMethod(class, index, is_abstract);
            }
            // Slots in ascending order keep the dispatch table sorted, since classes finish in order.
            const above = catalogue.Supertypes.of(class, self.definitions()).?;
            var reached_slots = w.visibleSlots(&above);
            while (reached_slots.next()) |slot| {
                const function = switch (w.implementationOf(@intCast(slot), &above)) {
                    .found => |index| w.methods[index].runtime.?,
                    .none => {
                        if (is_abstract) continue;
                        return w.fail(name.span, .unimplemented_method);
                    },
                    // Two interfaces offer a body and neither refines the other: the class must choose.
                    .ambiguous => {
                        if (is_abstract) continue;
                        return w.fail(name.span, .ambiguous_call);
                    },
                };
                if (w.dispatch_count == w.dispatch.len) return w.fail(name.span, .method_limit);
                if (w.dispatch_count != 0) {
                    const last = w.dispatch[w.dispatch_count - 1];
                    // Only an instantiation finishes out of the order of the type IDs (RFC-0073).
                    if (!(@backingInt(last.class) < @backingInt(class) or (last.class == class and last.slot < slot))) w.dispatch_unsorted = true;
                }
                w.dispatch[w.dispatch_count] = .{ .class = class, .slot = @intCast(slot), .function = function };
                w.dispatch_count += 1;
            }
        }

        /// `first` is where this class's own declarations start: they are the tail of the list.
        fn declareMethod(self: *Self, class: types.Type, first: u32) ParseError!void {
            const w = self.workspace;
            const signature = try self.parseMethodSignature(class, .parse);
            const function = signature.function;
            const text = function.name.text(w.source);
            const has_body = self.peek().kind == .equal;
            for (w.methods[first..w.method_count]) |method| {
                std.debug.assert(method.class == class);
                if (std.mem.eql(u8, method.name.text(w.source), text)) return w.fail(function.name, .duplicate_name);
            }
            if (w.method_count == w.methods.len) return w.fail(function.name, .method_limit);
            if (w.symbolNamed(text)) return w.fail(function.name, .duplicate_name);
            if (catalogue.findField(class, text, self.definitions(), self.fields(), w.source) != null) return w.fail(function.name, .duplicate_name);
            const is_interface = catalogue.definition(class, self.definitions()).?.class.is_interface;
            // A final member of an interface is complete: it has the body nothing below may replace.
            if (is_interface and (signature.is_abstract or (signature.is_final and !has_body))) return w.fail(function.name, .invalid_interface);
            if (signature.converges and !signature.is_abstract and !(is_interface and !has_body)) return w.fail(function.name, .converges_position);
            if (is_interface) if (signature.access) |access| if (access != .public and access != .internal) return w.fail(function.name, .invalid_interface);
            var slot: u32 = undefined;
            var narrowed: ?Narrowing = null;
            var replaced: u32 = no_member;
            // The class has no slot of this name of its own yet, so a match is inherited.
            if (w.findMethod(class, text)) |inherited| {
                // RFC-0085, I8: the getter and setter of a field are fixed where it is declared.
                if (w.accessor_count != 0 and self.accessorSlot(inherited)) return w.fail(function.name, .accessor_override);
                // An interface field has this name: a method cannot replace a field.
                if (w.slot_kind[inherited] != .method) return w.fail(function.name, .duplicate_name);
                // The access the method has here: its slot's, or what an override above narrowed it to.
                const seen = self.memberAccess(class, inherited);
                // A private method is invisible below its class, so it cannot be replaced there either.
                if (seen.access == .private) return w.fail(function.name, .inaccessible_member);
                // Nor can a member that is internal to another module be replaced from here.
                if (seen.access == .internal) try self.checkAccess(.internal, seen.declaring, function.name);
                if (!signature.is_override) return w.fail(function.name, .missing_override);
                if (w.sealedAbove(class, inherited)) return w.fail(function.name, .final_method);
                const shape = catalogue.definition(w.slots[inherited].callable, self.definitions()).?.callable;
                const parameters = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
                if (function.parameter_count != parameters.end - parameters.start) return w.fail(function.name, .override_mismatch);
                // B4 (RFC-0092): a class's override may narrow the result to a type below it (Book
                // 10:478); it then has a slot of its own, and the slot it replaces forwards to it.
                const refines = function.value_type != shape.result;
                if (refines and (is_interface or !self.narrowerResult(function.value_type, shape.result))) return w.fail(function.name, .override_mismatch);
                // Whoever calls through the slot declared the slot's effects: an override may do
                // less than they allow, never more (RFC-0078).
                if (missingEffect(Effect.of(function).set(), shape.effects(), override_codes)) |code| return w.fail(function.name, code);
                // A slot that predicts is filled by an override that predicts (RFC-0085, I12).
                if (Effect.of(function).set().dictates and !shape.effects().dictates) return w.fail(function.name, .override_widens_dictates);
                for (function.parameters[1..function.parameter_count], w.catalogue.tuple_elements[parameters.start + 1 .. parameters.end]) |declared, expected| {
                    if (declared.value_type != expected) return w.fail(function.name, .override_mismatch);
                }
                // An override keeps the access of the method it replaces, or narrows it (Book 12:385):
                // whoever may call it on this class may call it on the class above.
                var access = seen;
                if (signature.access) |stated| if (stated != seen.access) {
                    if (!stated.within(seen.access)) return w.fail(function.name, .override_mismatch);
                    access = .{ .access = stated, .declaring = class };
                };
                slot = inherited;
                if (refines) {
                    if (w.slot_count == w.slots.len) return w.fail(function.name, .method_limit);
                    slot = w.slot_count;
                    // The slot's parameters and effects, this receiver and this result.
                    var elements: [types.limits.parameters]types.Type = undefined;
                    elements[0] = class;
                    @memcpy(elements[1..function.parameter_count], w.catalogue.tuple_elements[parameters.start + 1 .. parameters.end]);
                    const callable = try self.internCallable(.{ .parameters = try self.internTuple(elements[0..function.parameter_count], function.name), .result = function.value_type, .transacts = shape.transacts, .decides = shape.decides, .detail = shape.detail }, function.name);
                    w.slots[slot] = .{ .owner = class, .callable = callable, .name = function.name };
                    w.slot_access[slot] = access.access;
                    w.slot_kind[slot] = .method;
                    w.slot_first[slot] = no_member;
                    w.slot_count += 1;
                    replaced = inherited;
                }
                // `public` holds everywhere, `internal` by module (an internal method is replaced
                // in its own module only), so only a protected access is judged by its class.
                if (access.access != w.slot_access[slot] or (access.access == .protected and access.declaring != w.slots[slot].owner)) narrowed = access;
            } else {
                if (signature.is_override) return w.fail(function.name, .unexpected_override);
                if (w.slot_count == w.slots.len) return w.fail(function.name, .method_limit);
                slot = w.slot_count;
                w.slots[slot] = .{ .owner = class, .callable = try self.functionType(function, function.name), .name = function.name };
                w.slot_access[slot] = signature.access orelse .internal;
                w.slot_kind[slot] = .method;
                w.slot_first[slot] = no_member;
                w.slot_count += 1;
            }
            try self.checkPlainClash(function.name, class, w.slots[slot].owner, function.parameters[1..function.parameter_count], w.scope());
            // What a call with named or omitted arguments reads from this declaration.
            const base = w.method_count * types.limits.parameters;
            for (function.parameters[1..function.parameter_count], function.defaults[1..function.parameter_count], 1..) |entry, default, position| {
                w.method_parameters[base + position] = .{ .name = entry.name, .default = default };
            }
            // An interface method without a body is abstract; one with a body is a default.
            w.methods[w.method_count] = .{ .class = class, .name = function.name, .slot = slot, .is_final = signature.is_final, .is_abstract = signature.is_abstract or (is_interface and !has_body) };
            if (narrowed) |held| {
                w.methods[w.method_count].narrowed = held;
                w.narrowed_count += 1;
            }
            // B4: the slot replaced by a narrower result is answered by forwarding to the new one,
            // once every declaration of the class is listed (`finishMethods`).
            w.methods[w.method_count].refines = replaced;
            w.linkMethod(w.method_count);
            w.method_count += 1;
        }

        /// B4 (RFC-0092): whether the class whose method is being compiled has a member `name`,
        /// which a builtin of that name leaves to the diagnostic it had (members are `Self.Name`).
        fn classMemberNamed(self: *Self, name: []const u8) bool {
            const class = self.method_class orelse return false;
            return self.workspace.findMethod(class, name) != null or catalogue.findField(class, name, self.definitions(), self.fields(), self.workspace.source) != null;
        }

        /// B4 (RFC-0092): whether an override's `result` narrows the `inherited` result: a class
        /// or interface below it, or anything that `any` holds (what `any(X)` converts).
        fn narrowerResult(self: *const Self, result: types.Type, inherited: types.Type) bool {
            if (result == inherited) return false;
            if (inherited == types.Type.any) return !catalogue.isScheduled(result, self.definitions()) and catalogue.refinementOf(result, self.definitions()) == null;
            const below = catalogue.definition(result, self.definitions()) orelse return false;
            const above = catalogue.definition(inherited, self.definitions()) orelse return false;
            if (below != .class or above != .class or catalogue.pendingClass(below.class)) return false;
            return catalogue.subtype(result, inherited, self.definitions());
        }

        /// B4 (RFC-0092): who may use method `slot` on a receiver of static type `class`: what the
        /// nearest declaration at or above `class` allows, which an override may have narrowed.
        fn memberAccess(self: *Self, class: types.Type, slot: u32) Narrowing {
            const w = self.workspace;
            const stated: Narrowing = .{ .access = w.slot_access[slot], .declaring = w.slots[slot].owner };
            if (w.narrowed_count == 0 or w.slot_kind[slot] != .method or w.slot_first[slot] == no_member or w.slot_narrowings[slot] == 0) return stated;
            return w.methods[w.declarationOf(class, slot)].narrowed orelse stated;
        }

        /// B4 (RFC-0092): `class` answers `slot` through `refined`, the slot its override with a
        /// narrower result introduced. The forwarder narrows the receiver to `class`, calls through
        /// the dispatch table, so an override further down still runs, and sees the result at the
        /// slot's type: every dispatch row keeps the exact signature of its slot.
        fn synthesizeRefinement(self: *Self, class: types.Type, name: Span, slot: u32, refined: u32) ParseError!void {
            const w = self.workspace;
            if (w.functions.count + w.generic_count == types.limits.functions) return w.fail(name, .function_limit);
            const function = self.beginSynthetic(slot);
            const span = w.slots[slot].name;
            const saved_class = self.method_class;
            self.function = function;
            self.method_class = null;
            errdefer {
                self.function = null;
                self.method_class = saved_class;
            }
            var arguments: [types.limits.parameters]u32 = undefined;
            const self_value = try self.emitTemplate(.{ .node = .{ .span = span, .value_type = function.parameters[0].value_type, .kind = .{ .integer = 0 } }, .input = .{ .parameter = 0 } });
            arguments[0] = try self.emit(.{ .span = span, .value_type = w.slots[refined].owner, .kind = .{ .downcast = self_value } });
            const lookup = try self.emit(.{ .span = span, .value_type = w.slots[refined].callable, .kind = .{ .method_value = .{ .receiver = arguments[0], .slot = refined } } });
            for (1..function.parameter_count) |position| {
                arguments[position] = try self.emitTemplate(.{ .node = .{ .span = span, .value_type = function.parameters[position].value_type, .kind = .{ .integer = 0 } }, .input = .{ .parameter = @intCast(position) } });
            }
            const range = try self.reserveArguments(arguments[0..function.parameter_count], span);
            const result = catalogue.definition(w.slots[refined].callable, self.definitions()).?.callable.result;
            const call = try self.checked(try self.emit(.{ .span = span, .value_type = result, .kind = .{ .invoke = .{ .callable = lookup, .arguments = range } } }));
            // `any(X)` where the slot holds `any`, the upcast to a class above otherwise.
            const root = if (function.value_type == types.Type.any) try self.emit(.{ .span = span, .value_type = types.Type.any, .kind = .{ .upcast = call } }) else try self.coerce(call, function.value_type);
            try self.finishSynthetic(class, .{ .kind = .identifier, .span = name }, slot, function, root, refined);
            self.method_class = saved_class;
            w.bridge_count += 1;
        }

        fn compileMethod(self: *Self, class: types.Type, index: usize, class_is_abstract: bool) ParseError!void {
            const w = self.workspace;
            // The defaults were compiled when the signature was declared.
            const signature = try self.parseMethodSignature(class, .skip);
            var function = signature.function;
            // An interface method may stop at its signature; with a body it is a default implementation.
            if (catalogue.definition(class, self.definitions()).?.class.is_interface and self.peek().kind != .equal) return;
            if (signature.is_abstract) {
                if (!class_is_abstract) return w.fail(function.name, .unsupported_specifier);
                if (self.peek().kind == .equal) return w.fail(self.peek().span, .unexpected_token);
                return;
            }
            // Every implementation of a slot has the slot's exact signature, so a method value is an
            // ordinary callable; an override reaches its own fields through a checked narrowing of `Self`.
            function.parameters[0].value_type = w.slots[w.methods[index].slot].owner;
            self.method_class = class;
            defer self.method_class = null;
            _ = try self.take(.equal, .expected_equal);
            if (w.functions.count + w.generic_count == types.limits.functions) return w.fail(function.name, .function_limit);
            self.function = function;
            self.member_expression = true;
            defer self.member_expression = false;
            const locals = try self.bindPatterns(function);
            const root = if (signature.discards) try self.discardedBody(function.name) else try self.coerce(try self.parseExpression(function.value_type), function.value_type);
            w.local_count = locals;
            function.root = root;
            function.end = w.functions.node_count;
            function.work = self.body(function.start, root).work;
            std.debug.assert(function.root >= function.start and function.root < function.end);
            try self.checkPredicting(function);
            // A method is reached through the dispatch table, so even a body that only names a
            // parameter is published as a runtime function.
            function.runtime = w.runtime_functions.publishAlias(function, &w.functions, self.definitions(), w.bindings[0..w.binding_count], w.binding_cells[0..w.binding_count], w.node_count) catch |err| return w.fail(function.name, switch (err) {
                error.FunctionLimit => .function_limit,
                error.NodeLimit => .template_limit,
                error.MemberLimit => .aggregate_limit,
                error.ArgumentLimit => .call_argument_limit,
                error.GlobalLimit => .binding_limit,
            });
            if (function.runtime == null) return w.fail(function.name, .unimplemented_method);
            w.methods[index].function = w.functions.count;
            w.functions.publishIn(function, w.source, w.scope());
            self.function = null;
            w.methods[index].runtime = function.runtime;
        }

        /// `Receiver.Method(arguments)`: the method the receiver's own class resolves the slot to, called
        /// with the receiver first. The call operator is opened here and finishes like any other call.
        fn startMethodCall(self: *Self, receiver: u32, slot: u32, name: Token, fixed: ?usize) ParseError!bool {
            const w = self.workspace;
            const callable = w.slots[slot].callable;
            const shape = catalogue.definition(callable, self.definitions()).?.callable;
            const open = self.peek();
            if (open.kind != .left_paren and open.kind != .left_bracket) {
                // A method named without a call is a function value that remembers its receiver:
                // the method the receiver's class resolves to, with the receiver bound as `Self`.
                if (fixed != null) return w.fail(name.span, .expected_call);
                const parameters = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
                var bound = [1]u32{try self.coerce(receiver, w.slots[slot].owner)};
                const lookup = try self.emit(.{ .span = name.span, .value_type = callable, .kind = .{ .method_value = .{ .receiver = bound[0], .slot = slot } } });
                const residual = w.catalogue.internTuple(w.catalogue.tuple_elements[parameters.start + 1 .. parameters.end]) catch |err| return w.fail(name.span, if (err == error.TypeLimit) .type_limit else .tuple_limit);
                const value_type = w.catalogue.internCallable(.{ .parameters = residual, .result = shape.result, .transacts = shape.transacts, .decides = shape.decides, .detail = shape.detail }) catch |err| return w.fail(name.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                const range = try self.reserveArguments(&bound, name.span);
                w.operands[self.operand_count - 1] = try self.emit(.{ .span = name.span, .value_type = value_type, .kind = .{ .bind = .{ .callable = lookup, .arguments = range } } });
                return false;
            }
            if ((open.kind == .left_bracket) != shape.decides) return w.fail(open.span, .expected_call);
            self.cursor += 1;
            try self.callEffect(open.span, shape.effects());
            if (shape.decides and !self.failureContext()) return w.fail(open.span, .failure_context_required);
            var as_owner: u32 = undefined;
            var method: u32 = undefined;
            if (fixed) |index| {
                // `Super.Method(...)` runs the superclass's own implementation whatever the receiver is.
                const info = w.methods[index];
                // A forwarder has no declaration to run in its place.
                if (info.synthetic) return w.fail(name.span, .unimplemented_method);
                const implementing = w.functions.definitions[info.function];
                // The body is named directly, not through the table, and a method body is not
                // exported from its module.
                if (!w.reaches(implementing.name)) return w.fail(name.span, .private_name);
                as_owner = try self.coerce(receiver, implementing.parameters[0].value_type);
                method = try self.emit(.{ .span = name.span, .value_type = try self.functionType(implementing, name.span), .kind = .{ .function_value = info.runtime.? } });
            } else {
                as_owner = try self.coerce(receiver, w.slots[slot].owner);
                method = try self.emit(.{ .span = name.span, .value_type = callable, .kind = .{ .method_value = .{ .receiver = as_owner, .slot = slot } } });
            }
            self.operand_count -= 1;
            // The receiver's static type decides which declaration names the parameters and
            // gives their defaults; it is looked up only by a call that uses either.
            try self.pushOperator(.{ .kind = .invoke, .span = open.span, .function = method, .operand_base = self.operand_count, .selected = if (shape.decides) 1 else no_member, .arguments = 1, .receiver = true, .method = slot, .value_type = self.node(receiver).value_type });
            try self.pushOperand(as_owner);
            return true;
        }

        fn parseEnum(self: *Self, name: Token, is_public: bool) ParseError!void {
            const w = self.workspace;
            std.debug.assert(self.function == null and self.operator_count == self.operator_base);
            // `enum<closed>` is the default; `enum<open>` (RFC-0083) may gain cases, so no
            // `Case(...)` over it is exhaustive.
            var is_open = false;
            var openness_stated = false;
            // RFC-0087, P5.2: `<persistable>` beside it, in any order, each at most once.
            var is_persistable = false;
            while (self.peek().kind == .less) {
                _ = try self.take(.less, .unsupported_specifier);
                const word = try self.take(.identifier, .unsupported_specifier);
                const text = word.span.text(w.source);
                if (!openness_stated and (std.mem.eql(u8, text, "open") or std.mem.eql(u8, text, "closed"))) {
                    openness_stated = true;
                    is_open = std.mem.eql(u8, text, "open");
                } else if (!is_persistable and std.mem.eql(u8, text, "persistable")) is_persistable = true else return w.fail(word.span, .unsupported_specifier);
                _ = try self.take(.greater, .unsupported_specifier);
            }
            _ = try self.take(.left_brace, .unexpected_token);
            self.skipNewlines();
            var count: u32 = 0;
            // Parse into the unpublished catalogue tail. No count advances until
            // addEnum admits every name; failures leave the published prefix intact.
            const start = w.catalogue.case_count;
            const cases = w.catalogue.cases[start..@min(start + types.limits.enum_cases, w.catalogue.cases.len)];
            while (self.peek().kind != .right_brace) {
                var token = try self.take(.identifier, .expected_case);
                if (w.localQualified(token.span.start)) return w.fail(token.span, .invalid_qualifier);
                // RFC-0085, I10: `(e:)Name`, now `e.Name`, declares `Name` in the body of `e`.
                if (w.qualifierFor(token.span.start) != null) {
                    if (!std.mem.eql(u8, token.span.text(w.source), name.span.text(w.source))) return w.fail(token.span, .invalid_qualifier);
                    _ = try self.take(.dot, .expected_case);
                    token = try self.take(.identifier, .expected_case);
                }
                if (count == cases.len) return w.fail(token.span, .case_limit);
                std.debug.assert(start + count < w.catalogue.cases.len);
                cases[count] = token.span;
                w.noteDeclaration(token.span, .member, name.span.start);
                count += 1;
                if (self.peek().kind == .right_brace) break;
                if (self.peek().kind != .comma and self.peek().kind != .newline) return w.fail(self.peek().span, .unexpected_token);
                self.cursor += 1;
                self.skipNewlines();
            }
            _ = try self.take(.right_brace, .unexpected_token);
            const declared = w.catalogue.addEnumIn(name.span, cases[0..count], is_public, w.source, w.scope()) catch |err| {
                // Catalogue admission hashes case names once. Only malformed source
                // needs a second bounded scan to retain the duplicate's exact span.
                if (err == error.DuplicateName) {
                    for (cases[0..count], 0..) |span, index| {
                        for (cases[0..index]) |earlier| {
                            if (std.mem.eql(u8, earlier.text(w.source), span.text(w.source))) return w.fail(span, .duplicate_case);
                        }
                    }
                }
                return w.fail(name.span, switch (err) {
                    error.TypeLimit => .type_limit,
                    error.CaseLimit => .case_limit,
                    error.DuplicateName => .duplicate_name,
                    error.InvalidName => .expected_case,
                });
            };
            w.catalogue.definitions[classIndex(declared)].enumeration.is_open = is_open;
            w.catalogue.definitions[classIndex(declared)].enumeration.persistable = is_persistable;
            if (self.peek().kind != .eof and self.peek().kind != .newline and self.peek().kind != .separator) return w.fail(self.peek().span, .unexpected_token);
            std.debug.assert(w.findType(name.span.text(w.source)) != null);
            std.debug.assert(count <= types.limits.enum_cases and self.operator_count == self.operator_base);
        }

        fn parseRecord(self: *Self, name: Token, is_public: bool) ParseError!void {
            _ = try self.parseRecordAs(name, is_public, null);
        }

        /// Parses a struct from the token after its keyword. With `arguments` it is the
        /// instantiation of a parametric struct for them (RFC-0073), named like its template.
        fn parseRecordAs(self: *Self, name: Token, is_public: bool, arguments: ?types.Type) ParseError!types.Type {
            const w = self.workspace;
            // `struct<persistable>` (RFC-0087, P5.2), the one specifier a struct takes, once.
            var is_persistable = false;
            // B4 (RFC-0092): `struct<computes>`, `struct<reads>`...: what building one needs.
            var effect_words: u16 = 0;
            while (self.peek().kind == .less) {
                _ = try self.take(.less, .unsupported_specifier);
                const word = try self.take(.identifier, .unsupported_specifier);
                if (std.meta.stringToEnum(EffectWord, word.span.text(w.source))) |effect_word| if (effect_word != .predicts) {
                    // A type is not declared in a failure context or in one that can wait (13:746).
                    if (effect_word == .decides or effect_word == .suspends or effect_word == .converges) return w.fail(word.span, .class_effect_specifier);
                    try self.addEffectWord(&effect_words, word, effect_word);
                    _ = try self.take(.greater, .unsupported_specifier);
                    continue;
                };
                if (is_persistable or !std.mem.eql(u8, word.span.text(w.source), "persistable")) return w.fail(word.span, .unsupported_specifier);
                is_persistable = true;
                _ = try self.take(.greater, .unsupported_specifier);
            }
            _ = try self.take(.left_brace, .unexpected_token);
            // While its fields are staged, a class instantiation it names is only reserved.
            w.declaring += 1;
            self.skipNewlines();
            var count: u32 = 0;
            while (self.peek().kind != .right_brace) {
                const field = try self.take(.identifier, .expected_field);
                // A `var` field is never persistable (17:126); in another struct it is what it was.
                if (is_persistable and std.mem.eql(u8, field.span.text(w.source), "var") and self.peek().kind == .identifier) return w.fail(self.peek().span, .persistable_field);
                if (w.localQualified(field.span.start)) return w.fail(field.span, .invalid_qualifier);
                if (count == w.record_fields.len) return w.fail(field.span, .field_limit);
                if (w.catalogue.field_count + count == w.field_defaults.len) return w.fail(field.span, .field_limit);
                for (w.record_fields[0..count]) |earlier| {
                    if (std.mem.eql(u8, earlier.name.text(w.source), field.span.text(w.source))) return w.fail(field.span, .duplicate_field);
                }
                // The type or the default may instantiate a type, which moves the staged fields.
                w.noteDeclaration(field.span, .member, name.span.start);
                const value_type = try self.parseType();
                w.record_fields[count] = .{ .name = field.span, .value_type = value_type };
                w.staged_fields = count + 1;
                const default: functions.Body = if (self.peek().kind == .equal) try self.parseDefault(field, value_type) else .{};
                const field_index = w.catalogue.field_count + count;
                if (field_index >= w.field_defaults.len) return w.fail(field.span, .field_limit);
                w.field_defaults[field_index] = default;
                count += 1;
                w.staged_fields = count;
                if (self.peek().kind == .right_brace) break;
                if (self.peek().kind != .comma and self.peek().kind != .newline) return w.fail(self.peek().span, .unexpected_token);
                self.cursor += 1;
                self.skipNewlines();
            }
            _ = try self.take(.right_brace, .unexpected_token);
            w.staged_fields = 0;
            w.declaring -= 1;
            const record = (if (arguments) |key| w.catalogue.addRecordInstance(name.span, key, w.record_fields[0..count], is_public, w.source, w.scope()) else w.catalogue.addRecordIn(name.span, w.record_fields[0..count], is_public, w.source, w.scope())) catch |err| return w.fail(name.span, switch (err) {
                error.TypeLimit => .type_limit,
                error.FieldLimit => .field_limit,
                error.DuplicateName => .duplicate_name,
                else => .unsupported_type,
            });
            if (is_persistable) w.catalogue.definitions[classIndex(record)].record.persistable = true;
            w.class_effects[classIndex(record)] = if (effect_words != 0) .{ .stated = true, .effect = effectOfWords(effect_words) orelse return w.fail(name.span, .expected_computes) } else .{};
            if (self.peek().kind != .eof and self.peek().kind != .newline and self.peek().kind != .separator) return w.fail(self.peek().span, .unexpected_token);
            if (arguments) |key| {
                if (w.instance_count == w.instances.len) return w.fail(name.span, .type_limit);
                const index = w.addInstance(self.generic.?.template, key, record, w.completing[w.instantiation_depth - 1], &.{});
                w.instances[index].state = .complete;
            } else {
                std.debug.assert(w.findType(name.span.text(w.source)) != null);
                try self.settle(name.span);
            }
            std.debug.assert(count <= types.limits.record_fields);
            return record;
        }

        fn body(self: *const Self, start: u32, root: u32) functions.Body {
            const storage = &self.workspace.functions;
            std.debug.assert(start <= root and root < storage.node_count);
            var work = storage.node_count - start;
            for (storage.nodes[start..storage.node_count]) |template| {
                if (template.input == .operation and template.node.kind == .aggregate) work += template.node.kind.aggregate.end - template.node.kind.aggregate.start;
            }
            std.debug.assert(work >= storage.node_count - start);
            return .{ .start = @intCast(start), .end = @intCast(storage.node_count), .root = @intCast(root), .work = @intCast(work) };
        }

        fn parseDefault(self: *Self, field: Token, value_type: types.Type) ParseError!functions.Body {
            return self.parseDefaultOf(field, value_type, null);
        }

        /// The heap effects written after the parameter list the cursor is in. Read ahead for the
        /// defaults of a method's parameters, which are compiled before the signature ends; the
        /// signature itself is diagnosed where it is parsed.
        fn effectAhead(self: *const Self) Effect {
            const w = self.workspace;
            var at = self.cursor;
            var depth: u32 = 0;
            while (at < w.token_count) : (at += 1) switch (w.tokens[at].kind) {
                .eof => return .{},
                .left_paren, .left_bracket, .left_brace => depth += 1,
                .right_bracket, .right_brace => depth -|= 1,
                .right_paren => {
                    if (depth == 0) break;
                    depth -= 1;
                },
                else => {},
            };
            at += 1;
            var seen: u16 = 0;
            while (at + 2 < w.token_count and w.tokens[at].kind == .less and w.tokens[at + 1].kind == .identifier and w.tokens[at + 2].kind == .greater) : (at += 3) {
                const text = w.tokens[at + 1].span.text(w.source);
                if (self.genericEffect(text)) |bound| return bound.heapOnly();
                if (std.meta.stringToEnum(EffectWord, text)) |word| seen |= word.bit();
            }
            // Words that contradict each other are refused by the parse; until then they give nothing.
            const exclusive = EffectWord.computes.bit() | EffectWord.transacts.bit();
            const additive = EffectWord.reads.bit() | EffectWord.writes.bit() | EffectWord.allocates.bit();
            if (seen & exclusive == exclusive or (seen & exclusive != 0 and seen & additive != 0)) return .{};
            const timed = EffectWord.decides.bit() | EffectWord.suspends.bit();
            if (seen & timed == timed) return .{};
            return (effectOfWords(seen) orelse Effect{}).heapOnly();
        }

        /// The default of a field, or of a parameter of `owner`. A parameter's default may read
        /// the parameters before it, and `Self` in a method (RFC-0076): its template takes them
        /// as its parameters, and a call hands it the arguments it has settled by then.
        fn parseDefaultOf(self: *Self, field: Token, value_type: types.Type, owner: ?*const functions.Definition) ParseError!functions.Body {
            const w = self.workspace;
            std.debug.assert(self.function == null and !self.default_expression);
            _ = try self.take(.equal, .expected_equal);
            const start = w.functions.node_count;
            const members = w.functions.member_count;
            const arguments = w.functions.argument_count;
            // The field name is diagnostic metadata, never a recursion/shadowing key.
            self.function = .{ .name = field.span, .value_type = value_type, .is_public = false, .start = start, .end = 0, .root = 0 };
            if (owner) |function| {
                self.function.?.parameters = function.parameters;
                self.function.?.parameter_count = function.parameter_count;
                self.function.?.is_method = function.is_method;
                // Reading a field of `Self` reads the instance, which the method must declare.
                if (function.is_method) {
                    const ahead = self.effectAhead();
                    self.function.?.transacts = ahead.transacts;
                    self.function.?.detail = ahead.detail;
                }
            }
            self.default_expression = true;
            defer {
                self.function = null;
                self.default_expression = false;
            }
            const root = try self.coerce(try self.parseExpression(value_type), value_type);
            const result = self.body(start, root);
            std.debug.assert(w.functions.nodes[result.root].node.value_type == value_type);
            std.debug.assert(result.start < result.end and self.operator_count == self.operator_base);
            // Inside an instantiation the storage below is not this type's to keep (RFC-0073).
            if (w.instantiation_depth != 0) return self.relocateDefault(result, members, arguments, field.span);
            return result;
        }

        fn definitions(self: *const Self) []const types.Definition {
            return self.workspace.catalogue.definitions[0..self.workspace.catalogue.count];
        }

        fn fields(self: *const Self) []const types.Field {
            return self.workspace.catalogue.fields[0..self.workspace.catalogue.field_count];
        }

        /// Whether values of this type have an equality: `==`, `!=` and map keys require it.
        fn comparable(self: *const Self, value_type: types.Type) bool {
            return self.workspace.catalogue.comparableType(value_type);
        }

        fn expectedContext(self: *const Self) ?types.Type {
            var index = self.operator_count;
            while (index > self.operator_base) {
                index -= 1;
                const operator = self.workspace.operators[index];
                switch (operator.kind) {
                    .anonymous_capture => return operator.value_type,
                    .call => {
                        // An argument of an inferred call is typed on its own (RFC-0091).
                        if (operator.infer) return null;
                        const function = self.callTarget(operator);
                        if (function.overloaded) return self.workspace.overloadContext(operator.function, operator.arguments);
                        const slot = if (operator.head != no_member) operator.head else if (operator.tail != no_member) function.parameter_count else operator.arguments;
                        return if (slot < function.parameter_count) function.parameters[slot].value_type else null;
                    },
                    .invoke => {
                        const shape = catalogue.definition(self.node(operator.function).value_type, self.definitions()).?.callable;
                        // A named argument of a method call has the type of the parameter it names.
                        return catalogue.tupleElementAt(shape.parameters, if (operator.head != no_member) operator.head else operator.arguments, self.definitions(), self.workspace.catalogue.tuple_elements[0..self.workspace.catalogue.tuple_count]);
                    },
                    .index => {
                        // RFC-0087, P5.4: the key of a keyed cell.
                        if (operator.head == keyed_cell_head) return catalogue.entryShape(self.workspace.source_cells[operator.method].value_type, self.definitions()).?.key;
                        // A position in a string, like one in an array, is an integer.
                        const base = catalogue.entryShape(self.node(operator.function).value_type, self.definitions()) orelse return .i64;
                        return base.key;
                    },
                    .text_method => return if (self.reissuing(operator)) operator.value_type else if (operator.head >= stdlib.first_head) self.stdContext(operator) else .i64,
                    .element_at => return if (operator.arguments == 1) .i64 else null,
                    .with_index => {
                        // RFC-0087, P5.4: the key, then the value, of a keyed cell.
                        if (operator.head == keyed_cell_head) {
                            const entries = catalogue.entryShape(self.workspace.source_cells[operator.method].value_type, self.definitions()).?;
                            return if (operator.arguments == 0) entries.key else entries.value;
                        }
                        if (operator.arguments == 0) return null;
                        const base = self.node(self.workspace.operands[operator.operand_base]).value_type;
                        const shape = catalogue.definition(base, self.definitions()) orelse return null;
                        // RFC-0087: a `weak_map` is updated one key at a time as a map is.
                        const entries = catalogue.entryShape(base, self.definitions());
                        if (operator.arguments == 1) return if (entries) |map| map.key else .i64;
                        return if (shape == .array) shape.array else if (entries) |map| map.value else null;
                    },
                    .with_field => {
                        if (operator.arguments == 0) return null;
                        if (operator.head == accessor_field_head) return self.workspace.accessor_fields[operator.method].value_type;
                        if (operator.method != no_member) return self.workspace.slot_field[operator.method].value_type;
                        const base = self.node(self.workspace.operands[operator.operand_base]).value_type;
                        return catalogue.memberAt(base, operator.function, self.definitions(), self.fields()).?.value_type;
                    },
                    .native_call => {
                        const binding = self.workspace.native_bindings[operator.function];
                        return if (operator.arguments < binding.param_count) binding.params[operator.arguments] else null;
                    },
                    .convert => return if (operator.function == @backingInt(Conversion.float) or (operator.function >= @backingInt(Conversion.quotient) and operator.function <= @backingInt(Conversion.to_rational))) .i64 else if (operator.selected != 1 and operator.function <= @backingInt(Conversion.ceil)) null else if (operator.function == @backingInt(Conversion.string) or operator.function == @backingInt(Conversion.interpolation) or operator.function >= @backingInt(Conversion.cast)) null else .float,
                    .recur => {
                        // RFC-0085, I4: a call of a nested function, by its declared parameters.
                        if (operator.method != no_member) return self.nestedContext(operator);
                        const f = self.function.?;
                        // A nested function calling itself passes its captures first (I3).
                        const skip: u32 = if (self.ownNested() != no_member) self.workspace.anonymous_frames[self.workspace.anonymous_count - 1].capture_count else 0;
                        return if (skip + operator.arguments < f.parameter_count) f.parameters[skip + operator.arguments].value_type else null;
                    },
                    .iterate => return if (operator.arguments == 0) .i64 else operator.value_type,
                    .iterate_value => return if (operator.arguments == 0) null else if (operator.arguments == 1) .i64 else operator.value_type,
                    .loop => return if (operator.arguments == 0) null else operator.value_type,
                    .bind => {
                        if (operator.arguments == 0) return null;
                        const callee = self.node(self.workspace.operands[operator.operand_base]);
                        const shape = catalogue.definition(callee.value_type, self.definitions()).?.callable;
                        return catalogue.tupleElementAt(shape.parameters, operator.arguments - 1, self.definitions(), self.workspace.catalogue.tuple_elements[0..self.workspace.catalogue.tuple_count]);
                    },
                    .conditional => return if (operator.arguments == 0) .logic else operator.value_type,
                    .block => return if (operator.head == no_member) operator.value_type else if (operator.arguments == 2) self.node(self.workspace.locals[operator.selected].node).value_type else if (operator.arguments == 3) self.workspace.source_cells[operator.selected].value_type else if (operator.arguments == 6) self.cellValue(operator.selected) else if (operator.selected == no_member) null else @fromBackingInt(@as(u16, @intCast(operator.selected))),
                    .attempt, .set_value, .set_local_value => return operator.value_type,
                    .demand => return .logic,
                    .fail, .err => return .string,
                    // What a `Return` hands on is the function's result; what an arm's exit
                    // hands on, its pending exit (P3.6).
                    .exit => return if (operator.head != no_member) @as(types.Type, @fromBackingInt(@as(u16, @intCast(operator.head)))) else self.function.?.value_type,
                    .record => return if (operator.selected == accessor_selected) self.workspace.accessor_fields[operator.accessor].value_type else if (operator.selected != no_member) catalogue.memberAt(operator.value_type.?, operator.selected, self.definitions(), self.fields()).?.value_type else null,
                    .array => return if (operator.value_type) |value_type| catalogue.definition(value_type, self.definitions()).?.array else null,
                    .tuple => return if (operator.value_type) |value_type| catalogue.tupleElementAt(value_type, operator.arguments, self.definitions(), self.workspace.catalogue.tuple_elements[0..self.workspace.catalogue.tuple_count]) else null,
                    .option => return if (operator.value_type) |value_type| catalogue.definition(value_type, self.definitions()).?.option else null,
                    .map => return if (operator.value_type) |value_type| map_type: {
                        const shape = catalogue.entryShape(value_type, self.definitions()).?;
                        break :map_type if (operator.arguments % 2 == 0) shape.key else shape.value;
                    } else null,
                    .lookup, .option_or => {
                        if (operator.arguments != 1) return null;
                        const first = self.node(self.workspace.operands[operator.operand_base]);
                        const item = catalogue.definition(first.value_type, self.definitions()) orelse return null;
                        if (operator.kind == .lookup) return if (catalogue.entryShape(first.value_type, self.definitions())) |map| map.key else null;
                        return if (operator.kind == .option_or and item == .option) item.option else null;
                    },
                    else => {},
                }
            }
            return self.expected_type;
        }

        fn aggregateDelimiter(self: *const Self) bool {
            var index = self.operator_count;
            while (index > self.operator_base) {
                index -= 1;
                const kind = self.workspace.operators[index].kind;
                if (kind == .record or kind == .array or kind == .tuple or kind == .option or kind == .map) return true;
                if (kind == .anonymous_capture or kind == .open or kind == .block or kind == .call or kind == .invoke or kind == .recur or kind == .iterate or kind == .iterate_value or kind == .loop or kind == .bind or kind == .lookup or kind == .option_or or kind == .index or kind == .convert or kind == .native_call or kind == .with_field or kind == .with_index or kind == .element_at or kind == .exhaustive or kind == .text_method or kind == .conditional or kind == .attempt or kind == .demand or kind == .fail or kind == .exit or kind == .err or kind == .set_value or kind == .set_local_value) return false;
            }
            return false;
        }

        fn startAggregate(self: *Self, resolved: Name) ParseError!void {
            const token = resolved.token;
            const w = self.workspace;
            const name = token.span.text(w.source);
            var operator: Operator = .{ .kind = .record, .span = resolved.span, .operand_base = self.operand_count };
            if (!resolved.qualified and (std.mem.eql(u8, name, "array") or compoundName(name))) {
                w.noteName(token.span, qualify.none, .builtin, qualify.none);
                operator.kind = if (std.mem.eql(u8, name, "array")) .array else if (std.mem.eql(u8, name, "tuple")) .tuple else if (std.mem.eql(u8, name, "option")) .option else .map;
                if (self.expectedContext()) |value_type| {
                    if (catalogue.definition(value_type, self.definitions())) |definition| {
                        if ((operator.kind == .array and definition == .array) or (operator.kind == .tuple and definition == .tuple) or (operator.kind == .option and definition == .option) or (operator.kind == .map and definition == .map)) operator.value_type = value_type;
                        // RFC-0087, W3: a map literal where a `weak_map` is expected is built at
                        // the `weak_map` type, as an empty one is.
                        if (operator.kind == .map and definition == .weak_map) operator.value_type = value_type;
                    }
                }
            } else {
                const alias = if (!resolved.qualified) self.genericType(name) else null;
                // RFC-0085, I8: only an access makes an `accessor`, whatever names its type.
                if (alias == null and !resolved.qualified and std.mem.eql(u8, name, "accessor") and w.catalogue.findNamedIn(name, w.source, resolved.scope) == null and !self.stdDeclared(@backingInt(stdlib.Form.accessor_type), name, null)) return w.fail(resolved.span, .accessor_construction);
                const value_type = alias orelse w.catalogue.findNamedIn(name, w.source, resolved.scope) orelse return w.fail(resolved.span, .unknown_name);
                if (w.standardAccessor()) |standard| if (value_type == standard) return w.fail(resolved.span, .accessor_construction);
                const item = catalogue.definition(value_type, self.definitions()) orelse return w.fail(resolved.span, .unknown_name);
                if (alias == null) {
                    if ((item != .record and item != .class) or !self.visible(catalogue.declaredName(item).?)) return w.fail(resolved.span, .unknown_name);
                    if (resolved.sealed() and !catalogue.declaredPublic(item)) return w.fail(resolved.span, .private_name);
                    // A class is built only after its own declaration has given it fields.
                    if (item == .class and catalogue.pendingClass(item.class)) return w.fail(resolved.span, .unknown_name);
                    if (item == .class and item.class.is_abstract and !self.constructs(value_type)) return w.fail(resolved.span, .abstract_instance);
                    // Its own block clauses are not all known yet, and would run for ever anyway.
                    if (item == .class and self.blocksUnknown(value_type)) return w.fail(resolved.span, .construction_cycle);
                    self.noteType(token.span, value_type);
                } else operator.kind = switch (item) {
                    // What a type parameter stands for is built under the rules of the type itself.
                    .class => |class| if (catalogue.pendingClass(class)) return w.fail(resolved.span, .unknown_name) else if (class.is_abstract) return w.fail(resolved.span, .abstract_instance) else if (self.blocksUnknown(value_type)) return w.fail(resolved.span, .construction_cycle) else .record,
                    .record => .record,
                    .array => .array,
                    .tuple => .tuple,
                    .option => .option,
                    .map => .map,
                    // RFC-0087, W3: a map literal built at the `weak_map` type it stands for.
                    .weak_map => .map,
                    else => return w.fail(resolved.span, .not_callable),
                };
                operator.value_type = value_type;
            }
            _ = try self.take(.left_brace, .unexpected_token);
            if (operator.kind == .option) if (w.optionKey(token.span)) |key| {
                const context = self.optionContext();
                // In a failure context older than RFC-0072 the constructor means what it meant.
                // Outside every context it catches once a compile has shown that it must
                // (`wantOption`), so that one that cannot fail keeps its IR. In a context of
                // that RFC nothing compiled before, and it catches as the Book says; whether
                // its expression can fail is not known yet, so it always gets its region.
                // RFC-0076: inside an older failure context it catches as well, by the same two
                // compiles, so one expression has one meaning wherever it stands.
                if (context == .caught or w.optionCaught(key)) {
                    try self.startAttempt(resolved.span);
                    w.operators[self.operator_count - 1].names = caught_option;
                    operator.operand_base = self.operand_count;
                    operator.names = caught_option;
                } else if (w.option_open_count < w.option_open.len) {
                    w.option_open[w.option_open_count] = .{ .key = key, .start = token.span.start, .frame = w.anonymous_count };
                    w.option_open_count += 1;
                    operator.names = open_option;
                }
            };
            try self.pushOperator(operator);
            try self.selectField();
        }

        fn selectField(self: *Self) ParseError!void {
            const w = self.workspace;
            std.debug.assert(self.operator_count > self.operator_base);
            const operator = &w.operators[self.operator_count - 1];
            std.debug.assert(operator.kind == .record or operator.kind == .array or operator.kind == .tuple or operator.kind == .option or operator.kind == .map);
            self.skipNewlines();
            if (operator.kind != .record or self.peek().kind == .right_brace) return;
            if (self.delegationAhead() and catalogue.definition(operator.value_type.?, self.definitions()).? == .class) {
                // `Name<constructor>(...)` instead of `Field := value`: the name is read as an operand.
                operator.delegation = true;
                return;
            }
            const token = try self.take(.identifier, .expected_field);
            // Nor is a field (RFC-0083).
            if (w.localQualified(token.span.start)) return w.fail(token.span, .invalid_qualifier);
            // RFC-0085, I8: a field with accessors has no cell to initialise. One without a
            // default (I9) is given here, and its setter receives the value.
            const field = catalogue.findField(operator.value_type.?, token.span.text(w.source), self.definitions(), self.fields(), w.source) orelse {
                const index = self.findAccessor(operator.value_type.?, token.span.text(w.source)) orelse return w.fail(token.span, .unknown_field);
                if (!w.accessor_fields[index].required) return w.fail(token.span, .accessor_archetype);
                // RFC-0085, I11: the archetype names the field with accessors.
                w.noteName(token.span, w.accessor_fields[index].name.start, .member, qualify.none);
                return self.selectAccessor(operator, index, token);
            };
            self.noteField(token.span, operator.value_type.?, field);
            if (catalogue.definition(operator.value_type.?, self.definitions()).? == .class) {
                // A hidden raw field (RFC-0084, P4.3) is no member.
                if (self.liveTypeOfField(operator.value_type.?, field)) |entry| if (entry.hidden and entry.raw == field) return w.fail(token.span, .unknown_field);
                try self.checkFieldAccess(operator.value_type.?, field, token.span, false);
                // A live field's guard gives it its value (RFC-0084, P4.2).
                if (w.field_live[catalogue.definition(operator.value_type.?, self.definitions()).?.class.fields.start + field]) return w.fail(token.span, .live_assigned);
                if (w.field_final[catalogue.definition(operator.value_type.?, self.definitions()).?.class.fields.start + field]) return w.fail(token.span, .final_field);
            }
            var member = operator.head;
            while (member != no_member) {
                std.debug.assert(member < w.staging_count);
                if (w.staging[member].field == field) return w.fail(token.span, .duplicate_field);
                member = if (w.staging[member].next == no_member) no_member else w.staging[member].next;
            }
            _ = try self.take(.colon, .expected_field);
            _ = try self.take(.equal, .expected_equal);
            operator.selected = field;
        }

        /// RFC-0085, I9: `F := V` in an archetype, `F` the field with accessors `index`, which
        /// has no default. Who may give it is who may give a field (`checkFieldAccess`): the
        /// field's read access. Its value is staged by `finishMember`.
        fn selectAccessor(self: *Self, operator: *Operator, index: u32, token: Token) ParseError!void {
            const w = self.workspace;
            const entry = w.accessor_fields[index];
            std.debug.assert(entry.required and entry.setter != no_member);
            try self.checkAccess(entry.read, entry.owner, token.span);
            numberArchetype(w, operator);
            if (w.accessor_given[index].archetype == operator.accessors) return w.fail(token.span, .duplicate_field);
            _ = try self.take(.colon, .expected_field);
            _ = try self.take(.equal, .expected_equal);
            operator.selected = accessor_selected;
            operator.accessor = index;
        }

        /// Gives the archetype `operator` its number in `accessor_given`, once.
        fn numberArchetype(w: *Workspace, operator: *Operator) void {
            if (operator.accessors != 0) return;
            w.accessor_archetypes += 1;
            operator.accessors = w.accessor_archetypes;
        }

        /// Records that the archetype `operator` gives the field with accessors `index` the
        /// value `value`: in its chain, and as a mark under its number.
        fn stageAccessor(w: *Workspace, operator: *Operator, index: u32, value: u32, span: Span) ParseError!void {
            std.debug.assert(operator.accessors != 0);
            if (w.staging_count == w.staging.len) return w.fail(span, .aggregate_limit);
            const staged = w.staging_count;
            w.staging[staged] = .{ .node = value, .field = index };
            if (operator.accessor_tail != no_member) w.staging[operator.accessor_tail].next = @intCast(staged) else operator.accessor_head = staged;
            operator.accessor_tail = staged;
            w.staging_count += 1;
            w.accessor_given[index] = .{ .archetype = operator.accessors, .node = value };
        }

        /// RFC-0085, I9: the fields with accessors and no default that `class` has (its own and
        /// those of every supertype), in declaration order, into `accessor_order`; returns how
        /// many. Each type `class` reaches is one probe of `accessor_owners`, so a class costs
        /// its supertypes and its own such fields, not every field of the program.
        fn requiredAccessors(self: *Self, class: types.Type) u32 {
            const w = self.workspace;
            if (w.accessor_required == 0) return 0;
            const above = catalogue.Supertypes.of(class, self.definitions()).?;
            var count: u32 = 0;
            var reached = above.reached.iterator(.{});
            while (reached.next()) |position| {
                const owner: types.Type = @fromBackingInt(@intCast(position + catalogue.builtin_count));
                var owned = w.accessor_owners.walk(&w.accessor_owner_slots, accessorKey(@backingInt(owner)));
                while (owned.next()) |index| {
                    const entry = w.accessor_fields[index];
                    if (entry.owner != owner or !entry.required) continue;
                    std.debug.assert(count < w.accessor_order.len);
                    w.accessor_order[count] = index;
                    count += 1;
                }
            }
            std.mem.sort(u32, w.accessor_order[0..count], {}, std.sort.asc(u32));
            return count;
        }

        fn finishMember(self: *Self, token: Token) ParseError!void {
            const w = self.workspace;
            const operator = try self.reduceToDelimiter(token);
            if (token.kind == .arrow and operator.kind != .map) return w.fail(token.span, .unexpected_token);
            if (operator.kind != .record and operator.kind != .array and operator.kind != .tuple and operator.kind != .option and operator.kind != .map) return w.fail(token.span, .unexpected_token);
            if (operator.delegation) {
                // The entry before this delimiter was a delegation, whose values are staged already.
                std.debug.assert(operator.kind == .record and operator.selected == no_member and self.operand_count == operator.operand_base);
                operator.delegation = false;
                return;
            }
            std.debug.assert(self.operand_count == operator.operand_base + 1);
            var member = w.operands[self.operand_count - 1];
            var value_type = self.node(member).value_type;
            if (operator.selected == accessor_selected) {
                // RFC-0085, I9: a value for a field with accessors and no default, kept apart;
                // the cells' values and the record's arguments are those of its other fields.
                std.debug.assert(operator.kind == .record and operator.accessor < w.accessor_count and operator.accessors != 0);
                member = try self.coerce(member, w.accessor_fields[operator.accessor].value_type);
                try stageAccessor(w, operator, operator.accessor, member, token.span);
                operator.selected = no_member;
                operator.accessor = no_member;
                self.operand_count = operator.operand_base;
                return;
            }
            if (operator.kind == .record) {
                std.debug.assert(operator.selected != no_member);
                const field_type = catalogue.memberAt(operator.value_type.?, operator.selected, self.definitions(), self.fields()).?.value_type;
                member = try self.coerce(member, field_type);
                value_type = field_type;
            } else if (operator.kind == .tuple) {
                if (operator.arguments == types.limits.tuple_arity) return w.fail(token.span, .tuple_limit);
                if (operator.value_type) |tuple_type| {
                    const element = catalogue.tupleElementAt(tuple_type, operator.arguments, self.definitions(), w.catalogue.tuple_elements[0..w.catalogue.tuple_count]) orelse return w.fail(self.node(member).span, .tuple_arity);
                    member = try self.coerce(member, element);
                    value_type = element;
                }
            } else if (operator.kind == .option) {
                if (operator.arguments != 0) return w.fail(token.span, .option_arity);
                if (operator.value_type) |option_type| {
                    const element = catalogue.definition(option_type, self.definitions()).?.option;
                    member = try self.coerce(member, element);
                    value_type = element;
                } else operator.value_type = w.catalogue.internOption(value_type) catch |err| return w.fail(token.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            } else if (operator.kind == .map) {
                if ((token.kind == .arrow) != (operator.arguments % 2 == 0)) return w.fail(token.span, .expected_map_value);
                if (operator.value_type) |map_type| {
                    const shape = catalogue.entryShape(map_type, self.definitions()).?;
                    const wanted = if (operator.arguments % 2 == 0) shape.key else shape.value;
                    member = try self.coerce(member, wanted);
                    value_type = wanted;
                } else if (operator.arguments % 2 == 0) {
                    if (!self.comparable(value_type)) return w.fail(self.node(member).span, w.equalityCode(value_type, .invalid_map_key));
                } else {
                    const key_type = self.node(w.staging[operator.head].node).value_type;
                    operator.value_type = w.catalogue.internMap(key_type, value_type) catch |err| return w.fail(token.span, switch (err) {
                        error.TypeLimit => .type_limit,
                        error.InvalidKey => .invalid_map_key,
                        error.InvalidType => .unsupported_type,
                    });
                }
            } else if (operator.value_type) |array_type| {
                const element = catalogue.definition(array_type, self.definitions()).?.array;
                member = try self.coerce(member, element);
                value_type = element;
            } else operator.value_type = w.catalogue.internArray(value_type) catch |err| return w.fail(token.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            if (w.staging_count == w.staging.len) return w.fail(token.span, .aggregate_limit);
            const index = w.staging_count;
            comptime std.debug.assert(types.limits.aggregate_elements < no_member and types.limits.record_fields < no_member);
            w.staging[index] = .{ .node = member, .field = operator.selected };
            if (operator.tail != no_member) w.staging[operator.tail].next = @intCast(index) else operator.head = index;
            operator.tail = index;
            operator.arguments += 1;
            operator.selected = no_member;
            w.staging_count += 1;
            self.operand_count = operator.operand_base;
            std.debug.assert(operator.arguments <= w.staging_count);
            std.debug.assert(w.staging[index].next == no_member);
        }

        fn memberPool(self: *Self) []u32 {
            return if (self.function != null) &self.workspace.functions.members else &self.workspace.members;
        }

        fn memberCount(self: *Self) *u32 {
            return if (self.function != null) &self.workspace.functions.member_count else &self.workspace.member_count;
        }

        fn reserveMembers(self: *Self, count: u32, span: Span) ParseError!Span {
            const used = self.memberCount();
            const pool = self.memberPool();
            // The template pool ends where the defaults of instantiated types begin.
            const limit = if (self.function != null) self.workspace.functions.member_top else pool.len;
            std.debug.assert(used.* <= limit);
            if (count > limit - used.*) return self.workspace.fail(span, .aggregate_limit);
            const range: Span = .{ .start = used.*, .end = used.* + count };
            used.* = range.end;
            std.debug.assert(range.end <= pool.len);
            return range;
        }

        fn closeAggregate(self: *Self, token: Token, empty: bool) ParseError!void {
            const w = self.workspace;
            if (empty) {
                if (self.operator_count == self.operator_base) return w.fail(token.span, .expected_expression);
                const top = w.operators[self.operator_count - 1];
                if ((top.kind != .record and top.kind != .array and top.kind != .tuple and top.kind != .option and top.kind != .map) or top.selected != no_member or self.operand_count != top.operand_base) return w.fail(token.span, .expected_expression);
            } else try self.finishMember(token);
            const operator = (try self.reduceToDelimiter(token)).*;
            if (operator.kind != .record and operator.kind != .array and operator.kind != .tuple and operator.kind != .option and operator.kind != .map) return w.fail(token.span, .unexpected_token);
            if (operator.kind == .map and operator.arguments % 2 != 0) return w.fail(token.span, .expected_map_value);
            const value_type = operator.value_type orelse if (operator.kind == .tuple) inferred: {
                var elements: [types.limits.tuple_arity]types.Type = undefined;
                var member = operator.head;
                var count: u32 = 0;
                while (member != no_member) {
                    std.debug.assert(count < elements.len and member < w.staging_count);
                    const entry = w.staging[member];
                    elements[count] = self.node(entry.node).value_type;
                    count += 1;
                    member = if (entry.next == no_member) no_member else entry.next;
                }
                std.debug.assert(count == operator.arguments);
                break :inferred try self.internTuple(elements[0..count], operator.span);
            } else return w.fail(operator.span, if (operator.kind == .option or operator.kind == .map) .contextual_type_required else .array_type_required);
            if (operator.kind == .tuple) {
                const shape = catalogue.definition(value_type, self.definitions()).?.tuple;
                if (operator.arguments != shape.end - shape.start) return w.fail(operator.span, .tuple_arity);
            }
            var complete_range: ?Span = null;
            if (operator.kind == .record and catalogue.definition(value_type, self.definitions()).? == .class) {
                try self.constructionEffect(value_type, operator.span);
                const class = catalogue.definition(value_type, self.definitions()).?.class;
                var roots: [types.limits.record_fields]u32 = undefined;
                const given = w.functions.node_count;
                try self.initialiseAccessors(operator, value_type, null);
                const count = try self.fieldRoots(operator, class.fields, &roots);
                const range = try self.reserveArguments(roots[0..count], operator.span);
                self.operator_count -= 1;
                // One node takes every field value, so no instance exists with a field unset; the
                // block clauses of its class then run on the complete instance.
                const object = try self.emit(.{ .span = .{ .start = operator.span.start, .end = token.span.end }, .value_type = value_type, .kind = .{ .object_new = .{ .arguments = range } } });
                try self.emitBlockCalls(value_type, object);
                try self.initialiseAccessors(operator, value_type, object);
                if (self.function != null) {
                    w.archetype_new = object;
                    w.archetype_end = w.functions.node_count;
                    w.archetype_given = given;
                }
                try self.pushOperand(object);
                return;
            }
            if (operator.kind == .record) {
                try self.structEffect(value_type, operator.span);
                const record = catalogue.definition(value_type, self.definitions()).?.record;
                if (operator.arguments != record.fields.end - record.fields.start) complete_range = try self.completeRecord(operator, record);
            }
            const range = complete_range orelse try self.reserveMembers(operator.arguments, operator.span);
            const pool = self.memberPool();
            var member = operator.head;
            var ordinal: u32 = 0;
            while (complete_range == null and member != no_member) {
                std.debug.assert(member < w.staging_count and ordinal < operator.arguments);
                const entry = w.staging[member];
                pool[range.start + if (operator.kind == .record) entry.field else ordinal] = entry.node;
                ordinal += 1;
                member = if (entry.next == no_member) no_member else entry.next;
            }
            std.debug.assert(complete_range != null or ordinal == operator.arguments);
            self.operator_count -= 1;
            try self.pushOperand(try self.emit(.{ .span = .{ .start = operator.span.start, .end = token.span.end }, .value_type = value_type, .kind = .{ .aggregate = range } }));
            if (operator.names == open_option) {
                std.debug.assert(operator.kind == .option and w.option_open_count > 0);
                w.option_open_count -= 1;
            }
            if (operator.names == caught_option) {
                // `Attempt(option{E}, option{})`: the alternative is the empty option of the same type.
                const attempt = w.operators[self.operator_count - 1];
                std.debug.assert(operator.kind == .option and attempt.kind == .attempt and attempt.names == caught_option and attempt.arguments == 0);
                try self.finishArgument(token);
                const none = try self.reserveMembers(0, operator.span);
                try self.pushOperand(try self.emit(.{ .span = .{ .start = operator.span.start, .end = token.span.end }, .value_type = value_type, .kind = .{ .aggregate = none } }));
                try self.closeParenthesis(token, false);
            }
        }

        /// RFC-0085, I9: each field with accessors and no default that `class` has, in the
        /// order the fields are declared, takes the value the archetype `operator` gave it.
        /// Without `object` this only checks that the archetype gave each one, before any
        /// default runs (as `fieldRoots` does for cells). With it, the instance `object` has
        /// been built and its block clauses have run: each setter now receives its value,
        /// through its slot as `set` calls it, and the construction needs its effects.
        fn initialiseAccessors(self: *Self, operator: Operator, class: types.Type, object: ?u32) ParseError!void {
            const w = self.workspace;
            if (w.accessor_required == 0) return;
            std.debug.assert(operator.kind == .record and operator.selected == no_member);
            // What this archetype gave, entered afresh: an archetype compiled inside its values
            // (or a method compiled where a parametric class is first named there) may have
            // entered values of its own since.
            w.accessor_archetypes += 1;
            const number = w.accessor_archetypes;
            var member = operator.accessor_head;
            var given_count: u32 = 0;
            while (member != no_member) : (member = w.staging[member].next) {
                const at = w.staging[member].field;
                if (w.accessor_given[at].archetype == number) return w.fail(operator.span, .duplicate_field);
                w.accessor_given[at] = .{ .archetype = number, .node = w.staging[member].node };
                given_count += 1;
            }
            const count = self.requiredAccessors(class);
            // Every value given is one of these: the archetype named only fields its class has.
            std.debug.assert(given_count <= count);
            for (w.accessor_order[0..count]) |index| {
                const entry = w.accessor_fields[index];
                // The methods of a class are declared before any of its archetypes is read.
                std.debug.assert(entry.required and entry.setter != no_member);
                const given = w.accessor_given[index];
                if (given.archetype != number) return w.fail(operator.span, .missing_field);
                const value = given.node;
                const built = object orelse continue;
                const callable = w.slots[entry.setter].callable;
                const shape = catalogue.definition(callable, self.definitions()).?.callable;
                try self.callEffect(operator.span, shape.effects());
                var passed = [3]u32{ try self.coerce(built, entry.owner), try self.accessorValue(operator.span), value };
                const lookup = try self.emit(.{ .span = operator.span, .value_type = callable, .kind = .{ .method_value = .{ .receiver = passed[0], .slot = entry.setter } } });
                const range = try self.reserveArguments(&passed, operator.span);
                _ = try self.emit(.{ .span = operator.span, .value_type = shape.result, .kind = .{ .invoke = .{ .callable = lookup, .arguments = range } } });
            }
        }

        fn completeRecord(self: *Self, operator: Operator, record: types.Record) ParseError!Span {
            const w = self.workspace;
            const count = record.fields.end - record.fields.start;
            std.debug.assert(operator.kind == .record and operator.arguments < count);
            var roots: [types.limits.record_fields]u32 = undefined;
            const filled = try self.fieldRoots(operator, record.fields, &roots);
            std.debug.assert(filled == count);
            // Nested default constructors reserve/emit first, so the parent's range
            // remains canonical and its immutable references point backwards.
            const range = try self.reserveMembers(count, operator.span);
            @memcpy(self.memberPool()[range.start..range.end], roots[0..count]);
            for (roots[0..count], self.fields()[record.fields.start..record.fields.end]) |root, field| std.debug.assert(self.node(root).value_type == field.value_type);
            _ = w;
            return range;
        }

        /// The value of every field in declaration order: the ones given, then each omitted field's
        /// default. Missing fields without a default are rejected before any default runs.
        fn fieldRoots(self: *Self, operator: Operator, span: Span, out: *[types.limits.record_fields]u32) ParseError!u32 {
            const w = self.workspace;
            const record = .{ .fields = span };
            const count = record.fields.end - record.fields.start;
            std.debug.assert(record.fields.end <= w.catalogue.field_count and count <= types.limits.record_fields);
            const roots = out[0..count];
            @memset(roots, no_member);
            var member = operator.head;
            while (member != no_member) {
                std.debug.assert(member < w.staging_count);
                const entry = w.staging[member];
                std.debug.assert(entry.field < count and roots[entry.field] == no_member);
                roots[entry.field] = entry.node;
                member = if (entry.next == no_member) no_member else entry.next;
            }
            // Reject the complete missing-required set before expanding defaults.
            for (roots[0..count], w.field_defaults[record.fields.start..record.fields.end]) |root, default| {
                if (root == no_member and default.start == default.end) return w.fail(operator.span, .missing_field);
            }
            for (roots[0..count], w.field_defaults[record.fields.start..record.fields.end]) |*root, default| {
                // RFC-0085, I12: a default runs where the instance is built.
                if (root.* == no_member and self.predicting() and self.dictatingTemplate(default.start, default.end)) return w.fail(operator.span, .construction_requires_dictates);
                if (root.* == no_member) root.* = try self.expandBody(default, &.{}, operator.span);
            }
            return count;
        }

        /// The receiver of the method being compiled, as an instance of that method's class.
        fn selfValue(self: *Self, span: Span) ParseError!u32 {
            const declared = self.function.?.parameters[0].value_type;
            const receiver = try self.emitTemplate(.{ .node = .{ .span = span, .value_type = declared, .kind = .{ .integer = 0 } }, .input = .{ .parameter = 0 } });
            const class = self.method_class orelse return receiver;
            if (class == declared) return receiver;
            // Dispatch only selects this body for instances of `class`; both machines still check.
            return self.emit(.{ .span = span, .value_type = class, .kind = .{ .downcast = receiver } });
        }

        /// Whether one scope declares both types.
        fn sameModule(self: *const Self, a: types.Type, b: types.Type) bool {
            const w = self.workspace;
            const first = catalogue.declaredName(catalogue.definition(a, self.definitions()).?).?;
            const second = catalogue.declaredName(catalogue.definition(b, self.definitions()).?).?;
            return w.homeOf(first) == w.homeOf(second);
        }

        /// A member is usable from the methods of its class (`private`), also from the methods of
        /// subclasses (`protected`), or from anywhere.
        fn checkAccess(self: *Self, access: Access, declaring: types.Type, span: Span) ParseError!void {
            if (access == .public) return;
            if (access == .internal) {
                // RFC-0076 (D14): the module that declares the type, and the modules nested in
                // it (rule 1 of RFC-0074). An instantiation is declared where its template is.
                const name = catalogue.declaredName(catalogue.definition(declaring, self.definitions()).?).?;
                if (!self.workspace.reaches(name)) return self.workspace.fail(span, .internal_member);
                return;
            }
            const inside: ?types.Type = if (self.function) |f| (if (f.is_method) self.method_class else null) else null;
            const current = inside orelse return self.workspace.fail(span, .inaccessible_member);
            const allowed = if (access == .private) current == declaring else catalogue.subtype(current, declaring, self.definitions());
            if (!allowed) return self.workspace.fail(span, .inaccessible_member);
        }

        /// Field `index` of `class` belongs to the outermost ancestor that already has that many fields.
        fn checkFieldAccess(self: *Self, class: types.Type, index: u32, span: Span, comptime write: bool) ParseError!void {
            var declaring = class;
            var shape = catalogue.definition(class, self.definitions()).?.class;
            const access = if (write) self.workspace.field_write[shape.fields.start + index] else self.workspace.field_access[shape.fields.start + index];
            if (access == .public) return;
            while (index < shape.inherited) {
                declaring = shape.parent.?;
                shape = catalogue.definition(declaring, self.definitions()).?.class;
            }
            // A field the class holds for an interface is the interface's member: who may use
            // it is decided where the interface is declared, not where the class is.
            if (access == .internal and shape.interface_count != 0) {
                const w = self.workspace;
                const text = self.fields()[shape.fields.start + index].name.text(w.source);
                if (w.findMethod(declaring, text)) |slot| if (w.slot_kind[slot] == .getter) {
                    declaring = w.slots[slot].owner;
                };
            }
            return self.checkAccess(access, declaring, span);
        }

        /// The first extension method named by `token` that this module can call: one of its own,
        /// or a public one of a module it names in `using`. Extension methods are scoped like
        /// functions, so two used modules that both offer the name leave the call ambiguous.
        fn findExtension(self: *Self, token: Token) ParseError!?u32 {
            const w = self.workspace;
            const text = token.span.text(w.source);
            if (w.functions.findIn(text, w.source, w.scope())) |index| {
                const f = w.functions.definitions[index];
                return if (f.is_extension and self.visible(f.name)) index else null;
            }
            if (!bundled) return null;
            // What the scopes around a nested module declare is in reach of it (RFC-0074), an
            // extension method like any function; the nearest declaration of the name decides.
            if (w.current_nested != types.no_parent) {
                var at = w.currentScope();
                while (w.outerScope(at)) |around| : (at = around) {
                    const index = w.functions.findIn(text, w.source, w.scopeOf(around)) orelse continue;
                    const f = w.functions.definitions[index];
                    return if (f.is_extension and self.visible(f.name)) index else null;
                }
            }
            var found: ?u32 = null;
            var hidden = false;
            for (w.using_edges[0..w.using_count]) |edge| {
                if (!w.insideScope(w.currentScope(), edge.module)) continue;
                const index = w.functions.findIn(text, w.source, w.scopeOf(edge.target)) orelse continue;
                if (!w.functions.definitions[index].is_extension) continue;
                var exported = false;
                var others = w.overloads(index);
                while (others.next()) |other| exported = exported or w.functions.definitions[other].is_public;
                if (!exported) {
                    hidden = true;
                    continue;
                }
                if (found != null and found.? != index) return w.fail(token.span, .ambiguous_call);
                found = index;
            }
            // With modules in files, an extension method that exists but is not public says so.
            if (found == null and hidden and w.module_storage.nested_count != 0) return w.fail(token.span, .private_name);
            return found;
        }

        /// `Value.Name(arguments)` where `Name` is an extension method: an ordinary call with the
        /// value as first argument. Null when no extension method has the name.
        fn startExtensionCall(self: *Self, token: Token) ParseError!?bool {
            const w = self.workspace;
            const text = token.span.text(w.source);
            const open = self.peek();
            if (!self.default_expression) if (self.function) |function| {
                // Inside its own body an extension method calls itself the way it is called,
                // on a value of the type it is declared for: on any other value the name is
                // what it is everywhere else (RFC-0077).
                if (function.is_extension and std.mem.eql(u8, text, function.name.text(w.source)) and function.parameter_count != 0 and self.receives(function.parameters[0].value_type, self.node(w.operands[self.operand_count - 1]).value_type)) {
                    if (open.kind != .left_paren and open.kind != .left_bracket) return w.fail(token.span, .expected_call);
                    // Its result type is not known while its body is compiled (RFC-0085, I7).
                    if (function.is_transparent) return w.fail(token.span, .transparent_recursion);
                    w.noteName(token.span, function.name.start, .global, qualify.none);
                    try self.callEffect(token.span, Effect.of(function).set());
                    if (function.decides and !self.failureContext()) return w.fail(token.span, .failure_context_required);
                    _ = try self.take(if (function.decides) .left_bracket else .left_paren, .expected_call);
                    try self.pushOperator(.{ .kind = .recur, .span = token.span, .operand_base = self.operand_count - 1, .selected = if (function.decides) 1 else no_member, .arguments = 1, .receiver = true });
                    return true;
                }
            };
            // A standard method (RFC-0077) is what the name means when no extension method has it,
            // or when those that have it are declared for values of other types than this one.
            const function = (try self.findExtension(token)) orelse return self.startStdMethod(token);
            if (!self.extensionTakes(function, self.node(w.operands[self.operand_count - 1]).value_type)) if (try self.startStdMethod(token)) |opened| return opened;
            // An extension method is only ever called: a function type has no receiver to remember.
            if (open.kind != .left_paren and open.kind != .left_bracket) return w.fail(token.span, .expected_call);
            const definition = w.functions.definitions[function];
            // An overload is noted where its arguments pick it (`expandCall`).
            if (!definition.overloaded) w.noteName(token.span, definition.name.start, .global, qualify.none);
            if (!definition.overloaded) try self.callEffect(token.span, Effect.of(definition).set());
            if (definition.decides and !self.failureContext()) return w.fail(token.span, .failure_context_required);
            _ = try self.take(if (definition.decides) .left_bracket else .left_paren, .expected_call);
            try self.pushOperator(.{ .kind = .call, .span = token.span, .function = function, .operand_base = self.operand_count - 1, .selected = if (definition.decides) 1 else no_member, .arguments = 1, .receiver = true });
            return true;
        }

        /// Reads a field or opens a method call; true when a call opened.
        fn accessField(self: *Self, dot: Token) ParseError!bool {
            std.debug.assert(self.operand_count > 0);
            const token = try self.take(.identifier, .expected_field);
            const value = self.workspace.operands[self.operand_count - 1];
            // `Super` is always followed by this access, so the mark never outlives it.
            const is_super = value == self.super_value;
            self.super_value = no_member;
            const name = token.span.text(self.workspace.source);
            // The text methods of RFC-0069 are members of their receiver's type: found first,
            // and `builtinMember` knows them, so no extension method can take their names.
            if (TextMethod.named(self.node(value).value_type, name)) |method| return self.startTextMethod(method, value, token);
            const known = self.builtinMember(self.node(value).value_type, name) or catalogue.findField(self.node(value).value_type, name, self.definitions(), self.fields(), self.workspace.source) != null;
            if (self.node(value).value_type == .string) {
                if (!known) return (try self.startExtensionCall(token)) orelse self.workspace.fail(token.span, .unknown_field);
                self.workspace.operands[self.operand_count - 1] = try self.emit(.{ .span = token.span, .value_type = .i64, .kind = .{ .string_length = value } });
                return false;
            }
            if (self.node(value).value_type.isCharacter()) return (try self.startExtensionCall(token)) orelse self.workspace.fail(token.span, .unknown_field);
            // A value without members of its own can still be the receiver of an extension method.
            const definition = catalogue.definition(self.node(value).value_type, self.definitions()) orelse return (try self.startExtensionCall(token)) orelse self.workspace.fail(dot.span, .type_mismatch);
            // A generic method and a member of one name that a class reaches by different
            // supertypes leave the name ambiguous (RFC-0081); one class declaring both is refused
            // where it is declared (`checkGenericMethods`).
            if (definition == .class and self.workspace.method_templates != 0 and (known or self.workspace.findMethod(self.node(value).value_type, name) != null)) {
                if (try self.genericMethodOf(self.node(value).value_type, name, false, token.span) != null) return self.workspace.fail(token.span, .ambiguous_call);
            }
            if (definition == .class and !known) {
                // RFC-0085, I8: a field with accessors is read by calling its getter.
                if (self.findAccessor(self.node(value).value_type, name)) |index| return self.readAccessor(value, index, token);
                if (self.workspace.findMethod(self.node(value).value_type, name)) |slot| {
                    const w = self.workspace;
                    // B4: what the receiver's class allows, which an override may have narrowed.
                    const allowed = self.memberAccess(self.node(value).value_type, slot);
                    try self.checkAccess(allowed.access, allowed.declaring, token.span);
                    w.noteName(token.span, w.slots[slot].name.start, .member, qualify.none);
                    if (w.slot_kind[slot] == .getter) {
                        // A field of an interface: the instance's class knows where it keeps it.
                        try self.stateEffect(token.span, .field_read);
                        var receiver = [1]u32{try self.coerce(value, w.slots[slot].owner)};
                        const getter = try self.emit(.{ .span = token.span, .value_type = w.slots[slot].callable, .kind = .{ .method_value = .{ .receiver = receiver[0], .slot = slot } } });
                        const range = try self.reserveArguments(&receiver, token.span);
                        w.operands[self.operand_count - 1] = try self.emit(.{ .span = token.span, .value_type = w.slot_field[slot].value_type, .kind = .{ .invoke = .{ .callable = getter, .arguments = range } } });
                        return false;
                    }
                    const fixed: ?usize = if (is_super) switch (w.implementationOf(slot, &catalogue.Supertypes.of(self.node(value).value_type, self.definitions()).?)) {
                        .found => |index| index,
                        .none, .ambiguous => return w.fail(token.span, .unimplemented_method),
                    } else null;
                    return self.startMethodCall(value, slot, token, fixed);
                }
                if (self.workspace.method_templates != 0) if (try self.genericMethodOf(self.node(value).value_type, name, false, token.span)) |found| return self.startGenericMethod(value, found, token);
            }
            // Members come first; an extension method is what a name means when the type has none.
            if (!known) if (try self.startExtensionCall(token)) |opened| return opened;
            const result = switch (definition) {
                .record => blk: {
                    const index = catalogue.findField(self.node(value).value_type, name, self.definitions(), self.fields(), self.workspace.source) orelse return self.workspace.fail(token.span, .unknown_field);
                    const field = catalogue.fieldAt(self.node(value).value_type, index, self.definitions(), self.fields()).?;
                    self.workspace.noteName(token.span, field.name.start, .member, qualify.none);
                    break :blk try self.emit(.{ .span = token.span, .value_type = field.value_type, .kind = .{ .field = .{ .value = value, .index = index } } });
                },
                .class => blk: {
                    const index = catalogue.findField(self.node(value).value_type, name, self.definitions(), self.fields(), self.workspace.source) orelse return self.workspace.fail(token.span, .unknown_field);
                    // A hidden raw field (RFC-0084, P4.3) is no member.
                    if (self.liveTypeOfField(self.node(value).value_type, index)) |entry| if (entry.hidden and entry.raw == index) return self.workspace.fail(token.span, .unknown_field);
                    const field = catalogue.classFieldAt(self.node(value).value_type, index, self.definitions(), self.fields()).?;
                    try self.checkFieldAccess(self.node(value).value_type, index, token.span, false);
                    self.workspace.noteName(token.span, field.name.start, .member, qualify.none);
                    try self.stateEffect(token.span, .field_read);
                    break :blk try self.emit(.{ .span = token.span, .value_type = field.value_type, .kind = .{ .object_get = .{ .value = value, .index = index } } });
                },
                .array, .map => blk: {
                    if (!std.mem.eql(u8, name, "Length")) return self.workspace.fail(token.span, .unknown_field);
                    break :blk try self.emit(.{ .span = token.span, .value_type = .i64, .kind = .{ .array_length = value } });
                },
                .option => blk: {
                    if (!std.mem.eql(u8, name, "IsSet")) return self.workspace.fail(token.span, .unknown_field);
                    break :blk try self.emit(.{ .span = token.span, .value_type = .logic, .kind = .{ .option_present = value } });
                },
                .enumeration, .tuple, .callable, .rational, .refinement => return self.workspace.fail(token.span, .type_mismatch),
                // A task handle has no member a program can name but `Await`, and an event none
                // but `Await` and `Signal` (RFC-0082, P3.2): those are standard methods.
                .task, .event, .live, .scheduled_interface, .cancelable, .ref, .grant => return self.workspace.fail(token.span, .unknown_field),
                // RFC-0087, W2: a `weak_map` has no `Length` (03:1112), and no other member.
                .weak_map => return self.workspace.fail(token.span, if (std.mem.eql(u8, name, "Length")) .weak_map_operation else .unknown_field),
            };
            self.workspace.operands[self.operand_count - 1] = result;
            return false;
        }

        /// RFC-0085, I8: `E.F` for a field with accessors is `E.G(accessor)`, a call of the getter
        /// through its slot, on the field's authority: the getter's own access does not limit
        /// it. The read needs `<reads>`, as any field read, and the getter's effects.
        fn readAccessor(self: *Self, value: u32, index: u32, token: Token) ParseError!bool {
            const w = self.workspace;
            const entry = w.accessor_fields[index];
            try self.checkAccess(entry.read, entry.owner, token.span);
            w.noteName(token.span, entry.name.start, .member, qualify.none);
            try self.stateEffect(token.span, .field_read);
            const callable = w.slots[entry.getter].callable;
            try self.callEffect(token.span, catalogue.definition(callable, self.definitions()).?.callable.effects());
            var arguments = [2]u32{ try self.coerce(value, entry.owner), try self.accessorValue(token.span) };
            const getter = try self.emit(.{ .span = token.span, .value_type = callable, .kind = .{ .method_value = .{ .receiver = arguments[0], .slot = entry.getter } } });
            const range = try self.reserveArguments(&arguments, token.span);
            w.operands[self.operand_count - 1] = try self.emit(.{ .span = token.span, .value_type = entry.value_type, .kind = .{ .invoke = .{ .callable = getter, .arguments = range } } });
            return false;
        }

        /// Opens a text method on the operand `receiver`. A method without arguments is emitted
        /// at once; `Slice` and `ScalarAt` become an operator that collects their arguments.
        /// Returns whether a bracket is now open.
        fn startTextMethod(self: *Self, method: TextMethod, receiver: u32, name: Token) ParseError!bool {
            const w = self.workspace;
            const open = self.peek();
            if (open.kind != @as(Token.Kind, if (method.decides()) .left_bracket else .left_paren)) return w.fail(name.span, .expected_call);
            if (method.decides() and !self.failureContext()) return w.fail(name.span, .failure_context_required);
            self.cursor += 1;
            if (method.arguments() != 0) {
                self.operand_count -= 1;
                try self.pushOperator(.{ .kind = .text_method, .span = name.span, .function = receiver, .head = @backingInt(method), .operand_base = self.operand_count, .selected = 1 });
                return true;
            }
            _ = try self.take(if (method.decides()) .right_bracket else .right_paren, .argument_count);
            w.operands[self.operand_count - 1] = try self.emitTextMethod(method, receiver, &.{}, name.span);
            return false;
        }

        fn emitText(self: *Self, span: Span, value_type: types.Type, op: types.TextOp, operands: [3]u32) ParseError!u32 {
            return self.emit(.{ .span = span, .value_type = value_type, .kind = .{ .text = (types.Text{ .op = op, .a = 0 }).mapped(operands) } });
        }
        fn emitInteger(self: *Self, span: Span, value: i64) ParseError!u32 {
            return self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .integer = value } });
        }
        fn emitCompare(self: *Self, span: Span, op: types.CompareOp, lhs: u32, rhs: u32) ParseError!u32 {
            return self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .compare = .{ .op = op, .lhs = lhs, .rhs = rhs } } });
        }
        fn emitBoth(self: *Self, span: Span, lhs: u32, rhs: u32) ParseError!u32 {
            return self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .logic_binary = .{ .op = .both, .lhs = lhs, .rhs = rhs } } });
        }
        fn emitDemand(self: *Self, span: Span, condition: u32) ParseError!void {
            _ = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .demand = condition } });
        }

        // The Book's standard functions (RFC-0077). A name reaches these only when the program
        // declares nothing by it. Each form lowers to nodes that exist: a `native_call` of a
        // kernel in `stdlib_natives.zig`, or the reads, slices and concatenations the machines
        // already have. A failable form is a `demand` in front of a total operation, as
        // `Items[I]` is, so its rollback, traces and failure contexts are those of `Require`.

        /// Whether a definition of the extension method `function` is declared for a receiver
        /// of this type or of a supertype of it.
        fn extensionTakes(self: *const Self, function: u32, receiver: types.Type) bool {
            const w = self.workspace;
            var others = w.overloads(function);
            while (others.next()) |index| {
                const candidate = &w.functions.definitions[index];
                if (!candidate.is_extension or candidate.parameter_count == 0) continue;
                if (self.receives(candidate.parameters[0].value_type, receiver)) return true;
            }
            return false;
        }

        /// Whether a receiver parameter of type `expected` takes a value of type `receiver`.
        fn receives(self: *const Self, expected: types.Type, receiver: types.Type) bool {
            return expected == receiver or catalogue.subtype(receiver, expected, self.definitions());
        }

        // One name has one meaning in a scope (RFC-0077 "Names"). A standard name that the
        // module declares itself, anywhere at its top level, is the module's throughout: a
        // use above the declaration does not quietly get the standard function, it is the
        // unknown name it was before there were standard functions. The declaration is
        // looked for in the tokens, once per name and scope.

        /// Whether the scope being compiled, or a scope around it, declares the standard name
        /// `name` at its top level: a binding, function, generic, type, alias or native for
        /// `method == null`, an extension method for that kind of receiver otherwise.
        fn stdDeclared(self: *const Self, bit: u32, name: []const u8, method: ?stdlib.Receiver) bool {
            const w = self.workspace;
            const row: usize = if (method) |kind| 1 + @as(usize, @backingInt(kind)) else 0;
            if (w.std_memo_pass != w.passes or w.std_memo_scope != w.currentScope()) {
                w.std_memo_pass = w.passes;
                w.std_memo_scope = w.currentScope();
                w.std_memo_known = @splat(0);
                w.std_memo_declared = @splat(0);
            }
            const mask = @as(u128, 1) << @intCast(bit);
            if (w.std_memo_known[row] & mask == 0) {
                var declared = self.stdScan(name, method, w.scope());
                var at = w.currentScope();
                while (!declared) {
                    at = w.outerScope(at) orelse break;
                    declared = self.stdScan(name, method, w.scopeOf(at));
                }
                w.std_memo_known[row] |= mask;
                if (declared) w.std_memo_declared[row] |= mask;
            }
            return w.std_memo_declared[row] & mask != 0;
        }

        /// Whether a statement at the top level of the scope with text `scope` declares `name`.
        /// RFC-0091 (B3): `Name(...)` in a function body, where nothing declares `Name` yet but
        /// the module declares one function of that name further down. The call is read
        /// against the header of that declaration, read here, and names a placeholder that
        /// the declaration's publication resolves. Returns false where the name is not such a
        /// call, so that it keeps the meaning it had.
        fn forwardCall(self: *Self, token: Token, resolved: Name, name: []const u8) ParseError!bool {
            const w = self.workspace;
            if (resolved.qualified or self.default_expression or self.generic != null) return false;
            const caller = self.function orelse return false;
            if (caller.is_constructor or self.memberNamed(name)) return false;
            if (self.peek().kind != .left_paren and self.peek().kind != .left_bracket) return false;
            const found = self.forwardHeader(name) orelse return false;
            const at = found.at;
            if (found.count != 1) return self.forwardFailure(resolved.span, w.tokens[at].span);
            const runtime = &w.runtime_functions;
            const entry = runtime.findForward(w.tokens[at].span) orelse fresh: {
                const header = try self.forwardSignature(at, resolved.span);
                break :fresh runtime.addForward(header.definition, header.has_default, resolved.span, w.node_count) catch return w.fail(resolved.span, .function_limit);
            };
            // Every call of it must find the module where the first found it, so that the
            // function, published further down, is available wherever its callers are.
            if (runtime.forward[entry].available_at != w.node_count) return w.fail(resolved.span, .forward_value_between);
            runtime.forward[entry].last_call = resolved.span.start;
            const callee = runtime.forward[entry].definition;
            w.noteName(token.span, callee.name.start, .global, qualify.none);
            try self.callEffect(resolved.span, Effect.of(callee).set());
            if (callee.decides and !self.failureContext()) return w.fail(resolved.span, .failure_context_required);
            _ = try self.take(if (callee.decides) .left_bracket else .left_paren, .expected_call);
            try self.pushOperator(.{ .kind = .call, .span = resolved.span, .function = entry, .operand_base = self.operand_count, .selected = if (callee.decides) 1 else no_member, .forward = true });
            return true;
        }

        fn forwardFailure(self: *Self, call: Span, declaration: Span) ParseError {
            const w = self.workspace;
            const failure = w.fail(call, .forward_signature);
            w.diagnostic.related = declaration;
            return failure;
        }

        /// The header of a module function `name` of this scope declared after the cursor, and
        /// how many headers of that name the scope has. Indexed once per scope and pass.
        fn forwardHeader(self: *Self, name: []const u8) ?struct { at: u32, count: u32 } {
            const w = self.workspace;
            if (w.forward_pass != w.passes or w.forward_scope != w.currentScope()) self.indexForwardHeaders();
            var same = w.forward_table.walk(&w.forward_slots, name_index.hashName(0, name));
            var first: ?u32 = null;
            var count: u32 = 0;
            while (same.next()) |index| {
                const at = w.forward_headers[index];
                if (!std.mem.eql(u8, w.tokens[at].span.text(w.source), name)) continue;
                count += 1;
                if (first == null or at < first.?) first = at;
            }
            const at = first orelse return null;
            if (at <= self.cursor) return null;
            return .{ .at = at, .count = count };
        }

        /// Every `Name(...)<...` and `Name<public>(...)<...` that starts a statement of the
        /// current scope at its top level: the headers of its plain functions.
        fn indexForwardHeaders(self: *Self) void {
            const w = self.workspace;
            w.forward_pass = w.passes;
            w.forward_scope = w.currentScope();
            w.forward_header_count = 0;
            w.forward_table.clear();
            const scope = w.scope();
            var depth: u32 = 0;
            var fresh = true;
            for (w.tokens[0..w.token_count], 0..) |token, at| {
                if (token.span.start < scope.start or token.span.start >= scope.end) continue;
                switch (token.kind) {
                    .left_brace, .left_paren, .left_bracket => {
                        depth += 1;
                        fresh = false;
                    },
                    .right_brace, .right_paren, .right_bracket => {
                        depth -|= 1;
                        fresh = false;
                    },
                    .newline, .separator => fresh = fresh or depth == 0,
                    .identifier => {
                        if (depth == 0 and fresh and w.forward_header_count < w.forward_headers.len and self.forwardHeaderAt(at)) {
                            const index = w.forward_header_count;
                            if (w.forward_table.crowded()) {
                                w.forward_table.grow(&w.forward_slots);
                                for (w.forward_headers[0..index], 0..) |earlier, item| w.forward_table.enter(&w.forward_slots, name_index.hashName(0, w.tokens[earlier].span.text(w.source)), @intCast(item));
                            }
                            w.forward_headers[index] = @intCast(at);
                            w.forward_table.enter(&w.forward_slots, name_index.hashName(0, token.span.text(w.source)), index);
                            w.forward_header_count += 1;
                        }
                        fresh = false;
                    },
                    else => fresh = false,
                }
            }
        }

        /// Whether token `word` starts the header of a plain function: its name, `<public>` or
        /// `<internal>`, its parameters and its effects.
        fn forwardHeaderAt(self: *const Self, word: usize) bool {
            const w = self.workspace;
            var next = word + 1;
            if (next + 3 >= w.token_count) return false;
            if (w.tokens[next].kind == .less) {
                const access = w.tokens[next + 1];
                if (access.kind != .identifier or w.tokens[next + 2].kind != .greater) return false;
                const text = access.span.text(w.source);
                if (!std.mem.eql(u8, text, "public") and !std.mem.eql(u8, text, "internal")) return false;
                next += 3;
            }
            if (next >= w.token_count or w.tokens[next].kind != .left_paren) return false;
            const after = self.stdAfterBracket(next) orelse return false;
            return after < w.token_count and w.tokens[after].kind == .less;
        }

        const ForwardHeader = struct { definition: functions.Definition, has_default: [types.limits.parameters]bool };

        /// Reads the header of the declaration whose name is token `at`, as its declaration
        /// will: parameters, effects and result type, resolved where the call stands. What
        /// cannot be read here is `forward_signature` at the call, naming the declaration.
        fn forwardSignature(self: *Self, at: u32, call: Span) ParseError!ForwardHeader {
            const w = self.workspace;
            const saved = self.cursor;
            const qualifying = w.qualify;
            w.qualify = false;
            defer {
                self.cursor = saved;
                w.qualify = qualifying;
            }
            const name = w.tokens[at];
            var header: ForwardHeader = .{ .definition = .{ .name = name.span, .value_type = .i64, .is_public = false, .start = 0, .end = 0, .root = 0 }, .has_default = @splat(false) };
            self.cursor = at + 1;
            self.readForwardHeader(&header) catch return self.forwardFailure(call, name.span);
            return header;
        }

        fn readForwardHeader(self: *Self, header: *ForwardHeader) ParseError!void {
            const w = self.workspace;
            const function = &header.definition;
            if (self.peek().kind == .less) function.is_public = try self.moduleAccess();
            _ = try self.take(.left_paren, .expected_parameter);
            self.skipNewlines();
            if (self.peek().kind == .right_paren) self.cursor += 1 else while (true) {
                if (self.peek().kind == .left_paren) {
                    const open = self.peek();
                    if (function.parameter_count == function.parameters.len) return w.fail(open.span, .parameter_limit);
                    const value_type = try self.parsePattern(function, false, null, no_member, function.parameter_count, 0);
                    function.parameters[function.parameter_count] = .{ .name = .{ .start = open.span.start, .end = open.span.start }, .value_type = value_type };
                    function.parameter_count += 1;
                    self.skipNewlines();
                    if (self.peek().kind == .right_paren) {
                        self.cursor += 1;
                        break;
                    }
                    _ = try self.take(.comma, .expected_parameter);
                    self.skipNewlines();
                    continue;
                }
                const name = try self.take(.identifier, .expected_parameter);
                if (function.parameter_count == function.parameters.len) return w.fail(name.span, .parameter_limit);
                const value_type = try self.parseType();
                function.parameters[function.parameter_count] = .{ .name = name.span, .value_type = value_type };
                if (self.peek().kind == .equal) {
                    header.has_default[function.parameter_count] = true;
                    // The default ends at the comma or parenthesis that ends its parameter.
                    var depth: u32 = 0;
                    while (true) : (self.cursor += 1) switch (self.peek().kind) {
                        .eof => return w.fail(self.peek().span, .expected_parameter),
                        .left_paren, .left_bracket, .left_brace => depth += 1,
                        .right_bracket, .right_brace => depth -|= 1,
                        .right_paren => if (depth == 0) break else {
                            depth -= 1;
                        },
                        .comma => if (depth == 0) break,
                        else => {},
                    };
                }
                function.parameter_count += 1;
                self.skipNewlines();
                if (self.peek().kind == .right_paren) {
                    self.cursor += 1;
                    break;
                }
                _ = try self.take(.comma, .expected_parameter);
                self.skipNewlines();
            }
            const effect = try self.parseEffect(.expected_computes);
            function.transacts = effect.transacts;
            function.decides = effect.decides;
            function.detail = effect.detail;
            // A transparent function's type is its body's, which is not compiled yet.
            if (self.peek().kind == .colon and w.tokens[self.cursor + 1].kind == .equal) return w.fail(self.peek().span, .forward_signature);
            function.value_type = (try self.parseResultType()).value_type;
        }

        fn stdScan(self: *const Self, name: []const u8, method: ?stdlib.Receiver, scope: Span) bool {
            const w = self.workspace;
            var depth: u32 = 0;
            var fresh = true;
            for (w.tokens[0..w.token_count], 0..) |token, at| {
                if (token.span.start < scope.start or token.span.start >= scope.end) continue;
                switch (token.kind) {
                    .left_brace, .left_paren, .left_bracket => {
                        if (depth == 0 and fresh and token.kind == .left_paren) if (method) |kind| {
                            if (self.stdExtensionHeader(at, name, kind)) return true;
                        };
                        depth += 1;
                        fresh = false;
                    },
                    .right_brace, .right_paren, .right_bracket => {
                        depth -|= 1;
                        fresh = false;
                    },
                    .newline, .separator => fresh = fresh or depth == 0,
                    .identifier => {
                        if (depth == 0 and fresh and method == null) {
                            // `var Name:T = ...` declares `Name` as `Name:T = ...` does.
                            const word = if (std.mem.eql(u8, token.span.text(w.source), "var") and at + 1 < w.token_count and w.tokens[at + 1].kind == .identifier) at + 1 else at;
                            if (std.mem.eql(u8, w.tokens[word].span.text(w.source), name) and self.stdDeclarationHeader(word)) return true;
                        }
                        fresh = false;
                    },
                    else => fresh = false,
                }
            }
            return false;
        }

        /// The token after the bracket that opens at `open`, or null when it does not close.
        fn stdAfterBracket(self: *const Self, open: usize) ?usize {
            const w = self.workspace;
            var depth: u32 = 0;
            var at = open;
            while (at < w.token_count) : (at += 1) switch (w.tokens[at].kind) {
                .left_brace, .left_paren, .left_bracket => depth += 1,
                .right_brace, .right_paren, .right_bracket => {
                    depth -= 1;
                    if (depth == 0) return at + 1;
                },
                .eof => return null,
                else => {},
            };
            return null;
        }

        /// Whether the name at token `word`, which starts a statement, is being declared:
        /// `Name:`, `Name<...>`, or a function header `Name(...)` or `Name[...](...)` that
        /// goes on with its effects or its result type. A call that is a statement does not.
        fn stdDeclarationHeader(self: *const Self, word: usize) bool {
            const w = self.workspace;
            if (word + 1 >= w.token_count) return false;
            var next = word + 1;
            switch (w.tokens[next].kind) {
                .colon, .less => return true,
                .left_bracket => {
                    next = self.stdAfterBracket(next) orelse return false;
                    if (next >= w.token_count or w.tokens[next].kind != .left_paren) return false;
                },
                .left_paren => {},
                else => return false,
            }
            next = self.stdAfterBracket(next) orelse return false;
            return next < w.token_count and (w.tokens[next].kind == .less or w.tokens[next].kind == .colon);
        }

        /// Whether the `(` at token `open`, which starts a statement, opens the header of an
        /// extension method `name` whose receiver is written as a type of this kind:
        /// `(Xs:[]T).Name`, `(S:string).Name`, `(X:float).Name`. A receiver written as a
        /// named type is a class, a struct or an alias, which a standard method does not
        /// have unless the alias names one of those three; that case is not seen from here.
        fn stdExtensionHeader(self: *const Self, open: usize, name: []const u8, kind: stdlib.Receiver) bool {
            const w = self.workspace;
            const after = self.stdAfterBracket(open) orelse return false;
            if (after + 1 >= w.token_count or w.tokens[after].kind != .dot or w.tokens[after + 1].kind != .identifier) return false;
            if (!std.mem.eql(u8, w.tokens[after + 1].span.text(w.source), name)) return false;
            if (open + 3 >= after or w.tokens[open + 1].kind != .identifier or w.tokens[open + 2].kind != .colon) return false;
            const first = w.tokens[open + 3];
            return switch (kind) {
                .array => first.kind == .left_bracket,
                .string => first.kind == .identifier and std.mem.eql(u8, first.span.text(w.source), "string"),
                .float => first.kind == .identifier and std.mem.eql(u8, first.span.text(w.source), "float"),
                .task => first.kind == .identifier and std.mem.eql(u8, first.span.text(w.source), "task"),
                .event => first.kind == .identifier and std.mem.eql(u8, first.span.text(w.source), "event"),
                .awaitable => first.kind == .identifier and std.mem.eql(u8, first.span.text(w.source), "awaitable"),
                .signalable => first.kind == .identifier and std.mem.eql(u8, first.span.text(w.source), "signalable"),
                .sticky_event => first.kind == .identifier and std.mem.eql(u8, first.span.text(w.source), "sticky_event"),
                .subscribable_event => first.kind == .identifier and std.mem.eql(u8, first.span.text(w.source), "subscribable_event"),
                .cancelable => first.kind == .identifier and std.mem.eql(u8, first.span.text(w.source), "cancelable"),
                // RFC-0086, P2.3.
                .reader => first.kind == .identifier and std.mem.eql(u8, first.span.text(w.source), "reader"),
                .writer => first.kind == .identifier and std.mem.eql(u8, first.span.text(w.source), "writer"),
            };
        }

        /// A local that is about to be declared under a standard name the same block already
        /// used as the standard function or constant would give the name two meanings in one
        /// scope: that is an error at the declaration. A local that takes such a name before
        /// any use of it is an ordinary local, so that the library can grow without breaking
        /// programs.
        fn stdLocalAfterUse(self: *const Self, name: Span) ParseError!void {
            const w = self.workspace;
            const text = name.text(w.source);
            const constant = std.mem.eql(u8, text, stdlib.pi_name);
            if (!constant and stdlib.function(text) == null and bitwiseNamed(text) == null) return;
            // RFC-0087: `weak_map(...)` is a type and never a use in an expression, so a local of
            // that name follows nothing it could have meant before.
            if (stdlib.function(text) == .weak_map_type) return;
            // Whatever the program declares by the name outside the block is what the uses meant.
            if (self.declaredCallee(text, w.scope()) or self.memberNamed(text)) return;
            var at: usize = @min(self.cursor, w.token_count - 1);
            while (at != 0 and !(w.tokens[at].kind == .identifier and w.tokens[at].span.start == name.start)) at -= 1;
            // From the declaration back to the brace that opens its block.
            var depth: u32 = 0;
            while (at != 0) {
                at -= 1;
                const token = w.tokens[at];
                switch (token.kind) {
                    .right_brace, .right_paren, .right_bracket => depth += 1,
                    .left_brace, .left_paren, .left_bracket => {
                        if (depth == 0) return;
                        depth -= 1;
                    },
                    .identifier => {
                        if (!std.mem.eql(u8, token.span.text(w.source), text)) continue;
                        if (at != 0 and w.tokens[at - 1].kind == .dot) continue;
                        const next = w.tokens[at + 1].kind;
                        // `Batch{` uses the form with a brace (RFC-0084, P4.5), and a form that
                        // fails is opened with a bracket (RFC-0086, P2.3).
                        if (if (constant) next != .colon else (next == .left_paren or (next == .left_brace and stdlib.function(text) == .batch) or (next == .left_bracket and stdFails(text)))) return w.fail(name, .used_before_declaration);
                    },
                    else => {},
                }
            }
        }

        /// What a value of this type can be the receiver of.
        fn stdReceiver(self: *const Self, value_type: types.Type) ?stdlib.Receiver {
            if (value_type == .string) return .string;
            if (value_type == .float) return .float;
            const definition = catalogue.definition(value_type, self.definitions()) orelse return null;
            return switch (definition) {
                .array => .array,
                .task => .task,
                // P3.9: each kind of event has its own methods.
                .event => |event| switch (event.kind) {
                    .plain => .event,
                    .sticky => .sticky_event,
                    .subscribable => .subscribable_event,
                },
                // P3.7.
                .scheduled_interface => |interface| if (interface.kind == .awaitable) .awaitable else .signalable,
                .cancelable => .cancelable,
                // RFC-0086, P2.3: a handle.
                .grant => |kind| switch (kind) {
                    .reader => .reader,
                    .writer => .writer,
                    // RFC-0087, P5.4: a session has no members.
                    else => null,
                },
                else => null,
            };
        }

        /// `Value.Name` where `Name` is a standard method of the value's type; null when it is
        /// none. The value is the top operand.
        fn startStdMethod(self: *Self, token: Token) ParseError!?bool {
            const w = self.workspace;
            const receiver = w.operands[self.operand_count - 1];
            const kind = self.stdReceiver(self.node(receiver).value_type) orelse return null;
            const form = stdlib.method(kind, token.span.text(w.source)) orelse return null;
            // An extension method of the name that the module declares further down for this
            // kind of receiver is what the name means here too: the standard method is not.
            if (self.stdDeclared(@backingInt(form), token.span.text(w.source), kind)) return null;
            return try self.openStd(form, receiver, token);
        }

        /// Opens the call of a standard form, a method of the operand `receiver` or a function
        /// (`no_member`). Returns whether a bracket is now open: a method without arguments is
        /// emitted at once.
        fn openStd(self: *Self, form: stdlib.Form, receiver: u32, name: Token) ParseError!bool {
            const w = self.workspace;
            const decides = form.decides();
            // `Spawn` takes braces and `task` and `event` are types: none is called (RFC-0082).
            if (form == .spawn or form == .task_type or form == .event_type) return w.fail(name.span, .unknown_name);
            // Nor are `awaitable` and `signalable` (P3.7).
            if (form == .awaitable_type or form == .signalable_type) return w.fail(name.span, .unknown_name);
            // `Sync` and `Race` read their arms as functions where they are opened (P3.3).
            if (form == .sync or form == .race) return w.fail(name.span, .unknown_name);
            // So does `Rush`, and `Branch` takes braces (P3.4).
            if (form == .rush or form == .branch) return w.fail(name.span, .unknown_name);
            // So do `Upon` and `When` (RFC-0084, P4.4).
            if (form == .upon or form == .when) return w.fail(name.span, .unknown_name);
            // And `Batch` takes braces (P4.5).
            if (form == .batch) return w.fail(name.span, .unknown_name);
            // `Await(G)` reads its guard where it is opened (P4.6).
            if (form == .await_guard) return w.fail(name.span, .unknown_name);
            // P3.9: the three types are no functions.
            if (form == .sticky_event_type or form == .subscribable_event_type or form == .cancelable_type) return w.fail(name.span, .unknown_name);
            // RFC-0085, I8: nor is `accessor`.
            if (form == .accessor_type) return w.fail(name.span, .unknown_name);
            // RFC-0087, P5.1: nor is `weak_map(K, V)`.
            if (form == .weak_map_type) return w.fail(name.span, .unknown_name);
            // RFC-0086, P2.3: nor are `reader` and `writer`.
            if (form == .reader_type or form == .writer_type) return w.fail(name.span, .unknown_name);
            // RFC-0087, P5.4: nor is `session`, nor (P5.5) `persistent_key`.
            if (form == .session_type or form == .persistent_key_type) return w.fail(name.span, .unknown_name);
            if (self.peek().kind != @as(Token.Kind, if (decides) .left_bracket else .left_paren)) return w.fail(name.span, .expected_call);
            if (form == .to_diagnostic and !self.stdDiagnosticPrinted()) return w.fail(name.span, .diagnostic_position);
            if (decides and !self.failureContext()) return w.fail(name.span, .failure_context_required);
            // RFC-0087, P5.3: `FromJson[T][Text]` (Q6) reads the type in its first bracket here.
            if (form == .from_json) return self.openFromJson(name);
            // RFC-0080: what the place of the call expects reaches the forms that build an array
            // from nothing or from a tuple, and the first argument of the forms whose first
            // argument is an array of a known type, so that an empty `array{}` is typed there.
            var context: ?types.Type = null;
            if (receiver == no_member) switch (form) {
                .concatenate, .to_array => context = self.expectedContext(),
                // RFC-0094: the body is typed by the place of the call, as the value it yields.
                .profile => context = self.expectedContext(),
                .join => context = w.catalogue.internArray(.string) catch |err| return w.fail(name.span, if (err == error.TypeLimit) .type_limit else .unsupported_type),
                else => {},
            };
            self.cursor += 1;
            // P3.7: a function of no arguments (`NextTick()`, `GetSimulationElapsedTime()`) is
            // emitted at once.
            if (receiver == no_member and form.arguments().max == 0) {
                // The parenthesis may close on a later line, as a call's may.
                self.skipNewlines();
                _ = try self.take(.right_paren, .argument_count);
                try self.pushOperand(try self.emitStd(form, no_member, &.{}, name.span));
                return false;
            }
            // One argument of `Concatenate` is an array of arrays, which the place does not type.
            if (receiver == no_member and form == .concatenate and self.peek().kind != .right_paren and !self.severalArguments()) context = null;
            if (receiver == no_member and form == .concatenate and self.peek().kind == .right_paren) {
                // `Concatenate()` joins nothing: the empty array, or the empty string, of the
                // type its place expects.
                const wanted = context orelse return w.fail(name.span, .array_type_required);
                const shape = catalogue.definition(wanted, self.definitions());
                if (wanted != .string and (shape == null or shape.? != .array)) return w.fail(name.span, .array_type_required);
                self.cursor += 1;
                try self.pushOperand(if (wanted == .string) try self.emit(.{ .span = name.span, .value_type = .string, .kind = .{ .string = .{ .start = 0, .end = 0 } } }) else try self.emit(.{ .span = name.span, .value_type = wanted, .kind = .{ .aggregate = try self.reserveMembers(0, name.span) } }));
                return false;
            }
            if (receiver != no_member) {
                if (form.arguments().min == 0 and self.peek().kind == @as(Token.Kind, if (decides) .right_bracket else .right_paren)) {
                    self.cursor += 1;
                    w.operands[self.operand_count - 1] = try self.emitStd(form, receiver, &.{}, name.span);
                    return false;
                }
                self.operand_count -= 1;
            }
            try self.pushOperator(.{ .kind = .text_method, .span = name.span, .function = receiver, .head = stdlib.first_head + @backingInt(form), .operand_base = self.operand_count, .selected = if (decides) 1 else no_member, .value_type = context });
            return true;
        }

        /// RFC-0087, P5.3: `FromJson[T][Text]`, after its name: the type `T`, which is persistable
        /// (`json_type` at its first token), and then the bracket of the text, which the form's
        /// operator reads as the one argument of a form that fails, holding `T`.
        fn openFromJson(self: *Self, name: Token) ParseError!bool {
            const w = self.workspace;
            self.cursor += 1;
            self.skipNewlines();
            const first = self.peek();
            const value_type = try self.parseTypeValue();
            if (!w.jsonShape(value_type).persistable) return w.fail(first.span, .json_type);
            self.skipNewlines();
            _ = try self.take(.right_bracket, .expected_call);
            if (self.peek().kind != .left_bracket) return w.fail(name.span, .expected_call);
            self.cursor += 1;
            try self.pushOperator(.{ .kind = .text_method, .span = name.span, .function = no_member, .head = stdlib.first_head + @backingInt(stdlib.Form.from_json), .operand_base = self.operand_count, .selected = 1, .value_type = value_type });
            return true;
        }

        /// Whether the `ToDiagnostic` about to be opened is the whole argument of a standard
        /// `Print`: the bracket before it is that `Print`'s, and nothing has been read since.
        /// A `diagnostic` is opaque (02:867): until it is a type of its own (with `any`,
        /// RFC-0079), the only place one can stand is where it is consumed.
        fn stdDiagnosticPrinted(self: *const Self) bool {
            const w = self.workspace;
            if (self.operator_count == 0 or self.cursor < 2) return false;
            const outer = w.operators[self.operator_count - 1];
            if (outer.kind != .text_method or outer.function != no_member or outer.head != stdlib.first_head + @as(u32, @backingInt(stdlib.Form.print))) return false;
            if (outer.arguments != 0 or self.operand_count != outer.operand_base) return false;
            // `self.cursor` is past the name: the token before the name opened the `Print`.
            return w.tokens[self.cursor - 2].kind == .left_paren and w.tokens[self.cursor - 2].span.start > outer.span.start;
        }

        /// The text of `ToDiagnostic(Value)`. The Book leaves the format open and promises
        /// only that every value is accepted (02:867): numbers, `logic`, characters and
        /// strings print as `ToString` prints them, a value of a type with a `ToString` of the
        /// program's own prints as that says, and any other value prints as the kind of thing it is.
        fn emitStdDiagnostic(self: *Self, operand: u32, span: Span) ParseError!u32 {
            const w = self.workspace;
            // Nothing may be done to a diagnostic but print it: the bracket of the `Print`
            // that holds it closes next.
            if (self.peek().kind != .right_paren) return w.fail(span, .diagnostic_position);
            const kind = self.node(operand).value_type;
            if (kind == .string) return operand;
            if (kind == .i64 or kind == .float or kind == .logic or kind.isCharacter()) return self.emit(.{ .span = span, .value_type = .string, .kind = .{ .to_string = operand } });
            // A refinement (RFC-0083) prints as its base does.
            if (catalogue.refinementOf(kind, self.definitions())) |refinement| return self.emit(.{ .span = span, .value_type = .string, .kind = .{ .to_string = try self.emit(.{ .span = span, .value_type = refinement.base, .kind = .{ .refine = operand } }) } });
            // RFC-0053, B5: a type with a `ToString` of the program's own prints as it says.
            if (try self.emitUserText(.{ .kind = .convert, .span = span, .function = @backingInt(Conversion.interpolation) }, operand)) |called| return called;
            const text: []const u8 = if (catalogue.definition(kind, self.definitions())) |definition| switch (definition) {
                .record => "<struct>",
                .array => "<array>",
                .enumeration => "<enum>",
                .tuple => "<tuple>",
                .option => "<option>",
                .map => "<map>",
                .callable => "<function>",
                .class => "<object>",
                .rational => "<rational>",
                .task => "<task>",
                .event => "<event>",
                .cancelable => "<cancelable>",
                .ref => "<ref>",
                .weak_map => "<weak_map>",
                // RFC-0086, P2.3: a handle prints as its type, as a task's does.
                .grant => |handle| switch (handle) {
                    .reader => "<reader>",
                    .writer => "<writer>",
                    // RFC-0087, P5.4, P5.5.
                    .key => "<persistent_key>",
                    else => "<session>",
                },
                .live => "<live>",
                .scheduled_interface => |interface| if (interface.kind == .awaitable) "<awaitable>" else "<signalable>",
                .refinement => unreachable,
            } else "<value>";
            const start = w.string_count;
            if (text.len > w.strings.len - start) return w.fail(span, .string_limit);
            @memcpy(w.strings[start..][0..text.len], text);
            w.string_count += @intCast(text.len);
            return self.emit(.{ .span = span, .value_type = .string, .kind = .{ .string = .{ .start = start, .end = w.string_count } } });
        }

        /// `PiFloat`, when nothing the program declares has the name.
        fn stdConstant(self: *Self, name: Name) ParseError!u32 {
            const w = self.workspace;
            if (name.qualified or self.memberNamed(name.token.span.text(w.source)) or !std.mem.eql(u8, name.token.span.text(w.source), stdlib.pi_name)) return w.fail(name.span, .unknown_name);
            if (self.stdDeclared(stdlib.pi_bit, stdlib.pi_name, null)) return w.fail(name.span, .unknown_name);
            w.noteName(name.token.span, qualify.none, .builtin, qualify.none);
            return self.emit(.{ .span = name.span, .value_type = .float, .kind = .{ .floating = std.math.pi } });
        }

        /// The type the next argument of a standard form is expected to have, where the form
        /// fixes one: an empty `array{}` or `option{}` there needs it.
        fn stdContext(self: *const Self, operator: Operator) ?types.Type {
            const w = self.workspace;
            const form: stdlib.Form = @fromBackingInt(operator.head - stdlib.first_head);
            const position = operator.arguments;
            if (operator.function == no_member) return switch (form) {
                .abs, .min, .max, .clamp, .concatenate_maps => if (position == 0) null else self.node(w.operands[operator.operand_base]).value_type,
                // The first array is typed by the place of the call (RFC-0080), the rest by it.
                .concatenate => if (position == 0) operator.value_type else self.node(w.operands[operator.operand_base]).value_type,
                .join => if (position == 0) operator.value_type else .string,
                .to_any, .to_void, .to_array, .to_base_int, .to_base_float => null,
                .print => .string,
                .get_random_int => .i64,
                .to_diagnostic, .shuffle => null,
                // RFC-0094: the tag is a text; the body is what the place of the call expects.
                .profile => if (position == 0) .string else operator.value_type,
                // RFC-0087, P5.3: any persistable value, and a text.
                .to_json => null,
                .from_json => .string,
                else => .float,
            };
            const receiver = self.node(operator.function).value_type;
            if (receiver == .string) return switch (form) {
                .find => types.Type.char,
                .replace_all => .string,
                .insert => if (position == 0) .i64 else .string,
                else => .i64,
            };
            const definition = catalogue.definition(receiver, self.definitions()) orelse return null;
            if (definition != .array) return null;
            return switch (form) {
                .find, .remove_first_element, .remove_all_elements, .replace_first_element, .replace_all_elements => definition.array,
                .replace_element => if (position == 0) .i64 else definition.array,
                .replace_all => receiver,
                .insert => if (position == 0) .i64 else receiver,
                else => .i64,
            };
        }

        /// A call of the kernel `id`, checked against the host's table as each machine will
        /// check it: a host that registered something else under the id does not have the form.
        fn stdCall(self: *Self, id: []const u8, result: types.Type, operands: []const u32, span: Span) ParseError!u32 {
            const w = self.workspace;
            const index = stdlib_natives.find(w.natives, id) orelse return w.fail(span, .unknown_native);
            var call: types.NativeCall = .{ .native = index, .count = @intCast(operands.len), .args = @splat(0) };
            var operand_types: [native.max_parameters]types.Type = undefined;
            for (operands, 0..) |operand, position| {
                call.args[position] = operand;
                operand_types[position] = self.node(operand).value_type;
            }
            const host = w.natives[index];
            if (!native.wellFormed(host) or !native.admits(host, operand_types[0..operands.len], result, self.definitions(), w.catalogue.comparable[0..w.catalogue.count])) return w.fail(span, .unknown_native);
            // The random draws dictate; `Print` predicts (RFC-0085, V22).
            if (native.dictates(host) and self.predicting()) return w.fail(span, .call_requires_dictates);
            return self.emit(.{ .span = span, .value_type = result, .kind = .{ .native_call = call } });
        }

        fn stdInteger(self: *Self, operand: u32) ParseError!u32 {
            if (self.node(operand).value_type != .i64) return self.workspace.fail(self.node(operand).span, .type_mismatch);
            return operand;
        }

        fn stdTyped(self: *Self, operand: u32, required: types.Type) ParseError!u32 {
            if (self.node(operand).value_type != required) return self.workspace.fail(self.node(operand).span, .type_mismatch);
            return operand;
        }

        /// Fails unless `0 <= start <= end <= length`: the ranges `Slice` and `Remove` accept.
        fn stdDemandRange(self: *Self, span: Span, length: u32, start: u32, end: u32) ParseError!void {
            const lower = try self.emitCompare(span, .greater_equal, start, try self.emitInteger(span, 0));
            const ordered = try self.emitCompare(span, .less_equal, start, end);
            const upper = try self.emitCompare(span, .less_equal, end, length);
            try self.emitDemand(span, try self.emitBoth(span, try self.emitBoth(span, lower, ordered), upper));
        }

        /// RFC-0086, P2.3: the value of the option a form yields, failing when it is empty, as
        /// `Maybe?` does.
        fn stdPresent(self: *Self, span: Span, option: u32) ParseError!u32 {
            const element = catalogue.definition(self.node(option).value_type, self.definitions()).?.option;
            const present = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .option_present = option } });
            try self.emitDemand(span, present);
            return self.emit(.{ .span = span, .value_type = element, .kind = .{ .option_value = option } });
        }

        /// The index a search found, failing when it found none.
        fn stdFound(self: *Self, span: Span, found: u32) ParseError!u32 {
            const present = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .option_present = found } });
            try self.emitDemand(span, present);
            return self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .option_value = found } });
        }

        /// The position `Last[]` or `Last[N]` reads: `Length - 1 - N`, failing unless `N` is
        /// in `0..Length-1`. `N` is checked first, so the subtraction cannot overflow.
        fn stdLastPosition(self: *Self, span: Span, length: u32, arguments: []const u32) ParseError!u32 {
            var position = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .binary = .{ .op = .subtract, .lhs = length, .rhs = try self.emitInteger(span, 1) } } });
            if (arguments.len == 1) {
                const back = try self.stdInteger(arguments[0]);
                try self.emitDemand(span, try self.emitCompare(span, .greater_equal, back, try self.emitInteger(span, 0)));
                position = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .binary = .{ .op = .subtract, .lhs = position, .rhs = back } } });
            }
            try self.emitDemand(span, try self.emitCompare(span, .greater_equal, position, try self.emitInteger(span, 0)));
            return position;
        }

        /// A standard form whose call has closed. What the place of the call expects, which
        /// `openStd` kept, is in reach of the form while it is emitted.
        fn emitStdIn(self: *Self, op: Operator, arguments: []const u32) ParseError!u32 {
            const outer = self.std_expected;
            defer self.std_expected = outer;
            self.std_expected = if (op.function == no_member) op.value_type else null;
            const form: stdlib.Form = @fromBackingInt(op.head - stdlib.first_head);
            if (form == .sync or form == .race or form == .rush) return self.emitStructured(op, arguments);
            if (form == .upon or form == .when) return self.emitReaction(op, form, arguments);
            if (form == .await_guard) return self.emitAwait(op, arguments);
            if (form == .profile) return self.emitProfile(op, arguments);
            return self.emitStd(form, op.function, arguments, op.span);
        }

        /// Whether the call whose opening parenthesis was just read has a comma between its
        /// arguments: more than one argument, as far as the tokens say.
        fn severalArguments(self: *const Self) bool {
            const w = self.workspace;
            var depth: u32 = 0;
            var at = self.cursor;
            while (at < w.token_count) : (at += 1) switch (w.tokens[at].kind) {
                .left_paren, .left_bracket, .left_brace => depth += 1,
                .right_paren, .right_bracket, .right_brace => {
                    if (depth == 0) return false;
                    depth -= 1;
                },
                .comma => if (depth == 0) return true,
                .eof => return false,
                else => {},
            };
            return false;
        }

        /// RFC-0094 (B6): `Profile(Tag, Body)` is the clock read when the tag is in (`finishArgument`),
        /// the body, a second read, and `Print` of one line with the difference; its value is the
        /// body's. Nothing is added to the IR: the reads are `GetSecondsSinceEpoch()`, so the time
        /// is the recorded clock of RFC-0086, and the line is `Print`'s, committed with its region.
        /// A body that leaves (`Return`, `Break`), fails or is cancelled skips the rest.
        fn emitProfile(self: *Self, op: Operator, arguments: []const u32) ParseError!u32 {
            const w = self.workspace;
            const span = op.span;
            if (arguments.len != 2) return w.fail(span, .argument_count);
            std.debug.assert(op.tail != no_member);
            const tag = arguments[0];
            const value = arguments[1];
            // A body that always leaves has no end to measure; it is what it was.
            if (self.node(value).value_type == types.Type.bottom) return value;
            const finished = try self.stdCall("std.clock_seconds", .float, &.{}, span);
            const elapsed = try self.emit(.{ .span = span, .value_type = .float, .kind = .{ .float_binary = .{ .op = .subtract, .lhs = finished, .rhs = op.tail } } });
            var line = try self.emitProfileText(span, "profile ");
            line = try self.emit(.{ .span = span, .value_type = .string, .kind = .{ .string_concat = .{ .lhs = line, .rhs = tag } } });
            line = try self.emit(.{ .span = span, .value_type = .string, .kind = .{ .string_concat = .{ .lhs = line, .rhs = try self.emitProfileText(span, ": ") } } });
            const seconds = try self.emit(.{ .span = span, .value_type = .string, .kind = .{ .to_string = elapsed } });
            line = try self.emit(.{ .span = span, .value_type = .string, .kind = .{ .string_concat = .{ .lhs = line, .rhs = seconds } } });
            line = try self.emit(.{ .span = span, .value_type = .string, .kind = .{ .string_concat = .{ .lhs = line, .rhs = try self.emitProfileText(span, " s") } } });
            const unit = w.catalogue.internTuple(&.{}) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            _ = try self.stdCall("std.print", unit, &.{line}, span);
            return value;
        }

        /// A piece of the line of `Profile`: text of the compiler's, kept in the string pool as
        /// the text of a diagnostic is.
        fn emitProfileText(self: *Self, span: Span, text: []const u8) ParseError!u32 {
            const w = self.workspace;
            const start = w.string_count;
            if (text.len > w.strings.len - start) return w.fail(span, .string_limit);
            @memcpy(w.strings[start..][0..text.len], text);
            w.string_count += @intCast(text.len);
            return self.emit(.{ .span = span, .value_type = .string, .kind = .{ .string = .{ .start = start, .end = w.string_count } } });
        }

        fn emitStd(self: *Self, form: stdlib.Form, receiver: u32, arguments: []const u32, span: Span) ParseError!u32 {
            const w = self.workspace;
            const bounds = form.arguments();
            if (arguments.len < bounds.min or arguments.len > bounds.max) return w.fail(span, .argument_count);
            if (receiver == no_member) return self.emitStdFunction(form, arguments, span);
            const receiver_type = self.node(receiver).value_type;
            if (receiver_type == .float) {
                // `X.IsFinite[]` succeeds with `X` itself.
                std.debug.assert(form == .is_finite);
                try self.emitDemand(span, try self.stdCall("std.is_finite", .logic, &.{receiver}, span));
                return receiver;
            }
            if (receiver_type == .string) return self.emitStdString(form, receiver, arguments, span);
            if (catalogue.isScheduled(receiver_type, self.definitions())) return self.emitStdScheduled(form, receiver, arguments, span);
            return self.emitStdArray(form, receiver, arguments, span);
        }

        /// `T.Await()`, `E.Await()` and `E.Signal(V)` (RFC-0082, P3.2). An `Await` is a site:
        /// it reads what the task or the event gives, only a function that suspends waits, and
        /// not where its code must finish at once. A `Signal` writes the event's waiters. From
        /// P3.7 also `T.Cancel()`, a site that writes (it asks a task to cancel), and the `Await`
        /// of an `awaitable(T)` and the `Signal` of a `signalable(T)`.
        fn emitStdScheduled(self: *Self, form: stdlib.Form, receiver: u32, arguments: []const u32, span: Span) ParseError!u32 {
            const w = self.workspace;
            const shape = catalogue.definition(self.node(receiver).value_type, self.definitions()).?;
            switch (form) {
                .await_value => {
                    try self.callEffect(span, .{ .reads = true, .suspends = true, .diverges = false, .dictates = false });
                    const site: types.Node = switch (shape) {
                        .task => |task| .{ .span = span, .value_type = task.result, .kind = .{ .task_await = receiver } },
                        .event => |event| .{ .span = span, .value_type = event.value, .kind = .{ .event_await = receiver } },
                        // P3.7: the handle or the event it holds is told apart where it runs.
                        .scheduled_interface => |interface| .{ .span = span, .value_type = interface.value, .kind = .{ .task_await = receiver } },
                        else => unreachable,
                    };
                    return self.checkSite(try self.emit(site));
                },
                // P3.9: a subscription's `Cancel` is no site: it ends the subscription, and a
                // region that fails takes that back (C111).
                .cancel => if (shape == .cancelable) {
                    try self.callEffect(span, .{ .writes = true, .diverges = false, .dictates = false });
                    const unit = w.catalogue.internTuple(&.{}) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                    return self.emit(.{ .span = span, .value_type = unit, .kind = .{ .subscription_cancel = receiver } });
                } else {
                    std.debug.assert(shape == .task);
                    try self.callEffect(span, .{ .writes = true, .suspends = true, .diverges = false, .dictates = false });
                    // A program that can cancel any task gets the landings of its `Defer`s
                    // (RFC-0082, C37, C61, C87).
                    w.structured_compiled = true;
                    const unit = w.catalogue.internTuple(&.{}) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                    return self.checkSite(try self.emit(.{ .span = span, .value_type = unit, .kind = .{ .task_cancel = receiver } }));
                },
                .signal => {
                    std.debug.assert(shape == .event or shape == .scheduled_interface);
                    // P3.9: a subscribable event's `Signal` calls its subscriptions, which may do
                    // anything `<transacts>` code may (C113).
                    const subscribable = shape == .event and shape.event.kind == .subscribable;
                    try self.callEffect(span, .{ .reads = subscribable, .writes = true, .allocates = subscribable, .diverges = false, .dictates = subscribable });
                    const value = try self.coerce(arguments[0], if (shape == .event) shape.event.value else shape.scheduled_interface.value);
                    const unit = w.catalogue.internTuple(&.{}) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                    const signalled = try self.emit(.{ .span = span, .value_type = unit, .kind = .{ .event_signal = .{ .event = receiver, .value = value } } });
                    if (!subscribable) return signalled;
                    return self.emit(.{ .span = span, .value_type = unit, .kind = .{ .event_notify = .{ .callable = receiver, .arguments = try self.reserveArguments(&.{value}, span) } } });
                },
                // RFC-0086, P2.3: `R.ReadLine[]`, an input that fails at the end of the stream (I6),
                // and `W.WriteLine(T)`, an action on the writer's channel (H5). Each is an effect
                // native, which needs all three heap effects and dictates.
                .read_line => {
                    std.debug.assert(shape == .grant and shape.grant == .reader);
                    try self.nativeEffect(span);
                    const option_type = w.catalogue.internOption(.string) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                    return self.stdPresent(span, try self.stdCall("std.read_line", option_type, &.{receiver}, span));
                },
                .write_line => {
                    std.debug.assert(shape == .grant and shape.grant == .writer);
                    try self.nativeEffect(span);
                    const text = try self.stdTyped(arguments[0], .string);
                    const unit = w.catalogue.internTuple(&.{}) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                    return self.stdCall("std.write_line", unit, &.{ receiver, text }, span);
                },
                // P3.9: `E.Subscribe(F)`, `F` seen as the callback type of the event's values (C107,
                // C108); the subscription is a `cancelable`, an instance.
                .subscribe => {
                    std.debug.assert(shape == .event and shape.event.kind == .subscribable);
                    try self.callEffect(span, .{ .writes = true, .allocates = true, .diverges = false, .dictates = false });
                    const parameters = try self.internTuple(&.{shape.event.value}, span);
                    const unit = try self.internTuple(&.{}, span);
                    const callback = try self.coerce(arguments[0], try self.internCallable(catalogue.subscriptionCallback(parameters, unit), span));
                    const made = w.catalogue.internCancelable() catch return w.fail(span, .type_limit);
                    return self.emit(.{ .span = span, .value_type = made, .kind = .{ .event_subscribe = .{ .event = receiver, .callback = callback } } });
                },
                else => unreachable,
            }
        }

        fn emitStdArray(self: *Self, form: stdlib.Form, receiver: u32, arguments: []const u32, span: Span) ParseError!u32 {
            const w = self.workspace;
            const array_type = self.node(receiver).value_type;
            const element = catalogue.definition(array_type, self.definitions()).?.array;
            const searches = switch (form) {
                .find, .remove_first_element, .remove_all_elements, .replace_first_element, .replace_all_elements, .replace_all => true,
                else => false,
            };
            // Searching compares elements: the Book has these methods for comparable ones only.
            // RFC-0087: equality on a `weak_map` is `weak_map_operation` wherever it is asked for.
            if (searches and !self.comparable(element)) return w.fail(span, if (catalogue.isWeakMap(element, self.definitions())) .weak_map_operation else .not_comparable);
            switch (form) {
                .find, .remove_first_element, .replace_first_element => {
                    const wanted = try self.coerce(arguments[0], element);
                    // The replacement is checked before anything is emitted that could fail.
                    const replacement = if (form == .replace_first_element) try self.coerce(arguments[1], element) else no_member;
                    const option_type = w.catalogue.internOption(.i64) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                    const index = try self.stdFound(span, try self.stdCall("std.array_find", option_type, &.{ receiver, wanted }, span));
                    if (form == .find) return index;
                    if (form == .replace_first_element) return self.emit(.{ .span = span, .value_type = array_type, .kind = .{ .array_set = .{ .array = receiver, .index = index, .value = replacement } } });
                    // An index of the array is below its length, so the next one exists.
                    const after = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .binary = .{ .op = .add, .lhs = index, .rhs = try self.emitInteger(span, 1) } } });
                    return self.stdCall("std.array_remove", array_type, &.{ receiver, index, after }, span);
                },
                .remove_all_elements => return self.stdCall("std.array_remove_all", array_type, &.{ receiver, try self.coerce(arguments[0], element) }, span),
                .replace_all_elements => {
                    const wanted = try self.coerce(arguments[0], element);
                    return self.stdCall("std.array_replace_each", array_type, &.{ receiver, wanted, try self.coerce(arguments[1], element) }, span);
                },
                .replace_all => {
                    const pattern = try self.stdTyped(arguments[0], array_type);
                    return self.stdCall("std.array_replace_all", array_type, &.{ receiver, pattern, try self.stdTyped(arguments[1], array_type) }, span);
                },
                .remove, .slice => {
                    const start = try self.stdInteger(arguments[0]);
                    if (arguments.len == 2) _ = try self.stdInteger(arguments[1]);
                    const length = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .array_length = receiver } });
                    const end = if (arguments.len == 2) arguments[1] else length;
                    try self.stdDemandRange(span, length, start, end);
                    return self.stdCall(if (form == .remove) "std.array_remove" else "std.array_slice", array_type, &.{ receiver, start, end }, span);
                },
                .insert => {
                    const at = try self.stdInteger(arguments[0]);
                    const added = try self.stdTyped(arguments[1], array_type);
                    const length = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .array_length = receiver } });
                    try self.stdDemandRange(span, length, at, at);
                    return self.stdCall("std.array_insert", array_type, &.{ receiver, at, added }, span);
                },
                .replace_element => {
                    const index = try self.stdInteger(arguments[0]);
                    const value = try self.coerce(arguments[1], element);
                    const length = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .array_length = receiver } });
                    const inside = try self.emitBoth(span, try self.emitCompare(span, .greater_equal, index, try self.emitInteger(span, 0)), try self.emitCompare(span, .less, index, length));
                    try self.emitDemand(span, inside);
                    return self.emit(.{ .span = span, .value_type = array_type, .kind = .{ .array_set = .{ .array = receiver, .index = index, .value = value } } });
                },
                .last => {
                    if (arguments.len == 1) _ = try self.stdInteger(arguments[0]);
                    const length = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .array_length = receiver } });
                    const position = try self.stdLastPosition(span, length, arguments);
                    return self.emit(.{ .span = span, .value_type = element, .kind = .{ .array_get = .{ .array = receiver, .index = position } } });
                },
                else => unreachable, // `stdlib.method` offers an array nothing else.
            }
        }

        /// The methods of a string. Positions are code units, and a position that would split
        /// an encoded scalar fails, as it does for `Slice`: the result is always text.
        fn emitStdString(self: *Self, form: stdlib.Form, receiver: u32, arguments: []const u32, span: Span) ParseError!u32 {
            const w = self.workspace;
            switch (form) {
                .find => {
                    const unit = try self.stdTyped(arguments[0], types.Type.char);
                    const code = try self.emitText(span, .i64, .code, .{ unit, 0, 0 });
                    const option_type = w.catalogue.internOption(.i64) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                    return self.stdFound(span, try self.stdCall("std.string_find_unit", option_type, &.{ receiver, code }, span));
                },
                .replace_all => {
                    const pattern = try self.stdTyped(arguments[0], .string);
                    return self.stdCall("std.string_replace_all", .string, &.{ receiver, pattern, try self.stdTyped(arguments[1], .string) }, span);
                },
                .insert, .remove => {
                    const start = try self.stdInteger(arguments[0]);
                    const second = if (form == .insert) try self.stdTyped(arguments[1], .string) else try self.stdInteger(arguments[1]);
                    const end = if (form == .insert) start else second;
                    const length = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .string_length = receiver } });
                    var holds = try self.emitText(span, .logic, .boundary, .{ receiver, start, 0 });
                    if (form == .remove) {
                        holds = try self.emitBoth(span, holds, try self.emitText(span, .logic, .boundary, .{ receiver, end, 0 }));
                        holds = try self.emitBoth(span, holds, try self.emitCompare(span, .less_equal, start, end));
                    }
                    try self.emitDemand(span, holds);
                    var head = try self.emitText(span, .string, .slice, .{ receiver, try self.emitInteger(span, 0), start });
                    if (form == .insert) head = try self.emit(.{ .span = span, .value_type = .string, .kind = .{ .string_concat = .{ .lhs = head, .rhs = second } } });
                    const tail = try self.emitText(span, .string, .slice, .{ receiver, end, length });
                    return self.emit(.{ .span = span, .value_type = .string, .kind = .{ .string_concat = .{ .lhs = head, .rhs = tail } } });
                },
                .last => {
                    if (arguments.len == 1) _ = try self.stdInteger(arguments[0]);
                    const length = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .string_length = receiver } });
                    const position = try self.stdLastPosition(span, length, arguments);
                    return self.emitText(span, types.Type.char, .unit, .{ receiver, position, 0 });
                },
                else => unreachable, // `stdlib.method` offers a string nothing else.
            }
        }

        fn emitStdFunction(self: *Self, form: stdlib.Form, arguments: []const u32, span: Span) ParseError!u32 {
            const w = self.workspace;
            if (arguments.len == 0) std.debug.assert(form == .next_tick or form == .elapsed_time or form == .seconds_since_epoch or form == .get_session);
            const first = if (arguments.len == 0) types.Type.any else self.node(arguments[0]).value_type;
            switch (form) {
                .abs, .min, .max, .clamp => {
                    // Defined for `int` and for `float`: the arguments choose, and agree.
                    if (first != .i64 and first != .float) return w.fail(self.node(arguments[0]).span, .type_mismatch);
                    for (arguments[1..]) |argument| _ = try self.stdTyped(argument, first);
                    const integer = first == .i64;
                    return switch (form) {
                        .abs => if (integer) self.stdCall("std.abs_int", .i64, arguments, span) else self.stdCall("std.abs", .float, arguments, span),
                        .min => if (integer) self.stdCall("std.min_int", .i64, arguments, span) else self.stdCall("std.min_float", .float, arguments, span),
                        .max => if (integer) self.stdCall("std.max_int", .i64, arguments, span) else self.stdCall("std.max_float", .float, arguments, span),
                        else => if (integer) self.stdCall("std.clamp_int", .i64, arguments, span) else self.stdCall("std.clamp_float", .float, arguments, span),
                    };
                },
                .concatenate => return self.emitStdConcatenate(arguments, span),
                // RFC-0080. `any(X)` is the one way into `any`: the value itself, seen as the top
                // type. `void(X)` evaluates `X` and is the unit value.
                // A refinement (RFC-0083) does not go into `any` either: its value is its base's,
                // which a type test would answer for. `any(i64(Age))` says which is meant.
                .to_any => return if (first == types.Type.any) arguments[0] else if (catalogue.isScheduled(first, self.definitions()) or catalogue.refinementOf(first, self.definitions()) != null) w.fail(self.node(arguments[0]).span, .type_mismatch) else self.emit(.{ .span = span, .value_type = types.Type.any, .kind = .{ .upcast = arguments[0] } }),
                // `i64(X)` and `float(X)` (RFC-0083): the Book's infallible cast to a base, which
                // a refinement over it always has. A value of the base is itself.
                .to_base_int, .to_base_float => {
                    const base: types.Type = if (form == .to_base_int) .i64 else .float;
                    if (first == base) return arguments[0];
                    const refinement = catalogue.refinementOf(first, self.definitions()) orelse return w.fail(self.node(arguments[0]).span, .type_mismatch);
                    if (refinement.base != base) return w.fail(self.node(arguments[0]).span, .type_mismatch);
                    return self.emit(.{ .span = span, .value_type = base, .kind = .{ .refine = arguments[0] } });
                },
                .to_void => return self.packTuple(&.{}, span),
                // `ToArray(Tuple)` is the explicit conversion of RFC-0067 D8: the elements of a
                // tuple, in order, as an array. Their one type is the element type; where the
                // place of the call expects an array type, each element converts to its element
                // type as a value does anywhere (a subclass to its superclass, nothing else).
                .to_array => {
                    const shape = catalogue.definition(first, self.definitions()) orelse return w.fail(self.node(arguments[0]).span, .type_mismatch);
                    if (shape != .tuple) return w.fail(self.node(arguments[0]).span, .type_mismatch);
                    const arity = shape.tuple.end - shape.tuple.start;
                    var wanted: ?types.Type = null;
                    if (self.std_expected) |expected| if (catalogue.definition(expected, self.definitions())) |expected_shape| {
                        if (expected_shape == .array) wanted = expected_shape.array;
                    };
                    if (wanted == null and arity == 0) return w.fail(span, .array_type_required);
                    const element = wanted orelse w.catalogue.tuple_elements[shape.tuple.start];
                    const array_type = w.catalogue.internArray(element) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                    var members: [types.limits.tuple_arity]u32 = undefined;
                    for (members[0..arity], 0..) |*member, position| {
                        const part = try self.emit(.{ .span = span, .value_type = w.catalogue.tuple_elements[shape.tuple.start + position], .kind = .{ .tuple_element = .{ .value = arguments[0], .index = @intCast(position) } } });
                        member.* = try self.coerce(part, element);
                    }
                    const range = try self.reserveMembers(arity, span);
                    @memcpy(self.memberPool()[range.start..range.end], members[0..arity]);
                    return self.emit(.{ .span = span, .value_type = array_type, .kind = .{ .aggregate = range } });
                },
                .concatenate_maps => {
                    const shape = catalogue.definition(first, self.definitions()) orelse return w.fail(self.node(arguments[0]).span, .type_mismatch);
                    // RFC-0087: no `weak_map` is joined (03:1112).
                    if (shape == .weak_map) return w.fail(self.node(arguments[0]).span, .weak_map_operation);
                    if (shape != .map) return w.fail(self.node(arguments[0]).span, .type_mismatch);
                    if (catalogue.isWeakMap(self.node(arguments[1]).value_type, self.definitions())) return w.fail(self.node(arguments[1]).span, .weak_map_operation);
                    _ = try self.stdTyped(arguments[1], first);
                    return self.stdCall("std.map_concatenate", first, arguments, span);
                },
                .join => {
                    const shape = catalogue.definition(first, self.definitions()) orelse return w.fail(self.node(arguments[0]).span, .type_mismatch);
                    if (shape != .array or shape.array != .string) return w.fail(self.node(arguments[0]).span, .type_mismatch);
                    _ = try self.stdTyped(arguments[1], .string);
                    return self.stdCall("std.join", .string, arguments, span);
                },
                // Effects (RFC-0079). Each is a call of an effect native, so the function
                // that makes it is `<transacts>`, as for a write.
                .print => {
                    try self.nativeEffect(span);
                    _ = try self.stdTyped(arguments[0], .string);
                    const unit = w.catalogue.internTuple(&.{}) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                    return self.stdCall("std.print", unit, arguments, span);
                },
                .to_diagnostic => return self.emitStdDiagnostic(arguments[0], span),
                .sleep => {
                    // A site (RFC-0082): only a function that suspends sleeps, and not where its
                    // code must finish at once.
                    try self.callEffect(span, .{ .suspends = true, .diverges = false, .dictates = false });
                    _ = try self.stdTyped(arguments[0], .float);
                    const unit = w.catalogue.internTuple(&.{}) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                    return self.checkSite(try self.emit(.{ .span = span, .value_type = unit, .kind = .{ .sleep = arguments[0] } }));
                },
                .spawn, .task_type, .event_type => unreachable, // `openStd` refuses them.
                .sync, .race => unreachable, // `emitStdIn` emits them.
                .rush => unreachable, // So it does this one.
                .branch => unreachable, // `openStd` refuses it.
                .upon, .when => unreachable, // `emitStdIn` emits them.
                .batch => unreachable, // `openStd` refuses it.
                .await_guard => unreachable, // `emitStdIn` emits it (P4.6).
                .await_value, .signal => unreachable, // Methods, which have a receiver.
                .cancel => unreachable, // So is this one.
                .awaitable_type, .signalable_type => unreachable, // `openStd` refuses them.
                .sticky_event_type, .subscribable_event_type, .cancelable_type => unreachable, // So it does these (P3.9).
                .accessor_type => unreachable, // And this one (RFC-0085, I8).
                .weak_map_type => unreachable, // And this one (RFC-0087).
                .subscribe => unreachable, // A method.
                // P3.7: `NextTick()` is `Sleep(0.0)` (Q2, Q3), a site.
                .next_tick => {
                    try self.callEffect(span, .{ .suspends = true, .diverges = false, .dictates = false });
                    const zero = try self.emit(.{ .span = span, .value_type = .float, .kind = .{ .floating = 0.0 } });
                    const unit = w.catalogue.internTuple(&.{}) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                    return self.checkSite(try self.emit(.{ .span = span, .value_type = unit, .kind = .{ .sleep = zero } }));
                },
                // P3.7: the virtual clock in seconds, which the function reads.
                .elapsed_time => {
                    try self.callEffect(span, .{ .reads = true, .diverges = false, .dictates = false });
                    return self.emit(.{ .span = span, .value_type = .float, .kind = .elapsed_time });
                },
                .get_random_int => {
                    try self.nativeEffect(span);
                    for (arguments) |argument| _ = try self.stdTyped(argument, .i64);
                    return self.stdCall("std.random_int", .i64, arguments, span);
                },
                // RFC-0086, P2.2: the wall clock is an input, an effect native as a draw is.
                .seconds_since_epoch => {
                    try self.nativeEffect(span);
                    return self.stdCall("std.clock_seconds", .float, &.{}, span);
                },
                // RFC-0086, P2.3 (H3): the handle of the grant of the name, failing when the run
                // has none. It reads the run's grant list, which never changes.
                .open_reader, .open_writer, .get_persistent_key => {
                    try self.callEffect(span, .{ .reads = true, .diverges = false, .dictates = false });
                    const name = try self.stdTyped(arguments[0], .string);
                    // RFC-0087, P5.5 (K2): `GetPersistentKey[Name]` is the same lookup among the
                    // keys the host granted.
                    const kind: types.GrantKind = switch (form) {
                        .open_writer => .writer,
                        .get_persistent_key => .key,
                        else => .reader,
                    };
                    const handle = w.catalogue.internGrant(kind) catch return w.fail(span, .type_limit);
                    const option_type = w.catalogue.internOption(handle) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                    return self.stdPresent(span, try self.emit(.{ .span = span, .value_type = option_type, .kind = .{ .grant = .{ .kind = kind, .name = name } } }));
                },
                .profile => unreachable, // `emitStdIn` emits it (RFC-0094).
                .reader_type, .writer_type => unreachable, // `openStd` refuses them.
                .read_line, .write_line => unreachable, // Methods.
                // RFC-0087, P5.4 (K1): the run's one session. It reads the run, as `OpenReader`
                // reads its grants, and cannot fail.
                .get_session => {
                    try self.callEffect(span, .{ .reads = true, .diverges = false, .dictates = false });
                    const session = w.catalogue.internGrant(.session) catch return w.fail(span, .type_limit);
                    return self.emit(.{ .span = span, .value_type = session, .kind = .{ .grant = .{ .kind = .session, .name = types.no_grant_name } } });
                },
                .session_type, .persistent_key_type => unreachable, // `openStd` refuses them.
                // RFC-0087, P5.3 (E1): the canonical text of a persistable value, which reads
                // instances when its type reaches a class.
                .to_json => {
                    const shape = w.jsonShape(first);
                    if (!shape.persistable) return w.fail(self.node(arguments[0]).span, .json_type);
                    if (shape.reaches_class) try self.stateEffect(span, .field_read);
                    return self.emit(.{ .span = span, .value_type = .string, .kind = .{ .json_encode = arguments[0] } });
                },
                // RFC-0087, P5.3 (E4): the value the text encodes as `T`, failing when it encodes
                // none, which builds instances when `T` reaches a class. `openFromJson` read `T`.
                .from_json => {
                    const value_type = self.std_expected.?;
                    const text = try self.stdTyped(arguments[0], .string);
                    if (w.jsonShape(value_type).reaches_class) try self.stateEffect(span, .construction);
                    const option_type = w.catalogue.internOption(value_type) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                    return self.stdPresent(span, try self.emit(.{ .span = span, .value_type = option_type, .kind = .{ .json_decode = text } }));
                },
                .get_random_float => {
                    try self.nativeEffect(span);
                    for (arguments) |argument| _ = try self.stdTyped(argument, .float);
                    return self.stdCall("std.random_float", .float, arguments, span);
                },
                .shuffle => {
                    try self.nativeEffect(span);
                    const shape = catalogue.definition(first, self.definitions()) orelse return w.fail(self.node(arguments[0]).span, .type_mismatch);
                    if (shape != .array) return w.fail(self.node(arguments[0]).span, .type_mismatch);
                    // One draw, and a pure permutation that the word drawn decides.
                    const key = try self.stdCall("std.random_word", .i64, &.{}, span);
                    return self.stdCall("std.array_shuffled", first, &.{ arguments[0], key }, span);
                },
                else => {},
            }
            // The rest take floats and give one.
            for (arguments) |argument| _ = try self.stdTyped(argument, .float);
            return switch (form) {
                .sqrt => self.stdCall("std.sqrt", .float, arguments, span),
                .pow => self.stdCall("std.pow", .float, arguments, span),
                .exp => self.stdCall("std.exp", .float, arguments, span),
                .ln => self.stdCall("std.ln", .float, arguments, span),
                .log => self.stdCall("std.log", .float, arguments, span),
                .sin => self.stdCall("std.sin", .float, arguments, span),
                .cos => self.stdCall("std.cos", .float, arguments, span),
                .tan => self.stdCall("std.tan", .float, arguments, span),
                .arc_sin => self.stdCall("std.arc_sin", .float, arguments, span),
                .arc_cos => self.stdCall("std.arc_cos", .float, arguments, span),
                .arc_tan => if (arguments.len == 1) self.stdCall("std.arc_tan", .float, arguments, span) else self.stdCall("std.arc_tan2", .float, arguments, span),
                .sinh => self.stdCall("std.sinh", .float, arguments, span),
                .cosh => self.stdCall("std.cosh", .float, arguments, span),
                .tanh => self.stdCall("std.tanh", .float, arguments, span),
                .ar_sinh => self.stdCall("std.ar_sinh", .float, arguments, span),
                .ar_cosh => self.stdCall("std.ar_cosh", .float, arguments, span),
                .ar_tanh => self.stdCall("std.ar_tanh", .float, arguments, span),
                .lerp => self.stdCall("std.lerp", .float, arguments, span),
                else => unreachable, // Every other form is a method or was emitted above.
            };
        }

        /// `Concatenate(Rows)` flattens an array of arrays, or joins an array of strings, in
        /// one pass. `Concatenate(A, B, ...)` is the Book's call with the arrays themselves,
        /// which it gathers into that array; here it is the chain `A + B + ...`.
        fn emitStdConcatenate(self: *Self, arguments: []const u32, span: Span) ParseError!u32 {
            const w = self.workspace;
            const first = self.node(arguments[0]).value_type;
            const shape: ?types.Definition = catalogue.definition(first, self.definitions());
            if (arguments.len == 1) {
                const rows = shape orelse return w.fail(self.node(arguments[0]).span, .type_mismatch);
                if (rows != .array) return w.fail(self.node(arguments[0]).span, .type_mismatch);
                if (rows.array == .string) {
                    const nothing = try self.emit(.{ .span = span, .value_type = .string, .kind = .{ .string = .{ .start = 0, .end = 0 } } });
                    return self.stdCall("std.join", .string, &.{ arguments[0], nothing }, span);
                }
                const row = catalogue.definition(rows.array, self.definitions()) orelse return w.fail(self.node(arguments[0]).span, .type_mismatch);
                if (row != .array) return w.fail(self.node(arguments[0]).span, .type_mismatch);
                return self.stdCall("std.array_concatenate", rows.array, arguments, span);
            }
            if (first != .string and (shape == null or shape.? != .array)) return w.fail(self.node(arguments[0]).span, .type_mismatch);
            var joined = arguments[0];
            for (arguments[1..]) |argument| {
                _ = try self.stdTyped(argument, first);
                joined = try self.emit(.{ .span = span, .value_type = first, .kind = if (first == .string) .{ .string_concat = .{ .lhs = joined, .rhs = argument } } else .{ .array_concat = .{ .lhs = joined, .rhs = argument } } });
            }
            return joined;
        }

        /// The text methods (RFC-0069). Every failable one is an ordinary `demand` in front of
        /// a pure operation, as `Items[I]` is, so rollback, traces and failure contexts are
        /// those of `Require`. The operation that follows a `demand` runs only when it held.
        fn emitTextMethod(self: *Self, method: TextMethod, receiver: u32, arguments: []const u32, span: Span) ParseError!u32 {
            const w = self.workspace;
            for (arguments) |argument| if (self.node(argument).value_type != .i64) return w.fail(self.node(argument).span, .type_mismatch);
            switch (method) {
                .slice => {
                    // `S.Slice[Start, End]`, or `S.Slice[Start]` up to the end of the string. The
                    // positions lie in `0..Length` in order, as for an array. A slice that is
                    // not empty must also be text: neither position may split an encoded scalar.
                    if (arguments.len == 0 or arguments.len > 2) return w.fail(span, .argument_count);
                    const start = arguments[0];
                    const length = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .string_length = receiver } });
                    var holds = try self.emitText(span, .logic, .boundary, .{ receiver, start, 0 });
                    const end = if (arguments.len == 2) arguments[1] else length;
                    if (arguments.len == 2) {
                        // A boundary is a position of the string, so only the empty slice needs its range checked.
                        holds = try self.emitBoth(span, holds, try self.emitText(span, .logic, .boundary, .{ receiver, end, 0 }));
                        const empty = try self.emitBoth(span, try self.emitCompare(span, .equal, start, end), try self.emitCompare(span, .greater_equal, start, try self.emitInteger(span, 0)));
                        holds = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .logic_binary = .{ .op = .either, .lhs = holds, .rhs = try self.emitBoth(span, empty, try self.emitCompare(span, .less_equal, end, length)) } } });
                        holds = try self.emitBoth(span, holds, try self.emitCompare(span, .less_equal, start, end));
                    }
                    try self.emitDemand(span, holds);
                    return self.emitText(span, .string, .slice, .{ receiver, start, end });
                },
                .scalar_at => {
                    // The scalar value whose encoding starts at a position: inside the string
                    // and on a boundary.
                    if (arguments.len != 1) return w.fail(span, .argument_count);
                    const position = arguments[0];
                    const length = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .string_length = receiver } });
                    const inside = try self.emitCompare(span, .less, position, length);
                    try self.emitDemand(span, try self.emitBoth(span, try self.emitText(span, .logic, .boundary, .{ receiver, position, 0 }), inside));
                    return self.emitText(span, types.Type.char32, .scalar, .{ receiver, position, 0 });
                },
                .to_code_unit, .to_code_point => return self.emitText(span, .i64, .code, .{ receiver, 0, 0 }),
                .to_ascii_string => return self.emit(.{ .span = span, .value_type = .string, .kind = .{ .to_string = receiver } }),
                .to_ascii_char32 => {
                    // Only an ASCII code unit is a scalar value by itself.
                    const code = try self.emitText(span, .i64, .code, .{ receiver, 0, 0 });
                    try self.emitDemand(span, try self.emitCompare(span, .less, code, try self.emitInteger(span, 0x80)));
                    return self.emitText(span, types.Type.char32, .from_code, .{ code, 0, 0 });
                },
                .to_char => {
                    const lower = try self.emitCompare(span, .greater_equal, receiver, try self.emitInteger(span, 0));
                    const upper = try self.emitCompare(span, .less_equal, receiver, try self.emitInteger(span, 0xFF));
                    try self.emitDemand(span, try self.emitBoth(span, lower, upper));
                    return self.emitText(span, types.Type.char, .from_code, .{ receiver, 0, 0 });
                },
                .to_char32 => {
                    // A Unicode scalar value: up to U+10FFFF and not a surrogate.
                    const lower = try self.emitCompare(span, .greater_equal, receiver, try self.emitInteger(span, 0));
                    const upper = try self.emitCompare(span, .less_equal, receiver, try self.emitInteger(span, 0x10FFFF));
                    const below = try self.emitCompare(span, .less, receiver, try self.emitInteger(span, 0xD800));
                    const above = try self.emitCompare(span, .greater, receiver, try self.emitInteger(span, 0xDFFF));
                    const outside = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .logic_binary = .{ .op = .either, .lhs = below, .rhs = above } } });
                    try self.emitDemand(span, try self.emitBoth(span, try self.emitBoth(span, lower, upper), outside));
                    return self.emitText(span, types.Type.char32, .from_code, .{ receiver, 0, 0 });
                },
            }
        }

        fn remapNode(self: *Self, original: types.Node, start: u32, end: u32) ParseError!types.Node {
            const storage = &self.workspace.functions;
            var mapped = remap(original, &storage.mapping, start, end);
            if (original.kind == .call or original.kind == .recur or original.kind == .invoke or original.kind == .bind or original.kind == .event_notify) {
                const range = if (original.kind == .call) original.kind.call.arguments else if (original.kind == .invoke) original.kind.invoke.arguments else if (original.kind == .bind) original.kind.bind.arguments else if (original.kind == .event_notify) original.kind.event_notify.arguments else original.kind.recur;
                var arguments: [types.limits.parameters]u32 = undefined;
                const count = range.end - range.start;
                std.debug.assert(count <= arguments.len);
                for (self.workspace.functions.arguments[range.start..range.end], arguments[0..count]) |operand, *destination| destination.* = self.workspace.functions.mapping[operand];
                const target = try self.reserveArguments(arguments[0..count], original.span);
                if (original.kind == .call) mapped.kind.call.arguments = target else if (original.kind == .invoke) mapped.kind.invoke.arguments = target else if (original.kind == .bind) mapped.kind.bind.arguments = target else if (original.kind == .event_notify) mapped.kind.event_notify.arguments = target else mapped.kind = .{ .recur = target };
            }
            if (original.kind == .structured) {
                // The arms are in the argument pool, as a call's arguments (RFC-0082, P3.3).
                const range = original.kind.structured.arms;
                var arms: [types.limits.parameters]u32 = undefined;
                const count = range.end - range.start;
                std.debug.assert(count <= arms.len);
                for (self.workspace.functions.arguments[range.start..range.end], arms[0..count]) |operand, *destination| destination.* = self.workspace.functions.mapping[operand];
                mapped.kind.structured.arms = try self.reserveArguments(arms[0..count], original.span);
            }
            if (original.kind == .object_new) {
                const range = original.kind.object_new.arguments;
                var arguments: [types.limits.record_fields]u32 = undefined;
                const count = range.end - range.start;
                std.debug.assert(count <= arguments.len);
                for (self.workspace.functions.arguments[range.start..range.end], arguments[0..count]) |operand, *destination| destination.* = self.workspace.functions.mapping[operand];
                mapped.kind = .{ .object_new = .{ .arguments = try self.reserveArguments(arguments[0..count], original.span) } };
            }
            if (original.kind == .aggregate) {
                const source = original.kind.aggregate;
                std.debug.assert(source.start <= source.end and (source.end <= storage.member_count or source.start >= storage.member_top));
                const target = try self.reserveMembers(source.end - source.start, original.span);
                const pool = self.memberPool();
                for (storage.members[source.start..source.end], pool[target.start..target.end]) |operand, *destination| {
                    std.debug.assert(operand >= start and operand < end);
                    destination.* = storage.mapping[operand];
                }
                mapped.kind = .{ .aggregate = target };
            }
            return mapped;
        }

        /// `Maybe?` yields the value of an option and fails when it is empty.
        fn unwrapOption(self: *Self, token: Token) ParseError!void {
            const w = self.workspace;
            const value = w.operands[self.operand_count - 1];
            const shape = catalogue.definition(self.node(value).value_type, self.definitions()) orelse return w.fail(token.span, .type_mismatch);
            if (shape != .option) return w.fail(token.span, .type_mismatch);
            if (!self.failureContext()) return w.fail(token.span, .failure_context_required);
            const present = try self.emit(.{ .span = token.span, .value_type = .logic, .kind = .{ .option_present = value } });
            _ = try self.emit(.{ .span = token.span, .value_type = .logic, .kind = .{ .demand = present } });
            w.operands[self.operand_count - 1] = try self.emit(.{ .span = token.span, .value_type = shape.option, .kind = .{ .option_value = value } });
        }

        fn accessValue(self: *Self, open: Token) ParseError!bool {
            const w = self.workspace;
            std.debug.assert(self.operand_count > 0);
            const value = w.operands[self.operand_count - 1];
            if (self.node(value).value_type == .string and open.kind == .left_bracket) {
                // `S[I]`: the code unit at a byte position, failing outside the string.
                if (!self.failureContext()) return w.fail(open.span, .failure_context_required);
                self.operand_count -= 1;
                try self.pushOperator(.{ .kind = .index, .span = open.span, .function = value, .operand_base = self.operand_count, .selected = 1 });
                return true;
            }
            const definition = catalogue.definition(self.node(value).value_type, self.definitions()) orelse return w.fail(open.span, .not_callable);
            if (open.kind == .left_bracket) if (self.metatypeOf(self.node(value).value_type)) |meta| return self.startTypeCast(value, meta, open);
            if (definition == .callable) {
                const shape = definition.callable;
                if ((open.kind == .left_bracket) != shape.decides) return w.fail(open.span, .expected_call);
                try self.callEffect(open.span, shape.effects());
                if (shape.decides and !self.failureContext()) return w.fail(open.span, .failure_context_required);
                self.operand_count -= 1;
                try self.pushOperator(.{ .kind = .invoke, .span = open.span, .function = value, .operand_base = self.operand_count, .selected = if (shape.decides) 1 else no_member });
                return true;
            }
            // RFC-0087, W2: `W[K]` on a `weak_map` is a map's lookup.
            if ((definition == .array or definition == .map or definition == .weak_map) and open.kind == .left_bracket) {
                if (!self.failureContext()) return w.fail(open.span, .failure_context_required);
                self.operand_count -= 1;
                try self.pushOperator(.{ .kind = .index, .span = open.span, .function = value, .operand_base = self.operand_count, .selected = 1 });
                return true;
            }
            if (definition != .tuple or open.kind != .left_paren) return w.fail(open.span, .not_callable);
            const token = try self.take(.integer, .expected_tuple_index);
            const index = std.fmt.parseInt(u32, token.span.text(w.source), 10) catch return w.fail(token.span, .tuple_index);
            const element = catalogue.tupleElementAt(self.node(value).value_type, index, self.definitions(), w.catalogue.tuple_elements[0..w.catalogue.tuple_count]) orelse return w.fail(token.span, .tuple_index);
            const close = try self.take(.right_paren, .expected_tuple_index);
            w.operands[self.operand_count - 1] = try self.emit(.{ .span = .{ .start = open.span.start, .end = close.span.end }, .value_type = element, .kind = .{ .tuple_element = .{ .value = value, .index = index } } });
            return false;
        }

        fn parseParameters(self: *Self, function: *functions.Definition, comptime defaults: Defaults) ParseError!void {
            const w = self.workspace;
            self.skipNewlines();
            if (self.peek().kind == .right_paren) {
                self.cursor += 1;
                return;
            }
            while (true) {
                // RFC-0085, I8: `(:accessor)`, the unnamed parameter of a getter or a setter, in a
                // method only and of that type only. Its name is empty: no body can name it.
                if (self.peek().kind == .colon and function.is_method) {
                    const colon = self.peek();
                    if (function.parameter_count == function.parameters.len) return w.fail(colon.span, .parameter_limit);
                    const value_type = try self.parseType();
                    if (w.standardAccessor() != value_type) return w.fail(colon.span, .expected_parameter);
                    function.parameters[function.parameter_count] = .{ .name = .{ .start = colon.span.start, .end = colon.span.start }, .value_type = value_type };
                    function.defaults[function.parameter_count] = .{};
                    function.parameter_count += 1;
                    self.skipNewlines();
                    if (self.peek().kind == .right_paren) {
                        self.cursor += 1;
                        return;
                    }
                    _ = try self.take(.comma, .expected_parameter);
                    self.skipNewlines();
                    continue;
                }
                // RFC-0091 (B3): `(A:T, B:U)` or `(A, B):tuple(T, U)` destructures a tuple.
                if (self.peek().kind == .left_paren) {
                    try self.patternParameter(function);
                    self.skipNewlines();
                    if (self.peek().kind == .right_paren) {
                        self.cursor += 1;
                        return;
                    }
                    _ = try self.take(.comma, .expected_parameter);
                    self.skipNewlines();
                    continue;
                }
                const name = try self.take(.identifier, .expected_parameter);
                if (reserved(name.span.text(w.source)) or (generatedName(name.span.text(w.source)) and w.libraryModule(name.span) == null)) return w.fail(name.span, .expected_parameter);
                if (function.parameter_count == function.parameters.len) return w.fail(name.span, .parameter_limit);
                if (self.patternNamed(function.*, name.span.text(w.source))) return w.fail(name.span, .duplicate_name);
                for (function.parameters[0..function.parameter_count]) |entry| {
                    if (std.mem.eql(u8, entry.name.text(w.source), name.span.text(w.source))) return w.fail(name.span, .duplicate_name);
                }
                // A function is visible in its own body under its name (an extension method only after a receiver).
                if (!function.anonymous and !function.is_extension and std.mem.eql(u8, function.name.text(w.source), name.span.text(w.source))) return self.failShadowed(name.span, function.name);
                // The signature of a named or generic function is read where no function of its
                // own is current; only an `Fn` stands inside the function that writes it.
                try self.checkShadow(name, function.anonymous);
                if (w.qualify) try self.noteParameter(function.*, name);
                const value_type = try self.parseType();
                function.parameters[function.parameter_count] = .{ .name = name.span, .value_type = value_type };
                function.defaults[function.parameter_count] = .{};
                if (self.peek().kind == .equal) {
                    switch (defaults) {
                        .none => return w.fail(self.peek().span, .unexpected_token),
                        .parse => function.defaults[function.parameter_count] = try self.parseDefaultOf(name, value_type, function),
                        .nested => function.defaults[function.parameter_count] = try self.nestedDefault(name, value_type, function),
                        .skip => {
                            // The default ends at the comma or parenthesis that ends its parameter.
                            var depth: u32 = 0;
                            while (true) : (self.cursor += 1) switch (self.peek().kind) {
                                .eof => return w.fail(self.peek().span, .expected_parameter),
                                .left_paren, .left_bracket, .left_brace => depth += 1,
                                .right_bracket, .right_brace => depth -|= 1,
                                .right_paren => if (depth == 0) break else {
                                    depth -= 1;
                                },
                                .comma => if (depth == 0) break,
                                else => {},
                            };
                        },
                    }
                }
                function.parameter_count += 1;
                self.skipNewlines();
                if (self.peek().kind == .right_paren) {
                    self.cursor += 1;
                    return;
                }
                _ = try self.take(.comma, .expected_parameter);
                self.skipNewlines();
            }
        }

        /// RFC-0091 (B3): a destructured parameter. The parameter has no name a body can write
        /// (it is empty, as the accessor's is) and the pattern's tuple type; its names are
        /// recorded in `Workspace.patterns` and bound as locals where the body begins.
        fn patternParameter(self: *Self, function: *functions.Definition) ParseError!void {
            const w = self.workspace;
            const open = self.peek();
            if (function.is_constructor) return w.fail(open.span, .parameter_pattern);
            if (function.parameter_count == function.parameters.len) return w.fail(open.span, .parameter_limit);
            if (function.patterns.start == function.patterns.end) function.patterns = .{ .start = w.pattern_count, .end = w.pattern_count };
            // A default would be read by callers before the body that destructures it.
            const value_type = try self.parsePattern(function, true, null, no_member, function.parameter_count, 0);
            function.patterns.end = w.pattern_count;
            if (self.peek().kind == .equal) return w.fail(self.peek().span, .parameter_pattern);
            function.parameters[function.parameter_count] = .{ .name = .{ .start = open.span.start, .end = open.span.start }, .value_type = value_type };
            function.defaults[function.parameter_count] = .{};
            function.parameter_count += 1;
        }

        /// Whether a name of a pattern of `function` read so far is `name`.
        fn patternNamed(self: *const Self, function: functions.Definition, name: []const u8) bool {
            const w = self.workspace;
            const range = function.patterns;
            if (range.start == range.end) return false;
            for (w.patterns[range.start..@min(range.end, w.pattern_count)]) |entry| {
                if (entry.name.start != entry.name.end and std.mem.eql(u8, entry.name.text(w.source), name)) return true;
            }
            return false;
        }

        /// The pattern at the cursor, `(` elements `)` with an optional `:Type` after it, and its
        /// type. `expected` is the type an enclosing pattern's annotation gives it; then neither
        /// it nor its names write a type. With `record` its entries are appended to the pool,
        /// under `parent`; without, the header of a later function is only being read.
        fn parsePattern(self: *Self, function: *functions.Definition, record: bool, expected: ?types.Type, parent: u32, position: u32, index: u32) ParseError!types.Type {
            const w = self.workspace;
            const open = try self.take(.left_paren, .expected_parameter);
            const first = self.cursor;
            const after = self.stdAfterBracket(first - 1) orelse return w.fail(open.span, .unmatched_parenthesis);
            var resume_at = after;
            var shape = expected;
            // The annotation after the pattern is read first: it gives the names their types.
            if (after < w.token_count and w.tokens[after].kind == .colon) {
                if (expected != null) return w.fail(w.tokens[after].span, .parameter_pattern);
                self.cursor = @intCast(after);
                shape = try self.parseType();
                resume_at = self.cursor;
                self.cursor = first;
            }
            const elements: ?Span = if (shape) |t| blk: {
                const item = catalogue.definition(t, self.definitions()) orelse return w.fail(open.span, .parameter_pattern);
                if (item != .tuple) return w.fail(open.span, .parameter_pattern);
                break :blk item.tuple;
            } else null;
            const entry = w.pattern_count;
            if (record) {
                if (w.pattern_count == w.patterns.len) return w.fail(open.span, .local_binding_limit);
                w.patterns[entry] = .{ .parent = parent, .parameter = position, .index = index, .name = .{ .start = open.span.start, .end = open.span.start }, .value_type = .i64 };
                w.pattern_count += 1;
            }
            var types_of: [types.limits.tuple_arity]types.Type = undefined;
            var count: u32 = 0;
            while (true) {
                self.skipNewlines();
                const at = self.peek();
                if (count == types_of.len) return w.fail(at.span, .tuple_limit);
                const element_type: ?types.Type = if (elements) |range| blk: {
                    if (count >= range.end - range.start) return w.fail(at.span, .parameter_pattern);
                    break :blk w.catalogue.tuple_elements[range.start + count];
                } else null;
                if (at.kind == .left_paren) {
                    types_of[count] = try self.parsePattern(function, record, element_type, entry, position, count);
                } else {
                    const name = try self.take(.identifier, .expected_parameter);
                    const text = name.span.text(w.source);
                    if (reserved(text) or (generatedName(text) and w.libraryModule(name.span) == null)) return w.fail(name.span, .expected_parameter);
                    const value_type = if (self.peek().kind == .colon) typed: {
                        if (element_type != null) return w.fail(self.peek().span, .parameter_pattern);
                        break :typed try self.parseType();
                    } else element_type orelse return w.fail(name.span, .parameter_pattern);
                    if (record) {
                        for (function.parameters[0..function.parameter_count]) |p| if (std.mem.eql(u8, p.name.text(w.source), text)) return w.fail(name.span, .duplicate_name);
                        if (self.patternNamed(.{ .name = function.name, .value_type = .i64, .is_public = false, .start = 0, .end = 0, .root = 0, .patterns = .{ .start = function.patterns.start, .end = w.pattern_count } }, text)) return w.fail(name.span, .duplicate_name);
                        if (!function.anonymous and !function.is_extension and std.mem.eql(u8, function.name.text(w.source), text)) return self.failShadowed(name.span, function.name);
                        try self.checkShadow(name, function.anonymous);
                        if (w.qualify) w.noteDeclaration(name.span, .local, qualify.none);
                        if (w.pattern_count == w.patterns.len) return w.fail(name.span, .local_binding_limit);
                        w.patterns[w.pattern_count] = .{ .parent = entry, .parameter = position, .index = count, .name = name.span, .value_type = value_type };
                        w.pattern_count += 1;
                    }
                    types_of[count] = value_type;
                }
                count += 1;
                self.skipNewlines();
                if (self.peek().kind == .right_paren) {
                    self.cursor += 1;
                    break;
                }
                _ = try self.take(.comma, .expected_parameter);
            }
            if (count < 2) return w.fail(open.span, .parameter_pattern);
            const value_type = if (elements) |range| blk: {
                if (count != range.end - range.start) return w.fail(open.span, .parameter_pattern);
                break :blk shape.?;
            } else try self.internTuple(types_of[0..count], open.span);
            if (record) w.patterns[entry].value_type = value_type;
            self.cursor = @intCast(resume_at);
            return value_type;
        }

        /// Binds the names of `function`'s patterns as immutable locals at the start of its
        /// body: each pattern is read once, its parameter or an element of its parent, and each
        /// name is an element of its pattern. Returns the locals there were before.
        fn bindPatterns(self: *Self, function: functions.Definition) ParseError!u32 {
            const w = self.workspace;
            const before = w.local_count;
            const range = function.patterns;
            if (range.start == range.end) return before;
            std.debug.assert(range.end <= w.pattern_count);
            for (range.start..range.end) |index| {
                const entry = &w.patterns[index];
                const span = if (entry.name.start != entry.name.end) entry.name else function.name;
                entry.node = if (entry.parent == no_member)
                    try self.emitTemplate(.{ .node = .{ .span = span, .value_type = function.parameters[entry.parameter].value_type, .kind = .{ .integer = 0 } }, .input = .{ .parameter = entry.parameter } })
                else
                    try self.emit(.{ .span = span, .value_type = entry.value_type, .kind = .{ .tuple_element = .{ .value = w.patterns[entry.parent].node, .index = entry.index } } });
                if (entry.name.start == entry.name.end) continue;
                if (w.local_count == w.locals.len) return w.fail(entry.name, .local_binding_limit);
                w.locals[w.local_count] = .{ .name = entry.name, .node = entry.node };
                w.local_count += 1;
            }
            // What the body's own functions destructure is read after this.
            w.pattern_count = range.start;
            return before;
        }

        /// RFC-0085, I11: a parameter declares a local, except where a macro wrote the function:
        /// there a parameter named with the author's text hands a loop a local of the code
        /// around it, which it names.
        fn noteParameter(self: *Self, function: functions.Definition, name: Token) ParseError!void {
            if (std.mem.eql(u8, name.span.text(self.workspace.source), "Self")) return;
            if (self.workspace.libraryModule(function.name) != null and self.noteCarried(name)) return;
            self.workspace.noteDeclaration(name.span, .local, qualify.none);
        }
        /// Notes `name`, which a macro declares again to carry it, as the local or parameter of
        /// that name in reach; false if there is none.
        fn noteCarried(self: *Self, name: Token) bool {
            const w = self.workspace;
            const text = name.span.text(w.source);
            // A carrier of the carrier, written at the same place, is noted already.
            if (self.findLocal(text)) |index| {
                if (w.locals[index].name.start != name.span.start) w.noteName(name.span, w.locals[index].name.start, .local, qualify.none);
                return true;
            }
            if (self.function != null) if (self.parameter(text)) |index| {
                if (self.function.?.parameters[index].name.start != name.span.start) w.noteName(name.span, self.function.?.parameters[index].name.start, .local, qualify.none);
                return true;
            };
            return false;
        }
        fn skipNewlines(self: *Self) void {
            while (self.peek().kind == .newline) self.cursor += 1;
        }

        fn visible(self: *const Self, span: Span) bool {
            const context = self.generic orelse return true;
            return span.start < self.workspace.generic_templates[context.template].name.start;
        }
        /// Whether the body of a parametric type is being compiled. Like the body of a class it
        /// may name classes and parametric types declared after it: a class is declared before
        /// anything is parsed, and a template either has been declared by the time the type is
        /// instantiated or is an unknown name, so the meaning never depends on the place.
        fn typesVisible(self: *const Self) bool {
            const context = self.generic orelse return false;
            const template = self.workspace.generic_templates[context.template];
            // A generic method sees what the class around it sees (RFC-0081).
            if (template.kind == .method) return template.outer != no_member;
            return template.kind != .function;
        }
        /// RFC-0085, I11: where the type parameter `name` of the template being compiled, or of
        /// the parametric type around a generic method, is declared.
        fn typeParameterSpan(self: *const Self, name: []const u8) ?Span {
            const w = self.workspace;
            const context = self.generic orelse return null;
            const template = w.generic_templates[context.template];
            for (template.parameters[0..template.parameter_count]) |span| if (std.mem.eql(u8, name, span.text(w.source))) return span;
            if (context.instance == no_member) return null;
            const outer = w.generic_templates[w.instances[context.instance].template];
            for (outer.parameters[0..outer.parameter_count]) |span| if (std.mem.eql(u8, name, span.text(w.source))) return span;
            return null;
        }
        fn genericType(self: *const Self, name: []const u8) ?types.Type {
            const context = self.generic orelse return null;
            const template = self.workspace.generic_templates[context.template];
            for (template.parameters[0..template.parameter_count], 0..) |span, index| if (std.mem.eql(u8, name, span.text(self.workspace.source))) return if (template.effect_mask >> @intCast(index) & 1 == 0) context.arguments[index] else null;
            return self.outerType(context, name);
        }
        /// A parameter of the parametric type around a generic method (RFC-0081): the argument
        /// of the instantiation the method is compiled for.
        fn outerType(self: *const Self, context: GenericContext, name: []const u8) ?types.Type {
            const w = self.workspace;
            if (context.instance == no_member) return null;
            const instance = w.instances[context.instance];
            const outer = w.generic_templates[instance.template];
            const arguments = catalogue.definition(instance.arguments, self.definitions()).?.tuple;
            for (outer.parameters[0..outer.parameter_count], 0..) |span, index| if (std.mem.eql(u8, name, span.text(w.source))) return w.catalogue.tuple_elements[arguments.start + index];
            return null;
        }
        fn genericEffect(self: *const Self, name: []const u8) ?Effect {
            const context = self.generic orelse return null;
            const template = self.workspace.generic_templates[context.template];
            for (template.parameters[0..template.parameter_count], 0..) |span, index| if (std.mem.eql(u8, name, span.text(self.workspace.source))) {
                if (template.effect_mask >> @intCast(index) & 1 == 0) return null;
                return self.effectOf(context.arguments[index]);
            };
            return null;
        }
        fn genericParameter(self: *const Self, name: []const u8) bool {
            const context = self.generic orelse return false;
            const template = self.workspace.generic_templates[context.template];
            for (template.parameters[0..template.parameter_count]) |span| if (std.mem.eql(u8, name, span.text(self.workspace.source))) return true;
            return self.outerType(context, name) != null;
        }
        /// An effect argument is carried as the canonical function type with those
        /// effects, so specialization identity needs no additional type kind.
        fn effectWitness(self: *Self, effect: Effect, span: Span) ParseError!types.Type {
            const parameters = try self.internTuple(&.{.i64}, span);
            return self.internCallable(.{ .parameters = parameters, .result = .i64, .transacts = effect.transacts, .decides = effect.decides, .detail = effect.detail }, span);
        }
        fn effectOf(self: *const Self, witness: types.Type) Effect {
            const shape = catalogue.definition(witness, self.definitions()).?.callable;
            return .{ .transacts = shape.transacts, .decides = shape.decides, .detail = shape.detail };
        }
        /// Parses the effect of an implementation: `parseEffectIn` where nothing may claim to
        /// converge.
        fn parseEffect(self: *Self, code: Diagnostic.Code) ParseError!Effect {
            return self.parseEffectIn(code, false);
        }
        /// Parses the specifiers of a signature, `<word>` after `<word>` in any order (RFC-0078):
        /// one heap effect, which is `<computes>`, `<transacts>` or any of `<reads>`, `<writes>`,
        /// `<allocates>`; then `<decides>` or `<suspends>`, and `<converges>` where `converges`
        /// allows it. `<E>` alone names an enclosing effect parameter, which carries a whole set.
        fn parseEffectIn(self: *Self, code: Diagnostic.Code, converges: bool) ParseError!Effect {
            _ = try self.take(.less, code);
            const first = try self.take(.identifier, code);
            if (self.genericEffect(first.span.text(self.workspace.source))) |bound| {
                _ = try self.take(.greater, code);
                return bound;
            }
            return self.effectWords(first, code, converges, true);
        }
        /// The specifiers from `first` on. Its `>` is still to come when `closed` says the first
        /// word stands in brackets like the others; an effect argument writes it bare.
        fn effectWords(self: *Self, first: Token, code: Diagnostic.Code, converges: bool, closed: bool) ParseError!Effect {
            const w = self.workspace;
            var seen: u16 = 0;
            var token = first;
            var bracketed = closed;
            while (true) {
                const word = std.meta.stringToEnum(EffectWord, token.span.text(w.source)) orelse return w.fail(token.span, if (seen == 0) code else .unsupported_specifier);
                if (word == .converges and !converges) return w.fail(token.span, .converges_position);
                try self.addEffectWord(&seen, token, word);
                if (bracketed) _ = try self.take(.greater, code);
                bracketed = true;
                if (self.peek().kind != .less) break;
                _ = try self.take(.less, .unsupported_specifier);
                token = try self.take(.identifier, .unsupported_specifier);
            }
            return effectOfWords(seen) orelse w.fail(first.span, code);
        }
        /// One more specifier of the effect being read; `seen` has the words before it. Each
        /// effect is said once, the whole heap effect in one way, and a function that may fail
        /// does not suspend.
        fn addEffectWord(self: *Self, seen: *u16, token: Token, word: EffectWord) ParseError!void {
            const w = self.workspace;
            const exclusive = EffectWord.computes.bit() | EffectWord.transacts.bit();
            const additive = EffectWord.reads.bit() | EffectWord.writes.bit() | EffectWord.allocates.bit();
            if (seen.* & word.bit() != 0) return w.fail(token.span, .effect_specifier_repeated);
            if (word.bit() & exclusive != 0 and seen.* & (exclusive | additive) != 0) return w.fail(token.span, .effect_specifier_conflict);
            if (word.bit() & additive != 0 and seen.* & exclusive != 0) return w.fail(token.span, .effect_specifier_conflict);
            seen.* |= word.bit();
            const timed = EffectWord.decides.bit() | EffectWord.suspends.bit();
            if (seen.* & timed == timed) return w.fail(token.span, .decides_with_suspends);
        }
        /// Building an instance of `class` allocates it, and does what its class says building
        /// one does (RFC-0078): the effect the class states, and the effect of each block clause
        /// the new instance is handed to.
        fn constructionEffect(self: *Self, class: types.Type, span: Span) ParseError!void {
            const w = self.workspace;
            try self.stateEffect(span, .construction);
            const function = self.function orelse return;
            // RFC-0084, P4.2: building an instance of a class with live fields runs their guards
            // and writes the fields, which the builder says it may.
            const fields_of = catalogue.definition(class, self.definitions()).?.class.fields;
            for (w.field_live[fields_of.start..fields_of.end]) |is_live| if (is_live) {
                self.useEffect(.{ .reads = true, .writes = true, .diverges = false });
                const have = Effect.of(function).set();
                if (!have.reads) return self.effectFailure(span, .construction_requires_reads);
                if (!have.writes) return self.effectFailure(span, .construction_requires_writes);
                break;
            };
            const declared = w.class_effects[classIndex(class)];
            if (declared.stated) self.useEffect(declared.effect.set().heap());
            if (declared.stated) if (missingEffect(declared.effect.set().heap(), Effect.of(function).set(), required_codes)) |code| return w.fail(span, code);
            const range = w.class_blocks[classIndex(class)];
            // RFC-0085, I12: predicting code builds what its clauses predict.
            if (self.predicting()) for (w.block_calls[range.start..range.end]) |target| if (w.runtime_functions.definitions[target].effects().dictates) return w.fail(span, .construction_requires_dictates);
            for (w.block_calls[range.start..range.end]) |target| try self.callEffect(span, w.runtime_functions.definitions[target].effects());
        }
        /// B4 (RFC-0092): building a `struct<E>` needs `E`, the effect its declaration states
        /// for its construction (Book 13:724). A struct that states none is built anywhere, as before.
        fn structEffect(self: *Self, record: types.Type, span: Span) ParseError!void {
            const declared = self.workspace.class_effects[classIndex(record)];
            if (!declared.stated) return;
            const function = self.function orelse return;
            self.useEffect(declared.effect.set().heap());
            if (missingEffect(declared.effect.set().heap(), Effect.of(function).set(), struct_codes)) |code| return self.workspace.fail(span, code);
        }
        /// An effect argument of a generic call: the specifiers with the first one bare, as in
        /// `Apply[transacts<decides>, i64]`, or the name of an enclosing effect parameter.
        fn parseEffectArgument(self: *Self) ParseError!types.Type {
            const token = try self.take(.identifier, .expected_computes);
            const text = token.span.text(self.workspace.source);
            if (self.genericEffect(text)) |bound| return self.effectWitness(bound, token.span);
            // A value of a converging type is a native's, and natives are not values yet.
            return self.effectWitness(try self.effectWords(token, .expected_computes, false, false), token.span);
        }
        fn findGeneric(self: *const Self, name: []const u8, scope: Span) ?u32 {
            const w = self.workspace;
            // Asked for every name that is declared or read: the templates are indexed by name,
            // where reading them all each time cost the square of their number.
            while (w.generics_indexed < w.generic_count) : (w.generics_indexed += 1) {
                if (w.generic_table.crowded()) {
                    w.generic_table.grow(&w.generic_slots);
                    for (w.generic_templates[0..w.generics_indexed], 0..) |earlier, at| w.generic_table.enter(&w.generic_slots, name_index.hashName(0, earlier.name.text(w.source)), @intCast(at));
                }
                w.generic_table.enter(&w.generic_slots, name_index.hashName(0, w.generic_templates[w.generics_indexed].name.text(w.source)), w.generics_indexed);
            }
            var same = w.generic_table.walk(&w.generic_slots, name_index.hashName(0, name));
            // A generic method is a member of its class (RFC-0081), reached only through a value.
            const found: ?u32 = while (same.next()) |index| {
                const t = w.generic_templates[index];
                if (t.kind != .method and modules.contains(scope, t.name) and std.mem.eql(u8, name, t.name.text(w.source)) and modules.owned(scope, t.name, w.nestedModules())) break index;
            } else null;
            if (paired_scans) {
                const scanned: ?u32 = for (w.generic_templates[0..w.generic_count], 0..) |t, index| {
                    if (t.kind != .method and modules.contains(scope, t.name) and std.mem.eql(u8, name, t.name.text(w.source)) and modules.owned(scope, t.name, w.nestedModules())) break @intCast(index);
                } else null;
                std.debug.assert(found == scanned);
            }
            return found;
        }
        /// Returns whether the result was written `void`.
        fn genericSignature(self: *Self, definition: *functions.Definition) ParseError!bool {
            _ = try self.take(.left_paren, .expected_parameter);
            const t = self.workspace.generic_templates[self.generic.?.template];
            if (t.kind == .method) {
                // A generic method (RFC-0081) takes its receiver first, as every method does.
                definition.parameters[0] = .{ .name = Span.self_word, .value_type = self.methodReceiver(t) };
                definition.defaults[0] = .{};
                definition.parameter_count = 1;
                definition.is_method = true;
            }
            try self.parseParameters(definition, .none);
            // A method's specialization is named by its receiver's type and its own arguments.
            if (definition.parameter_count + t.parameter_count + @intFromBool(t.kind == .method) > types.limits.parameters) return self.workspace.fail(definition.name, .parameter_limit);
            for (definition.parameters[0..definition.parameter_count]) |entry| if (self.genericParameter(entry.name.text(self.workspace.source))) return self.workspace.fail(entry.name, .duplicate_name);
            const effect = try self.parseEffect(.expected_computes);
            definition.transacts = effect.transacts;
            definition.decides = effect.decides;
            definition.detail = effect.detail;
            // RFC-0085, V11: the result of each specialisation would be a design of its own.
            if (self.peek().kind == .colon and self.workspace.tokens[self.cursor + 1].kind == .equal) return self.workspace.fail(definition.name, if (t.kind == .method) .transparent_method else .transparent_generic);
            const result = try self.parseResultType();
            definition.value_type = result.value_type;
            // A generic method has no slot, so it has a body wherever it is declared (RFC-0081).
            if (t.kind == .method and self.peek().kind != .left_brace) return self.workspace.fail(definition.name, .generic_method_slot);
            _ = try self.take(.left_brace, .expected_expression);
            return result.discards;
        }
        /// The receiver of generic method `template` in the context being compiled: the class
        /// that declares it, or the instantiation of its parametric type that is being compiled.
        fn methodReceiver(self: *const Self, template: GenericTemplate) types.Type {
            if (template.outer == no_member) return template.receiver;
            const context = self.generic.?;
            std.debug.assert(context.instance != no_member);
            return self.workspace.instances[context.instance].value;
        }
        fn parseGenericDeclaration(self: *Self, name: Token, is_public: bool, method: ?GenericMethod) ParseError!void {
            const w = self.workspace;
            if (w.generic_count + w.functions.count == types.limits.functions) return w.fail(name.span, .function_limit);
            const id = w.generic_count;
            var template: GenericTemplate = .{ .name = name.span, .is_public = is_public, .header = 0, .end = 0, .source = name.span, .module = w.current_module, .nested = w.current_nested };
            // The class context a generic method is declared in: the instantiation being compiled.
            const around = self.generic;
            if (method) |declared| {
                template.kind = .method;
                template.receiver = declared.class;
                template.access = declared.access;
                template.outer = if (around) |context| context.template else no_member;
                w.noteDeclaration(name.span, .member, self.ownerOf(declared.class));
            }
            _ = try self.take(.left_bracket, .expected_parameter);
            self.skipNewlines();
            while (true) {
                const parameter_name = try self.take(.identifier, .expected_parameter);
                if (reserved(parameter_name.span.text(w.source)) or effectKeyword(parameter_name.span.text(w.source))) return w.fail(parameter_name.span, .expected_parameter);
                // A type parameter is no local (RFC-0083).
                if (w.localQualified(parameter_name.span.start)) return w.fail(parameter_name.span, .invalid_qualifier);
                if (template.parameter_count == types.limits.parameters) return w.fail(parameter_name.span, .parameter_limit);
                for (template.parameters[0..template.parameter_count]) |earlier| if (std.mem.eql(u8, earlier.text(w.source), parameter_name.span.text(w.source))) return w.fail(parameter_name.span, .duplicate_name);
                // RFC-0076 (D5): a type parameter is a declaration, checked where it is written
                // against the template's own name and what the scopes around it declared.
                if (!generatedName(parameter_name.span.text(w.source)) and w.libraryModule(parameter_name.span) == null) {
                    if (std.mem.eql(u8, name.span.text(w.source), parameter_name.span.text(w.source))) return self.failShadowed(parameter_name.span, name.span);
                    if (self.declaredOutside(parameter_name.span.text(w.source), parameter_name.span.start, w.currentScope())) return self.failShadowed(parameter_name.span, null);
                    // A generic method's parameters extend those of its parametric type (RFC-0081).
                    if (self.genericParameter(parameter_name.span.text(w.source))) return self.failShadowed(parameter_name.span, null);
                }
                template.parameters[template.parameter_count] = parameter_name.span;
                template.parameter_count += 1;
                w.noteDeclaration(parameter_name.span, .local, qualify.none);
                _ = try self.take(.colon, .expected_type);
                const meta = try self.take(.identifier, .expected_type);
                const kind = meta.span.text(w.source);
                if (MetaKind.named(kind) != null) {
                    // `T:subtype(Base)`: only `Base` and the types below it are arguments. The
                    // bound is a class or interface known here; it cannot name a parameter, not
                    // even one of the parametric type around a generic method (RFC-0081).
                    _ = try self.take(.left_paren, .expected_type);
                    self.skipNewlines();
                    self.generic = null;
                    const bound = self.parseTypeValue();
                    self.generic = around;
                    self.skipNewlines();
                    _ = try self.take(.right_paren, .expected_type);
                    const shape = catalogue.definition(try bound, self.definitions()) orelse return w.fail(meta.span, .unsupported_type);
                    if (shape != .class) return w.fail(meta.span, .unsupported_type);
                    const bit = @as(u32, 1) << @intCast(template.parameter_count - 1);
                    template.subtype_mask |= bit;
                    // `castable_subtype` and `concrete_subtype` (RFC-0081) ask for more of the
                    // argument than being below the bound: see `boundAdmits`.
                    if (std.mem.startsWith(u8, kind, "castable")) template.castable_mask |= bit;
                    if (std.mem.endsWith(u8, kind, "concrete_subtype")) template.concrete_mask |= bit;
                    template.bounds[template.parameter_count - 1] = try bound;
                } else if (std.mem.eql(u8, kind, "effect")) template.effect_mask |= @as(u32, 1) << @intCast(template.parameter_count - 1) else if (std.mem.eql(u8, kind, "comparable")) template.comparable_mask |= @as(u32, 1) << @intCast(template.parameter_count - 1) else if (!std.mem.eql(u8, kind, "type")) return w.fail(meta.span, .unsupported_type);
                self.skipNewlines();
                if (self.peek().kind == .right_bracket) break;
                _ = try self.take(.comma, .expected_parameter);
                self.skipNewlines();
            }
            self.cursor += 1;
            if (self.peek().kind == .colon and w.tokens[self.cursor + 1].kind == .equal) {
                if (method != null) return w.fail(self.peek().span, .unexpected_token);
                return self.parseTypeTemplate(id, template);
            }
            template.header = self.cursor;
            w.generic_templates[id] = template;
            const types_start = w.catalogue.count;
            const tuples_start = w.catalogue.tuple_count;
            var context: GenericContext = .{ .template = id, .instance = if (around) |outer| w.findInstance(outer.template, outer.arguments[0..w.generic_templates[outer.template].parameter_count]) orelse no_member else no_member };
            @memset(&context.arguments, .i64);
            for (0..template.parameter_count) |index| if (template.effect_mask >> @intCast(index) & 1 != 0) {
                context.arguments[index] = try self.effectWitness(.{}, name.span);
            };
            for (0..template.parameter_count) |index| if (template.subtype_mask >> @intCast(index) & 1 != 0) {
                context.arguments[index] = template.bounds[index];
            };
            self.generic = context;
            // On error the class context of a generic method is not needed any more.
            errdefer self.generic = around;
            var signature: functions.Definition = .{ .name = name.span, .value_type = undefined, .is_public = false, .start = 0, .end = 0, .root = 0 };
            // The catalogue is put back below, so this reading may not instantiate a type.
            self.trial = true;
            self.trial_public = bundled and is_public;
            self.trial_name = name.span;
            defer {
                self.trial = false;
                self.trial_public = false;
            }
            _ = try self.genericSignature(&signature);
            if (bundled and is_public and w.module_storage.nested_count != 0) {
                const privacy = catalogue.Privacy.create(self.definitions(), w.catalogue.tuple_elements[0..w.catalogue.tuple_count], w.module_storage.modules[0..w.module_storage.module_count], w.nestedModules()) orelse return w.fail(name.span, .type_limit);
                defer privacy.destroy();
                if (!privacy.admits(signature.value_type, name.span, true)) return w.fail(name.span, .private_type_escape);
                for (signature.parameters[0..signature.parameter_count]) |entry| if (!privacy.admits(entry.value_type, name.span, true)) return w.fail(entry.name, .private_type_escape);
            } else if (bundled and is_public) {
                var exposed: [types.limits.user_types]bool = undefined;
                catalogue.exportableTypes(self.definitions(), self.fields(), w.catalogue.tuple_elements[0..w.catalogue.tuple_count], &exposed);
                const admitted = exposed[0..w.catalogue.count];
                if (!catalogue.exportable(signature.value_type, admitted)) return w.fail(name.span, .private_type_escape);
                for (signature.parameters[0..signature.parameter_count]) |entry| if (!catalogue.exportable(entry.value_type, admitted)) return w.fail(entry.name, .private_type_escape);
            }
            self.generic = around;
            w.catalogue.count = types_start;
            w.catalogue.tuple_count = tuples_start;
            var closers: [types.limits.expression_depth]Token.Kind = undefined;
            closers[0] = .right_brace;
            // The body is compiled when the function is called (per specialization), and
            // checked for shadowing then. What its tokens alone show is checked here, so that
            // a function nobody calls is not exempt (`ShadowScan`).
            var scan: ShadowScan = .{ .owner = name.span, .type_parameters = template.parameters[0..template.parameter_count], .parameters = signature.parameters[0..signature.parameter_count], .depth = 1, .outer_type_parameters = method != null };
            scan.places[0] = .statements;
            scan.function_body[0] = false;
            var depth: usize = 1;
            self.skipNewlines();
            if (self.peek().kind == .right_brace) return w.fail(self.peek().span, .expected_expression);
            while (depth != 0) {
                const token = self.peek();
                self.cursor += 1;
                try scan.step(self, self.cursor - 1);
                switch (token.kind) {
                    .eof => return w.fail(token.span, .unexpected_token),
                    .left_paren, .left_bracket, .left_brace => {
                        if (depth == closers.len) return w.fail(token.span, .expression_limit);
                        closers[depth] = switch (token.kind) {
                            .left_paren => .right_paren,
                            .left_bracket => .right_bracket,
                            .left_brace => .right_brace,
                            else => unreachable,
                        };
                        depth += 1;
                    },
                    .right_paren, .right_bracket, .right_brace => {
                        if (token.kind != closers[depth - 1]) return w.fail(token.span, .unmatched_parenthesis);
                        depth -= 1;
                        if (depth == 0) template.source.end = token.span.end;
                    },
                    else => {},
                }
            }
            template.end = self.cursor;
            // A member of a class ends where the next one starts, or where the class does.
            const member_end = method != null and (self.peek().kind == .comma or self.peek().kind == .right_brace);
            if (self.peek().kind != .eof and self.peek().kind != .newline and self.peek().kind != .separator and !member_end) return w.fail(self.peek().span, .unexpected_token);
            w.generic_templates[id] = template;
            w.generic_count += 1;
        }
        /// What an open bracket of a function body holds, as far as its tokens say: the
        /// statements of a block (`Block{`), the parameters of an `Fn`, or anything else:
        /// arguments, an archetype, a literal, the expression in the braces of an `Fn`.
        /// `members` is the body of a parametric type, read member by member (`ShadowScan`).
        const BodyPlace = enum { statements, parameters, other, members };

        /// The names that the body of a template declares, as far as its tokens show
        /// (`bodyDeclaration`), checked where the template is declared and not only where it
        /// is instantiated (RFC-0076), so that a template nobody instantiates is not exempt.
        /// A name is checked as compiling the body checks it: against the template's name and
        /// type parameters, the parameters of the function, the names the body declared before
        /// it that are still visible there (an outer local, a parameter of an `Fn` around it,
        /// a local whose initialiser holds it), the member of a parametric type whose code it
        /// is (its method or field), and the scopes around the template. A name declared twice
        /// in one block, or twice in one parameter list, is `duplicate_name`, as compiling it
        /// says. Each token is read once, in order, as the caller reads it (`step`); no type is
        /// made. The copy of a `Defer` body sees only the names that stood where the `Defer`
        /// was written, so nothing in it is checked here: this finds less than compiling the
        /// body does, never something else (test "the body of a template is shadow-checked from
        /// its tokens as compiling it checks it").
        const ShadowScan = struct {
            owner: Span,
            type_parameters: []const Span,
            parameters: []const functions.Parameter = &.{},
            /// A parametric type: its body is read member by member.
            members: bool = false,
            /// A generic method (RFC-0081): the type parameters of the class around it are
            /// visible in its body too (`Parser.genericParameter`).
            outer_type_parameters: bool = false,
            /// Brackets open, and what each holds.
            depth: usize,
            places: [types.limits.expression_depth]BodyPlace = undefined,
            /// Names in `Workspace.shadow_names`, in the order they were declared.
            count: usize = 0,
            /// The depth of the copy of a `Defer` body being passed over.
            skip: ?usize = null,
            /// The member of a parametric type being read: its name, and the token of its
            /// parameter list when it is a method.
            member: ?Span = null,
            member_parameters: usize = std.math.maxInt(usize),
            member_start: bool = false,
            in_member_parameters: bool = false,
            /// The depth at which the parameters of an `Fn` closed, until its body opens.
            fn_waiting: ?usize = null,
            /// The bodies of `Fn`s open, and which open bracket is one.
            level: u32 = 0,
            function_body: [types.limits.expression_depth]bool = undefined,

            fn step(scan: *ShadowScan, parser: *Self, at: usize) ParseError!void {
                const w = parser.workspace;
                const token = w.tokens[at];
                if (scan.skip) |floor| {
                    switch (token.kind) {
                        .left_paren, .left_bracket, .left_brace => scan.depth += 1,
                        .right_paren, .right_bracket, .right_brace => {
                            scan.depth -|= 1;
                            if (scan.depth == floor) scan.skip = null;
                        },
                        else => {},
                    }
                    return;
                }
                switch (token.kind) {
                    .synthetic_defer => scan.skip = scan.depth,
                    .identifier => {
                        if (scan.members and scan.depth == 1 and scan.member_start) scan.readMember(w, at);
                        if (scan.depth != 0) if (parser.bodyDeclaration(at, scan.places[scan.depth - 1])) |declared| try scan.declare(parser, declared, scan.places[scan.depth - 1] == .parameters);
                    },
                    .left_paren, .left_bracket, .left_brace => {
                        var place = if (scan.members and scan.depth == 0) .members else parser.bodyPlace(at);
                        // The brace after the parameters of an `Fn`, also when an effect or a
                        // result type stands between them, is its body: an expression, a
                        // function of its own, in which its parameters are seen.
                        const opens_body = token.kind == .left_brace and scan.fn_waiting == scan.depth;
                        if (token.kind == .left_brace and scan.attach(w, scan.depth + 1)) place = .other;
                        if (opens_body) {
                            place = .other;
                            scan.fn_waiting = null;
                            scan.level += 1;
                        }
                        if (at == scan.member_parameters) {
                            place = .parameters;
                            scan.in_member_parameters = true;
                        }
                        // The caller refuses a bracket deeper than this.
                        if (scan.depth < scan.places.len) {
                            scan.places[scan.depth] = place;
                            scan.function_body[scan.depth] = opens_body;
                        }
                        scan.depth += 1;
                        if (place == .members) scan.member_start = true;
                    },
                    .right_paren, .right_bracket, .right_brace => {
                        if (scan.depth == 0) return;
                        const inside = scan.depth <= scan.places.len;
                        const closing = if (inside) scan.places[scan.depth - 1] else .other;
                        if (inside and scan.function_body[scan.depth - 1]) scan.level -= 1;
                        scan.depth -= 1;
                        if (closing == .parameters and !scan.in_member_parameters) scan.fn_waiting = scan.depth;
                        scan.close(w, closing);
                        if (closing == .members) scan.endMember(w);
                    },
                    .separator, .newline, .comma => {
                        if (scan.fn_waiting) |waiting| if (waiting >= scan.depth) {
                            scan.fn_waiting = null;
                        };
                        scan.endStatement(w, token.kind != .comma);
                        if (scan.members and scan.depth == 1) scan.endMember(w);
                    },
                    else => {},
                }
            }

            /// The member that starts at token `at`, the first of its line in the body of a
            /// parametric type: `Name(...)` is a method, `Name:type`, `var Name:type` a field,
            /// `Block{...}` a clause of no name. Specifiers may follow `var` and the name.
            fn readMember(scan: *ShadowScan, w: *const Workspace, at: usize) void {
                scan.member_start = false;
                var index = at;
                if (std.mem.eql(u8, w.tokens[index].span.text(w.source), "var")) index = specifiersAfter(w, index + 1);
                if (index >= w.token_count or w.tokens[index].kind != .identifier) return;
                if (std.mem.eql(u8, w.tokens[index].span.text(w.source), "Block")) return;
                scan.member = w.tokens[index].span;
                const after = specifiersAfter(w, index + 1);
                if (after < w.token_count and w.tokens[after].kind == .left_paren) scan.member_parameters = after;
            }
            fn specifiersAfter(w: *const Workspace, from: usize) usize {
                var index = from;
                while (index + 2 < w.token_count and w.tokens[index].kind == .less and w.tokens[index + 1].kind == .identifier and w.tokens[index + 2].kind == .greater) index += 3;
                return index;
            }
            fn endMember(scan: *ShadowScan, w: *Workspace) void {
                scan.member = null;
                scan.member_parameters = std.math.maxInt(usize);
                scan.in_member_parameters = false;
                scan.member_start = true;
                scan.keep(w, struct {
                    fn stays(entry: ShadowName, _: usize) bool {
                        return !entry.member;
                    }
                }.stays, 0);
            }

            /// Removes the names `stays` refuses, keeping the order of the others.
            fn keep(scan: *ShadowScan, w: *Workspace, comptime stays: fn (ShadowName, usize) bool, depth: usize) void {
                var kept: usize = 0;
                for (w.shadow_names[0..scan.count]) |entry| if (stays(entry, depth)) {
                    w.shadow_names[kept] = entry;
                    kept += 1;
                };
                scan.count = kept;
            }

            /// The parameters waiting for the brace at `depth` belong to it from now on.
            fn attach(scan: *ShadowScan, w: *Workspace, depth: usize) bool {
                var any = false;
                for (w.shadow_names[0..scan.count]) |*entry| if (entry.awaiting and entry.depth == depth) {
                    entry.awaiting = false;
                    any = true;
                };
                return any;
            }

            /// A bracket closed: what was declared inside it is out of sight, except the
            /// parameters of an `Fn`, which wait for the brace of its body, and those of a
            /// method, which stay for the rest of the member.
            fn close(scan: *ShadowScan, w: *Workspace, closing: BodyPlace) void {
                const inside = scan.depth + 1;
                if (closing == .parameters) for (w.shadow_names[0..scan.count]) |*entry| if (entry.depth == inside and entry.parameter and !entry.awaiting) {
                    if (scan.in_member_parameters) {
                        entry.member = true;
                        entry.depth = scan.depth;
                    } else entry.awaiting = true;
                };
                if (closing == .parameters) scan.in_member_parameters = false;
                scan.keep(w, struct {
                    fn stays(entry: ShadowName, depth: usize) bool {
                        return entry.depth <= depth or entry.awaiting or entry.member;
                    }
                }.stays, scan.depth);
            }

            /// A statement ends at this depth: its name is no longer being initialised, and
            /// parameters that found no body there are dropped.
            fn endStatement(scan: *ShadowScan, w: *Workspace, statement: bool) void {
                if (statement) for (w.shadow_names[0..scan.count]) |*entry| if (entry.depth == scan.depth) {
                    entry.pending = false;
                };
                scan.keep(w, struct {
                    fn stays(entry: ShadowName, depth: usize) bool {
                        return !(entry.awaiting and entry.depth == depth + 1);
                    }
                }.stays, scan.depth);
            }

            /// Checks the name `declared` declares and notes it. `parameter` says it is a
            /// parameter of an `Fn` or of a method.
            fn declare(scan: *ShadowScan, parser: *Self, declared: Token, is_parameter: bool) ParseError!void {
                const w = parser.workspace;
                const text = declared.span.text(w.source);
                if (generatedName(text) or w.libraryModule(declared.span) != null) return;
                if (std.mem.eql(u8, text, scan.owner.text(w.source))) return parser.failShadowed(declared.span, scan.owner);
                for (scan.type_parameters) |type_name| if (std.mem.eql(u8, text, type_name.text(w.source))) return parser.failShadowed(declared.span, type_name);
                // The receiver of a generic method is written `Self`, nowhere in the source.
                for (scan.parameters) |entry| if (std.mem.eql(u8, text, entry.name.text(w.source))) return parser.failShadowed(declared.span, if (entry.name.start == Span.self_word.start) null else entry.name);
                var index = scan.count;
                while (index != 0) {
                    index -= 1;
                    const entry = w.shadow_names[index];
                    if (entry.awaiting or !std.mem.eql(u8, text, entry.span.text(w.source))) continue;
                    // A name being initialised is not seen in the body of an `Fn` inside it.
                    if (entry.pending and entry.level != scan.level) continue;
                    // Twice in one block, or in one parameter list.
                    if (entry.depth == scan.depth and entry.parameter == is_parameter and !entry.member) return w.fail(declared.span, .duplicate_name);
                    return parser.failShadowed(declared.span, if (entry.pending) null else entry.span);
                }
                if (scan.member) |member| if (std.mem.eql(u8, text, member.text(w.source))) return parser.failShadowed(declared.span, member);
                // A local declared `(local:)Name` may share its name with what is outside (RFC-0083).
                if (!w.localQualified(declared.span.start) and parser.declaredOutside(text, declared.span.start, w.currentScope())) return parser.failShadowed(declared.span, null);
                if (scan.outer_type_parameters and parser.genericParameter(text)) return parser.failShadowed(declared.span, null);
                // A body that declares more names at once than a function may hold is refused
                // when it is compiled; the names past that are not checked here.
                if (scan.count == w.shadow_names.len) return;
                w.shadow_names[scan.count] = .{ .span = declared.span, .depth = scan.depth, .parameter = is_parameter, .pending = !is_parameter, .level = scan.level };
                scan.count += 1;
            }
        };

        fn bodyPlace(self: *const Self, open: usize) BodyPlace {
            const w = self.workspace;
            if (open == 0) return .other;
            const before = w.tokens[open - 1];
            return switch (w.tokens[open].kind) {
                // The braces of an `Fn` hold one expression: a declaration there is no statement.
                .left_brace => if (before.kind == .identifier and std.mem.eql(u8, before.span.text(w.source), "Block")) .statements else .other,
                .left_paren => if (before.kind == .identifier and std.mem.eql(u8, before.span.text(w.source), "Fn")) .parameters else .other,
                else => .other,
            };
        }

        /// The name that the identifier at token `at` of a function body declares, if the
        /// tokens alone show that it declares one: `Name:=`, `Name:type=` or `var Name` at the
        /// start of a statement, or a parameter of an `Fn`. Macros are expanded by now, so the
        /// names a `For`, an `If` or a destructuring binds have one of these forms. A named
        /// argument, a field of an archetype and a capture are no statements and are not
        /// found; a `var` of the library re-declares the local a loop carries and is none
        /// either. This finds less than compiling the body does, never something else.
        fn bodyDeclaration(self: *const Self, at: usize, place: BodyPlace) ?Token {
            const w = self.workspace;
            if ((place != .statements and place != .parameters) or at == 0 or at + 1 >= w.token_count) return null;
            const token = w.tokens[at];
            const before = w.tokens[at - 1].kind;
            const after = w.tokens[at + 1];
            if (place == .parameters) return if ((before == .left_paren or before == .comma or before == .newline) and after.kind == .colon) token else null;
            if (before != .left_brace and before != .separator and before != .newline) return null;
            if (std.mem.eql(u8, token.span.text(w.source), "var")) return if (after.kind == .identifier and w.libraryModule(token.span) == null) after else null;
            return if (after.kind == .colon) token else null;
        }

        fn startGeneric(self: *Self, id: u32, name: Name, parentheses: u32) ParseError!bool {
            const w = self.workspace;
            const template = w.generic_templates[id];
            const own = self.generic != null and self.generic.?.template == id and self.function != null and std.meta.eql(self.function.?.name, template.name);
            if (!own and !self.visible(template.name)) return w.fail(name.span, .unknown_name);
            if (name.sealed() and !template.is_public) return w.fail(name.span, .private_name);
            _ = try self.take(.left_bracket, .expected_call);
            self.skipNewlines();
            var arguments: [types.limits.parameters]types.Type = undefined;
            var count: usize = 0;
            while (true) {
                if (count == arguments.len) return w.fail(name.span, .argument_count);
                arguments[count] = if (count < template.parameter_count and template.effect_mask >> @intCast(count) & 1 != 0) try self.parseEffectArgument() else try self.parseTypeValue();
                count += 1;
                self.skipNewlines();
                if (self.peek().kind == .right_bracket) break;
                _ = try self.take(.comma, .expected_type);
                self.skipNewlines();
            }
            self.cursor += 1;
            if (count != template.parameter_count) return w.fail(name.span, .argument_count);
            // The constraint is checked where the argument is written, before the body is expanded
            // for it, so the body may use `==` and map keys of the parameter freely.
            try self.checkTypeArguments(template, arguments[0..count], name.span);
            const key = try self.internTuple(arguments[0..count], name.span);
            if (own and self.function.?.specialization == key) {
                try self.pushOperand(try self.emit(.{ .span = name.span, .value_type = try self.functionType(self.function.?, name.span), .kind = .self_value }));
                return false;
            }
            if (w.findSpecialization(template.name, key)) |target| {
                const f = w.runtime_functions.definitions[target];
                var concrete: functions.Definition = .{ .name = f.name, .value_type = f.value_type, .is_public = false, .transacts = f.transacts, .decides = f.decides, .detail = f.detail, .parameter_count = f.parameter_count, .start = 0, .end = 0, .root = 0 };
                for (f.parameters[0..f.parameter_count], concrete.parameters[0..f.parameter_count]) |value_type, *entry| entry.* = .{ .name = f.name, .value_type = value_type };
                try self.pushOperand(try self.emit(.{ .span = name.span, .value_type = try self.functionType(concrete, name.span), .kind = .{ .function_value = @intCast(target) } }));
                return false;
            }
            try self.beginSpecialization(id, key, arguments, name.span, parentheses, self.cursor, 0);
            return true;
        }

        /// Starts compiling the specialization `key` of the generic function `id` for
        /// `arguments`: its body is read from its header, and the cursor goes back to
        /// `return_cursor` when it ends (`finishAnonymous`).
        fn beginSpecialization(self: *Self, id: u32, key: types.Type, arguments: [types.limits.parameters]types.Type, span: Span, parentheses: u32, return_cursor: u32, inferred: u32) ParseError!void {
            const w = self.workspace;
            const template = w.generic_templates[id];
            const name: struct { span: Span } = .{ .span = span };
            for (w.anonymous_frames[0..w.anonymous_count]) |frame| if (frame.kind == .generic and std.meta.eql(frame.definition.name, template.name) and frame.definition.specialization == key) return w.fail(name.span, .recursive_call);
            if (w.anonymous_count == w.anonymous_frames.len or w.runtime_functions.count == types.limits.functions) return w.fail(name.span, .function_limit);
            const work = template.end - template.header;
            if (work > types.limits.compiler_work - w.expansion_work) return w.fail(name.span, .compiler_work_limit);
            w.expansion_work += work;
            w.anonymous_frames[w.anonymous_count] = .{
                .kind = .generic,
                .return_cursor = return_cursor,
                .reference_span = name.span,
                .parent_module = w.current_module,
                .parent_nested = w.current_nested,
                .parent_generic = self.generic,
                .definition = .{ .name = template.name, .value_type = undefined, .is_public = false, .specialization = key, .generic_source = template.source, .template_public = template.is_public, .start = w.functions.node_count, .end = 0, .root = 0 },
                .parent_function = self.function,
                .parent_inferring = self.inferring,
                .expected_type = self.expected_type,
                .default_expression = self.default_expression,
                .control_depth = self.control_depth,
                .operator_base = self.operator_base,
                .operand_base = self.operand_base,
                .local_base = self.local_base,
                .parentheses = parentheses,
                .operators = self.operator_count,
                .operands = self.operand_count,
                .locals = w.local_count,
                .checkpoints = w.local_checkpoint_count,
                .failable_uses = w.failable_uses,
                .template_nodes = w.functions.node_count,
                .template_members = w.functions.member_count,
                .template_arguments = w.functions.argument_count,
                .staging = w.staging_count,
                .phase = .body,
                .inferred = inferred,
            };
            const frame = &w.anonymous_frames[w.anonymous_count];
            w.anonymous_count += 1;
            w.current_module = template.module;
            w.current_nested = template.nested;
            self.generic = .{ .template = id, .arguments = arguments, .specialization = key };
            // A generic function declares its own effect.
            self.inferring = null;
            self.cursor = template.header;
            var definition = frame.definition;
            frame.discards = try self.genericSignature(&definition);
            frame.definition = definition;
            self.operator_base = self.operator_count;
            self.operand_base = self.operand_count;
            self.local_base = w.local_count;
            self.function = definition;
            _ = try self.bindPatterns(definition);
            self.expected_type = if (frame.discards) null else definition.value_type;
            self.default_expression = false;
            self.control_depth = 0;
            self.skipNewlines();
        }

        /// RFC-0091 (B3): `Name(arguments)` of a generic function without its type arguments.
        /// The arguments are compiled first, on their own; when they close, the type arguments
        /// are read off their types (`closeInferred`), and the call is the call
        /// `Name[types](arguments)` would have been.
        fn startInferred(self: *Self, id: u32, name: Name) ParseError!void {
            const w = self.workspace;
            const template = w.generic_templates[id];
            std.debug.assert(template.kind == .function);
            const own = self.generic != null and self.generic.?.template == id and self.function != null and std.meta.eql(self.function.?.name, template.name);
            if (!own and !self.visible(template.name)) return w.fail(name.span, .unknown_name);
            if (name.sealed() and !template.is_public) return w.fail(name.span, .private_name);
            // An effect argument has no value to be read off.
            if (template.effect_mask != 0) return w.fail(name.span, .type_inference);
            _ = try self.take(.left_paren, .expected_call);
            try self.pushOperator(.{ .kind = .call, .span = name.span, .function = id, .operand_base = self.operand_count, .infer = true, .bound = self.templateArity(template) });
        }

        /// How many value parameters the header of `template` declares.
        fn templateArity(self: *const Self, template: GenericTemplate) u32 {
            const w = self.workspace;
            var at: usize = template.header + 1;
            if (w.tokens[at].kind == .right_paren) return 0;
            var depth: u32 = 0;
            var count: u32 = 1;
            while (at < template.end) : (at += 1) switch (w.tokens[at].kind) {
                .left_paren, .left_bracket, .left_brace => depth += 1,
                .right_paren, .right_bracket, .right_brace => {
                    if (depth == 0) return count;
                    depth -= 1;
                },
                .comma => if (depth == 0) {
                    count += 1;
                },
                else => {},
            };
            return count;
        }

        /// The type arguments that the argument types give the generic function `id`: each
        /// value parameter whose type names a type parameter is matched with its argument's
        /// type, structure by structure. Only the forms that name their parts (arrays, options,
        /// tuples, maps) are read through; a function type or an instantiation gives nothing.
        /// Every type parameter must be given one type, the same by every argument that gives
        /// it; otherwise the call is `type_inference`, and the type arguments are to be written.
        fn inferTypeArguments(self: *Self, id: u32, arguments: []const u32, span: Span, out: *[types.limits.parameters]types.Type) ParseError!void {
            const w = self.workspace;
            const template = w.generic_templates[id];
            var bound: [types.limits.parameters]?types.Type = @splat(null);
            var at: u32 = template.header + 1;
            for (arguments, 0..) |argument, ordinal| {
                if (w.tokens[at].kind == .left_paren) {
                    // A destructured parameter: its pattern is matched element by element.
                    at = try self.matchPattern(template, at, self.node(argument).value_type, &bound, span);
                } else {
                    // `Name:Type`, the parameter's type running to the comma or parenthesis after it.
                    if (w.tokens[at].kind != .identifier or w.tokens[at + 1].kind != .colon) return w.fail(span, .type_inference);
                    at += 2;
                    const end = self.typeEnd(at);
                    try self.matchWritten(template, at, end, self.node(argument).value_type, &bound, span);
                    at = end;
                }
                if (ordinal + 1 < arguments.len) {
                    if (w.tokens[at].kind != .comma) return w.fail(span, .argument_count);
                    at += 1;
                    while (w.tokens[at].kind == .newline) at += 1;
                }
            }
            for (bound[0..template.parameter_count], out[0..template.parameter_count]) |given, *argument| argument.* = given orelse return w.fail(span, .type_inference);
        }

        /// Matches the type written at `start..end` with `actual`, if it names a type parameter.
        fn matchWritten(self: *Self, template: GenericTemplate, start: u32, end: u32, actual: types.Type, bound: *[types.limits.parameters]?types.Type, span: Span) ParseError!void {
            if (!self.namesTypeParameter(template, start, end)) return;
            var cursor = start;
            try self.matchType(template, &cursor, end, actual, bound, span);
            if (cursor != end) return self.workspace.fail(span, .type_inference);
        }

        /// Matches the destructured parameter whose `(` is token `open` with `actual`: through
        /// its annotation, or through the types of its names and inner patterns, element by
        /// element. Returns the token after the pattern and its annotation.
        fn matchPattern(self: *Self, template: GenericTemplate, open: u32, actual: types.Type, bound: *[types.limits.parameters]?types.Type, span: Span) ParseError!u32 {
            const w = self.workspace;
            const after: u32 = @intCast(self.stdAfterBracket(open) orelse return w.fail(span, .type_inference));
            if (after < w.token_count and w.tokens[after].kind == .colon) {
                const end = self.typeEnd(after + 1);
                try self.matchWritten(template, after + 1, end, actual, bound, span);
                return end;
            }
            const item = catalogue.definition(actual, self.definitions()) orelse return w.fail(span, .type_mismatch);
            if (item != .tuple) return w.fail(span, .type_mismatch);
            const elements = w.catalogue.tuple_elements[item.tuple.start..item.tuple.end];
            var at = open + 1;
            var count: usize = 0;
            while (true) {
                while (w.tokens[at].kind == .newline) at += 1;
                if (at >= after - 1) break;
                if (count == elements.len) return w.fail(span, .type_mismatch);
                if (w.tokens[at].kind == .left_paren) {
                    at = try self.matchPattern(template, at, elements[count], bound, span);
                } else {
                    if (w.tokens[at].kind != .identifier or w.tokens[at + 1].kind != .colon) return w.fail(span, .type_inference);
                    const end = self.typeEnd(at + 2);
                    try self.matchWritten(template, at + 2, end, elements[count], bound, span);
                    at = end;
                }
                count += 1;
                while (w.tokens[at].kind == .newline) at += 1;
                if (w.tokens[at].kind == .comma) at += 1;
            }
            if (count != elements.len) return w.fail(span, .type_mismatch);
            return after;
        }

        /// The token after the type that starts at `at`: the first comma, `=` or closing
        /// parenthesis outside every bracket.
        fn typeEnd(self: *const Self, start: u32) u32 {
            const w = self.workspace;
            var at = start;
            var depth: u32 = 0;
            while (at < w.token_count) : (at += 1) switch (w.tokens[at].kind) {
                .left_paren, .left_bracket, .left_brace => depth += 1,
                .right_paren, .right_bracket, .right_brace => {
                    if (depth == 0) return at;
                    depth -= 1;
                },
                .comma, .equal, .newline => if (depth == 0) return at,
                .eof => return at,
                else => {},
            };
            return at;
        }

        /// Whether tokens `start..end` name a type parameter of `template`.
        fn namesTypeParameter(self: *const Self, template: GenericTemplate, start: u32, end: u32) bool {
            const w = self.workspace;
            for (w.tokens[start..end]) |token| if (token.kind == .identifier and self.typeParameterIndex(template, token) != null) return true;
            return false;
        }

        fn typeParameterIndex(self: *const Self, template: GenericTemplate, token: Token) ?usize {
            const w = self.workspace;
            for (template.parameters[0..template.parameter_count], 0..) |declared, index| {
                if (std.mem.eql(u8, declared.text(w.source), token.span.text(w.source))) return index;
            }
            return null;
        }

        /// Matches the type written at `cursor.*` (before `end`) with `actual`, binding the type
        /// parameters it names. A part that names none is not read: the call checks it.
        fn matchType(self: *Self, template: GenericTemplate, cursor: *u32, end: u32, actual: types.Type, bound: *[types.limits.parameters]?types.Type, span: Span) ParseError!void {
            const w = self.workspace;
            const start = cursor.*;
            const part_end = self.partEnd(start, end);
            if (!self.namesTypeParameter(template, start, part_end)) {
                cursor.* = part_end;
                return;
            }
            const token = w.tokens[start];
            const item = catalogue.definition(actual, self.definitions());
            if (token.kind == .identifier) {
                if (self.typeParameterIndex(template, token)) |index| {
                    if (start + 1 != part_end) {
                        cursor.* = part_end;
                        return;
                    }
                    if (bound[index]) |earlier| {
                        // The arguments disagree: exact types do not join (RFC-0067, D8).
                        if (earlier != actual) return w.fail(span, .type_inference);
                    } else bound[index] = actual;
                    cursor.* = part_end;
                    return;
                }
                const text = token.span.text(w.source);
                // Another form (a function type, an instantiation) gives nothing here: what it
                // names must come from other arguments, and the call checks it exactly.
                const form: enum { option, tuple, map } = if (std.mem.eql(u8, text, "option")) .option else if (std.mem.eql(u8, text, "tuple")) .tuple else if (std.mem.eql(u8, text, "map")) .map else {
                    cursor.* = part_end;
                    return;
                };
                if (w.tokens[start + 1].kind != .left_paren) {
                    cursor.* = part_end;
                    return;
                }
                cursor.* = start + 2;
                const close = part_end - 1;
                switch (form) {
                    .option => {
                        if (item == null or item.? != .option) return w.fail(span, .type_mismatch);
                        try self.matchType(template, cursor, close, item.?.option, bound, span);
                    },
                    .map => {
                        if (item == null or item.? != .map) return w.fail(span, .type_mismatch);
                        try self.matchType(template, cursor, close, item.?.map.key, bound, span);
                        if (w.tokens[cursor.*].kind != .comma) return w.fail(span, .type_inference);
                        cursor.* += 1;
                        try self.matchType(template, cursor, close, item.?.map.value, bound, span);
                    },
                    .tuple => {
                        if (item == null or item.? != .tuple) return w.fail(span, .type_mismatch);
                        const elements = w.catalogue.tuple_elements[item.?.tuple.start..item.?.tuple.end];
                        for (elements, 0..) |element, position| {
                            if (position != 0) {
                                if (w.tokens[cursor.*].kind != .comma) return w.fail(span, .type_mismatch);
                                cursor.* += 1;
                            }
                            if (cursor.* >= close) return w.fail(span, .type_mismatch);
                            try self.matchType(template, cursor, close, element, bound, span);
                        }
                    },
                }
                if (cursor.* != close) return w.fail(span, .type_mismatch);
                cursor.* = part_end;
                return;
            }
            if (token.kind == .left_bracket and w.tokens[start + 1].kind == .right_bracket) {
                // `[]T`.
                if (item == null or item.? != .array) return w.fail(span, .type_mismatch);
                cursor.* = start + 2;
                return self.matchType(template, cursor, end, item.?.array, bound, span);
            }
            // The type syntax has no `[K]V` or `?T` (they are `map(K,V)` and `option(T)`), so
            // no other prefix reaches here.
            cursor.* = part_end;
        }

        /// The token after the type that starts at `start`: a name with the arguments in
        /// parentheses after it, or the prefix `[]` and the type after that.
        fn partEnd(self: *const Self, start: u32, end: u32) u32 {
            const w = self.workspace;
            var at = start;
            while (at < end) {
                switch (w.tokens[at].kind) {
                    .left_bracket => {
                        const after = self.stdAfterBracket(at) orelse return end;
                        at = @intCast(after);
                    },
                    .identifier => {
                        at += 1;
                        // Effects of a function type, then its parenthesised parts.
                        while (at + 2 < end and w.tokens[at].kind == .less and w.tokens[at + 2].kind == .greater) at += 3;
                        if (at < end and w.tokens[at].kind == .left_paren) {
                            const after = self.stdAfterBracket(at) orelse return end;
                            at = @intCast(after);
                        }
                        return at;
                    },
                    else => return at + 1,
                }
            }
            return at;
        }

        /// The arguments of an inferred call have been read. The specialization they ask for is
        /// called with them: at once when it is published (or is the function being compiled),
        /// otherwise once its body, compiled from here, is (`finishInferred`).
        fn closeInferred(self: *Self, op: Operator, arguments: []const u32) ParseError!void {
            const w = self.workspace;
            const id = op.function;
            const template = w.generic_templates[id];
            if (arguments.len != op.bound) return w.fail(op.span, .argument_count);
            if (arguments.len == 0) return w.fail(op.span, .type_inference);
            var given: [types.limits.parameters]types.Type = undefined;
            try self.inferTypeArguments(id, arguments, op.span, &given);
            const count = template.parameter_count;
            try self.checkTypeArguments(template, given[0..count], op.span);
            const key = try self.internTuple(given[0..count], op.span);
            self.operator_count -= 1;
            const own = self.generic != null and self.generic.?.template == id and self.function != null and std.meta.eql(self.function.?.name, template.name) and self.function.?.specialization == key;
            const callee: ?u32 = if (own) try self.emit(.{ .span = op.span, .value_type = try self.functionType(self.function.?, op.span), .kind = .self_value }) else if (w.findSpecialization(template.name, key)) |target| published: {
                const f = w.runtime_functions.definitions[target];
                var concrete: functions.Definition = .{ .name = f.name, .value_type = f.value_type, .is_public = false, .transacts = f.transacts, .decides = f.decides, .detail = f.detail, .parameter_count = f.parameter_count, .start = 0, .end = 0, .root = 0 };
                for (f.parameters[0..f.parameter_count], concrete.parameters[0..f.parameter_count]) |value_type, *entry| entry.* = .{ .name = f.name, .value_type = value_type };
                break :published try self.emit(.{ .span = op.span, .value_type = try self.functionType(concrete, op.span), .kind = .{ .function_value = @intCast(target) } });
            } else null;
            if (callee) |value| {
                const call = try self.inferredCall(value, arguments, op.span);
                self.operand_count = op.operand_base;
                try self.pushOperand(call);
                return;
            }
            // The body is compiled from here, with the arguments waiting under it.
            try self.beginSpecialization(id, key, given, op.span, 0, self.cursor, @intCast(arguments.len));
            self.continued = true;
        }

        /// The specialization `callee` called with the arguments of an inferred call.
        fn inferredCall(self: *Self, callee: u32, arguments: []const u32, span: Span) ParseError!u32 {
            const w = self.workspace;
            const shape = catalogue.definition(self.node(callee).value_type, self.definitions()).?.callable;
            // A call that may fail is written with brackets, which name type arguments here.
            if (shape.decides) return w.fail(span, .type_inference);
            try self.callEffect(span, shape.effects());
            const parameters = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
            var ordered: [types.limits.parameters]u32 = undefined;
            std.debug.assert(arguments.len == parameters.end - parameters.start);
            for (arguments, w.catalogue.tuple_elements[parameters.start..parameters.end], ordered[0..arguments.len]) |argument, required, *slot| slot.* = try self.coerce(argument, required);
            const range = try self.reserveArguments(ordered[0..arguments.len], span);
            return self.checked(try self.emit(.{ .span = span, .value_type = shape.result, .kind = .{ .invoke = .{ .callable = callee, .arguments = range } } }));
        }

        /// The frame of an inferred call ends: the call of the published specialization takes
        /// the place of its arguments.
        fn finishInferred(self: *Self, frame: AnonymousFrame, callee: u32) ParseError!u32 {
            const count = frame.inferred;
            std.debug.assert(count > 0 and self.operand_count >= count);
            const arguments = self.workspace.operands[self.operand_count - count .. self.operand_count];
            const call = try self.inferredCall(callee, arguments, frame.reference_span);
            self.operand_count -= count;
            return call;
        }

        /// The bounds a template places on its type arguments, checked where they are given.
        fn checkTypeArguments(self: *Self, template: GenericTemplate, arguments: []const types.Type, span: Span) ParseError!void {
            const w = self.workspace;
            for (arguments, 0..) |argument, index| {
                if (template.comparable_mask >> @intCast(index) & 1 != 0 and !self.comparable(argument)) return w.fail(span, w.equalityCode(argument, .not_comparable));
                if (template.subtype_mask >> @intCast(index) & 1 != 0 and !catalogue.assignable(argument, template.bounds[index], self.definitions())) return w.fail(span, .type_argument_bound);
                // `castable_subtype` and `concrete_subtype` bounds (RFC-0081).
                if ((template.castable_mask | template.concrete_mask) >> @intCast(index) & 1 != 0) try self.boundAdmits(template, index, argument, span);
            }
        }

        /// `Name[T:type, ...] := class{...}` (or `interface`, `struct`) declares a parametric type
        /// (RFC-0073). Like a generic function it is kept as tokens: its body is compiled once
        /// for each list of type arguments it is named with (`instantiate`). The cursor is at `:=`.
        fn parseTypeTemplate(self: *Self, id: u32, declared: GenericTemplate) ParseError!void {
            const w = self.workspace;
            var template = declared;
            if (template.effect_mask != 0) return w.fail(template.name, .unsupported_type);
            // `char` in a type is the builtin wherever no type has the name, and a template is
            // not a type: one of that name could never be instantiated.
            if (Workspace.characterType(template.name.text(w.source)) != null) return w.fail(template.name, .expected_name);
            self.cursor += 2;
            const first = self.peek();
            const opens_body = first.kind == .identifier and w.tokens[self.cursor + 1].kind != .left_bracket and w.tokens[self.cursor + 1].kind != .dot and (std.mem.eql(u8, first.span.text(w.source), "class") or std.mem.eql(u8, first.span.text(w.source), "interface") or std.mem.eql(u8, first.span.text(w.source), "struct"));
            if (!opens_body) return self.parseAliasTemplate(id, template);
            const keyword = try self.take(.identifier, .unsupported_type);
            const word = keyword.span.text(w.source);
            template.kind = if (std.mem.eql(u8, word, "class")) .class else if (std.mem.eql(u8, word, "interface")) .interface else if (std.mem.eql(u8, word, "struct")) .record else return w.fail(keyword.span, .unsupported_type);
            template.header = self.cursor;
            // RFC-0087, P5.2 (T3, T4): saved data names its type, which a parameter leaves open.
            var ahead_at = self.cursor;
            while (ahead_at + 2 < w.token_count and w.tokens[ahead_at].kind == .less and w.tokens[ahead_at + 1].kind == .identifier and w.tokens[ahead_at + 2].kind == .greater) : (ahead_at += 3) {
                if (std.mem.eql(u8, w.tokens[ahead_at + 1].span.text(w.source), "persistable")) return w.fail(w.tokens[ahead_at + 1].span, .persistable_parametric);
            }
            // B8: the Book has no `<castable>` on a parametric class (10:2450, 10:2484): an
            // instantiation is no type value of a class bound (RFC-0081). A class below a
            // castable class may be parametric.
            ahead_at = self.cursor;
            while (template.kind == .class and ahead_at + 2 < w.token_count and w.tokens[ahead_at].kind == .less and w.tokens[ahead_at + 1].kind == .identifier and w.tokens[ahead_at + 2].kind == .greater) : (ahead_at += 3) {
                if (std.mem.eql(u8, w.tokens[ahead_at + 1].span.text(w.source), "castable")) return w.fail(w.tokens[ahead_at + 1].span, .castable_parametric);
            }
            var closers: [types.limits.expression_depth]Token.Kind = undefined;
            var depth: usize = 0;
            // The code of its members is compiled for each instantiation and checked for
            // shadowing then; what its tokens alone show is checked here (`ShadowScan`).
            var scan: ShadowScan = .{ .owner = template.name, .type_parameters = template.parameters[0..template.parameter_count], .members = true, .depth = 0 };
            while (true) {
                const token = self.peek();
                if (token.kind != .eof) try scan.step(self, self.cursor);
                switch (token.kind) {
                    .eof => return w.fail(token.span, .unexpected_token),
                    .newline, .separator => if (depth == 0) return w.fail(token.span, .unexpected_token),
                    .left_paren, .left_bracket, .left_brace => {
                        if (depth == closers.len) return w.fail(token.span, .expression_limit);
                        closers[depth] = switch (token.kind) {
                            .left_paren => .right_paren,
                            .left_bracket => .right_bracket,
                            .left_brace => .right_brace,
                            else => unreachable,
                        };
                        depth += 1;
                    },
                    .right_paren, .right_bracket, .right_brace => {
                        if (depth == 0 or token.kind != closers[depth - 1]) return w.fail(token.span, .unmatched_parenthesis);
                        depth -= 1;
                    },
                    else => {},
                }
                self.cursor += 1;
                // The brace that closes the body ends the declaration.
                if (depth == 0 and token.kind == .right_brace) {
                    template.source.end = token.span.end;
                    break;
                }
            }
            template.end = self.cursor;
            if (self.peek().kind != .eof and self.peek().kind != .newline and self.peek().kind != .separator) return w.fail(self.peek().span, .unexpected_token);
            w.generic_templates[id] = template;
            w.generic_count += 1;
        }

        /// `Name[T:type, ...] := type` (RFC-0083), the cursor at the type: a parametric alias.
        /// Each instantiation is the type the text names with the arguments in place of the
        /// parameters (`expandAlias`), which is a type the program could write itself, so there
        /// is no definition, origin or IR for it. The text is read once here, with placeholders
        /// as `checkTemplateTypes` reads a template, so that what it names is checked where it
        /// is written and a public alias names only what another module may name. Nothing it
        /// makes is kept.
        fn parseAliasTemplate(self: *Self, id: u32, declared: GenericTemplate) ParseError!void {
            const w = self.workspace;
            var template = declared;
            template.kind = .alias;
            template.header = self.cursor;
            const first = self.peek();
            var context: GenericContext = .{ .template = id };
            @memset(&context.arguments, .i64);
            for (0..template.parameter_count) |index| if (template.subtype_mask >> @intCast(index) & 1 != 0) {
                context.arguments[index] = template.bounds[index];
            };
            const types_start = w.catalogue.count;
            const tuples_start = w.catalogue.tuple_count;
            w.generic_templates[id] = template;
            const around = self.generic;
            const was_trial = self.trial;
            const was_public = self.trial_public;
            self.generic = context;
            self.trial = true;
            self.trial_public = bundled and template.is_public;
            self.trial_name = template.name;
            const read = self.parseTypeValue();
            const named: ParseError!usize = if (read) |value_type| (if (bundled and template.is_public) self.requireExported(&[_]struct { value_type: types.Type, span: Span }{.{ .value_type = value_type, .span = first.span }}) else @as(usize, 0)) else |err| err;
            self.generic = around;
            self.trial = was_trial;
            self.trial_public = was_public;
            w.catalogue.count = types_start;
            w.catalogue.tuple_count = tuples_start;
            _ = try named;
            template.end = self.cursor;
            template.source.end = w.tokens[self.cursor - 1].span.end;
            if (self.peek().kind != .eof and self.peek().kind != .newline and self.peek().kind != .separator) return w.fail(self.peek().span, .unexpected_token);
            w.generic_templates[id] = template;
            w.generic_count += 1;
        }

        /// The type the parametric alias `id` names for `arguments` (RFC-0083): its text, read
        /// where it is written with each parameter standing for its argument. The constraints
        /// of the parameters hold as they do for a parametric type. An alias names only aliases
        /// declared before it, so the reads nest at most as deep as aliases are declared; the
        /// depth is bounded all the same (`max_alias_depth`), since each one is a level of the
        /// native stack.
        fn expandAlias(self: *Self, id: u32, arguments: []const types.Type, span: Span) ParseError!types.Type {
            const w = self.workspace;
            const template = w.generic_templates[id];
            std.debug.assert(template.kind == .alias and arguments.len == template.parameter_count);
            // A signature read only to be checked makes no type, so an alias stands for any
            // type there, as a parametric type does (`instantiate`): reading it now would read
            // every alias it names, and those theirs.
            if (self.trial) return .i64;
            for (arguments, 0..) |argument, index| {
                if (template.comparable_mask >> @intCast(index) & 1 != 0 and !self.comparable(argument)) return w.fail(span, w.equalityCode(argument, .not_comparable));
                if (template.subtype_mask >> @intCast(index) & 1 != 0 and !catalogue.assignable(argument, template.bounds[index], self.definitions())) return w.fail(span, .type_argument_bound);
                if ((template.castable_mask | template.concrete_mask) >> @intCast(index) & 1 != 0) try self.boundAdmits(template, index, argument, span);
            }
            // Each list of arguments is read once and remembered: an alias naming others,
            // each named several times, would otherwise be read a number of times exponential
            // in the depth.
            const key = try self.internTuple(arguments, span);
            var same = w.alias_table.walk(&w.alias_slots, aliasHash(id, key));
            while (same.next()) |index| {
                if (index < w.alias_count and w.aliases[index].template == id and w.aliases[index].arguments == key) return w.aliases[index].value;
            }
            if (w.alias_count == w.aliases.len) return w.fail(span, .type_limit);
            if (w.alias_depth == max_alias_depth) return w.fail(span, .expression_limit);
            var context: GenericContext = .{ .template = id };
            @memset(&context.arguments, .i64);
            @memcpy(context.arguments[0..arguments.len], arguments);
            const saved_cursor = self.cursor;
            const saved_generic = self.generic;
            const saved_module = w.current_module;
            const saved_nested = w.current_nested;
            self.cursor = template.header;
            self.generic = context;
            w.current_module = template.module;
            w.current_nested = template.nested;
            w.alias_depth += 1;
            defer {
                w.alias_depth -= 1;
                self.cursor = saved_cursor;
                self.generic = saved_generic;
                w.current_module = saved_module;
                w.current_nested = saved_nested;
            }
            const value_type = try self.parseTypeValue();
            std.debug.assert(self.cursor == template.end);
            // Nested reads may have remembered others since the search above.
            const index = w.alias_count;
            if (index == w.aliases.len) return w.fail(span, .type_limit);
            w.aliases[index] = .{ .template = id, .arguments = key, .value = value_type };
            w.alias_count += 1;
            if (w.alias_table.crowded()) {
                w.alias_table.grow(&w.alias_slots);
                for (w.aliases[0..index], 0..) |earlier, at| w.alias_table.enter(&w.alias_slots, aliasHash(earlier.template, earlier.arguments), @intCast(at));
            }
            w.alias_table.enter(&w.alias_slots, aliasHash(id, key), index);
            return value_type;
        }

        fn aliasHash(id: u32, key: types.Type) u64 {
            return std.hash.Wyhash.hash(id, std.mem.asBytes(&key));
        }

        /// Reads the types a public parametric type names in its supertypes, fields and method
        /// signatures, with a placeholder for each parameter: all of them must be public, as
        /// `checkPublicApi` requires of a public class. Nothing is instantiated, and the
        /// catalogue is put back as it was. This runs when the whole bundle has been parsed,
        /// because a template may name types that are declared after it.
        fn checkTemplateTypes(self: *Self, id: u32) ParseError!void {
            const w = self.workspace;
            const template = w.generic_templates[id];
            const return_module = w.current_module;
            const return_nested = w.current_nested;
            w.current_module = template.module;
            w.current_nested = template.nested;
            const types_start = w.catalogue.count;
            const tuples_start = w.catalogue.tuple_count;
            const return_cursor = self.cursor;
            var context: GenericContext = .{ .template = id };
            @memset(&context.arguments, .i64);
            for (0..template.parameter_count) |index| if (template.subtype_mask >> @intCast(index) & 1 != 0) {
                context.arguments[index] = template.bounds[index];
            };
            self.generic = context;
            self.trial = true;
            self.trial_public = true;
            self.trial_name = template.name;
            defer {
                self.generic = null;
                self.trial = false;
                self.trial_public = false;
                self.cursor = return_cursor;
                w.current_module = return_module;
                w.current_nested = return_nested;
                w.catalogue.count = types_start;
                w.catalogue.tuple_count = tuples_start;
            }
            self.cursor = template.header;
            var named: [64]struct { value_type: types.Type, span: Span } = undefined;
            var count: usize = 0;
            while (self.peek().kind == .less) {
                _ = try self.take(.less, .unsupported_specifier);
                _ = try self.take(.identifier, .unsupported_specifier);
                _ = try self.take(.greater, .unsupported_specifier);
            }
            if (self.peek().kind == .left_paren) {
                self.cursor += 1;
                while (true) {
                    const parent = try self.take(.identifier, .expected_type);
                    if (count == named.len) count = try self.requireExported(named[0..count]);
                    named[count] = .{ .value_type = try self.namedType(try self.resolveTypeName(parent)), .span = parent.span };
                    count += 1;
                    if (self.peek().kind != .comma) break;
                    self.cursor += 1;
                }
                _ = try self.take(.right_paren, .unexpected_token);
            }
            _ = try self.take(.left_brace, .unexpected_token);
            self.skipNewlines();
            while (self.peek().kind != .right_brace) {
                if (template.kind != .record and self.methodAhead()) {
                    const signature = try self.parseMethodSignature(.i64, .skip);
                    const function = signature.function;
                    for (function.parameters[1..function.parameter_count]) |entry| {
                        if (count == named.len) count = try self.requireExported(named[0..count]);
                        named[count] = .{ .value_type = entry.value_type, .span = entry.name };
                        count += 1;
                    }
                    if (count == named.len) count = try self.requireExported(named[0..count]);
                    named[count] = .{ .value_type = function.value_type, .span = function.name };
                    count += 1;
                } else if (template.kind != .record and self.blockAhead()) {
                    // A `Block{...}` clause (RFC-0075) is code, compiled for each instantiation:
                    // it names no type that someone outside the module has to name.
                } else if (template.kind != .record and self.genericMethodAhead()) {
                    // A generic method (RFC-0081) names its own parameters; its declaration checks
                    // what its signature names, with the first instantiation.
                } else {
                    var field = try self.take(.identifier, .expected_field);
                    if (std.mem.eql(u8, field.span.text(w.source), "var")) {
                        // `var<private> Name<public>`: who may assign the field (RFC-0074).
                        if (self.peek().kind == .less) {
                            _ = try self.take(.less, .unsupported_specifier);
                            _ = try self.take(.identifier, .unsupported_specifier);
                            _ = try self.take(.greater, .unsupported_specifier);
                        }
                        field = try self.take(.identifier, .expected_field);
                    }
                    while (self.peek().kind == .less) {
                        _ = try self.take(.less, .unsupported_specifier);
                        _ = try self.take(.identifier, .unsupported_specifier);
                        _ = try self.take(.greater, .unsupported_specifier);
                    }
                    if (count == named.len) count = try self.requireExported(named[0..count]);
                    named[count] = .{ .value_type = try self.parseType(), .span = field.span };
                    count += 1;
                }
                try self.skipMember();
                if (self.peek().kind == .right_brace) break;
                self.cursor += 1;
                self.skipNewlines();
            }
            _ = try self.requireExported(named[0..count]);
        }

        /// Fails at the first of `named` whose type is not public; returns zero, the number left to check.
        /// Whether the public declaration whose signature is being read may name `template`.
        fn trialReaches(self: *const Self, template: GenericTemplate) bool {
            const w = self.workspace;
            if (!bundled or w.module_storage.nested_count == 0) return template.is_public;
            const privacy: catalogue.Privacy = .{ .modules = w.module_storage.modules[0..w.module_storage.module_count], .nested = w.nestedModules(), .reach = &.{} };
            return privacy.reaches(privacy.declared(template.name, template.is_public), self.trial_name);
        }

        fn requireExported(self: *Self, named: anytype) ParseError!usize {
            const w = self.workspace;
            if (named.len == 0) return 0;
            if (bundled and w.module_storage.nested_count != 0) {
                // The declaration being checked is used as far out as the modules around it
                // are public, and every type it names must be nameable there (RFC-0074).
                const privacy = catalogue.Privacy.create(self.definitions(), w.catalogue.tuple_elements[0..w.catalogue.tuple_count], w.module_storage.modules[0..w.module_storage.module_count], w.nestedModules()) orelse return w.fail(named[0].span, .scratch_unavailable);
                defer privacy.destroy();
                for (named) |entry| if (!privacy.admits(entry.value_type, self.trial_name, true)) return w.fail(entry.span, .private_type_escape);
                return 0;
            }
            // The table has a place for every type there can be; only the part in use is touched.
            const exposed = scratch.alloc(bool, types.limits.user_types) orelse return w.fail(named[0].span, .scratch_unavailable);
            defer scratch.free(exposed);
            catalogue.exportableTypes(self.definitions(), self.fields(), w.catalogue.tuple_elements[0..w.catalogue.tuple_count], exposed[0..types.limits.user_types]);
            for (named) |entry| if (!catalogue.exportable(entry.value_type, exposed[0..w.catalogue.count])) return w.fail(entry.span, .private_type_escape);
            return 0;
        }

        /// `Name[A, B]`, where `Name` is a parametric type and the cursor is after the name:
        /// reads the type arguments and returns the type they select.
        fn instantiateNamed(self: *Self, id: u32, name: Name) ParseError!types.Type {
            const w = self.workspace;
            const template = w.generic_templates[id];
            std.debug.assert(template.kind != .function);
            // Like every declaration, a template is seen from a generic function only if it was
            // declared before that function. The body of a parametric type sees every type,
            // itself included, as the body of a class does.
            if (!self.typesVisible() and !self.visible(template.name)) return w.fail(name.span, .unsupported_type);
            if (name.sealed() and !template.is_public) return w.fail(name.span, .private_name);
            if (self.trial_public and !self.trialReaches(template)) return w.fail(name.span, .private_type_escape);
            if (self.peek().kind != .left_bracket) return w.fail(name.span, .type_arguments_required);
            self.cursor += 1;
            self.skipNewlines();
            var arguments: [types.limits.parameters]types.Type = undefined;
            var count: usize = 0;
            while (true) {
                if (count == template.parameter_count) return w.fail(name.span, .argument_count);
                arguments[count] = try self.parseTypeValue();
                count += 1;
                self.skipNewlines();
                if (self.peek().kind == .right_bracket) break;
                _ = try self.take(.comma, .expected_type);
                self.skipNewlines();
            }
            self.cursor += 1;
            if (count != template.parameter_count) return w.fail(name.span, .argument_count);
            return self.instantiate(id, arguments[0..count], name.span);
        }

        /// What `instantiate` sets aside of the parse it interrupts. A parametric type is first
        /// named wherever a type can be written, which may be the middle of an expression in a
        /// function body; its own body is then compiled as the declaration it is, with every
        /// stack of the parser empty, and the interrupted parse is put back afterwards.
        const Suspended = struct {
            parser: Self,
            module: u32,
            /// The module of the file being compiled (RFC-0074).
            nested: u32,
            /// The archetype compiled last inside the function being compiled (RFC-0075).
            archetype_new: u32,
            archetype_end: u32,
            archetype_given: u32,
            failable_uses: u32,
            class_updates: u32,
            defer_barrier: bool,
            staged_fields: u32,
            staged_inherited: u32,
            template_nodes: u32,
            template_members: u32,
            template_arguments: u32,
            operators: []Operator = &.{},
            operands: []u32 = &.{},
            staging: []Member = &.{},
            locals: []Local = &.{},
            checkpoints: []LocalCheckpoint = &.{},
            frames: []AnonymousFrame = &.{},
            options: []Workspace.OptionCall = &.{},
            fields: []types.Field = &.{},
            defaults: []functions.Body = &.{},
            access: []Access = &.{},
            /// Who may assign each staged field and whether it is final (RFC-0074, RFC-0075).
            write: []Access = &.{},
            final: []bool = &.{},
            /// Whether each staged field is live (RFC-0084, P4.2).
            live: []bool = &.{},

            fn copy(comptime T: type, items: []const T) ?[]T {
                if (items.len == 0) return &.{};
                const result = scratch.alloc(T, items.len) orelse return null;
                @memcpy(result, items);
                return result;
            }

            fn take(parser: *Self) ?Suspended {
                const w = parser.workspace;
                var self: Suspended = .{
                    .parser = parser.*,
                    .module = w.current_module,
                    .nested = w.current_nested,
                    .archetype_new = w.archetype_new,
                    .archetype_end = w.archetype_end,
                    .archetype_given = w.archetype_given,
                    .failable_uses = w.failable_uses,
                    .class_updates = w.class_updates,
                    .defer_barrier = w.defer_barrier,
                    .staged_fields = w.staged_fields,
                    .staged_inherited = w.staged_inherited,
                    .template_nodes = w.functions.node_count,
                    .template_members = w.functions.member_count,
                    .template_arguments = w.functions.argument_count,
                };
                const first = w.catalogue.field_count;
                const staged = w.staged_inherited + w.staged_fields;
                const complete = complete: {
                    self.operators = copy(Operator, w.operators[0..parser.operator_count]) orelse break :complete false;
                    self.operands = copy(u32, w.operands[0..parser.operand_count]) orelse break :complete false;
                    self.staging = copy(Member, w.staging[0..w.staging_count]) orelse break :complete false;
                    self.locals = copy(Local, w.locals[0..w.local_count]) orelse break :complete false;
                    self.checkpoints = copy(LocalCheckpoint, w.local_checkpoints[0..w.local_checkpoint_count]) orelse break :complete false;
                    self.frames = copy(AnonymousFrame, w.anonymous_frames[0..w.anonymous_count]) orelse break :complete false;
                    self.options = copy(Workspace.OptionCall, w.option_open[0..w.option_open_count]) orelse break :complete false;
                    self.fields = copy(types.Field, w.record_fields[0..w.staged_fields]) orelse break :complete false;
                    self.defaults = copy(functions.Body, w.field_defaults[first..][0..staged]) orelse break :complete false;
                    self.access = copy(Access, w.field_access[first..][0..staged]) orelse break :complete false;
                    self.write = copy(Access, w.field_write[first..][0..staged]) orelse break :complete false;
                    self.final = copy(bool, w.field_final[first..][0..staged]) orelse break :complete false;
                    self.live = copy(bool, w.field_live[first..][0..staged]) orelse break :complete false;
                    break :complete true;
                };
                if (!complete) {
                    self.free();
                    return null;
                }
                return self;
            }

            /// Puts the interrupted parse back. The staged fields follow the catalogue's
            /// fields, which the instantiation has added to.
            fn restore(self: *const Suspended, parser: *Self) bool {
                const w = parser.workspace;
                const first = w.catalogue.field_count;
                if (self.defaults.len > w.field_defaults.len - first) return false;
                @memcpy(w.operators[0..self.operators.len], self.operators);
                @memcpy(w.operands[0..self.operands.len], self.operands);
                @memcpy(w.staging[0..self.staging.len], self.staging);
                @memcpy(w.locals[0..self.locals.len], self.locals);
                @memcpy(w.local_checkpoints[0..self.checkpoints.len], self.checkpoints);
                @memcpy(w.anonymous_frames[0..self.frames.len], self.frames);
                @memcpy(w.option_open[0..self.options.len], self.options);
                @memcpy(w.record_fields[0..self.fields.len], self.fields);
                @memcpy(w.field_defaults[first..][0..self.defaults.len], self.defaults);
                @memcpy(w.field_access[first..][0..self.access.len], self.access);
                @memcpy(w.field_write[first..][0..self.write.len], self.write);
                @memcpy(w.field_final[first..][0..self.final.len], self.final);
                @memcpy(w.field_live[first..][0..self.live.len], self.live);
                w.staging_count = @intCast(self.staging.len);
                w.local_count = @intCast(self.locals.len);
                w.local_checkpoint_count = @intCast(self.checkpoints.len);
                w.anonymous_count = @intCast(self.frames.len);
                w.option_open_count = @intCast(self.options.len);
                w.staged_fields = self.staged_fields;
                w.staged_inherited = self.staged_inherited;
                w.current_module = self.module;
                w.current_nested = self.nested;
                w.archetype_new = self.archetype_new;
                w.archetype_end = self.archetype_end;
                w.archetype_given = self.archetype_given;
                w.failable_uses = self.failable_uses;
                w.class_updates = self.class_updates;
                w.defer_barrier = self.defer_barrier;
                parser.* = self.parser;
                return true;
            }

            fn free(self: *const Suspended) void {
                scratch.free(self.operators);
                scratch.free(self.operands);
                scratch.free(self.staging);
                scratch.free(self.locals);
                scratch.free(self.checkpoints);
                scratch.free(self.frames);
                scratch.free(self.options);
                scratch.free(self.fields);
                scratch.free(self.defaults);
                scratch.free(self.access);
                scratch.free(self.write);
                scratch.free(self.final);
                scratch.free(self.live);
            }
        };

        /// Sets the interrupted parse aside and starts a clean one at `cursor` in `module`.
        fn interrupt(self: *Self, cursor: u32, module: u32, inner: u32, context: ?GenericContext, span: Span) ParseError!Suspended {
            const w = self.workspace;
            const suspended = Suspended.take(self) orelse return w.fail(span, .scratch_unavailable);
            self.* = .{ .workspace = w, .cursor = cursor, .generic = context };
            self.nested_floor = w.nested_count;
            w.staging_count = 0;
            w.local_count = 0;
            w.local_checkpoint_count = 0;
            w.anonymous_count = 0;
            w.option_open_count = 0;
            w.staged_fields = 0;
            w.staged_inherited = 0;
            w.defer_barrier = false;
            w.current_module = module;
            w.current_nested = inner;
            return suspended;
        }

        /// The type `template` makes for `arguments` (RFC-0073): each list of arguments is one
        /// type wherever it is named, and it is looked up without a search.
        ///
        /// A struct is made here and now. A class or an interface is made in two steps, as the
        /// declaration pre-pass and the declaration itself are two steps for a plain class:
        /// naming it reserves it, after the supertypes its header names (`reserveInstance`);
        /// its fields, signatures and bodies are compiled (`completeInstance`) at once where nothing is
        /// in the way, and otherwise as soon as that is so (`settle`). In the way are a class
        /// or struct that is still collecting its own fields and signatures, and a supertype
        /// whose declaration is still open. Until then the type is what a class declared
        /// further down is to the code above it: it can be named, and its members cannot be used.
        fn instantiate(self: *Self, id: u32, arguments: []const types.Type, span: Span) ParseError!types.Type {
            const w = self.workspace;
            const template = w.generic_templates[id];
            if (template.kind == .alias) return self.expandAlias(id, arguments, span);
            if (w.findInstance(id, arguments)) |existing| {
                if (!self.trial) try self.ensure(existing, span);
                return w.instances[existing].value;
            }
            if (self.trial) {
                // A signature that is only being checked makes no types: any type stands in.
                // What a public signature gives a parametric type must itself be public.
                if (self.trial_public) {
                    var named: [types.limits.parameters]struct { value_type: types.Type, span: Span } = undefined;
                    for (arguments, named[0..arguments.len]) |argument, *entry| entry.* = .{ .value_type = argument, .span = span };
                    _ = try self.requireExported(named[0..arguments.len]);
                }
                return .i64;
            }
            // A constraint is checked where the type is named, before anything is compiled for
            // the argument, so the body may rely on it.
            for (arguments, 0..) |argument, index| {
                if (template.comparable_mask >> @intCast(index) & 1 != 0 and !self.comparable(argument)) return w.fail(span, w.equalityCode(argument, .not_comparable));
                if (template.subtype_mask >> @intCast(index) & 1 != 0 and !catalogue.assignable(argument, template.bounds[index], self.definitions())) return w.fail(span, .type_argument_bound);
                // `castable_subtype` and `concrete_subtype` bounds (RFC-0081).
                if ((template.castable_mask | template.concrete_mask) >> @intCast(index) & 1 != 0) try self.boundAdmits(template, index, argument, span);
            }
            const key = try self.internTuple(arguments, span);
            // A type that is named again while its own header is read is among its supertypes.
            // A struct that is named again while it is being made would hold itself.
            for (w.instantiating[0..w.reserving_depth]) |open| {
                if (open.template == id and open.arguments == key) return w.fail(span, if (template.kind == .record) .unsupported_type else .invalid_parent);
            }
            if (w.instance_count == w.instances.len or w.catalogue.count == w.catalogue.definitions.len) return w.fail(span, .type_limit);
            // A body that names its own template with a larger argument each time never ends.
            const generation: u16 = if (w.instantiation_depth == 0) 0 else w.completing[w.instantiation_depth - 1] + 1;
            if (generation > types.limits.instantiation_depth) return w.fail(span, .instantiation_limit);
            if (template.kind == .record) return self.makeRecord(id, key, arguments, generation, span);
            const index = try self.reserveInstance(id, key, arguments, generation, span);
            try self.ensure(index, span);
            return w.instances[index].value;
        }

        /// Reads the supertypes a class header names, from the token after `class` or
        /// `interface` to the one before `{`. Naming them reserves those that are
        /// instantiations or classes that are declared late, so that they precede the class.
        /// What the header may say is checked when the class is compiled.
        fn readSupertypes(self: *Self, parents: *[1 + types.Class.max_interfaces]types.Type) ParseError!u8 {
            const w = self.workspace;
            var count: u8 = 0;
            while (self.peek().kind == .less) {
                _ = try self.take(.less, .unsupported_specifier);
                _ = try self.take(.identifier, .unsupported_specifier);
                _ = try self.take(.greater, .unsupported_specifier);
            }
            if (self.peek().kind != .left_paren) return 0;
            self.cursor += 1;
            while (true) {
                const parent = try self.take(.identifier, .expected_type);
                if (self.genericParameter(parent.span.text(w.source))) return w.fail(parent.span, .invalid_parent);
                if (count == parents.len) return w.fail(parent.span, .invalid_interface);
                parents[count] = try self.namedType(try self.resolveTypeName(parent));
                count += 1;
                if (self.peek().kind != .comma) break;
                self.cursor += 1;
            }
            _ = try self.take(.right_paren, .unexpected_token);
            return count;
        }

        /// Gives the instantiation of a parametric class or interface its place in the
        /// catalogue: after its supertypes, which reading its header reserves first.
        fn reserveInstance(self: *Self, id: u32, key: types.Type, arguments: []const types.Type, generation: u16, span: Span) ParseError!u32 {
            const w = self.workspace;
            const template = w.generic_templates[id];
            if (w.reserving_depth == w.instantiating.len) return w.fail(span, .instantiation_limit);
            var context: GenericContext = .{ .template = id, .specialization = key };
            @memcpy(context.arguments[0..arguments.len], arguments);
            const suspended = try self.interrupt(template.header, template.module, template.nested, context, span);
            defer suspended.free();
            w.instantiating[w.reserving_depth] = .{ .template = id, .arguments = key };
            w.reserving_depth += 1;
            var parents: [1 + types.Class.max_interfaces]types.Type = undefined;
            const count = try self.readSupertypes(&parents);
            w.reserving_depth -= 1;
            if (w.instance_count == w.instances.len) return w.fail(span, .type_limit);
            const class = w.catalogue.reserveInstance(template.name, key, template.is_public, w.source, w.scope()) catch |err| return w.fail(span, switch (err) {
                error.TypeLimit => .type_limit,
                error.InvalidName => .expected_name,
                error.InvalidType => .unsupported_type,
            });
            if (template.kind == .class and w.uniqueAhead(template.header)) w.catalogue.markUnique(class);
            const index = w.addInstance(id, key, class, generation, parents[0..count]);
            if (!suspended.restore(self)) return w.fail(span, .field_limit);
            return index;
        }

        /// Gives a class that is declared late (`Late`) its place in the catalogue before its
        /// declaration is reached, because a type above it names it: after its supertypes. It
        /// gets its fields where it is declared, like a class the pre-pass declared.
        fn reserveLate(self: *Self, entry: u32, span: Span) ParseError!types.Type {
            const w = self.workspace;
            const late = w.late[entry];
            std.debug.assert(late.kind == .class and late.declared == null);
            // Its own header names it: it would be among its own supertypes or their arguments.
            if (late.reserving) return w.fail(span, .unsupported_type);
            if (w.reserving_depth == w.instantiating.len) return w.fail(span, .instantiation_limit);
            const suspended = try self.interrupt(late.token + 1, late.module, late.nested, null, span);
            defer suspended.free();
            if (self.peek().kind == .less) self.cursor += 3;
            self.cursor += 3;
            const is_unique = w.uniqueAhead(self.cursor);
            w.late[entry].reserving = true;
            w.instantiating[w.reserving_depth] = .{ .template = std.math.maxInt(u32), .arguments = .i64 };
            w.reserving_depth += 1;
            var parents: [1 + types.Class.max_interfaces]types.Type = undefined;
            _ = try self.readSupertypes(&parents);
            w.reserving_depth -= 1;
            const class = w.catalogue.reserveClass(late.name, late.is_public, w.source, w.scope()) catch |err| return w.fail(span, switch (err) {
                error.TypeLimit => .type_limit,
                error.DuplicateName => .duplicate_name,
                error.InvalidName => .expected_name,
            });
            if (is_unique) w.catalogue.markUnique(class);
            w.late[entry].reserving = false;
            w.late[entry].declared = class;
            if (!suspended.restore(self)) return w.fail(span, .field_limit);
            return class;
        }

        /// The nominal type `text` names in `scope`: one the catalogue has, or a class that is
        /// declared late and is reserved now because it is named.
        fn findNominal(self: *Self, text: []const u8, scope: Span, span: Span) ParseError!?types.Type {
            const w = self.workspace;
            if (w.catalogue.findNamedIn(text, w.source, scope)) |found| return found;
            if (w.late_count == 0 or self.trial) return null;
            const entry = w.lateIn(text, w.scopeNamed(scope)) orelse return null;
            if (w.late[entry].kind != .class) return null;
            return try self.reserveLate(entry, span);
        }

        /// Completes the reserved instantiation `index` if nothing is in the way.
        fn ensure(self: *Self, index: u32, span: Span) ParseError!void {
            const w = self.workspace;
            // While a header is being read the type it belongs to has no place yet: what the
            // header names is completed once it has, so that their bodies can name it.
            if (w.instances[index].state != .reserved or w.declaring != 0 or w.reserving_depth != 0) return;
            if (!w.completable(index, 0)) return;
            try self.completeInstance(index, span);
        }

        /// Compiles the body of the reserved instantiation `index`: its supertypes first, then
        /// its fields, its signatures and its method bodies, as the declaration it is.
        fn completeInstance(self: *Self, index: u32, span: Span) ParseError!void {
            const w = self.workspace;
            if (w.instantiation_depth == w.completing.len) return w.fail(span, .instantiation_limit);
            var above: usize = 0;
            while (above < w.instances[index].parent_count) : (above += 1) {
                const parent = w.instanceOf(w.instances[index].parents[above]) orelse continue;
                if (w.instances[parent].state == .reserved) try self.completeInstance(parent, span);
            }
            // Completing a supertype settles what waited for it, which may have been this.
            if (w.instances[index].state != .reserved) return;
            const instance = w.instances[index];
            const template = w.generic_templates[instance.template];
            const work = template.end - template.header;
            if (work > types.limits.compiler_work - w.expansion_work) return w.fail(span, .compiler_work_limit);
            w.expansion_work += work;
            var context: GenericContext = .{ .template = instance.template, .specialization = instance.arguments };
            const list = catalogue.definition(instance.arguments, self.definitions()).?.tuple;
            @memcpy(context.arguments[0 .. list.end - list.start], w.catalogue.tuple_elements[list.start..list.end]);
            const suspended = try self.interrupt(template.header, template.module, template.nested, context, span);
            defer suspended.free();
            w.instances[index].state = .completing;
            w.completing[w.instantiation_depth] = instance.generation;
            w.instantiation_depth += 1;
            const value = try self.parseClassAs(.{ .kind = .identifier, .span = template.name }, template.kind == .interface, instance.arguments);
            std.debug.assert(value == instance.value and self.operator_count == self.operator_base and self.function == null and w.local_count == 0 and w.anonymous_count == 0);
            w.instantiation_depth -= 1;
            w.instances[index].state = .complete;
            // Method bodies are runtime functions by now and default values were moved to the
            // end of the template storage (`relocateDefault`), so what this type appended to
            // the storage is not read again: an interrupted body goes on where it stopped.
            w.functions.node_count = suspended.template_nodes;
            w.functions.member_count = suspended.template_members;
            w.functions.argument_count = suspended.template_arguments;
            if (!suspended.restore(self)) return w.fail(span, .field_limit);
            try self.settle(span);
        }

        /// Makes the instantiation of a parametric struct. A struct holds its fields by value,
        /// so they are earlier definitions and it has none of its own until they are all known.
        fn makeRecord(self: *Self, id: u32, key: types.Type, arguments: []const types.Type, generation: u16, span: Span) ParseError!types.Type {
            const w = self.workspace;
            const template = w.generic_templates[id];
            if (w.instantiation_depth == w.completing.len or w.reserving_depth == w.instantiating.len) return w.fail(span, .instantiation_limit);
            const work = template.end - template.header;
            if (work > types.limits.compiler_work - w.expansion_work) return w.fail(span, .compiler_work_limit);
            w.expansion_work += work;
            var context: GenericContext = .{ .template = id, .specialization = key };
            @memcpy(context.arguments[0..arguments.len], arguments);
            const suspended = try self.interrupt(template.header, template.module, template.nested, context, span);
            defer suspended.free();
            w.instantiating[w.reserving_depth] = .{ .template = id, .arguments = key };
            w.reserving_depth += 1;
            w.completing[w.instantiation_depth] = generation;
            w.instantiation_depth += 1;
            const value = try self.parseRecordAs(.{ .kind = .identifier, .span = template.name }, template.is_public, key);
            std.debug.assert(self.operator_count == self.operator_base and self.function == null and w.local_count == 0 and w.anonymous_count == 0);
            w.instantiation_depth -= 1;
            w.reserving_depth -= 1;
            w.functions.node_count = suspended.template_nodes;
            w.functions.member_count = suspended.template_members;
            w.functions.argument_count = suspended.template_arguments;
            if (!suspended.restore(self)) return w.fail(span, .field_limit);
            try self.settle(span);
            return value;
        }

        /// Completes the instantiations that were reserved while something was in their way and
        /// can be completed now, in the order they were named. When no declaration is open any
        /// more, every one of them can; one that still cannot then has a supertype that was never
        /// declared in time, which compiling it reports.
        fn settle(self: *Self, span: Span) ParseError!void {
            const w = self.workspace;
            if (w.declaring != 0) return;
            var index = w.settled;
            var contiguous = true;
            while (index < w.instance_count) : (index += 1) {
                if (w.instances[index].state == .reserved and (w.open_count == 0 or w.completable(index, 0))) try self.completeInstance(index, span);
                if (w.instances[index].state != .complete) contiguous = false;
                if (contiguous) w.settled = @max(w.settled, index + 1);
            }
        }

        /// What follows a parametric type named in an expression: `{` builds an instance of it
        /// and `[` casts a value to it.
        fn startInstanceForm(self: *Self, value_type: types.Type, span: Span) ParseError!void {
            const w = self.workspace;
            const item = catalogue.definition(value_type, self.definitions()) orelse return w.fail(span, .unknown_name);
            if (self.peek().kind == .left_bracket) {
                if (item != .class) return w.fail(span, .unknown_name);
                _ = try self.take(.left_bracket, .expected_call);
                try self.pushOperator(.{ .kind = .convert, .span = span, .function = @backingInt(Conversion.cast), .operand_base = self.operand_count, .selected = 1, .value_type = value_type });
                return;
            }
            if (self.peek().kind != .left_brace or (item != .record and item != .class)) return w.fail(span, .expected_call);
            // As for any class: built only once its declaration has given it fields. Where no
            // instance can be built at all, that is the diagnostic, as it is for a plain class.
            if (item == .class and catalogue.pendingClass(item.class)) {
                try self.stateEffect(span, .construction);
                return w.fail(span, .unknown_name);
            }
            // Only the body of a constructor function of an abstract class names it (RFC-0075).
            if (item == .class and item.class.is_abstract and !self.constructs(value_type)) return w.fail(span, .abstract_instance);
            // Its own block clauses are not all known yet, and would run for ever anyway.
            if (item == .class and self.blocksUnknown(value_type)) return w.fail(span, .construction_cycle);
            _ = try self.take(.left_brace, .unexpected_token);
            try self.pushOperator(.{ .kind = .record, .span = span, .operand_base = self.operand_count, .value_type = value_type });
            try self.selectField();
        }

        /// B4 (RFC-0092): the superclass `Super{...}` builds, in a method of a class that has one.
        /// Null where `Super` names nothing special: outside a method, or where the program
        /// declares a type, an alias or a template of that name, which keeps its meaning.
        fn superArchetype(self: *Self, resolved: Name) ParseError!?types.Type {
            const w = self.workspace;
            const f = self.function orelse return null;
            if (!f.is_method) return null;
            const class = self.method_class orelse return null;
            if (w.catalogue.findNamedIn("Super", w.source, resolved.scope) != null or w.findTypeAliasIn("Super", resolved.scope) != null or self.genericType("Super") != null or self.findGeneric("Super", resolved.scope) != null) return null;
            return catalogue.definition(class, self.definitions()).?.class.parent orelse w.fail(resolved.span, .invalid_parent);
        }

        /// Moves the default value just compiled, which ends the template storage, to the far
        /// end of it. The defaults of an instantiated type are read whenever the type is built,
        /// long after the function body in whose middle the type may have been made; there
        /// they would lie inside that body. `members` and `arguments` are where the pools stood
        /// before the default was compiled.
        fn relocateDefault(self: *Self, default: functions.Body, members: u32, arguments: u32, span: Span) ParseError!functions.Body {
            const w = self.workspace;
            const storage = &w.functions;
            std.debug.assert(default.end == storage.node_count and default.start < default.end);
            std.debug.assert(members <= storage.member_count and arguments <= storage.argument_count);
            const node_total = default.end - default.start;
            const member_total = storage.member_count - members;
            const argument_total = storage.argument_count - arguments;
            // The copy may not land on what it is copied from.
            if (node_total > storage.node_top - storage.node_count) return w.fail(span, .template_limit);
            if (member_total > storage.member_top - storage.member_count) return w.fail(span, .aggregate_limit);
            if (argument_total > storage.argument_top - storage.argument_count) return w.fail(span, .call_argument_limit);
            const node_base = storage.node_top - node_total;
            const member_base = storage.member_top - member_total;
            const argument_base = storage.argument_top - argument_total;
            const shift = node_base - default.start;
            for (default.start..default.end) |index| storage.mapping[index] = @intCast(index + shift);
            for (storage.nodes[default.start..default.end], storage.nodes[node_base..][0..node_total]) |original, *target| {
                target.* = original;
                if (original.input != .operation) continue;
                target.node = remap(original.node, &storage.mapping, default.start, default.end);
                switch (original.node.kind) {
                    .aggregate => |range| if (range.start != range.end) {
                        target.node.kind = .{ .aggregate = .{ .start = range.start - members + member_base, .end = range.end - members + member_base } };
                    },
                    .call => |c| target.node.kind.call.arguments = moved(c.arguments, arguments, argument_base),
                    .invoke => |c| target.node.kind.invoke.arguments = moved(c.arguments, arguments, argument_base),
                    .event_notify => |c| target.node.kind.event_notify.arguments = moved(c.arguments, arguments, argument_base),
                    .bind => |c| target.node.kind.bind.arguments = moved(c.arguments, arguments, argument_base),
                    .object_new => |c| target.node.kind.object_new.arguments = moved(c.arguments, arguments, argument_base),
                    .recur => |range| target.node.kind = .{ .recur = moved(range, arguments, argument_base) },
                    else => {},
                }
            }
            for (storage.members[members..storage.member_count], storage.members[member_base..][0..member_total]) |operand, *target| target.* = operand + shift;
            for (storage.arguments[arguments..storage.argument_count], storage.arguments[argument_base..][0..argument_total]) |operand, *target| target.* = operand + shift;
            storage.node_top = node_base;
            storage.member_top = member_base;
            storage.argument_top = argument_base;
            storage.node_count = default.start;
            storage.member_count = members;
            storage.argument_count = arguments;
            return .{ .start = default.start + shift, .end = default.end + shift, .root = default.root + shift, .work = default.work };
        }

        fn moved(range: Span, from: u32, to: u32) Span {
            return if (range.start == range.end) range else .{ .start = range.start - from + to, .end = range.end - from + to };
        }

        fn beginAnonymous(self: *Self, token: Token, parentheses: u32) ParseError!bool {
            const w = self.workspace;
            if (w.anonymous_count == w.anonymous_frames.len or w.runtime_functions.count == types.limits.functions) return w.fail(token.span, .function_limit);
            w.anonymous_frames[w.anonymous_count] = .{
                .definition = .{ .name = token.span, .value_type = undefined, .is_public = false, .anonymous = true, .specialization = if (self.generic) |g| g.specialization else null, .generic_source = if (self.generic) |g| if (g.specialization != null) w.genericSourceFor(w.generic_templates[g.template].source, token.span) else .{ .start = 0, .end = 0 } else .{ .start = 0, .end = 0 }, .start = 0, .end = 0, .root = 0 },
                .parent_module = w.current_module,
                .parent_nested = w.current_nested,
                .parent_generic = self.generic,
                .parent_function = self.function,
                .parent_inferring = self.inferring,
                .expected_type = self.expected_type,
                .default_expression = self.default_expression,
                .control_depth = self.control_depth,
                .operator_base = self.operator_base,
                .operand_base = self.operand_base,
                .local_base = self.local_base,
                .parentheses = parentheses,
                .operators = self.operator_count,
                .operands = self.operand_count,
                .locals = w.local_count,
                .checkpoints = w.local_checkpoint_count,
                .failable_uses = w.failable_uses,
                .template_nodes = w.functions.node_count,
                .template_members = w.functions.member_count,
                .template_arguments = w.functions.argument_count,
                .staging = w.staging_count,
            };
            w.anonymous_count += 1;
            w.anonymous_frames[w.anonymous_count - 1].for_call = w.forCallOf(token);
            if (w.libraryModule(token.span) != null) w.anonymous_frames[w.anonymous_count - 1].macro_site = token.site;
            // `__for_keep:=Fn(...)`: the filter of an RFC-0056 `For`; `__for_f:=Fn(...)`: a level's
            // function, or the body of an RFC-0056 `For` (P3.8).
            if (w.libraryModule(token.span) != null and self.cursor >= 4 and w.tokens[self.cursor - 2].kind == .equal and w.tokens[self.cursor - 3].kind == .colon and w.tokens[self.cursor - 4].kind == .identifier and w.libraryModule(w.tokens[self.cursor - 4].span) != null) {
                const bound = w.tokens[self.cursor - 4].span.text(w.source);
                w.anonymous_frames[w.anonymous_count - 1].filter = std.mem.eql(u8, bound, "__for_keep");
                w.anonymous_frames[w.anonymous_count - 1].for_body = std.mem.eql(u8, bound, "__for_f");
            }
            // The visit of a `Loop{}` or a `While` (P3.4): a library `Fn` that is a `Loop(`'s first argument.
            if (w.libraryModule(token.span) != null and self.operator_count > self.operator_base and w.operators[self.operator_count - 1].kind == .loop and self.operand_count == w.operators[self.operator_count - 1].operand_base) w.anonymous_frames[w.anonymous_count - 1].visit = true;
            if (self.peek().kind == .left_bracket) {
                self.cursor += 1;
                w.anonymous_frames[w.anonymous_count - 1].explicit_captures = true;
                const capture_type = try self.anonymousCaptureHeader();
                try self.pushOperator(.{ .kind = .anonymous_capture, .span = token.span, .operand_base = self.operand_count, .value_type = capture_type });
                return false;
            }
            try self.anonymousBodyHeader();
            return true;
        }

        fn anonymousCaptureHeader(self: *Self) ParseError!types.Type {
            const w = self.workspace;
            const frame = &w.anonymous_frames[w.anonymous_count - 1];
            self.skipNewlines();
            const name = try self.take(.identifier, .expected_parameter);
            if (reserved(name.span.text(w.source)) or (generatedName(name.span.text(w.source)) and w.libraryModule(name.span) == null)) return w.fail(name.span, .expected_parameter);
            if (frame.definition.parameter_count == types.limits.parameters) return w.fail(name.span, .parameter_limit);
            for (frame.definition.parameters[0..frame.definition.parameter_count]) |earlier| if (std.mem.eql(u8, earlier.name.text(w.source), name.span.text(w.source))) return w.fail(name.span, .duplicate_name);
            const value_type = try self.parseType();
            _ = try self.take(.equal, .expected_equal);
            // `[Name:type = Name]` captures that very name and is no new one; any other capture
            // is a new name and may not be one that is visible (RFC-0076, D5).
            const itself = self.peek().kind == .identifier and std.mem.eql(u8, self.peek().span.text(w.source), name.span.text(w.source)) and (w.tokens[self.cursor + 1].kind == .comma or w.tokens[self.cursor + 1].kind == .right_bracket);
            if (!itself) try self.checkShadow(name, true);
            w.noteDeclaration(name.span, .local, qualify.none);
            frame.definition.parameters[frame.definition.parameter_count] = .{ .name = name.span, .value_type = value_type };
            frame.definition.parameter_count += 1;
            self.skipNewlines();
            return value_type;
        }

        fn anonymousCaptureDelimiter(self: *const Self) bool {
            var index = self.operator_count;
            while (index > self.operator_base) {
                index -= 1;
                const op = self.workspace.operators[index];
                if (op.precedence() == 0) return op.kind == .anonymous_capture;
            }
            return false;
        }

        fn finishAnonymousCapture(self: *Self, token: Token) ParseError!bool {
            const w = self.workspace;
            const op = try self.reduceToDelimiter(token);
            std.debug.assert(op.kind == .anonymous_capture and w.anonymous_count > 0);
            if (self.operand_count != op.operand_base + 1) return w.fail(token.span, .expected_expression);
            const value = w.operands[op.operand_base];
            if (self.node(value).value_type != op.value_type.?) return w.fail(self.node(value).span, .type_mismatch);
            const frame = &w.anonymous_frames[w.anonymous_count - 1];
            std.debug.assert(frame.phase == .captures and frame.capture_count < frame.capture_values.len);
            frame.capture_values[frame.capture_count] = value;
            frame.capture_count += 1;
            self.operand_count = op.operand_base;
            if (token.kind == .comma) {
                op.value_type = try self.anonymousCaptureHeader();
                return false;
            }
            // RFC-0085, I11: the captures are names of the body only; their values are read
            // around the `Fn`.
            if (w.qualify) for (frame.definition.parameters[0..frame.definition.parameter_count]) |declared| w.beginScope(declared.name.start, token.span.end);
            self.operator_count -= 1;
            try self.anonymousBodyHeader();
            return true;
        }

        fn anonymousBodyHeader(self: *Self) ParseError!void {
            const w = self.workspace;
            const frame = &w.anonymous_frames[w.anonymous_count - 1];
            var definition = frame.definition;
            _ = try self.take(.left_paren, .expected_parameter);
            try self.parseParameters(&definition, .none);
            // `<effect>` and `:Type` are optional: the effect then follows the expected function
            // type or the enclosing function, and the result type is the body's own type.
            const generated = w.libraryModule(definition.name) != null;
            // A loop at the root does what the root may (`useEffect`).
            const infers = generated and self.peek().kind != .less and self.peek().kind != .synthetic_inherit and !self.expectsCallable() and self.rootLoop();
            const effect = if (self.peek().kind == .less) try self.parseEffect(.expected_computes) else if (self.peek().kind == .synthetic_inherit) inherit: {
                // A generated loop function (RFC-0068) may do what the code around the loop may:
                // write where that writes, and fail where a failure there is caught.
                self.cursor += 1;
                var around: Effect = if (self.function) |f| Effect.of(f).heapOnly() else .{ .transacts = true };
                around.decides = self.failureContextHere();
                // A loop in a suspending function may suspend, unless its failure is caught here:
                // then nothing in it may (`suspensionBarred` would say so of each call).
                if (self.function) |f| around.detail.suspends = f.detail.suspends and !around.decides and !self.suspensionBarred();
                break :inherit around;
            } else if (infers) Effect{ .transacts = true } else self.inheritedEffect(generated);
            definition.transacts = effect.transacts;
            definition.decides = effect.decides;
            definition.detail = effect.detail;
            // RFC-0082, P3.8: calling a filter that suspends would be a site in a condition.
            if (frame.filter) definition.detail.suspends = false;
            frame.infers = infers;
            self.inferring = if (infers) w.anonymous_count - 1 else null;
            frame.infer = self.peek().kind != .colon;
            if (frame.infer) definition.value_type = .i64 else {
                const result = try self.parseResultType();
                definition.value_type = result.value_type;
                frame.discards = result.discards;
            }
            _ = try self.take(.left_brace, .expected_expression);
            if (!frame.explicit_captures) try self.captureFreeNames(frame, &definition);
            definition.start = w.functions.node_count;
            frame.definition = definition;
            frame.phase = .body;
            frame.template_nodes = w.functions.node_count;
            frame.template_members = w.functions.member_count;
            frame.template_arguments = w.functions.argument_count;
            frame.staging = w.staging_count;
            self.operator_base = self.operator_count;
            self.operand_base = self.operand_count;
            self.local_base = w.local_count;
            self.function = definition;
            _ = try self.bindPatterns(definition);
            self.expected_type = if (frame.infer or frame.discards) null else definition.value_type;
            self.default_expression = false;
            self.control_depth = 0;
            self.skipNewlines();
        }

        /// The effect of an anonymous function that does not write one: the expected function
        /// type's when the context names one, otherwise the enclosing function's write access
        /// (and never `decides`, which a body must ask for).
        /// A function a macro wrote for a loop (`generated`) also suspends where the function
        /// around it does, as the loop's body is that function's code (RFC-0078).
        fn expectsCallable(self: *const Self) bool {
            const expected = self.expected_type orelse return false;
            const shape = catalogue.definition(expected, self.definitions()) orelse return false;
            return shape == .callable;
        }
        fn inheritedEffect(self: *const Self, generated: bool) Effect {
            if (self.expected_type) |expected| if (catalogue.definition(expected, self.definitions())) |shape| if (shape == .callable) {
                // What the type allows, except to converge: no body is vouched for.
                var detail = shape.callable.detail;
                detail.converges = false;
                return .{ .transacts = shape.callable.transacts, .decides = shape.callable.decides, .detail = detail };
            };
            const f = self.function orelse return .{};
            // A function the program writes inside a loop at the root keeps the `<computes>` it
            // has at the root: its type is the program's, and must not depend on how the loop
            // around it is lowered (`rootLoop`).
            if (!generated and self.rootLoop()) return .{};
            var around = Effect.of(f).heapOnly();
            around.detail.suspends = generated and f.detail.suspends and !self.suspensionBarred();
            return around;
        }

        /// Whether the code being compiled is the root's, or the body of a function a macro
        /// wrote for a `For`, `While` or `First` there, directly or inside another such function
        /// (RFC-0079): one that declares what its body uses (`AnonymousFrame.infers`). The
        /// function of a `Loop{...}` takes all three heap effects at the root, as it always did,
        /// so what is written inside it inherits them as before. A frame still reading its
        /// captures is not around the code yet.
        fn rootLoop(self: *const Self) bool {
            if (self.function == null) return true;
            const w = self.workspace;
            std.debug.assert(w.anonymous_count != 0);
            var index = w.anonymous_count - 1;
            while (index != 0) {
                index -= 1;
                const frame = &w.anonymous_frames[index];
                if (frame.phase != .body) continue;
                return frame.kind == .anonymous and frame.infers;
            }
            return false;
        }

        /// The root runs its initialisers with every heap effect (RFC-0078), and a loop's body
        /// is the code around the loop: a function a macro writes for a loop at the root may do
        /// what the root does (RFC-0079). It is compiled as if it declared all three heap
        /// effects, records the ones its body uses (`useEffect`), and declares exactly those
        /// when it is finished (`finishAnonymous`), so a loop that uses none compiles to what it
        /// compiled to before.
        fn useEffect(self: *Self, used: types.EffectSet) void {
            const index = self.inferring orelse return;
            const frame = &self.workspace.anonymous_frames[index];
            std.debug.assert(frame.infers and frame.phase == .body);
            frame.used.reads = frame.used.reads or used.reads;
            frame.used.writes = frame.used.writes or used.writes;
            frame.used.allocates = frame.used.allocates or used.allocates;
        }

        /// An `Fn` without `[...]` captures, by value at the moment it is built, every local and
        /// parameter of the enclosing function that its body names. Names that the function
        /// declares itself, fields after a dot and anything else are left to ordinary lookup.
        /// A name that only looks like a local (it is rebound inside the body) costs a spare capture.
        fn captureFreeNames(self: *Self, frame: *AnonymousFrame, definition: *functions.Definition) ParseError!void {
            const w = self.workspace;
            // `labelled` (RFC-0085, I13): every occurrence so far was a label, which shares nothing.
            const Found = struct { name: Span, node: u32, value_type: types.Type, labelled: bool = false };
            var found: [types.limits.parameters]Found = undefined;
            var count: u32 = 0;
            var depth: usize = 1;
            var at = self.cursor;
            // An arm (RFC-0082, P3.3) has no braces of its own: it ends at the comma or the
            // parenthesis after it.
            const arm = frame.arm;
            // RFC-0085, I3: a nested function's body ends with its statement.
            const nested = frame.nested;
            // RFC-0085, I13 (S1e): every closure form but a guard (S1b) and a nested function
            // (S1a) shares the local `var`s it names. A function a macro wrote for a loop, `First`
            // or `For` is not a closure: its body is the code around it. Nor is a landing: it
            // reads what it captures at its site (P3.3), where the function that declares the
            // local waits, so nothing has changed it (I13-D5, review).
            const names_share = !nested and !frame.guard_body and !frame.landing and w.share_names and (frame.task_body or frame.arm or frame.batch != null or self.userFunction(definition.*));
            scan: while (at < w.token_count and depth != 0) : (at += 1) {
                const token = w.tokens[at];
                switch (token.kind) {
                    .left_brace => depth += 1,
                    .right_brace => depth -= 1,
                    .left_paren, .left_bracket => if (arm or nested) {
                        depth += 1;
                    },
                    .right_paren, .right_bracket => if (arm or nested) {
                        depth -= 1;
                    },
                    .comma => if (arm and depth == 1) break :scan,
                    .newline, .separator => if (nested and depth == 1) break :scan,
                    .identifier, .synthetic_live_raw => {
                        if (token.kind == .identifier and at > 0 and w.tokens[at - 1].kind == .dot) continue;
                        // The raw field of a variable whose type is a function is read through
                        // the `Self` of the class's clauses (RFC-0084, P4.3).
                        if (token.kind == .synthetic_live_raw and (self.live_raw == null or self.live_raw.? != .field)) continue;
                        const text = if (token.kind == .synthetic_live_raw) "Self" else token.span.text(w.source);
                        // RFC-0085, I3: no superclass call in a nested function, at any depth
                        // (06:1225): `Super.Name`, or `(super:)Name` as the Book writes it.
                        if (nested and token.kind == .identifier and at + 1 < w.token_count and w.tokens[at + 1].kind == .dot and (std.mem.eql(u8, text, "Super") or (std.mem.eql(u8, text, "super") and w.qualifierFor(token.span.start) != null)) and self.findLocal(text) == null and self.parameter(text) == null) return w.fail(token.span, .nested_super);
                        if (reserved(text)) continue;
                        // RFC-0085, S1: a label denotes nothing, so it shares nothing (review).
                        if (nested and w.labelAt(at)) continue;
                        for (definition.parameters[0..definition.parameter_count]) |entry| if (std.mem.eql(u8, entry.name.text(w.source), text)) continue :scan;
                        for (found[0..count]) |*entry| if (std.mem.eql(u8, entry.name.text(w.source), text)) {
                            // RFC-0085, I13: a label of the name earlier in the body was captured (a
                            // spare capture) but shared nothing; the first use after it shares (review).
                            if (entry.labelled and !w.labelAt(at)) {
                                entry.labelled = false;
                                try self.nameShares(text, token.span);
                            }
                            continue :scan;
                        };
                        var capture: Found = undefined;
                        // RFC-0085, I13 (S1e, Q1): a local `var` that any other closure form names is
                        // shared, as one a nested function names is (S1a, below).
                        if (names_share and !w.labelAt(at)) try self.nameShares(text, token.span);
                        // RFC-0085, S1a: a local `var` a nested function names is shared.
                        if (nested) if (self.varOrigin(text)) |origin| if (w.locals[origin].mutable and !w.wantShare(w.locals[origin].name)) return w.fail(token.span, .not_mutable);
                        if (self.findLocal(text)) |index| {
                            // RFC-0085, S1b (I14, RFC-0084 P4.8): a guard that names a local `var`
                            // shares it, and follows its cell; a copy would never change (Q1).
                            if (frame.guard_body and w.locals[index].mutable) if (!self.guardShares(text)) return w.fail(token.span, .guard_local_var);
                            capture = .{ .name = w.locals[index].name, .node = w.locals[index].node, .value_type = self.node(w.locals[index].node).value_type };
                        } else if (self.parameter(text)) |index| {
                            const parameter_type = self.function.?.parameters[index].value_type;
                            // So does one that names it through what the closures around it
                            // captured (RFC-0085, Q10, I14), or through a loop's function: a cell
                            // they captured is the guard's capture too.
                            if (frame.guard_body and !catalogue.isRef(parameter_type, self.definitions())) if (self.captureOrigin(text)) |origin| if (origin.local and w.locals[origin.index].mutable and !self.guardShares(text)) return w.fail(token.span, if (origin.through_closure) .guard_capture_var else .guard_local_var);
                            // A landing reads what it captures at each site, not here (P3.3).
                            const read = if (frame.landing) no_member else try self.emitTemplate(.{ .node = .{ .span = token.span, .value_type = parameter_type, .kind = .{ .integer = 0 } }, .input = .{ .parameter = index } });
                            capture = .{ .name = self.function.?.parameters[index].name, .node = read, .value_type = parameter_type };
                        } else {
                            // RFC-0085, I3 (S7): a nested function in reach that the body names
                            // brings its captures, so that the body can call it or bind it. A
                            // guard that calls one reads what it reads, as through any call.
                            // RFC-0085, I4: an overloaded one brings the captures of each overload.
                            var overload = self.findNested(text, token.span.start);
                            while (overload) |entry| : (overload = self.nextOverload(entry)) {
                                const callee = w.nested_functions[entry];
                                if (callee.runtime == no_member) continue;
                                names: for (w.nested_capture_names[callee.captures.start..callee.captures.end]) |name| {
                                    const wanted = name.text(w.source);
                                    for (definition.parameters[0..definition.parameter_count]) |earlier| if (std.mem.eql(u8, earlier.name.text(w.source), wanted)) continue :names;
                                    for (found[0..count]) |earlier| if (std.mem.eql(u8, earlier.name.text(w.source), wanted)) continue :names;
                                    var carried: Found = undefined;
                                    if (self.findLocal(wanted)) |index| {
                                        carried = .{ .name = w.locals[index].name, .node = w.locals[index].node, .value_type = self.node(w.locals[index].node).value_type };
                                    } else if (self.parameter(wanted)) |index| {
                                        const parameter_type = self.function.?.parameters[index].value_type;
                                        const read = if (frame.landing) no_member else try self.emitTemplate(.{ .node = .{ .span = token.span, .value_type = parameter_type, .kind = .{ .integer = 0 } }, .input = .{ .parameter = index } });
                                        carried = .{ .name = self.function.?.parameters[index].name, .node = read, .value_type = parameter_type };
                                    } else return w.fail(token.span, .unknown_name);
                                    if (count == found.len or definition.parameter_count + count + 1 > definition.parameters.len) return w.fail(token.span, .parameter_limit);
                                    found[count] = carried;
                                    count += 1;
                                }
                            }
                            continue;
                        }
                        if (count == found.len or definition.parameter_count + count + 1 > definition.parameters.len) return w.fail(token.span, .parameter_limit);
                        found[count] = capture;
                        found[count].labelled = names_share and w.labelAt(at);
                        count += 1;
                    },
                    else => {},
                }
            }
            if (count == 0) return;
            std.mem.copyBackwards(functions.Parameter, definition.parameters[count .. count + definition.parameter_count], definition.parameters[0..definition.parameter_count]);
            for (found[0..count], 0..) |entry, index| {
                definition.parameters[index] = .{ .name = entry.name, .value_type = entry.value_type };
                frame.capture_values[index] = entry.node;
            }
            definition.parameter_count += count;
            frame.capture_count = count;
            frame.definition.parameter_count = definition.parameter_count;
            // RFC-0091: the parameters a pattern reads moved past the captures with the rest.
            for (w.patterns[definition.patterns.start..definition.patterns.end]) |*entry| entry.parameter += @intCast(count);
            frame.definition.patterns = definition.patterns;
        }

        /// RFC-0085, I13 (S1e): `name`, named by a closure form at `span`, shares the local `var`
        /// it denotes (`varOrigin`): the declaration is noted (`wantShare`). As for S1a, the note
        /// cannot be refused for a source program (the table has room for every declaration);
        /// if it were, the name is `not_mutable`, never a silent copy.
        fn nameShares(self: *Self, name: []const u8, span: Span) ParseError!void {
            const w = self.workspace;
            const origin = self.varOrigin(name) orelse return;
            if (!w.locals[origin].mutable) return;
            if (!w.wantShare(w.locals[origin].name)) return w.fail(span, .not_mutable);
        }

        fn finishAnonymous(self: *Self, close: Token) ParseError!u32 {
            const w = self.workspace;
            std.debug.assert(w.anonymous_count > 0);
            while (self.operator_count > self.operator_base) try self.applyOperator();
            if (self.operand_count != self.operand_base + 1) return w.fail(close.span, .expected_expression);
            const frame = w.anonymous_frames[w.anonymous_count - 1];
            var definition = frame.definition;
            definition.root = w.operands[self.operand_base];
            if (frame.discards) {
                // RFC-0080: the value of a `void` body is dropped and the unit value stands for it.
                try self.checkDiscarded(definition.root);
                definition.root = try self.packTuple(&.{}, definition.name);
            }
            if (frame.infer) definition.value_type = self.node(definition.root).value_type else if (self.node(definition.root).value_type != definition.value_type) return w.fail(self.node(definition.root).span, if (self.valuelessAt(definition.root)) .if_without_else else .type_mismatch);
            if (frame.infers) {
                // What the body used, and nothing more (`useEffect`).
                const used = frame.used;
                definition.transacts = used.reads or used.writes or used.allocates;
                definition.detail = if (definition.transacts) types.heapDetail(used.reads, used.writes, used.allocates) else .{};
            }
            definition.end = w.functions.node_count;
            definition.work = self.body(definition.start, definition.root).work;
            try self.checkPredicting(definition);
            const value_type = try self.functionType(definition, definition.name);
            const target = w.runtime_functions.publishAlias(definition, &w.functions, self.definitions(), w.bindings[0..w.binding_count], w.binding_cells[0..w.binding_count], w.node_count) catch |err| return w.fail(definition.name, switch (err) {
                error.FunctionLimit => .function_limit,
                error.NodeLimit => .template_limit,
                error.MemberLimit => .aggregate_limit,
                error.ArgumentLimit => .call_argument_limit,
                error.GlobalLimit => .binding_limit,
            });
            std.debug.assert(target != null);
            if (frame.nested) w.runtime_functions.definitions[target.?].nested = true;
            // RFC-0085, I11: the parameters an `Fn` declares, its explicit captures among them, are
            // names in its braces only. A capture `[A:t = A]` has the name of a local around it,
            // which names that local again after the closing brace.
            // A local an `Fn` captures without saying so is the local around it, which goes on.
            if (w.qualify) for (definition.parameters[0..definition.parameter_count], 0..) |declared, index| {
                if (frame.explicit_captures or index >= frame.capture_count) w.endScope(declared.name.start, close.span.end);
            };
            w.functions.node_count = frame.template_nodes;
            w.functions.member_count = frame.template_members;
            w.functions.argument_count = frame.template_arguments;
            w.staging_count = frame.staging;
            w.local_count = frame.locals;
            w.local_checkpoint_count = frame.checkpoints;
            self.function = frame.parent_function;
            self.inferring = frame.parent_inferring;
            self.generic = frame.parent_generic;
            if (frame.method) {
                self.method_class = frame.parent_method_class;
                self.member_expression = frame.parent_member_expression;
            }
            w.current_module = frame.parent_module;
            w.current_nested = frame.parent_nested;
            if (frame.kind == .generic) self.cursor = frame.return_cursor;
            self.expected_type = frame.expected_type;
            self.default_expression = frame.default_expression;
            self.control_depth = frame.control_depth;
            self.operator_base = frame.operator_base;
            self.operand_base = frame.operand_base;
            self.local_base = frame.local_base;
            self.operator_count = frame.operators;
            self.operand_count = frame.operands;
            w.failable_uses = frame.failable_uses;
            w.anonymous_count -= 1;
            // The access that named a generic method is read again and now finds it published.
            if (frame.method) return frame.parentheses;
            // A landing is called from each site with what it captures there (RFC-0082, P3.3).
            if (frame.landing) {
                try self.recordLanding(frame, definition, value_type, target.?);
                return frame.parentheses;
            }
            // A nested function leaves nothing where it is declared (RFC-0085, S7): its name
            // means it from the next statement to the end of its block.
            if (frame.nested) {
                try self.declareNested(frame, definition, target.?);
                return frame.parentheses;
            }
            var result = try self.emit(.{ .span = if (frame.kind == .generic) frame.reference_span else definition.name, .value_type = value_type, .kind = .{ .function_value = target.? } });
            if (frame.capture_count != 0) {
                var parameters: [types.limits.parameters]types.Type = undefined;
                const count = definition.parameter_count - frame.capture_count;
                for (definition.parameters[frame.capture_count..definition.parameter_count], parameters[0..count]) |entry, *t| t.* = entry.value_type;
                const residual = try self.internTuple(parameters[0..count], definition.name);
                const residual_type = w.catalogue.internCallable(.{ .parameters = residual, .result = definition.value_type, .transacts = definition.transacts, .decides = definition.decides, .detail = definition.detail }) catch |err| return w.fail(definition.name, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                const arguments = try self.reserveArguments(frame.capture_values[0..frame.capture_count], definition.name);
                result = try self.emit(.{ .span = definition.name, .value_type = residual_type, .kind = .{ .bind = .{ .callable = result, .arguments = arguments } } });
            }
            if (frame.inferred != 0) result = try self.finishInferred(frame, result);
            try self.pushOperand(result);
            return frame.parentheses;
        }

        fn parseExpression(self: *Self, expected_type: ?types.Type) ParseError!u32 {
            self.operator_count = 0;
            self.operand_count = 0;
            self.expected_type = expected_type;
            self.operator_base = 0;
            self.operand_base = 0;
            self.local_base = 0;
            self.mark_count = 0;
            self.hidden_count = 0;
            self.workspace.staging_count = 0;
            var expects_operand = true;
            var parentheses: u32 = 0;
            while (true) {
                const token = self.peek();
                // RFC-0085, I3: the body of a nested function ends with its statement.
                if (parentheses == 0 and self.ownNested() != no_member) {
                    if (token.kind == .newline or token.kind == .separator or token.kind == .right_brace or token.kind == .eof) {
                        if (expects_operand) return self.workspace.fail(token.span, .expected_expression);
                        parentheses = try self.finishAnonymous(token);
                        expects_operand = true;
                        continue;
                    }
                }
                if (parentheses == 0 and self.workspace.anonymous_count != 0 and self.workspace.anonymous_frames[self.workspace.anonymous_count - 1].phase == .body) {
                    if (token.kind == .newline) {
                        self.cursor += 1;
                        continue;
                    }
                    if (token.kind == .eof or token.kind == .separator) return self.workspace.fail(token.span, .unexpected_token);
                }
                // An arm of `Sync` or `Race` ends at the comma or the parenthesis after it, which
                // the form then reads (RFC-0082, P3.3).
                if (parentheses == 0 and self.armBody()) {
                    if (token.kind == .comma or token.kind == .right_paren) {
                        if (expects_operand) return self.workspace.fail(token.span, .expected_expression);
                        parentheses = try self.finishArm(token);
                        expects_operand = false;
                        continue;
                    }
                    if (token.kind == .right_brace) return self.workspace.fail(token.span, .unexpected_token);
                }
                if (token.kind == .right_brace and parentheses == 0 and self.workspace.anonymous_count != 0 and self.workspace.anonymous_frames[self.workspace.anonymous_count - 1].phase == .body) {
                    if (expects_operand) return self.workspace.fail(token.span, .expected_expression);
                    self.cursor += 1;
                    parentheses = try self.finishAnonymous(token);
                    expects_operand = false;
                    continue;
                }
                if (expects_operand and token.kind == .identifier and std.mem.eql(u8, token.span.text(self.workspace.source), "Fn")) {
                    self.cursor += 1;
                    const entered_body = try self.beginAnonymous(token, parentheses);
                    parentheses = if (entered_body) 0 else parentheses + 1;
                    expects_operand = true;
                    continue;
                }
                if ((token.kind == .comma or token.kind == .right_bracket) and self.anonymousCaptureDelimiter()) {
                    if (expects_operand) return self.workspace.fail(token.span, .expected_expression);
                    self.cursor += 1;
                    if (try self.finishAnonymousCapture(token)) parentheses = 0;
                    expects_operand = true;
                    continue;
                }
                if ((token.kind == .newline or token.kind == .separator) and self.blockDelimiter()) {
                    // Consume a whole separator run once. A trailing run keeps
                    // the final expression; completed declarations need a result.
                    while (self.peek().kind == .newline or self.peek().kind == .separator) self.cursor += 1;
                    if (expects_operand) {
                        const top = self.workspace.operators[self.operator_count - 1];
                        if (top.kind != .block or top.head != no_member or self.operand_count != top.operand_base) return self.workspace.fail(token.span, .expected_expression);
                        continue;
                    }
                    const block = try self.reduceToDelimiter(token);
                    if (block.head != no_member) {
                        try self.finishLocal(block);
                        self.operand_count = block.operand_base;
                        expects_operand = true;
                    } else if (self.peek().kind != .right_brace and self.peek().kind != .synthetic_defer) {
                        if (self.operand_count == block.operand_base + 1) try self.checkDiscarded(self.workspace.operands[block.operand_base]);
                        self.operand_count = block.operand_base;
                        expects_operand = true;
                    }
                    continue;
                }
                if (token.kind == .synthetic_defer_mark or token.kind == .synthetic_defer) {
                    // Both stand between the statements of a block and leave its value alone.
                    const w = self.workspace;
                    if (self.operator_count == self.operator_base) return w.fail(token.span, .unexpected_token);
                    const top = w.operators[self.operator_count - 1];
                    if (top.kind != .block or top.head != no_member or expects_operand != (self.operand_count == top.operand_base)) return w.fail(token.span, .unexpected_token);
                    self.cursor += 1;
                    if (token.kind == .synthetic_defer_mark) {
                        if (!expects_operand) return w.fail(token.span, .unexpected_token);
                        try self.pushDeferMark(token.span);
                        continue;
                    }
                    try self.startDeferred(token);
                    parentheses += 1;
                    expects_operand = true;
                    continue;
                }
                if (token.kind == .synthetic_landing) {
                    // The copy of a `Defer` body that a cancellation runs, right after its mark
                    // (RFC-0082, P3.3): compiled here, as a function, and called from each site.
                    const w = self.workspace;
                    if (self.operator_count == self.operator_base or !expects_operand or self.mark_count == 0) return w.fail(token.span, .unexpected_token);
                    const top = w.operators[self.operator_count - 1];
                    if (top.kind != .block or top.head != no_member or self.operand_count != top.operand_base or self.marks[self.mark_count - 1].operator != self.operator_count - 1 or w.landings[self.mark_count - 1].function != no_member) return w.fail(token.span, .unexpected_token);
                    self.cursor += 1;
                    try self.beginLanding(token, parentheses);
                    parentheses = 1;
                    continue;
                }
                if (expects_operand and token.kind == .identifier and self.operator_count > self.operator_base and self.workspace.operators[self.operator_count - 1].kind == .block) {
                    // RFC-0085, I3: a nested function, at the start of a statement.
                    const statement_block = self.workspace.operators[self.operator_count - 1];
                    // As the program wrote it, not where a macro moved an argument (review):
                    // there it stood where no statement does, and is refused below.
                    if (statement_block.head == no_member and self.operand_count == statement_block.operand_base and self.workspace.writtenAsStatement(token.span.start)) if (self.workspace.nestedHeaderAt(self.cursor)) |body_start| {
                        parentheses = try self.beginNested(token, parentheses, body_start);
                        continue;
                    };
                    const word = token.span.text(self.workspace.source);
                    if (std.mem.eql(u8, word, "var")) {
                        self.cursor += 1;
                        const local_name = self.peek();
                        if (local_name.kind != .identifier) return self.workspace.fail(local_name.span, .expected_name);
                        // RFC-0085, S1c (I14): `var live X:T = G`, a local whose cell follows `G`.
                        if (std.mem.eql(u8, local_name.span.text(self.workspace.source), "live") and self.workspace.tokens[self.cursor + 1].kind == .identifier) {
                            self.cursor += 1;
                            try self.startLiveLocal(self.peek());
                            continue;
                        }
                        try self.startLocal(local_name, true);
                        continue;
                    }
                    if (std.mem.eql(u8, word, "live") and self.workspace.tokens[self.cursor + 1].kind == .identifier) return self.workspace.fail(self.workspace.tokens[self.cursor + 1].span, .live_target);
                    if (std.mem.eql(u8, word, "set")) {
                        self.cursor += 1;
                        try self.startLocalSet();
                        continue;
                    }
                    if (self.workspace.tokens[self.cursor + 1].kind == .colon) {
                        try self.startLocal(token, false);
                        continue;
                    }
                }
                if (token.kind == .newline and parentheses > 0) {
                    self.cursor += 1;
                    if (!expects_operand and self.aggregateDelimiter()) {
                        try self.finishMember(token);
                        try self.selectField();
                        expects_operand = true;
                    }
                    continue;
                }
                if (token.kind == .eof or token.kind == .newline or token.kind == .separator or token.kind == .synthetic_live_end or
                    ((self.default_expression or self.member_expression) and parentheses == 0 and (token.kind == .comma or token.kind == .right_brace or token.kind == .right_paren)))
                {
                    if (parentheses != 0) return self.workspace.fail(token.span, .unmatched_parenthesis);
                    if (expects_operand) return self.workspace.fail(token.span, .expected_expression);
                    break;
                }
                self.cursor += 1;
                if (token.kind == .right_brace) {
                    if (parentheses == 0) return self.workspace.fail(token.span, .unexpected_token);
                    if (self.deferredDelimiter()) {
                        try self.closeDeferred(token, expects_operand);
                        parentheses -= 1;
                        if (parentheses == 0 and self.landingBodyDone()) {
                            // The landing is compiled; it leaves no value where it stands.
                            parentheses = try self.finishLanding(token);
                            expects_operand = true;
                            continue;
                        }
                        // The statement before the copy is the block's value again, if it left one.
                        expects_operand = self.operand_count == self.workspace.operators[self.operator_count - 1].operand_base;
                        continue;
                    }
                    if (self.blockDelimiter()) {
                        try self.closeBlock(token, expects_operand);
                        // The block of a `logic{...}` sits directly on its attempt.
                        if (self.operator_count > self.operator_base) {
                            const below = self.workspace.operators[self.operator_count - 1];
                            if (below.kind == .attempt and below.names == caught_logic and below.arguments == 0) try self.finishLogic(token);
                        }
                    } else try self.closeAggregate(token, expects_operand);
                    parentheses -= 1;
                    expects_operand = false;
                    // The block was the body of a `Spawn`, which ends with it (RFC-0082).
                    if (parentheses == 0 and self.spawnBodyDone()) parentheses = try self.finishSpawn(token);
                    // Or a live guard (RFC-0084).
                    if (parentheses == 0 and self.guardBodyDone()) parentheses = try self.finishGuard(token);
                } else if (token.kind == .right_paren or token.kind == .right_bracket) {
                    if (parentheses == 0) return self.workspace.fail(token.span, .unmatched_parenthesis);
                    try self.closeParenthesis(token, expects_operand);
                    parentheses -= 1;
                    expects_operand = false;
                    if (self.continued) {
                        // RFC-0091: the body of an inferred call's specialization is read from here on.
                        self.continued = false;
                        self.workspace.anonymous_frames[self.workspace.anonymous_count - 1].parentheses = parentheses;
                        parentheses = 0;
                        expects_operand = true;
                    }
                } else if (token.kind == .comma) {
                    if (expects_operand) return self.workspace.fail(token.span, .expected_expression);
                    if (self.aggregateDelimiter()) {
                        try self.finishMember(token);
                        try self.selectField();
                    } else {
                        try self.finishArgument(token);
                        // The next arm of a `Sync` or `Race` is a function of its own; after the
                        // last, the code that carries an arm's pending exit on (P3.6) is not.
                        if (self.structuredOpen() and self.peek().kind == .synthetic_arm_reissue) {
                            self.cursor += 1;
                            try self.beginReissue();
                        } else if (self.structuredOpen()) {
                            try self.beginArm(parentheses);
                            parentheses = 0;
                        } else if (self.reactionOpen()) {
                            // So is the body of an `Upon` or a `When` (RFC-0084, P4.4). `Await`
                            // takes its guard alone (P4.6).
                            if (self.awaitOpen()) return self.workspace.fail(token.span, .argument_count);
                            try self.beginReactionArm(parentheses, .body);
                            parentheses = 0;
                        }
                    }
                    expects_operand = true;
                } else if (token.kind == .arrow and !expects_operand) {
                    try self.finishMember(token);
                    expects_operand = true;
                } else if (expects_operand) {
                    const started = try self.expressionOperand(token, parentheses);
                    if (started == .continuation) parentheses = 0;
                    // The body of a `Spawn` begins with its block open (RFC-0082).
                    if (started == .body) parentheses = 1;
                    // The first arm of a `Sync` or `Race` begins with nothing open in it.
                    if (started == .arm) parentheses = 0;
                    if (started == .parenthesis) parentheses += 1;
                    if (started == .value) expects_operand = false;
                } else if (token.kind == .question) {
                    try self.unwrapOption(token);
                } else if (token.kind == .dot) {
                    if (try self.accessField(token)) {
                        if (self.continued) {
                            // The body of a generic method (RFC-0081) is read from here on.
                            self.continued = false;
                            self.workspace.anonymous_frames[self.workspace.anonymous_count - 1].parentheses = parentheses;
                            parentheses = 0;
                        } else parentheses += 1;
                        expects_operand = true;
                    }
                } else if (token.kind == .left_paren or token.kind == .left_bracket) {
                    if (try self.accessValue(token)) {
                        parentheses += 1;
                        expects_operand = true;
                    }
                } else if (token.kind == .left_brace and self.metatypeOf(self.node(self.workspace.operands[self.operand_count - 1]).value_type) != null) {
                    // `Self.Kind{}` through a `concrete_subtype` value (RFC-0081).
                    self.workspace.operands[self.operand_count - 1] = try self.constructThrough(self.workspace.operands[self.operand_count - 1], token);
                } else {
                    const operator: Operator = .{ .span = token.span, .kind = switch (token.kind) {
                        .plus => .add,
                        .minus => .subtract,
                        .star => .multiply,
                        .slash => .divide,
                        .equal_equal, .synthetic_case_equal => .equal,
                        .not_equal => .unequal,
                        .less => .less,
                        .less_equal => .less_equal,
                        .greater => .greater,
                        .greater_equal => .greater_equal,
                        .identifier => if (std.mem.eql(u8, token.span.text(self.workspace.source), "and")) .logical_and else if (std.mem.eql(u8, token.span.text(self.workspace.source), "or")) .logical_or else return self.workspace.fail(token.span, .unexpected_token),
                        else => return self.workspace.fail(token.span, .unexpected_token),
                    } };
                    // `A < B < C` (RFC-0076, D1): the comparison that is pending when another
                    // follows without parentheses is a link of a chain, and its right operand
                    // is the left operand of the next link.
                    var shared: u32 = no_member;
                    while (self.operator_count > self.operator_base and self.workspace.operators[self.operator_count - 1].precedence() >= operator.precedence()) {
                        const pending = &self.workspace.operators[self.operator_count - 1];
                        if (comparisonOperator(operator.kind) != null and comparisonOperator(pending.kind) != null) {
                            // A link whose conditional is open and still waits for the rest
                            // of the chain: the next link is read inside it.
                            if (pending.receiver) break;
                            shared = self.workspace.operands[self.operand_count - 1];
                            if (pending.selected == short_circuit) {
                                // The shared operand was evaluated inside this link's
                                // conditional, so the conditional stays open around the links
                                // that follow: it is compared here and closed when they are.
                                try self.compareLink(pending.*, shared);
                                pending.receiver = true;
                                break;
                            }
                            try self.applyOperator();
                            break;
                        }
                        try self.applyOperator();
                    }
                    if (token.kind == .synthetic_case_equal) try self.checkCaseScrutinee(self.workspace.operands[self.operand_count - 1], token.span);
                    if (operator.kind == .logical_and or operator.kind == .logical_or or shared != no_member) {
                        var lazy = operator;
                        lazy.method = shared;
                        // Where the main loop takes a line break for the end of the expression.
                        const in_body = w_anonymous: {
                            const frames = self.workspace.anonymous_frames[0..self.workspace.anonymous_count];
                            break :w_anonymous frames.len != 0 and frames[frames.len - 1].phase == .body;
                        };
                        try self.startShortCircuit(&lazy, self.blockDelimiter() or (parentheses == 0 and !in_body));
                        try self.pushOperator(lazy);
                    } else try self.pushOperator(operator);
                    expects_operand = true;
                }
            }
            while (self.operator_count > self.operator_base) try self.applyOperator();
            std.debug.assert(self.operand_count == self.operand_base + 1);
            std.debug.assert(self.workspace.operands[self.operand_base] < if (self.function != null) self.workspace.functions.node_count else self.workspace.node_count);
            return self.workspace.operands[self.operand_base];
        }

        /// At the start of a call argument: `Name := value` selects the parameter by name.
        /// Returns whether it consumed the `Name :=` prefix.
        fn namedArgument(self: *Self, token: Token) ParseError!bool {
            const w = self.workspace;
            if (self.operator_count <= self.operator_base) return false;
            const top = &w.operators[self.operator_count - 1];
            const method_call = top.kind == .invoke and top.method != no_member;
            // RFC-0085, I4: a direct call of a nested function names its declared parameters.
            const nested_call = top.kind == .recur and top.method != no_member;
            if ((top.kind != .call and !method_call and !nested_call) or self.operand_count != top.operand_base + top.arguments or top.head != no_member) return false;
            const named = token.kind == .identifier and w.tokens[self.cursor].kind == .colon and w.tokens[self.cursor + 1].kind == .equal and w.tokens[self.cursor].span.end == w.tokens[self.cursor + 1].span.start;
            if (!named) {
                if (top.tail != no_member) return w.fail(token.span, .named_argument_order);
                return false;
            }
            const text = token.span.text(w.source);
            // RFC-0091: the names of an inferred call's parameters are the template's, which
            // the call reads only once its arguments are known.
            if (top.kind == .call and top.infer) return w.fail(token.span, .type_inference);
            // A parameter name is no local of the caller (RFC-0083).
            if (w.localQualified(token.span.start)) return w.fail(token.span, .invalid_qualifier);
            const index: u32 = if (method_call) method_parameter: {
                // The declaration the receiver's static type sees names the parameters.
                const base = w.declarationOf(top.value_type.?, top.method) * types.limits.parameters;
                const shape = catalogue.definition(w.slots[top.method].callable, self.definitions()).?.callable;
                const parameters = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
                for (1..parameters.end - parameters.start) |position| {
                    if (std.mem.eql(u8, w.method_parameters[base + position].name.text(w.source), text)) break :method_parameter @intCast(position);
                }
                return w.fail(token.span, .unknown_parameter);
            } else if (nested_call) nested_parameter: {
                const entry = w.nested_functions[top.method];
                for (w.nested_capture_names[entry.captures.end..entry.parameters_end], 0..) |parameter_name, position| {
                    if (std.mem.eql(u8, parameter_name.text(w.source), text)) break :nested_parameter @intCast(position);
                }
                return w.fail(token.span, .unknown_parameter);
            } else for (self.callTarget(top.*).parameters[0..self.callTarget(top.*).parameter_count], 0..) |entry, position| {
                if (std.mem.eql(u8, entry.name.text(w.source), text)) break @intCast(position);
            } else return w.fail(token.span, .unknown_parameter);
            if (top.tail == no_member) top.tail = top.arguments;
            // A named argument is recorded in four bits, and sixteen of them fit.
            if (index > 0xf or top.arguments - top.tail >= 16) return w.fail(token.span, .parameter_limit);
            // Taken by a positional argument or an earlier named one.
            if (index < top.tail) return w.fail(token.span, .duplicate_argument);
            for (0..top.arguments - top.tail) |k| if (@as(u32, @intCast(top.names >> @intCast(4 * k) & 0xf)) == index) return w.fail(token.span, .duplicate_argument);
            top.head = index;
            self.cursor += 2;
            return true;
        }

        /// Records which parameter the argument that just ended belongs to.
        fn recordArgument(op: *Operator) void {
            if ((op.kind != .call and !(op.kind == .invoke and op.method != no_member) and !(op.kind == .recur and op.method != no_member)) or op.tail == no_member or op.arguments < op.tail) return;
            op.names |= @as(u64, op.head) << @intCast(4 * (op.arguments - op.tail));
            op.head = no_member;
        }

        fn expressionOperand(self: *Self, token: Token, parentheses: u32) ParseError!enum { sign, parenthesis, value, continuation, body, arm } {
            if (try self.namedArgument(token)) return .sign;
            switch (token.kind) {
                .synthetic_guard => {
                    try self.beginGuard(token, token.span, parentheses);
                    return .body;
                },
                // RFC-0084, P4.3: the guard of a variable whose type is a function, and the raw
                // value it reads.
                .synthetic_live_type => {
                    try self.beginLiveGuard(token, parentheses);
                    return .body;
                },
                .synthetic_live_raw => {
                    try self.pushOperand(try self.liveRawValue(token));
                    return .value;
                },
                .synthetic_attempt => {
                    _ = try self.take(.left_paren, .expected_call);
                    try self.startAttempt(token.span);
                    return .parenthesis;
                },
                .synthetic_false => {
                    try self.pushOperand(try self.emit(.{ .span = token.span, .value_type = .logic, .kind = .{ .boolean = false } }));
                    return .value;
                },
                .synthetic_first => {
                    // Only a mark for `failableCondition`: the expansion is the parenthesis after it.
                    const open = try self.take(.left_paren, .expected_call);
                    try self.pushOperator(.{ .kind = .open, .span = open.span, .operand_base = self.operand_count });
                    return .parenthesis;
                },
                .synthetic_exit => {
                    try self.startExit(token.span);
                    return .parenthesis;
                },
                // RFC-0082, P3.6: an arm ends with a pending exit; where its expression stands,
                // that exit's value.
                .synthetic_arm_exit => {
                    try self.startArmExit(token.span);
                    return .parenthesis;
                },
                .synthetic_arm_value => {
                    try self.pushOperand(try self.armValue(token.span));
                    return .value;
                },
                .synthetic_with_field => {
                    _ = try self.take(.left_paren, .expected_call);
                    try self.startWithField(token.span);
                    return .parenthesis;
                },
                // RFC-0084, P4.2: `set live E.F = G`, as the macro pass wrote it.
                .synthetic_live_field => {
                    _ = try self.take(.left_paren, .expected_call);
                    try self.pushOperator(.{ .kind = .with_field, .span = token.span, .operand_base = self.operand_count, .head = live_field_head });
                    return .parenthesis;
                },
                .synthetic_interpolate => {
                    _ = try self.take(.left_paren, .expected_call);
                    try self.pushOperator(.{ .kind = .convert, .span = token.span, .function = @backingInt(Conversion.interpolation), .operand_base = self.operand_count });
                    return .parenthesis;
                },
                .synthetic_with_index => {
                    _ = try self.take(.left_bracket, .expected_call);
                    // RFC-0087, P5.4: `set X[K] = V` of a keyed cell. The cell's name and the comma
                    // after it stand for the cell, which no operand holds.
                    if (self.keyed_set) |pending| if (pending.token + 2 == self.cursor) {
                        self.keyed_set = null;
                        self.cursor += 2;
                        try self.pushOperator(.{ .kind = .with_index, .span = token.span, .operand_base = self.operand_count, .selected = 1, .head = keyed_cell_head, .method = pending.cell });
                        return .parenthesis;
                    };
                    try self.startWithIndex(token.span);
                    return .parenthesis;
                },
                .synthetic_if => {
                    _ = try self.take(.left_paren, .expected_call);
                    try self.startConditional(token.span);
                    return .parenthesis;
                },
                .synthetic_require => {
                    // `Require[...]` as `startCall` opens it, placed by the rewrite of a guard
                    // inside its own attempt.
                    // A guard is always inside its attempt; a filter or a `Not[...]` stands
                    // where the user wrote it, which may be outside every failure context.
                    if (!self.failureContext()) return self.workspace.fail(token.span, .failure_context_required);
                    const context = self.expectedContext();
                    _ = try self.take(.left_bracket, .expected_call);
                    try self.pushOperator(.{ .kind = .demand, .span = token.span, .operand_base = self.operand_count, .value_type = context, .selected = 1 });
                    return .parenthesis;
                },
                .synthetic_fail => {
                    // The failure that ends a `Case[...]` (RFC-0080): a `Fail` without a reason,
                    // which has the type of the arms before it and needs a failure context.
                    if (!self.failureContext()) return self.workspace.fail(token.span, .failure_context_required);
                    try self.workspace.checkFailingArms(token.span);
                    const context = self.expectedContext() orelse return self.workspace.fail(token.span, .contextual_type_required);
                    const reason = try self.emit(.{ .span = token.span, .value_type = .string, .kind = .{ .string = .{ .start = 0, .end = 0 } } });
                    try self.pushOperand(try self.emit(.{ .span = token.span, .value_type = context, .kind = .{ .fail = reason } }));
                    return .value;
                },
                .synthetic_exhaustive => {
                    _ = try self.take(.left_paren, .expected_call);
                    try self.pushOperator(.{ .kind = .exhaustive, .span = token.span, .operand_base = self.operand_count });
                    return .parenthesis;
                },
                .plus, .minus => {
                    try self.pushOperator(.{ .kind = if (token.kind == .plus) .positive else .negative, .span = token.span });
                    return .sign;
                },
                .left_paren => {
                    try self.pushOperator(.{ .kind = .open, .span = token.span, .operand_base = self.operand_count });
                    return .parenthesis;
                },
                .identifier => {
                    if (self.operator_count > self.operator_base and self.workspace.operators[self.operator_count - 1].kind == .record and self.workspace.operators[self.operator_count - 1].delegation) {
                        try self.startDelegation(token);
                        return .parenthesis;
                    }
                    // RFC-0085, I3: a nested function header stands only at the start of a
                    // statement of a block (V7).
                    if (self.workspace.nestedHeaderAt(self.cursor - 1) != null) return self.workspace.fail(token.span, .nested_position);
                    if (std.mem.eql(u8, token.span.text(self.workspace.source), "not")) {
                        try self.pushOperator(.{ .kind = .logical_not, .span = token.span });
                        return .sign;
                    }
                    if (self.peek().kind == .left_brace and std.mem.eql(u8, token.span.text(self.workspace.source), "logic")) {
                        // `logic` names only the type elsewhere, so no program used this form.
                        self.cursor += 1;
                        try self.startLogic(token.span);
                        return .parenthesis;
                    }
                    if (std.mem.eql(u8, token.span.text(self.workspace.source), "Block")) {
                        _ = try self.take(.left_brace, .unexpected_token);
                        // Block reuses delimiter fields: function is the local
                        // scope base; head/tail/selected hold a pending name/type.
                        try self.pushOperator(.{ .kind = .block, .span = token.span, .operand_base = self.operand_count, .function = self.workspace.local_count, .value_type = self.expectedContext() });
                        return .parenthesis;
                    }
                    if (generatedName(token.span.text(self.workspace.source))) {
                        // Generated names are declared and read by library text only: a program
                        // cannot reach a macro's temporaries by spelling them.
                        if (self.workspace.libraryModule(token.span) == null) return self.workspace.fail(token.span, .unknown_name);
                        if (patternFormNamed(token.span.text(self.workspace.source))) |form| {
                            try self.startPatternForm(form);
                            return .parenthesis;
                        }
                    }
                    const resolved = try self.resolveName(token);
                    const name = resolved.token.span.text(self.workspace.source);
                    // RFC-0085, I3: a nested function in scope, called or as a value.
                    if (!resolved.qualified) if (self.findNested(name, token.span.start)) |entry| {
                        // RFC-0085, I11: a nested function is a local of the block that declares it.
                        // Of overloads, the one chosen is noted where it is chosen (I4).
                        if (self.nextOverload(entry) == null) self.workspace.noteName(token.span, self.workspace.nested_functions[entry].name.start, .local, qualify.none);
                        if (try self.nestedOperand(entry, resolved)) |opened| return if (opened) .parenthesis else .value;
                    };
                    if ((!resolved.qualified and (self.findLocal(name) != null or self.parameter(name) != null)) or self.workspace.findSymbolIn(name, resolved.scope) != null) {
                        // Existing value names shadow a template in expression scope.
                    } else if (self.findGeneric(name, resolved.scope)) |id| {
                        self.workspace.noteName(token.span, self.workspace.generic_templates[id].name.start, .global, qualify.none);
                        if (self.workspace.generic_templates[id].kind != .function) {
                            // `Box[i64]{...}` builds an instance and `Box[i64][Value]` casts to one.
                            const made = try self.instantiateNamed(id, resolved);
                            // Nothing is built through an alias, parametric or not (RFC-0074,
                            // RFC-0083); a cast through one is a cast to the type it names.
                            if (self.workspace.generic_templates[id].kind == .alias and self.peek().kind != .left_bracket) return self.workspace.fail(resolved.span, .unknown_name);
                            try self.startInstanceForm(made, resolved.span);
                            return .parenthesis;
                        }
                        // RFC-0091 (B3): without its type arguments, the arguments give them.
                        if (self.peek().kind == .left_paren and self.workspace.generic_templates[id].kind == .function) {
                            try self.startInferred(id, resolved);
                            return .parenthesis;
                        }
                        return if (try self.startGeneric(id, resolved, parentheses)) .continuation else .value;
                    }
                    // RFC-0081: `Value{}` builds through a `concrete_subtype` value, and a type
                    // written where a metatype is expected is a type value.
                    const is_value = (!resolved.qualified and (self.findLocal(name) != null or self.parameter(name) != null)) or self.workspace.findSymbolIn(name, resolved.scope) != null;
                    if (is_value and self.peek().kind == .left_brace and self.workspace.metatype_count != 0) {
                        const held = try self.literalName(resolved);
                        if (self.metatypeOf(self.node(held).value_type) != null) {
                            const open = try self.take(.left_brace, .unexpected_token);
                            try self.pushOperand(try self.constructThrough(held, open));
                            return .value;
                        }
                    }
                    if (!is_value and self.workspace.metatype_count != 0) switch (self.peek().kind) {
                        .left_brace, .left_bracket, .left_paren, .dot => {},
                        else => if (self.metatypeExpected()) |meta| {
                            try self.pushOperand(try self.typeValue(resolved, meta));
                            return .value;
                        },
                    };
                    if (self.peek().kind == .left_brace and !resolved.qualified and std.mem.eql(u8, name, "Spawn") and self.spawnForm(resolved.scope)) {
                        try self.beginSpawn(token, parentheses);
                        return .body;
                    }
                    if (self.peek().kind == .left_brace and !resolved.qualified and std.mem.eql(u8, name, "Branch") and self.branchForm(resolved.scope)) {
                        try self.beginBranch(token, parentheses);
                        return .body;
                    }
                    if (self.peek().kind == .left_brace and !resolved.qualified and std.mem.eql(u8, name, "Batch") and self.batchForm(resolved.scope)) {
                        try self.beginBatch(token, parentheses);
                        return .body;
                    }
                    // B4 (RFC-0092): `Super{...}` in a method builds a new instance of the
                    // superclass (Book 10:376), where nothing the program declares is `Super`.
                    if (self.peek().kind == .left_brace and !resolved.qualified and !is_value and std.mem.eql(u8, name, "Super")) if (try self.superArchetype(resolved)) |parent| {
                        try self.startInstanceForm(parent, resolved.span);
                        return .parenthesis;
                    };
                    if (self.peek().kind == .left_brace) {
                        if (!resolved.qualified and self.findLocal(resolved.token.span.text(self.workspace.source)) != null) return self.workspace.fail(resolved.span, .not_callable);
                        try self.startAggregate(resolved);
                        return .parenthesis;
                    }
                    // A value name before `[` is an element read, handled as a postfix access.
                    const value_name = (!resolved.qualified and (self.findLocal(name) != null or self.parameter(name) != null)) or self.workspace.findSymbolIn(name, resolved.scope) != null;
                    if (!value_name and !resolved.qualified and self.eventConstruction(token)) {
                        try self.pushOperand(try self.constructEvent(token));
                        return .value;
                    }
                    if (!value_name and !resolved.qualified and self.peek().kind == .left_paren) if (self.structuredForm(name, resolved.scope)) |form| {
                        try self.beginStructured(token, form, parentheses);
                        return .arm;
                    };
                    if (!value_name and !resolved.qualified and self.peek().kind == .left_paren) if (self.reactionForm(name, resolved.scope)) |form| {
                        try self.beginReaction(token, form, parentheses);
                        return .arm;
                    };
                    if (!value_name and !resolved.qualified and self.peek().kind == .left_paren and self.awaitForm(name, resolved.scope)) {
                        try self.beginAwait(token, parentheses);
                        return .arm;
                    }
                    if (self.peek().kind == .left_paren or (self.peek().kind == .left_bracket and !value_name)) {
                        return if (try self.startCall(resolved)) .parenthesis else .value;
                    }
                    // RFC-0087, P5.4 (W5): a keyed cell is read one key at a time, `X[K]`, and
                    // named in no other way.
                    if (value_name) if (self.keyedCell(resolved)) |cell| {
                        try self.keyedAccess(resolved);
                        if (self.peek().kind != .left_bracket) return self.workspace.fail(resolved.span, .weak_map_whole);
                        const open = try self.take(.left_bracket, .expected_call);
                        if (!self.failureContext()) return self.workspace.fail(open.span, .failure_context_required);
                        try self.stateEffect(resolved.span, .variable_read);
                        try self.pushOperator(.{ .kind = .index, .span = open.span, .function = no_member, .operand_base = self.operand_count, .selected = 1, .head = keyed_cell_head, .method = cell });
                        return .parenthesis;
                    };
                    try self.pushOperand(try self.literalName(resolved));
                    return .value;
                },
                .integer, .floating, .string, .escaped_string, .character => {
                    try self.pushOperand(try self.literal(token));
                    return .value;
                },
                else => return self.workspace.fail(token.span, .expected_expression),
            }
        }

        /// Opens a pattern form: `__case_is(Type, value)`, `__case_tuple(Last, value)`,
        /// `__case_some(value)`. What precedes the value is read here; the value is the operand.
        fn startPatternForm(self: *Self, form: Conversion) ParseError!void {
            const w = self.workspace;
            // The word lies in the library block; its parenthesis carries the span of the `Case`.
            const open = try self.take(.left_paren, .expected_call);
            var operator: Operator = .{ .kind = .convert, .span = open.span, .function = @backingInt(form), .operand_base = self.operand_count };
            switch (form) {
                .case_is, .case_as, .case_all => {
                    operator.value_type = try self.parseTypeValue();
                    _ = try self.take(.comma, .argument_count);
                },
                .case_tuple => {
                    const last = try self.take(.integer, .expected_tuple_index);
                    operator.head = std.fmt.parseInt(u32, last.span.text(w.source), 10) catch return w.fail(last.span, .tuple_index);
                    _ = try self.take(.comma, .argument_count);
                },
                else => {},
            }
            try self.pushOperator(operator);
        }

        /// The forms a `Case` pattern lowers to. None adds an operation of its own: a test is
        /// `instance_of`, `option_present` or the constant `true`, and a part is the operand
        /// itself, an `upcast`, a `downcast` or an `option_value`. The last two are not guarded
        /// by a `demand` here: the rewrite only places them where the matching test held for
        /// the same immutable temporary, and both machines trap a read that does not hold.
        fn emitPatternForm(self: *Self, form: Conversion, operator: Operator, operand: u32) ParseError!u32 {
            const w = self.workspace;
            const span = operator.span;
            const actual = self.node(operand).value_type;
            const shape = catalogue.definition(actual, self.definitions());
            switch (form) {
                .case_some, .case_none, .case_value => {
                    if (shape == null or shape.? != .option) return w.fail(self.node(operand).span, .type_mismatch);
                    if (form == .case_value) return self.emit(.{ .span = span, .value_type = shape.?.option, .kind = .{ .option_value = operand } });
                    const present = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .option_present = operand } });
                    if (form == .case_some) return present;
                    return self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .logic_not = present } });
                },
                .case_tuple => {
                    // A pattern names every element, so its last position is the tuple's.
                    if (shape == null or shape.? != .tuple or shape.?.tuple.end - shape.?.tuple.start != operator.head + 1) return w.fail(self.node(operand).span, .type_mismatch);
                    return operand;
                },
                .case_is, .case_as, .case_all => {
                    const target = operator.value_type.?;
                    const known = actual == target or catalogue.subtype(actual, target, self.definitions());
                    // A refinement is no type test's answer (RFC-0083): its values are its base's.
                    if (!known and catalogue.refinementOf(target, self.definitions()) != null) return w.fail(self.node(operand).span, .type_mismatch);
                    if (form == .case_is) try w.noteFailingTest(span, known, target);
                    // A total arm narrows only to what every value of the static type already is.
                    if (form == .case_all and !known) return w.fail(span, .case_not_exhaustive);
                    if (known) return if (form == .case_is) self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .boolean = true } }) else self.coerce(operand, target);
                    // RFC-0080: a value held as `any` is tested for any one type, not only a class.
                    if (actual == types.Type.any) {
                        if (form == .case_is) return self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .instance_of = .{ .value = operand, .class = target } } });
                        return self.emit(.{ .span = span, .value_type = target, .kind = .{ .downcast = operand } });
                    }
                    if (shape == null or shape.? != .class or !catalogue.castable(target, actual, self.definitions())) return w.fail(self.node(operand).span, .type_mismatch);
                    if (form == .case_is) return self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .instance_of = .{ .value = operand, .class = target } } });
                    return self.emit(.{ .span = span, .value_type = target, .kind = .{ .downcast = operand } });
                },
                else => unreachable,
            }
        }

        /// Opens `WithField(record, Field, value)`: a copy of `record` with one field replaced.
        fn startWithField(self: *Self, span: Span) ParseError!void {
            try self.pushOperator(.{ .kind = .with_field, .span = span, .operand_base = self.operand_count });
        }

        /// Opens `WithIndex[array, index, value]`: a copy of `array` with one element replaced.
        /// Like `Items[I]` it fails unless the index is within the array.
        fn startWithIndex(self: *Self, span: Span) ParseError!void {
            try self.pushOperator(.{ .kind = .with_index, .span = span, .operand_base = self.operand_count, .selected = 1 });
        }

        /// Opens `Without[map, key]`: a copy of `map` with the entry under `key` taken out and the
        /// others in their order. Like `M[K]` it fails when the key is absent, so it needs a failure
        /// context; `Attempt(Without[M, K], M)` is the form that never fails. It is the same
        /// operator as `WithIndex` with one argument fewer, and shares its bracket and its typing
        /// of the key.
        fn startWithout(self: *Self, span: Span) ParseError!void {
            try self.pushOperator(.{ .kind = .with_index, .span = span, .operand_base = self.operand_count, .selected = 1, .function = removal });
        }
        /// `Operator.function` of a `with_index` operator that removes instead of replacing.
        const removal: u32 = 1;

        fn emitWithout(self: *Self, operator: Operator, arguments: []const u32) ParseError!u32 {
            const w = self.workspace;
            if (arguments.len != 2) return w.fail(operator.span, .argument_count);
            const map = arguments[0];
            const span = operator.span;
            const shape = catalogue.definition(self.node(map).value_type, self.definitions()) orelse return w.fail(self.node(map).span, .type_mismatch);
            // RFC-0087: no entry is ever taken out of a `weak_map` (Q11).
            if (shape == .weak_map) return w.fail(self.node(map).span, .weak_map_operation);
            if (shape != .map) return w.fail(self.node(map).span, .type_mismatch);
            if (!self.failureContext()) return w.fail(span, .failure_context_required);
            const key = try self.coerce(arguments[1], shape.map.key);
            // Absence is an ordinary `demand`, exactly as for `M[K]`; the pure removal runs after it
            // and is handed what the lookup found, so the map is scanned once.
            const option_type = w.catalogue.internOption(shape.map.value) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            const found = try self.emit(.{ .span = span, .value_type = option_type, .kind = .{ .map_lookup = .{ .map = map, .key = key } } });
            const present = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .option_present = found } });
            _ = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .demand = present } });
            return self.emit(.{ .span = span, .value_type = self.node(map).value_type, .kind = .{ .map_remove = .{ .map = map, .key = found } } });
        }

        /// `ElementAt(Items, I)` reads element `I` without a failure context. It is total on
        /// every index the program has already proved (`If(I<Items.Length, ElementAt(Items, I), ...)`)
        /// and a fatal `index_out_of_range` error otherwise; prefer `Items[I]` in user code.
        /// `(scrutinee, pattern..., value)`: the value of the last arm of a `Case` without a default,
        /// once the patterns are seen to be every case of the scrutinee's enum, each exactly once.
        fn checkExhaustive(self: *Self, operator: Operator, arguments: []const u32) ParseError!u32 {
            const w = self.workspace;
            std.debug.assert(arguments.len >= 3);
            const scrutinee = self.node(arguments[0]).value_type;
            const shape = catalogue.definition(scrutinee, self.definitions()) orelse return w.fail(operator.span, .case_not_exhaustive);
            if (shape != .enumeration) return w.fail(operator.span, .case_not_exhaustive);
            if (shape.enumeration.is_open) return w.fail(operator.span, .open_enum_case);
            const cases = shape.enumeration.cases.end - shape.enumeration.cases.start;
            const patterns = arguments[1 .. arguments.len - 1];
            if (patterns.len != cases) return w.fail(operator.span, .case_not_exhaustive);
            var seen: std.StaticBitSet(types.limits.enum_cases) = .empty;
            for (patterns) |pattern| {
                const constant = self.node(pattern);
                if (constant.kind != .enumeration or constant.value_type != scrutinee) return w.fail(constant.span, .case_not_exhaustive);
                if (seen.isSet(constant.kind.enumeration)) return w.fail(constant.span, .case_not_exhaustive);
                seen.set(constant.kind.enumeration);
            }
            return arguments[arguments.len - 1];
        }

        fn emitElementAt(self: *Self, operator: Operator, arguments: []const u32) ParseError!u32 {
            const w = self.workspace;
            if (operator.function == 2) {
                // `KeyAt(NamedArray, Index)`: the array was recognised by name and skipped.
                if (arguments.len != 1) return w.fail(operator.span, .argument_count);
                if (self.node(arguments[0]).value_type != .i64) return w.fail(self.node(arguments[0]).span, .type_mismatch);
                return arguments[0];
            }
            if (arguments.len != 2) return w.fail(operator.span, .argument_count);
            const array = arguments[0];
            const index = arguments[1];
            if (self.node(array).value_type == .string) {
                // A loop over a string: its position is the byte position, its element the code unit there.
                if (self.node(index).value_type != .i64) return w.fail(self.node(index).span, .type_mismatch);
                if (operator.function == 1) return index;
                return self.emitText(operator.span, types.Type.char, .unit, .{ array, index, 0 });
            }
            const shape = catalogue.definition(self.node(array).value_type, self.definitions()) orelse return w.fail(self.node(array).span, .type_mismatch);
            // RFC-0087: a `weak_map` has no positions, so no loop walks one (03:1112).
            if (shape == .weak_map) return w.fail(self.node(array).span, .weak_map_operation);
            if (shape != .array and shape != .map) return w.fail(self.node(array).span, .type_mismatch);
            if (self.node(index).value_type != .i64) return w.fail(self.node(index).span, .type_mismatch);
            // `KeyAt` is what a loop calls its position: the index itself for an array, the key for a map.
            const keyed = operator.function == 1;
            if (shape == .map) return self.emit(.{ .span = operator.span, .value_type = if (keyed) shape.map.key else shape.map.value, .kind = if (keyed) .{ .map_key = .{ .array = array, .index = index } } else .{ .map_value = .{ .array = array, .index = index } } });
            if (keyed) return index;
            return self.emit(.{ .span = operator.span, .value_type = shape.array, .kind = .{ .array_get = .{ .array = array, .index = index } } });
        }

        fn emitWithIndex(self: *Self, operator: Operator, arguments: []const u32) ParseError!u32 {
            const w = self.workspace;
            if (operator.function == removal) return self.emitWithout(operator, arguments);
            // RFC-0087, P5.4: `set X[K] = V` of a keyed cell writes the entry, and yields `V`.
            if (operator.head == keyed_cell_head) {
                if (arguments.len != 2) return w.fail(operator.span, .argument_count);
                const entries = catalogue.entryShape(w.source_cells[operator.method].value_type, self.definitions()).?;
                const key = try self.coerce(arguments[0], entries.key);
                const value = try self.coerce(arguments[1], entries.value);
                return self.emit(.{ .span = operator.span, .value_type = entries.value, .kind = .{ .weak_set = .{ .cell = operator.method, .key = key, .value = value } } });
            }
            if (arguments.len != 3) return w.fail(operator.span, .argument_count);
            const array = arguments[0];
            var index = arguments[1];
            var value = arguments[2];
            const shape = catalogue.definition(self.node(array).value_type, self.definitions()) orelse return w.fail(self.node(array).span, .type_mismatch);
            const span = operator.span;
            // RFC-0087, W2: so does a `weak_map`, which `set W[K] = V` updates this way.
            if (catalogue.entryShape(self.node(array).value_type, self.definitions())) |entries| {
                // Updating a map adds or replaces an entry and cannot fail.
                index = try self.coerce(index, entries.key);
                value = try self.coerce(value, entries.value);
                return self.emit(.{ .span = span, .value_type = self.node(array).value_type, .kind = .{ .map_set = .{ .map = array, .key = index, .value = value } } });
            }
            if (shape != .array) return w.fail(self.node(array).span, .type_mismatch);
            if (!self.failureContext()) return w.fail(span, .failure_context_required);
            if (self.node(index).value_type != .i64) return w.fail(self.node(index).span, .type_mismatch);
            value = try self.coerce(value, shape.array);
            const length = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .array_length = array } });
            const zero = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .integer = 0 } });
            const lower = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .compare = .{ .op = .greater_equal, .lhs = index, .rhs = zero } } });
            const upper = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .compare = .{ .op = .less, .lhs = index, .rhs = length } } });
            const inside = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .logic_binary = .{ .op = .both, .lhs = lower, .rhs = upper } } });
            _ = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .demand = inside } });
            return self.emit(.{ .span = span, .value_type = self.node(array).value_type, .kind = .{ .array_set = .{ .array = array, .index = index, .value = value } } });
        }

        /// RFC-0084, P4.2: the field of `set live E.F = G`, read after `E`: a `var` field of a
        /// class instance that the code may assign. A live-only field is never assigned, and
        /// any other field is no live target. The guard that follows is the field's.
        fn liveFieldTarget(self: *Self, op: *Operator) ParseError!void {
            const w = self.workspace;
            const base = self.node(w.operands[op.operand_base]).value_type;
            const field = try self.take(.identifier, .expected_field);
            const shape = catalogue.definition(base, self.definitions()) orelse return w.fail(field.span, .live_target);
            if (shape != .class) return w.fail(field.span, .live_target);
            if (w.localQualified(field.span.start)) return w.fail(field.span, .invalid_qualifier);
            const index = catalogue.findField(base, field.span.text(w.source), self.definitions(), self.fields(), w.source) orelse {
                // A field of an interface lies in no cell the interface knows, nor does one with
                // accessors (RFC-0085, I8).
                if (w.findMethod(base, field.span.text(w.source)) != null or self.findAccessor(base, field.span.text(w.source)) != null) return w.fail(field.span, .live_target);
                return w.fail(field.span, .unknown_field);
            };
            const declared = catalogue.classFieldAt(base, index, self.definitions(), self.fields()).?;
            // RFC-0084, P4.3: a hidden raw field is no member, and an immutable form's raw value
            // is never assigned.
            if (self.liveTypeOfField(base, index)) |entry| {
                if (entry.hidden and entry.raw == index) return w.fail(field.span, .unknown_field);
                if (entry.fixed) return w.fail(field.span, .live_assigned);
            }
            try self.checkFieldAccess(base, index, field.span, false);
            if (declared.live_only) return w.fail(field.span, .live_assigned);
            if (!declared.is_var) return w.fail(field.span, .live_target);
            try self.checkFieldAccess(base, index, field.span, true);
            // It evaluates a guard, writes the field and builds a record: all three heap effects.
            try self.liveForm(field.span);
            try self.callEffect(field.span, .{ .reads = true, .writes = true, .allocates = true, .diverges = false });
            _ = w.catalogue.internLive(declared.value_type) catch |err| return w.fail(field.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            op.function = index;
            self.live_guard_type = declared.value_type;
            self.skipNewlines();
            _ = try self.take(.comma, .argument_count);
            self.skipNewlines();
        }
        fn emitWithField(self: *Self, operator: Operator, arguments: []const u32) ParseError!u32 {
            const w = self.workspace;
            if (arguments.len != 2) return w.fail(operator.span, .argument_count);
            if (operator.head == live_field_head) {
                // RFC-0084, P4.2: the guard is attached to the field of the instance.
                const field_type = catalogue.classFieldAt(self.node(arguments[0]).value_type, operator.function, self.definitions(), self.fields()).?.value_type;
                try self.takeGuard(arguments[1], field_type);
                return self.emit(.{ .span = operator.span, .value_type = field_type, .kind = .{ .object_live = .{ .object = arguments[0], .field = operator.function, .guard = arguments[1] } } });
            }
            const base = arguments[0];
            var value = arguments[1];
            const base_type = self.node(base).value_type;
            const record = (catalogue.definition(base_type, self.definitions()) orelse return w.fail(operator.span, .type_mismatch));
            if (operator.head == accessor_field_head) {
                // RFC-0085, I8: `set E.F = V` is `E.S(accessor, V)`. It needs `<writes>`, as
                // any assignment of a field, and the setter's effects.
                const entry = w.accessor_fields[operator.method];
                value = try self.coerce(value, entry.value_type);
                try self.stateEffect(operator.span, .set);
                const callable = w.slots[entry.setter].callable;
                const shape = catalogue.definition(callable, self.definitions()).?.callable;
                try self.callEffect(operator.span, shape.effects());
                var passed = [3]u32{ try self.coerce(base, entry.owner), try self.accessorValue(operator.span), value };
                const lookup = try self.emit(.{ .span = operator.span, .value_type = callable, .kind = .{ .method_value = .{ .receiver = passed[0], .slot = entry.setter } } });
                const range = try self.reserveArguments(&passed, operator.span);
                _ = try self.emit(.{ .span = operator.span, .value_type = shape.result, .kind = .{ .invoke = .{ .callable = lookup, .arguments = range } } });
                w.class_updates += 1;
                return base;
            }
            if (operator.method != no_member) {
                // The setter of an interface field: the instance's class writes its own cell.
                const setter = operator.method;
                std.debug.assert(record == .class and w.slot_kind[setter] == .setter);
                value = try self.coerce(value, w.slot_field[setter].value_type);
                try self.stateEffect(operator.span, .set);
                var pair = [2]u32{ try self.coerce(base, w.slots[setter].owner), value };
                const lookup = try self.emit(.{ .span = operator.span, .value_type = w.slots[setter].callable, .kind = .{ .method_value = .{ .receiver = pair[0], .slot = setter } } });
                const range = try self.reserveArguments(&pair, operator.span);
                _ = try self.emit(.{ .span = operator.span, .value_type = w.slot_field[setter].value_type, .kind = .{ .invoke = .{ .callable = lookup, .arguments = range } } });
                w.class_updates += 1;
                return base;
            }
            if (record == .class) {
                // An instance is updated in place and stays the same instance.
                const field = catalogue.classFieldAt(base_type, operator.function, self.definitions(), self.fields()).?;
                if (!field.is_var) return w.fail(operator.span, .not_mutable);
                value = try self.coerce(value, field.value_type);
                try self.stateEffect(operator.span, .set);
                _ = try self.emit(.{ .span = operator.span, .value_type = field.value_type, .kind = .{ .object_set = .{ .object = base, .index = operator.function, .value = value } } });
                w.class_updates += 1;
                return base;
            }
            if (record != .record) return w.fail(operator.span, .type_mismatch);
            const count = record.record.fields.end - record.record.fields.start;
            const replaced = operator.function;
            const field_type = catalogue.fieldAt(base_type, replaced, self.definitions(), self.fields()).?.value_type;
            value = try self.coerce(value, field_type);
            var members: [types.limits.record_fields]u32 = undefined;
            for (0..count) |index| {
                if (index == replaced) {
                    members[index] = value;
                    continue;
                }
                const kept = catalogue.fieldAt(base_type, @intCast(index), self.definitions(), self.fields()).?.value_type;
                members[index] = try self.emit(.{ .span = operator.span, .value_type = kept, .kind = .{ .field = .{ .value = base, .index = @intCast(index) } } });
            }
            const range = try self.reserveMembers(count, operator.span);
            @memcpy(self.memberPool()[range.start..range.end], members[0..count]);
            return self.emit(.{ .span = operator.span, .value_type = base_type, .kind = .{ .aggregate = range } });
        }

        /// Opens an `If` whose `(` was just consumed.
        fn startConditional(self: *Self, span: Span) ParseError!void {
            const w = self.workspace;
            var depth: usize = 0;
            for (w.operators[self.operator_base..self.operator_count]) |op| if (op.kind == .conditional or op.kind == .attempt) {
                depth += 1;
            };
            if (depth == types.limits.control_depth) return w.fail(span, .control_limit);
            // `names`, which a conditional does not use otherwise, holds what the condition is
            // known by (`Workspace.conditionPlace`), zero if by nothing.
            try self.pushOperator(.{ .kind = .conditional, .span = span, .operand_base = self.operand_count, .value_type = self.expectedContext(), .selected = no_member, .names = w.conditionPlace(span, w.tokens[self.cursor].span) });
        }

        /// Opens an `Attempt` region whose `(` was just consumed.
        fn startAttempt(self: *Self, span: Span) ParseError!void {
            const w = self.workspace;
            var depth: usize = 0;
            for (w.operators[self.operator_base..self.operator_count]) |op| if (op.kind == .conditional or op.kind == .attempt) {
                depth += 1;
            };
            if (depth == types.limits.control_depth) return w.fail(span, .control_limit);
            var op: Operator = .{ .kind = .attempt, .span = span, .operand_base = self.operand_count, .value_type = self.expectedContext() };
            // What can fail inside the body is caught here: it does not make the expression
            // around the attempt failable, so the count is put back when the body ends.
            op.tail = w.failable_uses;
            if (w.firstRegion(span)) op.names = caught_first;
            op.head = try self.saveLocalVersions(span);
            op.function = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .attempt_begin = .{ .condition = no_member, .alternative = no_member, .end = no_member } } });
            try self.pushOperator(op);
        }

        fn startCall(self: *Self, resolved: Name) ParseError!bool {
            const token = resolved.token;
            const w = self.workspace;
            const name = token.span.text(w.source);
            if (!resolved.qualified and std.mem.eql(u8, name, "Bind")) {
                _ = try self.take(.left_paren, .expected_call);
                self.skipNewlines();
                try self.pushOperator(.{ .kind = .bind, .span = resolved.span, .operand_base = self.operand_count });
                return true;
            }
            if (!resolved.qualified and std.mem.eql(u8, name, "Loop")) {
                _ = try self.take(.left_paren, .expected_call);
                self.skipNewlines();
                try self.pushOperator(.{ .kind = .loop, .span = resolved.span, .operand_base = self.operand_count });
                return true;
            }
            if (!resolved.qualified and std.mem.eql(u8, name, "Iterate")) {
                _ = try self.take(.left_paren, .expected_call);
                self.skipNewlines();
                const saved_cursor = self.cursor;
                if (self.peek().kind == .identifier) {
                    const step_token = try self.take(.identifier, .expected_name);
                    const step = try self.resolveName(step_token);
                    const step_name = step.token.span.text(w.source);
                    self.skipNewlines();
                    const shadowed = (!step.qualified and (self.findLocal(step_name) != null or self.parameter(step_name) != null)) or w.findSymbolIn(step_name, step.scope) != null;
                    const own = !step.qualified and !self.default_expression and self.function != null and std.mem.eql(u8, step_name, self.function.?.name.text(w.source));
                    if (!shadowed and !own and self.peek().kind == .comma) if (w.functions.findIn(step_name, w.source, step.scope)) |id| {
                        const f = w.functions.definitions[id];
                        if (!self.visible(f.name) or f.is_extension) return w.fail(step.span, .unknown_name);
                        if (step.sealed() and !f.is_public) return w.fail(step.span, .private_name);
                        w.noteName(step.token.span, f.name.start, .global, qualify.none);
                        if (f.is_constructor and self.abstractClass(f.value_type)) return w.fail(step.span, .abstract_instance);
                        if (f.parameter_count != 1) return w.fail(step.span, .argument_count);
                        if (f.parameters[0].value_type != f.value_type) return w.fail(step.span, .type_mismatch);
                        try self.callEffect(step.span, Effect.of(f).set());
                        if (f.decides and !self.failureContext()) return w.fail(step.span, .failure_context_required);
                        var target = f.runtime orelse f.alias_runtime;
                        if (target == null) {
                            target = w.runtime_functions.publishAlias(f, &w.functions, self.definitions(), w.bindings[0..w.binding_count], w.binding_cells[0..w.binding_count], w.node_count) catch |err| return w.fail(step.span, switch (err) {
                                error.FunctionLimit => .function_limit,
                                error.NodeLimit => .template_limit,
                                error.MemberLimit => .aggregate_limit,
                                error.ArgumentLimit => .call_argument_limit,
                                error.GlobalLimit => .binding_limit,
                            });
                            if (target == null) return w.fail(step.span, .not_callable);
                            w.functions.definitions[id].alias_runtime = target;
                        }
                        self.skipNewlines();
                        _ = try self.take(.comma, .argument_count);
                        self.skipNewlines();
                        try self.pushOperator(.{ .kind = .iterate, .span = resolved.span, .function = target.?, .operand_base = self.operand_count, .value_type = f.value_type });
                        return true;
                    };
                }
                self.cursor = saved_cursor;
                try self.pushOperator(.{ .kind = .iterate_value, .span = resolved.span, .operand_base = self.operand_count });
                return true;
            }
            if (!resolved.qualified and std.mem.eql(u8, name, "Set")) {
                _ = try self.take(.left_paren, .expected_call);
                const target_token = try self.take(.identifier, .expected_name);
                const target = try self.resolveName(target_token);
                const assignment = try self.assignmentTarget(target);
                _ = try self.take(.comma, .argument_count);
                self.skipNewlines();
                try self.pushOperator(.{ .kind = if (assignment == .local) .set_local_value else .set_value, .span = resolved.span, .function = switch (assignment) {
                    .cell => |n| n,
                    .local => |n| n,
                    .ref => |n| n,
                    .noted => 0,
                }, .operand_base = self.operand_count, .value_type = self.assignmentType(assignment), .selected = switch (assignment) {
                    .ref => set_ref,
                    .noted => set_noted,
                    .cell, .local => no_member,
                } });
                return true;
            }
            if (!resolved.qualified and std.mem.eql(u8, name, "Return")) {
                try self.startExit(token.span);
                return true;
            }
            if (!resolved.qualified and std.mem.eql(u8, name, "Err")) {
                // A runtime error: no failure context catches it, so it needs none.
                const context = self.expectedContext() orelse .logic;
                _ = try self.take(.left_paren, .expected_call);
                try self.pushOperator(.{ .kind = .err, .span = token.span, .operand_base = self.operand_count, .value_type = context });
                return true;
            }
            // The macro pass resolves every `Break` that has a `Loop{}` to leave. One with none in
            // an arm, or in a task's body, would leave that (RFC-0082).
            if (!resolved.qualified and std.mem.eql(u8, name, "Break")) return w.fail(token.span, if (self.reactionArm()) .return_in_task_body else if (self.armBody()) .exit_in_arm else if (self.taskBody()) .return_in_task_body else .break_outside_loop);
            if (!resolved.qualified and (std.mem.eql(u8, name, "If") or std.mem.eql(u8, name, "Attempt") or std.mem.eql(u8, name, "Require") or std.mem.eql(u8, name, "Fail"))) {
                const kind: @FieldType(Operator, "kind") = if (std.mem.eql(u8, name, "If")) .conditional else if (std.mem.eql(u8, name, "Attempt")) .attempt else if (std.mem.eql(u8, name, "Require")) .demand else .fail;
                const context = self.expectedContext();
                if ((kind == .demand or kind == .fail) and !self.failureContext()) return w.fail(token.span, .failure_context_required);
                if (kind == .fail and context == null) return w.fail(token.span, .contextual_type_required);
                _ = try self.take(if (kind == .demand or kind == .fail) .left_bracket else .left_paren, .expected_call);
                if (kind == .conditional or kind == .attempt) {
                    var depth: usize = 0;
                    for (w.operators[self.operator_base..self.operator_count]) |op| if (op.kind == .conditional or op.kind == .attempt) {
                        depth += 1;
                    };
                    if (depth == types.limits.control_depth) return w.fail(token.span, .control_limit);
                }
                if (kind == .attempt) {
                    try self.startAttempt(token.span);
                    if (w.forRegion(token.span)) w.operators[self.operator_count - 1].for_site = token.site;
                    return true;
                }
                if (kind == .conditional) {
                    try self.startConditional(token.span);
                    return true;
                }
                try self.pushOperator(.{ .kind = kind, .span = token.span, .operand_base = self.operand_count, .value_type = context, .selected = if (kind == .demand or kind == .fail) 1 else no_member });
                return true;
            }
            if (!resolved.qualified and (std.mem.eql(u8, name, "ElementAt") or std.mem.eql(u8, name, "KeyAt"))) {
                _ = try self.take(.left_paren, .expected_call);
                var mode: u32 = @intFromBool(std.mem.eql(u8, name, "KeyAt"));
                if (mode == 1 and self.peek().kind == .identifier and w.tokens[self.cursor + 1].kind == .comma) {
                    // An array's position is the index itself. A named array is not evaluated at
                    // all, so a loop over an array pays nothing for also working on maps.
                    const subject = self.peek().span.text(w.source);
                    const subject_type: ?types.Type = if (self.findLocal(subject)) |index| self.localType(index) else if (self.parameter(subject)) |index| self.parameterType(index) else if (w.findSymbolIn(subject, w.scope())) |binding| w.bindings[binding].value_type else null;
                    const shape = if (subject_type) |known| catalogue.definition(known, self.definitions()) else null;
                    if ((shape != null and shape.? == .array) or (subject_type != null and subject_type.? == .string)) {
                        self.cursor += 2;
                        mode = 2;
                    }
                }
                try self.pushOperator(.{ .kind = .element_at, .span = token.span, .operand_base = self.operand_count, .function = mode });
                return true;
            }
            if (!resolved.qualified and std.mem.eql(u8, name, "WithIndex")) {
                _ = try self.take(.left_bracket, .expected_call);
                try self.startWithIndex(token.span);
                return true;
            }
            if (!resolved.qualified and std.mem.eql(u8, name, "Without")) {
                _ = try self.take(.left_bracket, .expected_call);
                try self.startWithout(token.span);
                return true;
            }
            if (!resolved.qualified and std.mem.eql(u8, name, "WithField")) {
                _ = try self.take(.left_paren, .expected_call);
                try self.startWithField(token.span);
                return true;
            }
            // B4 (RFC-0092): `GetCastableFinalSuperClass[Base, Instance]`, unless the program names
            // something so; the base is a type, the instance an expression.
            if (!resolved.qualified and std.mem.eql(u8, name, "GetCastableFinalSuperClass") and self.peek().kind == .left_bracket and !self.declaredCallee(name, resolved.scope) and !self.classMemberNamed(name)) {
                w.noteName(token.span, qualify.none, .builtin, qualify.none);
                if (!self.failureContext()) return w.fail(token.span, .failure_context_required);
                _ = try self.take(.left_bracket, .expected_call);
                self.skipNewlines();
                const base = try self.parseTypeValue();
                self.skipNewlines();
                _ = try self.take(.comma, .argument_count);
                try self.pushOperator(.{ .kind = .convert, .span = token.span, .function = @backingInt(Conversion.final_super_class), .operand_base = self.operand_count, .selected = 1, .value_type = base });
                return true;
            }
            // A class that is declared late (RFC-0073) is a cast target above its declaration too,
            // like a class the pre-pass reserved: naming it reserves it (`findNominal`).
            if (self.peek().kind == .left_bracket and w.functions.findIn(name, w.source, resolved.scope) == null) if (try self.findNominal(name, resolved.scope, resolved.span)) |class_type| {
                // `Class[value]` converts to a class: always for a superclass value, and when the
                // instance really is one for a subclass.
                // A struct or an enum is a cast target too, for a value held as `any` (RFC-0080).
                const item = catalogue.definition(class_type, self.definitions()).?;
                const declared = catalogue.declaredName(item) orelse return w.fail(resolved.span, .unknown_name);
                if (!self.visible(declared)) return w.fail(resolved.span, .unknown_name);
                if (resolved.sealed() and !catalogue.declaredPublic(item)) return w.fail(resolved.span, .private_name);
                w.noteName(token.span, declared.start, .global, qualify.none);
                _ = try self.take(.left_bracket, .expected_call);
                try self.pushOperator(.{ .kind = .convert, .span = token.span, .function = @backingInt(Conversion.cast), .operand_base = self.operand_count, .selected = 1, .value_type = class_type });
                return true;
            };
            // RFC-0053, B5: `ToString` that a `using` brought in (no module path was written) is the same `ToString`.
            const brought = resolved.qualified and resolved.span.start == token.span.start and std.mem.eql(u8, name, "ToString");
            if ((!resolved.qualified or brought) and conversionNamed(name) != null) {
                // `emitConvert` notes `ToString`: it is the builtin or a function of the program.
                if (!std.mem.eql(u8, name, "ToString")) w.noteName(token.span, qualify.none, .builtin, qualify.none);
                const conversion = conversionNamed(name).?;
                // `Floor(R)` and `Ceil(R)` of a rational are total and take parentheses; the
                // bracket forms keep meaning the failable conversions of a float.
                const failable = conversion != .float and conversion != .string and !((conversion == .floor or conversion == .ceil) and self.peek().kind == .left_paren);
                if (failable and !self.failureContext()) return w.fail(token.span, .failure_context_required);
                _ = try self.take(if (failable) .left_bracket else .left_paren, .expected_call);
                try self.pushOperator(.{ .kind = .convert, .span = token.span, .function = @backingInt(conversion), .operand_base = self.operand_count, .selected = if (failable) 1 else no_member });
                return true;
            }
            if (!resolved.qualified and std.mem.eql(u8, name, "string") and self.peek().kind == .left_bracket) {
                // `string[Units]` converts a `[]char`, as `Class[value]` converts an instance.
                if (!self.failureContext()) return w.fail(token.span, .failure_context_required);
                w.noteName(token.span, qualify.none, .builtin, qualify.none);
                _ = try self.take(.left_bracket, .expected_call);
                try self.pushOperator(.{ .kind = .convert, .span = token.span, .function = @backingInt(Conversion.units), .operand_base = self.operand_count, .selected = 1 });
                return true;
            }
            if (self.peek().kind == .left_bracket and !std.mem.eql(u8, name, "string")) if (try self.castTarget(resolved)) |target| {
                _ = try self.take(.left_bracket, .expected_call);
                try self.pushOperator(.{ .kind = .convert, .span = token.span, .function = @backingInt(Conversion.cast), .operand_base = self.operand_count, .selected = 1, .value_type = target });
                return true;
            };
            if (!resolved.qualified and (std.mem.eql(u8, name, "Lookup") or std.mem.eql(u8, name, "Or"))) {
                _ = try self.take(.left_paren, .expected_call);
                try self.pushOperator(.{ .kind = if (std.mem.eql(u8, name, "Lookup")) .lookup else .option_or, .span = token.span, .operand_base = self.operand_count });
                return true;
            }
            if (!resolved.qualified) if (divisionNamed(name)) |form| if (!self.declaredCallee(name, resolved.scope)) {
                w.noteName(token.span, qualify.none, .builtin, qualify.none);
                const failable = form != .to_rational;
                if (failable and !self.failureContext()) return w.fail(token.span, .failure_context_required);
                _ = try self.take(if (failable) .left_bracket else .left_paren, .expected_call);
                try self.pushOperator(.{ .kind = .convert, .span = token.span, .function = @backingInt(form), .operand_base = self.operand_count, .selected = if (failable) 1 else no_member });
                return true;
            };
            // `i64(X)` and `float(X)` (RFC-0083): the type names are reserved, so nothing a
            // program declares can mean them, and before this they were `not_callable`.
            if (!resolved.qualified and self.peek().kind == .left_paren and (std.mem.eql(u8, name, "i64") or std.mem.eql(u8, name, "float"))) {
                w.noteName(token.span, qualify.none, .builtin, qualify.none);
                return self.openStd(if (name[0] == 'i') .to_base_int else .to_base_float, no_member, token);
            }
            // `Module.ToString(Value)` names the function a module declares.
            if (reserved(name) and !(resolved.qualified and std.mem.eql(u8, name, "ToString"))) return w.fail(token.span, .not_callable);
            if ((!resolved.qualified and (self.findLocal(name) != null or self.parameter(name) != null)) or w.findSymbolIn(name, resolved.scope) != null) {
                try self.pushOperand(try self.literalName(resolved));
                return false; // Leave '(' for the checked tuple-selection path.
            }
            if (!resolved.qualified) if (w.findNativeIn(name, resolved.scope)) |binding| {
                if (!self.visible(w.native_bindings[binding].name)) return w.fail(resolved.span, .unknown_name);
                w.noteName(token.span, w.native_bindings[binding].name.start, .global, qualify.none);
                _ = try self.take(.left_paren, .expected_call);
                try self.pushOperator(.{ .kind = .native_call, .span = resolved.span, .function = binding, .operand_base = self.operand_count });
                return true;
            };
            if (!resolved.qualified and !self.default_expression) if (self.function) |function| {
                // A bare call never reaches a method (W2 round 2, N-1), its own included: a
                // method recurs through `Self.Name(...)`, which dispatches, and a bare call of its
                // name chooses among the functions like every other one.
                if (!function.is_extension and !function.is_method and std.mem.eql(u8, name, function.name.text(w.source))) {
                    if (function.is_constructor and self.abstractClass(function.value_type)) return w.fail(resolved.span, .abstract_instance);
                    // Its result type is not known while its body is compiled (RFC-0085, I7).
                    if (function.is_transparent) return w.fail(resolved.span, .transparent_recursion);
                    w.noteName(token.span, function.name.start, if (self.ownNested() != no_member) .local else .global, qualify.none);
                    try self.callEffect(resolved.span, Effect.of(function).set());
                    if (function.decides and !self.failureContext()) return w.fail(resolved.span, .failure_context_required);
                    _ = try self.take(if (function.decides) .left_bracket else .left_paren, .expected_call);
                    try self.pushOperator(.{ .kind = .recur, .span = resolved.span, .operand_base = self.operand_count, .selected = if (function.decides) 1 else no_member });
                    return true;
                }
            };
            // An extension method is named only after a receiver, `Value.Name(...)`, so it leaves
            // the bare name what it was: an intrinsic, or unknown.
            const function = w.plainFunctionIn(name, resolved.scope) orelse {
                // RFC-0091 (B3): a module function declared further down, called from a body.
                if (try self.forwardCall(token, resolved, name)) return true;
                // Nothing the program defines has this name, so `BitAnd(A, B)` is the intrinsic.
                // Inside a class that has a member of the name it is not: a member is reached
                // through `Self`, and the bare name stays the unknown name it was, rather than
                // quietly meaning something other than the member the reader sees.
                if (!resolved.qualified and self.peek().kind == .left_paren and !self.memberNamed(name)) if (bitwiseNamed(name)) |operation| {
                    // One name, one meaning in a scope (RFC-0077 "Names"): a declaration of
                    // it further down is what it means here too, and that is not in reach yet.
                    if (self.stdDeclared(stdlib.bit_base + @as(u32, @backingInt(operation) - @backingInt(Conversion.bit_and)), name, null)) return w.fail(resolved.span, .unknown_name);
                    w.noteName(token.span, qualify.none, .builtin, qualify.none);
                    _ = try self.take(.left_paren, .expected_call);
                    try self.pushOperator(.{ .kind = .convert, .span = token.span, .function = @backingInt(operation), .operand_base = self.operand_count });
                    return true;
                };
                // So for the standard functions (RFC-0077): `Sqrt(X)` when nothing else is `Sqrt`.
                if (!resolved.qualified and (self.peek().kind == .left_paren or (self.peek().kind == .left_bracket and stdFails(name))) and !self.memberNamed(name) and !self.declaredCallee(name, resolved.scope)) if (stdlib.function(name)) |form| {
                    if (self.stdDeclared(@backingInt(form), name, null)) return w.fail(resolved.span, .unknown_name);
                    w.noteName(token.span, qualify.none, .builtin, qualify.none);
                    return self.openStd(form, no_member, token);
                };
                return w.fail(resolved.span, .unknown_name);
            };
            // An overload is noted where its arguments pick it (`expandCall`).
            if (!w.functions.definitions[function].overloaded) w.noteName(token.span, w.functions.definitions[function].name.start, .global, qualify.none);
            if (!self.visible(w.functions.definitions[function].name)) return w.fail(resolved.span, .unknown_name);
            if (resolved.sealed() and !w.functions.definitions[function].is_public) return w.fail(resolved.span, .private_name);
            if (!w.functions.definitions[function].overloaded) try self.callEffect(resolved.span, Effect.of(w.functions.definitions[function]).set());
            const decides = w.functions.definitions[function].decides;
            if (decides and !self.failureContext()) return w.fail(resolved.span, .failure_context_required);
            _ = try self.take(if (decides) .left_bracket else .left_paren, .expected_call);
            try self.pushOperator(.{ .kind = .call, .span = resolved.span, .function = function, .operand_base = self.operand_count, .selected = if (decides) 1 else no_member });
            return true;
        }

        /// Whether the class whose method is being compiled has a field or method `name`, its
        /// own or inherited.
        fn memberNamed(self: *const Self, name: []const u8) bool {
            const w = self.workspace;
            const class = self.method_class orelse return false;
            return w.findMethod(class, name) != null or catalogue.findField(class, name, self.definitions(), self.fields(), w.source) != null;
        }

        fn reduceToDelimiter(self: *Self, token: Token) ParseError!*Operator {
            while (self.operator_count > self.operator_base) {
                const operator = &self.workspace.operators[self.operator_count - 1];
                if (operator.precedence() == 0) return operator;
                try self.applyOperator();
            }
            return self.workspace.fail(token.span, .unexpected_token);
        }

        /// Asked wherever something that can fail is parsed, and only there: the count is how
        /// `logic{...}` knows that its expression can fail.
        fn failureContext(self: *const Self) bool {
            // Something that can fail stands here and needs a context. Where there is none, the
            // condition of an `If` it stands in becomes one (RFC-0049): only this need does
            // that, never a question (`failureContextHere`).
            // RFC-0076: the condition of an `If` is a failure context of its own wherever it
            // stands, so one that is nearer than every other context is asked first.
            if (self.conditionNearer() and self.wantCondition()) return true;
            return self.failureContextHere() or self.wantCondition() or self.workspace.wantFor();
        }

        /// Whether the condition of an `If` that can be made failable is open and nearer than
        /// every failure context, every `option{...}` that may catch and every `Defer` copy.
        fn conditionNearer(self: *const Self) bool {
            var index = self.operator_count;
            while (index > self.operator_base) {
                index -= 1;
                const op = self.workspace.operators[index];
                if (op.kind == .conditional and op.arguments == 0 and op.names != 0) return true;
                if (op.kind == .option and op.names == open_option) return false;
                if (op.kind == .attempt and op.arguments == 0) return false;
                if (op.kind == .block and self.deferredBlock(index)) return false;
            }
            return false;
        }

        /// Whether a failure here would be caught, as it was decided before a lone unwrap
        /// could make a condition failable. A generated loop function asks this to learn
        /// its effect, and learns what it always did: the question changes no condition.
        fn failureContextHere(self: *const Self) bool {
            const w = self.workspace;
            w.failable_uses += 1;
            // An `option{...}` that is nearer than every failure context catches first
            // (RFC-0076): it is noted, and the next compile gives it its region.
            if (self.optionNearer() and w.wantOption()) {
                w.defer_barrier = false;
                return true;
            }
            if (self.insideFailureContext()) return true;
            // Deferred code cannot fail (RFC-0068), so an `option{...}` around the `Defer` is not
            // made to catch what a copy of its body lets out; one inside the copy is (RFC-0072).
            if (w.defer_barrier and !self.optionInDeferred()) return false;
            if (!w.wantOption()) return false;
            w.defer_barrier = false;
            return true;
        }

        /// Whether what is being parsed stands in the condition of an `If` of this function
        /// body that can be made a failable condition (`Workspace.wantCondition`). The nearest
        /// condition is the one: a branch of an inner `If` is still inside the outer condition.
        /// A `Defer` body cuts its copy off from what is around it, and a constructor that
        /// `wantOption` just declined to make catch is left as it was.
        fn wantCondition(self: *const Self) bool {
            const w = self.workspace;
            var index = self.operator_count;
            while (index > self.operator_base) {
                index -= 1;
                const op = w.operators[index];
                if (op.kind == .block and self.deferredBlock(index)) return false;
                if (op.kind == .option and op.names == open_option) return false;
                if (op.kind != .conditional or op.arguments != 0 or op.names == 0) continue;
                if (!w.wantCondition(op.names)) return false;
                w.defer_barrier = false;
                return true;
            }
            return false;
        }
        fn insideFailureContext(self: *const Self) bool {
            const w = self.workspace;
            w.defer_barrier = false;
            // From the innermost outwards: deferred code cannot fail, so a `Defer` body ends the
            // search unless a region of its own catches the failure first.
            var index = self.operator_count;
            while (index > self.operator_base) {
                index -= 1;
                const op = w.operators[index];
                if (op.kind == .attempt and op.arguments == 0) return true;
                if (op.kind == .block and self.deferredBlock(index)) {
                    w.defer_barrier = true;
                    return false;
                }
            }
            return if (self.function) |f| f.decides else false;
        }

        /// Whether an `option{...}` that may still be made to catch stands between this point
        /// and the nearest failure context of this function body, or its nearest `Defer` copy.
        fn optionNearer(self: *const Self) bool {
            var index = self.operator_count;
            while (index > self.operator_base) {
                index -= 1;
                const op = self.workspace.operators[index];
                if (op.kind == .option and op.names == open_option) return true;
                if (op.kind == .attempt and op.arguments == 0) return false;
                if (op.kind == .block and self.deferredBlock(index)) return false;
            }
            return false;
        }

        /// Whether an `option{...}` that may still be made to catch (`wantOption`) was opened
        /// inside the innermost copy of a `Defer` body.
        fn optionInDeferred(self: *const Self) bool {
            var index = self.operator_count;
            while (index > self.operator_base) {
                index -= 1;
                const op = self.workspace.operators[index];
                if (op.kind == .option and op.names == open_option) return true;
                if (op.kind == .block and self.deferredBlock(index)) return false;
            }
            return false;
        }

        /// An attempt the compiler opened for `logic{...}` or for an `option{...}` that catches;
        /// the mark is in `Operator.names`, which an attempt does not use otherwise.
        const caught_logic: u64 = 1;
        const caught_option: u64 = 2;
        /// An `option{...}` that is on the `option_open` stack.
        const open_option: u64 = 3;
        /// The attempt around an iteration of a `First[...]`.
        const caught_first: u64 = 4;
        /// The attempt around the guard of an `Upon` or a `When` (RFC-0084, P4.4).
        const caught_guard: u64 = 5;

        /// What an `option{...}` at this point stands in: no failure context, one that programs
        /// could write before RFC-0072 (an `Attempt` body, a condition, an iteration of a `For`,
        /// a `<decides>` function), or one that RFC introduced (`logic{...}`, `First[...]`, an
        /// `option{...}` that catches). The nearest one decides.
        fn optionContext(self: *const Self) enum { none, earlier, caught } {
            var index = self.operator_count;
            while (index > self.operator_base) {
                index -= 1;
                const op = self.workspace.operators[index];
                if (op.kind == .attempt and op.arguments == 0) return if (op.names == caught_logic or op.names == caught_option or op.names == caught_first or op.names == caught_guard) .caught else .earlier;
                // A copy of a `Defer` body is cut off from the contexts around it (RFC-0068).
                if (op.kind == .block and self.deferredBlock(index)) return .none;
            }
            if (self.function) |f| if (f.decides) return .earlier;
            return .none;
        }

        /// `logic{E}` (RFC-0072) is `Attempt(Block{E; true}, false)`: `true` when `E` succeeds,
        /// `false` when it fails, with what a failed `E` wrote undone. The `{` is consumed.
        fn startLogic(self: *Self, span: Span) ParseError!void {
            const w = self.workspace;
            try self.startAttempt(span);
            const attempt = &w.operators[self.operator_count - 1];
            attempt.names = caught_logic;
            try self.pushOperator(.{ .kind = .block, .span = span, .operand_base = self.operand_count, .function = w.local_count });
        }

        /// The block of a `logic{...}` has closed and its value is on the operand stack.
        fn finishLogic(self: *Self, token: Token) ParseError!void {
            const w = self.workspace;
            const attempt = w.operators[self.operator_count - 1];
            std.debug.assert(attempt.kind == .attempt and attempt.names == caught_logic and attempt.arguments == 0);
            std.debug.assert(self.operand_count == attempt.operand_base + 1);
            // The Book rejects `logic{0}`: the expression must at least be able to fail.
            if (w.failable_uses == attempt.tail) return w.fail(attempt.span, .failure_expected);
            // The value of the expression is dropped; only whether it succeeded counts.
            w.operands[self.operand_count - 1] = try self.emit(.{ .span = attempt.span, .value_type = .logic, .kind = .{ .boolean = true } });
            try self.finishArgument(token);
            try self.pushOperand(try self.emit(.{ .span = attempt.span, .value_type = .logic, .kind = .{ .boolean = false } }));
            try self.closeParenthesis(token, false);
        }
        fn finishArgument(self: *Self, token: Token) ParseError!void {
            const op = try self.reduceToDelimiter(token);
            const w = self.workspace;
            if (op.kind == .open or op.kind == .block) return w.fail(token.span, .unexpected_token);
            std.debug.assert(self.operand_count == op.operand_base + op.arguments + 1);
            recordArgument(op);
            op.arguments += 1;
            const count: u32 = switch (op.kind) {
                .call => if (op.forward) w.runtime_functions.forward[op.function].definition.parameter_count else if (op.infer) op.bound else w.callBound(op.function),
                // RFC-0085, I3: a nested function's call; the arguments are counted when it closes.
                .recur => if (op.method != no_member) self.nestedBound(op.method) else self.function.?.parameter_count,
                .invoke => invoke_count: {
                    const shape = catalogue.definition(self.node(op.function).value_type, self.definitions()).?.callable;
                    const parameters = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
                    break :invoke_count parameters.end - parameters.start;
                },
                .bind => binding_count: {
                    const callee = self.node(w.operands[op.operand_base]);
                    const shape = catalogue.definition(callee.value_type, self.definitions()) orelse return w.fail(callee.span, .not_callable);
                    if (shape != .callable) return w.fail(callee.span, .not_callable);
                    const parameters = catalogue.definition(shape.callable.parameters, self.definitions()).?.tuple;
                    break :binding_count 1 + parameters.end - parameters.start;
                },
                .conditional, .iterate_value => 3,
                .with_index => if (op.function == removal) 2 else 3,
                .attempt, .lookup, .option_or, .iterate, .loop => 2,
                .convert => if ((op.function >= @backingInt(Conversion.quotient) and op.function <= @backingInt(Conversion.rational)) or op.function == @backingInt(Conversion.bit_and) or op.function == @backingInt(Conversion.bit_or) or op.function == @backingInt(Conversion.bit_xor)) 2 else 1,
                .demand, .fail, .exit, .err, .index, .set_value, .set_local_value => 1,
                .with_field, .element_at => 2,
                .text_method => if (op.head >= stdlib.first_head) std_count: {
                    const form: stdlib.Form = @fromBackingInt(op.head - stdlib.first_head);
                    // The arms of `Sync` and `Race` are as many as a call's arguments (P3.3).
                    if ((form == .sync or form == .race or form == .rush) and op.arguments >= types.limits.parameters and self.peek().kind != .synthetic_arm_reissue) return w.fail(op.span, .concurrency_arms);
                    break :std_count form.arguments().max;
                } else @as(TextMethod, @fromBackingInt(op.head)).arguments(),
                .exhaustive => std.math.maxInt(u32),
                .native_call => self.workspace.native_bindings[op.function].param_count,
                else => return w.fail(token.span, .unexpected_token),
            };
            if (op.arguments >= count) return w.fail(token.span, .argument_count);
            if (op.kind == .with_field and op.arguments == 1 and op.head == live_field_head) {
                try self.liveFieldTarget(op);
            } else if (op.kind == .with_field and op.arguments == 1) {
                // The middle argument is a field name, not an expression.
                const base = self.node(w.operands[op.operand_base]).value_type;
                const shape = catalogue.definition(base, self.definitions()) orelse return w.fail(op.span, .type_mismatch);
                if (shape != .record and shape != .class) return w.fail(self.node(w.operands[op.operand_base]).span, .type_mismatch);
                const field = try self.take(.identifier, .expected_field);
                if (w.localQualified(field.span.start)) return w.fail(field.span, .invalid_qualifier);
                op.function = catalogue.findField(base, field.span.text(w.source), self.definitions(), self.fields(), w.source) orelse interface_field: {
                    // RFC-0085, I8: a field with accessors is assigned through its setter.
                    if (shape == .class) if (self.findAccessor(base, field.span.text(w.source))) |index| {
                        try self.checkAccess(w.accessor_fields[index].write, w.accessor_fields[index].owner, field.span);
                        op.head = accessor_field_head;
                        op.method = index;
                        break :interface_field 0;
                    };
                    // A `var` field of an interface is assigned through its setter slot.
                    const slot = (if (shape == .class) w.findMethod(base, field.span.text(w.source)) else null) orelse return w.fail(field.span, .unknown_field);
                    if (w.slot_kind[slot] != .getter) return w.fail(field.span, .unknown_field);
                    if (!w.slot_field[slot].is_var) return w.fail(field.span, .not_mutable);
                    // The setter is as visible as the interface made the field.
                    try self.checkAccess(w.slot_access[slot + 1], w.slots[slot].owner, field.span);
                    op.method = slot + 1;
                    break :interface_field 0;
                };
                if (w.qualify) {
                    if (op.head == accessor_field_head) {
                        w.noteName(field.span, w.accessor_fields[op.method].name.start, .member, qualify.none);
                    } else if (op.method != no_member) {
                        w.noteName(field.span, w.slots[op.method - 1].name.start, .member, qualify.none);
                    } else self.noteField(field.span, base, op.function);
                }
                // A field whose type is a function is assigned its raw value (RFC-0084, P4.3), by
                // whoever may assign the field as written.
                var redirected = false;
                if (shape == .class and op.method == no_member) if (self.liveTypeOfField(base, op.function)) |entry| {
                    if (entry.hidden and entry.raw == op.function) return w.fail(field.span, .unknown_field);
                    if (entry.fixed) return w.fail(field.span, .live_assigned);
                    if (entry.out == op.function) {
                        try self.checkFieldAccess(base, op.function, field.span, true);
                        op.function = entry.raw;
                        redirected = true;
                    }
                };
                // Only its guard writes a live-only field (RFC-0084, P4.2).
                if (shape == .class and op.method == no_member and catalogue.classFieldAt(base, op.function, self.definitions(), self.fields()).?.live_only) return w.fail(field.span, .live_assigned);
                if (shape == .class and op.method == no_member and !redirected) try self.checkFieldAccess(base, op.function, field.span, true);
                self.skipNewlines();
                _ = try self.take(.comma, .argument_count);
                self.skipNewlines();
            } else if (op.kind == .loop and op.arguments == 1) {
                const step = self.node(w.operands[op.operand_base]);
                const definition = catalogue.definition(step.value_type, self.definitions()) orelse return w.fail(step.span, .not_callable);
                if (definition != .callable) return w.fail(step.span, .not_callable);
                const shape = definition.callable;
                const parameters = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
                if (parameters.end - parameters.start != 1) return w.fail(step.span, .argument_count);
                const result = catalogue.definition(shape.result, self.definitions()) orelse return w.fail(step.span, .type_mismatch);
                if (result != .option or w.catalogue.tuple_elements[parameters.start] != result.option) return w.fail(step.span, .type_mismatch);
                try self.callEffect(step.span, shape.effects());
                if (shape.decides and !self.failureContext()) return w.fail(step.span, .failure_context_required);
                op.value_type = result.option;
            } else if (op.kind == .iterate_value and op.arguments == 1) {
                const step = self.node(w.operands[op.operand_base]);
                const definition = catalogue.definition(step.value_type, self.definitions()) orelse return w.fail(step.span, .not_callable);
                if (definition != .callable) return w.fail(step.span, .not_callable);
                const shape = definition.callable;
                const parameters = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
                if (parameters.end - parameters.start != 1) return w.fail(step.span, .argument_count);
                if (w.catalogue.tuple_elements[parameters.start] != shape.result) return w.fail(step.span, .type_mismatch);
                try self.callEffect(step.span, shape.effects());
                if (shape.decides and !self.failureContext()) return w.fail(step.span, .failure_context_required);
                op.value_type = shape.result;
            } else if (op.kind == .conditional and op.arguments == 1) {
                const condition = w.operands[op.operand_base];
                if (self.node(condition).value_type != .logic) return w.fail(token.span, .type_mismatch);
                op.head = try self.saveLocalVersions(op.span);
                op.function = try self.emit(.{ .span = op.span, .value_type = .logic, .kind = .{ .if_begin = .{ .condition = condition, .alternative = no_member, .end = no_member } } });
            } else if ((op.kind == .conditional and op.arguments == 2) or op.kind == .attempt) {
                if (op.kind == .attempt) {
                    w.failable_uses = op.tail;
                    // The count has served; from here `tail` names a first arm that leaves (RFC-0068).
                    op.tail = no_member;
                }
                var first = w.operands[op.operand_base + op.arguments - 1];
                // RFC-0091: an arm of type `false` yields no value either; it is followed by an
                // `Err` that the second arm's type is given, as a `Return` would be.
                if (self.node(first).value_type == types.Type.bottom) {
                    first = try self.fromBottom(first, types.Type.bottom);
                    w.operands[op.operand_base + op.arguments - 1] = first;
                    op.tail = first;
                } else
                // An arm that leaves (`Return`, `Err`) yields no value: the other arm decides the type.
                if (self.leaves(first) and self.armEndsAt(self.exit_end)) op.tail = first else op.value_type = self.node(first).value_type;
                if (op.head != no_member) {
                    w.operands[op.operand_base + op.arguments - 1] = try self.packLocalVersions(op.head, first, op.span);
                    self.restoreLocalVersions(op.head);
                }
                _ = try self.emit(.{ .span = token.span, .value_type = .logic, .kind = .{ .otherwise = op.function } });
            } else if (op.kind == .text_method and op.function == no_member and op.head == stdlib.first_head + @as(u32, @backingInt(stdlib.Form.profile)) and op.arguments == 1) {
                // RFC-0094: the tag is in; the clock is read before the body, which is next.
                _ = try self.stdTyped(w.operands[op.operand_base], .string);
                try self.nativeEffect(op.span);
                op.tail = try self.stdCall("std.clock_seconds", .float, &.{}, op.span);
            }
        }
        /// The receiver `value` seen as `class`, the class whose declaration a default belongs to:
        /// the value itself, what an upcast of it was made from, or an upcast of it.
        fn receiverAs(self: *Self, value: u32, class: types.Type) ParseError!u32 {
            var at = value;
            while (self.node(at).value_type != class) {
                if (self.node(at).kind != .upcast) return self.coerce(at, class);
                at = self.node(at).kind.upcast;
            }
            return at;
        }
        /// The arguments an empty call already holds: a method call starts with its receiver.
        fn boundArguments(op: Operator) u32 {
            return if (op.receiver) 1 else 0;
        }

        /// The declaration a `call` operator names: a template, or the header of a function
        /// declared further down (RFC-0091).
        fn callTarget(self: *const Self, op: Operator) functions.Definition {
            std.debug.assert(op.kind == .call);
            if (op.forward) return self.workspace.runtime_functions.forward[op.function].definition;
            return self.workspace.functions.definitions[op.function];
        }

        fn closeParenthesis(self: *Self, token: Token, empty: bool) ParseError!void {
            const w = self.workspace;
            // Reject a missing operand before reducing its pending operators.
            // Reduction assumes a completed expression, including on malformed input.
            if (empty) {
                if (self.operator_count == self.operator_base) return w.fail(token.span, .expected_expression);
                const top = w.operators[self.operator_count - 1];
                if ((top.kind != .call and top.kind != .invoke and top.kind != .recur and top.kind != .lookup and top.kind != .option_or and top.kind != .native_call and top.kind != .err) or top.arguments != boundArguments(top) or self.operand_count != top.operand_base + boundArguments(top)) return w.fail(token.span, .expected_expression);
            }
            var op = (try self.reduceToDelimiter(token)).*;
            if (!empty) recordArgument(&op);
            if ((token.kind == .right_bracket) != (op.selected == 1 and (op.kind == .call or op.kind == .invoke or op.kind == .recur or op.kind == .demand or op.kind == .fail or op.kind == .index or op.kind == .convert or op.kind == .with_index or op.kind == .text_method))) return w.fail(token.span, .unexpected_token);
            if (empty and ((op.kind != .call and op.kind != .invoke and op.kind != .recur and op.kind != .lookup and op.kind != .option_or and op.kind != .native_call and op.kind != .err) or op.arguments != boundArguments(op) or self.operand_count != op.operand_base + boundArguments(op))) return w.fail(token.span, .expected_expression);
            if (op.kind == .open) {
                if (empty) return w.fail(token.span, .expected_expression);
                std.debug.assert(self.operand_count == op.operand_base + 1);
                self.operator_count -= 1;
                // `(A < B)` is still the comparison it encloses.
                if (self.predicate.node == w.operands[op.operand_base] and self.predicate.depth == self.operator_count + 1) self.predicate.depth = self.operator_count;
                return;
            }
            if (op.kind != .call and op.kind != .invoke and op.kind != .recur and op.kind != .iterate and op.kind != .iterate_value and op.kind != .loop and op.kind != .bind and op.kind != .lookup and op.kind != .option_or and op.kind != .index and op.kind != .convert and op.kind != .native_call and op.kind != .with_field and op.kind != .with_index and op.kind != .element_at and op.kind != .exhaustive and op.kind != .text_method and op.kind != .conditional and op.kind != .attempt and op.kind != .demand and op.kind != .fail and op.kind != .exit and op.kind != .err and op.kind != .set_value and op.kind != .set_local_value) return w.fail(token.span, .unexpected_token);
            const count = op.arguments + @as(u32, if (empty) 0 else 1);
            std.debug.assert(self.operand_count == op.operand_base + count);
            const arguments = w.operands[op.operand_base..self.operand_count];
            if (op.kind == .call and op.infer) return self.closeInferred(op, arguments);
            const index = switch (op.kind) {
                .call => try self.expandCall(op, arguments),
                .invoke => indirect: {
                    const shape = catalogue.definition(self.node(op.function).value_type, self.definitions()).?.callable;
                    const parameters = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
                    const total = parameters.end - parameters.start;
                    var ordered: [types.limits.parameters]u32 = undefined;
                    var complete: []u32 = arguments;
                    if (op.method != no_member and (op.tail != no_member or complete.len < total)) {
                        // A method call: arguments by position, then by name; parameters left out
                        // take the defaults of the declaration the receiver's static type sees.
                        if (complete.len > total) return w.fail(op.span, .argument_count);
                        @memset(ordered[0..total], no_member);
                        const positional: usize = if (op.tail == no_member) complete.len else op.tail;
                        for (complete, 0..) |argument, ordinal| {
                            const target: usize = if (ordinal < positional) ordinal else @intCast(op.names >> @intCast(4 * (ordinal - positional)) & 0xf);
                            std.debug.assert(target < total and ordered[target] == no_member);
                            ordered[target] = argument;
                        }
                        const declaration = w.declarationOf(op.value_type.?, op.method);
                        const base = declaration * types.limits.parameters;
                        // What the defaults read (RFC-0076): the receiver as the class that
                        // declares them, and the arguments before each as the method takes them.
                        var settled: [types.limits.parameters]u32 = undefined;
                        settled[0] = try self.receiverAs(ordered[0], w.methods[declaration].class);
                        for (ordered[1..total], w.catalogue.tuple_elements[parameters.start + 1 .. parameters.end], 1..) |*slot, required, position| {
                            if (slot.* == no_member) {
                                const default = w.method_parameters[base + position].default;
                                if (default.start == default.end) return w.fail(op.span, .argument_count);
                                slot.* = try self.expandBody(default, settled[0..position], op.span);
                            }
                            slot.* = try self.coerce(slot.*, required);
                            settled[position] = slot.*;
                        }
                        complete = ordered[0..total];
                    }
                    if (complete.len != total) return w.fail(op.span, .argument_count);
                    for (complete, w.catalogue.tuple_elements[parameters.start..parameters.end]) |*operand, required| operand.* = try self.coerce(operand.*, required);
                    const range = try self.reserveArguments(complete, op.span);
                    break :indirect try self.checked(try self.emit(.{ .span = op.span, .value_type = shape.result, .kind = .{ .invoke = .{ .callable = op.function, .arguments = range } } }));
                },
                .index => try self.emitIndex(op, arguments),
                .convert => try self.emitConvert(op, arguments),
                .native_call => try self.emitNative(op, arguments),
                .with_field => try self.emitWithField(op, arguments),
                .with_index => try self.emitWithIndex(op, arguments),
                .element_at => try self.emitElementAt(op, arguments),
                .text_method => if (op.head >= stdlib.first_head) try self.emitStdIn(op, arguments) else try self.emitTextMethod(@fromBackingInt(op.head), op.function, arguments, op.span),
                .exhaustive => try self.checkExhaustive(op, arguments),
                .recur => self_call: {
                    // RFC-0085, I3: a call of a nested function, or one calling itself.
                    if (op.method != no_member or self.ownNested() != no_member) break :self_call try self.nestedCall(op, arguments);
                    const f = self.function.?;
                    if (arguments.len != f.parameter_count) return w.fail(op.span, .argument_count);
                    for (arguments, f.parameters[0..f.parameter_count]) |*operand, parameter_type| operand.* = try self.coerce(operand.*, parameter_type.value_type);
                    const range = try self.reserveArguments(arguments, op.span);
                    break :self_call try self.checked(try self.emit(.{ .span = op.span, .value_type = f.value_type, .kind = .{ .recur = range } }));
                },
                .bind => binding: {
                    if (arguments.len < 2) return w.fail(token.span, .argument_count);
                    const callee = self.node(arguments[0]);
                    const definition = catalogue.definition(callee.value_type, self.definitions()) orelse return w.fail(callee.span, .not_callable);
                    if (definition != .callable) return w.fail(callee.span, .not_callable);
                    const shape = definition.callable;
                    const parameters = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
                    const bound_count: u32 = @intCast(arguments.len - 1);
                    if (bound_count > parameters.end - parameters.start) return w.fail(token.span, .argument_count);
                    for (arguments[1..], w.catalogue.tuple_elements[parameters.start .. parameters.start + bound_count]) |*operand, required| operand.* = try self.coerce(operand.*, required);
                    const residual = w.catalogue.internTuple(w.catalogue.tuple_elements[parameters.start + bound_count .. parameters.end]) catch |err| return w.fail(op.span, if (err == error.TypeLimit) .type_limit else .tuple_limit);
                    const value_type = w.catalogue.internCallable(.{ .parameters = residual, .result = shape.result, .transacts = shape.transacts, .decides = shape.decides, .detail = shape.detail }) catch |err| return w.fail(op.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                    const range = try self.reserveArguments(arguments[1..], op.span);
                    break :binding try self.emit(.{ .span = op.span, .value_type = value_type, .kind = .{ .bind = .{ .callable = arguments[0], .arguments = range } } });
                },
                .loop => state_loop: {
                    if (arguments.len != 2) return w.fail(token.span, .argument_count);
                    if (self.node(arguments[1]).value_type != op.value_type.?) return w.fail(token.span, .type_mismatch);
                    break :state_loop try self.checked(try self.emit(.{ .span = op.span, .value_type = op.value_type.?, .kind = .{ .loop = .{ .callable = arguments[0], .initial = arguments[1] } } }));
                },
                .iterate_value => dynamic_iteration: {
                    if (arguments.len != 3) return w.fail(token.span, .argument_count);
                    if (self.node(arguments[1]).value_type != .i64 or self.node(arguments[2]).value_type != op.value_type.?) return w.fail(token.span, .type_mismatch);
                    break :dynamic_iteration try self.checked(try self.emit(.{ .span = op.span, .value_type = op.value_type.?, .kind = .{ .iterate_value = .{ .callable = arguments[0], .count = arguments[1], .initial = arguments[2] } } }));
                },
                .iterate => iteration: {
                    if (arguments.len != 2) return w.fail(token.span, .argument_count);
                    if (self.node(arguments[0]).value_type != .i64 or self.node(arguments[1]).value_type != op.value_type.?) return w.fail(token.span, .type_mismatch);
                    break :iteration try self.checked(try self.emit(.{ .span = op.span, .value_type = op.value_type.?, .kind = .{ .iterate = .{ .function = op.function, .count = arguments[0], .initial = arguments[1] } } }));
                },
                .lookup, .option_or => try self.expandBuiltin(op, arguments),
                .conditional, .attempt => flow: {
                    if (op.kind == .conditional and arguments.len == 2) break :flow try self.closeElseless(op, arguments[1], token);
                    const arity: usize = if (op.kind == .conditional) 3 else 2;
                    if (arguments.len != arity) return w.fail(token.span, .argument_count);
                    const left = arguments[arity - 2];
                    var right = arguments[arity - 1];
                    if (op.tail != no_member) {
                        // The first arm leaves, so it takes the type of the second; if it was packed
                        // with the versions of the locals, the tuple it sits in follows.
                        self.mutableNode(op.tail).value_type = self.node(right).value_type;
                        if (left != op.tail) try self.retypeTuple(left);
                    } else if (self.node(right).value_type == types.Type.bottom and op.head == no_member) {
                        // RFC-0091: a second arm of type `false` takes the first arm's type.
                        right = try self.coerce(right, op.value_type.?);
                    } else if (self.node(right).value_type != op.value_type.?) {
                        // Two functions join to the narrowest type both are values of (RFC-0078,
                        // `fix2`): the second arm is widened where it stands, and the merge widens
                        // the first, whose code is already behind. Arms packed with the versions
                        // of the locals do not join.
                        if (op.head == no_member and catalogue.refinementOf(op.value_type.?, self.definitions()) != null and self.constantValue(right) != null) {
                            // A literal second arm is the refinement's, as anywhere one is expected (RFC-0083).
                            right = try self.coerce(right, op.value_type.?);
                        } else {
                            if (op.head != no_member) return w.fail(token.span, .type_mismatch);
                            const joined = try self.joinFunctions(op.value_type.?, self.node(right).value_type, op.span) orelse return w.fail(token.span, .type_mismatch);
                            right = try self.coerce(right, joined);
                        }
                    }
                    if (op.head != no_member) right = try self.packLocalVersions(op.head, right, op.span);
                    const result = self.node(right).value_type;
                    if (self.node(left).value_type != result and !catalogue.widens(self.node(left).value_type, result, self.definitions(), w.catalogue.tuple_elements[0..w.catalogue.tuple_count])) return w.fail(token.span, .type_mismatch);
                    const merged = try self.emit(.{ .span = op.span, .value_type = result, .kind = .{ .merge = .{ .begin = op.function, .left = left, .right = right } } });
                    break :flow if (op.head == no_member) merged else try self.selectLocalVersions(op.head, merged, op.span);
                },
                .set_value, .set_local_value => write: {
                    if (arguments.len != 1) return w.fail(token.span, .argument_count);
                    // RFC-0091: what is `false` may be written anywhere; no value ever is.
                    if (self.node(arguments[0]).value_type == types.Type.bottom) arguments[0] = try self.coerce(arguments[0], op.value_type.?);
                    if (self.node(arguments[0]).value_type != op.value_type.?) return w.fail(token.span, .type_mismatch);
                    break :write try self.assign(if (op.kind == .set_local_value) .{ .local = op.function } else if (op.selected == set_ref) .{ .ref = op.function } else if (op.selected == set_noted) .{ .noted = op.value_type.? } else .{ .cell = op.function }, arguments[0], op.span);
                },
                .demand, .fail => fail: {
                    if (arguments.len != 1) return w.fail(token.span, .argument_count);
                    if (self.node(arguments[0]).value_type != @as(types.Type, if (op.kind == .demand) .logic else .string)) return w.fail(token.span, .type_mismatch);
                    break :fail try self.emit(.{ .span = op.span, .value_type = if (op.kind == .demand) .logic else op.value_type.?, .kind = if (op.kind == .demand) .{ .demand = arguments[0] } else .{ .fail = arguments[0] } });
                },
                .exit => leave: {
                    // The node has the type its place expects and never yields it: the operand
                    // leaves through the function's result.
                    if (arguments.len != 1) return w.fail(token.span, .argument_count);
                    if (op.head != no_member) {
                        // RFC-0082, P3.6: an arm ends with its pending exit.
                        const pending = try self.coerce(arguments[0], @fromBackingInt(@as(u16, @intCast(op.head))));
                        self.exit_end = self.cursor;
                        break :leave try self.emit(.{ .span = op.span, .value_type = op.value_type.?, .kind = .{ .arm_exit = pending } });
                    }
                    const result = try self.coerce(arguments[0], self.function.?.value_type);
                    self.exit_end = self.cursor;
                    break :leave try self.emit(.{ .span = op.span, .value_type = op.value_type.?, .kind = .{ .exit = result } });
                },
                .err => stop: {
                    // The message is optional, as in the Book; without one it is the empty string.
                    if (arguments.len > 1) return w.fail(token.span, .argument_count);
                    const message = if (arguments.len == 1) arguments[0] else try self.emit(.{ .span = op.span, .value_type = .string, .kind = .{ .string = .{ .start = 0, .end = 0 } } });
                    if (self.node(message).value_type != .string) return w.fail(token.span, .type_mismatch);
                    self.exit_end = self.cursor;
                    break :stop try self.emit(.{ .span = op.span, .value_type = op.value_type.?, .kind = .{ .err = message } });
                },
                else => return w.fail(token.span, .unexpected_token),
            };
            self.operand_count = op.operand_base;
            self.operator_count -= 1;
            if (op.kind == .call and op.delegation) {
                // Its values are staged in the archetype around it; only another entry or the end may follow.
                const next = self.peek().kind;
                if (next != .comma and next != .newline and next != .right_brace) return w.fail(self.peek().span, .unexpected_token);
                return;
            }
            try self.pushOperand(index);
        }

        fn node(self: *const Self, index: u32) types.Node {
            if (self.function != null) {
                std.debug.assert(index < self.workspace.functions.node_count);
                return self.workspace.functions.nodes[index].node;
            }
            std.debug.assert(index < self.workspace.node_count);
            return self.workspace.nodes[index];
        }

        fn expandBuiltin(self: *Self, operator: Operator, arguments: []const u32) ParseError!u32 {
            const w = self.workspace;
            if (arguments.len != 2) return w.fail(operator.span, .argument_count);
            const first = catalogue.definition(self.node(arguments[0]).value_type, self.definitions()) orelse return w.fail(operator.span, .type_mismatch);
            const second = self.node(arguments[1]).value_type;
            if (operator.kind == .option_or) {
                if (first != .option or first.option != second) return w.fail(operator.span, .type_mismatch);
                return self.emit(.{ .span = operator.span, .value_type = second, .kind = .{ .option_or = .{ .option = arguments[0], .fallback = arguments[1] } } });
            }
            // RFC-0087, W2: `Lookup` of a `weak_map` is a map's.
            const entries = catalogue.entryShape(self.node(arguments[0]).value_type, self.definitions()) orelse return w.fail(operator.span, .type_mismatch);
            if (first != .map and first != .weak_map) return w.fail(operator.span, .type_mismatch);
            if (entries.key != second and !catalogue.subtype(second, entries.key, self.definitions())) return w.fail(operator.span, .type_mismatch);
            const key = try self.coerce(arguments[1], entries.key);
            const result_type = w.catalogue.internOption(entries.value) catch |err| return w.fail(operator.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            return self.emit(.{ .span = operator.span, .value_type = result_type, .kind = .{ .map_lookup = .{ .map = arguments[0], .key = key } } });
        }

        /// `node` as a value of type `expected`: itself, or an upcast when `expected` is a superclass of
        /// its class. Any other difference is a type mismatch.
        fn coerce(self: *Self, node_index: u32, expected: types.Type) ParseError!u32 {
            const actual = self.node(node_index).value_type;
            if (actual == expected) return node_index;
            // RFC-0091: a value of `false` stands where any type is expected; there is none.
            if (actual == types.Type.bottom) return self.fromBottom(node_index, expected);
            // A constant of a refinement's base is one of the refinement where it lies within the
            // bounds (RFC-0083), which the compiler sees; nothing else converts implicitly.
            if (catalogue.refinementOf(expected, self.definitions())) |refinement| if (refinement.base == actual) if (self.constantValue(node_index)) |value| {
                if (!refinementHolds(refinement, value)) return self.workspace.fail(self.node(node_index).span, .outside_refinement);
                return self.emit(.{ .span = self.node(node_index).span, .value_type = expected, .kind = .{ .refine = node_index } });
            };
            // A function with fewer effects stands where more are expected (RFC-0078).
            // A handle or an event is a value of an interface it implements (RFC-0082, P3.7).
            // A map is a `weak_map` of its key and value types (RFC-0087, W3), and nothing
            // converts a `weak_map` back to a map (03:1112).
            if (!catalogue.subtype(actual, expected, self.definitions()) and !catalogue.widens(actual, expected, self.definitions(), self.workspace.catalogue.tuple_elements[0..self.workspace.catalogue.tuple_count]) and !catalogue.implements(actual, expected, self.definitions()) and !catalogue.weakens(actual, expected, self.definitions())) {
                if (catalogue.weakens(expected, actual, self.definitions())) return self.workspace.fail(self.node(node_index).span, .weak_map_operation);
                if (self.valuelessAt(node_index)) return self.workspace.fail(self.node(node_index).span, .if_without_else);
                return self.workspace.fail(self.node(node_index).span, .type_mismatch);
            }
            return self.emit(.{ .span = self.node(node_index).span, .value_type = expected, .kind = .{ .upcast = node_index } });
        }

        /// RFC-0091 (B3): `node_index`, of type `false`, where a `value_type` is expected. No IR
        /// operation converts it, because it never yields: what follows it is an `Err` of that
        /// type, which leaves like any (`leaves`) and which no run reaches.
        fn fromBottom(self: *Self, node_index: u32, value_type: types.Type) ParseError!u32 {
            std.debug.assert(self.node(node_index).value_type == types.Type.bottom);
            const span = self.node(node_index).span;
            const message = try self.emit(.{ .span = span, .value_type = .string, .kind = .{ .string = .{ .start = 0, .end = 0 } } });
            return self.emit(.{ .span = span, .value_type = value_type, .kind = .{ .err = message } });
        }

        /// The value of a constant node: an integer or float literal, `Inf`, or one of them
        /// negated, as `-5` and `-Inf` are written.
        fn constantValue(self: *const Self, index: u32) ?types.Value {
            if (!self.isLiteral(index)) return null;
            const at = self.node(index);
            switch (at.kind) {
                .integer => |value| return .{ .integer = value },
                .floating => |value| return .{ .floating = value },
                .negate => |operand| {
                    const inner = self.node(operand);
                    if (inner.kind != .integer or inner.kind.integer == std.math.minInt(i64)) return null;
                    return .{ .integer = -inner.kind.integer };
                },
                .float_negate => |operand| {
                    const inner = self.node(operand);
                    if (inner.kind != .floating) return null;
                    return .{ .floating = -inner.kind.floating };
                },
                else => return null,
            }
        }

        /// A call at `index` that may suspend is a site (RFC-0082): in a function body it is
        /// followed by its check, whose `merge` stands for the call's value from here on.
        fn checked(self: *Self, index: u32) ParseError!u32 {
            const f = self.function orelse return index;
            const w = self.workspace;
            const call = self.node(index);
            const suspends = switch (call.kind) {
                .call => |c| w.runtime_functions.signature(c.function).detail.suspends,
                .iterate => |i| w.runtime_functions.definitions[i.function].detail.suspends,
                .recur => f.detail.suspends,
                .invoke => |i| catalogue.definition(self.node(i.callable).value_type, self.definitions()).?.callable.detail.suspends,
                .iterate_value => |i| catalogue.definition(self.node(i.callable).value_type, self.definitions()).?.callable.detail.suspends,
                .loop => |l| catalogue.definition(self.node(l.callable).value_type, self.definitions()).?.callable.detail.suspends,
                else => unreachable,
            };
            return if (suspends) self.checkSite(index) else index;
        }
        /// The check after the site at `site`: `canceling`, an `if_begin` on it whose first arm is
        /// the landing, an empty `otherwise`, and a `merge` of the landing's `cancel_exit` and
        /// the site. The landing runs the `Defer`s whose scope is open at the site, innermost
        /// first, each by calling the function compiled from its body where it stands (P3.3),
        /// and ends with the `cancel_exit`.
        fn checkSite(self: *Self, site: u32) ParseError!u32 {
