            // compile is not used.
            if (!self.function.?.detail.suspends) {
                std.debug.assert(self.workspace.for_suspended_pending != 0);
                return site;
            }
            const begin = try self.openCheck(site);
            const landing = self.node(begin).kind.if_begin.alternative - 1;
            return self.emit(.{ .span = at.span, .value_type = at.value_type, .kind = .{ .merge = .{ .begin = begin, .left = landing, .right = site } } });
        }
        /// The check up to its `otherwise`; the result is its `if_begin`.
        fn openCheck(self: *Self, site: u32) ParseError!u32 {
            const at = self.node(site);
            std.debug.assert(self.function != null and self.function.?.detail.suspends);
            const w = self.workspace;
            // `Sync` counts the arms that can suspend (`sync_arms`).
            if (self.armBody()) w.anonymous_frames[w.anonymous_count - 1].sites += 1;
            const flag = try self.emit(.{ .span = at.span, .value_type = .logic, .kind = .canceling });
            const begin = try self.emit(.{ .span = at.span, .value_type = .logic, .kind = .{ .if_begin = .{ .condition = flag, .alternative = no_member, .end = no_member } } });
            // The `Defer`s of this function are the marks of its own blocks.
            var first = self.mark_count;
            while (first != 0 and self.marks[first - 1].operator >= self.operator_base) first -= 1;
            var index = self.mark_count;
            while (index > first) {
                index -= 1;
                const landing = &w.landings[index];
                if (landing.function == no_member) {
                    // Its body is not compiled as a function yet: the next compile writes it out
                    // after the mark (`wantLanding`), and this one goes on without it.
                    if (!w.wantLanding(self.marks[index].span)) return w.fail(self.marks[index].span, .expression_limit);
                    continue;
                }
