                if (landing.capture_count != 0) {
                    var captured: [types.limits.parameters]u32 = undefined;
                    for (landing.names[0..landing.capture_count], captured[0..landing.capture_count]) |name, *value| value.* = try self.capturedValue(name, at.span);
                    const arguments = try self.reserveArguments(captured[0..landing.capture_count], at.span);
                    callee = try self.emit(.{ .span = at.span, .value_type = landing.bound, .kind = .{ .bind = .{ .callable = callee, .arguments = arguments } } });
                }
                const none = try self.reserveArguments(&.{}, at.span);
                _ = try self.emit(.{ .span = at.span, .value_type = landing.result, .kind = .{ .invoke = .{ .callable = callee, .arguments = none } } });
            }
            _ = try self.emit(.{ .span = at.span, .value_type = at.value_type, .kind = .cancel_exit });
