        }
        /// The value a landing captures for `name` at a site: the local as it is there, or the
        /// parameter. Each name was found where the `Defer` stood, inside whose scope the site is,
        /// and no name is declared twice, so it is found again here.
        fn capturedValue(self: *Self, name: Span, span: Span) ParseError!u32 {
            const w = self.workspace;
            const text = name.text(w.source);
            if (self.findLocal(text)) |index| return w.locals[index].node;
            const index = self.parameter(text) orelse return w.fail(span, .unknown_name);
            const parameter_type = self.function.?.parameters[index].value_type;
            return self.emitTemplate(.{ .node = .{ .span = span, .value_type = parameter_type, .kind = .{ .integer = 0 } }, .input = .{ .parameter = index } });
        }
