            if (token.kind != .identifier or next.kind != .left_paren) return false;
            const name = token.span.text(w.source);
            const form: stdlib.Form = if (std.mem.eql(u8, name, "task")) .task_type else if (std.mem.eql(u8, name, "event")) .event_type else if (std.mem.eql(u8, name, "awaitable")) .awaitable_type else if (std.mem.eql(u8, name, "signalable")) .signalable_type else if (std.mem.eql(u8, name, "sticky_event")) .sticky_event_type else if (std.mem.eql(u8, name, "subscribable_event")) .subscribable_event_type else if (std.mem.eql(u8, name, "weak_map")) .weak_map_type else return false;
            if (self.genericType(name) != null or self.genericParameter(name) or self.findGeneric(name, w.scope()) != null) return false;
            if (w.findTypeAliasIn(name, w.scope()) != null or w.catalogue.findNamedIn(name, w.source, w.scope()) != null) return false;
