            const value_type = try self.parseTypeValue();
            std.debug.assert(catalogue.isEvent(value_type, self.definitions()));
            _ = try self.take(.left_brace, .unexpected_token);
            if (self.peek().kind != .right_brace) return w.fail(self.peek().span, .unexpected_token);
