            try self.stateEffect(token.span, .construction);
            if (w.anonymous_count == w.anonymous_frames.len or w.runtime_functions.count == types.limits.functions) return w.fail(token.span, .function_limit);
            var effect: Effect = if (self.function) |f| Effect.of(f).heapOnly() else .{ .transacts = true };
            effect.detail.suspends = true;
