            const shape = catalogue.definition(self.node(arguments[1]).value_type, self.definitions()).?.callable;
            const result = if (form == .upon) shape.result else try self.internTuple(&.{}, op.span);
            const handle = w.catalogue.internTask(result) catch |err| return w.fail(op.span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
            return self.emit(.{ .span = op.span, .value_type = handle, .kind = .{ .reaction = .{ .kind = if (form == .upon) .upon else .when, .guard = arguments[0], .body = arguments[1] } } });
