            if (arms.len < 2 or arms.len > types.limits.parameters) return w.fail(op.span, .concurrency_arms);
            if (form == .sync and @popCount(op.names) < 2) return w.fail(op.span, .sync_arms);
            var results: [types.limits.parameters]types.Type = undefined;
