            const value_type = if (form == .sync) try self.internTuple(results[0..arms.len], op.span) else results[0];
            if (form == .race or form == .rush) for (arms, results[0..arms.len]) |arm, result| if (result != value_type) return w.fail(self.node(arm).span, .type_mismatch);
