            const op = &w.operators[self.operator_count - 1];
            std.debug.assert(self.structuredOpen());
            const arms = w.operands[op.operand_base .. op.operand_base + op.arguments];
            var exits: ?types.Type = null;
            for (arms) |arm| if (w.runtime_functions.definitions[self.armFunction(arm)].exits) |found| {
                if (exits != null and exits.? != found) return w.fail(self.node(arm).span, .type_mismatch);
                exits = found;
            };
            const pending = exits orelse return w.fail(op.span, .unexpected_token);
            // In a loop function a noted `For` kept from suspending (P3.8), the compile ends here:
            // the check that carries an exit on has no simpler form, and the compile is not used.
            if (!self.function.?.detail.suspends) {
