            _ = try self.emit(.{ .span = at.span, .value_type = .logic, .kind = .{ .if_begin = .{ .condition = exited, .alternative = no_member, .end = no_member } } });
            _ = try self.emit(.{ .span = at.span, .value_type = pending, .kind = .arm_exit_value });
