                .expected_type = self.expected_type,
                .default_expression = self.default_expression,
                .control_depth = self.control_depth,
                .operator_base = self.operator_base,
                .operand_base = self.operand_base,
                .local_base = self.local_base,
                .parentheses = parentheses,
                .operators = self.operator_count,
                .operands = self.operand_count,
                .locals = w.local_count,
                .checkpoints = w.local_checkpoint_count,
