                self.control_depth -= 1;
            }
            const index = if (self.function != null) try self.emitTemplate(.{ .node = value }) else emitted: {
                self.assertNode(value);
                break :emitted try self.workspace.emit(value);
            };
            switch (value.kind) {
                .otherwise => |begin| {
                    const node_ptr = self.mutableNode(begin);
                    if (node_ptr.kind == .if_begin) node_ptr.kind.if_begin.alternative = index else node_ptr.kind.attempt_begin.alternative = index;
                },
                .merge => |merge| {
                    const node_ptr = self.mutableNode(merge.begin);
                    if (node_ptr.kind == .if_begin) node_ptr.kind.if_begin.end = index else node_ptr.kind.attempt_begin.end = index;
                },
                else => {},
            }
            return index;
        }

        // Typed nodes are produced only after syntax/operand checks. Prove that
        // compiler output respects the same dependency rules as the VM verifier.
        fn assertNode(self: *const Self, value: types.Node) void {
            std.debug.assert(value.span.start <= value.span.end and value.span.end <= self.workspace.source.len);
            const value_type: types.Type = switch (value.kind) {
                .integer, .negate, .binary, .float_to_int, .string_length => .i64,
                .floating, .float_negate, .float_binary, .int_to_float => .float,
                .boolean => .logic,
                .option_present, .compare, .logic_not, .logic_binary, .if_begin, .attempt_begin, .otherwise, .demand, .instance_of => .logic,
                .string, .string_concat, .to_string => .string,
                .array_length => .i64,
                .rational => |r| if (r.op == .floor or r.op == .ceil) .i64 else if (r.op == .to_float) .float else value.value_type,
                .text => |t| switch (t.op) {
                    .unit => types.Type.char,
                    .scalar => types.Type.char32,
                    .boundary, .valid => .logic,
                    .slice, .join => .string,
                    .code => .i64,
                    .from_code => value.value_type,
                },
                .aggregate, .field, .enumeration, .tuple_element, .option_or, .map_lookup, .array_get, .map_key, .map_value, .native_call, .array_concat, .array_set, .map_set, .map_remove, .option_value, .merge, .fail, .exit, .err, .cell_init, .cell_read, .cell_write, .object_new, .object_get, .object_set, .upcast, .downcast, .method_value, .local_set, .call, .iterate, .iterate_value, .loop, .recur, .invoke, .bind, .function_value, .self_value, .character => value.value_type,
                .spawn, .sleep, .cancel_exit, .refine => value.value_type,
                .canceling => .logic,
                .task_await, .event_new, .event_signal, .event_await => value.value_type,
                .structured => value.value_type,
                .branch => value.value_type,
                .cell_live => value.value_type,
                .object_live => value.value_type,
                .arm_exit, .arm_exit_value => value.value_type,
                .arm_exited => .logic,
                .reaction => value.value_type,
                .task_cancel => value.value_type,
                .elapsed_time => .float,
                .batch => value.value_type,
                .await_guard => value.value_type,
                .event_subscribe, .subscription_cancel, .event_notify => value.value_type,
                .ref_new, .ref_get, .ref_set => value.value_type,
                .grant => value.value_type,
                .weak_init, .weak_get, .weak_set => value.value_type,
                // RFC-0087, P5.3.
                .json_encode => .string,
                .json_decode => value.value_type,
            };
            std.debug.assert(value.value_type == value_type);
            switch (value.kind) {
                .negate => |operand| std.debug.assert(self.node(operand).value_type == .i64),
                .binary => |binary| {
                    std.debug.assert(self.node(binary.lhs).value_type == .i64);
                    std.debug.assert(self.node(binary.rhs).value_type == .i64);
                },
                .float_negate => |operand| std.debug.assert(self.node(operand).value_type == .float),
                .native_call => |c| for (c.args[0..c.count]) |operand| std.debug.assert(operand < self.workspace.node_count or self.function != null),
                .int_to_float => |operand| std.debug.assert(self.node(operand).value_type == .i64),
                .string_length => |operand| std.debug.assert(self.node(operand).value_type == .string),
                .array_concat => |c| std.debug.assert(self.node(c.lhs).value_type == self.node(c.rhs).value_type and self.node(c.lhs).value_type == value.value_type),
                .map_set => |c| std.debug.assert(catalogue.entryShape(value.value_type, self.definitions()) != null and self.node(c.map).value_type == value.value_type and self.node(c.key).value_type == catalogue.entryShape(value.value_type, self.definitions()).?.key and self.node(c.value).value_type == catalogue.entryShape(value.value_type, self.definitions()).?.value),
                .option_value => |operand| std.debug.assert(catalogue.definition(self.node(operand).value_type, self.definitions()).? == .option and catalogue.definition(self.node(operand).value_type, self.definitions()).?.option == value.value_type),
                .array_set => |c| std.debug.assert(self.node(c.array).value_type == value.value_type and self.node(c.index).value_type == .i64 and catalogue.definition(value.value_type, self.definitions()).?.array == self.node(c.value).value_type),
                .string_concat => |c| std.debug.assert(self.node(c.lhs).value_type == .string and self.node(c.rhs).value_type == .string),
                .to_string => |operand| std.debug.assert(self.node(operand).value_type == .i64 or self.node(operand).value_type == .float or self.node(operand).value_type == .logic or self.node(operand).value_type.isCharacter()),
                .character => |code| std.debug.assert(types.validCharacter(value.value_type, code)),
                .text => |t| {
                    std.debug.assert(t.canonical());
                    const first = self.node(t.a).value_type;
                    switch (t.op) {
                        .unit, .boundary, .scalar => std.debug.assert(first == .string and self.node(t.b).value_type == .i64),
                        .slice => std.debug.assert(first == .string and self.node(t.b).value_type == .i64 and self.node(t.c).value_type == .i64),
                        .code => std.debug.assert(first.isCharacter()),
                        .from_code => std.debug.assert(first == .i64 and value.value_type.isCharacter()),
                        .valid, .join => std.debug.assert(catalogue.definition(first, self.definitions()).?.array == types.Type.char),
                    }
                },
                .float_to_int => |c| std.debug.assert(self.node(c.operand).value_type == .float),
                .rational => |r| {
                    const operand_type: types.Type = if (r.op == .make) .i64 else self.node(r.lhs).value_type;
                    std.debug.assert(self.node(r.lhs).value_type == operand_type and self.node(r.rhs).value_type == operand_type);
                    std.debug.assert(r.op == .make or catalogue.isRational(operand_type, self.definitions()));
                    std.debug.assert(!r.op.unary() or r.lhs == r.rhs);
                },
                .float_binary => |binary| {
                    std.debug.assert(self.node(binary.lhs).value_type == .float);
                    std.debug.assert(self.node(binary.rhs).value_type == .float);
                },
                .string => |span| {
                    std.debug.assert(span.start <= span.end);
                    std.debug.assert(span.end <= self.workspace.string_count);
                },
                .floating => |floating| std.debug.assert(types.isCanonicalFloat(floating)),
                .aggregate => |span| {
                    const pool = if (self.function != null) self.workspace.functions.members[0..self.workspace.functions.member_count] else self.workspace.members[0..self.workspace.member_count];
                    std.debug.assert(span.start <= span.end and span.end <= pool.len);
                    const definition = catalogue.definition(value.value_type, self.definitions()).?;
                    switch (definition) {
                        .record => |record| {
                            std.debug.assert(span.end - span.start == record.fields.end - record.fields.start);
                            for (pool[span.start..span.end], self.fields()[record.fields.start..record.fields.end]) |member, field| std.debug.assert(self.node(member).value_type == field.value_type);
                        },
                        .array => |element_type| for (pool[span.start..span.end]) |member| std.debug.assert(self.node(member).value_type == element_type),
                        .option => |element_type| {
                            std.debug.assert(span.end - span.start <= 1);
                            for (pool[span.start..span.end]) |member| std.debug.assert(self.node(member).value_type == element_type);
                        },
                        .map, .weak_map => |shape| {
                            std.debug.assert((span.end - span.start) % 2 == 0);
                            for (pool[span.start..span.end], 0..) |member, index| std.debug.assert(self.node(member).value_type == if (index % 2 == 0) shape.key else shape.value);
                        },
                        .tuple => |shape| {
                            std.debug.assert(span.end - span.start == shape.end - shape.start);
                            for (pool[span.start..span.end], self.workspace.catalogue.tuple_elements[shape.start..shape.end]) |member, element| std.debug.assert(self.node(member).value_type == element);
                        },
                        .enumeration, .callable, .class, .rational, .task, .refinement, .event, .live, .scheduled_interface, .cancelable, .ref, .grant => unreachable,
                    }
                },
                .object_new => |c| {
                    const shape = catalogue.definition(value.value_type, self.definitions()).?.class;
                    std.debug.assert(c.arguments.end - c.arguments.start == shape.fields.end - shape.fields.start);
                    const pool = if (self.function != null) self.workspace.functions.arguments[0..self.workspace.functions.argument_count] else self.workspace.call_arguments[0..self.workspace.call_argument_count];
                    for (pool[c.arguments.start..c.arguments.end], self.fields()[shape.fields.start..shape.fields.end]) |operand, field| std.debug.assert(self.node(operand).value_type == field.value_type);
                },
                .upcast => |n| std.debug.assert(if (value.value_type == types.Type.any) self.node(n).value_type != types.Type.any else catalogue.subtype(self.node(n).value_type, value.value_type, self.definitions()) or catalogue.widens(self.node(n).value_type, value.value_type, self.definitions(), self.workspace.catalogue.tuple_elements[0..self.workspace.catalogue.tuple_count]) or catalogue.implements(self.node(n).value_type, value.value_type, self.definitions()) or catalogue.weakens(self.node(n).value_type, value.value_type, self.definitions())),
                .downcast => |n| std.debug.assert(if (self.node(n).value_type == types.Type.any) value.value_type != types.Type.any else catalogue.castable(value.value_type, self.node(n).value_type, self.definitions())),
                .refine => |n| std.debug.assert(if (catalogue.refinementOf(value.value_type, self.definitions())) |refinement| refinement.base == self.node(n).value_type else catalogue.refinementOf(self.node(n).value_type, self.definitions()).?.base == value.value_type),
                .instance_of => |c| std.debug.assert(value.value_type == .logic and (if (self.node(c.value).value_type == types.Type.any) c.class != types.Type.any else catalogue.castable(c.class, self.node(c.value).value_type, self.definitions()))),
                .method_value => |m| std.debug.assert(self.workspace.slots[m.slot].callable == value.value_type and catalogue.subtype(self.node(m.receiver).value_type, self.workspace.slots[m.slot].owner, self.definitions())),
                .object_get => |access| std.debug.assert(catalogue.classFieldAt(self.node(access.value).value_type, access.index, self.definitions(), self.fields()).?.value_type == value.value_type),
                .object_set => |c| {
                    const field = catalogue.classFieldAt(self.node(c.object).value_type, c.index, self.definitions(), self.fields()).?;
                    std.debug.assert(field.is_var and field.value_type == value.value_type and self.node(c.value).value_type == value.value_type);
                },
                .field => |access| std.debug.assert(catalogue.fieldAt(self.node(access.value).value_type, access.index, self.workspace.catalogue.definitions[0..self.workspace.catalogue.count], self.workspace.catalogue.fields[0..self.workspace.catalogue.field_count]).?.value_type == value.value_type),
                .array_length => |operand| {
                    const shape = catalogue.definition(self.node(operand).value_type, self.definitions()).?;
                    std.debug.assert(shape == .array or shape == .map);
                },
                .option_present => |operand| std.debug.assert(catalogue.definition(self.node(operand).value_type, self.definitions()).? == .option),
                .option_or => |choice| std.debug.assert(catalogue.definition(self.node(choice.option).value_type, self.definitions()).?.option == self.node(choice.fallback).value_type and self.node(choice.fallback).value_type == value.value_type),
                .array_get => |access| std.debug.assert(catalogue.definition(self.node(access.array).value_type, self.definitions()).?.array == value.value_type and self.node(access.index).value_type == .i64),
                .map_key, .map_value => |access| std.debug.assert(catalogue.definition(self.node(access.array).value_type, self.definitions()).? == .map and self.node(access.index).value_type == .i64),
                .map_remove => |c| std.debug.assert(catalogue.definition(value.value_type, self.definitions()).? == .map and self.node(c.map).value_type == value.value_type and catalogue.definition(self.node(c.key).value_type, self.definitions()).?.option == catalogue.definition(value.value_type, self.definitions()).?.map.value),
                .map_lookup => |lookup| {
                    const shape = catalogue.entryShape(self.node(lookup.map).value_type, self.definitions()).?;
                    std.debug.assert(shape.key == self.node(lookup.key).value_type and catalogue.definition(value.value_type, self.definitions()).?.option == shape.value);
                },
                .enumeration => |index| std.debug.assert(catalogue.caseAt(value.value_type, index, self.definitions(), self.workspace.catalogue.cases[0..self.workspace.catalogue.case_count]) != null),
                .tuple_element => |access| std.debug.assert(catalogue.tupleElementAt(self.node(access.value).value_type, access.index, self.definitions(), self.workspace.catalogue.tuple_elements[0..self.workspace.catalogue.tuple_count]).? == value.value_type),
                .compare => |comparison| {
                    const left = self.node(comparison.lhs).value_type;
                    std.debug.assert(left == self.node(comparison.rhs).value_type);
                    std.debug.assert(if (comparison.op == .equal or comparison.op == .unequal) self.comparable(left) else left == .i64 or left == .float or catalogue.isRational(left, self.definitions()));
                },
                .logic_not => |operand| std.debug.assert(self.node(operand).value_type == .logic),
                .logic_binary => |binary| std.debug.assert(self.node(binary.lhs).value_type == .logic and self.node(binary.rhs).value_type == .logic),
                .if_begin => |b| std.debug.assert(self.node(b.condition).value_type == .logic),
                .demand => |n| std.debug.assert(self.node(n).value_type == .logic),
                .fail, .err => |n| std.debug.assert(self.node(n).value_type == .string),
                .exit => |n| std.debug.assert(self.function != null and self.node(n).value_type == self.function.?.value_type),
                .merge => |m| std.debug.assert((self.node(m.left).value_type == value.value_type or catalogue.widens(self.node(m.left).value_type, value.value_type, self.definitions(), self.workspace.catalogue.tuple_elements[0..self.workspace.catalogue.tuple_count])) and self.node(m.right).value_type == value.value_type),
                .cell_init => |c| std.debug.assert(self.node(c.value).value_type == value.value_type),
                .cell_write => |c| std.debug.assert(self.node(c.value).value_type == value.value_type and self.workspace.source_cells[c.cell].value_type == value.value_type),
                .local_set => |n| std.debug.assert(self.node(n).value_type == value.value_type),
                .cell_read => |c| std.debug.assert(self.workspace.source_cells[c].value_type == value.value_type),
                .iterate => |i| {
                    const callee = self.workspace.runtime_functions.definitions[i.function];
                    std.debug.assert(callee.parameter_count == 1 and callee.parameters[0] == value.value_type and callee.value_type == value.value_type);
                    std.debug.assert(self.node(i.count).value_type == .i64 and self.node(i.initial).value_type == value.value_type);
                },
                .loop => |l| {
                    const shape = catalogue.definition(self.node(l.callable).value_type, self.definitions()).?.callable;
                    const parameters = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
                    std.debug.assert(parameters.end - parameters.start == 1 and self.workspace.catalogue.tuple_elements[parameters.start] == value.value_type);
                    std.debug.assert(catalogue.definition(shape.result, self.definitions()).?.option == value.value_type and self.node(l.initial).value_type == value.value_type);
                },
                .iterate_value => |i| {
                    const shape = catalogue.definition(self.node(i.callable).value_type, self.definitions()).?.callable;
                    const parameters = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
                    std.debug.assert(parameters.end - parameters.start == 1 and self.workspace.catalogue.tuple_elements[parameters.start] == shape.result);
                    std.debug.assert(value.value_type == shape.result and self.node(i.count).value_type == .i64 and self.node(i.initial).value_type == shape.result);
                },
                .bind => |i| {
                    const shape = catalogue.definition(self.node(i.callable).value_type, self.definitions()).?.callable;
                    const residual = catalogue.definition(value.value_type, self.definitions()).?.callable;
                    const parameters = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
                    const remaining = catalogue.definition(residual.parameters, self.definitions()).?.tuple;
                    const count = i.arguments.end - i.arguments.start;
                    std.debug.assert(count > 0 and count <= parameters.end - parameters.start);
                    std.debug.assert(residual.result == shape.result and std.meta.eql(residual.effects(), shape.effects()));
                    std.debug.assert(remaining.end - remaining.start == parameters.end - parameters.start - count);
                    std.debug.assert(std.mem.eql(types.Type, self.workspace.catalogue.tuple_elements[remaining.start..remaining.end], self.workspace.catalogue.tuple_elements[parameters.start + count .. parameters.end]));
                    const pool = if (self.function != null) self.workspace.functions.arguments[0..self.workspace.functions.argument_count] else self.workspace.call_arguments[0..self.workspace.call_argument_count];
                    for (pool[i.arguments.start..i.arguments.end], self.workspace.catalogue.tuple_elements[parameters.start .. parameters.start + count]) |operand, required| std.debug.assert(self.node(operand).value_type == required);
                },
                .invoke => |i| {
                    const shape = catalogue.definition(self.node(i.callable).value_type, self.definitions()).?.callable;
                    const parameters = catalogue.definition(shape.parameters, self.definitions()).?.tuple;
                    const pool = if (self.function != null) self.workspace.functions.arguments[0..self.workspace.functions.argument_count] else self.workspace.call_arguments[0..self.workspace.call_argument_count];
                    std.debug.assert(shape.result == value.value_type and i.arguments.end - i.arguments.start == parameters.end - parameters.start);
                    for (pool[i.arguments.start..i.arguments.end], self.workspace.catalogue.tuple_elements[parameters.start..parameters.end]) |operand, required| std.debug.assert(self.node(operand).value_type == required);
                },
                .function_value, .self_value => std.debug.assert(catalogue.definition(value.value_type, self.definitions()).? == .callable),
                .recur => |range| {
                    const f = self.function.?;
                    std.debug.assert(f.value_type == value.value_type and range.end - range.start == f.parameter_count);
                    for (self.workspace.functions.arguments[range.start..range.end], f.parameters[0..f.parameter_count]) |operand, parameter_type| std.debug.assert(self.node(operand).value_type == parameter_type.value_type);
                },
                .call => |c| {
                    const callee = self.workspace.runtime_functions.signature(c.function);
                    std.debug.assert(callee.value_type == value.value_type and c.arguments.end - c.arguments.start == callee.parameter_count);
                    const arguments = if (self.function != null) self.workspace.functions.arguments[0..self.workspace.functions.argument_count] else self.workspace.call_arguments[0..self.workspace.call_argument_count];
                    for (arguments[c.arguments.start..c.arguments.end], callee.parameters[0..callee.parameter_count]) |operand, required| std.debug.assert(self.node(operand).value_type == required);
                },
                .attempt_begin, .otherwise, .integer, .boolean => {},
                .spawn => |n| std.debug.assert(catalogue.definition(value.value_type, self.definitions()).?.task.result == catalogue.definition(self.node(n).value_type, self.definitions()).?.callable.result),
                .sleep => |n| std.debug.assert(self.node(n).value_type == .float),
                .canceling, .cancel_exit => std.debug.assert(self.function != null),
                .arm_exit => std.debug.assert(self.function != null and self.armBody()),
                .arm_exited, .arm_exit_value => std.debug.assert(self.function != null),
                .task_await => |n| std.debug.assert(self.function != null and (if (catalogue.scheduledInterface(self.node(n).value_type, self.definitions())) |interface| interface.kind == .awaitable and interface.value == value.value_type else catalogue.definition(self.node(n).value_type, self.definitions()).?.task.result == value.value_type)),
                .event_await => |n| std.debug.assert(self.function != null and catalogue.definition(self.node(n).value_type, self.definitions()).?.event.value == value.value_type),
                .event_signal => |s| std.debug.assert(if (catalogue.scheduledInterface(self.node(s.event).value_type, self.definitions())) |interface| interface.kind == .signalable and interface.value == self.node(s.value).value_type else catalogue.definition(self.node(s.event).value_type, self.definitions()).?.event.value == self.node(s.value).value_type),
                .event_subscribe => |s| std.debug.assert(catalogue.definition(self.node(s.event).value_type, self.definitions()).?.event.kind == .subscribable and catalogue.isCancelable(value.value_type, self.definitions())),
                .subscription_cancel => |n| std.debug.assert(catalogue.isCancelable(self.node(n).value_type, self.definitions())),
                .event_notify => |n| std.debug.assert(catalogue.definition(self.node(n.callable).value_type, self.definitions()).?.event.kind == .subscribable and n.arguments.end - n.arguments.start == 1),
                .event_new => std.debug.assert(catalogue.isEvent(value.value_type, self.definitions())),
                .structured => |s| std.debug.assert(self.function != null and s.arms.end - s.arms.start >= 2),
                .branch => |n| std.debug.assert(self.function != null and catalogue.definition(self.node(n).value_type, self.definitions()).?.callable.result == value.value_type),
                .cell_live => |c| std.debug.assert(catalogue.definition(self.node(c.guard).value_type, self.definitions()).?.callable.result == value.value_type),
                // RFC-0085, I14: or the value of a variable cell, at field 0.
                .object_live => |c| std.debug.assert(catalogue.definition(self.node(c.guard).value_type, self.definitions()).?.callable.result == value.value_type and (if (catalogue.refValue(self.node(c.object).value_type, self.definitions())) |held| c.field == 0 and held == value.value_type else catalogue.classFieldAt(self.node(c.object).value_type, c.field, self.definitions(), self.fields()).?.value_type == value.value_type)),
                .reaction => |r| std.debug.assert(catalogue.definition(self.node(r.guard).value_type, self.definitions()).? == .callable and catalogue.definition(self.node(r.body).value_type, self.definitions()).? == .callable and catalogue.isTask(value.value_type, self.definitions())),
                .task_cancel => |n| std.debug.assert(self.function != null and catalogue.isTask(self.node(n).value_type, self.definitions())),
                .elapsed_time => {},
                .batch => |n| std.debug.assert(catalogue.definition(self.node(n).value_type, self.definitions()).?.callable.result == value.value_type),
                .await_guard => |n| std.debug.assert(self.function != null and catalogue.definition(catalogue.definition(self.node(n).value_type, self.definitions()).?.callable.result, self.definitions()).?.option == value.value_type),
                // RFC-0085, I1: a variable cell of the operand's type, a read of one, a write of one.
                .ref_new => |n| std.debug.assert(catalogue.refValue(value.value_type, self.definitions()).? == self.node(n).value_type),
                .ref_get => |n| std.debug.assert(catalogue.refValue(self.node(n).value_type, self.definitions()).? == value.value_type),
                .ref_set => |r| std.debug.assert(catalogue.refValue(self.node(r.ref).value_type, self.definitions()).? == value.value_type and self.node(r.value).value_type == value.value_type),
                // RFC-0086, P2.3: a name, and an option of the kind's handle.
                .grant => |g| if (g.kind == .session) std.debug.assert(g.name == types.no_grant_name and catalogue.grantKind(value.value_type, self.definitions()).? == .session) else std.debug.assert(self.node(g.name).value_type == .string and catalogue.grantKind(catalogue.definition(value.value_type, self.definitions()).?.option, self.definitions()).? == g.kind),
                // RFC-0087, P5.4: a keyed cell's declaration, lookup and update.
                .weak_init => |c| std.debug.assert(self.function == null and self.workspace.source_cells[c].value_type == value.value_type),
                .weak_get => |g| {
                    const entries = catalogue.entryShape(self.workspace.source_cells[g.cell].value_type, self.definitions()).?;
                    std.debug.assert(self.workspace.source_cells[g.cell].keyed != .none and entries.key == self.node(g.key).value_type and catalogue.definition(value.value_type, self.definitions()).?.option == entries.value);
                },
                .weak_set => |c| {
                    const entries = catalogue.entryShape(self.workspace.source_cells[c.cell].value_type, self.definitions()).?;
                    std.debug.assert(self.workspace.source_cells[c.cell].keyed != .none and entries.key == self.node(c.key).value_type and entries.value == value.value_type and self.node(c.value).value_type == value.value_type);
                },
                // RFC-0087, P5.3: a text, and an option of what it is read as.
                .json_encode => {},
                .json_decode => |n| std.debug.assert(self.node(n).value_type == .string and catalogue.definition(value.value_type, self.definitions()).? == .option),
            }
        }

        fn emitTemplate(self: *Self, template: functions.Template) ParseError!u32 {
            const storage = &self.workspace.functions;
            std.debug.assert(self.function != null);
            switch (template.input) {
                .operation => self.assertNode(template.node),
                .parameter => |index| {
                    std.debug.assert(index < self.function.?.parameter_count);
                    std.debug.assert(template.node.value_type == self.function.?.parameters[index].value_type);
                },
                .global => |index| {
                    std.debug.assert(index < self.workspace.binding_count and self.workspace.binding_cells[index] == std.math.maxInt(u16));
                    std.debug.assert(template.node.value_type == self.workspace.bindings[index].value_type);
                },
            }
            if (storage.node_count == storage.node_top) return self.workspace.fail(template.node.span, .template_limit);
            const index = storage.node_count;
            storage.nodes[index] = template;
            self.workspace.literal_templates.unset(index);
            // Nodes of generated code are blamed on the call that generated them.
            if (self.workspace.libraryModule(template.node.span)) |module| storage.nodes[index].node.span = self.workspace.siteBlame(template.node.span) orelse self.workspace.library_blame[module];
            storage.node_count += 1;
            return index;
        }

        fn findLocal(self: *const Self, name: []const u8) ?u32 {
            var index = self.workspace.local_count;
            scan: while (index > self.local_base) {
                index -= 1;
                // A copy of a `Defer` body sees the names its `Defer` saw, not the ones declared since.
                for (self.hidden[0..self.hidden_count]) |copy| if (index >= copy.from and index < copy.to) continue :scan;
                if (std.mem.eql(u8, name, self.workspace.locals[index].name.text(self.workspace.source))) return index;
            }
            return null;
        }

        /// RFC-0085, I2: the type the name of a local has: a shared local's node is its cell, a
        /// `ref(T)`, and the name means the `T` the cell holds.
        fn localType(self: *const Self, index: u32) types.Type {
            const held = self.node(self.workspace.locals[index].node).value_type;
            if (!self.workspace.locals[index].shared) return held;
            return catalogue.refValue(held, self.definitions()).?;
        }
        /// So for a parameter: what a closure captured for a shared local is its cell.
        fn parameterType(self: *const Self, index: u32) types.Type {
            const held = self.function.?.parameters[index].value_type;
            return catalogue.refValue(held, self.definitions()) orelse held;
        }
        /// The type a variable cell held by node `cell` holds.
        fn cellValue(self: *const Self, cell: u32) types.Type {
            return catalogue.refValue(self.node(cell).value_type, self.definitions()).?;
        }
        fn internRef(self: *Self, value_type: types.Type, span: Span) ParseError!types.Type {
            return self.workspace.catalogue.internRef(value_type) catch |err| self.workspace.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
        }
        /// A read of a shared local, through its cell (RFC-0085, S2). Another function can
        /// change it, so it needs `<reads>` (S6).
        fn readCell(self: *Self, cell: u32, span: Span) ParseError!u32 {
            try self.stateEffect(span, .local_read);
            return self.emit(.{ .span = span, .value_type = self.cellValue(cell), .kind = .{ .ref_get = cell } });
        }
        /// Where the parameter `name` of the function being compiled comes from, through the
        /// captures of the closures around it (RFC-0085, S1: an identifier denotes a local
        /// `var` through the capture parameters of enclosing closures, at any depth): the local
        /// of an enclosing frame it was captured from (`local`), or a parameter of a function
        /// that captures nothing for it. `through_fn` says whether the path crosses an `Fn` the
        /// program wrote: S1d (I2) shares a local an `Fn` assigns.
        /// `through_closure`: the path crosses an `Fn`, a task body, an arm, a reaction or a
        /// landing (RFC-0085 Q10), not only functions the macro pass writes for loops, `First`
        /// and `Batch{}`, whose bodies are the code around them.
        /// `through_form` (I5): the path crosses a task body (`Spawn{}`, `Branch{}`, `Batch{}`), an
        /// arm, a reaction body or a landing, a closure form other than a guard: S1d shares a local
        /// one of them assigns, as it does for an `Fn`.
        const CaptureOrigin = struct { index: u32, local: bool, through_fn: bool, through_closure: bool = false, through_form: bool = false };
        fn captureOrigin(self: *const Self, name: []const u8) ?CaptureOrigin {
            const w = self.workspace;
            var function = self.function orelse return null;
            var depth = w.anonymous_count;
            while (depth != 0 and w.anonymous_frames[depth - 1].phase != .body) depth -= 1;
            var through_fn = false;
            var through_closure = false;
            var through_form = false;
            // Whether the name is a parameter of `function`, or the local a loop's function
            // declares to carry it, which the loop's state hands in (`Local.carried`).
            var carried = false;
            while (true) {
                if (depth == 0) {
                    // A named function's parameter.
                    if (carried) return null;
                    const index = self.parameterIn(function, name) orelse return null;
                    return .{ .index = index, .local = false, .through_fn = through_fn };
                }
                const frame = &w.anonymous_frames[depth - 1];
                if (!carried) {
                    const index = self.parameterIn(function, name) orelse return null;
                    // One of a specialization compiled in a body, which captures nothing.
                    if (frame.kind != .anonymous) return .{ .index = index, .local = false, .through_fn = through_fn };
                    const generated = !self.userFunction(function);
                    const closure = frame.task_body or frame.arm or frame.landing or frame.guard_body or frame.reaction != .none or frame.batch != null or frame.branch_body;
                    if (!generated and !closure) {
                        // An `Fn`: a capture, unless it listed them or this is a parameter it declares.
                        if (frame.explicit_captures or index >= frame.capture_count) return .{ .index = index, .local = false, .through_fn = through_fn };
                        through_fn = true;
                    }
                    if (frame.batch == null and ((!generated and !closure) or frame.task_body or frame.arm or frame.landing or frame.reaction != .none or frame.branch_body)) through_closure = true;
                    if ((frame.task_body or frame.arm or frame.landing) and !frame.guard_body and frame.reaction != .guard) through_form = true;
                }
                // The code around the frame: one of its locals, or one of its parameters. A loop's
                // carry is declared further out.
                var at = frame.locals;
                const found: ?u32 = while (at > frame.local_base) {
                    at -= 1;
                    if (std.mem.eql(u8, name, w.locals[at].name.text(w.source))) break at;
                } else null;
                depth -= 1;
                // An `Fn` written in the `[...]` list of another is inside no body of that one.
                while (depth != 0 and w.anonymous_frames[depth - 1].phase != .body) depth -= 1;
                if (found) |local| if (!w.locals[local].carried) return .{ .index = local, .local = true, .through_fn = through_fn, .through_closure = through_closure, .through_form = through_form };
                carried = found != null;
                function = frame.parent_function orelse return null;
            }
        }
        /// Whether the program wrote `function`, an anonymous function: its `Fn` word is the
        /// program's, or the one the macro pass gave it in a copy of a `Defer` body.
        fn userFunction(self: *const Self, function: functions.Definition) bool {
            const w = self.workspace;
            if (w.libraryModule(function.name) == null) return true;
            for (w.renamed_fns[0..w.renamed_fn_count]) |position| if (position == function.name.start) return true;
            return false;
        }
        fn parameterIn(self: *const Self, function: functions.Definition, name: []const u8) ?u32 {
            for (function.parameters[0..function.parameter_count], 0..) |entry, index| {
                if (std.mem.eql(u8, name, entry.name.text(self.workspace.source))) return @intCast(index);
            }
            return null;
        }
        /// RFC-0085, S1d (I2): `set X = E` in an `Fn` on what it captured for a local `var` of
        /// the code around it assigns the variable, which is shared. A cell the closure captured
        /// is written; a local not shared yet is noted, and the assignment compiles to nothing in
        /// a compile that is discarded (`wantShare`). A task body, an arm, a reaction body, a
        /// `Batch{}` body or a landing shares it too (I5); a parameter, an immutable local or an
        /// explicit capture cannot be assigned (`not_mutable`, or `arm_assigns_local` and
        /// `landing_assigns_local` there).
        fn sharedAssignment(self: *Self, name: Name) ParseError!?Assignment {
            const w = self.workspace;
            if (name.qualified) return null;
            const text = name.token.span.text(w.source);
            if (self.findLocal(text) != null) return null;
            const index = self.parameter(text) orelse return null;
            if (self.capturedBy(text) != null) return null;
            const held = self.function.?.parameters[index].value_type;
            if (catalogue.isRef(held, self.definitions())) {
                try self.stateEffect(name.span, .set);
                return .{ .ref = try self.emitTemplate(.{ .node = .{ .span = name.span, .value_type = held, .kind = .{ .integer = 0 } }, .input = .{ .parameter = index } }) };
            }
            if (!self.sharesCapture(text)) return null;
            try self.stateEffect(name.span, .set);
            return .{ .noted = held };
        }
        /// `set X[I] = V` (or `.F`), pending in `block`, updated no instance: if `X` is what an
        /// `Fn` captured for a local `var`, the assignment shares it (S1d). Its value was
        /// compiled as `X with ...`, which reads the cell once the local is shared.
        fn sharesTarget(self: *Self, block: *const Operator) ParseError!bool {
            const span: Span = .{ .start = block.head, .end = block.tail };
            return self.sharesCapture(span.text(self.workspace.source));
        }
        /// Whether `name`, a parameter of the function being compiled, is what an `Fn` captured
        /// for a local `var` not shared yet, and the declaration is noted (`wantShare`).
        fn sharesCapture(self: *Self, name: []const u8) bool {
            const w = self.workspace;
            if (self.findLocal(name) != null or self.parameter(name) == null or self.capturedBy(name) != null) return false;
            const origin = self.captureOrigin(name) orelse return false;
            if (!origin.local or !(origin.through_fn or origin.through_form) or !w.locals[origin.index].mutable) return false;
            return w.wantShare(w.locals[origin.index].name);
        }
        /// RFC-0085, S1b (I14, RFC-0084 P4.8): a guard names `name`, which denotes a local `var`
        /// not shared yet, directly, through a loop's carry or through the captures of the
        /// closures around it (`varOrigin`). The declaration is noted (`wantShare`), and in the
        /// compile after it the guard captures the cell and depends on it. False when the note
        /// cannot be taken, and the guard is refused as before P4.8.
        fn guardShares(self: *Self, name: []const u8) bool {
            const w = self.workspace;
            const origin = self.varOrigin(name) orelse return false;
            if (!w.locals[origin].mutable) return false;
            return w.wantShare(w.locals[origin].name);
        }
        /// What `set live X = G` attaches the guard to when `X` denotes a local `var` (RFC-0085,
        /// S1c, I14): its cell, the local's own or the one a closure captured for it, or, for a
        /// local not shared yet, a note (`wantShare`) and the type the statement compiles at in a
        /// compile that is discarded. Null for every other name, which `liveTarget` judges: a
        /// parameter, an immutable local, an explicit capture and a module cell keep their rules.
        const LocalLive = union(enum) { cell: u32, noted: types.Type };
        fn localLiveTarget(self: *Self, name: Name) ParseError!?LocalLive {
            const w = self.workspace;
            if (name.qualified or self.peek().kind != .equal) return null;
            const text = name.token.span.text(w.source);
            if (self.findLocal(text)) |id| {
                const local = w.locals[id];
                if (!local.shared and !local.mutable) return null;
                if (!local.shared) {
                    const origin = self.varOrigin(text) orelse return null;
                    if (!w.locals[origin].mutable or !w.wantShare(w.locals[origin].name)) return null;
                }
                w.noteName(name.token.span, local.name.start, .local, qualify.none);
                try self.liveLocalEffects(name.span, self.localType(id));
                if (!local.shared) return .{ .noted = self.node(local.node).value_type };
                return .{ .cell = local.node };
            }
            const index = self.parameter(text) orelse return null;
            if (self.capturedBy(text) != null) return null;
            const held = self.function.?.parameters[index].value_type;
            if (!catalogue.isRef(held, self.definitions())) {
                const origin = self.captureOrigin(text) orelse return null;
                if (!origin.local or !w.locals[origin.index].mutable or !w.wantShare(w.locals[origin.index].name)) return null;
            }
            w.noteName(name.token.span, self.function.?.parameters[index].name.start, .local, qualify.none);
            try self.liveLocalEffects(name.span, self.parameterType(index));
            if (!catalogue.isRef(held, self.definitions())) return .{ .noted = held };
            return .{ .cell = try self.emitTemplate(.{ .node = .{ .span = name.span, .value_type = held, .kind = .{ .integer = 0 } }, .input = .{ .parameter = index } }) };
        }
        /// Attaching a guard to a local's cell evaluates the guard, writes the cell and builds a
        /// record, as for a module `var` (RFC-0084, "Effects"): all three heap effects.
        fn liveLocalEffects(self: *Self, span: Span, value_type: types.Type) ParseError!void {
            try self.liveForm(span);
            try self.callEffect(span, .{ .reads = true, .writes = true, .allocates = true, .diverges = false });
            _ = self.workspace.catalogue.internLive(value_type) catch |err| return self.workspace.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
        }

        // ---- RFC-0085, I3: nested functions (S7).

        /// `Name(P)<effects>:R = Body` (or `:= Body`) at the start of a statement of the block on
        /// top, whose body begins at token `body_start`. Its body is compiled as an `Fn`'s is, a frame
        /// of its own that ends with the statement; its name means it from the next statement to
        /// the end of the block, and nothing stands where it is declared. The result is the
        /// parentheses open in the body, none.
        fn beginNested(self: *Self, token: Token, parentheses: u32, body_start: usize) ParseError!u32 {
            const w = self.workspace;
            if (w.anonymous_count == w.anonymous_frames.len or w.runtime_functions.count == types.limits.functions or w.nested_count == w.nested_functions.len) return w.fail(token.span, .function_limit);
            self.cursor += 1;
            // No access specifier (06:1180): it is private to the function that declares it.
            if (self.peek().kind == .less) {
                const word = w.tokens[self.cursor + 1];
                if (Access.named(word.span.text(w.source)) != null or std.mem.eql(u8, word.span.text(w.source), "scoped")) return w.fail(word.span, .nested_access);
                return w.fail(word.span, .unsupported_specifier);
            }
            // No type parameters (V6), here or in a `where` clause; the function around may have them.
            if (self.peek().kind == .left_bracket) return w.fail(token.span, .nested_generic);
            const close = w.segmentClose(self.cursor);
            for (w.tokens[self.cursor..close]) |inside| if (inside.kind == .identifier and std.mem.eql(u8, inside.span.text(w.source), "where")) return w.fail(inside.span, .nested_generic);
            // No access specifier (06:1180): it is private to the function that declares it.
            var at = close + 1;
            while (at + 2 < body_start and w.tokens[at].kind == .less) : (at += 3) {
                const word = w.tokens[at + 1].span.text(w.source);
                if (Access.named(word) != null or std.mem.eql(u8, word, "scoped")) return w.fail(w.tokens[at + 1].span, .nested_access);
            }
            self.nested_header = token.span.start;
            try self.checkShadow(token, true);
            self.nested_header = no_member;
            w.noteDeclaration(token.span, .local, qualify.none);
            w.anonymous_frames[w.anonymous_count] = .{
                .definition = .{ .name = token.span, .value_type = undefined, .is_public = false, .anonymous = true, .specialization = if (self.generic) |g| g.specialization else null, .generic_source = if (self.generic) |g| if (g.specialization != null) w.genericSourceFor(w.generic_templates[g.template].source, token.span) else .{ .start = 0, .end = 0 } else .{ .start = 0, .end = 0 }, .start = 0, .end = 0, .root = 0 },
                .parent_module = w.current_module,
                .parent_nested = w.current_nested,
                .parent_generic = self.generic,
                .parent_function = self.function,
                .parent_inferring = self.inferring,
                .expected_type = self.expected_type,
                .default_expression = self.default_expression,
                .control_depth = self.control_depth,
                .operator_base = self.operator_base,
                .operand_base = self.operand_base,
                .local_base = self.local_base,
                .parentheses = parentheses,
                .operators = self.operator_count,
                .operands = self.operand_count,
                .locals = w.local_count,
                .checkpoints = w.local_checkpoint_count,
                .failable_uses = w.failable_uses,
                .template_nodes = w.functions.node_count,
                .template_members = w.functions.member_count,
                .template_arguments = w.functions.argument_count,
                .staging = w.staging_count,
                .nested = true,
                .nested_entry = w.nested_count,
            };
            // Its entry first, so that its name is taken in its own signature and body.
            _ = w.pushNested(.{ .name = token.span, .block = self.operator_count - 1, .depth = w.anonymous_count });
            w.anonymous_count += 1;
            const frame = &w.anonymous_frames[w.anonymous_count - 1];
            var definition = frame.definition;
            _ = try self.take(.left_paren, .expected_parameter);
            // Defaults and named parameters as a top-level function has them (RFC-0085, I4, V8).
            try self.parseParameters(&definition, .nested);
            // A heap effect is mandatory (V2, RFC-0067 D10), as on every function.
            const effect = try self.parseEffect(.expected_computes);
            definition.transacts = effect.transacts;
            definition.decides = effect.decides;
            definition.detail = effect.detail;
            try self.checkNestedOverloads(frame.nested_entry, definition);
            if (self.peek().kind == .colon and w.tokens[self.cursor + 1].kind == .equal) {
                // Transparent (Part 2): the result type is the body's.
                self.cursor += 2;
                definition.is_transparent = true;
                definition.value_type = .i64;
                frame.infer = true;
            } else {
                const result = try self.parseResultType();
                definition.value_type = result.value_type;
                frame.discards = result.discards;
                _ = try self.take(.equal, .expected_equal);
            }
            std.debug.assert(self.cursor == body_start);
            try self.captureFreeNames(frame, &definition);
            // RFC-0085, I4: each default stays with its parameter, after the captures.
            if (frame.capture_count != 0) {
                const declared = definition.parameter_count - frame.capture_count;
                std.mem.copyBackwards(functions.Body, definition.defaults[frame.capture_count..definition.parameter_count], definition.defaults[0..declared]);
                @memset(definition.defaults[0..frame.capture_count], .{});
            }
            definition.start = w.functions.node_count;
            frame.definition = definition;
            frame.phase = .body;
            frame.template_nodes = w.functions.node_count;
            frame.template_members = w.functions.member_count;
            frame.template_arguments = w.functions.argument_count;
            frame.staging = w.staging_count;
            self.operator_base = self.operator_count;
            self.operand_base = self.operand_count;
            self.local_base = w.local_count;
            self.function = definition;
            _ = try self.bindPatterns(definition);
            self.inferring = null;
            self.expected_type = if (frame.infer or frame.discards) null else definition.value_type;
            self.default_expression = false;
            self.control_depth = 0;
            return 0;
        }

        /// The finished nested function of `frame` is code entry `target`: its captures are the
        /// first parameters of `definition`, named as the code around it names them.
        fn declareNested(self: *Self, frame: AnonymousFrame, definition: functions.Definition, target: u32) ParseError!void {
            const w = self.workspace;
            std.debug.assert(frame.nested_entry == w.nested_count - 1 and frame.capture_count <= definition.parameter_count);
            // Its captures, then its declared parameters with their defaults (RFC-0085, I4),
            // which named arguments and calls that leave some out read.
            const count = definition.parameter_count;
            if (count > w.nested_capture_names.len - w.nested_capture_count) return w.fail(definition.name, .parameter_limit);
            const start = w.nested_capture_count;
            for (definition.parameters[0..count], w.nested_capture_names[start..][0..count]) |parameter_entry, *name| name.* = parameter_entry.name;
            @memcpy(w.nested_defaults[start..][0..count], definition.defaults[0..count]);
            w.nested_capture_count += count;
            w.nested_functions[frame.nested_entry].captures = .{ .start = start, .end = start + frame.capture_count };
            w.nested_functions[frame.nested_entry].parameters_end = w.nested_capture_count;
            w.nested_functions[frame.nested_entry].runtime = target;
        }

        /// Forgets the nested functions of the block at `operator`, which closes.
        fn popNested(self: *Self, operator: u32) void {
            const w = self.workspace;
            while (w.nested_count > self.nested_floor) {
                const entry = w.nested_functions[w.nested_count - 1];
                if (entry.block != operator or entry.depth != w.anonymous_count) break;
                w.dropNested();
            }
        }

        /// The entry of the nested function whose body is being compiled, if the innermost
        /// function is one.
        fn ownNested(self: *const Self) u32 {
            const w = self.workspace;
            if (w.anonymous_count == 0) return no_member;
            const frame = &w.anonymous_frames[w.anonymous_count - 1];
            return if (frame.phase == .body and frame.nested) frame.nested_entry else no_member;
        }

        /// The nested function `name` that source position `at` sees: declared before it in a
        /// block still open, in the function being compiled or one around it, and not outside the
        /// body of a generic function compiled where it is called (a `.generic` frame), nor in a
        /// parse that an interruption suspended (`nested_floor`).
        fn findNested(self: *const Self, name: []const u8, at: u32) ?u32 {
            const w = self.workspace;
            if (w.nested_count == self.nested_floor) return null;
            var link = w.nested_buckets[Workspace.nestedBucket(name)];
            while (link > self.nested_floor) : (link = w.nested_functions[link - 1].next) {
                const index = link - 1;
                const entry = w.nested_functions[index];
                if (entry.name.start >= at or !std.mem.eql(u8, entry.name.text(w.source), name)) continue;
                // One declared outside the generic function whose body is being compiled is
                // not in its scope.
                var depth = w.anonymous_count;
                while (depth > entry.depth) {
                    depth -= 1;
                    if (w.anonymous_frames[depth].kind == .generic) return null;
                }
                return index;
            }
            return null;
        }

        /// The local `name` denotes in the code around a nested function being declared (S1):
        /// a local of that code, or what it carries for a loop, or the local a parameter of it
        /// was captured from, through the closures around.
        fn varOrigin(self: *const Self, name: []const u8) ?u32 {
            const w = self.workspace;
            if (self.findLocal(name)) |index| {
                if (!w.locals[index].carried) return index;
                // A loop's carry: the local is declared further out.
                var depth = w.anonymous_count;
                while (depth != 0) {
                    depth -= 1;
                    const frame = &w.anonymous_frames[depth];
                    if (frame.phase != .body) continue;
                    var at = frame.locals;
                    while (at > frame.local_base) {
                        at -= 1;
                        if (std.mem.eql(u8, name, w.locals[at].name.text(w.source)) and !w.locals[at].carried) return at;
                    }
                }
                return null;
            }
            if (self.parameter(name) == null) return null;
            const origin = self.captureOrigin(name) orelse return null;
            return if (origin.local) origin.index else null;
        }

        /// A use of nested function `index` at `resolved`: a direct call when a parenthesis
        /// follows (true: it is open), otherwise its value (false). Null for the function being
        /// compiled, whose own name is a recursion or its value (`startCall`, `literalName`).
        fn nestedOperand(self: *Self, index: u32, resolved: Name) ParseError!?bool {
            const w = self.workspace;
            const entry = w.nested_functions[index];
            if (entry.runtime == no_member) {
                if (self.ownNested() == index) return null;
                // A closure inside its body names it before it is complete, as a loop in a
                // named function cannot name that function.
                return w.fail(resolved.span, .unknown_name);
            }
            const f = w.runtime_functions.definitions[entry.runtime];
            // RFC-0085, I4: overloads agree on failing, and the arguments choose one, whose
            // effect is then checked (`nestedCall`).
            const overloaded = self.nextOverload(index) != null;
            if (self.peek().kind == .left_paren or self.peek().kind == .left_bracket) {
                if (!overloaded) try self.callEffect(resolved.span, f.effects());
                if (f.decides and !self.failureContext()) return w.fail(resolved.span, .failure_context_required);
                _ = try self.take(if (f.decides) .left_bracket else .left_paren, .expected_call);
                try self.pushOperator(.{ .kind = .recur, .span = resolved.span, .operand_base = self.operand_count, .selected = if (f.decides) 1 else no_member, .method = index });
                return true;
            }
            var chosen = index;
            if (overloaded) {
                // The expected function type picks the overload; nothing else can (RFC-0061).
                const expected = self.expectedContext() orelse return w.fail(resolved.span, .ambiguous_call);
                chosen = (try self.nestedByType(index, expected, resolved.span)) orelse return w.fail(resolved.span, .ambiguous_call);
                // RFC-0085, I11: the name means the overload chosen.
                w.noteName(resolved.token.span, w.nested_functions[chosen].name.start, .local, qualify.none);
            }
            try self.pushOperand(try self.nestedValue(chosen, resolved.span));
            return false;
        }

        /// The values of the captures of nested function `entry` where it is used: each name it
        /// captured, as the function being compiled has it, a local or a parameter that
        /// captured it in turn (`captureFreeNames`). Each is an immutable value or a cell.
        fn nestedCaptures(self: *Self, entry: NestedFunction, span: Span, into: *[types.limits.parameters]u32) ParseError!u32 {
            const w = self.workspace;
            const f = w.runtime_functions.definitions[entry.runtime];
            const names = w.nested_capture_names[entry.captures.start..entry.captures.end];
            std.debug.assert(names.len <= f.parameter_count);
            for (names, into[0..names.len], f.parameters[0..names.len]) |name, *value, required| {
                const text = name.text(w.source);
                value.* = if (self.findLocal(text)) |local| w.locals[local].node else if (self.parameter(text)) |parameter_index| try self.emitTemplate(.{ .node = .{ .span = span, .value_type = self.function.?.parameters[parameter_index].value_type, .kind = .{ .integer = 0 } }, .input = .{ .parameter = parameter_index } }) else return w.fail(span, .unknown_name);
                if (self.node(value.*).value_type != required) return w.fail(span, .type_mismatch);
            }
            return @intCast(names.len);
        }

        /// `callee`, a function value whose leading `captures.len` parameters of `parameters`
        /// are its captures, bound to them (RFC-0036): the value of the rest.
        fn bindCaptured(self: *Self, callee: u32, parameters: []const types.Type, result: types.Type, effect: Effect, captures: []const u32, span: Span) ParseError!u32 {
            if (captures.len == 0) return callee;
            const residual = try self.internTuple(parameters[captures.len..], span);
            const residual_type = try self.internCallable(.{ .parameters = residual, .result = result, .transacts = effect.transacts, .decides = effect.decides, .detail = effect.detail }, span);
            const arguments = try self.reserveArguments(captures, span);
            return self.emit(.{ .span = span, .value_type = residual_type, .kind = .{ .bind = .{ .callable = callee, .arguments = arguments } } });
        }

        /// Nested function `index` as a value: its `function_value`, bound to its captures.
        fn nestedValue(self: *Self, index: u32, span: Span) ParseError!u32 {
            const w = self.workspace;
            const entry = w.nested_functions[index];
            const f = w.runtime_functions.definitions[entry.runtime];
            var captures: [types.limits.parameters]u32 = undefined;
            const count = try self.nestedCaptures(entry, span, &captures);
            const parameters = try self.internTuple(f.parameters[0..f.parameter_count], span);
            const full = try self.internCallable(.{ .parameters = parameters, .result = f.value_type, .transacts = f.transacts, .decides = f.decides, .detail = f.detail }, span);
            const value = try self.emit(.{ .span = span, .value_type = full, .kind = .{ .function_value = entry.runtime } });
            return self.bindCaptured(value, f.parameters[0..f.parameter_count], f.value_type, .{ .transacts = f.transacts, .decides = f.decides, .detail = f.detail }, captures[0..count], span);
        }

        /// The value of the nested function `f` whose body this is: `self_value`, bound to its
        /// capture parameters.
        fn nestedSelf(self: *Self, f: functions.Definition, span: Span) ParseError!u32 {
            const w = self.workspace;
            const value = try self.emit(.{ .span = span, .value_type = try self.functionType(f, span), .kind = .self_value });
            const frame = w.anonymous_frames[w.anonymous_count - 1];
            var captures: [types.limits.parameters]u32 = undefined;
            var parameters: [types.limits.parameters]types.Type = undefined;
            for (f.parameters[0..f.parameter_count], parameters[0..f.parameter_count]) |entry, *t| t.* = entry.value_type;
            for (captures[0..frame.capture_count], 0..) |*read, position| read.* = try self.emitTemplate(.{ .node = .{ .span = span, .value_type = parameters[position], .kind = .{ .integer = 0 } }, .input = .{ .parameter = @intCast(position) } });
            return self.bindCaptured(value, parameters[0..f.parameter_count], f.value_type, Effect.of(f), captures[0..frame.capture_count], span);
        }

        /// A direct call of a nested function (`op.method` its entry): a `call` of its code entry
        /// with its captures where the call stands, then the arguments. In its own body
        /// (`op.method` none) a `recur` whose captures are its capture parameters.
        fn nestedCall(self: *Self, op: Operator, arguments: []const u32) ParseError!u32 {
            const w = self.workspace;
            var complete: [types.limits.parameters]u32 = undefined;
            var parameters: [types.limits.parameters]types.Type = undefined;
            var total: u32 = 0;
            var captures: u32 = 0;
            var result: types.Type = undefined;
            if (op.method != no_member) {
                var chosen = op.method;
                if (self.nextOverload(op.method) != null) {
                    // RFC-0085, I4: as for top-level overloads (RFC-0061), no named arguments,
                    // and the overload whose parameter types the arguments have.
                    if (op.tail != no_member) return w.fail(op.span, .named_argument_order);
                    chosen = self.chooseNested(op.method, arguments) orelse return w.fail(op.span, if (self.nestedArity(op.method, arguments.len)) .type_mismatch else .argument_count);
                    try self.callEffect(op.span, w.runtime_functions.definitions[w.nested_functions[chosen].runtime].effects());
                    // RFC-0085, I11: the name means the overload chosen.
                    w.noteName(op.span, w.nested_functions[chosen].name.start, .local, qualify.none);
                }
                const entry = w.nested_functions[chosen];
                const f = w.runtime_functions.definitions[entry.runtime];
                captures = try self.nestedCaptures(entry, op.span, &complete);
                total = f.parameter_count;
                @memcpy(parameters[0..total], f.parameters[0..total]);
                result = f.value_type;
                // Arguments by position, then by name; a parameter left out takes its default,
                // which reads the arguments before it as the function receives them (RFC-0058,
                // RFC-0076): each is evaluated once, by the caller.
                const slots = complete[captures..total];
                if (arguments.len > slots.len) return w.fail(op.span, .argument_count);
                @memset(slots, no_member);
                const positional: usize = if (op.tail == no_member) arguments.len else op.tail;
                for (arguments, 0..) |argument, ordinal| {
                    const target: usize = if (ordinal < positional) ordinal else @intCast(op.names >> @intCast(4 * (ordinal - positional)) & 0xf);
                    std.debug.assert(target < slots.len and slots[target] == no_member);
                    slots[target] = argument;
                }
                std.debug.assert(entry.parameters_end - entry.captures.end == slots.len);
                for (slots, w.nested_defaults[entry.captures.end..entry.parameters_end], parameters[captures..total], 0..) |*slot, default, required, position| {
                    if (slot.* == no_member) {
                        if (default.start == default.end) return w.fail(op.span, .argument_count);
                        slot.* = try self.expandBody(default, slots[0..position], op.span);
                    }
                    slot.* = try self.coerce(slot.*, required);
                }
                const range = try self.reserveArguments(complete[0..total], op.span);
                return self.checked(try self.emit(.{ .span = op.span, .value_type = result, .kind = .{ .call = .{ .function = entry.runtime, .arguments = range } } }));
            } else {
                const f = self.function.?;
                captures = w.anonymous_frames[w.anonymous_count - 1].capture_count;
                total = f.parameter_count;
                for (f.parameters[0..total], parameters[0..total]) |entry, *t| t.* = entry.value_type;
                for (complete[0..captures], 0..) |*read, position| read.* = try self.emitTemplate(.{ .node = .{ .span = op.span, .value_type = parameters[position], .kind = .{ .integer = 0 } }, .input = .{ .parameter = @intCast(position) } });
                result = f.value_type;
            }
            if (arguments.len != total - captures) return w.fail(op.span, .argument_count);
            for (arguments, complete[captures..total], parameters[captures..total]) |argument, *slot, required| slot.* = try self.coerce(argument, required);
            const range = try self.reserveArguments(complete[0..total], op.span);
            if (op.method == no_member) return self.checked(try self.emit(.{ .span = op.span, .value_type = result, .kind = .{ .recur = range } }));
            return self.checked(try self.emit(.{ .span = op.span, .value_type = result, .kind = .{ .call = .{ .function = w.nested_functions[op.method].runtime, .arguments = range } } }));
        }

        // ---- RFC-0085, I4: overloads, defaults and named parameters of nested functions.

        /// The default of parameter `name` of a nested function whose parameters before it are
        /// those of `function` (V8): read as a top-level function's default is (RFC-0058,
        /// RFC-0076), in a parse of its own (`interrupt`), so that it reads literals, what the
        /// modules declare and the parameters before it, and nothing of the code around its
        /// block (`nestedDefaultNames`). Its template is kept at the far end of the pools
        /// (`relocateDefault`), out of the body being compiled, for each call that leaves the
        /// parameter out to expand.
        fn nestedDefault(self: *Self, name: Token, value_type: types.Type, function: *const functions.Definition) ParseError!functions.Body {
            const w = self.workspace;
            try self.nestedDefaultNames(function);
            const members = w.functions.member_count;
            const arguments = w.functions.argument_count;
            const owner = function.*;
            const suspended = try self.interrupt(self.cursor, w.current_module, w.current_nested, self.generic, name.span);
            defer suspended.free();
            const read = try self.parseDefaultOf(name, value_type, &owner);
            const end = self.cursor;
            // An instantiation's default is kept there already.
            const kept = if (read.start >= w.functions.node_top) read else try self.relocateDefault(read, members, arguments, name.span);
            if (!suspended.restore(self)) return w.fail(name.span, .field_limit);
            self.cursor = end;
            return kept;
        }

        /// The default at the cursor (its `=`) names no local, parameter or nested function of
        /// the code around the block (`nested_default`): it is read where a top-level function's
        /// would be, and would not find them. The parameters before it (of `function`) it reads.
        fn nestedDefaultNames(self: *const Self, function: *const functions.Definition) ParseError!void {
            const w = self.workspace;
            var level: usize = 0;
            var at = self.cursor + 1;
            while (at < w.token_count) : (at += 1) {
                const token = w.tokens[at];
                switch (token.kind) {
                    .left_paren, .left_bracket, .left_brace => level += 1,
                    .right_paren, .right_bracket, .right_brace => {
                        if (level == 0) return;
                        level -= 1;
                    },
                    .comma => if (level == 0) return,
                    .eof => return,
                    .identifier => {
                        if (w.tokens[at - 1].kind == .dot or w.labelAt(at)) continue;
                        const text = token.span.text(w.source);
                        if (reserved(text)) continue;
                        const own = for (function.parameters[0..function.parameter_count]) |entry| {
                            if (std.mem.eql(u8, entry.name.text(w.source), text)) break true;
                        } else false;
                        if (own) continue;
                        if (self.findLocal(text) != null or self.parameter(text) != null or self.findNested(text, token.span.start) != null) return w.fail(token.span, .nested_default);
                    },
                    else => {},
                }
            }
        }

        /// Whether nested function `entry` is one of the block on top, where a nested function is
        /// being declared (`beginNested`): one that it may overload.
        fn nestedSibling(self: *const Self, entry: u32) bool {
            const w = self.workspace;
            const found = w.nested_functions[entry];
            return found.runtime != no_member and self.operator_count != 0 and found.block == self.operator_count - 1 and found.depth == w.anonymous_count;
        }

        /// The nested function of the name of `index` declared before it in its block, which it
        /// overloads (06:1128): the next entry of that name down its bucket's chain. The names
        /// of a block are distinct but for overloads (`checkShadow`), so these are all of them.
        fn nextOverload(self: *const Self, index: u32) ?u32 {
            const w = self.workspace;
            const entry = w.nested_functions[index];
            const name = entry.name.text(w.source);
            var link = entry.next;
            while (link > self.nested_floor) : (link = w.nested_functions[link - 1].next) {
                const other = w.nested_functions[link - 1];
                if (other.block == entry.block and other.depth == entry.depth and std.mem.eql(u8, other.name.text(w.source), name)) return link - 1;
            }
            return null;
        }

        /// The types of the declared parameters of nested function `index`, its captures aside.
        fn nestedDeclared(self: *const Self, index: u32) []const types.Type {
            const w = self.workspace;
            const entry = w.nested_functions[index];
            const f = &w.runtime_functions.definitions[entry.runtime];
            return f.parameters[entry.captures.end - entry.captures.start .. f.parameter_count];
        }

        /// Nested function `index`, whose signature is `definition`, against those of its block it
        /// overloads, under the rules of top-level overloads (RFC-0061, RFC-0076 D16): its
        /// parameter types differ from each one's, at a position where no value fits both, and it
        /// fails as they do, since `F(...)` or `F[...]` is chosen before the arguments are read.
        fn checkNestedOverloads(self: *Self, index: u32, definition: functions.Definition) ParseError!void {
            const w = self.workspace;
            const ours = definition.parameters[0..definition.parameter_count];
            const our_types = parameterTypes(&definition);
            var overload = self.nextOverload(index);
            while (overload) |other| : (overload = self.nextOverload(other)) {
                const theirs = self.nestedDeclared(other);
                if (theirs.len == ours.len) {
                    const same = for (theirs, ours) |a, b| {
                        if (a != b.value_type) break false;
                    } else true;
                    if (same) return w.fail(definition.name, .duplicate_name);
                    switch (self.signaturesOverlap(theirs, our_types[0..ours.len])) {
                        .apart => {},
                        .overlap => return w.fail(definition.name, self.relatedCode(theirs, our_types[0..ours.len])),
                        // A class still to be declared decides: its declaration checks the two
                        // again (`recheckLateOverloads`), long after this block has closed.
                        .pending => {
                            var earliest = other;
                            while (self.nextOverload(earliest)) |earlier| earliest = earlier;
                            if (w.nested_functions[earliest].late_block == 0) {
                                w.late_block_count += 1;
                                w.nested_functions[earliest].late_block = w.late_block_count;
                            }
                            const group = w.nested_functions[earliest].name.start;
                            const block = w.nested_functions[earliest].late_block;
                            try self.noteLateOverload(group, block, w.nested_functions[other].name, theirs);
                            try self.noteLateOverload(group, block, definition.name, our_types[0..ours.len]);
                        },
                    }
                }
                if (w.runtime_functions.definitions[w.nested_functions[other].runtime].decides != definition.decides) return w.fail(definition.name, .overload_conflict);
            }
        }

        /// The most arguments a call of nested function `index` or of one it overloads takes,
        /// captures included (`finishArgument` counts them; `nestedCall` checks them).
        fn nestedBound(self: *const Self, index: u32) u32 {
            const w = self.workspace;
            var most: u32 = 0;
            var overload: ?u32 = index;
            while (overload) |candidate| : (overload = self.nextOverload(candidate)) most = @max(most, w.runtime_functions.definitions[w.nested_functions[candidate].runtime].parameter_count);
            return most;
        }

        /// Whether nested function `index` or one it overloads has `count` declared parameters.
        fn nestedArity(self: *const Self, index: u32, count: usize) bool {
            var overload: ?u32 = index;
            while (overload) |candidate| : (overload = self.nextOverload(candidate)) if (self.nestedDeclared(candidate).len == count) return true;
            return false;
        }

        /// The type the argument being read of a call of nested function `operator.method` is
        /// read with: that of the parameter it names or stands at, and for overloads the one
        /// every overload takes there, none where they disagree (RFC-0061).
        fn nestedContext(self: *const Self, operator: Operator) ?types.Type {
            const position: usize = if (operator.head != no_member) operator.head else if (operator.tail != no_member) return null else operator.arguments;
            var found: ?types.Type = null;
            var overload: ?u32 = operator.method;
            while (overload) |candidate| : (overload = self.nextOverload(candidate)) {
                const declared = self.nestedDeclared(candidate);
                if (position >= declared.len) continue;
                if (found == null) found = declared[position] else if (found.? != declared[position]) return null;
            }
            return found;
        }

        /// The overload of nested function `index` whose parameter types are exactly those of
        /// `arguments`, or else the most specific one that takes them as instances of subclasses,
        /// as `Workspace.chooseOverload` chooses among top-level overloads.
        fn chooseNested(self: *const Self, index: u32, arguments: []const u32) ?u32 {
            const definitions_now = self.definitions();
            var overload: ?u32 = index;
            while (overload) |candidate| : (overload = self.nextOverload(candidate)) {
                const declared = self.nestedDeclared(candidate);
                if (declared.len != arguments.len) continue;
                const matches = for (declared, arguments) |wanted, argument| {
                    if (wanted != self.node(argument).value_type) break false;
                } else true;
                if (matches) return candidate;
            }
            // As `Workspace.chooseOverload`: the one that is narrower than every other that takes them.
            var best: ?u32 = null;
            overload = index;
            while (overload) |candidate| : (overload = self.nextOverload(candidate)) {
                if (!self.nestedAccepts(candidate, arguments, definitions_now)) continue;
                const current = best orelse {
                    best = candidate;
                    continue;
                };
                if (self.nestedNarrower(candidate, current, definitions_now)) best = candidate;
            }
            const chosen = best orelse return null;
            overload = index;
            while (overload) |candidate| : (overload = self.nextOverload(candidate)) {
                if (candidate == chosen or !self.nestedAccepts(candidate, arguments, definitions_now)) continue;
                // Two that take them with no most specific one are ambiguous.
                if (!self.nestedNarrower(chosen, candidate, definitions_now)) return null;
            }
            return chosen;
        }

        fn nestedAccepts(self: *const Self, candidate: u32, arguments: []const u32, definitions_now: []const types.Definition) bool {
            const declared = self.nestedDeclared(candidate);
            if (declared.len != arguments.len) return false;
            return for (declared, arguments) |wanted, argument| {
                if (!catalogue.assignable(self.node(argument).value_type, wanted, definitions_now)) break false;
            } else true;
        }

        /// Whether nested overload `narrow` takes fewer values than `wide`, which takes as many arguments.
        fn nestedNarrower(self: *const Self, narrow: u32, wide: u32, definitions_now: []const types.Definition) bool {
            const own = self.nestedDeclared(narrow);
            const other = self.nestedDeclared(wide);
            std.debug.assert(own.len == other.len);
            var different = false;
            for (own, other) |a, b| {
                if (!catalogue.assignable(a, b, definitions_now)) return false;
                different = different or a != b;
            }
            return different;
        }

        /// The overload of nested function `index` whose value has type `expected`: the type of
        /// its declared parameters, which `nestedValue` gives it.
        fn nestedByType(self: *Self, index: u32, expected: types.Type, span: Span) ParseError!?u32 {
            const w = self.workspace;
            var overload: ?u32 = index;
            while (overload) |candidate| : (overload = self.nextOverload(candidate)) {
                const f = w.runtime_functions.definitions[w.nested_functions[candidate].runtime];
                const parameters = try self.internTuple(self.nestedDeclared(candidate), span);
                const value_type = try self.internCallable(.{ .parameters = parameters, .result = f.value_type, .transacts = f.transacts, .decides = f.decides, .detail = f.detail }, span);
                if (value_type == expected) return candidate;
            }
            return null;
        }

        /// Opens `Return(`: an exit of the function being compiled, whose `(` follows.
        fn startExit(self: *Self, span: Span) ParseError!void {
            const w = self.workspace;
            // A task has no caller to return to (RFC-0082, Book 14:595).
            if (self.taskBody()) return w.fail(span, .return_in_task_body);
            // Nor does the guard or the body of a reaction (RFC-0084, P4.4).
            if (self.reactionArm()) return w.fail(span, .return_in_task_body);
            // Nor does an arm, until P3.6 (`exit_in_arm`).
            if (self.armBody()) return w.fail(span, .exit_in_arm);
            if (self.function == null or self.default_expression) return w.fail(span, .return_outside_function);
            if (self.class_block and w.anonymous_count == 0) return w.fail(span, .return_outside_function);
            if (w.anonymous_count != 0) {
                // The operand is checked against the result type, so the function has to state it.
                const frame = w.anonymous_frames[w.anonymous_count - 1];
                if (frame.phase == .body and frame.infer) return w.fail(span, .return_type_required);
            }
            // So does a transparent function (RFC-0085, I7).
            if (self.function.?.is_transparent) return w.fail(span, .return_type_required);
            // Like `Fail`, a `Return` yields nothing and so fits what its place expects; where
            // nothing is expected it is `logic`, the type of a statement such as `While`.
            const context = self.expectedContext() orelse .logic;
            _ = try self.take(.left_paren, .expected_call);
            try self.pushOperator(.{ .kind = .exit, .span = span, .operand_base = self.operand_count, .value_type = context });
        }

        /// The result type of the function a `Return` written here leaves: the one being compiled,
        /// or the one around the generated loop functions it is nested in.
        fn exitType(self: *const Self, span: Span) ParseError!types.Type {
            const w = self.workspace;
            var function = self.function orelse return w.fail(span, .return_outside_function);
            var depth = w.anonymous_count;
            // A function whose header is still being read is not the one being compiled.
