        /// whose `)` precedes `end`: that exit itself, or blocks that end in it. A name bound
        /// to an exit is not: it has the type it was given, and other code may have used it.
        fn armEndsAt(self: *const Self, end: u32) bool {
            const tokens = &self.workspace.tokens;
            var at = self.cursor - 1;
            while (at != 0) {
                at -= 1;
                const kind = tokens[at].kind;
                if (kind != .right_brace and kind != .newline and kind != .separator) break;
            }
            return end != 0 and at + 1 == end;
        }
        /// RFC-0090: `If(Condition, Then)` without an else, whose `)` is `token`. It runs `Then`
        /// when the condition holds and is the unit value `tuple{}` (type `void`) either way:
        /// `Then`'s value is dropped as a statement's is, so a comparison there is
        /// `discarded_comparison`. Each arm yields its own unit, so no node reads `Then`; the
        /// `If` is noted (`valueless`) so that a place that needs its value names the cause.
        fn closeElseless(self: *Self, op: Operator, then: u32, token: Token) ParseError!u32 {
            // An arm that leaves (`Return`, `Err`) yields nothing; it takes the unit's type below.
            const leaving = self.leaves(then) and self.armEndsAt(self.exit_end);
            var left = then;
            if (!leaving) {
                try self.checkDiscarded(then);
                left = try self.packTuple(&.{}, op.span);
            }
            if (op.head != no_member) {
                left = try self.packLocalVersions(op.head, left, op.span);
                self.restoreLocalVersions(op.head);
            }
            _ = try self.emit(.{ .span = token.span, .value_type = .logic, .kind = .{ .otherwise = op.function } });
            const unit = try self.packTuple(&.{}, op.span);
            if (leaving) {
                self.mutableNode(then).value_type = self.node(unit).value_type;
                if (left != then) try self.retypeTuple(left);
            }
            const right = if (op.head != no_member) try self.packLocalVersions(op.head, unit, op.span) else unit;
            const merged = try self.emit(.{ .span = op.span, .value_type = self.node(right).value_type, .kind = .{ .merge = .{ .begin = op.function, .left = left, .right = right } } });
            const result = if (op.head == no_member) merged else try self.selectLocalVersions(op.head, merged, op.span);
            // The span as the node holds it: generated code is blamed on the call it came from.
            // With it a node made at the same index after a discarded trial is not taken for this one.
            self.valueless = .{ .node = result, .span = self.node(result).span, .in_function = self.function != null };
            return result;
        }
        /// Whether `index` is the value of the `If` without an else compiled last (RFC-0090).
        fn valuelessAt(self: *const Self, index: u32) bool {
            const noted = self.valueless;
            if (noted.node != index or noted.in_function != (self.function != null)) return false;
            const span = self.node(index).span;
            return span.start == noted.span.start and span.end == noted.span.end;
        }
        /// Whether the node at `index` never yields a value because control leaves there.
        fn leaves(self: *const Self, index: u32) bool {
            const kind = self.node(index).kind;
            return kind == .exit or kind == .err or kind == .arm_exit;
        }
        /// Gives a tuple built by `packTuple` the type its members have now.
        fn retypeTuple(self: *Self, index: u32) ParseError!void {
            const range = self.node(index).kind.aggregate;
            var elements: [3]types.Type = undefined;
            const members = self.memberPool()[range.start..range.end];
            std.debug.assert(members.len <= elements.len);
            for (members, elements[0..members.len]) |member, *value_type| value_type.* = self.node(member).value_type;
            const value_type = try self.internTuple(elements[0..members.len], self.node(index).span);
            self.mutableNode(index).value_type = value_type;
        }
        fn packLocalVersions(self: *Self, id: u32, result: u32, span: Span) ParseError!u32 {
            const w = self.workspace;
            std.debug.assert(id + 1 == w.local_checkpoint_count);
            const checkpoint = &w.local_checkpoints[id];
            std.debug.assert(checkpoint.count <= w.local_count and checkpoint.mutable_count > 0);
            var group: [128]u32 = undefined;
            var group_count: u32 = 0;
            var outer: [3]u32 = undefined;
            outer[0] = result;
            var outer_count: u32 = 1;
            for (w.locals[0..checkpoint.count], checkpoint.nodes[0..checkpoint.count]) |entry, version| {
                if (version == no_member) continue;
                std.debug.assert(entry.mutable);
                group[group_count] = entry.node;
                group_count += 1;
                if (group_count == group.len) {
                    outer[outer_count] = try self.packTuple(&group, span);
                    outer_count += 1;
                    group_count = 0;
                }
            }
            if (group_count > 0) {
                outer[outer_count] = try self.packTuple(group[0..group_count], span);
                outer_count += 1;
            }
            std.debug.assert(outer_count >= 2 and outer_count <= outer.len);
            return self.packTuple(outer[0..outer_count], span);
        }
        fn tupleProjection(self: *Self, value: u32, index: u32, span: Span) ParseError!u32 {
            const w = self.workspace;
            const value_type = catalogue.tupleElementAt(self.node(value).value_type, index, self.definitions(), w.catalogue.tuple_elements[0..w.catalogue.tuple_count]).?;
            return self.emit(.{ .span = span, .value_type = value_type, .kind = .{ .tuple_element = .{ .value = value, .index = index } } });
        }
        fn selectLocalVersions(self: *Self, id: u32, selected: u32, span: Span) ParseError!u32 {
            const w = self.workspace;
            std.debug.assert(id + 1 == w.local_checkpoint_count);
            const checkpoint = &w.local_checkpoints[id];
            const result = try self.tupleProjection(selected, 0, span);
            var ordinal: u32 = 0;
            var group: u32 = no_member;
            for (w.locals[0..checkpoint.count], checkpoint.nodes[0..checkpoint.count]) |*entry, version| {
                if (version == no_member) continue;
                if (ordinal % 128 == 0) group = try self.tupleProjection(selected, 1 + ordinal / 128, span);
                entry.node = try self.tupleProjection(group, ordinal % 128, span);
                ordinal += 1;
            }
            std.debug.assert(ordinal == checkpoint.mutable_count);
            w.local_checkpoint_count -= 1;
            return result;
        }

        fn closeBlock(self: *Self, token: Token, empty: bool) ParseError!void {
            var ended = empty;
            if (self.class_block and self.workspace.anonymous_count == 0) {
                // A block clause of a class runs for what it does, so it may end with a statement:
                // a `set` or a declaration still pending, or nothing after the last separator.
                const w = self.workspace;
                const block = if (empty) &w.operators[self.operator_count - 1] else try self.reduceToDelimiter(token);
                if (block.kind == .block and block == &w.operators[self.operator_base]) {
                    if (!empty and block.head != no_member) {
                        try self.finishLocal(block);
                        self.operand_count = block.operand_base;
                        ended = true;
                    } else if (!empty and self.operand_count == block.operand_base + 1) try self.checkDiscarded(w.operands[block.operand_base]);
                    if (ended and block.head == no_member and self.operand_count == block.operand_base) {
                        try self.pushOperand(try self.emit(.{ .span = token.span, .value_type = .logic, .kind = .{ .boolean = true } }));
                        ended = false;
                    }
                }
            }
            if (ended) return self.workspace.fail(token.span, .expected_expression);
            const op = (try self.reduceToDelimiter(token)).*;
            if (op.kind != .block or op.head != no_member or self.operand_count != op.operand_base + 1) return self.workspace.fail(token.span, .expected_expression);
            std.debug.assert(op.function <= self.workspace.local_count);
            self.workspace.local_count = op.function;
            self.popDeferMarks(self.operator_count - 1);
            self.popNested(self.operator_count - 1);
            self.operator_count -= 1;
        }

        fn parameter(self: *const Self, name: []const u8) ?u32 {
            const function = self.function orelse return null;
            for (function.parameters[0..function.parameter_count], 0..) |entry, index| {
                if (std.mem.eql(u8, name, entry.name.text(self.workspace.source))) return @intCast(index);
            }
            return null;
        }

        fn reserveArguments(self: *Self, arguments: []const u32, span: Span) ParseError!Span {
            const w = self.workspace;
            const count = if (self.function != null) &w.functions.argument_count else &w.call_argument_count;
            const pool = if (self.function != null) &w.functions.arguments else &w.call_arguments;
            const limit = if (self.function != null) w.functions.argument_top else pool.len;
            if (arguments.len > limit - count.*) return w.fail(span, .call_argument_limit);
            const range: Span = .{ .start = count.*, .end = count.* + @as(u32, @intCast(arguments.len)) };
            @memcpy(pool[range.start..range.end], arguments);
            count.* = range.end;
            return range;
        }

        /// `Items[I]` reads an element, failing when `I` is outside `0..Length`. The
        /// bound is an ordinary `demand`, so rollback, traces and failure contexts
        /// are exactly those of `Require`; the pure `array_get` runs only after it.
        fn emitIndex(self: *Self, operator: Operator, arguments: []const u32) ParseError!u32 {
            const w = self.workspace;
            if (arguments.len != 1) return w.fail(operator.span, .argument_count);
            const index = arguments[0];
            const array = operator.function;
            const span = operator.span;
            // RFC-0087, P5.4: `X[K]` of a keyed cell, the lookup of a map's but of the cell.
            if (operator.head == keyed_cell_head) {
                const entries = catalogue.entryShape(w.source_cells[operator.method].value_type, self.definitions()).?;
                const key = try self.coerce(index, entries.key);
                const option_type = w.catalogue.internOption(entries.value) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                const found = try self.emit(.{ .span = span, .value_type = option_type, .kind = .{ .weak_get = .{ .cell = operator.method, .key = key } } });
                const present = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .option_present = found } });
                _ = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .demand = present } });
                return self.emit(.{ .span = span, .value_type = entries.value, .kind = .{ .option_value = found } });
            }
            if (self.node(array).value_type == .string) {
                // `S[I]`: the same bounds `demand` as an array read, then the code unit.
                if (self.node(index).value_type != .i64) return w.fail(self.node(index).span, .type_mismatch);
                const length = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .string_length = array } });
                const lower = try self.emitCompare(span, .greater_equal, index, try self.emitInteger(span, 0));
                const upper = try self.emitCompare(span, .less, index, length);
                try self.emitDemand(span, try self.emitBoth(span, lower, upper));
                return self.emitText(span, types.Type.char, .unit, .{ array, index, 0 });
            }
            const container = catalogue.definition(self.node(array).value_type, self.definitions()).?;
            // RFC-0087, W2: `W[K]` on a `weak_map` is the same lookup.
            if (catalogue.entryShape(self.node(array).value_type, self.definitions())) |entries| {
                // `M[K]` is a lookup that fails when the key is absent.
                const key = try self.coerce(index, entries.key);
                const option_type = w.catalogue.internOption(entries.value) catch |err| return w.fail(span, if (err == error.TypeLimit) .type_limit else .unsupported_type);
                const found = try self.emit(.{ .span = span, .value_type = option_type, .kind = .{ .map_lookup = .{ .map = array, .key = key } } });
                const present = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .option_present = found } });
                _ = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .demand = present } });
                return self.emit(.{ .span = span, .value_type = entries.value, .kind = .{ .option_value = found } });
            }
            if (self.node(index).value_type != .i64) return w.fail(self.node(index).span, .type_mismatch);
            const element = container.array;
            const length = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .array_length = array } });
            const zero = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .integer = 0 } });
            const lower = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .compare = .{ .op = .greater_equal, .lhs = index, .rhs = zero } } });
            const upper = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .compare = .{ .op = .less, .lhs = index, .rhs = length } } });
            const inside = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .logic_binary = .{ .op = .both, .lhs = lower, .rhs = upper } } });
            _ = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .demand = inside } });
            return self.emit(.{ .span = span, .value_type = element, .kind = .{ .array_get = .{ .array = array, .index = index } } });
        }

        /// `Type[Value]` for a value held as `any` (RFC-0080): the value as a `Type`, failing
        /// unless it is one. For a class or interface that is the test of an instance; for
        /// every other type the value was made as exactly that type or it is not of it.
        fn castFromAny(self: *Self, span: Span, operand: u32, target: types.Type) ParseError!u32 {
            const w = self.workspace;
            std.debug.assert(self.node(operand).value_type == types.Type.any);
            if (target == types.Type.any) return operand;
            if (!self.failureContext()) return w.fail(span, .failure_context_required);
            const is_one = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .instance_of = .{ .value = operand, .class = target } } });
            _ = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .demand = is_one } });
            return self.emit(.{ .span = span, .value_type = target, .kind = .{ .downcast = operand } });
        }

        /// `Refinement[Value]` (RFC-0083): the value of the base, failing unless it lies within
        /// the bounds. The test is a `demand` of comparisons with the bounds, then `refine` makes
        /// the value one of the refinement; each machine checks the bounds again there. A float
        /// is always compared on both sides, so that a NaN, which no comparison holds for, fails
        /// here. A value of another type, `any` included, is not converted: types stay exact.
        fn emitRefinementCast(self: *Self, span: Span, operand: u32, target: types.Type, refinement: types.Refinement) ParseError!u32 {
            const w = self.workspace;
            if (self.node(operand).value_type != refinement.base) return w.fail(self.node(operand).span, .type_mismatch);
            if (!self.failureContext()) return w.fail(span, .failure_context_required);
            var inside: ?u32 = null;
            if (refinement.base == .i64) {
                const low: i64 = @bitCast(refinement.low);
                const high: i64 = @bitCast(refinement.high);
                if (low != std.math.minInt(i64)) inside = try self.emitCompare(span, .greater_equal, operand, try self.emitInteger(span, low));
                if (high != std.math.maxInt(i64)) {
                    const below = try self.emitCompare(span, .less_equal, operand, try self.emitInteger(span, high));
                    inside = if (inside) |above| try self.emitBoth(span, above, below) else below;
                }
            } else {
                const low = try self.emit(.{ .span = span, .value_type = .float, .kind = .{ .floating = @bitCast(refinement.low) } });
                const high = try self.emit(.{ .span = span, .value_type = .float, .kind = .{ .floating = @bitCast(refinement.high) } });
                const above = try self.emitCompare(span, if (refinement.low_open) .greater else .greater_equal, operand, low);
                const below = try self.emitCompare(span, if (refinement.high_open) .less else .less_equal, operand, high);
                inside = try self.emitBoth(span, above, below);
            }
            if (inside) |condition| try self.emitDemand(span, condition);
            return self.emit(.{ .span = span, .value_type = target, .kind = .{ .refine = operand } });
        }

        /// The type that `Name[` casts to when `Name` is a type that is not a class: a scalar,
        /// an alias, a struct, an enum, a type parameter. Only a value held as `any` is cast to
        /// one (RFC-0080). A value or function of the name is what the name means first.
        fn castTarget(self: *Self, name: Name) ParseError!?types.Type {
            const w = self.workspace;
            const text = name.token.span.text(w.source);
            if (!name.qualified and (self.findLocal(text) != null or self.parameter(text) != null)) return null;
            if (w.findSymbolIn(text, name.scope) != null or w.plainFunctionIn(text, name.scope) != null or w.findNativeIn(text, name.scope) != null) return null;
            if (!name.qualified) if (self.genericType(text)) |bound| {
                if (w.qualify) if (self.typeParameterSpan(text)) |declared| w.noteName(name.token.span, declared.start, .local, qualify.none);
                return bound;
            };
            if (w.findTypeAliasIn(text, name.scope)) |alias| {
                if (!self.visible(alias.name)) return null;
                if (name.sealed() and !alias.is_public) return w.fail(name.span, .private_name);
                w.noteName(name.token.span, alias.name.start, .global, qualify.none);
                return alias.value;
            }
            if (name.qualified or self.findGeneric(text, name.scope) != null) return null;
            if (w.catalogue.findNamedIn(text, w.source, name.scope) != null) return null;
            if (std.meta.stringToEnum(types.Type, text)) |builtin| {
                w.noteName(name.token.span, qualify.none, .builtin, qualify.none);
                return builtin;
            }
            if (Workspace.characterType(text)) |builtin| {
                w.useCharacter(builtin);
                w.noteName(name.token.span, qualify.none, .builtin, qualify.none);
                return builtin;
            }
            if (std.mem.eql(u8, text, "rational")) {
                w.noteName(name.token.span, qualify.none, .builtin, qualify.none);
                return try self.rationalType(name.span);
            }
            return null;
        }

        /// `ToFloat(N)` converts exactly to the nearest binary64. `Floor`, `Ceil`, `Round`
        /// (ties to even) and `Int` (toward zero) convert a float to `i64`; they fail,
        /// via an ordinary `demand`, unless the argument is finite and within i64 range.
        fn emitConvert(self: *Self, operator: Operator, arguments: []const u32) ParseError!u32 {
            const w = self.workspace;
            const conversion: Conversion = @fromBackingInt(@intCast(operator.function));
            if (conversion == .quotient or conversion == .modulo or conversion == .rational) return self.emitDivision(conversion, operator, arguments);
            const span = operator.span;
            if (conversion == .final_super_class) return self.emitFinalSuper(operator, arguments);
            if (conversion.bitwise()) |op| {
                if (arguments.len != @as(usize, if (conversion == .bit_not) 1 else 2)) return w.fail(span, .argument_count);
                for (arguments) |argument| if (self.node(argument).value_type != .i64) return w.fail(self.node(argument).span, .type_mismatch);
                // Inverting every bit is exclusive-or with all ones, which is -1 in two's complement.
                const rhs = if (conversion == .bit_not) try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .integer = -1 } }) else arguments[1];
                return self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .binary = .{ .op = op, .lhs = arguments[0], .rhs = rhs } } });
            }
            if (arguments.len != 1) return w.fail(operator.span, .argument_count);
            const operand = arguments[0];
            if (conversion.pattern()) return self.emitPatternForm(conversion, operator, operand);
            if (conversion == .interpolation or conversion == .string) {
                if (try self.emitUserText(operator, operand)) |called| return called;
                // `ToString(Value)` written out: the builtin is what the name means here.
                if (conversion == .string) {
                    if (w.qualify and w.declaresText()) w.noteVaries(operator.span) else w.noteName(operator.span, qualify.none, .builtin, qualify.none);
                }
            }
            if (conversion == .interpolation) {
                const kind = self.node(operand).value_type;
                if (kind == .string) return operand;
                // A refinement (RFC-0083) is written as its base is.
                if (catalogue.refinementOf(kind, self.definitions())) |refinement| return self.emit(.{ .span = span, .value_type = .string, .kind = .{ .to_string = try self.emit(.{ .span = span, .value_type = refinement.base, .kind = .{ .refine = operand } }) } });
                if (kind != .i64 and kind != .float and kind != .logic and !kind.isCharacter()) return w.fail(self.node(operand).span, .type_mismatch);
                return self.emit(.{ .span = span, .value_type = .string, .kind = .{ .to_string = operand } });
            }
            if (conversion == .units) {
                // `string[Units]`: the units must be valid UTF-8, which is the whole condition.
                if (self.node(operand).value_type == types.Type.any) return self.castFromAny(span, operand, .string);
                const shape = catalogue.definition(self.node(operand).value_type, self.definitions()) orelse return w.fail(self.node(operand).span, .type_mismatch);
                if (shape != .array or shape.array != types.Type.char) return w.fail(self.node(operand).span, .type_mismatch);
                try self.emitDemand(span, try self.emitText(span, .logic, .valid, .{ operand, 0, 0 }));
                return self.emitText(span, .string, .join, .{ operand, 0, 0 });
            }
            if (conversion == .cast) {
                const target = operator.value_type.?;
                const actual = self.node(operand).value_type;
                if (catalogue.refinementOf(target, self.definitions())) |refinement| return self.emitRefinementCast(span, operand, target, refinement);
                if (actual == types.Type.any) return self.castFromAny(span, operand, target);
                // Anything else is cast only among classes and interfaces.
                const target_shape = catalogue.definition(target, self.definitions()) orelse return w.fail(self.node(operand).span, .type_mismatch);
                if (target_shape != .class) return w.fail(self.node(operand).span, .type_mismatch);
                const operand_shape = catalogue.definition(actual, self.definitions()) orelse return w.fail(self.node(operand).span, .type_mismatch);
                if (operand_shape != .class) return w.fail(self.node(operand).span, .type_mismatch);
                if (catalogue.subtype(actual, target, self.definitions())) return self.coerce(operand, target);
                if (!catalogue.castable(target, actual, self.definitions())) return w.fail(self.node(operand).span, .type_mismatch);
                if (!self.failureContext()) return w.fail(span, .failure_context_required);
                const is_instance = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .instance_of = .{ .value = operand, .class = target } } });
                _ = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .demand = is_instance } });
                return self.emit(.{ .span = span, .value_type = target, .kind = .{ .downcast = operand } });
            }
            if (conversion == .string) {
                const kind = self.node(operand).value_type;
                // The Book's `ToString` of a string hands back what it was given (RFC-0077).
                if (kind == .string) return operand;
                if (catalogue.refinementOf(kind, self.definitions())) |refinement| return self.emit(.{ .span = span, .value_type = .string, .kind = .{ .to_string = try self.emit(.{ .span = span, .value_type = refinement.base, .kind = .{ .refine = operand } }) } });
                if (kind != .i64 and kind != .float and kind != .logic and !kind.isCharacter()) return w.fail(self.node(operand).span, .type_mismatch);
                return self.emit(.{ .span = span, .value_type = .string, .kind = .{ .to_string = operand } });
            }
            if (conversion == .float) {
                if (catalogue.isRational(self.node(operand).value_type, self.definitions())) return self.emit(.{ .span = span, .value_type = .float, .kind = .{ .rational = .{ .op = .to_float, .lhs = operand, .rhs = operand } } });
                if (self.node(operand).value_type != .i64) return w.fail(self.node(operand).span, .type_mismatch);
                return self.emit(.{ .span = span, .value_type = .float, .kind = .{ .int_to_float = operand } });
            }
            if (conversion == .to_rational) {
                // An integer is itself over one, which is already in lowest terms.
                if (self.node(operand).value_type != .i64) return w.fail(self.node(operand).span, .type_mismatch);
                const one = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .integer = 1 } });
                return self.emit(.{ .span = span, .value_type = try self.rationalType(span), .kind = .{ .rational = .{ .op = .make, .lhs = operand, .rhs = one } } });
            }
            if (operator.selected != 1) {
                // The parenthesised `Floor` and `Ceil`: total, and only for a rational.
                if (!catalogue.isRational(self.node(operand).value_type, self.definitions())) return w.fail(self.node(operand).span, .type_mismatch);
                return self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .rational = .{ .op = if (conversion == .floor) .floor else .ceil, .lhs = operand, .rhs = operand } } });
            }
            if (self.node(operand).value_type != .float) return w.fail(self.node(operand).span, .type_mismatch);
            const low = try self.emit(.{ .span = span, .value_type = .float, .kind = .{ .floating = -types.integer_float_bound } });
            const high = try self.emit(.{ .span = span, .value_type = .float, .kind = .{ .floating = types.integer_float_bound } });
            const above = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .compare = .{ .op = .greater_equal, .lhs = operand, .rhs = low } } });
            const below = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .compare = .{ .op = .less, .lhs = operand, .rhs = high } } });
            const inside = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .logic_binary = .{ .op = .both, .lhs = above, .rhs = below } } });
            _ = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .demand = inside } });
            const mode: types.FloatRounding = switch (conversion) {
                .floor => .floor,
                .ceil => .ceil,
                .round => .round_even,
                .truncate => .truncate,
                .float, .string, .interpolation, .quotient, .modulo, .rational, .to_rational, .cast, .bit_and, .bit_or, .bit_xor, .bit_not, .units, .case_is, .case_as, .case_all, .case_some, .case_none, .case_value, .case_tuple, .final_super_class => unreachable,
            };
            return self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .float_to_int = .{ .mode = mode, .operand = operand } } });
        }

        /// `Quotient[A,B]`, `Mod[A,B]` and `Rational[A,B]` fail when `B` is zero, as `Require`
        /// fails, and then divide. The machines reject a zero divisor that arrives unguarded.
        fn emitDivision(self: *Self, conversion: Conversion, operator: Operator, arguments: []const u32) ParseError!u32 {
            const w = self.workspace;
            const span = operator.span;
            if (arguments.len != 2) return w.fail(span, .argument_count);
            for (arguments) |operand| if (self.node(operand).value_type != .i64) return w.fail(self.node(operand).span, .type_mismatch);
            const zero = try self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .integer = 0 } });
            const nonzero = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .compare = .{ .op = .unequal, .lhs = arguments[1], .rhs = zero } } });
            _ = try self.emit(.{ .span = span, .value_type = .logic, .kind = .{ .demand = nonzero } });
            if (conversion == .rational) return self.emit(.{ .span = span, .value_type = try self.rationalType(span), .kind = .{ .rational = .{ .op = .make, .lhs = arguments[0], .rhs = arguments[1] } } });
            return self.emit(.{ .span = span, .value_type = .i64, .kind = .{ .binary = .{ .op = if (conversion == .quotient) .quotient else .modulo, .lhs = arguments[0], .rhs = arguments[1] } } });
        }

        /// Whether `function`, named `ToString`, is one the language can call for interpolation
        /// (RFC-0053, B5): one value of a type with no text of its own, a string result, no failure.
        fn textFunction(self: *const Self, function: functions.Definition) bool {
            if (function.parameter_count != 1 or function.value_type != .string or function.decides or function.is_extension or function.is_method) return false;
            return !self.hasBuiltinText(function.parameters[0].value_type);
        }

        /// The types whose text the language gives (`i64`, `float`, `logic`, characters, strings
        /// and refinements, which print as their base): a program's `ToString` never replaces it.
        fn hasBuiltinText(self: *const Self, kind: types.Type) bool {
            return kind == .string or kind == .i64 or kind == .float or kind == .logic or kind.isCharacter() or catalogue.refinementOf(kind, self.definitions()) != null;
        }

        /// The definition of `ToString` for a value of type `kind` that the code being compiled
        /// reaches: the overloads of its own module or the modules around it, else those of the
        /// modules a `using` brings in, where exactly one module may have one for the type.
        fn chooseText(self: *Self, span: Span, kind: types.Type) ParseError!?u32 {
            const w = self.workspace;
            var at = w.currentScope();
            while (true) {
                if (w.plainFunctionIn("ToString", w.scopeOf(at))) |found| return if (self.visible(w.functions.definitions[found].name)) self.textFor(found, kind) else null;
                if (w.module_storage.nested_count == 0) break;
                at = w.outerScope(at) orelse break;
            }
            if (!bundled) return null;
            var picked: ?u32 = null;
            for (w.using_edges[0..w.using_count]) |edge| {
                if (!w.insideScope(w.currentScope(), edge.module)) continue;
                const first = w.plainFunctionIn("ToString", w.scopeOf(edge.target)) orelse continue;
                if (!w.functions.definitions[first].is_public) continue;
                const candidate = self.textFor(first, kind) orelse continue;
                if (picked != null and picked.? != candidate) return w.fail(span, .ambiguous_call);
                picked = candidate;
            }
            return picked;
        }

        /// The overload of the `ToString` that starts at `first` which takes a value of type `kind`.
        fn textFor(self: *const Self, first: u32, kind: types.Type) ?u32 {
            const w = self.workspace;
            if (w.functions.definitions[first].overloaded) return w.chooseOverload(first, &.{kind});
            const candidate = &w.functions.definitions[first];
            if (candidate.parameter_count != 1 or !catalogue.assignable(kind, candidate.parameters[0].value_type, self.definitions())) return null;
            return first;
        }

        /// Interpolation and `ToString(Value)` of a value that has no text of its own call the
        /// `ToString` the program declares for its type (the Book, 02:840), chosen as any
        /// overload is. Nothing else changes: a value with a text of its own keeps it, and
        /// a type with no `ToString` stays the type mismatch it was.
        fn emitUserText(self: *Self, operator: Operator, operand: u32) ParseError!?u32 {
            const w = self.workspace;
            const kind = self.node(operand).value_type;
            if (self.hasBuiltinText(kind)) return null;
            const chosen = (try self.chooseText(operator.span, kind)) orelse return null;
            const function = w.functions.definitions[chosen];
            // A call is public across modules, as any call is.
            if (!function.is_public and !w.reaches(function.name)) return w.fail(operator.span, .private_name);
            const named = operator.kind == .convert and operator.function == @backingInt(Conversion.string);
            if (named) w.noteName(operator.span, function.name.start, .global, qualify.none);
            try self.callEffect(operator.span, Effect.of(function).set());
            return try self.expandChosen(.{ .kind = .call, .span = operator.span, .function = chosen, .operand_base = operator.operand_base }, function, &.{operand});
        }

        fn expandCall(self: *Self, operator: Operator, arguments: []const u32) ParseError!u32 {
            const w = self.workspace;
            const storage = &w.functions;
            // RFC-0091: a call of a function declared further down names its header.
            if (operator.forward) return self.expandChosen(operator, self.callTarget(operator), arguments);
            std.debug.assert(operator.kind == .call and operator.function < storage.count);
            var function = storage.definitions[operator.function];
            if (function.overloaded) {
                // Several definitions share the name: the argument types choose one.
                if (operator.tail != no_member) return w.fail(operator.span, .named_argument_order);
                var types_of_arguments: [types.limits.parameters]types.Type = undefined;
                for (arguments, types_of_arguments[0..arguments.len]) |argument, *slot| slot.* = self.node(argument).value_type;
                const chosen = w.chooseOverload(operator.function, types_of_arguments[0..arguments.len]) orelse return w.fail(operator.span, if (w.hasArity(operator.function, arguments.len)) .type_mismatch else .argument_count);
                function = storage.definitions[chosen];
                // RFC-0085, I11: the call names the overload its arguments picked. The name
                // ends the call's span, after any module path.
                if (w.qualify) w.noteName(.{ .start = operator.span.end - (function.name.end - function.name.start), .end = operator.span.end }, function.name.start, .global, qualify.none);
                try self.callEffect(operator.span, Effect.of(function).set());
            }
            return self.expandChosen(operator, function, arguments);
        }

        /// The call of `function`, which the arguments (or the name) have chosen.
        fn expandChosen(self: *Self, operator: Operator, function: functions.Definition, arguments: []const u32) ParseError!u32 {
            const w = self.workspace;
            // An extension method found through `using` belongs to another module: only its public definitions are callable.
            if (operator.receiver and !function.is_public and !w.reaches(function.name)) return w.fail(operator.span, .private_name);
            if (arguments.len > function.parameter_count) return w.fail(operator.span, .argument_count);
            // Arguments by position, then by name; parameters left out take their defaults.
            var ordered: [types.limits.parameters]u32 = @splat(no_member);
            const positional: usize = if (operator.tail == no_member) arguments.len else operator.tail;
            for (arguments, 0..) |argument, ordinal| {
                const target: usize = if (ordinal < positional) ordinal else @intCast(operator.names >> @intCast(4 * (ordinal - positional)) & 0xf);
                std.debug.assert(ordered[target] == no_member);
                ordered[target] = argument;
            }
            // In parameter order, so that a default reads the arguments before it as the
            // function will receive them: each is evaluated once, by the caller.
            const complete = ordered[0..function.parameter_count];
            for (complete, function.defaults[0..function.parameter_count], function.parameters[0..function.parameter_count], 0..) |*slot, default, entry, position| {
                if (slot.* == no_member) {
                    if (operator.forward and w.runtime_functions.forward[operator.function].has_default[position]) return w.fail(operator.span, .forward_arguments);
                    if (default.start == default.end) return w.fail(operator.span, .argument_count);
                    slot.* = try self.expandBody(default, complete[0..position], operator.span);
                }
                slot.* = try self.coerce(slot.*, entry.value_type);
            }
            if (operator.delegation) return self.delegate(operator, function, complete);
            // Only an archetype that delegates uses the constructor function of an abstract class.
            if (function.is_constructor and self.abstractClass(function.value_type)) return w.fail(operator.span, .abstract_instance);
            if (operator.forward) {
                const range = try self.reserveArguments(complete, operator.span);
                return self.checked(try self.emit(.{ .span = operator.span, .value_type = function.value_type, .kind = .{ .call = .{ .function = runtime_functions.forward_base + operator.function, .arguments = range } } }));
            }
            if (function.runtime) |target| {
                const range = try self.reserveArguments(complete, operator.span);
                return self.checked(try self.emit(.{ .span = operator.span, .value_type = function.value_type, .kind = .{ .call = .{ .function = target, .arguments = range } } }));
            }
            return self.expandBody(.{ .start = @intCast(function.start), .end = @intCast(function.end), .root = @intCast(function.root), .work = @intCast(function.work) }, complete, operator.span);
        }

        /// Whether `Name<constructor>` or `Module.Name<constructor>` starts here.
        fn delegationAhead(self: *const Self) bool {
            const tokens = &self.workspace.tokens;
            var at = self.cursor;
            if (tokens[at].kind != .identifier) return false;
            // A path through modules declared in files (RFC-0074) has a dot for each of them.
            while (tokens[at + 1].kind == .dot and tokens[at + 2].kind == .identifier) {
                at += 2;
                if (self.workspace.module_storage.nested_count == 0) break;
            }
            return tokens[at + 1].kind == .less and tokens[at + 2].kind == .identifier and tokens[at + 3].kind == .greater and std.mem.eql(u8, tokens[at + 2].span.text(self.workspace.source), "constructor");
        }

        /// `Name<constructor>(arguments)` as an entry of a class archetype: a call of the
        /// constructor function `Name` that is finished by `delegate` instead of yielding an
        /// instance. Overloads, named arguments and defaults are those of any call.
        fn startDelegation(self: *Self, token: Token) ParseError!void {
            const w = self.workspace;
            const resolved = try self.resolveName(token);
            _ = try self.take(.less, .unsupported_specifier);
            _ = try self.take(.identifier, .unsupported_specifier);
            _ = try self.take(.greater, .unsupported_specifier);
            const found = w.plainFunctionIn(resolved.token.span.text(w.source), resolved.scope) orelse return w.fail(resolved.span, .unknown_name);
            const function = w.functions.definitions[found];
            if (!self.visible(function.name)) return w.fail(resolved.span, .unknown_name);
            if (resolved.sealed() and !function.is_public) return w.fail(resolved.span, .private_name);
            if (!function.is_constructor and !function.overloaded) return w.fail(resolved.span, .invalid_delegation);
            // RFC-0085, I11: the constructor function a delegation names.
            if (!function.overloaded) w.noteName(resolved.token.span, function.name.start, .global, qualify.none);
            if (!function.overloaded) try self.callEffect(resolved.span, Effect.of(function).set());
            if (function.decides and !self.failureContext()) return w.fail(resolved.span, .failure_context_required);
            _ = try self.take(if (function.decides) .left_bracket else .left_paren, .expected_call);
            try self.pushOperator(.{ .kind = .call, .span = resolved.span, .function = found, .operand_base = self.operand_count, .selected = if (function.decides) 1 else no_member, .delegation = true });
        }

        /// Finishes `Name<constructor>(arguments)` inside an archetype of class `D`. The constructor
        /// function builds class `C`, which is `D` or one of its superclasses, so `C`'s fields are the
        /// first cells of `D`. The part of its template that computes the values its own archetype
        /// was given is expanded here, and those values are staged as entries of this archetype.
        /// Neither its defaults nor its `object_new` nor the calls of `C`'s block clauses are taken:
        /// a field nobody gave gets the default `D` has for it, the instance is built by this
        /// archetype's single `object_new`, and the block clauses run once, for `D`.
        fn delegate(self: *Self, operator: Operator, function: functions.Definition, arguments: []const u32) ParseError!u32 {
            const w = self.workspace;
            const storage = &w.functions;
            if (!function.is_constructor) return w.fail(operator.span, .invalid_delegation);
            std.debug.assert(self.operator_count >= self.operator_base + 2);
            const record = &w.operators[self.operator_count - 2];
            std.debug.assert(record.kind == .record and record.delegation and record.selected == no_member);
            const built = record.value_type.?;
            const base = function.value_type;
            if (built != base and !catalogue.subtype(built, base, self.definitions())) return w.fail(operator.span, .invalid_delegation);
            // One constructor decides the superclass part.
            if (record.method != no_member) return w.fail(operator.span, .invalid_delegation);
            record.method = 0;
            const new = storage.nodes[function.root].node.kind.object_new.arguments;
            const count = new.end - new.start;
            const built_fields = catalogue.definition(built, self.definitions()).?.class.fields;
            for (storage.arguments[new.start..new.end], 0..) |operand, field| {
                if (operand >= function.given) continue;
                // No archetype of `D` gives a field `D` holds final, a constructor's included.
                if (w.field_live[built_fields.start + field]) return w.fail(operator.span, .live_assigned);
                if (w.field_final[built_fields.start + field]) return w.fail(operator.span, .final_field);
                // Given both by name and by the constructor: one of them would be dropped.
                var member = record.head;
                while (member != no_member) : (member = w.staging[member].next) {
                    if (w.staging[member].field == field) return w.fail(operator.span, .duplicate_field);
                }
            }
            const work = function.work;
            if (work > types.limits.compiler_work - w.expansion_work) return w.fail(operator.span, .compiler_work_limit);
            w.expansion_work += work;
            // Both machines admit a local assignment and a read or write of a module variable
            // only inside the module of the function that holds it, so a constructor function
            // that has them cannot lend its body to another module. The module they mean is the
            // file: the modules declared in one file lend to each other (RFC-0074).
            const foreign = bundled and !modules.contains(w.scopeOf(w.current_module), function.name);
            for (function.start..function.given) |index| {
                const template = storage.nodes[index];
                storage.mapping[index] = switch (template.input) {
                    .parameter => |parameter_index| arguments[parameter_index],
                    .global => |global| if (self.function == null) w.bindings[global].node else try self.emitTemplate(template),
                    .operation => switch (template.node.kind) {
                        .local_set, .cell_read, .cell_write, .weak_get, .weak_set => if (foreign) return w.fail(operator.span, .invalid_delegation) else try self.emit(try self.remapNode(template.node, function.start, @intCast(index))),
                        // The constructor naming or calling itself means that function, not this one.
                        .self_value => try self.emit(.{ .span = template.node.span, .value_type = template.node.value_type, .kind = .{ .function_value = function.runtime.? } }),
                        .recur => |range| again: {
                            var operands: [types.limits.parameters]u32 = undefined;
                            const operand_count = range.end - range.start;
                            for (storage.arguments[range.start..range.end], operands[0..operand_count]) |operand, *destination| destination.* = storage.mapping[operand];
                            const target = try self.reserveArguments(operands[0..operand_count], template.node.span);
                            break :again try self.checked(try self.emit(.{ .span = template.node.span, .value_type = template.node.value_type, .kind = .{ .call = .{ .function = function.runtime.?, .arguments = target } } }));
                        },
                        else => try self.emit(try self.remapNode(template.node, function.start, @intCast(index))),
                    },
                };
            }
            if (count > w.staging.len - w.staging_count) return w.fail(operator.span, .aggregate_limit);
            for (storage.arguments[new.start..new.end], 0..) |operand, field| {
                std.debug.assert(operand >= function.start and operand < function.root);
                if (operand >= function.given) continue;
                const value = storage.mapping[operand];
                std.debug.assert(self.node(value).value_type == catalogue.classFieldAt(built, @intCast(field), self.definitions(), self.fields()).?.value_type);
                const index = w.staging_count;
                w.staging[index] = .{ .node = value, .field = @intCast(field) };
                if (record.tail != no_member) w.staging[record.tail].next = @intCast(index) else record.head = index;
                record.tail = index;
                record.arguments += 1;
                w.staging_count += 1;
            }
            if (w.accessor_required != 0) try self.delegateAccessors(record, function, operator.span);
            return no_member;
        }

        /// RFC-0085, I9: the values the archetype of the constructor function `function` gave
        /// the fields with accessors and no default of its class, given to the
        /// archetype `record` that delegates, as the values of its cells are. That archetype
        /// ends, after its `object_new` and the calls of its block clauses, with one setter
        /// call for each such field in declaration order (`initialiseAccessors`), whose third
        /// argument is the value, computed before the `object_new` and expanded by `delegate`.
        fn delegateAccessors(self: *Self, record: *Operator, function: functions.Definition, span: Span) ParseError!void {
            const w = self.workspace;
            const storage = &w.functions;
            var at: usize = function.root + 1;
            const count = self.requiredAccessors(function.value_type);
            for (w.accessor_order[0..count]) |index| {
                const call = while (at < function.end) : (at += 1) {
                    const template = storage.nodes[at];
                    if (template.input == .operation and template.node.kind == .invoke) break template.node.kind.invoke;
                } else unreachable;
                at += 1;
                std.debug.assert(call.arguments.end - call.arguments.start == 3);
                const operand = storage.arguments[call.arguments.start + 2];
                std.debug.assert(operand >= function.start and operand < function.given);
                // Given both by name and by the constructor: one of them would be dropped.
                numberArchetype(w, record);
                if (w.accessor_given[index].archetype == record.accessors) return w.fail(span, .duplicate_field);
                try stageAccessor(w, record, index, storage.mapping[operand], span);
            }
        }

        fn expandBody(self: *Self, template_body: functions.Body, arguments: []const u32, span: Span) ParseError!u32 {
            const w = self.workspace;
            const storage = &w.functions;
            std.debug.assert(template_body.start <= template_body.root and template_body.root < template_body.end);
            std.debug.assert(template_body.end <= storage.node_count or template_body.start >= storage.node_top);
            const work = template_body.work;
            std.debug.assert(work >= template_body.end - template_body.start);
            std.debug.assert(w.expansion_work <= types.limits.compiler_work);
            if (work > types.limits.compiler_work - w.expansion_work) return w.fail(span, .compiler_work_limit);
            // RFC-0085, I12: what a template runs, it runs in the code it is expanded into.
            if (self.predicting() and self.dictatingTemplate(template_body.start, template_body.end)) return w.fail(span, .call_requires_dictates);
            w.expansion_work += work;
            for (template_body.start..template_body.end) |index| {
                const template = storage.nodes[index];
                storage.mapping[index] = switch (template.input) {
                    .parameter => |parameter_index| argument: {
                        std.debug.assert(parameter_index < arguments.len);
                        break :argument arguments[parameter_index];
                    },
                    .global => |global| if (self.function == null) w.bindings[global].node else try self.emitTemplate(template),
                    .operation => try self.emit(try self.remapNode(template.node, template_body.start, @intCast(index))),
                };
                std.debug.assert(self.node(storage.mapping[index]).value_type == template.node.value_type);
            }
            return storage.mapping[template_body.root];
        }

        fn pushOperator(self: *Self, operator: Operator) ParseError!void {
            std.debug.assert(self.operator_count <= self.workspace.operators.len);
            if (self.operator_count == self.workspace.operators.len) return self.workspace.fail(operator.span, .expression_limit);
            self.workspace.operators[self.operator_count] = operator;
            self.operator_count += 1;
            std.debug.assert(self.operator_count <= self.workspace.operators.len);
        }
        fn pushOperand(self: *Self, index: u32) ParseError!void {
            std.debug.assert(index < if (self.function != null) self.workspace.functions.node_count else self.workspace.node_count);
            if (self.operand_count == self.workspace.operands.len) return self.workspace.fail(self.node(index).span, .expression_limit);
            self.workspace.operands[self.operand_count] = index;
            self.operand_count += 1;
            self.operand_pushes += 1;
            std.debug.assert(self.operand_count <= self.workspace.operands.len);
        }
        fn applyOperator(self: *Self) ParseError!void {
            std.debug.assert(self.operator_count > self.operator_base);
            std.debug.assert(self.operand_count > 0);
            self.operator_count -= 1;
            const operator = self.workspace.operators[self.operator_count];
            const rhs = self.workspace.operands[self.operand_count - 1];
            const value_type = self.node(rhs).value_type;
            if (operator.kind == .logical_not) {
                if (value_type != .logic) return self.workspace.fail(operator.span, .type_mismatch);
                self.workspace.operands[self.operand_count - 1] = try self.emit(.{ .span = operator.span, .value_type = .logic, .kind = .{ .logic_not = rhs } });
                self.predicate = .{ .node = self.workspace.operands[self.operand_count - 1], .span = operator.span, .depth = self.operator_count, .pushes = self.operand_pushes };
                return;
            }
            if (operator.kind == .logical_and or operator.kind == .logical_or or comparisonOperator(operator.kind) != null) return self.applyPredicate(operator, rhs);
            return switch (value_type) {
                .i64 => self.applyNumericOperator(.i64, operator, rhs),
                .float => self.applyNumericOperator(.float, operator, rhs),
                .string => self.applyStringOperator(operator, rhs),
                else => if (catalogue.definition(value_type, self.definitions())) |shape| (if (shape == .array) self.applyArrayOperator(operator, rhs) else if (shape == .rational) self.applyRationalOperator(operator, rhs) else self.workspace.fail(operator.span, .type_mismatch)) else self.workspace.fail(operator.span, .type_mismatch),
            };
        }

        /// Exact `+`, `-`, `*` and unary minus on rationals. `/` is not offered: it would have
        /// to fail on a zero divisor, which an operator cannot do here.
        fn applyRationalOperator(self: *Self, operator: Operator, rhs: u32) ParseError!void {
            const w = self.workspace;
            const value_type = self.node(rhs).value_type;
            if (operator.kind == .positive) return;
            if (operator.kind == .negative) {
                w.operands[self.operand_count - 1] = try self.emit(.{ .span = operator.span, .value_type = value_type, .kind = .{ .rational = .{ .op = .negate, .lhs = rhs, .rhs = rhs } } });
                return;
            }
            const op: types.RationalOp = switch (operator.kind) {
                .add => .add,
                .subtract => .subtract,
                .multiply => .multiply,
                else => return w.fail(operator.span, .type_mismatch),
            };
            std.debug.assert(self.operand_count >= 2);
            self.operand_count -= 1;
            const lhs = w.operands[self.operand_count - 1];
            if (self.node(lhs).value_type != value_type) return w.fail(operator.span, .type_mismatch);
            w.operands[self.operand_count - 1] = try self.emit(.{ .span = operator.span, .value_type = value_type, .kind = .{ .rational = .{ .op = op, .lhs = lhs, .rhs = rhs } } });
        }

        /// `+` concatenates two arrays of the same type into a fresh run-owned array.
        fn applyArrayOperator(self: *Self, operator: Operator, rhs: u32) ParseError!void {
            if (operator.kind != .add) return self.workspace.fail(operator.span, .type_mismatch);
            std.debug.assert(self.operand_count >= 2);
            self.operand_count -= 1;
            const lhs = self.workspace.operands[self.operand_count - 1];
            if (self.node(lhs).value_type != self.node(rhs).value_type) return self.workspace.fail(operator.span, .type_mismatch);
            self.workspace.operands[self.operand_count - 1] = try self.emit(.{ .span = operator.span, .value_type = self.node(rhs).value_type, .kind = .{ .array_concat = .{ .lhs = lhs, .rhs = rhs } } });
        }

        /// `+` concatenates strings into the run-owned pool; every other operator is a type error.
        fn applyStringOperator(self: *Self, operator: Operator, rhs: u32) ParseError!void {
            if (operator.kind != .add) return self.workspace.fail(operator.span, .type_mismatch);
            std.debug.assert(self.operand_count >= 2);
            self.operand_count -= 1;
            const lhs = self.workspace.operands[self.operand_count - 1];
            if (self.node(lhs).value_type != .string) return self.workspace.fail(operator.span, .type_mismatch);
            self.workspace.operands[self.operand_count - 1] = try self.emit(.{ .span = operator.span, .value_type = .string, .kind = .{ .string_concat = .{ .lhs = lhs, .rhs = rhs } } });
        }

        /// Whether the right operand of the `and` or `or` whose word was just consumed is
        /// plain (RFC-0076): built only from numeric literals, `true`, `false`, `not`,
        /// comparisons, parentheses, further `and`/`or`, and names of locals, parameters and
        /// constants of this scope whose type is `logic`, `i64` or `float`. Such an operand
        /// cannot trap, fail, write or cost more than its fixed size, so evaluating it cannot
        /// be told from skipping it, and the strict node is kept for it.
        /// `line_ends` says whether a line break ends the expression here: inside parentheses
        /// that are not a block's it is only space, and the operand goes on after it.
        fn plainOperand(self: *const Self, kind: @FieldType(Operator, "kind"), line_ends: bool) bool {
            const w = self.workspace;
            var at = self.cursor;
            var depth: u32 = 0;
            while (at < w.token_count) : (at += 1) {
                const token = w.tokens[at];
                switch (token.kind) {
                    .integer, .floating, .equal_equal, .not_equal, .less, .less_equal, .greater, .greater_equal => {},
                    .plus, .minus => {
                        // Only the sign of a literal: arithmetic can overflow.
                        const before = w.tokens[at - 1].kind;
                        const after = w.tokens[at + 1].kind;
                        if (before == .integer or before == .floating or before == .right_paren or (before == .identifier and !logicWord(w.tokens[at - 1].span.text(w.source)))) return false;
                        if (after != .integer and after != .floating) return false;
                    },
                    .left_paren => depth += 1,
                    .right_paren => {
                        if (depth == 0) return true;
                        depth -= 1;
                    },
                    .newline => if (depth == 0 and line_ends) return true,
                    .comma, .right_bracket, .right_brace, .separator, .eof, .arrow => return depth == 0,
                    .identifier => {
                        const text = token.span.text(w.source);
                        if (std.mem.eql(u8, text, "and") or std.mem.eql(u8, text, "or")) {
                            // The operand of an `and` ends at the next `and` or `or`; that of an `or` at the next `or`.
                            if (depth == 0 and (kind == .logical_and or text.len == 2)) return true;
                            continue;
                        }
                        if (std.mem.eql(u8, text, "not") or std.mem.eql(u8, text, "true") or std.mem.eql(u8, text, "false")) continue;
                        const next = w.tokens[at + 1].kind;
                        if (next == .left_paren or next == .left_bracket or next == .left_brace or next == .dot or next == .question or next == .colon) return false;
                        const value_type: types.Type = if (self.findLocal(text)) |local| self.localType(local) else if (self.parameter(text)) |index| self.parameterType(index) else if (w.findSymbol(text)) |binding| constant: {
                            if (w.binding_cells[binding] != std.math.maxInt(u16)) return false;
                            break :constant w.bindings[binding].value_type;
                        } else return false;
                        if (value_type != .logic and value_type != .i64 and value_type != .float) return false;
                    },
                    else => return false,
                }
            }
            return false;
        }
        fn logicWord(text: []const u8) bool {
            return std.mem.eql(u8, text, "and") or std.mem.eql(u8, text, "or") or std.mem.eql(u8, text, "not");
        }

        /// `P and Q` and `P or Q` evaluate `Q` only when `P` does not decide the result
        /// (RFC-0076, RFC-0067 D2). They are the conditionals `If(P, Q, false)` and
        /// `If(P, true, Q)`, opened here, once `P` is complete and before `Q` is read, and
        /// closed by `applyPredicate`. An operator whose right operand is plain keeps the strict
        /// node. `selected` marks the lazy form; `function` is its `if_begin`, `head` the saved
        /// versions of the locals, and for `or` `tail` is the first arm.
        fn startShortCircuit(self: *Self, operator: *Operator, line_ends: bool) ParseError!void {
            const w = self.workspace;
            // A link of a comparison chain is the `and` of what came before and its comparison.
            const link = operator.method != no_member;
            std.debug.assert(operator.kind == .logical_and or operator.kind == .logical_or or (link and comparisonOperator(operator.kind) != null));
            std.debug.assert(self.operand_count > self.operand_base);
            const lhs = w.operands[self.operand_count - 1];
            if (self.node(lhs).value_type != .logic) return w.fail(operator.span, .type_mismatch);
            // `A == B == C` meant `(A == B) == C` before chains, for `logic` operands; as a
            // chain it would mean something else, so it has to be written with parentheses.
            if (link and self.node(operator.method).value_type == .logic) return w.fail(operator.span, .type_mismatch);
            if (self.plainOperand(if (link) .logical_and else operator.kind, line_ends)) return;
            operator.selected = short_circuit;
            operator.head = try self.saveLocalVersions(operator.span);
            operator.function = try self.emit(.{ .span = operator.span, .value_type = .logic, .kind = .{ .if_begin = .{ .condition = lhs, .alternative = no_member, .end = no_member } } });
            if (operator.kind != .logical_or) return;
            var decided = try self.emit(.{ .span = operator.span, .value_type = .logic, .kind = .{ .boolean = true } });
            if (operator.head != no_member) {
                decided = try self.packLocalVersions(operator.head, decided, operator.span);
                self.restoreLocalVersions(operator.head);
            }
            operator.tail = decided;
            _ = try self.emit(.{ .span = operator.span, .value_type = .logic, .kind = .{ .otherwise = operator.function } });
        }
        const short_circuit: u32 = 1;

        /// Closes the conditional `startShortCircuit` opened, with `rhs` as the operand that was
        /// evaluated only when needed.
        fn finishShortCircuit(self: *Self, operator: Operator, rhs: u32) ParseError!void {
            const w = self.workspace;
            std.debug.assert(operator.selected == short_circuit and self.operand_count >= 2);
            self.operand_count -= 1;
            if (self.node(rhs).value_type != .logic) return w.fail(operator.span, .type_mismatch);
            var left = rhs;
            var right = rhs;
            if (operator.kind != .logical_or) {
                if (operator.head != no_member) {
                    left = try self.packLocalVersions(operator.head, rhs, operator.span);
                    self.restoreLocalVersions(operator.head);
                }
                _ = try self.emit(.{ .span = operator.span, .value_type = .logic, .kind = .{ .otherwise = operator.function } });
                right = try self.emit(.{ .span = operator.span, .value_type = .logic, .kind = .{ .boolean = false } });
            } else left = operator.tail;
            if (operator.head != no_member) right = try self.packLocalVersions(operator.head, right, operator.span);
            const merged = try self.emit(.{ .span = operator.span, .value_type = self.node(left).value_type, .kind = .{ .merge = .{ .begin = operator.function, .left = left, .right = right } } });
            w.operands[self.operand_count - 1] = if (operator.head == no_member) merged else try self.selectLocalVersions(operator.head, merged, operator.span);
            self.predicate = .{ .node = w.operands[self.operand_count - 1], .span = operator.span, .depth = self.operator_count, .pushes = self.operand_pushes };
        }

        /// RFC-0090: the Book's `case` compares a value of `int`, `logic`, `char`, `string`, an
        /// enum or a refinement type with constants, and not a float, an object or a tuple
        /// (07:389). `scrutinee` is the left operand of the `==` of a constant arm, at `span`.
        /// Forbic's `rational` and its other aggregates are refused with the float; an option,
        /// a tuple or an object is matched by the patterns of RFC-0066, which do not come here.
        fn checkCaseScrutinee(self: *Self, scrutinee: u32, span: Span) ParseError!void {
            var value_type = self.node(scrutinee).value_type;
            if (catalogue.refinementOf(value_type, self.definitions())) |refinement| value_type = refinement.base;
            if (value_type == .i64 or value_type == .logic or value_type == .string or value_type.isCharacter()) return;
            if (catalogue.definition(value_type, self.definitions())) |shape| if (shape == .enumeration) return;
            return self.workspace.fail(span, .case_scrutinee_type);
        }

        /// RFC-0076 (D1): a statement whose value is dropped may not be a comparison, a chain,
        /// or a `not`, `and` or `or`: nothing but the value comes of those, so the author meant
        /// a check, which is `Require[...]`. `value` is what the statement left.
        fn checkDiscarded(self: *Self, value: u32) ParseError!void {
            const w = self.workspace;
            if (self.predicate.node != value or self.predicate.depth != self.operator_count or self.predicate.pushes != self.operand_pushes) return;
            // Library text drops what it means to drop.
            if (w.libraryModule(self.predicate.span) != null) return;
            return w.fail(self.predicate.span, .discarded_comparison);
        }

        /// Replaces the operand `rhs` on top of the stack by the comparison of a chain link:
        /// the operand the link shares with the one before it, against `rhs`.
        fn compareLink(self: *Self, operator: Operator, rhs: u32) ParseError!void {
            const w = self.workspace;
            std.debug.assert(operator.method != no_member and w.operands[self.operand_count - 1] == rhs);
            var single = operator;
            single.method = no_member;
            single.selected = no_member;
            single.receiver = false;
            w.operands[self.operand_count - 1] = operator.method;
            try self.pushOperand(rhs);
            try self.applyPredicate(single, rhs);
        }

        fn applyPredicate(self: *Self, operator: Operator, rhs: u32) ParseError!void {
            const w = self.workspace;
            std.debug.assert(self.operand_count >= 2);
            if ((operator.kind == .logical_and or operator.kind == .logical_or) and operator.selected == short_circuit) return self.finishShortCircuit(operator, rhs);
            if (operator.method != no_member) {
                // A chain link: compare the operand it shares with the link before it, then
                // join the two with `and`, strictly or as the conditional that was opened.
                std.debug.assert(comparisonOperator(operator.kind) != null);
                // One whose comparison was made when the next link arrived takes the rest of
                // the chain as its right operand.
                if (operator.receiver) return self.finishShortCircuit(operator, rhs);
                try self.compareLink(operator, rhs);
                const compared = w.operands[self.operand_count - 1];
                if (operator.selected == short_circuit) return self.finishShortCircuit(operator, compared);
                self.operand_count -= 1;
                const before = w.operands[self.operand_count - 1];
                w.operands[self.operand_count - 1] = try self.emit(.{ .span = operator.span, .value_type = .logic, .kind = .{ .logic_binary = .{ .lhs = before, .rhs = compared, .op = .both } } });
                self.predicate = .{ .node = w.operands[self.operand_count - 1], .span = operator.span, .depth = self.operator_count, .pushes = self.operand_pushes };
                return;
            }
            self.operand_count -= 1;
            var lhs = w.operands[self.operand_count - 1];
            var value_type = self.node(lhs).value_type;
            var right = rhs;
            const right_type = self.node(rhs).value_type;
            if (value_type != right_type) {
                // The narrower class is compared as the wider one.
                if (catalogue.subtype(value_type, right_type, self.definitions())) {
                    lhs = try self.coerce(lhs, right_type);
                    value_type = right_type;
                } else if (catalogue.refinementOf(right_type, self.definitions()) != null and self.constantValue(lhs) != null) {
                    // `25 == Age`: the literal is the refinement's, as on the right (RFC-0083).
                    lhs = try self.coerce(lhs, right_type);
                    value_type = right_type;
                } else right = try self.coerce(rhs, value_type);
            }
            const kind: @FieldType(types.Node, "kind") = if (comparisonOperator(operator.kind)) |op| compare: {
                const equality = op == .equal or op == .unequal;
                if (equality and !self.comparable(value_type)) return w.fail(operator.span, w.equalityCode(value_type, .not_comparable));
                if (!equality and value_type != .i64 and value_type != .float and !catalogue.isRational(value_type, self.definitions())) return w.fail(operator.span, .type_mismatch);
                break :compare .{ .compare = .{ .lhs = lhs, .rhs = right, .op = op } };
            } else logical: {
                if (value_type != .logic) return w.fail(operator.span, .type_mismatch);
                break :logical .{ .logic_binary = .{ .lhs = lhs, .rhs = right, .op = if (operator.kind == .logical_and) .both else .either } };
            };
            w.operands[self.operand_count - 1] = try self.emit(.{ .span = operator.span, .value_type = .logic, .kind = kind });
            self.predicate = .{ .node = w.operands[self.operand_count - 1], .span = operator.span, .depth = self.operator_count, .pushes = self.operand_pushes };
        }

        // Specialize node construction so integer operations retain constant result
        // tags/types and their original assertion path instead of merging two unions.
        fn applyNumericOperator(self: *Self, comptime value_type: types.Type, operator: Operator, rhs: u32) ParseError!void {
            std.debug.assert(self.operand_count > 0 and self.node(rhs).value_type == value_type);
            std.debug.assert(self.workspace.operands[self.operand_count - 1] == rhs);
            if (operator.kind == .positive) return;
            if (operator.kind == .negative) {
                const negated = try self.emit(.{ .span = operator.span, .value_type = value_type, .kind = if (value_type == .float) .{ .float_negate = rhs } else .{ .negate = rhs } });
                // `-5` and `-Inf` are literals too (RFC-0083).
                self.workspace.operands[self.operand_count - 1] = if (self.isLiteral(rhs)) self.markLiteral(negated) else negated;
                return;
            }
            std.debug.assert(operator.kind != .open and operator.kind != .call);
            std.debug.assert(self.operand_count >= 2);
            self.operand_count -= 1;
            const lhs = self.workspace.operands[self.operand_count - 1];
            if (self.node(lhs).value_type != value_type) return self.workspace.fail(operator.span, .type_mismatch);
            const op: types.BinaryOp = switch (operator.kind) {
                .add => .add,
                .subtract => .subtract,
                .multiply => .multiply,
                .divide => .divide,
                else => unreachable,
            };
            self.workspace.operands[self.operand_count - 1] = try self.emit(.{
                .span = operator.span,
                .value_type = value_type,
                .kind = if (value_type == .float) .{ .float_binary = .{ .lhs = lhs, .rhs = rhs, .op = op } } else .{ .binary = .{ .lhs = lhs, .rhs = rhs, .op = op } },
            });
        }

        fn literal(self: *Self, token: Token) ParseError!u32 {
            const w = self.workspace;
            const text = token.span.text(w.source);
            switch (token.kind) {
                .floating => return self.floatLiteral(token),
                .integer => {
                    const magnitude = lexer.integerMagnitude(text) orelse return w.fail(token.span, .integer_range);
                    var value: i64 = undefined;
                    if (magnitude <= std.math.maxInt(i64)) {
                        value = @intCast(magnitude);
                    } else if (magnitude == @as(u64, std.math.maxInt(i64)) + 1 and self.operator_count > self.operator_base and w.operators[self.operator_count - 1].kind == .negative) {
                        self.operator_count -= 1;
                        value = std.math.minInt(i64);
                    } else return w.fail(token.span, .integer_range);
                    return self.markLiteral(try self.emit(.{ .span = token.span, .value_type = .i64, .kind = .{ .integer = value } }));
                },
                .string, .escaped_string => return self.emit(.{ .span = token.span, .value_type = .string, .kind = .{ .string = try self.decodeString(token) } }),
                .character => {
                    // An ASCII character in quotes and `0oXX` are `char`; any other character in
                    // quotes and `0uXXXXXX` are `char32`. Neither converts to the other.
                    const character = lexer.characterLiteral(text) orelse return w.fail(token.span, .invalid_char_literal);
                    return self.emit(.{ .span = token.span, .value_type = if (character.wide) types.Type.char32 else types.Type.char, .kind = .{ .character = character.code } });
                },
                .identifier => return self.literalName(.{ .token = token, .span = token.span, .scope = w.scope() }),
                else => unreachable,
            }
        }
        /// RFC-0085, I11: notes the identifier at `at` as naming the declared type `value_type`.
        fn noteType(self: *Self, at: Span, value_type: types.Type) void {
            if (!self.workspace.qualify) return;
            const item = catalogue.definition(value_type, self.definitions()) orelse return;
            const declared = catalogue.declaredName(item) orelse return;
            self.workspace.noteName(at, declared.start, .global, qualify.none);
        }
        /// Where the name of the type that declares a member of `class` is written.
        fn ownerOf(self: *const Self, class: types.Type) u32 {
            if (!self.workspace.qualify) return qualify.none;
            const item = catalogue.definition(class, self.definitions()) orelse return qualify.none;
            const declared = catalogue.declaredName(item) orelse return qualify.none;
            return declared.start;
        }
        /// RFC-0085, I11: notes the identifier at `at` as naming field `index` of `value_type`.
        fn noteField(self: *Self, at: Span, value_type: types.Type, index: u32) void {
            if (!self.workspace.qualify) return;
            const item = catalogue.definition(value_type, self.definitions()) orelse return;
            const field = (if (item == .class) catalogue.classFieldAt(value_type, index, self.definitions(), self.fields()) else catalogue.fieldAt(value_type, index, self.definitions(), self.fields())) orelse return;
            self.workspace.noteName(at, field.name.start, .member, qualify.none);
        }
        fn literalName(self: *Self, name: Name) ParseError!u32 {
            const w = self.workspace;
            const text = name.token.span.text(w.source);
            if (!name.qualified) {
                if (std.mem.eql(u8, text, "NaN") or std.mem.eql(u8, text, "Inf")) return self.markLiteral(try self.emit(.{ .span = name.span, .value_type = .float, .kind = .{ .floating = if (std.mem.eql(u8, text, "Inf")) std.math.inf(f64) else types.canonicalFloat(std.math.nan(f64)) } }));
                if (std.mem.eql(u8, text, "true") or std.mem.eql(u8, text, "false")) return self.emit(.{ .span = name.span, .value_type = .logic, .kind = .{ .boolean = std.mem.eql(u8, text, "true") } });
                if (reserved(text)) return w.fail(name.span, .expected_expression);
                if (self.findLocal(text)) |index| {
                    w.noteName(name.token.span, w.locals[index].name.start, .local, qualify.none);
                    // RFC-0085, S2: the name of a shared local reads its cell.
                    if (w.locals[index].shared) return self.readCell(w.locals[index].node, name.span);
                    return self.namedNode(w.locals[index].node);
                }
                if (self.parameter(text)) |index| {
                    if (index == 0 and self.function.?.is_method) return self.selfValue(name.span);
                    // `Self` is the receiver wherever a macro's function carries it.
                    if (!std.mem.eql(u8, text, "Self")) w.noteName(name.token.span, self.function.?.parameters[index].name.start, .local, qualify.none);
                    const read = try self.emitTemplate(.{ .node = .{ .span = name.span, .value_type = self.function.?.parameters[index].value_type, .kind = .{ .integer = 0 } }, .input = .{ .parameter = index } });
                    // So does the cell a closure captured for it.
                    if (catalogue.isRef(self.function.?.parameters[index].value_type, self.definitions())) return self.readCell(read, name.span);
                    return read;
                }
                if (std.mem.eql(u8, text, "Super")) if (self.function) |f| if (f.is_method) {
                    // The receiver seen as its superclass, for a call that skips the overrides.
                    const parent = catalogue.definition(self.method_class.?, self.definitions()).?.class.parent orelse return w.fail(name.span, .invalid_parent);
                    if (self.peek().kind != .dot) return w.fail(name.span, .expected_field);
                    self.super_value = try self.coerce(try self.selfValue(name.span), parent);
                    return self.super_value;
                };
            }
            if (!name.qualified and !self.default_expression) if (self.function) |f| {
                if (!f.is_extension and std.mem.eql(u8, text, f.name.text(w.source))) {
                    if (f.is_constructor and self.abstractClass(f.value_type)) return w.fail(name.span, .abstract_instance);
                    if (f.is_transparent) return w.fail(name.span, .transparent_recursion);
                    w.noteName(name.token.span, f.name.start, if (self.ownNested() != no_member) .local else if (f.is_method) .member else .global, qualify.none);
                    // RFC-0085, I3: a nested function's own value is bound to its captures.
                    if (self.ownNested() != no_member) return self.nestedSelf(f, name.span);
                    return self.emit(.{ .span = name.span, .value_type = try self.functionType(f, name.span), .kind = .self_value });
                }
            };
            if (w.functions.findIn(text, w.source, name.scope)) |found| {
                // An extension method must be called on a receiver; it is not a value.
                if (w.functions.definitions[found].is_extension) return w.fail(name.span, .unknown_name);
                var index = found;
                if (w.functions.definitions[found].overloaded) {
                    // The expected function type picks the definition; nothing else can.
                    const expected = self.expectedContext() orelse return w.fail(name.span, .ambiguous_call);
                    index = (try w.overloadByType(self, found, expected, name.span)) orelse return w.fail(name.span, .ambiguous_call);
                }
                const f = w.functions.definitions[index];
                if (!self.visible(f.name)) return w.fail(name.span, .unknown_name);
                if (name.sealed() and !f.is_public) return w.fail(name.span, .private_name);
                if (f.is_constructor and self.abstractClass(f.value_type)) return w.fail(name.span, .abstract_instance);
                w.noteName(name.token.span, f.name.start, .global, qualify.none);
                const value_type = try self.functionType(f, name.span);
                const target = try self.referenceTarget(index, name.span);
                return self.emit(.{ .span = name.span, .value_type = value_type, .kind = .{ .function_value = target } });
            }
            const binding = w.findSymbolIn(text, name.scope) orelse {
                const value_type = w.catalogue.findNamedIn(text, w.source, name.scope) orelse return self.stdConstant(name);
                const item = catalogue.definition(value_type, self.definitions()).?;
                if (!self.visible(catalogue.declaredName(item) orelse return w.fail(name.span, .unknown_name))) return w.fail(name.span, .unknown_name);
                if (name.sealed() and !catalogue.declaredPublic(item)) return w.fail(name.span, .private_name);
                if (item != .enumeration) return w.fail(name.span, .expected_expression);
                _ = try self.take(.dot, .expected_expression);
                const case = try self.take(.identifier, .expected_case);
                const index = catalogue.findCase(value_type, case.span.text(w.source), self.definitions(), w.catalogue.cases[0..w.catalogue.case_count], w.source) orelse return w.fail(case.span, .unknown_case);
                self.noteType(name.token.span, value_type);
                w.noteName(case.span, w.catalogue.cases[item.enumeration.cases.start + index].start, .member, qualify.none);
                return self.emit(.{ .span = .{ .start = name.span.start, .end = case.span.end }, .value_type = value_type, .kind = .{ .enumeration = index } });
            };
            if (!self.visible(w.bindings[binding].name)) return w.fail(name.span, .unknown_name);
            if (name.sealed() and !w.bindings[binding].is_public) return w.fail(name.span, .private_name);
            w.noteName(name.token.span, w.bindings[binding].name.start, .global, qualify.none);
            const cell = w.binding_cells[binding];
            // RFC-0087, P5.4 (W5): the name of a keyed cell is no value.
            if (cell != std.math.maxInt(u16) and w.source_cells[cell].keyed != .none) return w.fail(name.span, .weak_map_whole);
            if (cell != std.math.maxInt(u16)) {
                try self.stateEffect(name.span, .variable_read);
                return self.emit(.{ .span = name.span, .value_type = w.bindings[binding].value_type, .kind = .{ .cell_read = cell } });
            }
            if (self.function != null) return self.emitTemplate(.{ .node = .{ .span = name.span, .value_type = w.bindings[binding].value_type, .kind = .{ .integer = 0 } }, .input = .{ .global = binding } });
            return self.namedNode(w.bindings[binding].node);
        }
        /// Marks `index` as a numeric literal written where it is used (RFC-0083).
        fn markLiteral(self: *Self, index: u32) u32 {
            if (self.function != null) self.workspace.literal_templates.set(index) else self.workspace.literal_nodes.set(index);
            return index;
        }
        fn isLiteral(self: *const Self, index: u32) bool {
            return if (self.function != null) self.workspace.literal_templates.isSet(index) else self.workspace.literal_nodes.isSet(index);
        }
        /// A node read through a name: from now on it is a value, not a literal of this place.
        fn namedNode(self: *Self, index: u32) u32 {
            if (self.function != null) self.workspace.literal_templates.unset(index) else self.workspace.literal_nodes.unset(index);
            return index;
        }
        // Decimal conversion has a larger implementation than integer admission.
        // Keep it outside the common scalar literal path without removing checks.
        noinline fn floatLiteral(self: *Self, token: Token) ParseError!u32 {
            std.debug.assert(token.kind == .floating);
            std.debug.assert(token.span.start < token.span.end and token.span.end <= self.workspace.source.len);
            const value = std.fmt.parseFloat(f64, lexer.floatDigits(token.span.text(self.workspace.source))) catch return self.workspace.fail(token.span, .invalid_number);
            if (!std.math.isFinite(value)) return self.workspace.fail(token.span, .float_range);
            return self.markLiteral(try self.emit(.{ .span = token.span, .value_type = .float, .kind = .{ .floating = value } }));
        }
        fn decodeString(self: *Self, token: Token) ParseError!Span {
            const w = self.workspace;
            const start = w.string_count;
            const text = w.source[token.span.start + 1 .. token.span.end - 1];
            // Lexer validation already proved UTF-8 and escape correctness. Ordinary
            // strings need one bounded copy, retaining the checked escape path below.
            if (token.kind == .string) {
                if (text.len > w.strings.len - start) return w.fail(token.span, .string_limit);
                @memcpy(w.strings[start..][0..text.len], text);
                w.string_count += @intCast(text.len);
                return .{ .start = start, .end = w.string_count };
            }
            var cursor = token.span.start + 1;
            while (cursor + 1 < token.span.end) {
                var byte = w.source[cursor];
                cursor += 1;
                if (byte == '\\') {
                    byte = switch (w.source[cursor]) {
                        'n' => '\n',
                        'r' => '\r',
                        't' => '\t',
                        '\\' => '\\',
                        // The rest of the Book's escapes stand for themselves.
                        '"', '\'', '{', '}', '<', '>', '&', '#', '~' => |escaped| escaped,
                        else => unreachable,
                    };
                    cursor += 1;
                }
                if (w.string_count == w.strings.len) return w.fail(token.span, .string_limit);
                w.strings[w.string_count] = byte;
                w.string_count += 1;
            }
            std.debug.assert(start <= w.string_count);
            return .{ .start = start, .end = w.string_count };
        }
    };
}

/// Names the compiler generates start with two underscores; only generated code may declare them.
fn exportedType(definitions: []const types.Definition, named: types.Type) bool {
    const item = catalogue.definition(named, definitions) orelse return false;
    return catalogue.declaredPublic(item);
}

/// A name of the hidden raw cells and fields (RFC-0084, P4.3, C37), which no field may take.
fn rawNamed(name: []const u8) bool {
    return std.mem.startsWith(u8, name, "__raw");
}

fn generatedName(name: []const u8) bool {
    return std.mem.startsWith(u8, name, "__");
}

fn reserved(name: []const u8) bool {
    for ([_][]const u8{ "If", "Attempt", "Require", "Fail", "Set", "Iterate", "Loop", "Bind", "Fn", "Block", "var", "set", "Floor", "Ceil", "Round", "Int", "ToFloat", "ToString", "Case", "WithField", "WithIndex", "Without", "ElementAt", "KeyAt", "For", "While", "Not", "using", "class", "interface", "Return", "Break", "Defer", "Err" }) |control| if (std.mem.eql(u8, name, control)) return true;
    if (std.mem.eql(u8, name, "not") or std.mem.eql(u8, name, "and") or std.mem.eql(u8, name, "or") or std.mem.eql(u8, name, "import") or compoundName(name) or std.mem.eql(u8, name, "Lookup") or std.mem.eql(u8, name, "Or")) return true;
    if (std.meta.stringToEnum(types.Type, name) != null or std.mem.eql(u8, name, "struct") or std.mem.eql(u8, name, "array") or std.mem.eql(u8, name, "enum") or std.mem.eql(u8, name, "tuple")) return true;
    return std.mem.eql(u8, name, "true") or std.mem.eql(u8, name, "false") or std.mem.eql(u8, name, "Inf") or std.mem.eql(u8, name, "NaN");
}

/// RFC-0082: the words that build an event with `Word(T){}`, from P3.9 of each kind.
fn eventWord(name: []const u8) bool {
    return std.mem.eql(u8, name, "event") or std.mem.eql(u8, name, "sticky_event") or std.mem.eql(u8, name, "subscribable_event");
}
fn compoundName(name: []const u8) bool {
    return std.mem.eql(u8, name, "tuple") or std.mem.eql(u8, name, "option") or std.mem.eql(u8, name, "map") or std.mem.eql(u8, name, "function");
}

/// Whether `value`, of the base of `refinement`, lies within its bounds (RFC-0083).
fn refinementHolds(refinement: types.Refinement, value: types.Value) bool {
    if (refinement.base == .i64) return value.integer >= @as(i64, @bitCast(refinement.low)) and value.integer <= @as(i64, @bitCast(refinement.high));
    const low: f64 = @bitCast(refinement.low);
    const high: f64 = @bitCast(refinement.high);
    const x = value.floating;
    const above = if (refinement.low_open) x > low else x >= low;
    const below = if (refinement.high_open) x < high else x <= high;
    return above and below;
}

fn remap(original: types.Node, mapping: []const u32, start: u32, end: u32) types.Node {
    var node = original;
    switch (node.kind) {
        .negate, .float_negate, .int_to_float, .logic_not => |operand| {
            std.debug.assert(operand >= start and operand < end);
            node.kind = if (original.kind == .logic_not) .{ .logic_not = mapping[operand] } else if (original.kind == .float_negate) .{ .float_negate = mapping[operand] } else if (original.kind == .int_to_float) .{ .int_to_float = mapping[operand] } else .{ .negate = mapping[operand] };
        },
        .float_to_int => |c| {
            std.debug.assert(c.operand >= start and c.operand < end);
            node.kind = .{ .float_to_int = .{ .mode = c.mode, .operand = mapping[c.operand] } };
        },
        .string_length, .to_string => |operand| {
            std.debug.assert(operand >= start and operand < end);
            node.kind = if (original.kind == .string_length) .{ .string_length = mapping[operand] } else .{ .to_string = mapping[operand] };
        },
        .string_concat => |c| {
            std.debug.assert(c.lhs >= start and c.lhs < end and c.rhs >= start and c.rhs < end);
            node.kind = .{ .string_concat = .{ .lhs = mapping[c.lhs], .rhs = mapping[c.rhs] } };
        },
        .text => |t| {
            var operands: [3]u32 = @splat(0);
            for (operands[0..t.op.arity()], 0..) |*operand, ordinal| {
                std.debug.assert(t.operand(ordinal) >= start and t.operand(ordinal) < end);
                operand.* = mapping[t.operand(ordinal)];
            }
            node.kind = .{ .text = t.mapped(operands) };
        },
        .map_set => |c| {
            std.debug.assert(c.map >= start and c.map < end and c.key >= start and c.key < end and c.value >= start and c.value < end);
            node.kind = .{ .map_set = .{ .map = mapping[c.map], .key = mapping[c.key], .value = mapping[c.value] } };
        },
        .option_value => |operand| {
            std.debug.assert(operand >= start and operand < end);
            node.kind = .{ .option_value = mapping[operand] };
        },
        .array_set => |c| {
            std.debug.assert(c.array >= start and c.array < end and c.index >= start and c.index < end and c.value >= start and c.value < end);
            node.kind = .{ .array_set = .{ .array = mapping[c.array], .index = mapping[c.index], .value = mapping[c.value] } };
        },
        .array_concat => |c| {
            std.debug.assert(c.lhs >= start and c.lhs < end and c.rhs >= start and c.rhs < end);
            node.kind = .{ .array_concat = .{ .lhs = mapping[c.lhs], .rhs = mapping[c.rhs] } };
        },
        .rational => |r| {
            std.debug.assert(r.lhs >= start and r.lhs < end and r.rhs >= start and r.rhs < end);
            node.kind = .{ .rational = .{ .op = r.op, .lhs = mapping[r.lhs], .rhs = mapping[r.rhs] } };
        },
        .binary, .float_binary => |binary| {
            std.debug.assert(binary.lhs >= start and binary.lhs < end);
            std.debug.assert(binary.rhs >= start and binary.rhs < end);
            node.kind = if (original.kind == .float_binary) .{ .float_binary = .{ .lhs = mapping[binary.lhs], .rhs = mapping[binary.rhs], .op = binary.op } } else .{ .binary = .{ .lhs = mapping[binary.lhs], .rhs = mapping[binary.rhs], .op = binary.op } };
        },
        .compare => |comparison| {
            std.debug.assert(comparison.lhs >= start and comparison.lhs < end and comparison.rhs >= start and comparison.rhs < end);
            node.kind = .{ .compare = .{ .lhs = mapping[comparison.lhs], .rhs = mapping[comparison.rhs], .op = comparison.op } };
        },
        .logic_binary => |binary| {
            std.debug.assert(binary.lhs >= start and binary.lhs < end and binary.rhs >= start and binary.rhs < end);
            node.kind = .{ .logic_binary = .{ .lhs = mapping[binary.lhs], .rhs = mapping[binary.rhs], .op = binary.op } };
        },
        .field => |access| {
            std.debug.assert(access.value >= start and access.value < end);
            node.kind = .{ .field = .{ .value = mapping[access.value], .index = access.index } };
        },
        .object_get => |access| {
            std.debug.assert(access.value >= start and access.value < end);
            node.kind = .{ .object_get = .{ .value = mapping[access.value], .index = access.index } };
        },
        .upcast, .downcast => |operand| {
            std.debug.assert(operand >= start and operand < end);
            node.kind = if (original.kind == .upcast) .{ .upcast = mapping[operand] } else .{ .downcast = mapping[operand] };
        },
        .refine => |operand| {
            std.debug.assert(operand >= start and operand < end);
            node.kind = .{ .refine = mapping[operand] };
        },
        .instance_of => |c| {
            std.debug.assert(c.value >= start and c.value < end);
            node.kind = .{ .instance_of = .{ .value = mapping[c.value], .class = c.class } };
        },
        .method_value => |m| {
            std.debug.assert(m.receiver >= start and m.receiver < end);
            node.kind = .{ .method_value = .{ .receiver = mapping[m.receiver], .slot = m.slot } };
        },
        .object_set => |c| {
            std.debug.assert(c.object >= start and c.object < end and c.value >= start and c.value < end);
            node.kind = .{ .object_set = .{ .object = mapping[c.object], .index = c.index, .value = mapping[c.value] } };
        },
        .tuple_element => |access| {
            std.debug.assert(access.value >= start and access.value < end);
            node.kind = .{ .tuple_element = .{ .value = mapping[access.value], .index = access.index } };
        },
        .array_length, .option_present => |operand| {
            std.debug.assert(operand >= start and operand < end);
            node.kind = if (original.kind == .array_length) .{ .array_length = mapping[operand] } else .{ .option_present = mapping[operand] };
        },
        .option_or => |choice| {
            std.debug.assert(choice.option >= start and choice.option < end and choice.fallback >= start and choice.fallback < end);
            node.kind = .{ .option_or = .{ .option = mapping[choice.option], .fallback = mapping[choice.fallback] } };
        },
        .native_call => |c| {
            var mapped = c;
            for (mapped.args[0..mapped.count]) |*operand| {
                std.debug.assert(operand.* >= start and operand.* < end);
                operand.* = mapping[operand.*];
            }
            node.kind = .{ .native_call = mapped };
        },
        .array_get => |access| {
            std.debug.assert(access.array >= start and access.array < end and access.index >= start and access.index < end);
            node.kind = .{ .array_get = .{ .array = mapping[access.array], .index = mapping[access.index] } };
        },
        .map_key, .map_value => |access| {
            std.debug.assert(access.array >= start and access.array < end and access.index >= start and access.index < end);
            const mapped: types.ArrayIndex = .{ .array = mapping[access.array], .index = mapping[access.index] };
            node.kind = if (original.kind == .map_key) .{ .map_key = mapped } else .{ .map_value = mapped };
        },
        .map_lookup, .map_remove => |lookup| {
            std.debug.assert(lookup.map >= start and lookup.map < end and lookup.key >= start and lookup.key < end);
            const mapped: types.Lookup = .{ .map = mapping[lookup.map], .key = mapping[lookup.key] };
            node.kind = if (original.kind == .map_lookup) .{ .map_lookup = mapped } else .{ .map_remove = mapped };
        },
        .if_begin => |b| node.kind = .{ .if_begin = .{ .condition = mapping[b.condition], .alternative = no_member, .end = no_member } },
        .attempt_begin => node.kind = .{ .attempt_begin = .{ .condition = no_member, .alternative = no_member, .end = no_member } },
        .otherwise => |b| node.kind = .{ .otherwise = mapping[b] },
        .merge => |m| node.kind = .{ .merge = .{ .begin = mapping[m.begin], .left = mapping[m.left], .right = mapping[m.right] } },
        .local_set => |n| node.kind = .{ .local_set = mapping[n] },
        .demand => |n| node.kind = .{ .demand = mapping[n] },
        .fail => |n| node.kind = .{ .fail = mapping[n] },
        .exit => |n| node.kind = .{ .exit = mapping[n] },
        .arm_exit => |n| node.kind = .{ .arm_exit = mapping[n] },
        .err => |n| node.kind = .{ .err = mapping[n] },
        .spawn => |n| node.kind = .{ .spawn = mapping[n] },
        .sleep => |n| node.kind = .{ .sleep = mapping[n] },
        .canceling, .cancel_exit => {},
        .arm_exited, .arm_exit_value => {},
        .task_await => |n| node.kind = .{ .task_await = mapping[n] },
        .event_await => |n| node.kind = .{ .event_await = mapping[n] },
        .event_signal => |s| node.kind = .{ .event_signal = .{ .event = mapping[s.event], .value = mapping[s.value] } },
        .event_new => {},
        // Its arms are mapped with the argument pool (`remapNode`).
        .structured => {},
        .branch => |n| node.kind = .{ .branch = mapping[n] },
        .task_cancel => |n| node.kind = .{ .task_cancel = mapping[n] },
        .elapsed_time => {},
        .cell_live => |c| node.kind = .{ .cell_live = .{ .cell = c.cell, .guard = mapping[c.guard], .initialize = c.initialize } },
        .object_live => |c| node.kind = .{ .object_live = .{ .object = mapping[c.object], .field = c.field, .guard = mapping[c.guard] } },
        .reaction => |r| node.kind = .{ .reaction = .{ .kind = r.kind, .guard = mapping[r.guard], .body = mapping[r.body] } },
        .batch => |n| node.kind = .{ .batch = mapping[n] },
        .await_guard => |n| node.kind = .{ .await_guard = mapping[n] },
        .event_subscribe => |s| node.kind = .{ .event_subscribe = .{ .event = mapping[s.event], .callback = mapping[s.callback] } },
        .subscription_cancel => |n| node.kind = .{ .subscription_cancel = mapping[n] },
        // Its argument is mapped with the argument pool (`remapNode`).
        .event_notify => |i| node.kind = .{ .event_notify = .{ .callable = mapping[i.callable], .arguments = i.arguments } },
        // RFC-0085, I1: both operands of each move (`RefSet` is not a `CellWrite`).
        .ref_new => |n| node.kind = .{ .ref_new = mapping[n] },
        .ref_get => |n| node.kind = .{ .ref_get = mapping[n] },
        .ref_set => |r| node.kind = .{ .ref_set = .{ .ref = mapping[r.ref], .value = mapping[r.value] } },
        // RFC-0086, P2.3: the name moves.
        .grant => |g| node.kind = .{ .grant = .{ .kind = g.kind, .name = if (g.kind == .session) g.name else mapping[g.name] } },
        // RFC-0087, P5.4: the key and the value move; the cell does not.
        .weak_get => |g| node.kind = .{ .weak_get = .{ .cell = g.cell, .key = mapping[g.key] } },
        .weak_set => |c| node.kind = .{ .weak_set = .{ .cell = c.cell, .key = mapping[c.key], .value = mapping[c.value] } },
        .weak_init => {},
        // RFC-0087, P5.3: the value or the text moves.
        .json_encode => |n| node.kind = .{ .json_encode = mapping[n] },
        .json_decode => |n| node.kind = .{ .json_decode = mapping[n] },
        .cell_init, .cell_write => |c| {
            std.debug.assert(c.value >= start and c.value < end);
            const mapped: types.CellWrite = .{ .cell = c.cell, .value = mapping[c.value] };
            node.kind = if (original.kind == .cell_init) .{ .cell_init = mapped } else .{ .cell_write = mapped };
        },
        .iterate => |i| node.kind = .{ .iterate = .{ .function = i.function, .count = mapping[i.count], .initial = mapping[i.initial] } },
        .invoke => |i| node.kind = .{ .invoke = .{ .callable = mapping[i.callable], .arguments = i.arguments } },
        .bind => |i| node.kind = .{ .bind = .{ .callable = mapping[i.callable], .arguments = i.arguments } },
        .iterate_value => |i| node.kind = .{ .iterate_value = .{ .callable = mapping[i.callable], .count = mapping[i.count], .initial = mapping[i.initial] } },
        .loop => |l| node.kind = .{ .loop = .{ .callable = mapping[l.callable], .initial = mapping[l.initial] } },
        .function_value, .self_value, .aggregate, .integer, .floating, .boolean, .string, .enumeration, .character, .cell_read, .call, .recur, .object_new => {},
    }
    return node;
}

fn comparisonOperator(kind: @FieldType(Operator, "kind")) ?types.CompareOp {
    return switch (kind) {
        .equal => .equal,
        .unequal => .unequal,
        .less => .less,
        .less_equal => .less_equal,
        .greater => .greater,
        .greater_equal => .greater_equal,
        else => null,
    };
}
